INSERT INTO `migrations` (`migration`, `batch`) SELECT '2026_10_27_200000_add_hastane_sablonu_to_risk_tablolari', COALESCE(MAX(`batch`), 0) + 1 FROM `migrations` WHERE NOT EXISTS (SELECT 1 FROM `migrations` WHERE `migration` = '2026_10_27_200000_add_hastane_sablonu_to_risk_tablolari');
INSERT INTO `migrations` (`migration`, `batch`) SELECT '2026_10_27_210000_add_risk_cikti_sablonu_to_firmalar_table', COALESCE(MAX(`batch`), 0) + 1 FROM `migrations` WHERE NOT EXISTS (SELECT 1 FROM `migrations` WHERE `migration` = '2026_10_27_210000_add_risk_cikti_sablonu_to_firmalar_table');
