INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: HASTANE GENELİ', '1- Kapalı alanlarda sigara içilmesi', '1-Yangın çıkması sonucu yaralnma', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- Duman dedektörleri mevcuttur.\n2- Yangın söndürme sistemleri mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1- Hastane içinde ve kapalı alanlarda sigara içilmemelidir.                                                                                                             2- Özellikle acil çıkış merdivenlerinde sigara içilmesi yasaklanmalı, acil çıkış kapılarında bulunan manyetik tutucular aktif hale getirilmelidir.                                                                                       2- Duman dedektörleri çalışanlar ya da hastalar tarafından iptal edilmemelidir.                                                                                                                                          3- Kapalı alanda sigara içenlere ve yangın ihbar sistemini iptal edenlere idari yaptırım, disiplin cezaları uygulanmalıdır.', 'İŞVEREN V.\nFİRMA', 'HERGÜN\n2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', 'yapılmadı', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: HASTANE GENELİ', '1- Yüksekten düşmeye sebep olabilecek alanlar', '1-Sarkma, atlama,  fiziksel şiddet vb. hareketler sonucu yüksekten düşme', '1- Çalışanlar', '1-Korkuluklar mevcuttur ve sağlam yapıdadır.', 1, 0, 3, 6, 15, 270, 'B', '1- Çalışanların yüksekten düşme riskine sebep olabilecek açıklıklar TS EN 1263-1  ve TS EN 1263-2 standardına uygun olarak güvenlik filesi vb. sistemler ile kapatılmalıdır.                                                                                    \n2- Ankraj noktaları,  betonarme kolon, kiriş vb. yük taşıyabilecek sağlam  yapısal elemanlara takılmalı, alçıpan gibi zayıf taşıyıcı sistemlere takılmamalıdır. \n3-Güvenlik filelerinin halatları yüksek mukavemetli, doğru gerginlikte ve düşüş mesafesine uygun olarak kurulmalıdır.                                     \n4-Ankraj sistemleri, vida, dübel, kanca ve halkalar yüksek dayanımlı paslanmaz çelik malzemeden olmalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', '20.04.2026 tarihinde 312121690 resmi yazı ile teknik hizmetlere iletilmiş, Mart kurulunda konuşulmuştur.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: HASTANE GENELİ', '1- Ortam ölçümlerinin yapılmamış olması', '1- İş kazlarında, Meslek hastalıklarında artış', '1- Çalışanlar', NULL, 1, 0, 6, 6, 7, 252, 'B', '1-Hastanede toz, voc, gürültü, aydınlatma, termal konfor ölçümleri akreditasyonu olan firmalara yaptırılmalıdır.                                 \n2- Ortam ölçümü yapılırken çalışan maruziyetleri de ölçülmelidir.\n3-Çıkan sonuçlara göre gereken tedbirler alınmalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', 'voc, ve formaldehit ortam ölçümleri yapılmıştır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: HASTANE GENELİ', '1-Halojen free özellikte olmayan elektrik kabloların kullanılması', '1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm', '1- Çalışanlar', '1-Hastane tesisatında ki elektrik kabloları halojen free özelliktedir.                                     2- 300 MA yangın yangın röleleri mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1-Hastane de kullanılan tüm elektrik, uzatma (3\'lü) vb. kablolar halojen free (geç yanan, zehirli gaz çıkarmayan) özellikte olmalıdır.                                                                                                                                                           2- Halojen free olmayan uzatma kablolalarının kulllanımı yasaklanmalı, toplatılmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', '08.10.2025 tarihinde iç emir çıkartılmıştır. Tespiti halinde toplanmaktadır\n290866361 .', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: HASTANE GENELİ', '1-Elektrikli mutfak aletleri (çay, kahve, microdalga fırın, airfryer vb.) kullanılması', '1- Elektrik yangını çıkması sonucu, yaralanma', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Hastane de mutfak olarak belirlenmiş alanlar dışında hiçbir yerde elektrikli mutfak aletleri kullanılmamalıdır.                                          \n2- Mutfak olarak tanımlanmış alanlarda sadece çay ve kahve makinesi kullanılmalı, bunların dışındaki aletlerin kullanımı yasaklanmalıdır.                                                                                                          3- Sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.                                                                                                                         4- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.                                                                                                                5- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.', 'İŞVEREN V.\nÇALIŞANLAR', '2 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', '08.10.2025 tarihinde iç emir çıkartılmıştır. Tespiti halinde toplanmaktadır\n290866361 .', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: HASTANE GENELİ', '1- Elektrik kabloların da aşırı yükleme olması', '1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- 3 lü uzatma kablolarına, 3 lü uzatma kablosu kullanarak kullanılmamalıdır.                                                                                                     2- Yüsek akım çeken cihazlar (kettle çay makinesi vb.) beslemesi ayrı fişlerden yapılmalı, uzatma kabloları kullanılmamalıdır.                                                                                                             3- Çalışanların dışarıdan uzatma kablosu getirmesi yasaklanmalıdır.                                                                                                                                   4- Konu ile ilgili kontrol denetim sağlanmalı ,uygun olmayan cihaz ve kablolar toplatılmalıdır.', 'İŞVEREN V.\nÇALIŞANLAR', '2 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', '08.10.2025 tarihinde iç emir çıkartılmıştır. Tespiti halinde toplanmaktadır\n290866361 .', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: HASTANE GENELİ', '1-Çalışan hasta ve hasta yakınları iletişim problemleri, fiziksel sözlü şiddet,', '1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma,', '1-Çalışanlar', '1-Bir çok alanda  panik butonları mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Hasta ve hasta yakınları tarafından çalışanların şiddete uğrayabileceği tüm alanlara sabit panik butonları ya da yaka butonları temin edilmelidir.                                                                                        \n 2- Özellikle şiddet riskinin yoğun olduğu alanlarda ( hasta hakları, psikayatri acil vb.) alanlarda ilave butonlar konulmalıdır.                                                                                                                3- Şiddet riskinin yoğun olduğu alanlarda butonlara ilave olarak sabit güvenlik personeli  bulundurulmalıdır.                   \n4- Çalışanlara iletişim, stres yönetimi ve öfke kontrolü ile mesleki bilgi ve becerilerini arttırıcı eğitimler verilmelidir.', 'İŞVEREN V.\nİŞ GÜVENLİĞİ UZMANI', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', 'İlgili alanlara yaka butonları dağıtılmıştır.\nGüvenlik sayıları arttırılmıştır.\nStress yönetimi ve öfke kontrolü konularında eğitimler planlanmıştır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: HASTANE GENELİ', '1-Çalışanların fazla mesai ile çalışması                                                          2- İş yükünün fazla olması', '1-Dikkatin azalması, yorgunluk, uykusuzluk, sonucunda iş kazalarının oluşması', '1- Çalışanlar', NULL, 1, 0, 6, 6, 7, 252, 'B', '1-Fazla mesai süreleri yasal sınırlarla En fazla 130 saat olmalıdır.                                                                                                                                             2- 24 saatlik nöbetten sonra çalışanlara en az 24 saat dinlenme süresi verilmelidir.                               \n3- Gün aşırı nöbet sayısı azaltılmalıdır.                                                                                                            4-Çalışanların düzenli sağlık kontrolleri yapılmalı ve yeterli dinlenme süreleri sağlanmalıdır.                                                                                                                                                                                                                                                                                                                                                    5- Yorgunluk ve stres yönetimi için psikososyal destek programları sağlanmalıdır.', 'İŞVEREN V.', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', 'Çalışanların yönetmelik gereği yıllık sağlık kontrolleri yapılmaktadır.\nÇalışanlar için sosyal etkinlikler yapılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: HASTANE GENELİ', '1-Bina dış cephe karolarının düşmesi, kopması', '1-Karoların düşmesi sonucu, yaralanma, ölüm', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', NULL, 1, 0, 3, 2, 40, 240, 'B', '1-  Dış cephe karolarında çatlak, kabarma ayrılma vb. olup olmadığı, drone, sepetli platform ya da termal kamera ile yılda bir kez kontrol edilmeli, hasarlı, ayrılmış olan karolar değiştirilmelidir.                                                                                                                              2- Dış cephe karolarını tutan tırnak ve vidalar da paslanma olmamalıdır.                                                                                                                                 3- Şiddetli rüzgar ya da deprem sonrası bina karoları kontrol edilmeli, hasarlı olanlar değiştirilmelidir.', 'FİRMA', 'YILDA 1\nŞİDDETLİ \nRÜZGAR\nSONRASI\nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', 'Rönesans', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: HASTANE GENELİ', '1- Kurşun önlüklerin, tiroid koruyucuların vb. ekipmanların kırılması, bozulması, yeterli sayıda olmaması', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Radyasyona maruz kalan çalışanlar', '1- Özel askı aparatları mevcuttur.', 1, 0, 6, 2, 15, 180, 'C', '1- Çalışanların radyasyona maruz kaldıkları bölümlerde, her bölüm için maruz kalabilecek tüm çalışanlara yetecek kadar kurşun önlük tiroid koruyucu vb. ekipmanlar temin edilmelidir.   \n2- Kurşun önlükler ve diğer koruyucular kullanıldıktan sonra özel askılıklara asılmalı, kırılması önlenmelidir.                                                                                                                  3- Kırılan, bozulan kurşun önlük vb. ekipmanlar yerine yenileri temin edilmelidir.                                                                                                                                                                     4- Kurşun önlükler ve diğer koruyucular kullanıldıktan sonra dezenfekte edilmelidir.', 'İŞVEREN V.\nÇALIŞANLAR', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', 'Satın alma talebi yapılmıştır.\nÖzel askılıklar mevcuttur.\nDezenfeksiyon????', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: HASTANE GENELİ', '1- Taşınabilir röntgen cihazlarının kullanımı sonucu X ışınlarına maruziyet', '1-Meslek hastalıkları, mesleki kanserler oluşması', '1- Çalışanlar', '1- Kurşun önlükler mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Taşınabilir röntgen cihazı ile yapılan çekimler de kurşun paravan kullanılmalıdır.                                                                                                                                                               2- Çekim yapılan alanda hasta ve çekim yapan çalışan dışında kimse olmamalı, zorunlu hallerde bulunulması gerekirse(TS EN 61331 standardında kurşun önlük troid koruyucu vb.kişisel koruyucu ekipmanlar kullanılmalıdır.                                                                                                       3- Çekim yapılan odaların kapıları kapatılmalıdır.                                                                                           4- Açık alanlarda yapılan çekimlerde çalışanlar en az 2 metre uzakta durmalıdır.', 'RADYOLOJİ ÇALIŞANLARI        ÇALIŞANLAR', 'ÇEKİM ESANASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', 'Çekim yapılan odalarda hasta haricinde kimse bulundurulmamaktadır.\nHasta odası kapısı kapalı tutulmaktadır.\nÇekim öncesi Çalışanlar bilgilendirilmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: HASTANE GENELİ', '1-Defibilatörün emniyetsiz kullanımı', '1-Defibrilatör kullanımı sırasında elektrik çarpması, elektrik yanıkları oluşması', '1- Defbilatör kullanan çalışanlar                                                     2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 3, 15, 135, 'C', '1-Defibrilasyon esnasında hastaya elektrotlara ve diğer iletken nesnelere dokunulmamalıdır.\n2-Hastaya ıslak  ve iletken ortamlarda defibrilasyon uygulanmamalı, hastanın göğsünde ıslaklık, jel, ter olmamalı, hastanın göğüsü kurulanmalıdır.\n3-Defibrilatör cihazı oksijen tüpü, alkol vb. yanıcı sıvı ve gazların bulunduğu ortamlarda kullanılmamalıdır.                       \n4- Hastanın ve defibilatörü kullanan çalışanın üzerinde metal eşyalar bulunmamalıdır.                                                                                           \n5- Ortamda bulunan diğer çalışanlar en az 1 metre uzakta bulunmalıdır.', 'DEFİLBİLATÖR KULLANAN ÇALIŞANLAR', 'DEFİBİLATÖR KULLANIM SIRASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: HASTANE GENELİ', '1- Acil çıkış yollarının, kapılarının malzemeler ile kapatılması', '1-Acil durumlarda hızlı tahliyenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- Acil çıkış yönlendirmeleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Acil çıkış kapıları ve acil çıkış yolları açıkça görülebilir olmalı ve acil çıkış kapılarnın ve yollarının önüne ve üzerine saksı, malzeme vb. konulmamalıdır.  \n2- Acil çıkış yönlendirmelerinin önleri kapatılmamalı, kaçış yolu üzerinde bütün erişim noktalarından görülebilir olmalı, yönlendirmeler 200-240 cm yüksekliğe asılı olmalıdır.                                                                         \n3- Acil çıkış yollarında en az 150 cm genişliğinde mesafe olması sağlanmalıdır.', 'İŞVEREN V.\nÇALIŞANLAR', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: HASTANE GENELİ', '1- Oksijen tüplerinin ve diğer basınçlı tüplerin paslı ve korozyonlu olması', '1- Tüplerinin yapısal bütünlüğünün bozulması sonucu gaz kaçağı, patlama meydana gelmesi', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- Birçok alanda tüp sabitleme aparatları bulunmaktadır.', 1, 0, 6, 3, 7, 126, 'C', '1- Paslı ve korozyonlu tüpler kullanım dışı bırakılmalıdır.                     \n2- Bu tüplerin tedarikçi firma tarafından hidrostatik test ve ultrasonik kalnlık ölçümleri yapılmalıdır.                                                                            \n3- Gaz sızıntısı durumunda hiçbir onarım yapmadan tüp açık bir alana çıkarılarak tedarikçi firmaya haber verilmelidir.                                                                                                             4- Basınçlı tüpler elektrik ısı kıvılcım kaynaklarından en az 3 metre uzakta bulundurulmalı, en az iki noktadan dik konumda sabitlenmelidir.', 'İŞVEREN V.\nÇALIŞANLAR', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: HASTANE GENELİ', '1-Oksijen ve basınçlı tüplerin uygunsuz taşınması', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- Sabitleme aparatı bulunmaktadır.', 1, 0, 6, 3, 7, 126, 'C', '1- Hasta yatakları, taşıma araçları vb. basınçlı tüp taşınan ekipmanlarda tüpleri sabitlemek için aparatlar bulunmalı, tüpler en az iki noktadan sabitlenerek taşınmalıdır.                                                                                                                         2- Tüplerin taşınması esnasında vanaları kapalı olmalı, dik taşınmalı, kapağı kapalı olmalıdır.                                                                                 \n3- Taşıma esnasında tüplerin başka cisimlere çarpması engellenmelidir.  \n4- Hastaneye kendi oksijen tüpü ile gelen hastalar için sedye ve tekerlekli sandalye için sabitleme aparatı verilmeldir.', 'ÇALIŞANLAR', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', '11.05.2026 tarih ve 314350255 yazı ile kalite destek birimine bildirimiştir. \nÖzel aparat alınmıştır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: HASTANE GENELİ', '1-Özel politika grupları uygulamalarının yetersiz olması', '1-İş kazası ve meslek hastalıklarının artması', '1-Özel politika grupları', '1- Refakatçiler belirlenmiştir.', 1, 0, 6, 3, 7, 126, 'C', '1- Acil durumlarda özel politika gruplarına tahliye esnasında refakat edilmesi için refakatçiler belirlenmeli, refakatçi listesi sürekli güncel tutulmalıdır.\n2-Engelliler sadece sağlık raporunda belirtilen ve engel durumuna uygun işlerde  çalıştırılmalıdır.  \n3-Özel politika gruplarına kendi istekleri dışında fazla mesai yaptırılmamalı, gece vardiyalarında çalıştırılmamalıdır.\n4-Bu gruplar uzun süre ayakta çalıştırılmamalı, ağır yük taşıtılmamalıdır.                                                                                                                                     5-Özel politika gruplarına özel olarak eğitim verilmelidir.', 'İŞVEREN V. \nİŞYERİ HEKİMİ\nİŞ GÜVENLİĞİ UZMANI', 'SÜREKLİ\n3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', '1- Acil durumlarda özel politika gruplarına tahliye esnasında refakat edilmesi için refakatçiler belirlenmiş ve yıllık revize edilmektedir.\n2- İşyeri hekimi tarafından uygun alanlarda çalışmaları konusunda yönlendirilmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: HASTANE GENELİ', '1-Makinelerin gövde topraklama ölçümlerinin yapılmamaış olması.                                              2-Yıpranmış, ezilmiş kablolar', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, elektrik yanıkları, ölüm,', '1- Çalışanlar', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1-Makinelerin gövde topraklama ölçümleri yaptırılmalı, belgelendirilmelidir.\n2-Cihazlar durdurulmadan ve akım kesilmeden bakım, arıza onarım ve müdahaleler yapılmamalıdır.\n3-Yıpranmış, ezilmiş, soyulmuş ve izolasyonsuz kablolar değiştirilmelidir.                                                                                                                           4- Makikenelerin elektrik kabloları çift izolasyonlu olmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', '????? RÖNESANS', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: HASTANE GENELİ', '1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması', '1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması', '1- Çalışanlar', '1-KKD\'ler çalışanlara zimmetlenmektedir.', 1, 0, 3, 6, 7, 126, 'C', '1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan kkd\'ler temin edilmelidir.\n2- Çalışanların maskeleri TS EN149 A1 standardında uygun olmalıdır.                                                                                                                     3-Çalışanların göz koruyucuları TS EN 166 standardına uygun ve tam kapalı tip olmalıdır.                                                                                                                             4-Çalışanların iş eldivenleri kimyasallara karşı TS EN 374 standartı, kesilmelere dayanıklı TS EN 388 standartı, radyoaktif maddelere karşı TS EN 421 standartı elektrik tehlikelerine karşı TSE EN 60903 standartına uygun olmalıdır.                                                                                                                                5- Çalışanların iş tulumları kimyasal maddelere karşı TS EN 14126 standartına, radyoaktif maddelere karşı  TS EN 1073-2 standartına uygun olmalıdır.\n6-Çalışanların iş ayakkabıları, koruyucu burun ve taban TS EN 12568 standardına ve kaymayı önleyici TS EN 13287 standartı, kimyasallara ve radyokaktif maddelere karşı EN ISO 20347, elektrik tehlikelerine karşı TS EN 50321 standartına uygun olmalıdır.\n7-Çalışanlar sahada kişisel koruyucu ekipmanlarını eksiksiz şekilde kullanmalıdırlar.', 'İŞVEREN V.\n (EKSİK \nKKD \nTEMİNİ)\n ÇALIŞANLAR', '3 AY  \n\n                                HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: HASTANE GENELİ', '1- Elektrik kablolarında yırtık, izolasyon bozukluğu olması,                                                                                   2- Ekli kabloların kullanılması', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm', '1- Çalışanlar', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1- Elektrik kablolarında yırtık, izolasyon bozlukluğu vb. olmamalı, olan kablolar kullanılmamalı değiştirilmelidir.                          \n2- Elektrik kabloları ağır malzeme ya da ekipmanların altına konulmamalı, kabloların ezilmesi önlenmelidir.                                            \n3- Kablolarda olan izolasyon açıklıkları izole bant ile kapatılmamalı, ekli kablolar değiştirilmelidir.', 'İŞVEREN V.\nÇALIŞANLAR', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', 'Tespiti halinde taleple müdahale edilmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: HASTANE GENELİ', '1- Taşınabilir elektrikli aletlerin PAT testlerinin yapılmaması', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm', NULL, '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1- Taşınabilir elektrikli cihazların (çay kahve makineleri, bilgisyar, yazıcı, monitörler, fotokopi makineleri vb. aletlerin)en az yılda bir kez topraklama direnci, izolasyon seviyesi ve kaçak akım gibi temel elektriksel değerlerini ölçülmesini sağlayan PAT testleri yapılmalıdır.                                                                                                                               2- PAT testinden geçen cihazlar etiketlenmeli, diğerlerinin kullanımı eksiklikler tamamlanana kadar  önlenmelidir.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: HASTANE GENELİ', '1- Oksijen ya da basınçlı tüplerin uygunsuz kullanılması', '1-Fiziksel olarak patlaması sonucu vücut bölümlerinin yaralanması', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Oksijen tüplerine yağlı, kremli eller ile temas edilmemeli, vanaları yağlanmamalıdır.                                                                                                                                   2- Tüpler ısı kaynaklarından ve güneşin etkisinden uzak tutulmalıdır.                                                                                                                                    3- Manometreler sağlam olmalı, kırık olanlar değiştirilmelidir.                                       \n4- Basınçlı tüpler zeminde sabitlenmeden bırakılmamalı, sabitleme aparatlarına takılmalı ve 2 noktadan zincir ya da halatla bağlanmalıdır.', 'ÇALIŞANLAR', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', 'Kullanım talimatı tüplerin üzerinde bulundurulmaktadır.\nKullanımı konusunda eğitim verilmektedir. (genel isg eğitimi)', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 1: HASTANE GENELİ', '1- Elektrik kablolarının, priz vb. elektrik sistemlerinin su ya da sıvı maddeler ile temas etmesi', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm', '1- Çalışanlar', '1-30 MA kaçak akım rölesi mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1-Su ya da sıvı maddeler bulunduran cihazların bağlantı yerlerinde ve hortumlarında hiç bir sızıntı olmamalıdır.                                                                                2- Cihazların elektrik kablolarında izole bant ile bantlanmış ekler olmamalıdır.                                                                                                                          3- Elektrik kabloları çift izolasyonlu olmalıdır.                                                                                                                4- Su ya da sıvı sızdırabilecek cihazlar fiş priz vb. elektrik sistemlerinden uzakta tutulmalı, suyun elektrik ile temas etmesi önlenmelidir.                                                                                                               5- Cihazların bakım ve kalibrasyonları  yapılmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', 'Tespiti halinde taleple müdahale edilmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 1: HASTANE GENELİ', '1-Hastalardan inhalasyon yoluyla hastalık bulaşması', '1-Enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- Çalışanlar', '1-KKD\'ler mevcuttur.                                         2- Çalışanlara KKD önemi ve kullanımı konusunda eğitim verilmektedir.', 1, 0, 3, 6, 7, 126, 'C', '1-Bulaşıcı hastalık şüphesi olan hastalar, sonuçları çıkana kadar tek kişilik izolasyon odalarında tutulmalıdır.                                                                                           2- Şüpheli hastaların bulunduğu alanın teması bittikten sonra hemen dezenfekte edilmelidir.                                                                                                                          3- Bulaşıcı hastalıkların yayılma ihtimali yüksek olan bölümlerde (acil servis, poliklinik, görüntüleme vb.) hepa filtreler kullanılmalıdır.                                                                                                                                              4-Tanı konulmuş hastalar negatif basınçlı odalara alınarak izole edilmelidir.                                                                                                                        5-Çalışanlar N95 ya da TS EN 149 standrtdında FFP2 filtreli maske, yüz siperi, TS EN 455  standardında eldiven kullanmalıdır.', 'BİRİM SORUMLULARI   ÇALIŞANLAR', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 1: HASTANE GENELİ', '1-Tehlikeli kimyasalların yanlış depolanması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması                                 2- Yangın meydana gelmesi', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- Kimyasallar depo alanında depolanmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Kimyasal maddeler depolama matirsine göre depolanmalıdır.                                                        \n2- Yanıcı kimyasallar elektrik kaynaklarından uzak depolanmalıdır.                                                                               3- Kimyasal maddelerin ağzı açık olmamalı, dik olarak istiflenmelidir.\n 4- Ağzı açılmış kimyasal madde kaplarının altına taşma kapları konulmalıdır.', 'İŞVEREN V.    ÇALIŞANLAR', '3 AY                               HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM 1: HASTANE GENELİ', '1- Kimyasal madde deposunda göz duşu ve döküntü kiti bulunmaması                                               2- Çalışanların kimyasallar hakkında bilgi sahibi olmaması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1- Çalışanlar', '1- Kimyasallar depo alanında depolanmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         \n2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.  \n3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               \n4-Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.                              \n5- Çalışanlara MSDS ve kimyasalların güvenli kullanımı konusunda eğitimler verilmelidir.', 'İŞVEREN V.                                       İŞ GÜVENLİĞİ UZMANI', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM 1: HASTANE GENELİ', '1- Yangın algılama ihbar ve söndürme sistemlerinin periyodik kontrollerinin tekrarlanmaması', '1- Yangına müdahale edilememesi sonucu şiddetin artması', NULL, '1- Periyodik kontroller mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Yangın söndürme tüplerinin, sprinklerin, yangın hortumlarının, yangın alarmlarının, duman algılama dedektörlerinin, yangın panellerinin, yangın pompalarının vb. yangın söndürme ile ilgili tüm tesisatların periyodik kontrolleri, risk değerlendirmesinin yangın söndürme sistemleri bölümünde belirtilen standartlara ve sürelere göre periyodik kontrolleri tekrarlanmaldır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 27, 'BÖLÜM 1: HASTANE GENELİ', '1-Hastane camlarının açılması', '1-Düşme ya da intihar sonucu yaralanma, ölüm', '1- Çalışanlar', '1-Camların bir çoğu tam açılmamaktadır.', 1, 0, 1, 3, 40, 120, 'C', '1- Hastane de tüm camlar kontrol edilmeli, tam açılabilen camlar en fazla açıklık 15 cm açılacak şekilde ayarlanmalı ve sabitlenmelidir.                                                                                                  2- Pencere kilitleri sadece yetkili bölüm sorumlularında bulunmalı, sadece acil ihtiyaç halinde açılmalıdır.', 'FİRMA\nÇALIŞANLAR', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 28, 'BÖLÜM 1: HASTANE GENELİ', '1-Özel izin gerektiren işlerin belirlenmemiş olması', '1-Emniyetsiz çalışma sonucunda iş kazaları yaşanması\n2- Parlama, patlama, yangın çıkması', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', NULL, 1, 0, 1, 3, 40, 120, 'C', '1-Yüksekte çalışma, genel bakımlar, trafo işleri, çatı işleri, büyük kaynak işleri, taşıma işleri, kapalı alanlarda çalışma gibi işler özel izinle yapılmalıdır.\n2-İzin veren birim bütün tedbirlerin alındığından emin olmalı, sürekli kontrol ve denetim sağlanmalıdır.\n3-Tüm tedbirler alınıp izin formu imzalandıktan sonra çalışmaya başlanmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 29, 'BÖLÜM 1: HASTANE GENELİ', '1-Taşeron firma ve çalışanların iş güvenliği kurallarına uymaması, güvenlik tedbirlerini almaması', '1-Emniyetsiz çalışma sonucunda iş kazaları, vücut bölümlerinin yaralanması, ezilmesi, uzuv kayıpları ve ölüm                        2 -Yangın çıkması', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', NULL, 1, 0, 1, 3, 40, 120, 'C', '1-Taşeron firmadan gelen çalışanlardan ağır ve tehlikeli işlerde çalışabilir sağlık raporu temin edilmeli, sağlık durumu uygun olmayan çalışanlar çalıştırılmamalıdır.\n1-Taşeron çalışanların 16 saatlik güncel iş güvenliği eğitim sertifikaları temin edilmelidir.\n2-Taşeron firma çalışanlarından yaptıkları işe uygun mesleki eğitim belgeleri temin edilmeli, mesleki eğitim belgesi olmayan kişiler çalıştırılmamalıdır.\n3-Taşeron firma çalışanlarının yaptıkları işe uygun kkd’leri eksiksiz olmalı, kkd zimmet belgeleri temin edilmelidir.\n4-Taşeron firma çalışanlarına ilk girişlerde hastane ile ilgili oryantasyon eğitimi verilmelidir.\n5-Taşeron firma ve çalışanlar hastane içinde kendi iş güvenliği önlemlerini almalı, ayrıca işyeri içindeki iş güvenliği kurallarına uymalı, diğer çalışanların güvenliklerini tehlikeye düşürecek durum ve davranışlarda bulunmamalıdırlar.', 'İŞVEREN V.', 'TAŞERE \nİŞLER SIRASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 30, 'BÖLÜM 1: HASTANE GENELİ', '1- İş kazası olması', '1-Vücut bölümlerinin yaralanması, uzuv kayıpları, ölüm', '1- Çalışanlar', '1- Çalışanlara ilk işe girişte temel isg eğitimlerinde iş kazası yaşamaları durumunda yapılacaklar ile ilgili eğitim verilmektedir.', 1, 0, 6, 6, 3, 108, 'C', '1-Risk değerlendirmesinde ve tespit öneri defterinde yazan hususlar eksiksiz yerine getirilmelidir.\n2-Çalışanlar geçirdikleri iş kazalarını en geç 3 iş günü içerisinde İSG birimine bildirmeli ve SGK bildirimi yapılmalıdır.                                       \n3-İş kazası sonrası çalışanlara kaza sonrası iş güvenliği eğitimi verilmelidir.', 'İŞVEREN V.\nİŞ GÜVENLİĞİ UZMANI', 'İŞ KAZASI OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 31, 'BÖLÜM 1: HASTANE GENELİ', '1-Stajer öğrencilerin tek başına iş ve işlem yapması', '1-İş kazası sonucu ele iğne batması, yaralanma', '1-Stajer öğrenciler', '1-Stajer öğrencilere iş güvenliği eğitimi verilmektedir.', 1, 0, 6, 6, 3, 108, 'C', '1- Lise stajeri öğrencilerine invaziv (iğne, kan alma vb.)işlemler kesinlikle yaptırılmamalıdır.                                                                   \n2- Üniversite öğrencilerine yaptırılan invaziv işlemler mutlaka bir gözlemci çalışan eşliğinde yaptırılmalıdır.                                                          \n3- Stajer öğrenciler yetkisiz hiç bir iş ve işlem yapmamalı, cihaz ve makineleri kullanmamalıdır.\n4- Stajer öğrenciler, hastanede çalışırken gözlük ya da yüz siperi, maske, eldiven, kaymaz tabanlı ayakkabı kullanmalıdır.', 'İŞVEREN V.\nBİRİM SORUMLULARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 32, 'BÖLÜM 1: HASTANE GENELİ', '1- Panik butonlarının çalışmaması, yaka butonlarının pilinin bitmesi', '1- Beyaz kod durumunda güvenlik görevlilerine ulaşılamaması sonucu durumun kötüleşmesi', '1- Çalışanlar', '1-Bir çok alanda  panik butonları mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1- Panik butonları her zaman çalışır durumda olmalıdır.                    \n2- Panik butonlarının haftalık fonksiyon testleri yapılmalı, yılda en az bir kez periyodik kontrol yapılmalıdır.                                       \n3- Panik butonlarında arıza olması halinde en fazla 2 saat içinde arıza giderilmeli, giderilemiyorsa, çalışanlara yaka butonları verilmelidir.                                                                                                                                 4- Yaka butonları kontrol edilmeli pilleri bitmeden değiştirilmelidir.', 'İŞVEREN V.\nÇALIŞANLAR', 'YILDA 1\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 33, 'BÖLÜM 1: HASTANE GENELİ', '1- Kesici delici aletlerin emniyetsiz kullanılması', '1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- Çalışanlar', '1- Kesici delici alet kutuları mevcttur.                2-Çalışanlara kesici delici aletlerin güvenli kullanımı konusunda eğitim verilmektedir.', 1, 0, 6, 6, 3, 108, 'C', '1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                                 3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                                                                                                5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.', 'ÇALIŞANLAR', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 34, 'BÖLÜM 1: HASTANE GENELİ', '1- Kan ve vücut sıvılarının göz ve cilde temas etmesi', '1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- Çalışanlar', '1-KKD\'ler mevcuttur.                                         2- Çalışanlara KKD önemi ve kullanımı konusunda eğitim verilmektedir.', 1, 0, 6, 6, 3, 108, 'C', '1-Çalışanlar TS EN 455  standardında eldiven, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında maske vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.', 'İŞYERİ HEKİMİ  ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA    HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 35, 'BÖLÜM 1: HASTANE GENELİ', '1-Steril olmayan, kontamine olmuş aletlerin açıkta bırakılması', '1-Steril olmayan aletlere temas sonucu iş kazaları enfeksiyon, bulaşıcı hastalık', '1- Çalışanlar', '1-KKD\'ler mevcuttur.                                         2- Atık kutuları mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1-Kullanılan, kontamine olmuş aletler bekletilmeden hemen kapaklı ve renk kodlu atık kutularına atılmalıdır.                                                                                                                           2- Sterilazyona gidecek aletlere TS EN 388 standardında kesilme ve delinmeye dayanıklı eldiven olmadan temas edilmemeli, çelik, kapaklı kutulara konulmalıdır.                                                                                                                                                        3- Tek kullanımlık olmayan aletler her kullanımdan sonra dezenfekte edilmelidir. \n 4- Kontamine olmuş aletler, çarşaf, yatak, yorgan vb. yere saplanmamalı, yere atılmamalıdır.                                                                                                                                                          5- Temas edilmesi durumunda, bölge bol su ve sabunla yıkanmalıdır.', 'İŞVEREN V.\n(EKSİK KKD TEMİNİ)\nÇALIŞANLAR', '3 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 36, 'BÖLÜM 1: HASTANE GENELİ', '1- Makine ve cihazların kullanım talimatlarının bulunmaması', '1- İş kazları meydana gelmesi', '1- Çalışanlar', NULL, 1, 0, 6, 6, 3, 108, 'C', '1- Hastane de kullanılan tüm makine ve cihazların güvenli kullanım talimatları hazırlanmaldır.\n2- Kullanım talimatları makine ve cihazlar ile birlikte bulundurulmalıdır.\n3- Kullanım talimatlarında üreticinin tavsiyelerine uyulmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 37, 'BÖLÜM 1: HASTANE GENELİ', '1-Atık varillerin kapaklarının açık bırakılması', '1-Zehirlenme, toksik maddelere maruz kalma', '1- Çalışanlar', '1-Renk kodlarına göre atık varilleri mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1- Atık varillerinin kapağı sürekli olarak kapalı halde tutulmalıdır,                                                                  2- Atıklar karıştırılmamalı, her atık türü için (Tıbbi, Tehlikeli, Evsel)belirlenmiş renk kodlu atık kutularına atılmalıdır.                                                                                                                                                    3- Kesici delici aletler sadece kesici delici alet kutusuna atılmalıdır.                                                                                                                           4- Atık varilleri en fazla 3/4 oranında dolduğunda değiştirilmelidir.', 'ÇALIŞANLAR', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 38, 'BÖLÜM 1: HASTANE GENELİ', '1- Lateks eldivenlerinin kullanılması', '1- Ciltte alerji meydana gelmesi', '1- Çalışanlar', NULL, 1, 0, 6, 6, 3, 108, 'C', '1- Pudralı eldivenler kullanılmamalı, pudrasız eldivenler temin edilmelidir.\n2- Daha az alerjik reaksiyona sebep olan eldivenler tercih edilmelidir.\n3- Koruyucu el kremleri kullanılmalıdır.\n4- Eldiven kullanımından sonra eller bol su ve sabun ile yıkanmalıdır.', 'İŞVEREN V.    ÇALIŞANLAR', '3 AY                               HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 39, 'BÖLÜM 1: HASTANE GENELİ', '1- Elektrik tesisatının, topraklamaların, kaçak akım rölelerinin, yangın rölelerinin periyodik kontrollerinin tekrarlanmaması', '1- Elektrik çarpması sonucu yaralanma\n2- Elektrik yangınları  meydana gelmesi', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1- Elektrik tesisatının, topraklamaların, kaçak akım rölelerinin, yangın rölelerinin periyodik kontrolleri TS EN 60079 serisi, TS HD 60364-4 serisi, TS HD 60364-5 Serisi, TS HD 60364-6 standartlarına uygun olarak en geç yılda bir kez tekrarlanmalıdır.\n2- Her elektrik panosu için ayrı test ve ölçüm yaptırılmalıdır.\n3- Tüm bakım ve kontroller kayıt altına alınmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 40, 'BÖLÜM 1: HASTANE GENELİ', '1- Periyodik sağlık kontrollerinin ve sağlık taramalarının yılda bir tekrarlanmaması', '1-Meslek hastalığının gerçekleşmesi erken tanı konulamaması müdahaleye geç kalınması', '1- Çalışanlar', '1- Periyodik muayeneler yapılmaktadır.', 1, 0, 1, 6, 15, 90, 'C', '1- Çalışanların, akciğer grafileri, göz muayeneleri, solunum fonksiyon testleri ekg, odyometri ölçümleri, kan ve idrar tahlilleri, ppd testleri  ve işyeri hekiminin talep edeceği diğer tıbbi tetkikler yılda bir kez yapılmalıdır.                                                                                                                                               2- İşe yeni başlayan çalışanlara gerekli tahliller yaptırılmadan işbaşı verilmemelidir.', 'İŞVEREN V.                                        İŞYERİ HEKİMİ', 'İLGİLİ PERİYOTLAR \nİLE \nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 41, 'BÖLÜM 1: HASTANE GENELİ', '1-Etiketleme kilitleme sisteminin uygulanmaması', '1- Elektrik çarpması sonucu yaralanma', '1- Elektrik işlerinde çalışanlar \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 2, 15, 90, 'C', '1- İşyerinde elektrik ile yapılacak çalışma ya da tamir bakım işleri için etiketleme kilitleme sistemi kurulmalıdır.\n2- Çalışma sırasında yetkili kişiler tarafından ekipmanın çalışmasını önleyecek şekilde kilitlenmeli ve pano üzerine çalışma yapıldığına dair etiket asılmalıdır.\n3- Kilitleme işleminden sonra enerjinin kesildiği kontrol edilmeden çalışma yapılmamalıdır.\n4- Diğer çalışanlar etiketleme kilitleme yapılacağı konusunda uyarılmalıdır.', 'FİRMA', 'ELEKTRİK İŞLERİ SIRASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 42, 'BÖLÜM 1: HASTANE GENELİ', '1- Basınçlı kapların periyodik kontrollerinin tekrarlanmaması', '1- Basınçlı kapların patlaması sonucu yaralanma', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- Basınçlı kapların periyodik kontrol raporları mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1- Basınçlı hava ve gaz tanklarının periyodik kontrolleri TS 1203 EN 286-1, TS EN 13445-5, TS EN 764-7 standartlarında, Buhar ve sıcak su kazanlarının periyodik kontrolleri TS EN 12952 serisi, TS EN 12953 ve TS 497 standartlarında, Boyler ve akümülasyon tankları periyodik kontrolleri TS 736, TS EN 12897+A1 standartlarında, Oksijen tanklarının periyodik kontrolleri TS EN 13445-5, TS 1446, TS EN 12817 ve TS EN standartlarında en geç yılda bir kez tekrarlanmalıdır.\n2-  Basınçlı kapların basınç testleri belirlenmiş ise işletme basıncı ile belirlenmemiş ise en yüksek çalışma basınç değerinin 1,5 katı ile hidrostatik test yapılmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 43, 'BÖLÜM 1: HASTANE GENELİ', '1- Narkotik İlaç dolaplarının açık olması, kilitlerinin üzerinde bırakılması', '1-Narkotik ilaç kullanımına bağlı zehirlenme, bağımlılık oluşması, ölüm', '1- Çalışanlar', '1-Narkotik ilaç dolaplarının anahtarları mevcuttur.', 1, 0, 1, 2, 40, 80, 'C', '1- Narkotik ilaç dolapları her zaman kilitli olmalıdır.                                    \n2- Narkotik ilaç dolaplarının üzerinde anahtar bırakılmamalı, anahtarlar bölüm sorumlularına zimmetlenmelidir.                                                                                                                            3- Bölümlere gelen narkotik ilaçlar kayıt altına alınmalı, her vardiya değişiminde sayım yapılmalı, eksik çıkması durumunda yetkililere haber verilmelidir.', 'BİRİM SORUMLULARI   ÇALIŞANLAR', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 44, 'BÖLÜM 1: HASTANE GENELİ', '1- Çalışanların temel iş güvenliği eğitimlerine katılmamaları', '1-İş kazası ve meslek hastalıklarının artması', '1- Çalışanlar', '1- Eğitim planı ve eğitim tarihleri çalışanlar ile paylaşılmıştır.', 1, 0, 3, 3, 7, 63, 'D', '1-İşe yeni başlayan çalışanlara hastane tehlike sınıfına göre 16 saat temel iş sağlığı güvenliği eğitimi verilmelidir.\n2-Mevcut çalışanların eğitimleri yılda bir kez tekrarlanmalıdır.\n3-İş güvenliği eğitimi aldırılmayan kişilere iş başı verilmemelidir.\n4-İşe yeni başlayan çalışanlara bölüm sorumluları tarafından en az 2 saat iş başı eğitimi verilmelidir.', 'İŞVEREN V.', 'İLGİLİ PERİYOTLAR \nİLE \nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 45, 'BÖLÜM 1: HASTANE GENELİ', '1-Pendatlarda gaz kaçağı(oksijen, azot, azotprotoksit, karbondioksit) olması', '1-Baş dönmesi, sersemlik, uyku hali bulantı, konsatrasyon bozukluğu oluşması', '1- Çalışanlar', NULL, 1, 0, 3, 3, 7, 63, 'D', '1- Çalışanlar pendant sistemi üzerinde gaz kaçağı (tıslama hava çıkış sesi vb.) tespit edilmesi durumunda hemen yetkililere haber vermeli, terminal çıkışı kapatılmalıdır.                                                                                         \n2- Kaçak olan pendant da tüm gazlar kesilmelidir.  \n3- Gaz kaçağı olan alanda elektrikli hiç bir alet kullanılmamalı, ateş kıvılcım kaynağı bulundurulmamalıdır.                                                                       \n4-Gaz kaçak kaynağı (conta, hasarlı hortum, bağlantı eleamanlarında gevşeme ) tespit edilmelidir.                                                        \n5- Arıza giderildikten sonra sızdırmazlık testi yapılmadan pendant aktif hale getirilmememlidir.                                                                                            \n6- Pendatların en az yılda bir kez mekanik, sızdırmazlık ve basınç testleri yapılmalıdır.', 'İŞVEREN V.   ÇALIŞANLAR', 'ARIZA DURUMUNDA SÜREKLİ\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 46, 'BÖLÜM 1: HASTANE GENELİ', '1-EKG cihazının kablo ve elektrotlarda izolasyon açıklıkları olması                                            2- Şarj işlemi sonrası kabloların fişe takılı bırakılması', '1-Ekg kullanımı sırasında elektrik çarpması, elektrik yanıkları oluşması', '1- EKG kullanan çalışanlar                                                     2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 3, 7, 63, 'D', '1-EKG cihazı kullanılmadan önce kablolar, elektrotlar ve cihaz gövdesi kontrol edilmelidir.                \n2- EKG kullanılacak alanda yanıcı sıvı gaz ve ıslak yüzeyler bulunmamalıdır.                                                                                                                                             3- Her işlemden sonra cihaz ve elektrotlar yanıcı olmayan malzemeler ile dezenfekte edilmelidir. Tek kullanımlık elektrotlar tıbbi atık kutusuna atılmalıdır.                                                                                        \n4- EKG cihazı ya da kablosu şarj edildikten sonra fişe takılı bırakılmamalıdır.', 'ÇALIŞANLAR', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 47, 'BÖLÜM 1: HASTANE GENELİ', '1-Elektrik panolarının, pano odalarının yangın dolaplarının önlerinin kapatılmış olması', '1-Acil durumlarda hızlı müdahalenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Malzeme, makine, temizlik arabası vb. pano ve  yangın dolaplarının önlerini kapatmaması sağlanmalıdır.\n2-Panolara erişim için en az 80 cm genişlikte ulaşım yolları sağlanmalıdır.\n3-Pano üzerlerine uyarı etiket ve işaretleri asılmalıdır.', 'İŞVEREN V.\nÇALIŞANLAR', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 48, 'BÖLÜM 1: HASTANE GENELİ', '1- Aydınlatma yetersizliği, bozulması, titremesi', '1- Görme bozukluklarının oluşması ve ilerlemesi, ş kazalarında artış', '1- Çalışanlar', '1- Suni aydınlatma sistemleri yeterli sayıdadır.', 1, 0, 3, 3, 7, 63, 'D', '1-Özellikle gece çalışmalarında olmak üzere, suni ışık ihtiyacında çalışma alanı ve diğer eklentiler, yollar en az 300 lüks şiddetinde aydınlatılmalıdır.                                                                                                                      2-Aydınlatma sistemleri sağlam yapıda olmalı, bozulan, yanmayan titreyen aydınlatmalar değiştirilmelidir.\n3-Periyodik göz muayeneleri yılda bir kez yapılmalıdır.', 'İŞVEREN V.                                  İŞYERİ HEKİMİ', '3 AY                              YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 49, 'BÖLÜM 1: HASTANE GENELİ', '1-Elle taşıma işlerinin yük kaldırma prensiplerine uygun yapılmaması', '1-Kas iskelet sistemi hastalıkları oluşması,                                    2-Malzeme düşmesi, devrilmesi sonucu yaralanma', '1- Çalışanlar', '1- Çalışanlara elle taşıma işleri hakkında eğitim verilmektedir.', 1, 0, 3, 3, 7, 63, 'D', '1-Erkek çalışanlar için 25 kg’dan, kadın çalışanlar için 15 kg\'dan ağır yükler mümkün olan hallerde bir taşıma aracıyla ya da birden fazla kişi ile  taşınmalıdır.\n2- Dengesiz devrilme riski olan yükler sabitlenerek taşınmalıdır.\n3-Yükler taşıma teknikleri kullanılarak taşınmalıdır.\n4-Yükler görüş alanını kapatmayacak şekilde taşınmalıdır.\n5-Kaldırma, indirme ve yerleştirme esnasında el, ayak ve vücut bölümlerinin sıkışmayacağı şekilde ara destekler, ya da teknikler kullanılmalıdır.', 'ÇALIŞANLAR', 'EL İLE TAŞIMA İŞLERİ SIRASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 50, 'BÖLÜM 1: HASTANE GENELİ', '1-Buat kapaklarının açık olması, kapakların kırık olması', '1-Elektrik çarpması sonucu yaralanma', '1- Çalışanlar', NULL, 1, 0, 6, 3, 3, 54, 'D', '1- Buat kapakları kapalı tutulmalıdır.                                                                         2- Kırık buat kapakları değiştirilmeli, vidalar ile tutturulmamalıdır.                                                                                                  3- Buatlara L tipi fişler kullanılmalı,  buatların açık kalması önlenmelidir.                                                                                                                             4- Buatların üzerinde ki masalarda bir şey yenilip içilmemelidir.', 'İŞVEREN V.   ÇALIŞANLAR', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 51, 'BÖLÜM 1: HASTANE GENELİ', '1-Pendatların üzerine sıvı malzemeler konulması', '1- Elektriğin su ile teması sonucu çarpılma, yangın çıkması', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 3, 3, 54, 'D', '1-Pendatlar üzerine sıvı malzemeler bırakılmamalıdır.                                                    2- Pendant üzerine sıvı dökülmesi halinde kağıt havlu ile hemen silinmeli, priz veya valflere sıvı girmesi önlenmelidir.                                                                                                                          3- Prizlere sıvı kaçması durumunda hemen yetkililere haber verilmeli, pendant kullanılmamalı, gerekirse elektrik akımı kesilmelidir.', 'ÇALIŞANLAR', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 52, 'BÖLÜM 1: HASTANE GENELİ', '1-Transformatör, jeneratör, akümülatörlerin periyodik kontrollerinin tekrarlanmaması', '1- Fiziksel patlama meydana gelmesi sonucu iş kazaları yaşanması', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- Periyodik kontrol raporları mevcuttur.', 1, 0, 3, 1, 15, 45, 'D', '1- Jeneratörlerin periyodik kontrolleri TS ISO 8528 standartında, Transformatörlerin periyodik kontrolleri üreticinin belirlediği kriterlere göre, Akümülatörlerin periyodik kontrolleri TS EN IEC 62485-1 standartında en geç yılda bir tekrarlanmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 53, 'BÖLÜM 1: HASTANE GENELİ', '1-Sabitlenmemiş dolap ve raflar', '1-Devrilme, düşme ya da çarpma sonucunda vücut bölümlerinin sıkışması, yaralanması', '1- Çalışanlar', '1-Hastanede bir çok alanda dolaplar sabitlenmiştir.', 1, 0, 3, 2, 7, 42, 'D', '1-Sabitlenmemiş doalp ve raflar en az iki noktadan sabitlenmelidir.\n2-Düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.\n3-Ağır malzeme ve ekipmanlar yüksek istiflenmemelidir.   \n4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 54, 'BÖLÜM 1: HASTANE GENELİ', '1- Pendant üzerindeki prizlerin ya da jakların yerinden çıkması', '1- Elektrik çarpması ya da gaz sızıntısı sonucu yaralanma', '1- Çalışanlar', NULL, 1, 0, 3, 2, 7, 42, 'D', '1- Bozuk yerinden çıkmış priz ve jaklar kullanılmamalı, değiştirilmelidir.\n2- Fişler prizlerden çekilirken kablodan asılarak çekilmemeli, fişten tutarak çıkarılmalıdır.                                                              \n3- Gaz hortumları zorlanarak takılmamalı, jaka dik oturtularak takılmalıdır.  \n4- Jaklar kullanılmadığında tam kapatılmalıdır. \n5- Hortum ağırlığının jakları zorlamaması için destekler kullanılmalıdır.', 'İŞVEREN V.  \n\n ÇALIŞANLAR', 'ARIZA DURUMUNDA SÜREKLİ\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 55, 'BÖLÜM 1: HASTANE GENELİ', '1-Pano önlerinde yalıtkan paspas olmaması,                                                         2-Uyarı levhası olmaması,', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm', '1- Çalışanlar', '1-Pano odalarında kartlı giriş sistemi mevcuttur.', 1, 0, 3, 2, 7, 42, 'D', '1-Pano altlarına yalıtkan paspas yerleştirilmelidir.\n2-Panolara ve pano odalarında eksik olan yerlere tehlike uyarı ve işaretleri asılmalıdır.                              \n3-Elektrik pano odalarında ve panolar ile çalışma yapılırken TS EN 50321 standartında yaltkan ayakkabı, TSE EN 60903 standartında yalıtkan eldiven kullanılmalıdır.', 'İŞVEREN V.\nFİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 56, 'BÖLÜM 1: HASTANE GENELİ', '1- Elektrikli ısıtıcıların kullanılması', '1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- İklimlendirme sistemi mevcuttur.', 1, 0, 3, 2, 7, 42, 'D', '1- Hastane de soğuk havalarda elektrik ısıtıcılar kullanılmamalı, ısınma amaçlı sadece iklimlendirme sistemi kullanılmalıdır.                                                                                                          2- Çalışanların otomatik açılan kapılardan soğuk havaya maruz kaldıkları alanlara hava perdeleri yapılmalıdır.                                                                                                                                3- İstisnai durumlarda idareden özel izin alınmalı, ısıtıcıların prizlerden beslenmesi sağlanmalı, yanıcı malzemelerden uzak tutulmalı,kullanım sonrası fiş prizden çekilmelidir.                                                                                                                     4- İzinsiz kullanılan tüm ısıtıcılar toplatılmalıdır.', 'İŞVEREN V.\nÇALIŞANLAR', '2 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 57, 'BÖLÜM 1: HASTANE GENELİ', '1- Kaygan zemin oluşması                                                                  2- Bozuk zemin yüzeyi', '1-Düşme, denge kaybı sonucunda vücut bölümlerinin yaralanması', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- Temizlik işlerinde kaygan zemin levhaları konulmaktadır.', 1, 0, 1, 6, 7, 42, 'D', '1- Bozulan zeminin tamir ve tadilatı yapılmalıdır.\n2- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.                                                                                                     3- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\n4-  Çalışanlar kaymaz tabanlı ayakkabı giymelidir.', 'FİRMA\nTEMİZLİK\nÇALIŞANLARI', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 58, 'BÖLÜM 1: HASTANE GENELİ', '1-Sivri, delici, kesici, paslı makine ve ekipmanlar', '1-Yaralanma sonucu tetanos hastalığına yakalanma', '1- Çalışanlar', '1- Tetanos aşıları yapılmaktadır.', 1, 0, 3, 2, 7, 42, 'D', '1-Paslı alet ve ekipmanlar yenileriyle değiştirilmeli, paslanmaz malzemeler kullanılmalıdır.\n2-Sivri, delici, kesici, paslı makine ve ekipmanlara eldivensiz temas edilmemelidir.\n3-Yeni başlayan ya da aşısı eksik olan çalışanlara tetanos aşısı yapılmalı, 5 yılda bir ya da yaralanma durumunda tekrar aşı yapılmalıdır.', 'İŞVEREN V.                                  İŞYERİ HEKİMİ', '3 AY                              İLGİLİ PERİYOTLAR İLE SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 59, 'BÖLÜM 1: HASTANE GENELİ', '1- Havalandırma sisteminin periyodik kontrollerinin tekrarlanmaması', '1-Zararlı partiküllerin solunması sonucunda meslek hastalıklarının oluşması', '1- Çalışanlar', '1- Havalandırma sisteminin periyodik kontrolleri mevcuttur.', 1, 0, 1, 6, 7, 42, 'D', '1- Havalandırma sisteminin periyodik kontrolleri havalandırma tesisat projesinde yer alan kriterlere göre en geç yılda bir tekrarlanmalıdır. \n2- Hava değişim sayısı ölçümleri yaptırılmalıdır.\n3- Otomatik sıcaklık, nem izleme sistemleri bulunmalı, çalışır durumda olmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 60, 'BÖLÜM 1: HASTANE GENELİ', '1- Termal konfor takibinin yapılmaması', '1- Dikkat kaybı, iş kazası ve meslek hastalıklarında artışlar', '1- Çalışanlar', '1- İklimlendirme sistemi mevcuttur.', 1, 0, 3, 3, 3, 27, 'D', '1-Çalışma ortamı %35-%75 nem oranında ve 18-24 C derece arasında olması sağlanmalıdır.                                                                                  \n2- Ofislerde çalışan başına 10m3 temiz hava sağlanmalıdır.\n3-Hava akım hızının 0,5 m/sn ortalamada olması sağlanmalıdır.\n4-Çalışma ortamının saatte en az 6-10 kez havalandırılması sağlanmalıdır.', 'İŞVEREN V.', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 61, 'BÖLÜM 1: HASTANE GENELİ', '1- Sivri keskin yüzeylerin bulunması', '1- Temas sonucu yaralanma', '1- Çalışanlar', NULL, 1, 0, 3, 3, 3, 27, 'D', '1- Keskin ya da sivri yüzeyler oval hale getirilmelidir.\n2- Keskin ya da sivri yüzeyler yumuşak bir malzeme ile kaplanmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 62, 'BÖLÜM 1: HASTANE GENELİ', '1- Otomatik kayar kapıların sensörlerinin bozulması, periyodik kontrollerinin tekrarlanmaması', '1-Hareket sensörlerinin bozulması sonucu sıkışma yaralanma', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', NULL, 1, 0, 1, 3, 7, 21, 'D', '1- Otomatik kayar kapıların hareket sensörleri ayda bir kontrol edilmeli en geç yılda bir kez periyodik kontrolleri yapılmalıdır. \n2-Çalışanlar kapı kapanırken el, kol ya da bacaklarını kapı arasına sokmamalı, kapının tamamen kapanmasını beklemelidir.', 'FİRMA\nÇALIŞANLAR', 'YILDA 1\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 63, 'BÖLÜM 1: HASTANE GENELİ', '1- Çalışanların yöneticileri ya da hasta hasta yakınları tarafından mobing uygulanması', '1-Sinirlilik, stres, depresyon, tükenmişlik sendromu, iş kazalarında artış', '1- Çalışanlar', '1-Çalışan hakları birimi mevcuttur.                                         2-Çalışan memnuniyet anketleri yapılmaktadır.', 1, 0, NULL, NULL, NULL, NULL, NULL, '1-Çalışanlara gereğinde psikolojik destek ve danışmanlık sağlanmalıdır.                                                                                                                                         2- Mobing bildirimi alındığında tarafsız inceleme süreci başlatılmalı, taraflar ayrı ayrı dinlenmeli, ve somut veriler ile kayıt tutulmalıdır.                                                                                                                            3- Tükenmişlik yaşayan çalışanlar düşük yoğunluklu birimlere kaydırılmalıdır.                                                                                                                              4- Şikayet konusu yönetici ise, yönetici davranış düzeltme sürecine (eğitim, gözlem vb.) alınmalıdır.                                                                           \n5- Sürekli sorun çıkaran çalışanlar için eğitim, görev değişikliği ya da disiplin süreçleri başlatılmalıdır.', 'İŞVEREN V.\nÇALIŞAN \nHAKLARI \nBİRİMİ', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: AMELİYATHANE', '1-Ameliyat esnasında skopi kullanılması                                               2-Skopi kullanımı esnasında çalışanı korumak için kurşun paravan olmaması                                                             3-Kurşun önlüklerin yetersiz olması', '1-Meslek hastalıkları, mesleki kanserler oluşması', '1- Tüm Ameliyathane Çalışanları', '1- Kurşun önlük ve triot koruyucular alanda mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1- Skopi kullanılan odalarda kurşun paravan bulunmalıdır.                                                                                        2- Skopi kullanılan odaların kapıları, çalışma sırasında kapalı tutulmalıdır.                                                                                           3- Skopi çekimleri Radyoloji Teknikeri tarafından yapılmalıdır ve çekim yapılırken, odada yetkili kişi ve hasta dışındaki kişilerin bulunması önlenmelidir. \n4- Oda içerisinde bulunması gereken tüm çalışanların KKD\'leri (Kurşun önlük,troit koruyucu,vb) eksiksiz olmalıdır. \n5- İyonize radyasyon kaynaklarına maruz kalan bütün çalışanlar doz ölçer kullanmalıdır.                                                                                                                                                                                                                    6-Hamile çalışanlar radyasyon alanlarına girmemelidir.', 'İŞVEREN V.\n\nRADYOLOJİ ÇALIŞANLARI       \n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\n\nÇEKİM ESANASINDA SÜREKLİ KULLANIM', 2, 2, 15, 60, 'D', 'acik', 'Kurşun paravan mevcutta olmayıp, mevcutta olan kurşun önlükler çalışan sayısına yeteri kadar bulunmamaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: AMELİYATHANE', '1- Skopi önlüklerinin uygun şartlarda muhafaza edilmemesi', '1-Meslek hastalıkları, mesleki kanserler oluşması', '1- Tüm Ameliyathane Çalışanları', '1- Kurşun önlük ve triot koruyucular alanda mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1-Skopi önlüğü kullanması gereken azami kişi sayısına yetecek kadar kurşun önlük, troit koruyucu ve kurşun gözlük temin edilmelidir.                                                                              2-Skopi önlükleri dikey pozisyonda, özel askılarda (omuzdan destekli şekilde) muhafaza edilmelidir.Kesinlikle katlanmamalı, üst üste konulmamalıdır.                                                                                                                                                                                       3-En az yılda 1 kez floroskopik kontrol (radyografik test) ile kurşun tabakanın bütünlüğü kontrol edilmeli. Çatlak, yırtık veya deformasyon tespit edilen önlükler raporlanarak derhal kullanım dışı bırakılmalı ve hasarlı ekipmanın yerine yenisinin temin edilmelidir.                                                                                  4- Her kullanım sonrası uygun şekilde dezenfekte edilmelidir.', 'İŞVEREN V. \n (ÖNLÜK TEMİNİ)\n                              AMELİYATHANE ÇALIŞANLARI', '30.09.2027\n                                            HERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', 'Önlükleri muhafaza etmek için uygun askılık sistemleri mevcut olup yıllık floroskopik kontrolleri yapılarak hasarlı olan KKD\'ler kullanımdan kaldırılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: AMELİYATHANE', '1- Ameliyathane dinlenme alanlarında yüksek güçlü elektrikli ekipmanın (çay kazanı) kontrollü ve güvenli kullanılmaması', '1- Uygunsuz elektrik bağlantısı, aşırı yüklenme, \n2- Kablo/fiş-priz arızası veya ekipman arızası \n3- elektrik çarpması \n4- Yangın', '1- Tüm ameliyathane çalışanları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Ameliyathane içerisinde yalnızca kurum tarafından belirlenmiş mutfak/dinlenme alanlarında elektrikli içecek hazırlama cihazlarının kullanılmasına izin verilmeli, bunun dışındaki odalarda (ameliyat salonu, depo, ofis, malzeme odası vb.) elektrikli ısıtıcı cihaz kullanımı yasaklanmalıdır.                    \n2- Cihazlar doğrudan topraklamalı sabit prizden beslenmeli; uzatma kablosu, çoklu priz veya seyyar kablo ile kullanımına izin verilmemelidir.       \n3- Elektrikli cihazların periyodik elektriksel güvenlik kontrolleri (topraklama, kaçak akım, kablo ve fiş bütünlüğü) biyomedikal/teknik hizmetler tarafından planlı olarak yapılmalıdır.                                                            4-Kullanım sonrası tüm elektrikli cihazların enerjisi kapatılmalı ve fişleri prizden çekilmelidir.                                                                                                      5- Mutfak olarak tanımlanmış alanlarda sadece çay ve kahve makinesi  dışındaki aletlerin (tost makinası,mikrodalga fırın, vb.) kullanımı yasaklanmalıdır.                                                                                                            6-Alan sorumluları tarafından günlük saha kontrollerinde yetkisiz elektrikli cihaz bulundurulup bulundurulmadığı denetlenmelidir.', 'İŞVEREN V.\n\nBİRİM SORUMLULARI\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\n HERGÜN KONTROL\n \nHERGÜN KONTROL', 3, 1, 7, 21, 'D', 'acik', 'Konuyla ilgili olarak 08.10.2025 tarihinde iç emir yayımlanmıştır. Husus, Temmuz 2026 tarihli İSG Kurulu toplantısında yeniden değerlendirilmiş ve 19.08.2026 tarihinde konuya ilişkin tekrar iç emir yayımlanmıştır. Onaysız elektrikli mutfak aletlerinin kullanımının tespit edilmesi hâlinde, ilgili kişi hakkında tutanak düzenlenmesine karar verilmiştir.\n\nMevcut risk devam etmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: AMELİYATHANE', '1- Ameliyathane içerisindeki lavaboların önünde su birikintilerinin olması', '1- Elektrik çarpması                    2- Kayma- düşme sonucu yaralanma', '1- Tüm Ameliyathane çalışanları', '1- Uyarı levhaları mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1-Lavabo çevresindeki prizler, anahtarlar ve elektrik bağlantıları IP koruma sınıfına uygun, sıçrama suyundan etkilenmeyecek şekilde tesis edilmeli; kablo ve prizlerde hasar bulunmamalıdır.                                                              2- Lavabo çevresinde su yalıtımı sağlanmalı, sızıntı kaynakları önlenmelidir.\n3- Temizlik hizmetleri arttırılarak su birikintisi görüldüğünde anında temizlenmeli ve kurulanmalı, \"Islak Zemin\" uyarı levhaları yerleştirilmelidir.\n4- Çalışanlar EN ISO 20347 veya EN ISO 20345 standardına uygun kaymaz tabanlı iş ayakkabısı giymelidir.                                                                                           5-Lavabo önlerinde kullanılan zemin kaplamalarının kaymaz özellikte olması sağlanmalı; gerekli görülen alanlarda kaydırmaz paspas veya kaydırmaz yüzey uygulaması yapılmalıdır.', 'İŞVEREN V. \n\nTEMİZLİK HİZMETLERİ\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\n HERGÜN KONTROL \n\nHERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', '2 İŞ KAZASI YAŞANMIŞTIR.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: AMELİYATHANE', '1-Ameliyat salonu  dezenfeksiyon işlemi sonrasında zemin kurumadan yeni hasta alınması', '1- Zemin ıslaklığı nedeniyle kayma/düşme kazası, yaralanma', '1- Tüm Ameliyathane çalışanları', '1- Her ameliyat sonrasında  dezenfeksiyon işlemi yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1-Zemin dezenfeksiyonu tamamlandıktan sonra zemin tamamen kuruyuncaya kadar ameliyat salonuna personel, hasta ve ekipman girişine izin verilmemelidir.                                                                                         \n 2- Zemin dezenfeksiyonunda kullanılacak ürünler seçilirken kuruma süresi kısa ve kuruduktan sonra su ile yeniden temas ettiğinde kayganlık oluşturmayan ürünler tercih edilmelimelidir.                                                                                                                      3-Zemin dezenfeksiyonunda kullanılacak ürünler seçilirken kuruma süresi kısa ve kuruduktan sonra su ile yeniden temas ettiğinde kayganlık oluşturmayan ürünler tercih edilmeli; su ile yeniden teması halinde kayganlık riskini azaltacak uygulamalar standart hale getirilmelidir.                     4-Ameliyat salonuna yeni hasta kabulü, zeminin tamamen kuruduğu ve kayma riski bulunmadığı sorumlu ameliyathane personeli tarafından doğrulandıktan sonra yapılmalıdır.                                                                                5-Kayma riskinin yüksek olduğu alanlarda çalışanların EN ISO 20347 standardına uygun kaymaz tabanlı iş ayakkabısı kullanmaları sağlanmalıdır.', 'İŞVEREN V.\n \n TEMİZLİK HİZMETLERİ\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\n HERGÜN KONTROL\n \nHERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: AMELİYATHANE', '1-Patoloji ve dezenfeksiyon odalarında dökülme kiti ve göz duşu bulunmaması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1- Patoloji ve dezenfeksiyon odası çalışanları                                                2- Diğer ameliyathane çalışanları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Kimyasal kullanılan tüm alanlarda kullanılan kimyasalların özelliklerine uygun döküntü müdahale (spill kit) ekipmanları kolay ulaşılabilir noktalarda bulundurulmalıdır.                                       \n2- Göz ve yüz bölgesine kimyasal sıçrama riski bulunan alanlara TS EN 15154 standardına uygun acil göz/yüz duşu sistemi kurulmalı veya uygun taşınabilir göz yıkama istasyonları bulundurulmalıdır.                                         3-Kimyasal dökülmesi halinde uygulanacak acil müdahale prosedürü çalışma alanında görünür şekilde bulundurulmalıdır.  \n4-Kimyasal hazırlama ve kullanım sırasında kimyasalın SDS\'inde belirtilen kişisel koruyucu donanımlar (kimyasala dayanıklı eldiven, gözlük/yüz siperi, önlük vb.) eksiksiz kullanılmalıdır.                                                                                           \n5- Kimyasallara ait güncel Güvenlik Bilgi Formları (GBF/SDS), çalışma alanında kolay erişilebilir şekilde bulundurulmalı ve çalışanların erişimine açık olmalıdır. Çalışanlara SDS ve kimyasalların güvenli kullanımı konusunda eğitimler verilmelidir.', 'İŞVEREN V.\n\nPATOLOJİ ODALARI ÇALIŞANLARI', '30.09.2027\n\nHERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', 'Mevcut risk devam etmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: AMELİYATHANE', '1-Patoloji odalarında formaldehitin uygunsuz kullanımı', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması, meslek hastlaıkları oluşması', '1- Patoloji odası çalışanları                                                2- Diğer ameliyathane çalışanları', '1- Formaldehit porsiyonlaması  10lt\'lik musluklu bidondan aktarılarak yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1- 21.10.2025 tarihinde hazırlanan Yöntem Beyan\'ına göre firma tarafından formaldehit, patoloji laboratuvarında porsiyonlanarak ameliyathaneye  gönderilmelidir.  \n2- Numune kaplarının işlem süresince kapalı tutulması; kapakların açık bırakılmamalıdır.\n3- Formaldehitin başka bir kaba aktarılmasının zorunlu olduğu durumlarda, uygun ve etiketli kapların kullanılması; açık kapta bekletilmemelidir.\n4- Formaldehit kullanılan alanlarda kimyasal maruziyetine yönelik KKD\'nin TS EN 374 Standardında eldiven (nitril, neopren veya formaldehite dayanıklı), laboratuvar önlüğü, EN 166 standartlarında gözlük/ siperlik ve FFP3 ventili maske ve ya en az FFP2 maske kullanılmalıdır.\n6-  Formaldehit kapları tanımlı olmalı; üzerinde kimyasalın adı, tehlike bilgileri ve gerekli uyarıların bulunmasının sağlanmalıdır.\n7-  Formaldehitin diğer kimyasallardan uygun şekilde ayrılarak, güvenli ve kontrollü koşullarda depolanmalıdır. \n8-  Formaldehit dökülmesi/sıçraması durumunda uygulanacak acil müdahale prosedürünün oluşturulmalı ve dökülme kiti kolay erişilebilir olmalıdır.\n9-  Formaldehit kullanılan alanlarda  VOC Ölçümü ile iç ortam ve kişisel maruziyet ölçümleri yapılmalıdır.                                                                                                                                                                                                                                                                                                                                       10- Kullanılmış formalin, dökülmeyecek şekilde kapağı kapatılarak patoloji birimine teslim edilmeli ve meydana gelen atıkları \"Tehlikeli Atık Varili\"ne atılarak imha edilmelidir.', 'İŞVEREN V.\n\nPATOLOJİ  ODASI ÇALIŞANLARI', '30.09.2027\n\n HERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', 'Formaldehit kapları 15ml ve 100 ml boyutlarda porsiyonlanarak gelmektedir. KKD\'ler eksiksiz kullanılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: AMELİYATHANE', '1-Patoloji odalarında havalandırmanın sisteminin yeterliliğinin ve etkinliğinin sürekliliğinin sağlanamaması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması, meslek hastlaıkları oluşması', '1- Patoloji odası çalışanları                                                2- Diğer ameliyathane çalışanları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1-Formaldehit kullanılan odalara saatlik temiz hava giriş debi ve saysı  arttırılmalı, kimyasal solunum bölgesine ulaşmadan zeminden atılmalıması sağlanmalı, alttan çekiş sistemi kurulmalıdır.\n2- Havalandırma menfezlerinin önü kapatılmamalı ve hava akışını engelleyecek malzeme/depolama yapılmamalıdır..\n3- Formaldehit ile yapılan çalışmalar sadece çeker ocak altında yapılmalı                                                                                                                           4- Formadehit kaplarının ağızları kapalı tutulmalı, sadece çeker ocak altında açılmalıdır.  \n4-Havalandırmanın etkinliğine ilişkin (hava debisi, hava değişim sayısı,vb) teknik parametrelerin ölçülmleri yapılmalı, bakım ve kontrolleri kayıt altına alınmalıdır.', 'İŞVEREN V.\n\nTEKNİK BİRİM\n\n PATOLOJİ ODALARI ÇALIŞANLARI', '30.09.2027\n\n HERGÜN KONTROL \n\nHERGÜN KONTROL', 1, 3, 7, 21, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: AMELİYATHANE', '1-Kırmızı, yeşil reçeteli (narkotik ve psikotrop) ilaçların depolandığı dolapların yetkisiz erişime açık olması', '1-Narkotik ilaç kullanımına bağlı zehirlenme, bağımlılık oluşması, ölüm', '1- Tüm ameliyathane çalışanları', '1- Kilitli narkotik dolabı mevcuttur.', 1, 0, 6, 1, 40, 240, 'B', '1- İlaçların yetkisiz kişilerin erişimine kapalı, güvenli, kilitli koşullarda muhafaza edilmelidir. Anahtar sadece yetkili eczane çalışanları kontrolünde olmalıdır.                                                                                                   2-Kullanım kayıt defteri veya elektronik sistem üzerinden giriş/çıkış kayıtları tutulmalı ve sorumlu eczacı tarafından günlük stok takibi yapılmalıdır.                                                                                                                     3- İlaç dolaplarının bulunduğu alanda kamera sistemi olmalı ve kamera kayıtlarıyla ilaç odasına giriş-çıkışlar denetlenmelidir.                                                                                   4-Narkotik ilaçların teslim alınması işlemleri, uzman hekim tarafından onaylanmış form doğrultusunda, uzman hekim veya anestezi asistanı tarafından gerçekleştirilmelidir.', 'ECZANE SORUMLUSU\n\nBİRİM SORUMLUSU\n\nANESTEZİ HEKİM VE \nÇALIŞANLARI', '30.09.2027\n\nHERGÜN\n\nHERGÜN', 1, 1, 40, 40, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: AMELİYATHANE', '1- Narkotik ilaçların yetkisiz veya kötüye kullanımı', '1-Narkotik ilaç kullanımına bağlı zehirlenme, bağımlılık oluşması, ölüm', '1- Tüm ameliyathane çalışanları', '1- Narkotik ilaçtarın teslimi yetkili eczane çalışanları tarafından yapılmaktadır.', 1, 0, 6, 1, 40, 240, 'B', '1- Narkotik ilaçların hem teslim alma hem de kullanım sonrası iade/imha işlemleri iki yetkili personelin (uzman hekim + anestezi teknikeri/asistanı) eş zamanlı kontrolü ile yapılmalarak kayıt altına alınmalıdır.                                                                              2- İlaç imhası süreci, ilgili anestezi hekimi tarafından tutanakla kayıt altına alınmalı ve eczane birimi tarafından doğrulanmalıdır.   \n3- Olağan dışı tüketim farkı tespitinde olay incelip raporlanarak yetkili kişilere bildirilmelidir.', 'ECZANE SORUMLUSU\n\nBİRİM SORUMLUSU\n\nANESTEZİ HEKİM VE \nÇALIŞANLARI', '30.09.2027\n\nHERGÜN\n\nHERGÜN', 1, 1, 40, 40, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: AMELİYATHANE', '1- Ameliyathane yemekhanesinin acil çıkış kapısının olmaması ve tahliye zorluğu', '1- Yangın, deprem vb. acil durumlarda tahliye zorluğu', '1- Tüm ameliyathane çalışanları', NULL, 1, 0, 1, 6, 40, 240, 'B', '1-Ameliyathane yemekhanesinde en az 2 adet acil çıkış kapısı olmalıdır.                                                                                                              2-Acil çıkış kapıları dkaçış yönünde açılması ve kapının kaçışı engellememeli ve kapıların kolay erişilebilir, kilitsiz ve acil durumda gecikmeye neden olmadan açılabilir durumda olması, kaçış kapısının açıldığında koridoru, merdiveni veya kaçış yolunu tehlikeli şekilde daraltmaması/engellememesi gerekir.                                                                  3- En az 60–120 dakika çalışabilen acil aydınlatma ve yönlendirme levhaları ve yangın söndürme ekipmanları en fazla 20–25 m aralıklarla yerleştirilmelidir.                                                                                                                4-Acil çıkış/kaçış yönü işaretleri bulunmalıdır', 'İŞVEREN V.\n\nTEKNİK BİRİM\n\n BİRİM SORUMLUSU', '30.09.2027\n\n HERGÜN KONTROL \n\nHERGÜN KONTROL', 1, 1, 40, 40, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: AMELİYATHANE', '1- Temizlik arabalarının akülerinin uygunsuz alanda şarj edilmesi', '1-Patlama, yangın,                           2-Elektrik çarpması', '1- Tüm ameliyathane çalışanları', '1- Tesisatın periyodik kontrolü mevcuttur.\n2- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Ameliyathane içerisindeki temizlik arabalarının akü şarj işlemi temizlik odalarında yapılmamalıdır.                                                                                                                                                                2- Aküler şarj için belirlenmiş tanımlı alanlarda şarj edilmelidir.                                                              3-Akü şarj alanları iyi havalandırılmış olmalı, devrilmeyecek şekilde konumlandırmalıdır. Herhangi bir şekilde sıvı ile teması engellenmelidir.\n4-Aküler şarj edildikten sonra fişte takılı bırakılmamalıdır.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  5-Şarj noktasında CO₂ veya kuru kimyevi tozlu söndürücü bulundurulmalıdır.', 'İŞVEREN V.\n\n ŞİRKET', '30.09.2027\n\n30.09.2027', 2, 2, 15, 60, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: AMELİYATHANE', '1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması', '1-Enfeksiyon sonucu bulaşıcı hastalıklar                                      2- meslek hastalıkları', '1- Tüm Ameliyathane çalışanları', '1- Alanda KKD mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Alanda çalışan tüm çalışanlara yetecek uygunlukta EN 14683 cerrahi maske, EN 455 eldiven, EN 166 yüz siperliği/koruyucu gözlük temin edilerek çalışanların kullanımına uygun ve her zaman alanda hazır olarak bulundurulmalıdır.                                                 \n2- Çalışanlar sahada kişisel koruyucu ekipmanlarını eksiksiz şekilde kullanmalıdırlar.                                                                                                            3- KKD Zimmet formu tüm çalışanlar tarafından imzalanmalıdır.', 'İŞVEREN V.\n (KKD TEMİNİ) \n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n                                                                                                       HERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: AMELİYATHANE', '1-Ameliyat esnasında kullanılan yıkama (irigasyon) solüsyonlarının akma ve damlamaları sonucu zeminde ıslaklık oluşması', '1-Zemin ıslaklığına bağlı kayma, düşme, sonucu iş kazaları                                            2- Elektrik çarpması', '1-Tüm Ameliyathane çalışanları', '1- Her ameliyat sonrasında ıslak ıslak alanlar elektrikli zemin temizleme makinası ile temizlenmektedir.', 1, 0, 6, 3, 7, 126, 'C', '1- İrrigasyon solüsyonunun zemine ulaşmasını engelleyecek  Enfeksiyon Kotrol Komitesinin uygun gördüğü toplama/emme/drenaj sistemleri kullanılmalıdır.\n2- Sıvının kontrollü şekilde toplanmasını sağlayacak  Enfeksiyon Kotrol Komitesinin uygun gördüğü drenaj/toplama sistemi veya cerrahi sıvı toplama ekipmanları kullanılmalıdır.\n3- Operasyon masası ve cerrahi alan çevresinde sıvı akışının zemine yönelmesini önleyecek Enfeksiyon Kotrol Komitesinin uygun gördüğü bariyer/toplama (sıvı emici) materyaller kullanılmalıdır.\n4- Yıkama (irigasyon) sistemlerinin hortum ve bağlantı noktaları her kullanım öncesi sızdırmaya karşı kontrol edilmelidir.\n5- Elektrik kablolarında izolasyon açıklığı ya da ek bulunmamalı, kablolar çift izolasyonlu olmalıdır.                                                                                                                                                                                                                                                                                    6-Tüm ameliyathane çalışanları kaymaz tabanlı, sıvı geçirmez ameliyathane ayakkabısı kullanmalıdır.', 'İŞVEREN V.\n\nENFEKSİYON KONTROL KOMİTESİ\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\n HERGÜN KONTROL \n\nHERGÜN KONTROL', 3, 1, 15, 45, 'D', 'acik', '2 İŞ KAZASI YAŞANMIŞTIR.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: AMELİYATHANE', '1- Ameliyat odalarında kabloların dağınıklığı', '1- Elektrik çarpmaları                                      2- Takılma/düşme kaynaklı iş kazaları', '1- Tüm Ameliyathane çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Cihazlara ait elektrik kabloları, bağlantı kabloları ve varsa hortumlar mümkün olduğunca kablo kanalı, kablo köprüsü, uygun kablo düzenleyici veya üretici tarafından uygunluğu belirtilmiş sabitleme sistemleri kullanılarak düzenlenmelidir.\n2- Kabloların ameliyathane personelinin yürüme ve çalışma alanlarında serbest şekilde zeminde bulunması önlenmelidir.\n3- Geçiş yollarından kablo geçirilmesi zorunlu ise kablolar uygun şekilde sabitlenmeli ve üzerinden geçmeye bağlı takılma riskini önleyecek uygun kablo köprüsü/zemin üstü kablo koruyucu kullanılmalıdır.\n4- Kabloların kapı altından, keskin kenarlardan, hareketli ekipmanların altından veya sıkışma/ezilme meydana gelebilecek bölgelerden geçirilmesi önlenmelidir.\n5- Kabloların fiş, priz, bağlantı noktası ve izolasyonları düzenli olarak kontrol edilmeli; ezilmiş, kesilmiş, çatlamış, izolasyonu bozulmuş veya ısınma belirtisi bulunan kablolar derhal kullanım dışı bırakılmalıdır.\n6- Kabloların cihazların hareketli parçaları, tekerlekleri veya mekanik aksamı tarafından ezilmesi ve çekilmesi önlenmelidir.\n7- Birden fazla cihazın kablolarının tek noktada toplanması gereken durumlarda kablo yoğunluğu ve priz/elektrik tesisatının kapasitesi dikkate alınmalı; uygunsuz çoklu priz ve uzatma kablosu kullanımına izin verilmemelidir.\n8- Ameliyat öncesinde ve vardiya başlangıcında çalışma alanındaki kablo düzeni kontrol edilmeli, geçiş alanlarında bulunan kablolar derhal düzenlenmelidir.', 'İŞVEREN V. \n\nŞİRKET\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\n\n\nHERGÜN KONTROL', 1, 6, 7, 42, 'D', 'acik', '1- MYM sisteminden kayıt oluşturularak işlem yaptırılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: AMELİYATHANE', '1- Hareketli ekipmanların, hareket  sırasında çalışana çarpması', '1-Hareketli parçalarla temas sonucu iş kazaları', '1- Tüm ameliyathane çalışanları', '1- Tekerlekli hareketli ekipmanların tekerleklerinde kilit mekanizması mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1- Hareketli ekipmanların hareket güzergâhı boş bırakılmalı, ekipmanlar yalnızca yetkili/eğitimli çalışanlar tarafından hareket ettirilmelidir.\n2- Hareketli ekipman hareket ettirilmeden önce çevrede bulunan çalışanlar uyarılmalı ve hareket sırasında çarpma/sıkışma riski oluşturabilecek kişiler güvenli mesafede bulunmalıdır.\n3- Tekerlekli ekipmanlar kullanılmadığında uygun alanlarda park edilmeli ve tekerlek kilitleri devreye alınmalıdır.\n4- Cerrahi tepe lambası, cerrahi mikroskop vb. hareketli başlıklar uygun park pozisyonunda bırakılmalı; kilitleme/sabitleme mekanizmalarının sağlam ve çalışır durumda olduğu kontrol edilmelidir.\n5- Tabure, sandalye, sehpa, cihaz standı, taşıma arabası vb. ekipmanların; gövde, ayak, tekerlek, bağlantı noktaları, vida/somunları ve diğer mekanik aksamlarının sağlamlığı düzenli olarak kontrol edilmelidir.\n6- Üretici tarafından öngörülen bağlantı elemanlarından herhangi birinin eksik, gevşek, kırık veya hasarlı olması halinde geçici olarak dahi kullanılması engellenmeli; ekipman kesinlikle kullanılmamalı ve derhal kullanım dışı bırakılmalıdır.\n7- Ekipmanların bakım ve onarımları üretici talimatları doğrultusunda yapılmalı, yapılan bakım/onarım ve kontroller kayıt altına alınmalıdır.', 'İŞVEREN V. \n\nAMELİYATHANE ÇALIŞANLARI \n\nBİYOMEDİKAL TEKNİK SERVİSİ', '30.09.2027\n\nHERGÜN KONTROL\n\nPERİYODİK KONTROL', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: AMELİYATHANE', '1- Dezenfeksiyon odsında opa\'nın uygunsuz kullanımı', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması, meslek hastlaıkları oluşması', '1- Dezenfeksiyon odası çalışanları                                                                   2- Ameliyathane hemşireleri', '1- Dezenfeksiyon işlemi sadece yetkili çalışan tarafından yapılmaktadır.', 1, 0, 6, 3, 7, 126, 'C', '1-OPA\'nın yalnızca üretici kullanım talimatında belirtilen amaç, konsantrasyon, sıcaklık ve temas süresine uygun kullanılmalıdır.\n2- Kapaklı ve tanımlı kaplarda sadece yetkili çalışan tarafından kullanılmalıdır.\n3- Temas sırasında sıvı gecirmez önlük, TS EN ISO 374 standardında eldiven, sıçramaya karşı koruyucu gözlük ve tam yüz siperliği ve damlacık koruması amacıyla cerrahi maske, havalandırmanın yetersiz olduğu alanlarda FFP2/FFP3 maskeler  KKE olarak kullanılmalıdır.\n4- Kimyasal hazırlama ve kullanım alanlarında uygun havalandırma sistemleri kullanılmalı ve her zaman aktif olmalıdır.\nDökülme saçılma ve riskine karşı göz duşu , ilk yardım kiti ve dökülme kiti temin edilerek hazır bulundurulmalıdır.\n5-OPA\'dan alınan aletlerin durulanma işlemi sırasında zeminin ıslanmasını önlemek için emici ped serilmelidir.\n6- Her işlem sırasında KKD\'ler eksiksiz kullanılmalıdır. \n7-Mahalde \"YÜKSEK DÜZEY DEZENFEKSİYON TALİMATI\" asılı olmalı ve çalışanlar tarafından imzalı KKD zimmet formları birimde bulunması gereken İSG dosyasında arşivlenmelidir.', 'İŞVEREN V. \n\nDEZENFEKSİYON ODALARI ÇALIŞANLARI', '30.09.2027 \n\n              \nHERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: AMELİYATHANE', '1-Yetkisiz kişilerin tehlikeli kimyasal madde kullanılan odalara erişimi ve müdahale etmesi', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması, meslek hastlaıkları oluşması', '1- Dezenfeksiyon odası çalışanları                                                                   2- Ameliyathane hemşireleri', '1- Tehlikli kimyasallar için tanımlanmış çalışanlar mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1-Formaldehit ve OPA’ya erişim yetkisi olanç alışanlar bir yetki listesiyle belirlenmeli ve bu kişilerden başka kimse müdahale etmemelidir.  \n2- Odaların kapıları kapalı tutulmalı, numune teslimi için kontrollü erişim sistemi oluşturulmalıdır.\n3-Tehlikeli kimyasal kullanım alanına “Tehlikeli Kimyasal – Yetkisiz Giriş Yasaktır” ibaresi içeren görünür bir uyarı levhası asılmalıdır.  \n4- Temizlik, bakım ve teknik müdahale yapacak personelin işlem öncesinde ilgili kimyasallar ve gerekli KKD konusunda bilgilendirilmelidir.\n5-Kimyasal kullanılan odalarda kimyasalların açıkta ve yetkisiz kişilerin kolaylıkla ulaşabileceği şekilde bırakılmamalıdır.\n6- Kimyasal dökülmesi/sızıntısı halinde yalnızca eğitimli ve uygun KKD\'ye sahip personelin müdahale etmesini sağlayacak prosedür oluşturulmalıdır.\n7- Temizlik personeline özellikle kimyasalların birbirleriyle karıştırılmaması ve kimyasal döküntülere gelişigüzel müdahale edilmemesi konusunda eğitim verilmelidir.', 'İŞVEREN V. \n\nŞİRKET\n\nDEZENFEKSİYON ODALARI ÇALIŞANLARI', '30.09.2027 \n\n\n              \nHERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: AMELİYATHANE', '1-Hasta transferi esnasında Oksijen tüpünün sabitlenmeden, yatay pozisyonda taşınması', '1-Patlama ve Yangın                                                                                         2- Ekipman Hasarı                                                                                        3- İş kazaları', '1- Tüm çalışanlar', '1- Tekerlekli taşıma aparatı mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Oksijen tüplerinin hasta transferi sırasında tüp taşımaya uygun, devrilmeye karşı güvenli taşıma aparatı/arabası üzerinde ve dik konumda taşınmalıdır.\n2- Transfer öncesinde tüpün sabitliği, vana/regülatör bağlantısı, basıncı ve hortum bağlantılarının kontrol edilmelidir.                                                                                \n3- Tüp taşıma ekipmanlarının düzenli olarak kontrol edilmesi ve hasarlı/uygunsuz ekipmanların kullanım dışı bırakılmalıdır.\n4-Taşıma esnasında tüplerin başka cisimlere çarpması engellenmelidir. \n5- Transfer güzergâhlarında tüpün takılmasına veya çarpmasına neden olabilecek engellerin ortadan kaldırılmalıdır.\n6- Tüplerin vana kısmı korunacak şekilde taşınması ve tüpün taşınması sırasında vana/regülatörden tutulmamalıdır.', 'İŞVEREN V. \n\nHYYRT (TAŞIMA) HİZMETLERİ\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027 \n\nHERGÜN KONTROL\n              \nHERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', 'Mevcut risk devam etmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: AMELİYATHANE', '1- Anestezi cihazlarına gelen gaz hortumlarının dağınık durması', '1- Hortumların yıpranması sonucu gaz kaçakları                                               2- Takılma/ düşme kaynaklı iş kazaları', '1- Tüm ameliyathane çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Anestezi cihazlarına ait O₂, medikal hava, N₂O ve diğer bağlantı hortumlarının geçiş yollarına taşmayacak şekilde düzenlenmelidir.                                                  \n2- Hortumların cihaz üzerinde veya uygun sabitleme noktalarında mekanik olarak güvenli şekilde sabitlenmesini sağlayacak sistem oluşturulmalıdır.\n3- Hortumların birbirleriyle ve elektrik kablolarıyla karışmasını önlemek amacıyla ayrı güzergâh/kanal veya uygun hortum-kablo yönetim aparatı kullanılarak alan düzenlemesi yapılmalıdır.\n4- Hortumların keskin kenarlara, tekerlekli ekipmanlara ve sıkışma/ezilme noktalarına temas etmesinin önlenmelidir. \n5- Hortumların bağlantı noktalarında gevşeme, çatlak, deformasyon ve kaçak açısından periyodik görsel kontrol yapılmalı,  yıpranma/ deformasyon olan hortumlar değiştirilmeden kullanılmamalıdır.                                                                                                     6-Gaz hortumlarının periyodik bakımları yetkili personeller yarafından düzenli olarak yapılmalı ve kayıt altına alınmalıdır.', 'İŞVEREN V. \n\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\n\n\nHERGÜN KONTROL', 1, 6, 7, 42, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: AMELİYATHANE', '1-Pendant gaz sisteminin periyodik kontrollerinin yapılmaması', '1- Anestezik gazların (N₂O, desflorane, sevofluran vb.) ortama sızması                           2- Maruziyet riski', '1- Anestezi uzmanı                              2- Anestezi teknisyeni                          3- Hemşire                             4- Cerrahi ekip', '1- Atık gaz sistemi mevcut ve aktif durumdadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Çalışanlar pendant sistemi üzerinde gaz kaçağı (tıslama hava çıkış sesi vb.) tespit edilmesi durumunda hemen yetkililere haber vermeli, terminal çıkışı kapatılmalıdır.\n2- Kaçak olan pendant da tüm gazlar kesilmelidir. \n3- Gaz kaçağı olan alanda elektrikli hiç bir alet kullanılmamalı, ateş kıvılcım kaynağı bulundurulmamalıdır.                                                                       \n4-Gaz kaçak kaynağı (conta, hasarlı hortum, bağlantı eleamanlarında gevşeme ) tespit edilmelidir.                                                       \n 5- Arıza giderildikten sonra sızdırmazlık testi yapılmadan pendant aktif hale getirilmememlidir.                                                                                            \n6- Pendatların en az yılda bir kez mekanik, sızdırmazlık ve basınç testleri yapılmalıdır.\n7- Pendantın taşıma kapasitesi ile üzerine yerleştirilen cihaz/ekipmanların toplam ağırlığının uygunluğu değerlendirilmelidir.\n8- Pendant üzerinde sıvı malzeme istiflemesi yapılmamalıdır.', 'İŞVEREN V. \n\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\n\n\nHERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 1: AMELİYATHANE', 'Anestezi cihazındaki anestezik ajan vaporizatörlerinin dolumu sırasında dökülme, sıçrama,', '1- Çalışanların dolum esnasında kimyasal ajana maruz kalması                                                               2- İş kazaları', '1- Tüm ameliyathane çalışanları', '1- Dolum işlemi sırasında kullanılmak üzere uygun KKD\'ler (koruyucu eldiven, göz/yüz koruyucu vb.) alanda mevcut bulunmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1-Vaporizatörlerin dolumu ilgili cihaz ve anestezik ajanın üretici kullanım talimatlarına uygun şekilde gerçekleştirilmelidir.\n2- Dolum işlemi sırasında dökülme/sıçramayı azaltmak amacıyla üretici tarafından öngörülen dolum adaptörü/uygun dolum sistemi kullanılmalıdır.\n3- Dolum işlemi yalnızca eğitimli ve yetkilendirilmiş personel tarafından yapılmalıdır.\n4- Dolum bölgesinde açık kıvılcım/elektrikli ısıtıcı/cihaz bulundurmamalı, mümkünse dolum sırasında cihazin güç bağlantısı kesilmelidir. Güç bağlantısının kesilmesi mümkün olmadığı durumlarda vaporizatör ayarı \"0\" konumuna getirilmeden dolum kapağı açılmamalıdır.    \n 5- Dolum işlemi sırasında, ilgili ürünün Güvenlik Bilgi Formu (GBF/SDS) ve üretici talimatları doğrultusunda KKD (Eldiven, gözlük/yüz siperliği) kullanılmalıdır.\n6- Dökülme kiti, göz duşu temin edilerek alanda hazır bulundurulmalı ve kolay erişilebilir olmalıdır.\n7- Vaporizatör doldurulurken seviye göstergesi takip edilmeli ve fazla doldurulmalıdır.', 'İŞVEREN V. \n\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\n\n\nHERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 1: AMELİYATHANE', '1-Anestezi cihazında kullanılan sodalime (CO₂ absorbanı) ile kartuşun değiştirilmesi, boşaltılması veya dolumu sırasında çalışanın temas etmesi', '1- Cilt,göz, temasına bağlı yanık                                                    2-İş kazaları', '1- Tüm ameliyathane çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Sodalime değişimi anestezi cihazı ve sodalime üreticisinin kullanım talimatlarına uygun olarak gerçekleştirilmelidir.\n2- Anestezi cihazı içindeki CO₂ absorbanı değişimi sırasında ortamdaki taze hava akımı aktif çalışıyor olmalıdır.                                   \n3- Kartuş/absorban değişimi sırasında ürünün toz oluşturmasını artıracak hızlı boşaltma, çalkalama veya uygunsuz müdahalelerden kaçınılmalıdır.\n4- Sodalime\'ın su, nem ve üretici tarafından uyumsuz olarak belirtilen kimyasallarla temas etmesi önlenmelidir.\n5-Sodalime\'ın depolandığı ve kullanıldığı alanlara MSDS özeti asılmalı, \"Korozif Madde\" uyarı işaretleri bulunmalı ve uygun koşullarda muhafaza edilmesi sağlanmalıdır.                                                                                                                                      \n6- Dolum işi sırasında GBF/SDS\'si ve üretici talimatına göre KKD (EN 374 standardında eldiven, EN 149 standardında maske, EN166 standardında gözlük/siperlik, EN13795 standardında önlük) kullanılmalıdır.', 'İŞVEREN V. \n\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\n\n\nHERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 1: AMELİYATHANE', 'Yanık ameliyathanesinde skar revizyonu için Lynton marka Nd:YAG lazer cihazı kullanımı', '1- Lazer radyasyonu maruziyeti', '1- Yanık ameliyathanesi çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-Çalışan ve hasta için uygun dalga boyuna (1064 nm) uygun EN 207 standardında özel lazer gözlüğü kullanımı sağlanmalıdır.                                                                                                   2-Yansıtıcı yüzeyler lazer ışınının yayılımını engellemek için kaplanmalı veya uzaklaştırılmalıdır.                                            \n3-Lazer dumanına karşı vakum aktif olmalı işlem sırasındaFFP2/FFP3 maske kullanılmalıdır.                                                                                                                                        4-Cihaz kullanım sırasında cihaz başlığı çalışanın cildine temas ettirilmemelidir.                                                                                                             5-Oksijen kaynakları ve yanıcı maddeler lazerden uzakta tutulmalıdır.', 'İŞVEREN V. \n\nYANIK\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\n\n\nHERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM 1: AMELİYATHANE', '1- Ameliyathanelerde aynı anda birden fazla elektrikli tıbbi cihazın kullanılması ve cihazların elektriksel yüklerinin uygun şekilde yönetilmemesi', '1- Elektrik kaçağı                                            2- Sıvı teması, uygunsuz kullanım sonrasında elektrik çarpması                                                  3- Yangın', '1- Tüm ameliyathane çalışanları', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Ameliyathanede kullanılan elektrikli cihazların gövde topraklama ölçümleri yapılmalıdır.                                                                                                                                                       2-Kablo, fiş ve prizlerin düzenli görsel kontrollerinin yapılmalı izolasyon bozukluğu,  kablo hasarı bulunanlar kullanılmamalıdır.                                                                                                                        3- Islak hacim olan alanlarda kullanım sırasında sıvı teması  önlenmelidir.                                                                                                                                        4-Ameliyathanede kullanılan elektrikli tıbbi cihazların  periyodik bakım, elektriksel güvenlik testleri en az 6 ayda bir yapılmalıdır.\n5- Tıbbi cihazların mümkün olduğunca sabit ve uygun kapasitedeki prizlerden beslenmesi sağlanmalıdır.\n6- Çoklu priz ve uygunsuz uzatma kablosu kullanımından kaçınılmalı, zorunlu durumlarda yalnızca teknik olarak uygun ve onaylanmış ekipman kullanılmalıdır.\n7- Elektrik tesisatı ve tıbbi cihazlara ilişkin periyodik kontrol/bakım kayıtları düzenli olarak takip edilmelidir.', 'İŞVEREN V. \n\nBİYOMEDİKAL/ DİĞER TIBBİ EKİPMAN HİZMETLERİ\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\n\n\n\n\n\nHERGÜN KONTROL', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM 1: AMELİYATHANE', '1-Ameliyat sırasında kesici-delici aletlerin (bistüri, sütur iğnesi, enjektör vb.) uygunsuz kullanılması, elden ele verilmesi veya güvenli şekilde bırakılmaması', '1- Bulaşıcı hastalıklar                               2- Enfeksiyon                                                        3- İş kazaları', '1- Tüm Ameliyathane çalışanları', '1- Her ameliyat odasında yeterli sayıda sharp box bulunmaktadır.', 1, 0, 6, 6, 3, 108, 'C', '1- Bistüri, sütur iğnesi, enjektör ve diğer kesici-delici aletlerin kullanım amacı dışında kullanılmaması sağlanmalıdır.\n2- Kesici-delici aletlerin mümkün olduğunca elden ele verilmesi yerine güvenli transfer yöntemi kullanılmalıdır.\n3- Kullanılmış bistüri ve iğnelerin çalışma alanında kontrolsüz veya geçici olarak bırakılması önlenmelidir.\n4- Kullanılmış iğne, bistüri vb. atıklar, kapakları kapatılmadan delinmeye dayanıklı, kapaklı kesici delici alet kutularına atılmalıdır.\n5- Atık kutularının 2/3 doluluk oranına ulaştığında kapatılmalı ve değiştirilmelidir. \n6- Kesici delici alet  yaralanmaları ile kan ve vücut sıvıları sıçramasına maruz kalma olay sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkik  takipleri yaptırmalıdır.', 'İŞVEREN V.\n\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\nHERGÜN KONTROL', 3, 3, 3, 27, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 27, 'BÖLÜM 1: AMELİYATHANE', '1- Ameliyat sırasında lazer, elektrokoter ve benzeri enerji temelli cerrahi cihazların kullanımı sonucu cerrahi duman oluşması ve çalışanların cerrahi dumana maruz kalması', '1- Dumanların solunması sonucu meslek hastalıkları meydana gelmesi', '1- Tüm ameliyathane çalışanları', '1- Vakum sistemi mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1- Cerrahi dumanın oluştuğu noktaya mümkün olduğunca yakın lokal duman emiş sistemi bulunmalı ve tüm ameliyathanelerde aktif olarak kullanılmalıdır.          \n2- Emiş başlığı/ucu, dumanın oluştuğu bölgeye yeterli yakınlıkta konumlandırılmalıdır.Hortum ve bağlantılarda kaçak, tıkanıklık veya deformasyon bulunmamalıdır.\n3- N95 veya FFP2/FFP3 maske kullanılmalıdır.\n4- Ameliyathane genel havalandırmasının cerrahi dumanın kontrolünde lokal emiş sisteminin yerine kullanılmaması, destekleyici bir kontrol olarak değerlendirilmesi gerekir.        \n5- Vakum sisteminin periyodik kontrolü düzenli olarak yapılmalıdır.    \n6- Lazer/elektrokoter kullanılan ameliyatlarda cerrahi duman kontrolüne ilişkin kurum prosedürü oluşturulmalıdır.', 'İŞVEREN V.\n\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\nHERGÜN KONTROL', 3, 3, 3, 27, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 28, 'BÖLÜM 1: AMELİYATHANE', '1- Ameliyat esnasında uzun süre aynı postürde durmak \n2- Uzun süre ayakta çalışılması', '1- Kas iskelet sistemi hastalıkları', '1-Tüm Ameliyathane çalışanları', '1- Ergonomik olarak ayarlanabilir ekipmanlar mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1- Ayarlanabilir ameliyat masası ve cerrahi mikroskoplar, monitörler  alet tepsileri operatörün ergonomisine göre ayarlanabilir olmalı ve ayarlama mekanizmaları çalışır durumda olmalıdır.                                                                                           \n2- Uzun süren operasyonlarda ekip rotasyonu yapılmalıdır.\n3- Çalışanlar 45 dakikalık periyotlarla oturarak dinlenmelidirler. \n4- Çalışanlar ortopedik tabanlı iş ayakkabısı giymeli, eksik malzemeler temin edilmelidir.', 'İŞVEREN V.\n\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\n\n\nHERGÜN KONTROL', 3, 6, 3, 54, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 29, 'BÖLÜM 1: AMELİYATHANE', '1- Acil kaçış ve yönlendirme levhalarının kaçış güzergâhını doğru göstermemesi, yanlış yönlendirmesi veya acil çıkış olarak gösterilen kapıların  uygun olmaması ve sürekli kilitli olması', '1- Acil durumlarda tahliye gecikmesi', '1- Tüm ameliyathane çalışanları', '1- Ameliyathane içerisinde acil çıkış levhaları mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1- Acil çıkış olarak gösterilen kapıların kaçış sırasında kullanılabilir durumda ve erişilebilir olması sağlanmalıdır.\n2-Acil çıkış kapılarının önünde malzeme, ekipman veya depolama yapılması önlenmelidir.\n3- Acil yönlendirme levhalarının görüş alanını engelleyen ekipman, dekorasyon veya tabela bulunmaması sağlanmalıdır.\n4- Acil Çıkış Levhaları, Kaçış yönlendirmesinin ulaştığı kapının kilitli, erişilemez veya kaçış için uygun olmadığının tespit edilmesi halinde; kapı ve güzergâhın kendisi de uygun hale getirilmelidir.                                                                                                                                                                                               \n5- Acil çıkış kapıları kapalı tutulmalı, manyetik tutucuları sürekli çalışır durumda olmalıdır.', 'İŞVEREN V.\n\nŞİRKET\n\nBİNA ARAZİ HİZMETLERİ\n\nBİRİM SORUMLUSU', '30.09.2027\n\n\n30.09.2027\n\n\nHERGÜN KONTROL', 1, 2, 15, 30, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 30, 'BÖLÜM 1: AMELİYATHANE', '1- Gaz manometrelerin bulunduğu panonun dijital göstergelerinin çalışmaması', '1- Gaz kaçakları sonucu iş kazaları                  2- Meslek hastalıkları', '1- Tüm ameliyathane çalışanları', NULL, 1, 0, 3, 2, 15, 90, 'C', '1-Medikal gaz sistemlerinin basınç değerleri ve alarm sistemleri düzenli olarak takip edilmelidir.\n2- Basınç değerlerinin normal çalışma aralıkları pano üzerinde görünür şekilde belirtilmelidir.\n3- Gaz manometrelerinin üzerinde basınç manometreleri bulunmalı, aktif ve çalır durumda olmalıdır.                                                                                                                                                                                              4- Gaz manometrelerinde yaşanacak arızalar için ışıklı, sesli sinyal sistemi bulundurulmalı ve arıza derhal yetkili personellerce onarılmalıdır.\n5- Medikal gaz panolarının yetkisiz kişilerce müdahale edilmesi önlenmelidir.\n6- Gösterge ve alarm sistemlerinin periyodik kontrol, bakım ve test kayıtları tutulmalıdır.', 'İŞVEREN V.\n\nŞİRKET\n\nBİYOMEDİKAL/ DİĞER TOBBİ EKİPMAN HİZMETLERİ', '30.09.2027   \n\n30.09.2027\n\n30.09.2027', 1, 2, 15, 30, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 31, 'BÖLÜM 1: AMELİYATHANE', '1- Radyasyon koruma önlemleri bulunmayan ameliyathane odalarında skopi kullanılması', '1- Radyasyon maruziyeti                                                2- Meslek hastalığı', '1- Tüm ameliyathane çalışanları', '1- 4,7,12,13,14,30 numaralı odaların kurşun kaplaması mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1-C-kollu skopi cihazı kullanımı, yapısal radyasyon zırhlaması bulunan ameliyathane odalarında gerçekleştirilmelidir. \n2-Projeye göre skopi kullanımı uygun olmayan alanlarda zorunlu kullanım durumlarında geçici radyasyon koruma önlemleri (Kurşun paravan, vb) alınmalıdır. \n3-Radyasyon Güvenliği Komitesi tarafından 6 ayda bir saha ölçümleri ve denetimi yapılarak zırhlama yeterliliği doğrulanmalıdır.                                                   3-Doz ölçüm sonuçlarına göre uygun bulunmayan odalarda skopili işlemler, yapısal radyasyon zırhlaması uygun ameliyathanelere taşınmalı veya gerekli yapısal iyileştirmeler planlanmalıdır.                                                                                                   \n4-Skopi cihazlarının en az yılda bik kez periyodik bakım, kalibrasyon ve radyasyon sızıntı ölçümleri yapılmalıdır.                                                                                                        5-Skopi kullanılan alanlarda görev yapan tüm personele kişisel dozimetre temini ve doz takibi yapılmalıdır. Kurşun önlük, tiroid koruyucu, kurşun gözlük, vb kişisel koruyucu donanımları eksiksiz olarak kullanımı düzenli olarak denetlenmesi ve kayıt altına alınması sağlanmalıdır.', 'İŞVEREN V. (EKİPMAN TEMİNİ)                         \n\n\nRADYASYON GÜVENLİĞİ KOMİTESİ  \n\nBİRİM SORUMLUSU', '30.09.2027', 1, 2, 15, 30, 'D', 'acik', 'TÜRKİYE ATOM ENERJİSİ KURUMU TIBBİ RADYOLOJİ UYGULAMALARININ YAPILDIĞIODALARIN TASARIMINDA DİKKAT EDİLECEK HUSUSLARA VE ZIRHLAMA KOŞULLARINA İLİŞKİN KILAVUZ MADDE 5.3S', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 32, 'BÖLÜM 1: AMELİYATHANE', '1- Anjio cihazı hareket ederken çalışana ve ekipmana çarpması', '1- iş kazaları                                              2-ekipman hasarı', '1- Tüm anjio birimi çalışanları', NULL, 1, 0, 6, 2, 7, 84, 'C', '1- Anjiyo cihazının hareket alanı ve dönüş/seyir güzergâhı belirlenerek zemin işaretlemesi yapılmalıdır.\n2- Cihazın hareket alanı içerisinde personel, sedye, masa, monitör, serum askısı, kablo ve diğer ekipmanların bulundurulması önlenmelidir.\n3- Cihaz hareket ettirilmeden önce operatör tarafından 360° görsel kontrol yapılmalıdır.\n4- Cihaz hareketi sırasında ilgili personelin “cihaz hareket ediyor” uyarısı vermesi ve çevredeki personelin güvenli konuma geçmesi sağlanmalıdır.\n5-Hareketli parçalar ile sabit ekipmanlar arasında güvenli mesafe oluşturulmalı, mümkün olduğunca cihaz çevresinde gereksiz ekipman bulundurulmamalıdır.\n6- Cihazın hareketini engelleyen veya görüşü kapatan kablolar düzenlenmeli, kablo yönetimi sağlanmalıdır.\n7-Cihazın hareket ettirilmesi sırasında gerektiğinde tek bir sorumlu personel tarafından yönlendirme yapılmalı, birden fazla kişinin farklı yönlendirme yapması önlenmelidir.', 'İŞVEREN V.\n\nBİYOMEDİKAL/ TEKNİK HİZMETLER\n\nBİRİM SORUMLUSU', 'SÜREKLİ KONTROL', 2, 2, 4, 16, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 33, 'BÖLÜM 1: AMELİYATHANE', '1- Sıvı azotun vücut ile temas etmesi', '1- Dokularda donma ve nekroz riski                             2- İş kazaları meydana gelmesi', '1- Tüp bebek merkezi çalışanları', NULL, 1, 0, 3, 3, 7, 63, 'D', '1- Kullanım sırasında izolasyonlu EN 511 standardına uygun kriyojenik eldiven, kriyojenik önlük, kriyojenik ayak koruyucuve yüz siperliği kullanılmalıdır. Eksik KKD\'ler temin edilmelidir.                                                                             \n2- KKD\'ler, zimmet formu ile çalışana zimmetlenmeli ve çalışanlar tarafından da eksiksiz kullanılmalıdır.\n3- Sıvı azot depolama kapları düzenli olarak kontrol edilmeli; hasarlı, uygunsuz veya emniyetsiz kaplar kullanılmamalıdır.\n4- Kriyojenik kaplar yalnızca üretici tarafından belirtilen şekilde taşınmalı; kapların devrilmesini önleyecek sabitleme tedbirleri alınmalıdır.\n5-Sıvı azot bulunan alanlarda yeterli havalandırma sağlanmalıdır.\n6- Kapalı alanlarda oksijen seviyesinin düşmesine karşı gerekli görülmesi halinde oksijen eksikliği alarm ve izleme sistemi kurulmalıdır.\n7- Sıvı azotun bulunduğu alanlara “Kriyojenik Madde – Sıvı Azot – Donma/Yanık Riski” uyarı levhaları yerleştirilmelidir.\n8- Sıvı azotun güvenlik bilgi formu (GBF/SDS) çalışma alanında erişilebilir bulundurulmalıdır.', 'İŞVEREN V. \n(KKD TEMİNİ)\n\n\nTÜP BEBEK MERKEZİ ÇALIŞANLARI', '30.09.2027\n\n\n                             HERGÜN KONTROL', 3, 1, 7, 21, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 34, 'BÖLÜM 1: AMELİYATHANE', '1- Hastalara pozisyon verilmesi/ sedyeye aktarılması, sedye ile taşınması sırasında gelişebilecek durumlar', '1- Kas-iskelet sistemi yaralanmaları                      2- Sedye-ekipman çarpması sonucu fiziksel yaralanma, 3- Meslek hastalığı', '1- Anestezi teknikerleri                        2- Ameliyathane Teknikerleri (klinik destek )                3- Taşıma personelleri', '1- Sezeryan ameliyathanesinde Hasta Transfer Sistemi (Rollboard) kullanılmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1- Hastanın bilinci, kilosu ve durumu göz önünde bulundurularak uygun taşıma yöntemi seçilmelidir. Yardımcı ekipmanların (kayar çarşaf, transfer tahtası, hasta kaldırma lifti vb.) kullanımının teşvik edilmelidir.                                                                                                   2- Hastayı sedyeden işi  en az üç çalışan tarafından yapılmalı ve çalışanlar arasında iletişim ve koordinasyon sağlanmalıdır.                                                                                     3- Sedyelerin ve transfer ekipmanlarının (fren, emniyet kemeri, tekerlek durumu vb.) periyodik kontrollerinin yapılmalıdır.                                                                             4- Aktarma işinden önce ameliyat masası ve sedyenin transfer öncesinde frenlerinin kilitli olduğu kontrol edilmelidir.\n5- Sedye ve ameliyat masasının yükseklikleri mümkün olduğunca eşitlenerek hasta transferi gerçekleştirilmelidir.\n6- Hasta transferi ve pozisyonlandırma işlemleri için yazılı hasta transfer ve pozisyonlandırma prosedürü oluşturulmalıdır.', 'İŞVEREN V. \n\nBİRİM SORUMLUSU\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n                        HERGÜN KONTROL\n\nHERGÜN KONTROL', 1, 3, 7, 21, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 35, 'BÖLÜM 1: AMELİYATHANE', '1- Cerrahi dermatom cihazı kullanımı', '1- Kesici- delici alet yaralanması riski', '1- Yanık, El Cerrahisi ve Plastik Cerrahi Ameliyathanesi Çalışanları', NULL, 1, 0, 3, 3, 7, 63, 'D', '1- Dermatom cihazı yalnızca eğitim almış ve yetkilendirilmiş çalışanlar tarafından kullanılmalıdır.\n2- Kullanım öncesinde cihazın, bıçağın, bıçak bağlantısının ve koruyucu parçaların fiziksel bütünlüğü ve güvenli şekilde sabitlendiği kontrol edilmelidir.\n3- Cihaz çalıştırılmadan önce bıçağın çevresinde el, parmak veya başka bir çalışanın bulunmadığından emin olunmalıdır.\n4- Cihazın kesici kısmı takılmadan önce güç kaynağı bağlantısı kesilmiş olmalıdır. \n5- Bıçak değişimi, çıkarılması, temizliği ve bakımında cihazın enerjisi tamamen kesilmeli ve üretici talimatlarına uygun işlem yapılmalıdır.\n6- Cihaz çalışırken operasyon bölgesine elle müdahale edilmemelidir.                                                                                                                                                               7-KKD\'ler  (eldiven,önlük, koruyucu gözlük) kullanılmalıdır.', 'İŞVEREN V. \n\nBİRİM SORUMLUSU\n\nAMELİYATHANE ÇALIŞANLARI', 'SÜREKLİ KONTROL', 1, 2, 7, 14, 'E', 'acik', '1- Tıbbi cihazların bakım ve kalibrasyonları yapılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 36, 'BÖLÜM 1: AMELİYATHANE', '1- Steril set alırken elle kaldırma işlerinin yapılması', '1- Kas–iskelet sistemi rahatsızlıkları                                   2- İş kazları', '1-Ameliyathane hemşireleri', '1- Raflı set arabaları mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Steril setlerin taşınması için taşıma arabaları kullanılmalıdır.                                                                                                      2- Raf yükseklikleri ergonomik olarak düzenlenmeli, diz altı ve omuz üstü raflara ağır set konulmamalıdır.                                                                                                              3-Depo ve steril alan zeminlerinin düz, kaymaz ve engelsiz hale getirilmelidir.                                                                                                               4- Ağır veya hacimli steril setlerin iki kişiyle taşınmalıdır.', 'İŞVEREN V. \n\nAMELİYATHANE ÇALIŞANLARI', 'SÜREKLİ KONTROL', 1, 1, 7, 7, 'E', 'acik', '1 İŞ KAZASI YAŞANMIŞTIR. ALAN FİRMA UHDESİNDE OLDUĞU İÇİN YETKİSİZ ERİŞİM KISITLANMIŞTIR.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 37, 'BÖLÜM 1: AMELİYATHANE', '1- Elektrokoter cihazının kullanımı sırasında aktif elektrotun çalışana temas etmesi veya enerji iletiminin kontrolsüz şekilde gerçekleşmesi', '1- Elektrik çarpması  sonucu yaralanma                               2- Yanık oluşması', '1- Cerrahi branş hekimleri, ameliyathane hemşireleri ve klinik destek elemanları', '1-30 MA kaçak akım rölelelri mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1- Elektrokoter cihazı yalnızca eğitimli ve yetkilendirilmiş sağlık çalışanları tarafından kullanılmalıdır.\n2- Aktif elektrot kullanım sırasında çalışanların temas edebileceği alanlardan uzak tutulmalı, kullanılmadığı zaman güvenli bir taşıyıcı/izole tutucu üzerinde bulundurulmalıdır.\n3- Aktif elektrot örtü, örtü altı veya çalışanların ulaşabileceği kontrolsüz alanlara bırakılmamalıdır.\n4- Elektrokoter kablosu ve bağlantıları; ezilme, kesilme, izolasyon hasarı ve uygunsuz bağlantı açısından kullanım öncesinde kontrol edilmelidir.\n5- Hasta üzerinde kullanılan nötr/return elektrotun uygun şekilde yerleştirilmesi ve bütünlüğünün kontrol edilmesi sağlanmalıdır.\n6- Aktif elektrot, kablo ve diğer aksesuarlar üretici talimatlarına uygun kullanılmalı; uyumsuz veya hasarlı aksesuar kullanılmamalıdır.\n7- Ameliyat masası ve zeminin kuru tutulması, sıvı temasının önlenmelidir.', 'İŞVEREN V. \n\nAMELİYATHANE ÇALIŞANLARI', 'SÜREKLİ KONTROL', 1, 6, 3, 18, 'E', 'acik', '1- Tıbbi cihazların bakım ve kalibrasyonları yapılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 38, 'BÖLÜM 1: AMELİYATHANE', '1-Ameliyathanelerde oluşan atıkların kaynağında uygun atık türüne göre ayrıştırılmaması ve yanlış atık grubuna atılması', '1- Enfeksiyon riski                      2-iş kazası                                         3- çevre kirliliği', '1- Tüm Ameliyathane Çalışanları                                                                         2- Atık depo personelleri', '1- Uygun renklerde atık kutuları mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1- Tüm atıklar kaynağında ayrı kaplarda toplanmalıdır: Kırmızı: Tıbbi atık, Sarı kutu: Kesici–delici atık, Mavi: Geri dönüştürülebilir ambalaj atığı, Siyah: Evsel atık \n2- Ameliyathanelerde oluşabilecek atık türleri belirlenerek kaynağında ayrı toplanması sağlanmalıdır.\n3- Kesici-delici atık kapları delinmeye dayanıklı, sızdırmaz, uygun hacimde ve devrilmeye karşı güvenli şekilde konumlandırılmalıdır.\n4- Atık kaplarının aşırı doldurulması önlenmeli; özellikle kesici-delici atık kapları üretici/kurum tarafından belirlenen doluluk seviyesine ulaşmadan kapatılıp değiştirilmelidir.\n5- Atık toplama sırasında el ile bastırma, sıkıştırma veya atığın yeniden ayrıştırılması gibi çalışanı maruziyete sokabilecek uygulamalar önlenmelidir.\n6- Atık kutularının renk ve etiket kontrolü ve tanımlaması periyodik olarak yapılmalıdır.', 'İŞVEREN V. \n\nAMELİYATHANE ÇALIŞANLARI \n\nTEMİZLİK HİZMETLERİ', 'SÜREKLİ KONTROL', 1, 6, 3, 18, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 39, 'BÖLÜM 1: AMELİYATHANE', '1-Kullanılmış kesici-delici aletlerin (iğne, bistüri, sütur iğnesi vb.) yatak, çarşaf, örtü veya benzeri yüzeyler üzerinde bırakılması ya da bu yüzeylere saplanarak gizli şekilde kalması', '1-Biyolojik maruziyet                                                   2-Enfeksiyon riski                                                3-İğne batması kaynaklı iş kazaları', '1- Tüm ameliyathane çalışanları, çamaşırhane personelleri', NULL, 1, 0, 3, 6, 3, 54, 'D', '1- Kullanılmış kesici-delici aletler kullanım sonrasında bekletilmeden, kullanım noktasına en yakın kesici-delici atık kutusuna atılmalıdır.\n2- Kesici-delici aletlerin yatak, çarşaf, örtü, ameliyat masası veya diğer yüzeylere bırakılması kesinlikle önlenmelidir.\n3- Kesici-delici atık kutuları, işlem sırasında çalışanın kolay ve güvenli şekilde ulaşabileceği uygun konumda bulundurulmalıdır.\n4- Kullanım sırasında mümkün olduğunca güvenlik mekanizmalı kesici-delici ekipmanlar tercih edilmelidir.                                   \n5- Kullanım sonrası iğneler iğne ucu kapatılmadan derhal kutusuna atılmalı, derhal atılmasının mümkün olmadığı koşullarda delinmez bir kapta biriktirilerek her ameliyat sonrasında bertaraf edilmelidir.                                                                                            6- Atık ayrıştırılması ve kesici-delici alet yaralanması ile ilgili en az yılda bir hizmet içi eğitim verilmelidir.', 'İŞVEREN V. \n\nAMELİYATHANE ÇALIŞANLARI \n\nTEMİZLİK HİZMETLERİ', 'SÜREKLİ KONTROL', 1, 6, 3, 18, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 40, 'BÖLÜM 1: AMELİYATHANE', '1- Ameliyat masalarında meydana gelen mekanik, elektriksel, hidrolik/elektromekanik veya kumanda sistemi arızaları nedeniyle masanın kontrolsüz hareket etmesi, pozisyonunu koruyamaması veya kullanım sırasında işlevini kaybetmesi', '1- Elektrik arızaları                                                                  2- Ekipman hasarı                                                           3- İş kazası', '1-Tüm ameliyathane çalışanları', '1- Topraklama ölçümleri yapılmıştır.', 1, 0, 3, 6, 3, 54, 'D', '1- Masa hareket mekanizmaları, kilitleme/fren sistemleri, kumanda paneli, elektrik bağlantıları ve diğer hareketli bileşenler düzenli olarak kontrol edilmelidir.\n2- Kullanım öncesinde masa yüksekliği, eğim, pozisyonlandırma, fren ve hareket mekanizmalarının çalışırlığı kontrol edilmelidir.\n3- Çalışanların masa üzerinde tespit ettikleri arızaları bildirebilecekleri etkin bir arıza bildirim ve takip sistemi oluşturulmalıdır.\n4- Arızalı veya güvenli çalışmadığı değerlendirilen ameliyat masası kullanımdan derhal çıkarılmalı ve uygun şekilde işaretlenmelidir.\n5- Arızalı ekipmanın yeniden kullanıma alınması, teknik servis tarafından yapılan kontrol ve uygunluk onayı sonrasında gerçekleştirilmelidir.\n6- Mekanik, hidrolik ve elektrik sistemlerinin aylık, 6aylık düzenli kontrolü yapılmalı ve kayıt altına alınmalıdır.                                                                             \n7- Gövde topraklama ölçümleri yapılmalıdır.', 'İŞVEREN V. \n\nAMELİYATHANE ÇALIŞANLARI \n\nTEMİZLİK HİZMETLERİ', 'SÜREKLİ KONTROL', 1, 6, 3, 18, 'E', 'acik', '1- Tıbbi cihazların bakım ve kalibrasyonları yapılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 41, 'BÖLÜM 1: AMELİYATHANE', '1- Cerrahi testere kullanımı sırasında oluşan titreşimin çalışan tarafından el ve kol üzerinden alınması ve tekrarlayan/uzun süreli titreşim maruziyeti', '1- El-kol titreşimi maruziyeti sonucu meslek hastalıkları\n2- İş kazaları', '1- Cerrahi ekip', NULL, 1, 0, 3, 6, 3, 54, 'D', '1- Cihaz kaynaklı maruziyet ölçümleri (el-kol titreşimi,gürültü) yapılmalıdır.\n2- Cerrahi testerelerin üretici tarafından belirtilen titreşim emisyon değerleri takip edilmelidir.                                                                                                                                        3- Cihaz kullanılırken eldivenler kuru olmalı, cihaz elde sıkı tutulmalı, cihaz aktif durumdayken yön değiştirilmemelidir.Cihazın sap kısmı titreşim sönümleyici malzeme ile kaplanmalıdır.                                                                                                \n4- Batarya değişimi vb. işler için cihaz güç kaynağından ayrılmalı ve bıçak tamamen durduktan sonra müdahale edilmelidir.', 'İŞVEREN V. \n\nAMELİYATHANE ÇALIŞANLARI', 'SÜREKLİ KONTROL', 1, 6, 3, 18, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 42, 'BÖLÜM 1: AMELİYATHANE', '1- Tıbbi cihaz jaklarının takılması, çıkarılması veya aktarılması sırasında basınçlı gazın ani boşalmasına bağlı olarak jak, hortum veya bağlantı ekipmanının kontrolsüz şekilde geri tepmesi', '1- Basınç yaralanması kaynaklı iş kazaları', '1- Tüm ameliyathane çalışanları', NULL, 1, 0, 3, 6, 3, 54, 'D', '1- Jakların takılması ve çıkarılması işlemleri üretici talimatlarına uygun yalnızca yetkili ve eğitimli personelin müdahale etmesi sağlanmalıdır.                                                                                                         2- Jak, soket ve hortumlarda hasar, deformasyon, gevşeklik ve kaçak kontrolü yapılmalıdır.                                 \n3- Jaklar takılırken veya çıkarılırken çalışanların yüz ve gözlerini bağlantı noktasına doğrudan yaklaştırmaması sağlanmalıdır.\n4- Bağlantı sökülmeden önce ilgili sistemin basınç durumu kontrol edilmeli ve gerekli ise hat basıncı güvenli şekilde boşaltılmalıdır.                                                                                                5- Medikal gaz sistemleri ve bağlantı elemanlarının bakım/teknik kontrolleri yetkili teknik personel tarafından yapılmalıdır.', 'İŞVEREN V. \n\nBİYOMEDİKAL/ DİĞER TIBBİ EKİPMAN HİZMETLERİ\n\nAMELİYATHANE ÇALIŞANLARI', 'SÜREKLİ KONTROL', 1, 3, 3, 9, 'E', 'acik', '1- Tıbbi cihazların bakım ve kalibrasyonları yapılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 43, 'BÖLÜM 1: AMELİYATHANE', '1- Hasta taşınmasında kullanılan sedyelerin tekerlek, fren sistemi, yan koruma bariyerleri, kilitleme mekanizmaları ve diğer güvenlik ekipmanlarının olmaması', '1- Hasta transferi sırasında yaralanmalar', '1- Tüm ameliyathane çalışanları', '1- Tüm sedyelerin fren mekanizması ve yan koruma bariyerleri mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Tüm sedyeler için kullanım öncesi/günlük kontrol listesi (Tekerleklerin serbest ve düzgün hareketi,\nFren/merkezi kilit sisteminin çalışması,\nYan koruma bariyerlerinin açılma-kapanma ve kilitlenme fonksiyonu,vb.) oluşturulmalıdır.\n2- Özellikle yan koruma bariyerlerinin kilitlenme mekanizmasının kullanım öncesinde kontrol edilmesi sağlanmalıdır.\n3- Kontrolü gerçekleştiren personel ve kontrol sonucu kayıt altına alınmalıdır.\n4- Fren, tekerlek, yan bariyer veya başka bir güvenlik ekipmanında uygunsuzluk tespit edilmesi halinde sedye derhal kullanım dışı bırakılmalı ve “ARIZALI/KULLANMAYIN” şeklinde işaretlenmelidir.\n5-Sedye kullanıcılarına güvenli kullanım, frenlerin kullanılması, yan bariyerlerin doğru konumlandırılması ve arıza durumunda yapılacak işlemler konusunda talep açılarak arızaların giderilmesi sağlanmalıdır.\n6- Periyodik bakım ve teknik kontroller üretici talimatlarına uygun olarak gerçekleştirilmelidir.', 'İŞVEREN V. \n\nBİYOMEDİKAL/ DİĞER TIBBİ EKİPMAN HİZMETLERİ\n\nHYYRT(TAŞIMA) HİZMETLERİ\n\nAMELİYATHANE ÇALIŞANLARI', '30.09.2027\n\nHERGÜN KONTROL', 1, 3, 7, 21, 'D', 'acik', '1- ŞİRKET tarafından belirli aralıklarla sedyelerin periyodik muayeneleri yaptırılmaktadır.                                                                                                                                        2- Kilit sistemleri veya sedyede herhangi bir arıza meydana gelirse kullanım dışı bırakılmakta, onarımı yaptırılmadan kullanılmamaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 44, 'BÖLÜM 1: AMELİYATHANE', '1- Ameliyathanede bulunan serum ısıtma kabinlerinin +80 °C\'ye kadar ısıtma yapması nedeniyle cihazın sıcak yüzeylerine veya ısıtılmış malzemelere temas sonucu çalışanların termal yanığa maruz kalması', '1- Sıcak yüzeylere temas sonucu ısı yanıkları meydana gelmesi', '1-Tüm ameliyathane çalışanları', NULL, 1, 0, 3, 3, 6, 54, 'D', '1- Serum ısıtma kabini üretici kullanım talimatında belirtilen sıcaklık ve kullanım koşullarına uygun kullanılmalıdır.\n2- Cihazın ısı ayarları ve termostatı düzenli olarak biyomedikal birimi tarafından kontrol edilmeli, dolap iç sıcaklığının alanda yetkili çalışan tarafından günlük kayıt altına alınmalıdir.   \n3- Cihaz üzerine “DİKKAT – SICAK YÜZEY / YANIK RİSKİ” uyarısı konulmalıdır.\n4- Isıtılmış serum/kapların alınması sırasında;dolap iç yüzeyleri ve metal raflar temas etmeden önce EN 407 belgeli uygun ısıya dayanıklı KKD kullanılmalıdır.                                                                                                                 5- Termostat, sıcaklık göstergesi ve varsa aşırı sıcaklığı önleyici güvenlik sistemleri düzenli kontrol edilmelidir.                                                                                                                                                                                                                                            6- Yüksek ısıda deformasyon riski nedeniyle latex veya vinil eldiven kullanılmamalıdır.\n7- Cihazın periyodik bakım ve teknik kontrolleri yapılmalı ve kayıt altına alınmalıdır.', 'İŞVEREN V. \n\nAMELİYATHANE ÇALIŞANLARI', 'SÜREKLİ KONTROL', 1, 3, 6, 18, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 45, 'BÖLÜM 1: AMELİYATHANE', '1- Yenidoğan radyan ısıtıcı ünitesinin kontrolsüz, amacı dışında veya üretici talimatlarına uygun olmayan şekilde kullanılması', '1- Ciltte, gözde tahriş                                                      2- Yanık riski', '1- Yenidoğan ekibi                                          2- Anestezi ekibi', NULL, 1, 0, 3, 6, 3, 54, 'D', '1- Radyan ısıtıcı yalnızca eğitimli ve yetkilendirilmiş sağlık çalışanları tarafından kullanılmalıdır.\n2- Kullanım öncesinde cihazın sıcaklık ayarı, sensörleri, alarm sistemleri ve kontrol paneli kontrol edilmelidir.\n3- Cihazın radyant ısıtıcı kısmına çıplak elle temas edilmemelidir, uzun süre açık bırakılmamalıdır.                                                                            \n4- Cihazın çevresinde ısı kaynaklarıyla temas edebilecek yanıcı malzeme ve ekipman bulundurulmamalıdır.\n5- Cihazların bakım, kalibrasyon ve teknik kontrolleri üretici önerileri doğrultusunda yetkili teknik/biyomedikal birim tarafından yapılmalıdır.', 'İŞVEREN V. \n\nBİYOMEDİKAL/ DİĞER TIBBİ EKİPMAN HİZMETLERİ\n\nAMELİYATHANE/ DOĞUMHANE ÇALIŞANLARI', 'SÜREKLİ KONTROL', 1, 3, 3, 9, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 46, 'BÖLÜM 1: AMELİYATHANE', '1- Tüp Bebek Merkezi\'nde sıvı azotun depolanması, dolumu, transferi veya kullanımı sırasında kaçak/dökülme sonucu azot gazının ortama yayılması ve oksijen konsantrasyonunun azalmasına bağlı çalışanların oksijen yetersizliğine maruz kalması', '1- Baş dönmesi                                                   2-Bilinç kaybı', '1- Tüp bebek merkezi çalışanları', NULL, 1, 0, 3, 1, 15, 45, 'D', '1- Sıvı azot bulunan/depolanan ve transfer işlemlerinin yapıldığı alanlarda etkin ve sürekli havalandırma sağlanmalıdır.\n2-Alanın kullanım şekli ve sıvı azot miktarı dikkate alınarak oksijen seviyesi izleme sistemi (O₂ dedektörü) gerekliliği değerlendirilmelidir.\n3- O₂ alarm sistemi kullanılması halinde sesli ve görsel alarmın çalışanların fark edebileceği şekilde konumlandırılması sağlanmalıdır.                                    \n4- Boş tüpler alanda bekletilmemeli, boş tüp deposuna gönderilmelidir.                                                                                                                                                       5- Dökülme/buharlaşma gibi acil durumlarda alan acilen tahliye edilerek alan tamamen havalanmadan tekrar giriş yapılmamalıdır. \n6- Transfer işlemlerinde üretici tarafından belirtilen uygun kriyojenik eldiven, yüz/göz koruması ve diğer KKD\'ler kullanılmalıdır.\n7- Oksijen yetersizliği şüphesi bulunan alana eğitimsiz personelin kurtarma amacıyla girmesi engellenmelidir.', 'İŞVEREN V. \n\nBİYOMEDİKAL/ DİĞER TIBBİ EKİPMAN HİZMETLERİ\n\nTÜP BEBEK MERKEZİ ÇALIŞANLARI', 'SÜREKLİ KONTROL', 1, 1, 15, 15, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 47, 'BÖLÜM 1: AMELİYATHANE', '1- Tüp Bebek Merkezi\'nde kullanılan sıvı azot tankının taşınması sırasında tankın devrilmesi, kontrolsüz hareket etmesi, çarpması veya taşıma ekipmanından ayrılması sonucu çalışanların yaralanması ve sıvı azotun ortama yayılması', '1- Devrilme / dökülme kaynaklı yaralanmalar                                                         2-  iş kazaları', '1-Tüp bebek merkezi çalışanları                                                    2-Taşıma personelleri', NULL, 1, 0, 3, 1, 15, 45, 'D', '1-Sıvı azot tankının tankın model ve kapasitesine uygun, devrilmeye karşı güvenli taşıma arabası ile taşınması sağlanmalıdır.\n2- Tank, taşıma arabasına uygun sabitleme mekanizması/kemer veya bağlantı sistemi ile güvenli şekilde sabitlenmelidir.\n3- Taşıma sırasında tank dik konumda tutulmalı; yatırılmamalı, sürüklenmemeli veya yuvarlanmamalıdır.\n4- Taşıma işlemi yalnızca eğitimli ve yetkilendirilmiş personel tarafından gerçekleştirilmelidir.\n5- Tankın taşınması sırasında çalışanların  EN 511 kriyojenik eldiven, göz/yüz koruması ve uygun iş ayakkabısı kullanması sağlanmalıdır; KKD, tankın güvenli taşınmasına yönelik mühendislik kontrollerinin yerine geçmemelidir.\n6-  Yılda bir kez periyodik bakım ve onarımları yapılmalı, dört yılda bir basınç testleri yapılmalıdır.                                                                      \n7- Pas ve korozyon olan tüpler kullanılmamalı, tedarikçi firmaya iade edilmelidir.', 'İŞVEREN V. \n\nBİYOMEDİKAL/ DİĞER TIBBİ EKİPMAN HİZMETLERİ\n\nTÜP BEBEK MERKEZİ ÇALIŞANLARI', 'SÜREKLİ KONTROL', 1, 1, 15, 15, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 48, 'BÖLÜM 1: AMELİYATHANE', '1-Ameliyatlar sırasında kullanılan vakum sisteminin çalışması nedeniyle ameliyathane ortamında oluşan gürültünün çalışanların maruziyetine neden olması', '1- Konsantrasyon kaybı                                                        2- İşitme kaybı', '1- Tüm ameliyathane çalışanları', NULL, 1, 0, 1, 6, 7, 42, 'D', '1- Vakum sisteminin bulunduğu ve çalışanların maruz kaldığı alanlarda gürültü düzeyi dB(A) cinsinden ölçülmelidir\n2- Ölçüm sonucunda maruziyetin ilgili sınırların üzerinde olduğunun belirlenmesi halinde mühendislik ve idari kontroller uygulanmalıdır.\n3- Kontrollerle yeterli azaltım sağlanamaması halinde işe uygun TS EN 352/2 işitme koruyucu KKD kullanımı değerlendirilmelidir.                                                                                                                                      4- Vakum sistemi ve ilgili ekipmanların periyodik bakım ve kontrolleri üretici talimatlarına uygun şekilde gerçekleştirilmelidir.\n5- Gürültünün kaynağında azaltılması için mümkün olması halinde daha düşük gürültü seviyesine sahip ekipman, izolasyon veya akustik kontrol yöntemleri değerlendirilmelidir.\n6Yapılan ölçüm, bakım ve düzeltici faaliyetlerin sonuçları kayıt altına alınmalıdır.', 'İŞVEREN V. \n\nİŞYERİ HEKİMİ\n\nAMELİYATHANE ÇALIŞANLARI', 'SÜREKLİ KONTROL', 1, 3, 7, 21, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: DİYALİZ', '1-Diyaliz/portable cihazlardan sıvı dökülmesi/sızması', '1-Kayma/düşme                                                 2-Elektrik çarpması', '1-Diyaliz çalışanları                                            2- Diğer ilgili çalışanlar                                                3- Hasta ve hasta yakınları', '1-Giderler mevcuttur.                                      2-Cihaz bakımlarını firma yapmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1- Cihazlar kullanılmadan önce hortumların gözle kontrolü yapılmalı herhangi bir arıza, zedelenme, bükülme ,ek yapılma durumu söz konusu ise onarım veya değişimi yapılmalıdır.                                                                                                                                                           2- Sıvı sızıntısı tespit edilen diyaliz cihazı derhal kullanım dışı bırakılmalı ve teknik servise bildirilmelidir.                                   \n3- Cihazların periyodik bakım ve sızdırmazlık kontrolleri 3 ayda bir yapılmalıdır.', 'BİOMEDİKAL                    DİYALİZ ÇALIŞANLARI', '3 AYDA 1    HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: DİYALİZ', '1-Diyaliz cihazlarının hortumlarında deformasyon                         2-Bağlantılarında su sızıntısı olması', '1-Elektrik çarpması                           2-Kayma düşme                                                3-Yangın', '1-Diyaliz çalışanları                         2- Diğer ilgili çalışanlar                         3- Hasta ve hasta yakınları', '1- Bakımları firma tarafından yapılmaktadır.                           2- Kaçak akım röleleri mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Diyaliz cihazlarının hortum ve kablolarında hiçbir şekilde ek ve deformasyon olmamalıdır.                                                                                                                                                             2- Kablolar ve hortumlar çift izolasyonlu olmalıdır.                                                                                     3- Hortumlar elektrik bulunan alanlardan (prizlerden) uzakta konumlandırılmalıdır.', 'DİYALİZ ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: DİYALİZ', '1-Su numunesi alınan vanaların altında elektrik panosu olması, ekli kabloların bulunması', '1-Elektrik çarpması                                                       2-Kıvılcımlanma ile yangın riski', '1-Diyaliz çalışanları                                     2- Diğer ilgili çalışanlar', '1- Kaçak akım röleleri mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Numune alma vanalarının altında pano, hidrofor vb. hiç bir elektrik ekipman ve elektrik kablosu bulunmamalıdır.                                                                                                                          2-Numıune vanalarında ki basınçlı suyun ortama yayılmasını önlemek için vana zemine yakın bir alana taşınmalı, vana altına büyük kaplar konulmalıdır.                                                                                                                                                                                3-Çalışanlara TS EN 50321 stardadında yalıtkan ayakkabı temin edilmeli ve zimmetlenmelidir.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: DİYALİZ', '1-Cihazlarda elektrik kaçağı olması', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm', '1-Diyaliz çalışanları                                     2- Diğer ilgili çalışanlar                                         3- Hasta ve hasta yakınları', '1- Kaçak akım röleleri mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Cihaz kabloları çift izolasyonlu olmalı herhangi bir ek ya da zedelenme olmamalıdır.                                                                                                                                                                     2- Elektirikli araç ve gereçler olası su (kirli-temiz) basmaları olabilecek alanlardan uzakta muhafaza edilmelidir.\n3- Elektirikle çalışan cihazlarda arızalar olduğunda ilgili bölüm sorumlusu tarafından ilgili firma çalışanları bilgilendirilmeli ve arızalar en kısa sürede giderilmelidir.                                                                                                                                                                                        4- Elektirik güvenliği ile ilgili eğitim verilmeli, Arızalı araç gereç kullanımdan çekilmeli,  bakım ve onarımı sağlanmalıdır.', 'BİOMEDİKAL                    DİYALİZ ÇALIŞANLARI', '2 AY                 HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: DİYALİZ', '1-Diyaliz cihazı temizleme sırasında oluşabilecek su kaçakları/cihazın boşta durması', '1-Yangın                              2-Su kaçağı                     3-Elektrik çarpması', '1-Diyaliz çalışanları                                     2- Diğer ilgili çalışanlar                                         3- Hasta ve hasta yakınları', '1-Bakımları yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1-Cihazların hortumlarıve bağlantı yerleri su sızıntısına karşı kontrol edilmeli su kaçağı olmamalıdır.                                                                                                                                                2-Fiş kabloları kontrol edilmeli herhangi bir deformasyon ek yeri olmamalıdır.                                    3-İşlemi biten cihaz fişte tutulmamalı, fiş çıkarılıp kuru bir yere sabitlenmelidir.', 'DİYALİZ ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: DİYALİZ', '1-Buatlara 3\'lü priz takılması sonucu aşırı yükleme', '1-Elektrik kaçağı    2-Yangın riski', '1-Diyaliz çalışanları                                         2- Diğer ilgili çalışanlar                                                     3- Hasta ve hasta yakınları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Buat içlerine 3 lü priz takılması kesinlikle engellenmelİ ve halojen free olmalıdır.\n2- Priz ihtiyaçları için buat yapılmalıdır.\n3- Elektrik tesisatı ve kaçak akım röleleri düzenli olarak yetkili çalışanlar tarafından kontrol edilmelidir.', 'BRS TEKNİK BİRİM', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: DİYALİZ', '1-Yatan hastaların yataklarında radyolojik\ngrafilerinin çekilmesi ( portable çekim)', '1-Meslek hastalığı (Kanser)', '1-Diyaliz çalışanları                                     2- Diğer ilgili çalışanlar                                         3- Hasta ve hasta yakınları', '1- Çekim yapan çalışanların KKD leri mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Portable radyoloji çekimleri yalnızca tıbben zorunlu hallerde diyaliz bölümü içerisinde yapılmalıdır.\n2- Çekim esnasında kurşun paravan kullanılmalıdır.                                                                                                                      3- Çalışanlar kişisel koruyucu donanım (kurşun önlük, tiroid koruyucu vb.) (TS EN 61331) kullanmalıdır.                                                                                                                                            4- Çekim sırasında hasta dışındaki kişilerin ( çalışan, refakatçi, diğer hastalar) en az 2 metre radyasyon alanından uzaklaştırılması sağlanmalıdır.', 'RADYOLOJİ ÇALIŞANLARI       DİYALİZ ÇALIŞANLARI', 'ÇEKİM ESANASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: DİYALİZ', '1-KKD eksikliği                      2-KKD kullanılmaması          3-KKD zimmeti olmaması', '1-İş kazaları                                   2-Meslek hastalıkları', '1-Diyaliz çalışanları                                                  2- Diğer ilgili çalışanlar', '1-KKD mevcuttur.                                                                  2-Çalışanlara KKD kullanımı konusunda eğitim verilmiştir.', 1, 0, 3, 6, 7, 126, 'C', '1- Çalışanlara kişisel koruyucu donanım Eldiven (EN 455) - Koruyucu Gözlük , Yüz Siperliği (EN 166) - Cerrahi Maske (EN14683) - Solunum Maskesi (EN149) sağlanmalı ve zamanında temin edilmelidir.\n2- KKD kullanımı bölüm sorumlusu tarafından sürekli denetlenmelidir.                                                                      \n3- Çalışanlara teslim edilen tüm KKD ler zimmetlenmelidir.\n4- Eksik veya hasarlı KKD hızla yenilenmeli, kullanılabilir durumda olmalıdır.', 'DİYALİZ SORUMLUSU     DİYALİZ ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: DİYALİZ', '1-Basınçlı oksijen tüplerinin hatalı kullanılması', '1-Yaralanma ve yanık', '1-Diyaliz çalışanları                                      2- Diğer ilgili çalışanlar                                                                          3- Hasta ve hasta yakınları', '1- Çalışanlara basınçlı tüplerin doğru kullanımı hakkında eğitim verilmiştir.', 1, 0, 3, 6, 7, 126, 'C', '1- Oksijen tüpleri alanda sabitleme aparatına en az iki noktadan bağlanmalıdır.                                               \n2- Tüp çıkış valfleri özellikle yağ ve su gibi kirleticilerden uzak ve temiz tutulmalı, yağlı ekipman (conta, regülatör vb.). kesinlikle kullanılmamalıdır.                                                                                                                                         3- Oksijen tüplerinin manometreleri sağlam olmalıdır.                                          \n4- Yanıcı maddeler oksijen tüpleri ile temas etmemelidir.                                                                               5- Eldivensiz oksijen tüpüne dokunulmamalı yağlı eldiven veya kremli ellerle dokunulmamalıdır.', 'BRS TEKNİK BİRİM                    DİYALİZ ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: DİYALİZ', '1-Hastalardan temas ve inhalasyon yolu ile bulaş', '1-Solunum yolu hastalıkları                                                                                  2- Temas yolu ile bulaşan hastalıklar', '1-Diyaliz çalışanları                                                                                        2- Diğer ilgili çalışanlar                                                 3- Hasta ve hasta yakınları', '1- Havalandırma sistemi mevcuttur.                                                              2-KKD\'ler mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Çalışanlar, temas ve inhalasyon yoluyla bulaş riski olan hastalarla çalışırken kişisel koruyucu donanım (Eldiven (EN 455) - Koruyucu Gözlük , Yüz Siperliği (EN 166) - Cerrahi Maske (EN14683) - Solunum Maskesi (EN149)) kullanmalıdır.\n2- El hijyenine azami özen gösterilmeli, sıvı sabun ve alkol bazlı antiseptik kullanımı sağlanmalıdır.\n3- Çalışanlar hastalardan bulaşma yolları ve korunma yöntemleri konusunda düzenli olarak eğitilmelidir.', 'DİYALİZ ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: DİYALİZ', '1-Kan ve vücut sıvılarının cilde teması', '1-Enfekte hastadan bulaş                                                                     2-Enfeksiyon riski', '1-Diyaliz çalışanları                                                                                                         2- Diğer ilgili çalışanlar', '1-KKD mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- KKD (Eldiven (EN 455) - Koruyucu Gözlük , Yüz Siperliği (EN 166) - Cerrahi Maske (EN14683) - Solunum Maskesi (EN149)) kullanılmalıdır.\n2- Temas sonrası cilt hemen su ve sabunla yıkanmalı, gerekirse antiseptik uygulanmalıdır.', 'DİYALİZ ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: DİYALİZ', '1-Kesici ve delici aletlerin emniyetsiz kullanımı', '1-Enfeksiyon, enfekte hastadan bulaş', '1-Diyaliz çalışanları                                                                        2- Diğer ilgili çalışanlar', '1- Sharpbox ve KKD mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Kullanılmış iğne ve kesici delici aletler mutlaka delinmeye dayanıklı, kapaklı atık kutularına atılmalıdır.                                                                                                                                     2- Kesici ve delici aletlerle çalışırken kişisel koruyucu donanım mutlaka kullanılmalıdır.                                             \n3- İlaç arabalarının rafları kapalı ve kilitli olmalıdır.                                                                                                                                                                    4- Atık kutularının doluluk durumu düzenli kontrol edilmeli,2/3 ü dolan atık kutuları boşaltılmalıdır.\n5- Kesici ve delici aletler dikkatli ve uygun şekilde kullanılmalı, gereksiz temaslardan kaçınılmalıdır.', 'DİYALİZ ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: DİYALİZ', '1-Tehlikeli davranışlar (Ucu açık iğne uçları,\nKKD kullanılmaması, stajyer öğrencilerin tek\nbaşına iş yapması)', '1-Meslek hastalığı                                            2-İş kazası                                              3-Enfeksiyon riski', '1-Diyaliz çalışanları                                        2- Diğer ilgili çalışanlar', '1- Sharpbox ve KKD mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Kullanılmış iğne uçları hemen ve güvenli şekilde uygun atık kutularına atılmalıdır.\n2- KKD (Eldiven (EN 455) - Koruyucu Gözlük , Yüz Siperliği (EN 166) - Cerrahi Maske (EN14683) - Solunum Maskesi (EN149)) her zaman ve doğru şekilde kullanılmalıdır.\n3- Stajyer öğrenciler kesinlikle tek başına riskli işlerde çalıştırılmamalı, mutlaka deneyimli çalışanların gözetiminde bulunmalıdır.\n4- Çalışanlar ve stajyerlere tehlikeli davranışların riskleri hakkında düzenli eğitim verilmelidir.', 'DİYALİZ BÖLÜM SORUMLUSU  DİYALİZ ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: DİYALİZ', '1-Açıkta bırakılan kontamine araç gereçler', '1-Enfeksiyon riski', '1-Diyaliz çalışanları                              2- Diğer ilgili çalışanlar                                    3- Hasta ve hasta yakınları', '1- 1616’dan talep açıldığında kontamine araç gereçler sterilizasyon firması tarafından toplanmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Kontamine araç gereçler hemen uygun kapalı kaplarda muhafaza edilmelidir.\n2- Kullanılan araç gereçler temizlenmeli, dezenfekte edilmeli veya sterilize edilmelidir.\n3- Atık yönetimi prosedürlerine göre kontamine malzemeler bertaraf edilmelidir.                                                                       4- Araç gereçlerin açıkta bırakılması engellenmeli, uygun depolama alanları sağlanmalıdır.                                                                                                                                                                             5- Kontamine malzemelerle temas önlenmeli ve hijyen kurallarına uyulmalıdır.', 'ISS TEMİZLİK ÇALIŞANLARI                            DİYALİZ ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: DİYALİZ', '1-Diyaliz kimyasallarının dökülme ve sıçramasına bağlı kazalar', '1-İş kazaları riski    2-Solunum yolu hastalıkları                                       3-Düşme riski                                                                  4-Elektrik çarpması', '1-Diyaliz çalışanları                                  2- Diğer ilgili çalışanlar                                                 3- Hasta ve hasta yakınları', '1- KKD mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Kimyasalların taşınması sırasında dökülme/sıçrama riskini önleyecek uygun taşıma ekipmanları (kapaklı bidonlar, sızdırmaz kaplar vb.) kullanılmalıdır.\n2- Kimyasallar kullanılırken kişisel koruyucu donanımlar (Eldiven (EN 455) - Koruyucu Gözlük , Yüz Siperliği (EN 166) - Cerrahi Maske (EN14683) - Solunum Maskesi (EN149)) mutlaka kullanılmalıdır.\n3- Kimyasal dökülme durumları için uygun temizlik ve müdahale kitleri (absorban malzemeler vb.) kolay ulaşılabilir yerlerde bulundurulmalıdır.                                        \n4- Kimyasal maddeler ve dezenfektanlar depolanırken üst üste konulmamalıdır.      5- Dökülmeye karşı zemin temizlenmeli, temizlik sonrası havalandırma sağlanmalıdır.', 'İŞVEREN V.                    DİYALİZ ÇALIŞANLARI', '3 AY                            HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: DİYALİZ', '1-Portable kullanılan cihazların (Diyaliz, Usg, Röntgen, EKG  Vb.) temizlik ve dezenfeksiyonunun yapılmaması', '1-Enfeksiyon riski', '1-Diyaliz çalışanları                                    2- Diğer ilgili çalışanlar', '1- Firma tarafından takipleri yapılmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1-Tüm portable cihazlar (Diyaliz, USG, Röntgen, EKG  vb.) kullanım sonrası mutlaka temizlenmeli ve dezenfekte edilmelidir.\n2-Cihazların temizliği ve dezenfeksiyonu periyodik olarak denetlenmeli ve kayıt altına alınmalıdır.', 'TEMİZLİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: DİYALİZ', '1-Kan ve vücut sıvılarının göze teması ile bulaş', '1-Enfeksiyon riski', '1-Diyaliz çalışanları                                        2- Diğer ilgili çalışanlar', '1- Çalışanların KKD leri mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Kan ve vücut sıvıları ile çalışılırken mutlaka kişisel koruyucu donanım (Koruyucu Gözlük , Yüz Siperliği (EN 166)) kullanılmalıdır.                                     \n2-Çalışma alanlarında acil durumlarda gözün hızlıca yıkanabileceği göz duşu solüsyonu bulundurulmalıdır.', 'İŞVEREN V.   DİYALİZ ÇALIŞANLARI', '3 AY                         HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: DİYALİZ', '1-Bulaş tehlikesi olan hastaların ayrı alanlarda tedavi alması', '1-Meslek hastalığı                          2-Enfeksiyon riski', '1-Diyaliz çalışanları                                       2- Diğer ilgili çalışanlar', '1- Ayrı işlem odaları mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Hasta nakli sırasında enfeksiyon kontrol protokollerine uyulmalı, kişisel koruyucu ekipmanlar mutlaka kullanılmalıdır.                                                                                                                          2- Bulaşıcı hastalık riski taşıyan hastalar, diğer hastalardan ayrı izole odalarda tedavi edilmelidir.                                          \n3- Ortak kullanım alanlarında (tuvalet, bekleme salonu vb.) düzenli dezenfeksiyon işlemleri yapılmalıdır.', 'DİYALİZ ÇALIŞANLARI TEMİZLİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: DİYALİZ', '1-Çıkış kapısından alana soğuk hava girişi', '1-Termal konfor koşullarının sağlanamaması sonucunda hastalıklara yakalanma', '1-Diyaliz çalışanları                                         2- Diğer ilgili çalışanlar', '1- Havalandırma iklimlendirme sistemi mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Kapı girişlerine hava perdesi sistemi kurulmalıdır.\n2- Kapılarda herhangi bir arıza durumunda talep açılıp onarımı sağlanmalıdır.', 'İŞVEREN V.', '1 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: DİYALİZ', '1-Su numunesi alınan teknik mahallerin girişleri ve yollarında alçak tavan ve havalandırma sistemleri sebebiyle baş çarpması/yaralanması', '1-Baş yaralanması', '1-Diyaliz çalışanları                                    2- Diğer ilgili çalışanlar', 'Uyarı işaretleri mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1- Çalışanların baret  (EN 397+A1 )  ve iş ayakkabısı (EN ISO 20345) temin edilmelidir. kullanılmalıdır.                                                                                                                                             2- Uyarı işaretleri ( DİKKAT ALÇAK TAVAN vb.) gibi konulmalıdır.                                                3- Tavanda bulunan vidalar tehlike yaratmayacak şekilde körlenmeli ya da uçlarına mantarlar takılmalıdır.', 'İŞVEREN V.                             SU NUMUNESİ ALAN ÇALIŞANLAR', '3 AY                                                          HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: DİYALİZ', '1-Diyaliz setinin takılması ve sökülmesi esnasında kan ve vücut sıvılarının dökülmesi sonucu bulaş ve kayma', '1-Enfeksiyon riski  2-Kayma, düşme', '1-Diyaliz çalışanları                                 2- Diğer ilgili çalışanlar', '1- Çalışanların KKD leri mevcuttur.', 1, 0, 6, 2, 7, 84, 'C', '1- İşlem öncesi ve sonrası alan temizliği ve dezenfeksiyonu yapılmalıdır.                            2- Kişisel koruyucu ekipman (Eldiven (EN 455) - Koruyucu Gözlük , Yüz Siperliği (EN 166) - Solunum Maskesi (EN149)) kullanılmalıdır.\n3- Kaymayı önleyici ayakkabı (EN ISO 20345) ve emici paspaslar kullanılmalıdır.', 'DİYALİZ ÇALIŞANLARI TEMİZLİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 1: DİYALİZ', '1-Kesici delici aletlerin ortalıkta bulunması (Makas, enjektör vb.)', '1-Çalışan hasta ve yakınları için kesici delici alet yaralanması', '1-Diyaliz çalışanları                                   2- Diğer ilgili çalışanlar', '1- Çalışanların zimmetleri vardır.', 1, 0, 6, 2, 7, 84, 'C', '1- Kesici delici aletler sadece belirlenen alanlarda bulundurulmalıdır.\n2- Kullanım sonrası hemen toplanmalı ve güvenli şekilde saklanmalıdır.', 'DİYALİZ ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 1: DİYALİZ', '1-Kullanılan kimyasalların malzeme güvenlik bilgi\nformlarının (MSDS) alanda olmaması', '1-Parlama, patlama, yangın ve iş kazası riski', '1-Diyaliz çalışanları                                       2- Diğer ilgili çalışanlar', '1- MSDS mevcuttur.', 1, 0, 6, 2, 7, 84, 'C', '1- Kullanılan tüm kimyasal maddeler belirlenmelidir.\n2- Her kimyasal maddeye ait güncel Malzeme Güvenlik Bilgi Formları (MSDS) temin edilmelidir.\n3- MSDS belgeleri kolay erişilebilir bir yerde bulundurulmalı ve çalışanların ulaşabileceği şekilde düzenlenmelidir.', 'DİYALİZ BÖLÜM SORUMLUSU                               İSG UZMANI', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 1: DİYALİZ', '1-Lavabolarda bulaş ve ergonomi', '1-Enfeksiyon yayılımı                                                                    2-Ergonomi problemleri', '1-Diyaliz çalışanları', '1- Lavabolar mevcuttur.', 1, 0, 3, 2, 7, 42, 'D', '1- El ile açılan musluklar fotoselli musluklar ile değiştirilmelidir.\n2- El hijyen ekipmanları kolay erişilebilir konumda olmalıdır.                                                             \n3- Musluk ve lavabo yüzeyleri düzenli olarak dezenfekte edilmelidir.', 'İŞVEREN V.   TEMİZLİK ÇALIŞANLARI', '3 AY                         HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM: TEMİZLİK İŞLERİ', '1-Yüzeylerin yanlış bez ya da ekipman ile temizlenmesi', '1-Çapraz Bulaşma (Çapraz Kontaminasyon)         2-Hijyen Kurallarının İhlali', '1-Çalışanlar', '1-Bölgelere göre bezler paspaslar ayrılmıştır.', 1, 0, 6, 6, 7, 252, 'B', '1-Her alan için ayrı temizlik ekipmanı (bez, kova, süpürge vs.) kullanılmalıdır.\n2-Temizlik arabalarında bezler renk kodlarına göre işaretlenmelidir.\n3- Temizlik işleri, temizlenecek yüzeye göre belirlenmiş renkteki bezler ile yapılmalı, bezler kesinlikle karıştırılmamalıdır.                                                                                                                   Kırmızı bez-Klozet, klozet kapağı, pisuvar                                                                                              Yeşil bez-Mobilya, yatak, raf, havalandırma, aydınlatma                                                                      Mavi bez-Ofis, oda toz alımlarında                                                                                                       Sarı bez-WC lerdeki lavabo, fayans, sifon, wc aparatları, ayna, duşakabin                                                             4-Bezler ve kovalar her kullanımdan sonra  dezenfekte edilmelidir.                                                               5-Alan sorumluları tarafından sürekli kontrol denetim sağlanmalıdır.', 'ISS TEMİZLİK FİRMASI ALAN SORUMLUSU VE  ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM: TEMİZLİK İŞLERİ', '1-Ortak alanların rutin temizliğinin uygun yapılmaması', '1-Çapraz Bulaşma (Çapraz Kontaminasyon)', '1-Çalışanlar', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Çalışanlar için enfeksiyon hastalıklarına yol açabilecek ortak alanlar asansörler, yürüyen merdivenler, kapı kolları vb. temizliği günlük düzenli olarak yapmalıdır.                                                                                                                                                                         2- Temizlenecek yüzeye göre belirlenmiş bezler ve dezenfektanlar kullanılmalıdır.                                                                                                                                              3- Sorumlular tarafından yapılan temizlik kontrol edilmelidir.                                                                 4- Temizlik formları, hem temizlik yapanlar hem de kontrol edenler tarafından her temizlik sonrası imzalanmalıdır.', 'ISS TEMİZLİK FİRMASI ALAN SORUMLUSU VE  ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM: TEMİZLİK İŞLERİ', '1-Tıbbi cihazların                              ( röntgen, ultrason, mr, tomografi, diyaliz vb.) temizlik ve dezenfeksiyonun yapılmaması ya da yanlış yapılması', '1-Enfeksiyon, bulaşıcı hastalıkları oluşması', '1-Çalışanlar', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Temizlik mavi kodlu bezlerle yapılmalı herhangi bir kan veya vücut sıvısı bulaşı yoksa saf su ile eğer kan ve vücut sıvısı var ise yüzey dezenfektanıyla temizlenmelidir.                                                                                                                                                                                                           2- Temizlik arabalarında cihaz temizliği için kullanılan kimyasallar ve ekipmanlar bulundurulmalıdır.                                                                                                                                         3-Çalışanlara konu hakkında eğitimler verilmelidir.                                                                       4- Alan sorumluları tarafından sürekli kontrol denetim sağlanmalıdır.', 'ISS TEMİZLİK FİRMASI ALAN SORUMLUSU VE  ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM: TEMİZLİK İŞLERİ', '1- Acil çıkış yolları üzerinde temizlik arabalarının bırakılması', '1-Acil durum karşısında tahliyenin zorlaşması                           2-Kargaşaya sebebiyet verme', '1- Çalışanlar                                2- Hastalar ve hasta yakınları        3- Diğer ilgili kişiler', '1-Çalışanlar uyarılmakta ve denetlenmektedir.', 1, 0, 6, 3, 7, 126, 'C', '1-Temizlik ekipmanları ve arabaları, belirlenmiş depolama alanlarında muhafaza edilmelidir.                                                         \n2-Acil çıkış yolları ve koridorlar kesinlikle herhangi bir eşya veya temizlik arabası ile engellenmemelidir.\n3-Temizlik çalışanlarına acil çıkış yollarının önemi ve bu alanlarda araç bulundurulmaması konusunda eğitim verilmelidir.', 'ISS TEMİZLİK FİRMASI ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM: TEMİZLİK İŞLERİ', '1-Temizlik arabalarının yangın dolapları ve söndürücüleri, elektrik panoları önünde bulundurulması', '1-Yangın durumunda dolaplara ve tüplere erişimi zorlaştırma', '1- Çalışanlar                                2- Hastalar ve hasta yakınları        3- Diğer ilgili kişiler', '1-Çalışanlar uyarılmakta ve denetlenmektedir.', 1, 0, 6, 3, 7, 126, 'C', '1-Yangın dolaplarının, tüplerinin, elektrik panolarının ve pano odalarının önünde hiçbir şekilde temizlik arabası bulundurulmamalıdır.                                                                                                                                                                              2-Çalışan bu konuda sürekli kontrol edilmeli ve eğitimleri verilmelidir.', 'ISS TEMİZLİK FİRMASI ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM: TEMİZLİK İŞLERİ', '1-Temizlik arabalarında kimyasal döküntü kitinin olmaması', '1-Kimyasal buharının ortama  yayılıması sonucu maruziyet', '1-İlgili çalışanlar                  2- Hastalar ve hasta yakınları', '1-Bazı temizlik arabalarında döküntü kiti mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1-Kimyasal dökülmelerine karşı her araçta kimyasal döküntü kiti bulundurulmalıdır.                                                                                                                                       2-Çalışanlara kimyasal döküntü kitinin nasıl kullanılması gerektiği anlatılmalıdır.', 'ISS TEMİZLİK FİRMASI', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM: TEMİZLİK İŞLERİ', '1-Biyolojik vücut sıvılarının dökülmesi', '1-Bulaşıçı hastalıklar', '1-İlgili çalışanlar                  2- Hastalar ve hasta yakınları', '1-Havalandırma sistemi mevcut ve aktif olarak çalışmaktadır.', 1, 0, 6, 6, 3, 108, 'C', '1-Çalışanlar KKD kullanmalıdır.                                                                                                                       2-Döküntü fazla ise emdirilip tıbbi atık kutusuna atılmalıdır.                                              3-Yüzey klorlu temizleyicilerle temizlenmelidir.', 'ISS TEMİZLİK FİRMASI ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM: TEMİZLİK İŞLERİ', '1-El hijyeni sağlamak için lavabo (sıvı sabun, kağıt havlu vb.) ve alkol bazlı el antiseptiğinin bulunmaması', '1-Enfeksiyon', '1- Çalışanlar                                2- Hastalar ve hasta yakınları        3- Diğer ilgili kişiler', '1-Lavabo ve temizlik dejenfeksiyon malzemeleri alanda mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1-Çalışma alanlarında lavabolar sürekli kullanıma hazır olmalıdır.\n2-Lavabolarda sıvı sabun, kağıt havlu ve hijyenik kurutma malzemeleri bulundurulmalıdır.\n3-Alkol bazlı el antiseptikleri erişilebilir olmalıdır.\n4-El hijyeni için gerekli malzemelerin düzenli olarak kontrolü ve temini sağlanmalıdır.', 'ISS TEMİZLİK FİRMASI ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM: TEMİZLİK İŞLERİ', '1-Yüksekte çalışma faaliyetleri, dış cephe temizlenmesi', '1-Yüksekten malzeme düşmesi sonucu yaralanma', '1-İlgili çalışanlar', NULL, 1, 0, 6, 1, 15, 90, 'C', '1-Dış cephe temizliği çalışma izin formu ile yapılmalıdır.                                                                                                                                                2-Malzeme ve ekipman düşmelerine karşı güvenlik çemberi oluşturulmalıdır.                                                                      3-Yüksekte yapılan çalışmalarda kullanılan malzeme ve aletlerin düşmemesi için Çapa noktaları (EN 795), Emniyet halatları (EN 354), Bağlantı elemanları (EN 362) ile sabitlenmelidir.                                                                                                                                     4-Dış cephe temizliğinde, Tam vücut emniyet kemerleri (EN 361) Bağlantı halatları (lanyard) (EN 354) Şok emici bağlantı sistemleri (EN 355) Kendiliğinden geri sarımlı düşüş durdurucular (EN 360) Karabinalar (EN 362) Ankraj sistemleri (yaşam hatları vb.) (EN 795) Endüstriyel baretler (EN 397) Kurtarma kaldırma ekipmanları (EN 1496) İniş sistemleri (acil iniş) (EN 341) Dikey düşüş durdurucu sistemler (EN 353-1/2) standartlarında yüksekten düşmeyi önleyici ekipmanlar ve KKD\'ler kullanılmalıdır.\n5-Temizlik kovaları ankraj sistemine bağlanmadan kullanılmamalıdır.                                                                                                     6-Çalışanlara yüksekte çalışma eğitimi ve güvenlik kuralları mutlaka verilmelidir.', 'ISS FİRMASI', 'DIŞ CEPHE TEMİZLİK                 İŞLERİ SIRASINDA', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM: TEMİZLİK İŞLERİ', '1-Islak ve kaygan zemin', '1-Düşme, yaralanma, çarpma, burkulma', '1- Çalışanlar                                2- Hastalar ve hasta yakınları        3- Diğer ilgili kişiler', '1-Nemli temizlik yapılmaktadır.                  2-Uyarı levhaları mevcuttur', 1, 0, 6, 3, 3, 54, 'D', '1-Islak ve kaygan zeminler uyarı levhalarıyla işaretlenmelidir.\n2-Zeminler mümkün olan en kısa sürede kurutulmalıdır.\n3-Islak zemin oluşumuna neden olan kaynaklar (sızıntı, temizlik vb.) belirlenerek önleyici tedbirler alınmalıdır.                                                                                                                                                                                4-Çalışanlar, kaygan zeminlerde kaymaz ayakkabı (EN 13287) kullanımı konusunda bilgilendirilmelidir.', 'ISS TEMİZLİK FİRMASI ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM: TEMİZLİK İŞLERİ', '1-Temizlik kat arabalarında bulunan kimyasalların düzensizliği', '1-Yere kimyasal dökülmesi', '1-Çalışanlar', '1-Taşma kapları mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1-Kimyasalların temizlik arabalarında yerleştirilmesi kimyasal matrisine uygun şekilde düzenlenmelidir.\n2-Temizlik kimyasalları birbirine karıştırılarak kullanılmamalıdır.                                                              3-Kimyasallar taşma kaplarına konularak sızıntı ve akma durumunda taşma kabı dışına çıkmamalıdır.                                                                                                                                                                                                                                                                                                   4-Kullanıcılar kimyasal maddelerin doğru kullanımı ve güvenliği konusunda eğitilmelidir.', 'ISS TEMİZLİK FİRMASI ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM: TEMİZLİK İŞLERİ', '1-Cam ya da camdan oluşan kapıların kırılma ve çatlamaları', '1-Parçalanma, kesilme, yaralanma', '1- Çalışanlar                                2- Hastalar ve hasta yakınları        3- Diğer ilgili kişiler', '1-KKD mevcuttur.', 1, 0, 3, 2, 7, 42, 'D', '1-Camlar ve cam kapılar, dayanıklı ve kırılmaya karşı güvenlik camı (lamine veya temperli cam) olmalıdır.\n2-Cam kapılar ve büyük cam yüzeyler görünürlük işaretler (frost, bant, sticker vb.) sağlam olmalı, yıpranan ya da çıkan işaretler yenilenmelidir.\n4-Cam ve cam kapılar düzenli olarak kontrol edilmeli, çatlak veya hasarlı camlar derhal yenilenmelidir.\n5-Cam kırılması durumunda etrafı çevrelenmeli, hızlıca temizlik yapılmalı, çalışanların ve hastaların korunması sağlanmalıdır.', 'ISS TEMİZLİK FİRMASI ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM: TEMİZLİK İŞLERİ', '1-Temizlik arabalarının dikkatsiz kullanımı', '1-Cam ve kapı kırılmaları, çarpmalar ve iş kazaları', '1-İlgili çalışanlar                  2- Hastalar ve hasta yakınları', '1-Çalışanlara eğitim verilmiştir.', 1, 0, 3, 3, 3, 27, 'D', '1-Temizlik arabalarının frenleri düzenli olarak kontrol edilmelidir.                                          2-Araçların düzenli bakım ve kontrolü sağlanmalıdır.\n3-Kullanım alanı ve çevre koşulları sürekli gözlemlenerek riskler azaltılmalıdır.                                                                        4-Kullanıcılar dikkatli kullanım ve güvenlik konularında eğitilmelidir.', 'ISS TEMİZLİK FİRMASI ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Yeterli sayıda kişisel koruyucu ekipman olmaması                              2- Kişisel koruyucu ekipmanın deforme olması', '1- Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', '1- Her çalışanın kişisel tiroid koruyucusu vardır.', 1, 0, 3, 6, 15, 270, 'B', '1-Nükleer tıp bölümünde tüm çalışanlara ts en 61331-1 standartında kurşun yelek,kurşun tiroid koruyucu donanımlardan eksik olanlar verilmelidir.                                                           2-Özellikli(kurşun kaplı) kişisel koruyucu donanımların kırılma vb. kontrolü günlük olarak çalışanlar tarafından yapılmalıdır.                                                                                                                     3-Koruyucu önlükler sandalye ve koltuk üzerine buruşuk bir şekilde koyulmamalıdır,özel askılıklarda tutulmalıdır.                                                                                                                                                                                  4-Dezenfeksiyon ve temizliğinde alkol içerikli temizleme maddesi kullanılmamalıdır.                                                                                                                                                      5-Tüm koruyucular yılda en az bir kez veya ihtiyaç görüldüğü hallerde (Deforme olmuş,bozulmuş,kırılmış,düşmüş) sorumluya bilgi verilip skopi ile kontrol edilerek ayrılmalı ve kullanılmamalıdır.', 'İŞVEREN V. NÜKLEER TIP BÖLÜM ÇALIŞANLARI', '2 AY                          HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1-Çalışan dinlenme odasının radyasyonlu alana yakın olması', '1- Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1-Gözetimli alanlar içerisinde bulunan hasta bekleme,doktor,personel dinlenme odası gibi alanların radayoaktif ölçümü en az altı ayda bir yapılmalı ve belgelendirilmelidir.                                                                                                                               2- Alan ölçüm değeri 0,5 µSv/h  değerini geçmemelidir.', 'RKS (RADSYASYON ÖLÇÜMÜ)', '6 AYDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Hastaya radyoaktif madde uygulaması yapılması', '1- Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', '1- Her çalışanın kişisel tiroid koruyucusu vardır.', 1, 0, 6, 6, 7, 252, 'B', '1-Hastaya ilaç uygulanacağı zaman çalışanlar eldiven,kurşun önlük,boyun koruyucu,maske,tam yüz koruma gözlüklerini giymiş olmalıdır.                                                                                                       2-İlaçlar hasta odasına taşınırken kurşun zırhla kaplı kutularda taşınmalıdır.                                                      3-Enjeksiyon işlemi bittikten sonra atıklar kurşun zırhlı atık kutularına atılmalıdır.', 'NÜKLEER TIP BÖLÜM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Atıkların uzun süreli bekletme sonucu sineklenme olması', '1- Enfeksiyon bulaşı', '1-Nükleer tıp bölüm çalışanları', '1- Evsel atıklar kilitli tehlikeli atık varillerinde bekletilmektedir.', 1, 0, 6, 6, 7, 252, 'B', '1-Atık poşetleri sağlam olmalı, poşetlerde yırtık delik olmamalıdır.                                                                                                  2- Atık poşetlerinin ağızları sıkıca bağlanmalı kilitli kutularda saklanmalıdır.                                                                                                                           3-Ortam ısısı düşürülmelidir.                                                                                                                                   4-En geç ayda bir ilaçlama yapılmalıdır.                                                                                                                     5- Atık odasının kapısı açık bırakılmamalıdır.', 'ISS     (İLAÇLAMA)                           ISS TEMİZLİK ÇALIŞANLARI', 'AYDA 1                          HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Radyasyonlu hastanın ve hasta yakınının çalışana teması yada yakın mesafede bulunması', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', '1- Hastalara tedavi öncesi eğitim verilmektedir.', 1, 0, 6, 6, 7, 252, 'B', '1-İşlem yapılmadan önce hasta ve hasta yakınlarına işlem bitimini takiben diğer insanlarla en az 2 metre radyosyon güvenli mesafesi bırakılması gerektiğinin bilgisi verilmelidir.                                                                                                                                                                 2-İşlem öncesi,sırası ve sonrasında yapılacaklar hastaya detaylı bir şekilde anlatılmalıdır.                                                                                                                                                                         3-Çalışanlar kurşun yelek,kurşun tiroid koruyucu,maske , gözlük ve eldiven kullanarak çalışmalıdır.', 'NÜKLEER TIP BÖLÜM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- İlaç hazırlama ünitesi arkasında ekli kabloların olması', '1-Elektirik çarpması sonucu yanık,sinir kas ya da organ kaybı', '1-Nükleer tıp bölüm çalışanları', '1-Panolarda 30 MA kaçak akım rölesi mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Elektirik kabloları sağlam yapıda,çift izolasyonlu  olmalıdır.                                                                                   2-Kablolarda deformasyon olmamalıdır.                                                                                           3-Deformasyon olan kablolar değiştirilmelidir.', 'BRS TEKNİK BİRİM', '1 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- MON.FDG (18F) Enjeksiyonluk Çözelti kullanılması', '1- Maruziyet durumunda göz cilt iritasyonu', '1-Nükleer tıp bölüm çalışanları', '1- Radyoaktif ilaçlar sıcak odada çeker ocak altında hazırlanmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1-Bulaşma olan alana emici bir materyal koyarak maddenin dağılmasını önlenmeli, dıştan merkeze dogru temizlenmelidir.                                                                                                                                                                                                                                                                     2-Dekontaminasyon çözeltisi ile, sonrasında su ve sabun ile temizleyip ortam havalandırılmalıdır.                                                                                                                                              3-Kontamine olmuş tüm kullanılan materyaller ve atıklar radyasyon güvenliği sorumlusunun talimatına göre, kalıntı, kir bırakmayacak şekilde toplanmalıdır.                                                                      4-İmhası için, yarılanma ömrünü dikkate alarak uygun kapalı radyoaktif atik kabında toplanmalıdır.                                                                                                                                                5-Göze temas durumunda En az 15 dakika bol su ile yıkanmalıdır.\n6-Yutma durumunda ağız su ile çalkalanmalıdır. Bilinci kapalı ise ağız yolu ile hiçbir şey verilmemeli, acile başvurulmalıdır.', 'NÜKLEER TIP BÖLÜM ÇALIŞANLARI', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- MON.Tek Jeneratör', '1- Maruziyet durumunda gözde irritasyon,alerjik reaksiyon,kronik maruziyette genetik ve teratojenik etkiler', '1-Nükleer tıp bölüm çalışanları', '1- Radyoaktif ilaçlar sıcak odada çeker ocak altında hazırlanmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1-İnhalasyon durumunda inhale edilen miktar kaydedilmeli ve değerlendirilmelidir.                                                                                                                                        2-Yutma durumunda yutulan miktar kaydedilmeli ve değerlendirilmelidir. Kusturmadan bilinç kapalı ise ağız yolundan hiçbirşey vermeden doktora danışılmalıdır.                                                                                                                                                    3-Cilde temas durumunda radyoaktif madde dekontaminasyon çözeltileri ile veya sabun ve bol su ile bu iş düzenlenmiş lavaboda yıkanmalıdır. Cilt sertçe ovuşturularak tahriş edilmemelidir.                                                                                                                                                                                                                               4-Bulaşma olan giysi ayakkabı vs. çıkartılmalı ve radyoaktivitesi belli bir seviyeye inene kadar uygun alanda bekletilmelidir.                                                                                                                                                                5-Göze temas durumunda radyoaktif madde bulaşı kalmayana kadar en az 15 dakika bol su ile yıkanmalıdır.Yıkanma esnasında göz açık tutulmamalıdır.', 'NÜKLEER TIP BÖLÜM ÇALIŞANLARI', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Radyoaktif taşıma kaplarının düşmesi,devrilmesi', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', '1- Kilitli kurşun kaplı taşıma çantaları mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Radyoaktif taşıma kapları taşıma arabaları ie en az iki noktadan sabitlenerek taşınmalıdır.                                                                                                                                                                2-Dökülme riskine karşı taşıma arabasına sabit döküntü kiti bulundurulmalıdır.                                              3-Taşıma kaplarının emniyet kilitleri sağlam yapıda olmalıdır bozulanlar değiştirilmelidir.                                                                                                                                                               4-Kontrol ve denetim sağlanmalıdır.', 'BRS ŞİRKETİ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1-Sıcak odada plastik sharp-box kullanılması', '1- Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', '1-Shaprboxlar kurşun tuğlaların içinde bulunmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1-Sharp-boxlar kullanımı sonlanana kadar kurşun blokların arkasından çıkarılmamalıdır.                                                                                                                                                   2-Sharp-box 2/3 si dolunca kapatılıp etiketlenerek  transfer dolabından atık bekletme odasına taşınmalıdır.                                                                                                                                               3- Sıcak odada ki diğer radyoaktif atıklar kurşun atık kutusuna atılmalıdır.', 'NÜKLEER TIP BÖLÜM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Temizlik çalışanlarının yeterli eğitime sahip olmaması', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-Nükleer tıp bölümünde, her vardiyada sabit temizlik çalışanları bulundurulmalıdır.                                                                                                                                                                  2-Radyasyon Güvenliği, Radyoaktif Atıklar ve Radyokaktif Alanda Güvenli Çalışma konuları hakkında eğitime sahip olmayan temizlik çalışanları Nükleer tıp bölümünde çalıştırılmamalıdır.                                                                                                                                                                                                                                                      3-Eğitimleri en az yılda bir kez tekrarlanmalı ve belgelendirilmelidir.', 'ISS ŞİRKETİ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Radyoaktif atıkların doğru atılmaması ve depolanmaması', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', '1- Uzun süreli atık odası mevcut ve kilitli durumdadır.', 1, 0, 3, 6, 7, 126, 'C', '1-Günlük çalışmalar için kullanılacak olan kabın kapağı ayak pedalı ile açılır olmalıdır.                                                                                                                                                        2-Kabın iç kısımları,kapağı ve tabanı kurşun malzeme ile zırhlanmalıdır.                                                                                3-Kabın dış kısmında ulaslararası standart radyasyon işareti bulunmalıdır.                                             4-Kabın içerisinde yeterli büyüklükte ve uç kısımları dışarı taşacak şekilde torba yerleştirilmelidir.                                                                                                                                                   5-Biriktirme kabı dolduğunda plastik torbaların ağzı bağlanarak etiketlenmelidir.                                                                                                                                        6-Torbalar uzun süreli atık bekletme odasında radyasyon doz hızı 1 mSv/saat e düşünceye kadar bekletilmelidir.', 'NÜKLEER TIP BÖLÜM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1-Gama kamera odalarına işlem esnasında girilmesi                                        2-Gama kamera odalarında güvenli kullanım talimatı olmaması', '1- Gama ışınlarına maruziyet sonucu meslek hastalığı oluşması', '1-Nükleer tıp bölüm çalışanları', '1- Gama odalarına ilaç verme işlemleri dışında girilmemektedir.', 1, 0, 3, 6, 7, 126, 'C', '1- Dinamik çekimlerde odaya giren personel  eldiven,kurşun önlük,boyun koruyucu,maske,tam yüz koruma gözlük kullanmalıdır.                                                                                                              2-Hastaya ilaç verme işlemi görüntüleme ile eş zamanlı başayıp işlem bitiminden hemen sonra odadan hemen çıkılmalıdır.                                                                                                                                                                      3-Odaya güvenli ekipman kullanım talimatı konulmalıdır.', 'BRS ŞİRKETİ           (TALİMAT) NÜKLEER TIP BÖLÜM ÇALIŞANLARI', '3 AY                      HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Çeker ocağın aspiratörünün filtre değişim ve kontrollerinin tekrarlanmaması', '1- Radyoaktif maddenin solunması', '1-Nükleer tıp bölüm çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-Filtreleri en geç yılda bir değiştirilmelidir.                                                                                                                          2-Filtrelerin akış hızı testi en geç altı ayda bir, sızdırmazlık verim testleri en geç yılda bir tekrarlanmalıdır.                                                                                                                                                                       3-Çeker ocak içerisindeki doz kalibratörleri en geç 2 yılda bir NDK nın belirlediği yetkin kuruluşlarca kalibre edilmelidir.                                                                                                                                           4-Kontrol formları kayıt altına alınarak arşivlenmelidir.', 'RKS                           (KONTROL DENETİM)', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Sıcak odada radyoaktif ilaç hazırlanması', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', '1- Çeker ocak ve kurşun tuğlalar mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Radyoaktif İlaç hazırlama işleri sadece çeker ocak altında ve yetkili kişilerce yapılmalıdır.                                                                                                                                                                              2-Oda kapısı işlem sonrasına kadar kapalı olmalıdır.                                                                                                                         3-Oadaya yetkisiz kişilerin girişi engellenmelidir.                                                                                                                                                                                                                 4-Oda içerisinde mevcut sürekli ölçüm yapan Alan Ölçüm Cihazı çalışır durumda olmalıdır.                                                                                                                                                                                                        5-Kontrol bakım ve kalibrasyonu en geç 2 yılda bir yapılmalıdır.                                                                                                                                                           6-Çalışma esnasında kurşun önlük ve troid koruyucular,  tulum maske gözlük çizme eldiven mutlaka kullanılmalıdır.', 'BRS ŞİRKETİ ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
