INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Efor odasında kurşun önlük ve boyun koruyucusu olmadan çalışma', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', '1-Efor odasına sadece ilaç verme esnasında girilmektedir.', 1, 0, 3, 6, 7, 126, 'C', '1-Çalışan eldiven,kurşun önlük,boyun koruyucu,maske,tam yüz koruma gözlük kullanmalıdır.                                                                                                                                                                                    2-Kişisel koruyucu ekipmanlar efor odasına girilmeden giyilmelidir.                                                      3- İlaç atıkları kurşun kaplamalı ve üstünde radyoaktif atık madde işareti olan kaplara atılmalıdır.                                                                                                                                                             4- İşlem sırasında odanın kapısı kapalı tutulmalıdır.', 'NÜKLEER TIP BÖLÜM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Acil göz ve vücut duşundan su sızması', '1- Radyoaktif su sızıntısı sonucu bulaş', '1-Nükleer tıp bölüm çalışanları', '1-Uzun süreli atık bekletme odası mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Duş zeminine gidere doğru eğim verilmelidir.                                                                                                               2-Zeminin etrafı radyasyonlu suyun çalışma oratmına yayılmasını önlemek için bariyer yükselti ile çevrilmelidir.                                                                                                                                            3-Duş perdesi bulaş sonrası uzun süreli atık bekletme odasına alınmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1-Gözetimli alanda bulunan hasta hazırlama odası içinde lavabo bulunmaması', '1-Enfeksiyon bulaşı', '1-Nükleer tıp bölüm çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-İnvaziv işlem yapılan alanlarda lavabo,el yıkama ünitesi yapılmalıdır.                                                           2-Musluklar fotoselli olmalı, el ile açılan musluklar kullanılmamalıdır.\n3- El hijyen ekipmanları kolay erişilebilir konumda olmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Radyoaktif madde döküntüsü yada sızıntısı olması', '1-Radyasyona maruziyet sonucu iş kazaları oluşması', '1-Nükleer tıp bölüm çalışanları', '1- Kilitli kurşun kaplı taşıma çantaları mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1-Radyoaktif sızıntı olması durumunda sızıntı olan bölüm boşaltılmalı, en az 10 metre çevre bariyeri kurulmalı, havalandırma sistemi kapatılmalıdır.                                                               2-Radyoaktif döküntü ya da sızıntı olması durumunda ilk müdahale döküntü kiti kullanılarak bölüm çalışanları tarafından yapılmalıdır.                                                                                           3-Yetkili ve eğitimli kişiler tarafından koruycu tulum, maske, gözlük, eldiven ve çizme giyerek bulaş olan bölüm emici malzemeler ile temizlenmelidir.                                                                                                                                                        4-Temizlik işlemi sonrası alanın radyasyon ölçümü yapılmalıdır 2,5 µSv/h  altına düşene kadar bölümde çalışma yapılmamalıdır.', 'NÜKLEER TIP BÖLÜM ÇALIŞANLARI', 'RADYOAKTİF DÖKÜNTÜ OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Atık odalarının kapısı üzerinde radyoaktif işaretlemenin yıpranması ya da düşmesi                                                                                       2- Atık odası kapılarının kilitlenmemesi', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', '1-Kurşun yelek ve trioid gonad koruyucular mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1-Atık odasının kapısı her zaman kilitli tutulmalı,yetkisiz kişilerin odaya girmesi engellenmelidir.                                                                                                                                                                 2-Atık odasına giren çalışanlar kurşun önlük ve trioid gonad koruyucular,  tulum maske gözlük çizme eldiven ile girmelidir.                                                                                                                                                  3-Kapı üstünde bulunan radyoaktif madde etiketinin yıpranması ya da düşmesi durumunda yenisi ile değiştirilmelidir.', 'NÜKLEER TIP BÖLÜM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Dozimetre kullanım sürelerinin aşılması', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', '1- Dozimetreler iki ayda bir ölçüme gönderiliyor.', 1, 0, 1, 10, 7, 70, 'C', '1-Nükleer Düzenleme Kurulunun klavuzuna uygun olarak dozimetreler en geç iki ayda bir  ölçüme gönderilmelidir.                                                                                                                 2-Sonuçlar belgelendirilerek arşivlenmelidir.', 'İŞVEREN V.                                 RKS', '2 AYDA BİR', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Ortam ölçüm cihazlarının kalibrasyonlarının tekrarlanmaması', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', '1- Cihazların kalibrasyonu yapılmaktaıdır.', 1, 0, 1, 10, 7, 70, 'C', '1-Kalibrasyonlar Nükleer Düzenleme Kurulunun belirlediği akredite firmalar tarafından tekrarlanmalıdır.                                                                                                                                                                                                                       2-Alan monitörleri  ve Geiger-Müller cihazı en geç iki yılda bir kalibre edilerek sonuçlar kayıt altına alınmalıdır.', 'İŞVEREN V.                             RKS', '2 YILDA BİR', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- MON.DTPA KIT kullanılması', '1- Maruziyet durumunda ciddi göz tahrişi,nefes darlığı,astım,alerji', '1-Nükleer tıp bölüm çalışanları', '1- Radyoaktif ilaçlar sıcak odada çeker ocak altında hazırlanmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1-İnhalasyon durumunda kişisel solunum cihazı kullanılması gerekmez,solunursa temiz havaya çıkılmalıdır.                                                                                                                                                                              2-Cilde temasta su ve sabunla iyice yıkanmalıdır.                                                                                                                          3-Göze bulaşta en az 15 dakika bol su ile yıkanmalıdır.', 'NÜKLEER TIP BÖLÜM ÇALIŞANLARI', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- MON.MDP KIT kullanılması', '1- Maruziyet durumunda beklenmeyen alerji gelişmesi', '1-Nükleer tıp bölüm çalışanları', '1- Radyoaktif ilaçlar sıcak odada çeker ocak altında hazırlanmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1-Koruyucu gözlük,maske ve labaratuvar önlüğü kullanılmalıdır.                                                                             2-İnhalasyon ve oral maruziyette ilk yardım gerektirecek bir durum beklenmemektedir.Doktora başvurulmalıdır.                                                                                                              3-Cilde temasta su ile iyice yıkanmalıdır.                                                                                                       4-Göze temasta en az 15 dakika bol su ile yıkanmalı irritasyon olursa doktora danışılmalıdır.', 'NÜKLEER TIP BÖLÜM ÇALIŞANLARI', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 27, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- MON.MIBI KIT', '1- Ciltte alerjik reaksiyonlar,Gözde tahriş,yutulması halinde toksisite', '1-Nükleer tıp bölüm çalışanları', '1- Radyoaktif ilaçlar sıcak odada çeker ocak altında hazırlanmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1-Tam yüz koruma teçhizatı, hava filtreli respiratör eldiven,labaratuvar ceketi,galoş,önlük veya tulum kullanılmalıdır.                                                                                                                                                                                                                                                                                                                                                                                                                                2-Solunması halinde temiz havaya çıkılmalıdır.Nefes alamama durumunda suni solunum sağlanmalıdır,nefes almada güçlük çekiliyorsa oksijen verilmeli,doktortor çağrılmalıdır.                                                                                                                                  3-Cilde temastan sonra suyla yıkanmalıdır.Kontamine giysiler tekrar kullanılmadan önce yıkanmalıdır.                                                                                                                                                                                                                                                                                                                                                                                                                                             4-Göze temas halinde gözler derhal en az 15 dakika boyunca bol suyla yıkanmalıdır.                                                                                                                                                                      5-Yutulması durumunda derhal 2 bardak su verilip kusturulmalıdır.Bilincini kaybetmiş kişilere asla ağız yoluyla bir şey verilmemelidir.doktor çağrılmalıdır.', 'NÜKLEER TIP BÖLÜM ÇALIŞANLARI', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 28, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Üniteye alan çalışanları dışında çalışanların girmesi', '1- Kısa süreli radyasyona maruziyet sonucu akut semptomlar', '1-Nükleer tıp bölüm çalışanları', '1- Radyoaktif alan uyarı levhaları mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1-Nükleer tıp bölümüne girişler yetkili olmalı,kapılar açık bırakılmamalıdır.                                                                                               2-Kapıda uyarı ve güvenlik işareti (radyoaktif alan ) olan ve yetkisiz kişilerin girmesi yasaktır levhası asılı olmalıdır.', 'NÜKLEER TIP BÖLÜM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 29, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Çeker ocak tezgahında devrilmeye müsait kurşun blokların bulunması', '1- Malzemenin düşmesine karşın yaralanma riski', '1-Nükleer tıp bölüm çalışanları', NULL, 1, 0, 1, 6, 7, 42, 'D', '1-Kurşun bloklar tam ve eksiksiz olmalı birbiri içerisine kilitlenmiş olmalıdır.                                              2-Blokların çevresi ikinci bir malzeme ile kapatılmalıdır.', 'BRS ŞİRKETİ', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 30, 'BÖLÜM: İYOT TEDAVİ ÜNİTESİ,PET VE CT BÖLÜMÜ', '1- Atık kutularının üzerinde radyoaktif işaretlemenin olmaması', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', '1- Radyoaktif madde kutularında etiket mevcuttur.', 1, 0, 1, 6, 7, 42, 'D', '1-Radyoaktif madde etiketleri görünebilir ve okunabilir boyutta olmalıdır.                                                    2-Yıpranan etiketler değiştirilmelidir.', 'ISS ŞİRKETİ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Yangın alarm butonlarının yetersiz olması                                                           2-Acil yönlendirmelerin net görülmemesi', '1-Acil durumlarda hızlı müdahalenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması', '1-Tüm çalışanlar                      2- Hasta ve hasta yakınları', '1-Yangın sirenleri mevcuttur.                     2-Yönlendirmeler mevcuttur.', 1, 0, 1, 3, 100, 300, 'B', '1-Mutfak alanı içerisinde her koridorda en fazla  60m mesafe için en az 1 tane yangın alarm butonu ve ışıklı ve sesli ikaz sireni bulunmalı, alarm sesi ortam sesinin en az 15 db üstünde olmalıdır.                                                                                                                                                                          2- Yönlendirmeler kapıdan çıkınca direkt görülecek pozisyonda olmalı ve yerden 150 cm yüksekliğe asılmalıdır.                                                                                                                                         3- Yangın algılama sisteminin, yönlendirme sisteminin ve acil anons sisteminin bakımları 6 ayda ve yılda bir periyodik kontrolleri tekrarlanmalıdır.', 'BRS TEKNİK BİRİM', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Acil çıkış kapılarının önüne engel konulması                                              2-Acil çıkış kapılarının iptal edilmesi', '1-Acil durumlarda hızlı tahliyenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması', '1- İlgili kamu çalışanları                                               2- Mutfak yemekhane çalışanları', '1- Acil çıkış kapıları mevcuttur.', 1, 0, 1, 3, 100, 300, 'B', '1-Kapıların önüne engel konulmamalıdır.                                                                                                       2- Ana yemekhanede kapatılan acil çıkış kapısı aktif edilmelidir ve ne maksatla olusa  olsun acil çıkış kapıları kullanıma kapatılmamalıdır.                                                                                                                                                                                      3- Panoların, şaftların, pano odalarının,butonların ve sirenlerin  rahat görünmesini engelleyecek hiçbir malzeme bu cihazların odaların önüne -yanına - yakınına konulmamalıdır.', 'YEMEK FİRMASI   ÇALIŞANLARI', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Topraklama ölçümlerinin yapılmaması, tekrarlanmaması', '1- Elektrik çarpması   sonucu yaralanma, ölüm', '1- İlgili kamu çalışanları                                               2- Mutfak yemekhane çalışanları', '1-Topraklama ölçümleri yapılmaktadır.                                  2- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1- Elektrik tesisatının, panoların, fiş priz sistemlerinin topraklama ölçümleri yıllık olarak yetkili elektrik mühendislerine yaptırılmalıdır.                                                                                                                                                         2- Benmariler dahil tüm elektrikli mutfak ve yemekhane cihazlarının ve taşıma araçlarının gövde topraklama ölçümleri yıllık olarak yaptırılmalı ve kayıt altına alınmalıdır.', 'BRS TEKNİK BİRİM', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Davlumbazlarda yağ birikmesi', '1-Yağ birikimi sonucu yangın çıkması', '1-Tüm çalışanlar                      2- Hasta ve hasta yakınları', '1-Davlumbazlar düzenli aralıkla temizlenmektedir.', 1, 0, 3, 6, 15, 270, 'B', '1-Davlumbazlarda yağ ve kir birikimi olmayacak şekilde  davlumbazlar  günlük temizlenerek yağ ve benzeri yanmaya sebep olabilecek maddelerin birikmesi önlenmelidir.                                                                                                                                                                                       2- Ayda en az bir kez davlumbazlar ve bacaları detaylı temizlenmelidir.', 'ISS TEMİZLİK ÇALIŞANLARI', 'HERGÜN                               BACA TEMİZLİĞİ AYDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Ocaklarda açık alev kullanılması', '1- Yangın çıkması', '1-Tüm çalışanlar                      2- Hasta ve hasta yakınları', NULL, 1, 0, 3, 6, 15, 270, 'B', '1-Ocak etrafında herhangi yanıcı bir madde bulundurulmamalıdır.                                                                             2- Günlük temizlik yapılarak yağ ve benzeri yanmaya sebep olabilecek maddelerin birikmesi önlenmelidir.                                                                                                                                              3- Açık aleve fazla yaklaşılmadan çalışılmalı, elbise tutuşma ihtimali göz önünde bulundurulmalıdır.                                                                                                                                           4- Gaz detektörlerin bakım ve kontrolleri yapılmalıdır.', 'YEMEK FİRMASI   ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1- Seksiyonel kapıda fotosel olmaması', '1-Kapının düşmesi sonucu vücut bölümlerinin ezilmesi, yaralanma', '1-Tüm çalışanlar       \n2-İlgili Kamu personeli', '1- Periyodik kontrol raporu mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1-Seksiyonel kapıya altından çalışan geçerken çalışmasını durduracak şekilde fotosel tertibatı yaptırılmalıdır. \n2-Kapı indirilip kaldırılırken 1 metreden yakın içeride ve dışarıda hiç kimse bulunmamalıdır.\n3-En geç yılda bir kez TS EN 13241+A2, TS EN 12453, TS EN 12604+A1 standartlarına uygun olarak periyodik bakımları tekrarlanmalıdır.', 'BRS TEKNİK BİRİM', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1- Yemek Taşımada kullanılan termoboxların kirli olması', '1-Enfeksiyon hastalıklarına yakalanma', '1-Tüm çalışanlar                      2- Hasta ve hasta yakınları', '1- Termoboxların temizliği günlük yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1- Yemek taşıma için kullanılan  termoboxların içi, dışı günlük temizlenmelidir.                                            2- Termoboxların üzerinde yağ, kir ve toz birikimi önlenmelidir.                                                                    3- Termoboxlar taşıma esnasında streç film ile sarılmalıdır.                                                                                                                        4- Termoboxları taşımak için kullanılan araçlar kirli olmamalıdır.', 'YEMEK FİRMASI   ÇALIŞANLARI        ISS TEMİZLİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Davlumbaz  söndürme sisteminin periyodik kontrollerinin yapılmaması', '1-Yangın çıkması', '1-Tüm çalışanlar                      2- Hasta ve hasta yakınları', '1-Davlumbazlarda otomatik yangın söndürme sistemi mevcuttur.', 1, 0, 3, 2, 40, 240, 'B', '1-Davlumbazlardaki otomatik söndürme sisteminin aylık kontrolleri yapılmalı, en geç yılda bir kez TS ISO 11602-2 standardına göre periyodik kontrol yapılmalıdır.\n2- 4 yılda bir hidrostatik basınç testi yapılmalı, içindeki söndürme maddeleri yenilenmelidir.', 'BRS TEKNİK BİRİM', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Yangın tüp sayısının yetersiz olması', '1-Yangın çıkması', '1-Tüm çalışanlar                      2- Hasta ve hasta yakınları', '1-Koridorlardaki yangın dolaplarında yangın tüpü mevcuttur.', 1, 0, 3, 2, 40, 240, 'B', '1- Yağ bulunan depoların önünde ve yağ kullanılan alanların önünde  köpüklü ya da kuru kimyevi tozlu söndürme cihazları konulmalıdır.                                                                                              2- Yağ ya da sıvı madde yangınlarında su kesinlikle kullanılmamalıdır.                                                                                                                                                                        3-Yangın dolaplarının kontrolleri  ve su testi Ayda 1 düzenli olarak yapılmalıdır.', 'BRS TEKNİK BİRİM', '2 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Mutfak ve Yemekhane personelinin aynı kıyafeti hastane genelinde kullanması', '1-Enfeksiyon hastalıklarına yakalanma', '1-Tüm çalışanlar                      2- Hasta ve hasta yakınları', '1-Yemekhane ve mutfak  personeli önlük, maske ve bone kullanmaktadır.', 1, 0, 3, 10, 7, 210, 'B', '1-Yemekhane ve mutfak  personeli  iş kıyafetini ve ayakkabı/terliğini sadece çalışma alanında kullanmalı, bu ekipmanlar ile çalışma alanı dışına çıkılmamalıdır.                                                                                                                                                  2- Yemekhane ve mutfak  personeli önlük bone ve eldiven kullanmadan çalışmamalıdır.', 'YEMEK FİRMASI   ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Kaygan zemin', '1-Kayma, düşme sonucu yaralanma', '1- İlgili kamu çalışanları                                               2- Mutfak yemekhane çalışanları', '1-Zemin kayma veya düşmeyi önleyecek şekilde uygun malzeme ile kaplanmıştır.', 1, 0, 6, 2, 15, 180, 'C', '1-Çalışma alanlarında dökülen malzemeler veya diğer sebeplerden ötürü kayganlaşmış zeminler ya da geçitler derhal temizlenmeli ve kurulanmalıdır.                                                        2-Temizlik sonrası uyarı levhaları konulmalıdır.                                                                                             3-Çalışanlar ve mutfağa giren ilgili tüm personel kauçuk tabanlı kaymaz ayakkabı giymelidir.', 'ISS TEMİZLİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1- Soğuk hava deposunda acil kapı açma butonunun olmaması', '1-Mahsur kalma sonucu hipotermi geçirme', '1-Soğuk hava deposuna giren çalışanlar', '1-Soğuk odaların içerisinde alarm butonu mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Soğuk hava depolarında  kapı kolunun arızalanmasına karşı, içeriden açılabillir ilave acil kapı açma butonu takılmalıdır.                                                                                                                                                                                                   2- Acil kapı açma butonu ve alarm butonu erişilebilir yükseklikte olmalı ve önüne malzeme konulmamalıdır.                                                                                                                                           3- Acil kapı açma butonu ve alarm sistemi karanlıkta görülebilir şekilde işaretlenmiş olmalıdır.', 'BRS TEKNİK BİRİM', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Yemek yapılan ve dağıtılan alanların kirli olması, yağ birikimi olması', '1-Enfeksiyon hastalıklarına yakalanma', '1-Tüm çalışanlar                      2- Hasta ve hasta yakınları', '1-Ortam temizliği günlük yapılmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1-Paslanmaz tezhgahlar, benmariler ve kullanılan aletler günlük olarak temizlenmelidir.                                                                                                                                                     2-Zemin günlük olarak düzenli temizlenmeli , duvar yüzeyleri haftalık olarak düzenli  temizlenmeli  ve  asma tavan aylık olarak  düzenli temizlenmelidir.', 'ISS TEMİZLİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', '=', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Fayansların kirli olması\n2-Fayansların kırık olması', '1-Enfeksiyon          2-Yaralanma', '1-Tüm çalışanlar                      2- Hasta ve hasta yakınları', '1-Duvarlar kolay temizlenebilir malzemeden yapılmıştır.', 1, 0, 3, 3, 15, 135, 'C', '1-Pişirme alanı arkası paslı duvar fayansları yenilenmelidir. Fayans derzlerinde yağ birikimini önlemek için fayans ebatları maksimum büyüklükte seçilip  fayans derz sayıları minumuma indirilmelidir.                                                                                                         2- Kırık fayanslar değiştirilmelidir.                                                                                                               3-Rutubetli duvar yüzeyleri boyanmalıdır.                                                                                                               4- Fayanslarda yağ birikimi önlenmeli günlük oralak temizlenmeldir.', 'BRS TEKNİK BİRİM', '3 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Prizlerin etanj olmaması', '1- Elektrik çarpması                       2-yangın', '1-Tüm çalışanlar     \n2- İlgili Kamu personeli', '1-Kaçak akım koruma  rölesi mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Elektriğin su, nem ve buhar ile temas ettiği tüm alanlarda elektrik sistemleri, aydınlatmar ve prizler etanj özellikte olmalıdır.', 'BRS TEKNİK BİRİM', '3 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Makina ve ekipmanların elektrik aksamına su veya diğer sıvıların temas etmesi', '1- Elektrik çarpması                       2-Ölüm', '1-Tüm çalışanlar      \n2- İlgili Kamu personeli', '1-Kaçak akım koruma  rölesi mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Mutfakta kullanılan tüm elektrikli aletlerin kabloları çift izalasyonlu olmalıdır.                                        2- Sabit kablolar kablo kanalı içerisine alınmalıdır.                                                                                                         3- Elektrik kabloları sağlam olmalı, ek ya da izole bant ile bantlanmış kısımlar bulunmamalıdır.                                                                                                                                                    4- Elektrikli ekipmanlar su ve kimyasal içerikli ürünlerden uzakta saklanmalı ve kuru elle kullanılmalıdır.', 'BRS TEKNİK BİRİM                        YEMEK FİRMASI   ÇALIŞANLARI', '3 AY                              HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Yükleme rampası (platform asansör) bakımı olmaması', '1-Sıkışma                     2- Yaralanma', '1-Tüm çalışanlar       \n2-İlgili Kamu personeli', 'Yükleme için kullanılan  platform asansör bakımları yapılmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1-Yükleme rampalarının en geç yılda bir kez TS EN 1398 standardına göre yapılmalıdır.                                                                                                                                                                                           2- Yükleme rampalarına araç yanaşırken boşluk kalmamalı, bariyer, kilit sistemi vb. ekipmanlar konulmalıdır.                                                                                                                                       3- Araçlar rampaya yanaşırken kör noktalarda çalışan bulunmamalıdır.                                                     4- Yük indirme, yükleme işleri sırasında yetkisiz kişilerin alana girmesi engellenmeli,  set, bariyer vb. ile alan çevrelenmelidir.', 'BRS TEKNİK BİRİM', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Kızgın yağ, kaynar su kullanılması', '1-Devrilme, dökülme sonucunda el, kol ve ciltte yanıklar oluşması', '1- İlgili kamu çalışanları                                               2- Mutfak yemekhane çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-Kaplar devrilmeyecek şekilde dengeli konulmalıdır.\n2-Kızgın yağ ya da sıcak su kaplarına ısıya dayanıklı eldiven olmadan temas edilmemelidir.\n3-Yağ üzerine su sıçratılmamalıdır.\n4-Önlük, kaymaz tabanlı çizme, ısıya dayanıklı eldiven gibi kişisel koruyucular kullanılmalıdır.', 'YEMEK FİRMASI   ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Çöp kovalarının açık olması', '1-Enfeksiyon', '1- İlgili kamu çalışanları                                               2- Mutfak yemekhane çalışanları', '1-Çöp kovaları mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1-Çöp kovalarının kapağı her daim kapalı olmalı, sineklenme olmayacak şekilde düzenli boşaltılmalıdır.                                                                                                                                      2-Pedalı bozuk olan çöp kovaları onarılmalı veya değiştirilmelidir.                                           3-Atık odalarının kapıları kapalı tutulmalıdır. Kapıya ait hidrolik yay sistemleri sökülmemelidir.', 'YEMEK FİRMASI', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Mutfak çalışanlarının  sağlık kontrollerinin yapılmamış olması', '1- Bulaşıcı hastalıklar ve salgın hastalıkların diğer çalışanlara bulaştırma', '1-Tüm çalışanlar                     3- Hasta ve hasta yakınları', '1-Çalışanların işe giriş raporları ve periyodik kontrolleri yaptırılmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1-Mutfak ve yemekhane çalışanlarının 6 ayda 1 portör muayeneleri yapılmalıdır.\n2- Hepatit taramaları ve akciğer grafileri yılda bir tekrarlanmalıdır.   \n3- Bölüme yeni başlayan çalışanlar sağlık taramaları yapılmadan işe başlatılmamalıdır.                                                                                                                                                                                                           4-Sonucu uygun olmayanlar çalışanlar mutfak yemekhane bölümünde çalıştırılmamalıdır.', 'YEMEK FİRMASI               İŞYERİ HEKİMİ', '6 AYDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Atık yağlar için yeterli kapasitede taşma havuzu olmaması', '1-Kayma, düşme sonucu yaralanma', '1-Tüm çalışanlar        2-İlgili Kamu personeli', '1-Atık yağlar yükseltilmiş zemindedir.', 1, 0, 3, 1, 40, 120, 'C', '1-Atık yağlar için uygun derinlikte ve sızdırmaz, yanmaz ve kıvılcım çıkarmayan malzemeden yapılmış taşma havuzu temin  edilmelidir.', 'YEMEK FİRMASI', '3 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Yetersiz aydınlatma', '1- Çarpma düşme ya da sıcak yüzeylere temas sonucu yaralanma', '1- İlgili kamu çalışanları                                               2- Mutfak yemekhane çalışanları', '1-Aydınlatma ve acil aydınlatmalar mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1-TS EN  12464-1 standardına göre mutfak aydınlatması 500 lux şiddetinde olması sağlanmalıdır.                                                                                                                                                    2-Aydınlatma sisteminin devre dışı kalmasının çalışanlar için risk oluşturabileceği yerlerde keninden beslemeli acil aydınlatma sistemi bulunmalıdır ve bakımları düzenli olarak yapılmalı ve test edilmelidir.                                                                                                                                                                      3- Yemek pişirme ve hazırlık alanlarında her bir ocak için ve her bir tezgah için   en az 1 acil aydınlatma olacak şekilde acil aydınlatma sayısı arttırılmalıdır.', 'BRS TEKNİK BİRİM', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Sıcak yüzeylere temas', '1-Cilt yanıklarının oluşması', '1- İlgili kamu çalışanları                                               2- Mutfak yemekhane çalışanları', NULL, 1, 0, 6, 1, 15, 90, 'C', '1-Sıcak yüzeyler izole edilmelidir.\n2-Sıcak aletlerin üzerinde uyarı işaretleri bulundurulmalıdır.                                                                                                        3-Sıcak mutfak malzemelerinin taşınmasında ısıya dayanıklı eldivenler kullanılmalı, kızartma v.b. Yapılırken yağ sıçramasına karşı önlem alınmalıdır.                                                                                          4- Kızgın yağa su temas etmemesine özen gösterilmelidir.', 'YEMEK FİRMASI', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Kuru gıda depolarında haşere ilaçlamasının olmaması', '1-Sinek, böcek, fare gibi zararlı canlıların çoğalması ve hastalık yayması', '1-Tüm çalışanlar                      2- Hasta ve hasta yakınları', '1-Bir çok alanda ilaçlama kutuları mevcuttur.', 1, 0, 3, 1, 15, 45, 'D', '1-İlaçlama kutusu olmayan kuru gıda depolarına kutular konulmalıdır.                                                        2- 3 ayda 1 zararlının türüne göre ilaçlama yapılmalıdır.\n3- Zararlı canlıların yemekhane ve mutfağa ulaşabilecekleri delik ve açıklıklar kapatılmalıdır.', 'YEMEK FİRMASI', '3 AYDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Gıda maddelerinin ve yemeklerin uygunsuz şartlarda muhafazası, bekletilmesi', '1-Gıda zehirlenmesi', '1-Tüm çalışanlar                      2- Hasta ve hasta yakınları', '1-Bozulma riski olan gıdalar soğuk hava depolarında tutulmaktadır.', 1, 0, 1, 6, 7, 42, 'D', '1-Bozulma riski yüksek olan gıda maddeleri (tavuk et vb.), soğuk hava depolarında muhafaza edilmeli, dış alanda fazla bekletilmemelidir.                                                                                                            \n2-Son kullanma tarihi geçmiş, ambalajı okunmayan, yırtılmış, bombeleşmiş, gözle kontrol edildiğinde hatası bulunan,   etiketsiz, imal ve son kullanma tarihi bulunmayan, etiketi üzerinde ithalat veya üretim izin tarih ve sayısı bulunmayan gıda maddeleri imha edilmeli, kullanılmamalıdır.                                                                                           \n3-Gıda maddeleri kontrol edilmeden kullanılmamalıdır.', 'YEMEK FİRMASI   ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Deforme olmuş zemin', '1-Düşme sonucu yaralanma', '1-Tüm çalışanlar    \n2-İlgili Kamu personeli', '1- Mutfak alanında epoksi zemin mevcuttur', 1, 0, 3, 2, 7, 42, 'D', '1-Yemek pişirme  alanı içerisindeki deforme olmuş zemindeki epoksi yüzeyler tamir edilmelidir.', 'BRS TEKNİK BİRİM', '6 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 27, 'BÖLÜM 1: MUTFAK YEMEKHANE', '1-Ortamın çok soğuk veya çok sıcak olması', '1- Dikkat kaybı, iş kazası ve meslek hastalıklarında artışlar', '1-Tüm çalışanlar      \n2-İlgili Kamu personeli', 'Çalışma ortamı sıcaklığı çok soğuk ya da çok sıcak değildir.', 1, 0, 3, 2, 7, 42, 'D', '1-Çalışma ortamı %35-%75 nem oranında ve 18-24 C derece arasında olması sağlanmalıdır.                                                                                 \n2-Hava akım hızının 0,5 m/sn ortalamada olması sağlanmalıdır.\n3-Çalışma ortamının saatte en az 6-10 kez havalandırılması sağlanmalıdır.', 'BRS TEKNİK BİRİM', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- Patoloji Laboratuvarında havalandırma sisteminin yetersiz olması', '1-Kimyasal madde buharlarının solunması sonucunda meslek hastalıklarının oluşması', '1-Patoloji Lab. Çalışanları                                  2-Diğer çalışanlar', '1-Aspirasyon sistemi mevcuttur.\n2-Havalandırma sisteminin periyodik kontrolü mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1-Formaldehit, Ksilen kullanılan odalara saatlik temiz hava giriş debi ve saysı  arttırılmalı, kimyasal solunum bölgesine ulaşmadan zeminden atılmalıdır.     \n2- Havalandırma sisteminin periyodik kontrolleri havalandırma tesisat projesinde yer alan kriterlere göre en geç yılda bir tekrarlanmalıdır.                                                                                                           3-  Kimyasal buharı ve partiküllere karşı kullanılan hepa filtreler ve karbon filtreler en geç yılda bir kez değiştirilmelidir.                                                                                                                                                                                                             4- Patoloji laboratuvarında formaldehit ve ksilen kullanılan bölümlerin kapıları açık bırakılmamalı, kimyasal madde buharının diğer bölümlere yayılması önlenmelidir.', 'FİRMA        PATOLOJİ ÇALIŞANLARI', 'YILDA 1   HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- Patoloji Laboratuvarında Formaldehitin uygunsuz kullanılması', '1-Kimyasal madde buharlarının solunması ya da teması  sonucunda meslek hastalıklarının oluşması', '1-Patoloji Lab. Çalışanları                                  2-Diğer çalışanlar', '1-Çeker ocaklar mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1- Formaldehit ile yapılan çalışmalar sadece çeker ocak altında yapılmalıdır.                                                                                                                            2- Formadehit kaplarının ağızları kapalı tutulmalı, sadece çeker ocak altında açılmalıdır.                                                                                                                                                              3- Formaldehitin dökülmesi durumunda hemen döküntü kiti kullanılmalı, absorban madde kullanılarak formaldehit buharının çalışma ortamına yayılması önlenmelidir.                                                                                                                                                        4- Formaldehit kullanılan bölümlerde TS EN 143 standadın da ABEK filtreli maske, TS EN 166 gözlük TS EN 13034 Tip 6 kimyasal koruyucu tulum, TS EN 374  nitril eldiven,sıvı geçirmeyen ayakkabı kullanılmalıdır.   \n5- Eksik KKD\'ler temin edilmeli, çalışanlar tarafından eksiksiz kullanılmalıdır.', 'FİRMA                                            (KKD                              DÖKÜNTÜ KİTİ)  PATOLOJİ ÇALIŞANLARI', '2 AY  \n                                            HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- Patoloji Laboratuvarında Formaldehit, Ksilen vb. yanıcı parlayıcı kimyasalların kullanılması', '1-Kimyasal maddelerinin elektrikle teması sonucunda parlama, patlama, yangın çıkması', '1-Çalışanlar                          2- Hasta ve hasta yakınları                      3- Diğer ilgli kişiler', '1-Yangın algılama ihbar sistemleri mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1- Ksilen, Formaldehit vb. parlayıcı kimyasalların bulunduğu bölümlerde fiş, priz,  aydınlatma vb. tüm elektrik tesisatı ve fan motorları kıvılcım çıkarmayan (exproof) özellikte olmalıdır.                                                                                                                                                         2- Bu alanlarda kullanılması zorunlu olmayan hiçbir elektrikli ekipman bulundurulmamalıdır.                                                                                                        \n3- Elektrik kabloları yanmaz kablo kanalı içerisine alınmalıdır.                                                                                                                                                        4- Parlama, yangın oluşmasını engellemek için belirli periyotlarla VOC ölçümleri yaptırılmalıdır.                                                                                                                             \n5-Parlama, yangın oluşabilecek alanlar “Ateşle Yaklaşma” vb. levhalar ile işaretlenmelidir.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1-Formaldehit, Ksilen vb. kimyasalların kullandığı alanlarda sulu söndürme sistemleri kullanılması', '1-Yangının büyümesi sonucu', '1-Çalışanlar                          2- Hasta ve hasta yakınları                      3- Diğer ilgli kişiler', '1-Yangın algılama ihbar sistemleri mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1- Ksilen, Formaldehit vb. kimyasal madde yangınlarında söndürme sistemleri (sprink, yangın dolabı) köpüklü sistem olmalıdır.                                                                                                        2-Kimyasal madde yangınlarında su kesinlikle kullanılmamalıdır.                                                 3- Bölüme 50 kg\'lik köpüklü ya da kuru kimyevi tozlu yangın söndürücü konulmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- Formaldehit kullanmına bağlı maruziyet', '1- Maruziyet durumunda göz cilt iritasyonu', '1-Patoloji Lab. Çalışanları                                  2-Diğer çalışanlar', '1-Bir çok kkd mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1-Gözlerle Temas: Lens takılı ise çıkarmalıdır. Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkanmalıdır.\n2- Ciltle Temas: Kirlenmiş giysiler çıkarılmalı hemen bol su ile yıkanamlıdır. Tahriş devam ediyorsa, doktora danışıılmalıdır. Kirlenmiş giysiler tekrar kullanmadan önce yıkanmalıdır.\n3-Solunum: Kişi açık havaya çıkarılmalıdır. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım aldırılmalıdır.\nYutma: Sadece doktor tavsiyesi üzerine kusturmaya çalışılmalı bir doktor tarafından izin verilmedikçe, bilinçsiz bir kişiye asla ağızdan bir şey vermemelidir.', 'PATOLOJİ ÇALIŞANLARI', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1-Patoloji laboratuvarından diğer bölümlere porsiyonlanmadan gönderilmesi', '1-Kimyasal madde buharlarının solunması ya da teması  sonucunda meslek hastalıklarının oluşması', '1- Çalışanlar', NULL, 1, 0, 3, 6, 15, 270, 'B', '1- 21.10.2025 tarihinde hazırlanan Yöntem Beyan\'ına göre firma tarafından bölümlerde kullanılan formaldehit, patoloji laboratuvarında porsiyonlanarak alanlara  gönderilmelidir.                                                                                                     \n2- Porsiyonlanmış formaldehit kapları, kapalı kaplarda olmalı, kapakları sağlam olmalı, taşıma esnasında açılmamalıdır. \n3- Formaldehit taşıma arabalarında döküntü kiti bulundurulmalıdır. \n4- Sürekli kontrol denetim sağlanmalıdır.', 'FİRMA   LABORATUVAR KONTROL KOMİSYONU', '2 AY               SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- Kişisel Koruyucu ekipmanların eksik olması, kullanılmaması', '1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluşması', '1-Patoloji Lab. Çalışanları                                  2-Diğer çalışanlar', '1- Düzenli aralıklarla ortam temizliği yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1- Kimyasal kullanılan bölümlerde TS EN 143 standardın da ABEK filtreli maske, TS EN 166 gözlük TS EN 13034 Tip 6 anti statik kimyasal koruyucu tulum, TS EN 374  nitril eldiven, sıvı geçirmeyen ayakkabı kullanılmalıdır.                                                                                2- Kan ve vücut sıvıları ile temas olacak uygulamalarda cerrahi eldiven kullanılmalıdır. \n3- Çalışanlara KKD kullanımı ve önemi hakkında eğitim verilmelidir.\n4- Laboratuvar komisyonu tarafından kontrol ve denetim sağlanmalıdır.', 'FİRMA                             İŞ GÜVENLİĞİ UZMANI                               PATOLOJİ ÇALIŞANLARI', '2 AY                          HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- Statik elektrik tedbirlerinin yetersiz olması', '1-Parlama, patlama, yangın çıkması', '1-Patoloji Lab. Çalışanları                                  2-Diğer çalışanlar', NULL, 1, 0, 1, 6, 40, 240, 'B', '1- Bölüm girişine nötralizatör takılmalı, vücuttaki statik elektrik boşaltılarak giriş yapılmalıdır.                                                                                                                                             2- Statik elektriğe sebep olabilecek metal raf, dolap çeker ocak, makine ekipmanlar vb. metal kısımları statik elektriğe karşı topraklanmalıdır.                                                                       3- Çalışanların kişisel koruyucu ekipmanları anti statik özellikte olmalı, statik elektrik oluşturabilecek yünlü vb. kıyafetler giyilmemelidir.', 'FİRMA        PATOLOJİ ÇALIŞANLARI', '3 AY         HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- Patoloji arşivi Kimyasal maddelerin dökülme, saçılması', '1- Cilt yanıkları ve göz hasarı, \n2- Alerjik cilt reaksiyonları,                    3- Solunum yolu tahrişi,\n4- Uzun dönemde kansorejen/ mutajen', '1- Patoloji Lab. Çalışanları', '1- Patoloji laboratuvarında numunelerin saklandığı odada metal dolaplar bulunmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1- Atık kapakları kontrol edilmeli bozuk, tam kapanmayan kaplar kullanılmamalıdır.\n2- Numune saklama alanlarında numuneler havalandırmalı dolaplara ağır olanlar alt raflara, hafif olanlar üst raflara olacak şekilde konulmalıdır.\n3- Atık varillerinin altlarına taşma kapları konulmalıdır.                                                                                                                     4- Numunelerin kaplara boşaltılması esnasında kkdler eksiksiz kullanılmalıdır.', 'FİRMA        PATOLOJİ ÇALIŞANLARI', 'Sürekli\n\n2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- Patoloji arşiv odasında örneklerin açık raflarda ya da zeminde istiflenmesi', '1-Kimyasal madde buharlarının solunması sonucunda meslek hastalıklarının oluşması', '1- Patoloji Lab. Çalışanları', '1- Patoloji laboratuvarında numunelerin saklandığı odada metal dolaplar bulunmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1- Patoloji örnekleri sadece havalandırması olan, kapaklı metal dolaplarda saklanmalıdır.                                                                                                                                                 2- Eksik metal dolaplar temin edilmelidir.                                                                                                            3-Açık raflara ya da zemine patoloji örnek kapları bırakılmamalıdır.                                                   4- Metal dolaplar duvara en az iki noktadan sabitlenmelidir.                                                                        5- Metal dolapların statik elektrik topraklamaları yapılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- Delici Kesici Alet Kullanımı', '1- Kesilme sonucu yaralanma', '1- Patoloji Lab. Çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1 Mikrotom bıçağı kullanılma esnasında EN 388 2016 standartlarına uygun kesilmeye dayanıklı eldiven kullanılmalıdır. \n2- Cerrahi aletlerin temizliğinde malzemeler sterilizasyon birimi tarafından yapılmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- VOC ortam ve kişisel maruziyet ölçümlerinin yapılmamış olması', '1- İş kazlarında, Meslek hastalıklarında artış', '1-Patoloji Lab. Çalışanları                                  2-Diğer çalışanlar', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- VOC ortam ölçümleri akredite kuruluşlara yaptırılmalıdır.                                                                                        2- Ortam ölçümleri yapılırken kişi maruziyetleri de ölçülmelidir.                                                                                               3- Çıkan sonuçlara göre gereken tedbirler alınmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- Kimyasal madde depolarının uygun olmaması', '1-Devrilme dökülme sızıntı durumunda elektrik, kıvılcım kaynağıyla temas parlama, yangın çıkması', '1-Patoloji Lab. Çalışanları                                  2-Diğer çalışanlar', '1-  MSDS\'ler mevcuttur.                                        2- Yangına dayanıklı dolap mevcuttur.                                       3- Depo girişinde döküntü kiti mevcuttur.', 1, 0, 1, 3, 40, 120, 'C', '1- Kimyasal madde deposunda, kimyasal maddeler sızdırmaz toplama hazneli plastik paletler üzerine konulmalı, eksik paletler temin edilmelidir.                                                                                                                                                                    2- Kimyasal madde dolabının statik elektrik topraklaması yapılmalıdır.                                                         3- Kimyasal madde dolabında kimyasallar taşma kaplarının içinde muhafaza edilmelidir.                                                                                                                                                        4- Kimyasallar paletlerin üzerine yüksek istiflenmemeli, dengeli devrilmeyecek şekilde istifleme yapılmalı, en fazla 3 kutu üst üste istiflenmelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- Patoloji laboratuvarında firma tarafından iş güvenliği önlemlerinin yeterince alınmaması', '1-İş kazaları ve meslek hastalıkları meydana gelmesi', '1-Patoloji Lab. Çalışanları', '1-Laboratuvar komisyonu tarafından kontroller yapılmaktadır.', 1, 0, 1, 6, 15, 90, 'C', '1-21.10.2025 tarihinde hazırlanan Yöntem Beyanı\'na göre firma tarafından                                                                                                                             - İşe yeni başlayan çalışanların laboratuvarda maruz kalabilecekleri riskler  ve  bölümde kullanılan cihazlar hakkında eğitim alıp almadıkları,                                                                                                                             - Labaratuvar çalışanlarının kişisel koruyucu ekipmanlarının eksiksiz olarak temin edilip edilmediği,                                                                                                                                         - Labaratuvarda yapılması gereken ortam ölçümlerinin yapılıp yapılmadığı                                                                                                                                    - Çalışanlara periyodik olarak yapılması gereken aşı ve muyayenelerinin yapılıp yapılmadığı kontrol edilmelidir.                                                                                                                2- Sürekli saha denetimi kontrol ve gözetim sağlanmalıdır.', 'LABORATUVAR KONTROL KOMİSYONU', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- Periyodik sağlık kontrollerinin ve sağlık taramalarının yılda bir tekrarlanmaması', '1-Meslek hastalığının gerçekleşmesi erken tanı konulamaması müdahaleye geç kalınması', '1-Patoloji Lab. Çalışanları', '1- Periyodik muayeneler yapılmaktadır.', 1, 0, 1, 6, 15, 90, 'C', '1- Çalışanların, akciğer grafileri, göz muayeneleri, solunum fonksiyon testleri ekg, odyometri ölçümleri, kan ve idrar tahlilleri, ppd testleri  ve işyeri hekiminin talep edeceği diğer tıbbi tetkikler yılda bir kez yapılmalıdır.                                                                                                                                               2- İşe yeni başlayan çalışanlara gerekli tahliller yaptırılmadan işbaşı verilmemelidir.                                                                                                                                   3- Tahlil sonuçları uygun olmayan çalışanlar gerekli tedaviyi alana ve tam iyileşene kadar bölümde çalıştırılmamalıdır.', 'İŞVEREN V.                      İŞYERİ HEKİMİ', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: PATOLOJİ LABORATUVARI', '1- Ksilen kullanımına bağlı maruziyet', '1- Maruziyet durumunda göz cilt iritasyonu', '1-Patoloji Lab. Çalışanları                                  2-Diğer çalışanlar', '1-Bir çok kkd mevcuttur.', 1, 0, 1, 2, 15, 30, 'D', '1-Gözlerle Temas: Lens takılı ise çıkarmalıdır. Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkanmalıdır.\n2- Ciltle Temas: Kirlenmiş giysiler çıkarılmalı hemen bol su ile yıkanamlıdır. Tahriş devam ediyorsa, doktora danışıılmalıdır. Kirlenmiş giysiler tekrar kullanmadan önce yıkanmalıdır.\n3-Solunum: Kişi açık havaya çıkarılmalıdır. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım aldırılmalıdır.\nYutma: Sadece doktor tavsiyesi üzerine kusturmaya çalışılmalı bir doktor tarafından izin verilmedikçe, bilinçsiz bir kişiye asla ağızdan bir şey vermemelidir.', 'PATOLOJİ ÇALIŞANLARI', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 2: TBC LABORATUVARI', '1- TBC Labrotuvarında AARB boyama işlerinde havalandırma sistemi olarak davlumbaz kullanılması', '1-Kimyasal madde buharlarının solunması sonucunda meslek hastalıklarının oluşması', '1-TBC Lab. Çalışanları                                  2-Diğer çalışanlar', NULL, 1, 0, 3, 6, 15, 270, 'B', '1- AARB boyama işleminde, boya havadan ağır olduğu için kirli hava zeminden atılmalı, temiz hava üstten verilecek şekilde aspirasyon sistemi yapılmalıdır.                                                     2-Kimyasal madde buharının çalışma ortamına yayılması önlenmeli,  kimyasal madde buharı solunum bölgesine ulaşmadan zeminden atılmalıdır.                                                                                                    3- Çalışanlar  TS EN 143 standardın da ABEK filtreli maske, TS EN 166 gözlük TS EN 13034 Tip 6 anti statik kimyasal koruyucu tulum, TS EN 374  nitril eldiven, sıvı geçirmeyen aykkabı kullanılmalıdır.', 'FİRMA                                   İŞVEREN V.                                           TBC LAB.  ÇALIŞANLARI', '2 AY                                 HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 2: TBC LABORATUVARI', '1- TBC Labrotuvarında AARB yanıcı parlayıcı boya kullanılması', '1-Kimyasal maddelerinin elektrikle teması sonucunda parlama, patlama, yangın çıkması', '1-Çalışanlar                          2- Hasta ve hasta yakınları                      3- Diğer ilgli kişiler', '1-Yangın algılama ihbar sistemleri mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1- AARB boyasının kullanıldığı bölümde fiş, priz,  aydınlatma vb. tüm elektrik tesisatı ve fan motorları kıvılcım çıkarmayan (exproof) özellikte olmalıdır.                                                                                                                                                         2- Bütün metal yüzey ve ekipmanların statik elektrik topraklamaları yapılmalıdır.                                                                                                                                                       3- Elektrik kabloları yanmaz kablo kanalı içerisine alınmalıdır.                                                                                                                                                        4- Parlama, yangın oluşmasını engellemek için belirli periyotlarla VOC ölçümleri yaptırılmalıdır.                                                                                                                                      5-Parlama, yangın oluşabilecek alanlar “Ateşle Yaklaşma” vb. levhalar ile işaretlenmelidir.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 2: TBC LABORATUVARI', '1- TBC Labrotuvarında AARB boyama işlerinde çakmak kullanımı', '1- Yangın çıkması', '1-Çalışanlar                          2- Hasta ve hasta yakınları                      3- Diğer ilgli kişiler', NULL, 1, 0, 3, 6, 15, 270, 'B', '1- AARB boyama işleminde açık alev (çakmak )kullanılmamalıdır.    \n2- Elektrikli lam ısıtıcı, Kimyasal fiksatif , su banyosu vb. kullanılmalıdr.\n3- Kimyasal maddelerin kullanıldığı alanlarda kimyasal maddenin özelliğine göre köpüklü yangın söndürücü veya KKT yangın söndürücü bulundurulmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 2: TBC LABORATUVARI', '1- AARB boya kullanmına bağlı maruziyet', '1- Maruziyet durumunda göz cilt iritasyonu', '1-TBC Lab. Çalışanları                                  2-Diğer çalışanlar', '1-Bir çok kkd mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1-Gözlerle Temas: Lens takılı ise çıkarmalıdır. Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkanmalıdır.\n2- Ciltle Temas: Kirlenmiş giysiler çıkarılmalı hemen bol su ile yıkanamlıdır. Tahriş devam ediyorsa, doktora danışıılmalıdır. Kirlenmiş giysiler tekrar kullanmadan önce yıkanmalıdır.\n3-Solunum: Kişi açık havaya çıkarılmalıdır. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım aldırılmalıdır.\nYutma: Sadece doktor tavsiyesi üzerine kusturmaya çalışılmalı bir doktor tarafından izin verilmedikçe, bilinçsiz bir kişiye asla ağızdan bir şey vermemelidir.', 'TBC LAB ÇALIŞANLARI', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 2: TBC LABORATUVARI', '1-  TBC Labrotuvarında çay, kahve, su içilmesi, gıda maddeleri bulundurulması', '1-Meslek hastalıklarına yakalanma', '1- TBC Lab. Çalışanları', NULL, 1, 0, 3, 6, 15, 270, 'B', '1- Çalışma ortamında yiyecek ve içecek tüketilmemelidir                                                                                2- TBC malzemelerin saklandığı buzdolaplarına yiyecek içecek konulmamalıdır.                                                                                                                                                 3- Sürekli saha gözetimi kontrol ve denetim sağlanmalıdır.', 'LABORATUVAR KOMİSYONU (KONTROL DENETİM)             TBC LAB.  ÇALIŞANLARI', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 2: TBC LABORATUVARI', '1- TBC Labrotuvarında AARB boyama işlerinde yanıcı kimyasalların lavaboda zeminde birikmesi', '1-Yangın meydana gelmesi durumunda şiddetinin artması', '1-Çalışanlar                          2- Hasta ve hasta yakınları                      3- Diğer ilgli kişiler', '1-Yangın algılama ihbar sistemleri mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1- Atık boya varillerinin altında taşma kapları bulundurlmalı, atık varilleri kilitli olmalıdır.                                                                                                                                                            2-AARB boya bölümüne döküntü kiti temin edilmeli, dökülen boya absorban kullanılarak buharın çalışma ortamına yayılması önlenmelidir.                                                                                    3-  Dökülen boyalar hemen temizlenmeli, lavabo yüzeylerinde ve zeminde birikmesi önlenmelidir.                                                                                                                                 4- Tüm temizlik ekipmanları anti statik özellikte olmalıdır.', 'FİRMA                                TBC LAB.  ÇALIŞANLARI', '2 AY   DÖKÜLME OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 2: TBC LABORATUVARI', '1- Kişisel Koruyucu ekipmanların eksik olması, kullanılmaması', '1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluşması', '1-TBC Lab. Çalışanları                                  2-Diğer çalışanlar', '1- Düzenli aralıklarla ortam temizliği yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1- Kimyasal kullanılan bölümlerde TS EN 143 standardın da ABEK filtreli maske, TS EN 166 gözlük TS EN 13034 Tip 6 anti statik kimyasal koruyucu tulum, TS EN 374  nitril eldiven,sıvı geçirmeyen ayakkabı kullanılmalıdır.                                                                                2- Kan ve vücut sıvıları ile temas olacak uygulamalarda cerrahi eldiven kullanılmalıdır.                                                                                                                                               3- KKD\'ler bölüme girilmeden giyilmelidir.\n4- Çalışanlara KKD kullanımı ve önemi hakkında eğitim verilmelidir.', 'FİRMA                     İŞ GÜVENLİĞİ UZMANI                               TBC LAB. ÇALIŞANLARI', '2 AY                          HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 2: TBC LABORATUVARI', '1-TBC Labrotuvarında numune ekim odasında partiküllerin çalışma ortamına yayılması', '1- TBC partiküllerinin yayılması sonucu hastalıklara yakalanma', '1-TBC Lab. Çalışanları                                  2-Diğer çalışanlar', '1-Oda negatif basınçlıdır.', 1, 0, 3, 3, 15, 135, 'C', '1- Negatif basınçlı odanın, oda içinde ki hava basınç debisi en az yılda bir kez ölçülmelidir.                                                                                                                                            2- Negatif odanın basıncı, kapı açık olduğunda bile dış ortamdan daha düşük olmalıdır.                                                                                                                                                     3- Numune tüplerinin kapakları sürekli kapalı tutulmalıdır.                                                                4- Makineler çalışırken kapakları açılmamalıdır.                                                                                                                  5- Çalışanlar KKD\'lerini eksiksiz kullanmalıdır.', 'FİRMA                             TBC LAB.  ÇALIŞANLARI', 'YILDA 1   HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM 2: TBC LABORATUVARI', '1- Otoklavın periyodik kontrollerinin yapılmaması', '1-Patlama sonucu yangın, uzuv kaybı, kalıcı sağırlık', '1- Tüm laboratuvar çalışanları', NULL, 1, 0, 3, 3, 15, 135, 'C', '1- Otoklavın periyodik kontrolü TS EN 285+A1 ve TS EN 13060+A1 standartlarına göre en geç yılda bir kez yapılmalıdır.                                                                                                                     2- Otoklavın hidrolik basınç deneyleri, en yüksek çalışma basıncının 1,5 katı ile yapılmalıdır.                                                                                                                                                    3- Otoklavın kapı switchleri her zaman aktif olmalı, otoklav çalışırken kapıları açılmamalıdır.                                                                                                                                            4- Otoklav dolum ve boşaltılmasında ısıya dayanıklı eldiven kullanılmalı, eldiven yerde bırakılmamalıdır.', 'FİRMA                             TBC LAB.  ÇALIŞANLARI', 'YILDA 1   OTOKLAV KULLANIMI SIRASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM 2: TBC LABORATUVARI', '1- Periyodik sağlık kontrollerinin ve sağlık taramalarının yılda bir tekrarlanmaması', '1-Meslek hastalığının gerçekleşmesi erken tanı konulamaması müdahaleye geç kalınması', '1- TBC Lab. Çalışanları', '1-Çalışanların periyodik sağlık kontrolleri yapılmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1- TBC çalışanlarının QuantiFERON testi,TDT, İGST, Akciğer filmi, Balgam yayma, Balgam kültürü, Klinik muayeneleri en geç yılda bir kez yapılmalıdır.                                                   2- Tahlil sonuçları uygun olmayan çalışanlar gerekli tedaviyi alana ve tam iyileşene kadar bölümde çalıştırılmamalıdır.', 'İŞVEREN V.                     İŞYERİ HEKİMİ', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 27, 'BÖLÜM 2: TBC LABORATUVARI', '1- TBC Labrotuvarında steril olmayan tüplerin açık poşette bırakılması', '1-Meslek hastalıklarına yakalanma', '1- TBC Lab. Çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Steril olmayan tüpler için kapaklı atık kutuları temin edilmelidir.                                         2- Otoklav poşetleri atık kutularına konulmalı, açıkta bekletilmemeli ve kapakları kapalı tutulmalıdır.      \n3- Kirli tüplerin atık kutularına temas etmemesine dikkat edilmeli, her kullanımdan sonra atık kutusu dezenfekte edilmelidir.', 'FİRMA                             TBC LAB.  ÇALIŞANLARI', '2 AY                      HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 28, 'BÖLÜM 2: TBC LABORATUVARI', '1-TBC Labrotuvarına giriş alanında negatif basıncın ölçülmemesi', '1- TBC partiküllerinin diğer alanlara yayılması sonucu hastalıklara yakalanma', '1-TBC Lab. Çalışanları                                  2-Diğer çalışanlar', '1- Çift kapı giriş sistemi mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Bölüm giriş alanında negatif basıncın hava basınç debisi en az yılda bir kez ölçülmelidir.                                                                                                                                            2- Negatif basınç, kapı açık olduğunda bile dış ortamdan daha düşük olmalıdır.                                                                                                                                                  3- İlk kapı tam kapanmadan, ikinci kapının açılmama sistemi sürekli aktif olmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 29, 'BÖLÜM 2: TBC LABORATUVARI', '1- TBC Laboratuvarında Havalandırma sisteminin periyodik kontrollerinin tekrarlanmaması', '1-Kimyasal madde buharlarının solunması sonucunda meslek hastalıklarının oluşması', '1-TBC Lab. Çalışanları                                  2-Diğer çalışanlar', '1-Havalandırma sisteminin periyodik kontrolü mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1- Havalandırma sisteminin periyodik kontrolleri havalandırma tesisat projesinde yer alan kriterlere göre en geç yılda bir tekrarlanmalıdır. \n2- Partiküllere karşı kullanılan hepa filtreler en geç yılda bir kez değiştirilmelidir.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 30, 'BÖLÜM 2: TBC LABORATUVARI', '1- Ultraviole ışınlarına maruziyet', '1- Yanık,\n2- Cilt kanseri, \n3- Gözde katarakt', '1- TBC Lab. Çalışanları', '1-  UV lambalarının altında kapak bulunmaktadır.', 1, 0, 1, 6, 15, 90, 'C', '1- UV lambaları sayaçlı olmalıdır. Sayaç ömrü tamamladığında değişimi yapılmalıdır.\n2-  UV lambalarının kapakları her zaman takılı olmalıdır. \n3-  UV Lambaları çalışanlar bölümdeyken çalıştırılmamalı, mesai bitiminden sonra çalıştırılmalıdır.                                                                  \n4-UV lambasını kapatmak için odaya girildiğinde kişisel koruyucu ekipmanları kullanılmalıdır.                                                                                                                                        5- UV lambaları Ultraviyole lamba kullanımı hakkında eğitim verilmelidir.', 'FİRMA                             TBC LAB.  ÇALIŞANLARI                  İŞ GÜVENLİĞİ UZAMNI', 'SAYAÇ ÖMRÜ BİTTİĞİNDE DEĞİŞİM                      HERGÜN                                  3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 31, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1- Gram boya bölümünde havalandırma sisteminin yetersiz olması', '1-Kimyasal madde buharlarının solunması sonucunda meslek hastalıklarının oluşması', '1-Gram boya çalışanları                                  2-Diğer çalışanlar', '1-Havalandırma sisteminin periyodik kontrolü mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1- Gram boyama işleminde, boya havadan ağır olduğu için kirli hava zeminden atılmalı, temiz hava üstten verilecek şekilde aspirasyon sistemi yapılmalıdır.                                                                                                                                                2-Kimyasal madde buharının çalışma ortamına yayılması önlenmeli,  kimyasal madde buharı solunum bölgesine ulaşmadan zeminden atılmalıdır.                                                                                                                                                                                3- Gram boya bölümünün kapısı açık bırakılmamalıdır.                                                                           4- Çalışanlar  TS EN 143 standardın da ABEK filtreli maske, TS EN 166 gözlük TS EN 13034 Tip 6 anti statik kimyasal koruyucu tulum, TS EN 374  nitril eldiven, sıvı geçirmeyen ayakkabı kullanılmalıdır.', 'FİRMA                         GRAM BOYA ÇALIŞANLARI', '2 AY                              HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 32, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1-Gram boyama işlerinde yanıcı kimyasalların lavaboda zeminde birikmesi', '1-Yangın meydana gelmesi durumunda şiddetinin artması', '1-Çalışanlar                          2- Hasta ve hasta yakınları                      3- Diğer ilgli kişiler', '1-Yangın algılama ihbar sistemleri mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1- Atık boya varillerinin altında taşma kapları bulundurlmalı, atık varilleri kilitli olmalıdır.                                                                                                                                                                                      2-Gram boya bölümüne döküntü kiti temin edilmeli, dökülen boya absorban kullanılarak buharın çalışma ortamına yayılması önlenmelidir.                                                                                    3-  Dökülen boyalar hemen temizlenmeli, lavabo yüzeylerinde ve zeminde birikmesi önlenmelidir.                       \n4- Tüm temizlik ekipmanları anti statik özellikte olmalıdır.', 'FİRMA                               GRAM BOYA ÇALIŞANLARI', '2 AY            DÖKÜLME SIRASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 33, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1- Gram boya işlerinde yanıcı parlayıcı boya kullanılması', '1-Kimyasal maddelerinin elektrikle teması sonucunda parlama, patlama, yangın çıkması', '1-Çalışanlar                          2- Hasta ve hasta yakınları                      3- Diğer ilgli kişiler', '1-Yangın algılama ihbar sistemleri mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1- Gram boya kullanıldığı bölümde fiş, priz,  aydınlatma vb. tüm elektrik tesisatı ve fan motorları kıvılcım çıkarmayan (exproof) özellikte olmalıdır.                                                                                                                                                         2- Bütün metal yüzey ve ekipmanların statik elektrik topraklamaları yapılmalıdır.                                                                                                                                                                                         3- Elektrik kabloları yanmaz kablo kanalı içerisine alınmalıdır.                                                                                                                                                        4- Parlama, yangın oluşmasını engellemek için belirli periyotlarla VOC ölçümleri yaptırılmalıdır.                                                                                                                                      5-Parlama, yangın oluşabilecek alanlar “Ateşle Yaklaşma” vb. levhalar ile işaretlenmelidir.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 34, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1- Gram boyama işlerinde çakmak kullanımı', '1- Yangın çıkması', '1-Çalışanlar                          2- Hasta ve hasta yakınları                      3- Diğer ilgli kişiler', NULL, 1, 0, 3, 6, 15, 270, 'B', '1- Gram boyama işleminde açık alev (çakmak )kullanılmamalıdır.           \n2- Elektrikli lam ısıtıcı, Kimyasal fiksatif , su banyosu vb. kullanılmalıdr.\n3- Kimyasal maddelerin kullanıldığı alanlarda kimyasal maddenin özelliğine göre köpüklü yangın söndürücü veya KKT yangın söndürücü bulundurulmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 35, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1- Kişisel Koruyucu ekipmanların eksik olması, kullanılmaması', '1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluşması', '1-Mikrobiyoloji Lab. Çalışanları                                  2-Diğer çalışanlar', '1- Düzenli aralıklarla ortam temizliği yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1- Kimyasal kullanılan bölümlerde TS EN 143 standardın da ABEK filtreli maske, TS EN 166 gözlük TS EN 13034 Tip 6 anti statik kimyasal koruyucu tulum, TS EN 374  nitril eldiven, sıvı geçirmeyen ayakkabı kullanılmalıdır.                                                                                2- Kan ve vücut sıvıları ile temas olacak uygulamalarda cerrahi eldiven kullanılmalıdır. \n3- Çalışanlara KKD kullanımı ve önemi hakkında eğitim verilmelidir.', 'İŞVEREN V.                     İŞ GÜVENLİĞİ UZMANI                               MİKROBİYOLOJİ LAB.ORATUVARI ÇALIŞANLARI', '2 AY                          HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 36, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1- Mikrobiyoloji laboratuvarında göz duşu istasyonun etrafının çevrili olmaması', '1- Suyun elektrik ile teması sonucu çarpılma', '1-Mikrobiyoloji Lab. Çalışanları                                  2-Diğer çalışanlar', NULL, 1, 0, 6, 1, 40, 240, 'B', '1- Göz duşu istasyonu, elektrikli cihazlardan uzak korunaklı bir alana taşınmalıdır.                                                                                                                                              2- Göz duşu istasyonun olduğu alana gider yapılmalı, suyun yayılması önlenmelidir.                                                                                                                                                      3-Duşlara sürekli göz ve cilt yıkamaya su sağlanmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 37, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1- Kan transfüzyon merkezinde Elektrik kablolarının uygunsuz olması', '1- Elektrik çarpması', '1-  Kan Transfüzyon merkezi çalışanları', '1-  Topraklama ölçümleri yaptırılmıştır.', 1, 0, 3, 3, 15, 135, 'C', '1- Topraklama ölçümleri yılda bir kez tekrarlanmlaıdır. \n2- Laboratuvarda makinelerin gövde topraklama ölçümleri yıllık yapılmalıdır.\n3- Üçlü priz kullanılmamalı, kullanılacaksa eğer halojen free özellikte kullanılmalıdır.\n4-  Üçlü prizlere üçlü priz takılarak kullanılmamalıdır.                                                                            5- Elektrik kabloları ekli olmamalı, izole bant ile bantlanmış kablolar kullanılmamalıdır.\n6- Cihazların bakım ve kalibrasyonu yılda bir kez  yapılmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 38, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1- Gram boya bölümünde kimyasal madde dolabının statik elektrik topraklamasının olmaması', '1-Statik elektrik oluşması sonucu parlama, yangın meydana gelmesi', '1-Gram boya çalışanları                                  2-Diğer çalışanlar', '1- Kimyasal madde dolabı yangına dayanıklı malzemeden yapılmıştır.', 1, 0, 3, 3, 15, 135, 'C', '1- Kimyasal madde dolabına statik elektrik topraklaması yapılmalıdır.                                       2- Dolap içine boyalar taşma kaplarının üzerine konulmalıdır.                                                 3- Dolap üzerinde boya birikmesi önlenmeli, dökülen boyalar kurumadan temizlenmelidir.', 'FİRMA                         GRAM BOYA ÇALIŞANLARI', '3 AY                              HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 39, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1- Periyodik sağlık kontrollerinin ve sağlık taramalarının yılda bir tekrarlanmaması', '1-Meslek hastalıklarına yakalanma', '1-Mikrobiyoloji Lab. Çalışanları', '1-Çalışanların periyodik sağlık kontrolleri yapılmaktadır.', 1, 0, 1, 6, 15, 90, 'C', '1- Çalışanların, akciğer grafileri, göz muayeneleri, solunum fonksiyon testleri ekg, odyometri ölçümleri, kan ve idrar tahlilleri, ppd testleri  ve işyeri hekiminin talep edeceği diğer tıbbi tetkikler yılda bir kez yapılmalıdır.                                                                                                                                               2- İşe yeni başlayan çalışanlara gerekli tahliller yaptırılmadan işbaşı verilmemelidir.                                                                                                                                   3- Tahlil sonuçları uygun olmayan çalışanlar gerekli tedaviyi alana ve tam iyileşene kadar bölümde çalıştırılmamalıdır.', 'İŞVEREN V.                     İŞYERİ HEKİMİ', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 40, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1- Mikrobiyoloji laboratuvarında firma tarafından iş güvenliği önlemlerinin yeterince alınmaması', '1-İş kazaları ve meslek hastalıkları meydana gelmesi', '1-Patoloji Lab. Çalışanları', '1-Laboratuvar komisyonu tarafından kontroller yapılmaktadır.', 1, 0, 1, 6, 15, 90, 'C', '1-21.10.2025 tarihinde hazırlanan Yöntem Beyanı\'na göre firma tarafından                                                                                                                             - İşe yeni başlayan çalışanların laboratuvarda maruz kalabilecekleri riskler  ve  bölümde kullanılan cihazlar hakkında eğitim alıp almadıkları,                                                                                                                             - Labaratuvar çalışanlarının kişisel koruyucu ekipmanlarının eksiksiz olarak temin edilip edilmediği,                                                                                                                                         - Labaratuvarda yapılması gereken ortam ölçümlerinin yapılıp yapılmadığı                                                                                                                                    - Çalışanlara periyodik olarak yapılması gereken aşı ve muyayenelerinin yapılıp yapılmadığı kontrol edilmelidir.                                                                                                                2- Sürekli saha denetimi kontrol ve gözetim sağlanmalıdır.', 'LABORATUVAR KONTROL KOMİSYONU', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 41, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1- Mikrobiyoloji laboratuvarı girişindeki kapının temas ile açılması', '1- Enfeksiyon ve bulaşıcı hastalıklara yakalanma', '1-Mikrobiyoloji Lab. Çalışanları                                  2-Diğer çalışanlar', NULL, 1, 0, 3, 3, 7, 63, 'D', '1- Laboratuvar kapıları çalışanların açmak için temas etmeyeceği şekilde değiştirlmeli, kayar kapı vb. sistemler kullanılmalıdır.      \n2-Yetkisiz kişilerin giriş çıkışları engellenmelidir.           \n3- Laboratuvar kapıları her gün dezenfekte edilmelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 42, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1- Çalışanların kullanılan kimyasallar hakkında bilgi sahibi olmaması', '1- İş kazlarına doğru müdahale edilememesi sonucu şiddetin artması', '1-Mikrobiyoloji Lab. Çalışanları                                  2-Diğer çalışanlar', '1-MSDS\'ler asılmıştır.', 1, 0, 3, 3, 7, 63, 'D', '1- Kullanılan tüm kimyaslların malzeme güvenlik bilgi formları çalışanların görebileceği şekilde asılı olmalı, yıpranan okunmayan msds ler değiştirilmelidir. \n2- Yeni kimyasal madde eklenmesi durumunda msds asılmalı, çalışanlar bilgilendirilmelidir.                                                                                                                                   3- Çalışanlar malzeme güvenlik bilgi formları hakkında eğitim verilmelidir.', 'FİRMA                                   İŞ GÜVENLİĞİ UZMANI', 'SÜREKLİ              YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 43, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1- Elektrikli cihazların koruyucularının yetersiz olması', '1- Hareketli kısımlara kapılma sonucu el kol parmak yaralanmaları', '1-Mikrobiyoloji Lab. Çalışanları                                  2-Diğer çalışanlar', '1- Bir çok cihazda akım kesici switch bulunmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1- Mikrobiyoloji laboratuvarında kullanılan tüm elektrikli cihazların kapı akım kesici switchleri aktif olmalıdır.                                                                                                                             2- Çalışanların cihazların operasyon bölgelerine ellerini sokabilecekleri alanlara switchli kapaklar takılmalıdır.                                                                                                                                    3- Cihazın içindeki numune kaplarının devrilmesi, sıkışması vb. durumlarda elektrik akımı kesilmeden müdahale edilmemelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 44, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1- Genetik laboratuvarında giriş alanında sivri uçlu yapıların bulunması', '1- Sivri kısımlara çarpma sonucu yaralanma', '1- Genetik laboratuvarı çalışanları', NULL, 1, 0, 3, 6, 3, 54, 'D', '1- Keskin ya da sivri yüzeyler oval hale getirilmelidir.\n2- Keskin ya da sivri yüzeyler yumuşak bir malzeme ile kaplanmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 45, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1-Dinlenme alanının olmaması', '1- Psikososyal Risk', '1- Aferez Çalışanları', NULL, 1, 0, 3, 6, 3, 54, 'D', '1- İcap nöbeti tutan personellere ait dinlenme odası oluşturulmalıdır', 'TEKNİK HİZMETLER MÜDÜRLÜĞÜ', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 46, 'BÖLÜM 3: MİCROBİYOLOJİ LABORATUVARI', '1-Ergonominin yetersiz oluşu', '1-Postür bozuklukları sonucunda kas-iskelet sistemi hastalıkları,  sırt, boyun, bel ve baş ağrıları', '1- Genetik kan alma çalışanları', '1- Genetik kan alma ünitesinde kan alma koltuğu mevcut', 1, 0, 1, 6, 7, 42, 'D', '1- Kan alma ünitesine bebek ve çocuk hastalardan kan alım esnasında çalışanın uygun pozisyon alabilecek şekilde sedye vb. kullanılmalıdır.       \n2- Sedye yüksekliği çalışanın rahatsız edici göz ve baş hareketleri ihtiyacını en aza indirecek şekilde olmalıdır.                      \n3- Sandalyeler ergonomik tasarıma sahip olmalı, gerekli hallerde ayak desteği kullanılmalıdır.', 'TEKNİK HİZMETLER MÜDÜRLÜĞÜ', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: ATIK', '1-Atık araçlarının hızlı kullanılması', '1-Atık araçlarının çalışanlara  çarpması sonucu yaralanma', '1- Çalışanlar                                2- Hastalar ve hasta yakınları        3- Diğer ilgili kişiler', '1-Atık araçları kapalı kasadır.', 1, 0, 3, 6, 15, 270, 'B', '1-Atık araçlarına hız sınırlayıcılar takılmalıdır. \n2-Tıbbi atıkları toplayan araç sayısı arttırılmalıdır.                                                                        3- Otopark içi ve kapalı alanlarda 20 km/s ve hastane bahçesinde 30 km/s hız sınırı limitleri aşılmamalıdır.\n3-Trafik kurallarına riayet edilmelidir.', 'FİRMA                         ATIK ARACI  ŞOFÖRÜ', '2 AY  \n                            HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: ATIK', '1-Atık toplayan çalışanların mesleki yeterliliklerinin olmaması', '1- Enfeksiyon kapma sonucu hastalıklara yakalanma', '1- Çalışanlar', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Atık toplayan çalışanlar \"Sağlık Kuruluşları Kaynaklı Tıbbi Atık Toplayıcısı (Seviye 3)\"mesleki yeterlilik belgesine sahip olmalıdır.                                                                                              2- Mesleki yeterlilik belgesi eksik olan çalışanlar mesleki yeterlilik merkezlerine gönderilerek belge almaları sağlanmalıdır.                                                                                                                      3- İşe yeni alınan çalışanlar mesleki yeterlilik belgesine sahip olan kişilerden seçilmelidir.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: ATIK', '1-Atık bekleme odalarının ve geçici atık depolarının kapılarının açık bırakılması', '1- Enfeksiyon kapma sonucu hastalıklara yakalanma', '1-Çalışanlar', '1.Uyarı tabelaları bulunmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1- Atık bekleme odalarının kapıları açık bırakılmamalı her zaman kilitli olmalıdır. \n2- Atık bekleme odalarına kartlı giriş sistemi yapılmalı, yetkisiz kişilerin girişi önlenmelidir.\n3- Düşen, okunmayan uyarı levhaları değiştirilmelidir.                                                                                                    4- Sürekli saha gözetimi, kontrol ve denetim sağlanmalıdır.', 'FİRMA                           ATIK VE TEMİZLİK ÇALIŞANLARI', '2 AY    \n                          HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: ATIK', '1- Atık toplayan çalışanların kişisel koruyucu ekipman kullanmaması, ekipmanların uygun olmaması', '1-Atık toplayan çalışanların, diğer çalışanlar tarafından fark edilememesi', '1-Çalışanlar', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Atıkların toplanması, taşınmasında görevlendirilen çalışanlar, çalışma sırasında eldiven, koruyucu gözlük, maske kullanır, çizme ve turuncu renkli özel koruyucu kıyafet giymelidir.                                                                                                                                                       2- Eksik malzemeler temin edilmeli, çalışanlar tarafından kullanılması sağlanmalıdır.                                                                                                                                                                     3- Tulumlar çalışan başına en az 2 adet temin edilmeli, kullanılan tulum yıkamya gönderilmeli, temiz olan kullanılmalıdır.                                                                                                            4- Tulumlar üzerinde  \"TIBBİ ATIK ÇALIŞANI\" yazısı bulunmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: ATIK', '1-Atık taşıma araçlarının belirlenmiş güzergahları kullanmaması', '1- Enfeksiyon kapma sonucu hastalıklara yakalanma', '1- Çalışanlar', '1. Atık konteynırların da renkli kodlama mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Atıkların bekleme odalarından, geçici depolama alanlarına götürülürken sadece atık asaönsörleri kullanılmalıdır.\n2-Atık konteynırları temiz alanlardan, insan ve hasta trafiğinin yoğun olduğu bölgelerden taşınmamalıdır.\n3- Atık asansörleri işaretlenmeli, uyarı levhaları asılmalıdır.\n4- Atıklar geçici depolama alanlarından, merkez atık depolama alanına taşınırken sadece Yöntem Beyan\'ında belirlenmiş güzergah kullanılmalıdır.', 'ATIK DEPO ÇALIŞANLARI  ATIK ARACI ŞOFÖRLERİ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: ATIK', '1- Atık araçların geri gidişlerde sesli ışıklı sinyallarinin çalışmaması', '1- Atık araçlarının çalışanlara  çarpması sonucu yaralanma', '1- Çalışanlar                                2- Hastalar ve hasta yakınları        3- Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 15, 135, 'C', '1-Atık toplayan araçların geri gidişlerde sesli ışıklı sinyalleri her zaman aktif olmalıdır.                                                                                                                                                                       2-Şoför geri gidişlerde aynalardan mutlaka kör noktaları kontrol etmeli etrafta hiç kimsenin olmadığından emin olmalıdır.                                                                                                                 3-Hastane içinde belirlenen hız limitlerine uyulmalıdır.', 'FİRMA                       ATIK ARACI  ŞOFÖRÜ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: ATIK', '1- Merkez geçici depolama alanında atıkların dışarıda bırakılması', '1- Sabotaj sonucu yaralanma, ölüm', '1-Çalışanlar', '1- Evsel atık, Tıbbi atık ve geri dönüşüm atıkları günlük toplanmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1- Tehlikeli atıklar geçici depolama alanı dışında kesinlikle depolanmamalıdır.   \n2- Tehlikeli atıklar geçici depolama alanında en fazla 180 gün süreyle geçici olarak depolanacak büyüklükte olmalıdır.\n3-Merkez geçici depolama alanında gece vardiyası için güvenlik görevlisi tarafından kontrolü sağlanmalıdır.\n4-Her atık türünün depolanacağı bölme üzerinde; atık türünü belirten levhalar hasar görmesi durumunda yenilenmelidir.', 'FİRMA                           MERKEZ                      ATIK DEPO ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: ATIK', '1- Atık konteynırlarının geçici atık depolarının dışında bırakılması', '1- Enfeksiyon kapma sonucu hastalıklara yakalanma', '1- Çalışanlar', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Atık konteynırları, asansör önlerinde, koridorlarda vb. yerlerde bekletilmemeli, geçici atık depolarına konulmalıdır.                                                                                                                                     2- Konteynırların kapakları açık bırakılmamalıdır.                                                                                             3- Atık konteynırlarının kapı, duvar asansör vb. yüzeylere temas etmemesine özen gösterilmelidir.                                                                                                                                                                 4-Temas eden yerler hemen dezenfekte edilmelidir.', 'FİRMA                            ATIK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: ATIK', '1- Atık bekleme odalarının ve geçici depolama alanlarının temiz olmaması', '1- Enfeksiyon kapma sonucu hastalıklara yakalanma', '1- Çalışanlar', '1-Günlük temizlik yapılmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Atık bekleme odalarında  ve geçici depolama alanlarının atıklar 48 saatten fazla bekletilmemelidir.                                                                                                                                                                        2- Atık bekleme odalarında  ve geçici depolama alanlarının atıklar poşetler yere bırakılmamalı, atık tipine uygun konteynırlara atılmalıdır.                                                                          3- Atık bekleme odaları   ve geçici depolama alanlarının yüzeyleri, kapıları, kapı kolları, duvarları her gün dezenfektanlar ile temizlenmelidir.                                                                                 4- Geçici depolama alanında oda ısısı +4 °C olması sağlanamalıdır.                                                                     5- Atık bekleme odalarında havalandırma sistemi her zaman aktif olmalı, koku oluşması önlenmeldir.', 'FİRMA                           ATIK VE TEMİZLİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: ATIK', '1- Firmanın atıkların toplanması, depolanması, taşınması vb. işlerde iş güvenliği tedbirlerini almaması', '1- İş kazası ve bulaşıcı hastalıklarda artış', '1-Çalışanlar', '1-Atık türüne uygun konteynır ve torbalar mevcuttur.   2- Atık bekleme odaları ve geçici depolama alanları mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Atık odalarının günlük olarak temizlenip, dezenfekte edildiği kontrol edilmelidir. \n2- Bekleme odasından alınan atıkların belirlenmiş güzergah ve asansörlerden geçici depolama alanlarına götürüldüğü kontrol edilmelidir. \n3- Atık konteynırlarının boşaltıldıktan sonra dezenfekte edilip edilmediği kontrol edilmelidir. \n4- Atıkların hergün belirlenmiş zaman aralığında toplanıp toplanmadığı kontrol edilmelidir.\n5-Atık işlerinin iş güvenliği kurallarına uygunluğunu sağlamak için sürekli saha gözetimi kontrol ve denetim sağlanmalıdır.', 'ATIK KOMİSYONU (KONTROL DENETİM)', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: ATIK', '1- Tehlikeli atık geçici depolama alanının uygunsuz olması', '1.Parlama , patlama yangın meydana gelmesi', '1-Çalışanlar', '1- Aydınlatma exproof özelliktedir.', 1, 0, 3, 6, 7, 126, 'C', '1- Yanıcı tehlikeli atık depolama odasında kullanılan tüm elektrik sistemleri exproof özellikte olmalıdır.\n2- Patlamadan korunma dokümanı hazırlanmalıdır.\n3- Metal kısımların kapı vs. statik elektrik topraklamaları yapılmalıdır.\n4- Elektrik kabloları, yanmaz kablo kanalı içine alınmalıdır.\n5- Exproof ekipmanların periyodik kontrolleri en geç yılda bir yapılmalı ve belgelenmelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: ATIK', '1-Tehlikeli atıkların uygunsuz taşınması', '1-Tehlikeli atıkların dökülmesi devrilmesi sonucu iş kazaları meydana gelmesi', '1-Çalışanlar', NULL, 1, 0, 3, 3, 7, 63, 'D', '1-Tehlikeli atık varil ya da kaplarının ağızları kapalı tutulmalı, kilitleri varsa kilitlenmelidir.                                                                                                                                                                 2- Tehlikeli atıklar toplandıktan sonra araçta ya da diğer alanlarda bekletilmemeli hemen merkez geçici depolama alanına götürülmelidir.                                                                                          3- Tehlikeli atıklar etrafı kapalı kasalarda taşınmalı, kasaların yanında döküntü kiti bulunmalıdır.                                                                                                                                                                            4-Tehlikeli atıklar sabitlenerek taşınmalıdır.', 'FİRMA                            ATIK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: ATIK', '1- Atık konteynırlarının dezenfekte edilmeden tekrar kullanıma gönderilmesi', '1- Enfeksiyon kapma sonucu hastalıklara yakalanma', '1-Çalışanlar', NULL, 1, 0, 3, 3, 7, 63, 'D', '1-Atık konteynırları boşaltıkdıtan sonra dezenfektanlarla yıkanmalıdır.\n2- Yıkanmış konteynerlar kimyasaldan arındırılmış şekilde alana temiz ve kokusuz teslim edilmelidir.\n3- Atık komisyonunun kontrolünden geçmeyen temizlenmiş konteynerlar alana verilmemelidir.', 'FİRMA', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: ATIK', '1- Merkez geçici depolama alanında tehlikeli atıkların uygunsuz yerleşimi', '1-Yangın meydana gelmesi', '1- Çalışanlar                                2- Hastalar ve hasta yakınları        3- Diğer ilgili kişiler', '1- Döküntü kiti mevcuttur.                                                              2- Oda girişinde 50 kg\'lik yangın söndürme tüpü mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1. Odada havalandırma sistemi olmalıdır.\n2. Yanıcı atıkları yüksek istiflenmemelidir. En fazla 2 varil üst üste konmalıdır.\n3. Zemine dökülen atıklar bekletilmemeli, hemen temizlenmelidir.\n4. Dökülme Kiti bulundurulmalıdır.\n5. Tehlikeli atıklar paletlerin üzerine istiflenmemeli, atık kapları taşkan havuzlarına konulmalıdır.', 'FİRMA                           MERKEZ                      ATIK DEPO ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: ATIK', '1- Atıkların karıştırılması', '1- Enfeksiyon kapma sonucu hastalıklara yakalanma', '1-Çalışanlar', '1. Atık konteynırların da renkli kodlama mevcuttur.', 1, 0, 3, 3, 3, 27, 'D', '1- Atıklar renk kodlarına göre ayrıştırılmalıdır.\nMAVİ: Kâğıt / Karton atıkları için,\nSARI: Plastik atıklar için sarı,\nYEŞİL: Cam atıklar için,\nGRİ: Metal atıklar için,\nKAHVERENGİ: Organik atıklar için,\nSİYAH: Geri dönüşemeyen atıklar için,\nTURUNCU: Tıbbi atıklar için poşetlerde kırmızı, kova konteynerlerde turuncu,\nŞEFFAF: Tehlikeli atıklar ve elektronik atıklar için                                                                             2- Atık ayrıştırılması konusunda tüm çalışanlara eğitim verilmelidir.', 'İŞ GÜVENLİĞİ UZMANI \nÇALIŞANLAR', '3 AY\n\nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Çalışanların fazla mesai ile çalışması                                                          2- İş yükünün fazla olması', '1-Dikkatin azalması, yorgunluk, uykusuzluk, sonucunda iş kazalarının oluşması', '1- Yoğun bakım ve Pacu çalışanları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1-Tüm yoğun bakım ve PACU ünitesinde  fazla mesai süreleri uygun koşullarda planlamalıdır.                                                                                                                                             2- 24 saatlik nöbetten sonra çalışanlara en az 24 saat dinlenme süresi verilmelidir.                               3- Yoğun bakımlarda 3. basamak için her iki hastaya bir çalışan, 2. basamak için her üç hastaya bir çalışan, 1. basamak için her dört hastaya bir çalışan görevlendirilmelidir. (Hekimdışı personel)                                                                                                                                                  4-Çalışanların düzenli sağlık kontrolleri yapılmalı ve yeterli dinlenme süreleri sağlanmalıdır.                                                                                                                                                                                                                                                                                                                                                    5- Yorgunluk ve stres yönetimi için psikososyal destek programları sağlanmalıdır.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'acik', 'Hastane geneli yapılan risk analizi değerlendirmesi kapsamında daha ayrıntılı ele alınmıştır. (Bkz. Hastane Geneli Risk Analizi)', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1- Pendant üzerindeki prizlerin ya da jakların yerinden çıkması', '1- Elektrik çarpması ya da gaz sızıntısı sonucu yaralanma', '1- Yoğun bakım ve Pacu çalışanları                                              2- Hasta ve Hasta Yakınları', '1-Talep halinde arızalar için kurum içerisinde firma teknik birim tarafından takip edilmektedir.', 1, 0, 3, 3, 15, 135, 'C', '1- Bozuk yerinden çıkmış priz ve jaklar kullanılmamalı, değiştirilmelidir.                                                                                                              2- Fişler prizlerden çekilirken kablodan asılarak çekilmemeli, fişten tutarak çıkarılmalıdır.                                                                                                                                                                         3- Gaz hortumları zorlanarak takılmamalı, jaka dik oturtularak takılmalıdır.                                                                                                                       4- Jaklar kullanılmadığında tam kapatılmalıdır.      \n5- Hortum ağırlığının jakları zorlamaması için destekler kullanılmalıdır.', 'FİRMA         (BİNA VE ARAZİ HİZMETLERİ KOMİSYONU)                               YOĞUN BAKIM PACU ÇALIŞANLARI', '30.12.2026 ARIZA OLMASI DURUMUNDA                                                SÜREKLİ KONTROL', 3, 3, 15, 135, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Elektrikli medikal cihazlarda (Mekanik ventilatör ,CPAP/BiPAP cihazları,Aspiratör cihazı,Hasta monitörü, İnfüzyon pompaları, Defibrilatör vb.) kablolarının hasarlı veya dağınık olması', '1- Kablolara takılıp düşme sonucu yaralanma                                2- Elektrik çarpması', '1- Yoğun bakım ve Pacu çalışanları                                   2- Hasta ve Hasta Yakınları', '1-Cihazların yılda bir kez kalibrasyonları yapılmaktadır.                                      2-30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Tüm yoğun bakım ve PACU ünitesinde cihazların periyodik bakım ve kalibrasyonların yapılmalı, yılda bir kez tekrarlanmalıdır.                                                                                                                                                       2- Cihazların gövde topraklama ölçümleri yapılmalıdır.                                                                             3- Kullanım öncesi kablo ve priz kontrolleri yapılmalı, hasarlı izalasyonu bozulmuş kablolar, kırk yerinden çıkmış prizler değiştirilmelidir.                                                                                                                                                                                                                                                                                                                                                                                                                                               4- Cihazlar yeterli mesafeye yerleştirilmeli, kablolar dağınık olmamalıdır.', 'FİRMA                 (BİNA VE ARAZİ HİZMETLERİ KOMİSYONU)                               YOĞUN BAKIM PACU ÇALIŞANLARI', '30.09.2027 ARIZA OLMASI DURUMUNDA\n                                                   SÜREKLİ KONTROL', 1, 3, 15, 45, 'D', 'acik', 'Her yıl tüm cihazların kalibrasyonu, periyodik bakımları ve topraklama ölçümleri düzenli olarak yapılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Çalışanların mutfak/dinlenme alanlarında elektrikli ev aletleri kullanımı', '1-Yangın sonucu yaralanma                                                  2-Elektrik çarpması', '1- Yoğun bakım ve Pacu çalışanları                                   2- Hasta ve Hasta Yakınları', '1-30 mA kaçak akım röleleri mevcuttur.                           2-Elektrik tesisatı ve topraklama ölçümü mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Mutfak olarak tanımlanmış alanlarda sadece çay ve kahve makinesi kullanılmalı, bunların dışındaki aletlerin kullanımı yasaklanmalıdır.                                                                                                          2- Sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.                                                                                                                         3- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.                                                                                                                4- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.                                                                                  5- Elektrikli cihazlara ıslak elle temas edilmemelidir.', 'FİRMA                 (BİNA VE ARAZİ HİZMETLERİ KOMİSYONU) İŞVEREN V.   YOĞUN BAKIM PACU ÇALIŞANLARI', '30.12.2026 SÜREKLİ KONTROL', 3, 3, 15, 135, 'C', 'acik', 'Alanlarda elektirkli alet kullanımları devam etmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması', '1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması', '1- Yoğun bakım ve Pacu çalışanları', '1-Yeterli KKD mevcuttur.                     2-Çalışanlara KKD eğitimi verilmektedir.', 1, 0, 3, 6, 7, 126, 'C', '1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan kkd\'ler temin edilmelidir.\n2- Çalışanların maskeleri N95 ya da TS EN149 A1 standardında,göz koruyucuları TS EN 166 standardına uygun ve tam kapalı tip, iş eldivenleri TS EN 455 standardına, kesilmelere dayanıklı TS EN 388 standardına, çalışanların önlükleri sıvı geçirmez önlük/ cerrahi önlük TS EN ISO 13688 ve TS EN 13795 standartlarında iş ayakkabıları kaymaz tabanlı olmalıdır.                                                                                                                                                                                                 3- Bütün kişisel koruyucular çalışanlara zimmetlenmelidir.                                                                       4- Kişisel koruyucu donanımlar çalışanlar tarafından eksiksiz kullanılmalıdır.', 'İŞVEREN V.   YOĞUN BAKIM PACU ÇALIŞANLARI', '30.09.2027  \n                           SÜREKLİ KONTROL', 1, 6, 7, 42, 'D', 'acik', 'Tüm Yoğun Bakım ve PACU alanlarında yeterli sayıda KKD mevcuttur. Zimmet formları doldurulmuştur. Tüm personel tarafından eksiksiz kullanımında eksiklik devam etmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Tehlikeli kimyasalların yanlış depolanması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması                                 2- Yangın meydana gelmesi', '1- Yoğun bakım ve Pacu çalışanları                                   2- Hasta ve Hasta Yakınları', '1- Kimyasallar depo alanında depolanmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Kimyasal maddeler depolama matirsine göre depolanmalıdır.                                                        2- Yanıcı kimyasallar elektrik kaynaklarından uzak depolanmalıdır.                                                                               3- Kimyasal maddelerin ağzı açık olmamalı, dik olarak istiflenmelidir.                                              4- Ağzı açılmış kimyasal madde kaplarının altına taşma kapları konulmalıdır.', 'İŞVEREN V.   YOĞUN BAKIM PACU ÇALIŞANLARI', '30.09.2027  \n                           SÜREKLİ KONTROL', 1, 6, 7, 42, 'D', 'acik', 'Kimyasallar dik istiflenip ağzı açık bırakılmamaktadır. Bazı alanlarda elektrik kaynağına yakın depolama devam etmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1- Kimyasal madde deposunda göz duşu ve döküntü kiti bulunmaması                                               2- Çalışanların kimyasallar hakkında bilgi sahibi olmaması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1- Yoğun bakım ve Pacu çalışanları', '1- Kimyasallar depo alanında depolanmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.                                              3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               4-Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.                              5- Çalışanlara MSDS ve kimyasalların güvenli kullanımı konusunda eğitimler verilmelidir.', 'İŞVEREN V.   YOĞUN BAKIM PACU ÇALIŞANLARI', '30.12.2026 SÜREKLİ KONTROL', 3, 6, 7, 126, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Basınçlı tüplerin hatalı kullanılması', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1- Yoğun bakım ve Pacu çalışanları                                   2- Hasta ve Hasta Yakınları', '1-Oksijen tüpü sabitleme aparatları bulunmaktadır.                            2-Çalışanlara basınçlı tüplerin güvenli kullanımı konusunda eğitim verilmektedir.', 1, 0, 3, 6, 7, 126, 'C', '1-Tüm yoğun bakım ve PACU alanlarında tüpler dikey ve zincir/kelepçe ile en az 2 noktadan sabitlenmelidir.                                                                                                                                2- Basınç göstergeleri ve vanaların her kullanımdan önce kontrol edilmelidir.                                    3- Oksijen tüpleri ısı, kıvılcım ve yanıcı maddelerden uzakta depolanmalıdır.                                            4- Tüp vanalarının yavaşça açılmalı, ani basınç değişiminden kaçınılmalıdır.                                                                                                                               5-Oksijen tüplerine yağlı el, yağlı eldiven, gres yağı ile temas edilmemelidir.', 'YOĞUN BAKIM PACU ÇALIŞANLARI', '30.12.2026 SÜREKLİ KONTROL', 3, 6, 7, 126, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Yoğun bakım ve Pacu alanlarında hijyen tedbirlerinin yeterli olmaması', '1-Enfeksiyon hastalıklarına yakalanma, meslek hastalıkları', '1- Yoğun bakım ve Pacu çalışanları', '1-KKD\' ler mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Yoğun bakımların havalandırılması ve temizliği denetlenmelidir.\n2- Tıbbi ve medikal cihazların her kullanımdan sonra belirlenmiş olan kimyasallar ile dezenfekte edilip edilmediği kontrol edilmelidir.\n3- Çalışanlar tarafından KKD kullanımı denetlenmelidir.\n4- Çalışanların hijyen kurallarına uyup uymadıkları ve el hijyeni malzemelerinin yeterli miktarda olup olmadığı denetlenmelidir.\n5- Çalışanlara el hijyeni eğitimleri verilmelidir.', 'ENFEKSİYON KONTROL KOMİTESİ (TEMİZLİK HİZMETLERİ KOMİSYONU)', '30.09.2027  \n                           SÜREKLİ KONTROL', 3, 3, 7, 63, 'D', 'acik', 'El hijyeni malzemeleri yeterli miktardadır.Yıllık olarak Hepa filtreler yenilenmektedir. Tüm çalışanlar el hijyeni eğitimlerini almaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Hastaların taşınması ve pozisyon verilmesi', '1-Düşme ve travma                                       2-Kas-iskelet yaralanmaları', '1- Yoğun bakım ve Pacu çalışanları', '1-Hastalar birden fazla kişi tarafından taşınmaktadır.                                      2- Çalışanlara elle kaldırma ve taşıma eğitimi verilmektedir.', 1, 0, 3, 6, 7, 126, 'C', '1- Tüm yoğun bakım ve PACU alanlarında hasta taşıma için kaydırma örtüsü, hasta kaldırma lifti, tekerlekli sandalye, sedye gibi ekipmanlar kullanılmalıdır.     \n2- Yatak kenarlıkları kaldırılmalı, frenlerin kilitlenmelidir. Kateter, dren ve monitör bağlantılarının sabitlenmelidir. \n3- Hastalara pozisyon verme ve taşıma esnasında en az 2 kişi tarafından yapılmalıdır. Zemin kuru ve güvenli olmalıdır. \n 4- Çalışanlara elle kaldırma ve taşıma için eğitim verilmelidir.', 'YOĞUN BAKIM PACU ÇALIŞANLARI (HYRRT HİZMETLERİ KOMİSYONU)', '30.09.2027  \n                           SÜREKLİ KONTROL', 3, 2, 7, 42, 'D', 'acik', 'Hasta taşıma en az  kişi tarafından yapılmaktadır. Çalışanlara ele kaldırma ve taşıma eğitimi İSG Temel eğitimi içerisnde verilmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1- Kan ve vücut sıvılarının göz ve cilde temas etmesi', '1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- Yoğun bakım ve Pacu çalışanları', '1-KKD\' ler mevcuttur.                                   2-Çalışanlara KKD\'lerin kullanımı ve önemi hakkında eğitimler verilmektedir .', 1, 0, 6, 6, 3, 108, 'C', '1-Çalışanlar TS EN 455  standardında eldiven, N95 ya da TS EN 149 standardında maske, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                                                                                      2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.', 'İŞYERİ HEKİMİ YOĞUN BAKIM PACU ÇALIŞANLARI', '30.12.2026 MARUZİYET OLMASI DURUMUNDA    SÜREKLİ KONTROL', 6, 6, 3, 108, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1- Kesici delici aletlerin emniyetsiz kullanılması', '1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- Yoğun bakım ve Pacu çalışanları', '1- Kesici delici alet kutuları mevcttur.                2-Çalışanlara kesici delici aletlerin güvenli kullanımı konusunda eğitim verilmektedir.', 1, 0, 6, 6, 3, 108, 'C', '1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                               3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                             5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.', 'YOĞUN BAKIM PACU ÇALIŞANLARI', '30.12.2026 SÜREKLİ KONTROL', 6, 6, 3, 108, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Steril olmayan, kontamine olmuş aletlerin açıkta bırakılması', '1-Steril olmayan aletlere temas sonucu iş kazaları enfeksiyon, bulaşıcı hastalık', '1- Yoğun bakım ve Pacu çalışanları', '1-KKD\'ler mevcuttur.                                         2- Atık kutuları mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1-Kullanılan, kontamine olmuş aletler bekletilmeden hemen kapaklı ve renk kodlu atık kutularına atılmalıdır.                                                                                                                           2- Sterilazyona gidecek aletlere TS EN 388 standardında kesilme ve delinmeye dayanıklı eldiven olmadan temas edilmemeli, çelik, kapaklı kutulara konulmalıdır.                                                                                                                                                        3- Tek kullanımlık olmayan aletler her kullanımdan sonra dezenfekte edilmelidir.                                                                                                                                                                                     4- Kontamine olmuş aletler, çarşaf, yatak, yorgan vb. yere saplanmamalı, yere atılmamalıdır.                                                                                                                                                          5- Temas edilmesi durumunda, bölge bol su ve sabunla yıkanmalıdır.', 'İŞVEREN V.   YOĞUN BAKIM PACU ÇALIŞANLARI (TEMİZLİK HİZMETLERİ KOMİSYONU)', '30.12.2026 SÜREKLİ KONTROL', 6, 6, 3, 108, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Defibralatörün hatalı kullanılması', '1-Defibrilatör kullanımı sırasında elektrik çarpması, elektrik yanıkları oluşması', '1- Defbilatör kullanan çalışanlar                                                     2- Diğer ilgili çalışanlar', '1-Defibralatörün periyodik kontrolü yapılmaktadır.', 1, 0, 3, 2, 15, 90, 'C', '1-Defibrilasyon esnasında hastaya elektrotlara ve diğer iletken nesnelere dokunulmamalıdır.\n2-Hastaya ıslak  ve iletken ortamlarda defibrilasyon uygulanmamalı, hastanın göğsünde ıslaklık, jel, ter olmamalı, hastanın göğüsü kurulanmalıdır.\n3-Defibrilatör cihazı oksijen tüpü, alkol vb. yanıcı sıvı ve gazların bulunduğu ortamlarda kullanılmamalıdır.                                                                                                                                                            4- Hastanın ve defibilatörü kullanan çalışanın üzerinde metal eşyalar bulunmamalıdır.                                                                                                                                                                                  5- Ortamda bulunan diğer çalışanlar en az 1 metre uzakta bulunmalıdır.', 'DEFİLBİLATÖR KULLANAN ÇALIŞANLAR', '30.09.2027 DEFİBİLATÖR KULLANIM SIRASINDA SÜREKLİ KONTROL', 1, 2, 15, 30, 'D', 'acik', 'Çalışanların defibralatör kullanımı sınırlıdır. Kullanan çalışanlar CPR eğitimi içerisinde eğitim almaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Pendatlarda gaz kaçağı(oksijen, azot, azotprotoksit, karbondioksit) olması', '1-Baş dönmesi, sersemlik, uyku hali bulantı, konsatrasyon bozukluğu oluşması', '1- Yoğun bakım ve Pacu çalışanları                                   2- Hasta ve Hasta Yakınları', '1-Talep halinde arızalar için kurum içerisinde firma teknik birim tarafından takip edilmektedir.', 1, 0, 3, 2, 15, 90, 'C', '1- Çalışanlar pendant sistemi üzerinde gaz kaçağı (tıslama hava çıkış sesi vb.) tespit edilmesi durumunda hemen yetkililere haber vermeli, terminal çıkışı kapatılmalıdır.                                                                                                                                                  2- Kaçak olan pendant da tüm gazlar kesilmelidir.                                                                                           3- Gaz kaçağı olan alanda elektrikli hiç bir alet kullanılmamalı, ateş kıvılcım kaynağı bulundurulmamalıdır.                                                                                                                                                4-Gaz kaçak kaynağı (conta, hasarlı hortum, bağlantı eleamanlarında gevşeme ) tespit edilmelidir.                                                                                                                                            5- Arıza giderildikten sonra sızdırmazlık testi yapılmadan pendant aktif hale getirilmememlidir.                                                                                                                                                                                                6- Pendatların en az yılda bir kez mekanik, sızdırmazlık ve basınç testleri yapılmalıdır.', 'FİRMA                 (BİNA VE ARAZİ HİZMETLERİ KOMİSYONU)                               YOĞUN BAKIM PACU ÇALIŞANLARI', 'ARIZA OLMASI DURUMUNDA VE YILDA 1                                                   SÜREKLİ KONTROL', 1, 2, 7, 14, 'E', 'acik', 'Yıllık validasyon bakımlarında kontroller yapılmakta sistem üzerinden bir kaçak durumunda alarm verilmekte, talep halinde onarımı yapılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Pendantların üzerine sıvı konulması ve serum askılarının kırık olması', '1-Elektrik çarpması', '1- Yoğun bakım ve Pacu çalışanları                                   2- Hasta ve Hasta Yakınları', '1-Talep halinde arızalar için kurum içerisinde firma teknik birim tarafından takip edilmektedir.', 1, 0, 3, 2, 15, 90, 'C', '1-Pendatlar üzerine sıvı malzemeler bırakılmamalıdır.                                                                                                                               2- Pendant üzerine sıvı dökülmesi halinde kağıt havlu ile hemen silinmeli, priz veya valflere sıvı girmesi önlenmelidir.                                                                                                                          3- Prizlere sıvı kaçması durumunda hemen yetkililere haber verilmeli, pendant kullanılmamalı, gerekirse elektrik akımı kesilmelidir.                                                                                    4- Kırık olan serum askıları yenileri ile değiştirilmeli ve sabitlenmelidir.', 'FİRMA                                YOĞUN BAKIM PACU ÇALIŞANLARI', '30.12.2026 ARIZA OLMASI DURUMUNDA                                                   SÜREKLİ', 3, 2, 15, 90, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Diyaliz atık giderlerinin tıkanması/taşması', '1-Kontamine atık suların zemine taşması  sonucu kayma, düşme ve yaralanma, temas sonucu elektrik çarpması', '1- Yoğun bakım  çalışanları                                   2- Hasta ve Hasta Yakınları', '1-Atıklar için ayrı bir gider bulunmaktadır.', 1, 0, 3, 2, 15, 90, 'C', '1- Diyaliz giderlerinde tıkanma, taşma olması durumunda hemen cihazın elektrik bağlantıları kesilmeli, suyun elektrik ile temas etmesi önlenmelidir.                                                                                       2-Taşma sonrasında yüzey ve zeminler derhal dezenfektanlarla temizlenmeli, taşma sırasında oluşabilecek biyolojik atık,  atık torbaları atılmalıdır.                                                          3- Diyaliz makinesi filtreleri düzenli aralıklar ile değiştirilmelidir.                                                                  4-Giderler düzenli aralıklar ile kontrol edilmeli tıkanması önlenmelidir.', 'FİRMA                                YOĞUN BAKIM ÇALIŞANLARI', '30.09.2027                                                  SÜREKLİ KONTROL', 3, 1, 7, 21, 'D', 'acik', 'Diyaliz atıklarında tıkanma ve taşma durumlarında talep açılarak sorun gideriliyor, taşma tıkanma vakası yıl içinde yaşanmadığı tespit edilmiştir. 15.05.2026 saha turu raporu', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Yoğun bakım acil çıkış kapılarından yetkisiz giriş yapılması', '1-Güvenlik ihlali, hırsızlık, sabotaj', '1- Yoğun bakım çalışanları', '1- Yoğun bakımlarda manyetik kilit sistemi mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1-Otopark katından direk yoğun bakım bölümlerine yetkisiz giriş ve çıkışlar engellenmelidir önlenmelidir.                                                                                                                                                             2-Manyetik tutucular periyodik olarak kontrol edilmeli, aktif olması sağlanmalıdır.                                                            3- Yoğun bakımlara yetkisiz giriş görüldüğünde derhal güvenliğe haber verilmelidir.                                                                                                                                                                                      4- Güvenlik birimi tarafından düzenli devriye ve denetim yapılmalıdır.                                              5-Panik butonları her zaman çalışır durumda olmalıdır.', 'FİRMA (GÜVENLİK HİZMETLERİ KOMİSYONU)', '30.12.2026 SÜREKLİ KONTROL', 3, 2, 15, 90, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Kesici delici aletlerin ortalıkta bulunması (Makas, enjektör vb.)', '1-Çalışan hasta ve yakınları için kesici delici alet yaralanması', '1- Yoğun bakım ve Pacu çalışanları', '1- Çalışanların zimmetleri vardır.', 1, 0, 6, 2, 7, 84, 'C', '1- Kesici delici aletler sadece belirlenen alanlarda bulundurulmalıdır.\n2- Kullanım sonrası hemen toplanmalı ve güvenli şekilde saklanmalıdır.', 'YOĞUN BAKIM PACU ÇALIŞANLARI', '30.12.2026 SÜREKLİ KONTROL', 6, 2, 7, 84, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Hastalardan inhalasyon yoluyla hastalık bulaşması', '1-Enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- Yoğun bakım ve Pacu çalışanları', '1-KKD\'ler mevcuttur.                                         2- Çalışanlara KKD önemi ve kullanımı konusunda eğitim verilmektedir.', 1, 0, 3, 3, 7, 63, 'D', '1-Bulaşıcı hastalık şüphesi olan hastalar, sonuçları çıkana kadar tek kişilik izolasyon odalarında tutulmalıdır.                                                                                                                                                                                              2- Şüpheli hastaların bulunduğu alanın teması bittikten sonra hemen dezenfekte edilmelidir.                                                                                                                                                                                                                                                                                                         4-Tanı konulmuş hastalar negatif basınçlı odalara alınarak izole edilmelidir.                                                                                                                        5-Çalışanlar N95 ya da TS EN 149 standrtdında FFP2 filtreli maske, yüz siperi, TS EN 455  standardında eldiven kullanmalıdır.', 'BİRİM SORUMLUSU YOĞUN BAKIM PACU ÇALIŞANLARI', '30.09.2027                                                  SÜREKLİ KONTROL', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Röntgen çekimi esnasında kurşun paravan kullanılmaması', '1-Radyasyon maruziyeti', '1- Yoğun bakım ve Pacu çalışanları', '1-Kurşun önlükler mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Taşınabilir röntgen cihazı ile yapılan çekimler de kurşun paravan kullanılmalıdır.                                                                                                                                                               2- Çekim yapılan alanda hasta ve çekim yapan çalışan dışında kimse olmamalı, zorunlu hallerde bulunulması gerekirse(TS EN 61331 standardında kurşun önlük troid koruyucu vb.kişisel koruyucu ekipmanlar kullanılmalıdır.                                                                                                       3- Çekim yapılan odaların kapıları kapatılmalıdır.                                                                                           4- Açık alanlarda yapılan çekimlerde çalışanlar en az 2 metre uzakta durmalıdır.', 'RADYOLOJİ ÇALIŞANLARI       YOĞUN BAKIM PACU ÇALIŞANLARI (GÖRÜNTÜLEME HİZMETLERİ KOMİSYONU)', '30.09.2027 ÇEKİM ESANASINDA SÜREKLİ', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Hasta yataklarının mekanizmalarının bozulması', '1-El kol parmak sıkışmaları                                            2- Ayak yaralanmaları', '1- Yoğun bakım ve Pacu çalışanları', '1-Arıza olması halinde onarılmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1-Tüm yoğun bakım ve PACU ünitesinde hasta yataklarının düzenli bakım ve periyodik kontrolleri yapılmalıdır.                                                                                                                         2- Yatak frenleri sağlam olmalıdır.                                                                                                                                                                               3- Elektrikli/motorlu yataklarda kablo ve kumanda sistemlerinin kontrol edilmeli hasarlı kablolar değiştirilmelidir.                                                                                                                                                                                4-Korkuluklar her zaman sağlam ve kilitli pozisyonda tutulmalıdır.                                                                            5- Arızalı yataklar kullanım dışı bırakılmalıdır.', 'FİRMA       (DİĞER TİBBİ EKİPMAN HİZMETLERİ KOMİSYONU)', '30.09.2027                                                  SÜREKLİ KONTROL', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Hasta bölmeleri arası  mahremiyet perdeleri kullanımı ve temizliği', '1-Enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- Yoğun bakım ve Pacu çalışanları', '1-Ayda bir kere perde değişimi yapılmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1-Hastalar arası bölmeler  için Sabit Duvar/Modüler Kabin Sistemleri yapılmalıdır.\n2-Yırtık veya bozuk perdeler hemen yenisiyle değiştirilmelidir.     \n3- Tüm yoğun bakım ve PACU ünitesinde perdeler en geç ayda bir kere  (Bulaş ve hasta değişiminde hemen) ve kontaminasyon durumunda hemen yıkanmalı/dezenfekte edilmelidir.                                                                                                                                                                                                                                 4-Perdeler çıkarılırken kirli yüzeyin çalışanla temas etmesi önlenmelidir.', 'İŞVEREN V. (TEMİZLİK HİZMETLERİ KOMİSYONU)  YOĞUN BAKIM PACU ÇALIŞANLARI', '30.09.2027                                                  SÜREKLİ KONTROL', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Çalışma alanında yiyecek-içecek tüketilmesi', '1-Meslek hastalıklarının oluşması\n2-Çalışan sağlığının bozulması', '1- Yoğun bakım ve Pacu çalışanları', '1-Tanımlı mutfak alanı mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1-Tüm yoğun bakım ve PACU alanlarında ilaç hazırlama odaları, hasta bakım alanları gibi bölümlerde yiyecek–içecek kesinlikle tüketilmemelidir.         \n2-Yemek ve çay saatlerinden önce el, yüz ve vücut temizliği sağlanmalıdır.                                                                                                                                                                                                                                                                                                                                                                                                      3-Çalışanlara, yiyecek–içecek tüketiminin hastane enfeksiyonlarına, kimyasal/biyolojik madde bulaşına ve çalışan sağlığına yönelik risklerine karşı eğitim verilmelidir.', 'İŞ GÜVENLİĞİ UZMANI     YOĞUN BAKIM PACU ÇALIŞANLARI', '30.09.2027                                                  SÜREKLİ KONTROL', 3, 6, 3, 54, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1- Havalandırma sisteminin periyodik kontrollerinin tekrarlanmaması                                            2- Hepa filtrelerin yılda bir değiştirilmemesi', '1-Enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- Yoğun bakım ve Pacu çalışanları', '1- Havalandırma tesisatının periyodik kontrolü mevcuttur.', 1, 0, 1, 6, 7, 42, 'D', '1- Havalandırma sisteminin periyodik kontrolleri havalandırma tesisat projesinde yer alan kriterlere göre en geç yılda bir tekrarlanmalıdır. \n2- Partiküllere karşı kullanılan hepa filtreler en geç yılda bir kez değiştirilmelidir.', 'FİRMA                 (BİNA VE ARAZİ HİZMETLERİ KOMİSYONU)', 'YILDA 1', 1, 2, 7, 14, 'E', 'acik', 'Havalandırma ve HEPA filtreler düzenli olarak her yıl yenileniyor.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM: YOĞUN BAKIMLAR ve PACU', '1-Hasta odalarında bulunan çeşmelerin sensörsüz olması', '1-Bulaş sonucu enfeksiyon hastalıkları', '1- Yoğun bakım ve Pacu çalışanları', '1-Çalışanlara biyolijik riskler hakkında eğitim verilmektedir.', 1, 0, 3, 3, 3, 27, 'D', '1- El ile açılan musluklar fotoselli musluklar ile değiştirilmelidir.\n2- El hijyen ekipmanları yeterli miktarda ve kolay erişilebilir konumda olmalıdır.                                                           \n3- Musluklar kapatılırken temas edilmemeli, kağıt havlu kullanılmalıdır.        \n4- Musluk ve lavabo yüzeyleri düzenli olarak dezenfekte edilmelidir.', 'İŞVEREN V.  FİRMA                 (BİNA VE ARAZİ HİZMETLERİ KOMİSYONU)   YOĞUN BAKIM PACU ÇALIŞANLARI', '30.09.2027                                                  SÜREKLİ KONTROL', 3, 3, 3, 27, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI', '1-Diyaliz sıvılarının Elektrik pano odalarının önüne depolanması', '1-Acil durumlarda hızlı müdahalenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması', '1-Kemoterapi çalışanları', '1- 30 MA kaçak akım rölesi mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Elektrik pano odalarının önüne  malzeme depolanmamalıdır.     \n2- Panolara erişim için en az 80 cm genişlikte ulaşım yolları sağlanmalıdır.                                                                                    3- Diyaliz sıvıları ayrı depolama alanlarında (serin, kuru, iyi havalandırılmış, güneş görmeyen) muhafaza edilmelidir.                                                                                                                    4-Birim sorumlusu tarafından düzenli kontrol yapılmalıdır. Uygunsuz depolama tespit edildiğinde anında raporlama ve düzeltici faaliyet uygulanmalıdır.', 'KEMOTERAPİ  ÇALIŞANLARI FİRMA (HYRRT HİZMETLERİ KOMİSYONU)', '30.09.2027 SÜREKLİ KONTROL', 3, 1, 15, 45, 'D', 'acik', 'Kısmi olarak depolama yapılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI', '1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması', '1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması', '1- Kemoterapi çalışanları', '1-Yeterli KKD mevcuttur.                     2-Çalışanlara KKD eğitimi verilmektedir.', 1, 0, 3, 6, 7, 126, 'C', '1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan KKD\'ler temin edilmelidir.\n2- Çalışanların maskeleri N95 ya da TS EN149 A1 standardında,göz koruyucuları TS EN 166 standardına uygun ve tam kapalı tip iş eldivenleri TS EN 455 standardı, kesilmelere dayanıklı TS EN 388 standartına çalışanların önlükleri sıvı geçirmez önlük/ cerrahi önlük TS EN ISO 13688 ve TS EN 13795 standartlarında iş ayakkabıları kaymaz tabanlı olmalıdır.                                                                                                                                                                                                 3- Bütün kişisel koruyucular çalışanlara zimmetlenmelidir.                                                                       4- Kişisel koruyucu donanımlar çalışanlar tarafından eksiksiz kullanılmalıdır.', 'İŞVEREN V.   KEMOTERAPİ ÇALIŞANLARI', '30.09.2027 SÜREKLİ KONTROL', 3, 1, 7, 21, 'D', 'acik', 'KKD zimmet formları tamamlanmıştır. Tüm KKD ler alanlarda bulunmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI', '1-Kemoterapi alanında kullanılan hasta koltuklarının kabloların dağınıklığı', '1-İş kazası, yaralanma                                                2-Takılma,düşme                                            3- Kabloların zarar görmesi', '1-Kemoterapi çalışanları          2- Hasta ve Hasta Yakınları', '1- 30 MA kaçak akım rölesi mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Kablo düzenleyiciler, spiral borular veya kablo kanalları kullanılarak dağınık kablolar düzenlenmelidir.                                 \n2-Elektrik prizleri, medikal cihazların konumuna uygun şekilde, zeminden yüksekte ve erişilebilir yerlerde olmalıdır.                                                                                                                           3-Elektrik kablolarının hasar görmesi durumunda cihaz hemen kullanımdan çıkarılmalıdır.   \n4- Çalışanlar geçiş amaçlı kabloların bulunduğu kısmı kullanmamalıdır.', 'FİRMA                 (BİNA VE ARAZİ HİZMETLERİ KOMİSYONU) \n\n  KEMOTERAPİ ÇALIŞANLARI', '30.12.2026 SÜREKLİ KONTROL', 3, 6, 7, 126, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI', '1-Kemoterapi alanında kullanılan hasta koltuklarının devrilmesi,düşmesi', '1-Koltuğun devrilmesi sonucu yaralanma', '1-Kemoterapi çalışanları          2- Hasta ve Hasta Yakınları', '1- Koltuklar sabitlenme aparatı ile tek yönden zemine sabitlenmiştir.', 1, 0, 3, 6, 7, 126, 'C', '1-Kemoterapi koltukları iki noktadan zemine devrilmeyecek şekilde sabitlenmelidir.                                                                           \n2- Koltuk kolçakları her zaman sağlam ve kilitli pozisyonda tutulmalıdır.     \n3- Koltukların elektrikli mekanizmaları çalışır durumda olmalı, düzenli kontrol ve bakımları yapılmalıdır. \n4- Koltuğa hasta transferleri en az 2 çalışan ile yapılmalıdır.', 'FİRMA            (DİĞER TİBBİ EKİPMAN HİZMETLERİ KOMİSYONU)\n\n  KEMOTERAPİ ÇALIŞANLARI', '30.09.2027 SÜREKLİ KONTROL', 3, 1, 7, 21, 'D', 'acik', 'Koltuklar tek noktadan sabitlenmiştir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI', '1-Kemoterapi uygulama alanında hijyen tedbirlerinin yeterli olmaması', '1-Enfeksiyon hastalıklarına yakalanma, meslek hastalıkları', '1- Kemoterapi çalışanları', '1-KKD\' ler mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Kemoterapi sonrası hasta alanlarının havalandırılması ve temizliği denetlenmelidir.\n2- Tıbbi ve medikal cihazların her kullanımdan sonra belirlenmiş olan kimyasallar ile dezenfekte edilip edilmediği kontrol edilmelidir.\n3- Çalışanlar tarafından KKD kullanımı denetlenmelidir.\n4- Çalışanların hijyen kurallarına uyup uymadıkları ve el hijyeni malzemelerinin yeterli miktarda olup olmadığı denetlenmelidir.\n5- Çalışanlara el hijyeni eğitimleri verilmelidir.', 'ENFEKSİYON KONTROL KOMİTESİ (TEMİZLİK HİZMETLERİ KOMİSYONU)', '30.09.2027 SÜREKLİ KONTROL', 3, 2, 7, 42, 'D', 'acik', 'Çalışanlara el hijyeni eğitimleri verilmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI', '1- Kan ve vücut sıvılarının göz ve cilde temas etmesi', '1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- Kemoterapi çalışanları', '1-KKD\' ler mevcuttur.                                   2-Çalışanlara KKD\'lerin kullanımı ve önemi hakkında eğitimler verilmektedir .', 1, 0, 6, 6, 3, 108, 'C', '1-Çalışanlar TS EN 455  standardında eldiven, N95 ya da TS EN 149 standardında maske, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.', 'İŞYERİ HEKİMİ\n\n KEMOTERAPİ ÇALIŞANLARI', '30.12.2026 MARUZİYET OLMASI DURUMUNDA    SÜREKLİ KONTROL', 6, 6, 3, 108, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI', '1-Sitotoksik ilaçların dökülmesi sonucu maruziyet', '1-Temas sonucu  cilt, göz iritasyonu', '1- Kemoterapi çalışanları', '1-KKD\' ler mevcuttur.                                   2-Çalışanlara KKD\'lerin kullanımı ve önemi hakkında eğitimler verilmektedir .', 1, 0, 6, 6, 3, 108, 'C', '1-Gözlerle Temas: Lens takılı ise çıkarmalıdır. Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkanmalıdır.\n2- Ciltle Temas: Kirlenmiş giysiler çıkarılmalı hemen bol su ile yıkanamlıdır. Tahriş devam ediyorsa, doktora danışılmalıdır. Kirlenmiş giysiler tekrar kullanmadan önce yıkanmalıdır.\n3-Solunum: Kişi açık havaya çıkarılmalıdır. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım aldırılmalıdır.\nYutma: Yutulması durumunda medikal tavsiye alınmalıdır.', 'KEMOTERAPİ ÇALIŞANLARI (TEMİZLİK HİZMETLERİ KOMİSYONU)', '30.12.2026 SÜREKLİ KONTROL', 6, 6, 3, 108, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI', '1- Kesici delici aletlerin emniyetsiz kullanılması', '1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- Kemoterapi çalışanları', '1- Kesici delici alet kutuları mevcttur.                2-Çalışanlara kesici delici aletlerin güvenli kullanımı konusunda eğitim verilmektedir.', 1, 0, 6, 6, 3, 108, 'C', '1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                               3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                             5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.', 'KEMOTERAPİ ÇALIŞANLARI', '30.09.2027 SÜREKLİ KONTROL', 3, 2, 7, 42, 'D', 'acik', 'Çalışanlarra kesici delici aletlerin güvenli kullanımı hakında eğitim verilmektedir. Atıklar 2/3 oranında dolunca değiştirilmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI', '1-Sitotoksik ilaçların, serumların ortama yayılması, dökülmesi, sonucu maruziyet', '1-Sitotoksik ilaca maruz kalma sonucu iş kazası meydana gelmesi', '1-Kemoterapi çalışanları                                        2- Hasta ve Hasta Yakınları', '1-Kimyasal atık varilleri bulunmaktadır.                           2-Kimyasal müdahale kitleri bulunmaktadır.', 1, 0, 6, 6, 3, 108, 'C', '1-Sitotoksik ilaçlar ve serumlar sızdırmaz, darbeye dayanıklı olmalıdır.                                                                             2- Sitotoksik ilaç serumları elde değil kap içerisinde taşınmalıdır.                                                        3- Hazırlık ve uygulama alanlarında dökülme kiti her zaman hazır bulundurulmalıdır.                                                                                                                                                  4- Dökülme olması durumunda alan hemen izole edilmeli, absorban kullanılarak sitotoksik ilacın çalışma ortamına yayılması önlenmelidir.                                                                         5- Döküntü olan yüzey deterjan ve su ile iki kere temizlenmelidir.                                                                                                               6- Döküntü atıkları atık poşetlerine atılarak ağızları sıkıca bağlanmalıdır.', 'KEMOTERAPİ ÇALIŞANLARI (TEMİZLİK HİZMETLERİ KOMİSYONU)', '30.12.2026 DÖKÜLME SIRASINDA SÜREKLİ KONTROL', 6, 6, 3, 108, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI', '1-Bölüme özel eğitimler', '1-İş kazası, meslek hastalığı                                        2-Sitotoksik ilaç maruziyeti', '1-Kemoterapi çalışanları', '1- Çalışanlar Temel İSG Eğitimlerine Katılmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1-Sitotoksik ilaç güvenliği ile ilgili olarak   hazırlama, taşıma, uygulama sırasında riskler ve önlemler için yılda bir kere eğitim verilmelidir.                                                                                                                                 2- Atık yönetimi için  Sitotoksik atıkların ayrı toplanması ve imhası ile ilgili olarak yılda bir eğitim verilmelidir.                                                                                                                                                                                                                                                                                                                                                                                                                                                         3-Dökülme  kiti kullanımı eğitimleri verilmeli ve uygulamalı olarak  tatbikatı yapılmalıdır.\n4-Acil durum simülasyonları (ilaç dökülmesi, sitotoksik ilaç maruziyeti vb.)için eğitim düzenlenmelidir.', 'İŞ GÜVENLİĞİ UZMANI', '30.09.2027 SÜREKLİ KONTROL', 3, 3, 7, 63, 'D', 'acik', 'Çalışanlara turuncu kod ve sitotoksik ilaç dökülmelerine karşı eğitim planlanmıştır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI', '1-Çalışma alanında yiyecek-içecek tüketilmesi', '1-Meslek hastalıklarının oluşması\n2-Çalışan sağlığının bozulması', '1- Kemoterapi çalışanları', '1-Tanımlı mutfak alanı mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1-Kemoterapi alanlarında ilaç hazırlama odaları, hasta bakım alanları gibi bölümlerde yiyecek–içecek kesinlikle tüketilmemelidir. \n2-Yemek ve çay saatlerinden önce el, yüz ve vücut temizliği sağlanmalıdır.                                                                                                                                                                                                                                                                                                                                                                                                      3-Çalışanlara, yiyecek–içecek tüketiminin hastane enfeksiyonlarına, kimyasal/biyolojik madde bulaşına ve çalışan sağlığına yönelik risklerine karşı eğitim verilmelidir.', 'KEMOTERAPİ ÇALIŞANLARI', '30.09.2027 SÜREKLİ KONTROL', 3, 6, 3, 54, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI', '1-Sitotoksik ilaçların ilaç hazırlama ünitesinden tedavi alanlarına taşınması', '1-Sitotoksik ilaçlara maruziyet sonucu iş kazaları meydana gelmesi', '1-Kemoterapi çalışanları  \n2-Dieğer çalışanlar', '1-Taşıma araçlarında müdahale kiti bulunmaktadır.', 1, 0, 3, 6, 3, 54, 'D', '1- Sitotoksik ilaçlar sızdırmaz kaplarda taşınmalı ve etiketlenmelidir.\n2- Taşıma araçlarında dökülme ve saçılmalara karşı müdahale kitleri bulunmalıdır. \n3- Müdahale kiti bulaş olma ihtimaline karşı taşıma kabini dışında tutulmalıdır.                        4- Taşıma güzergâhı önceden belirlenmeli, insan ve hasta trafiğinin yoğun olduğu bölgelerden taşınmamalıdır.', 'FİRMA              (HYRRT HİZMETLERİ KOMİSYONU)', '30.09.2027 SÜREKLİ KONTROL', 3, 6, 3, 54, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: KEMOTERAPİ TEDAVİ ALANLARI', '1-Göz duşu solüsyonlarının yenilenmemesi', '1-Göze sitotoksik ilaç kaçması sonucu iş kazası meydana gelmesi', '1-Kemoterapi çalışanları', '1-Göz duşu bulunmaktadır.', 1, 0, 3, 6, 3, 54, 'D', '1-Tüm kemotetapi tedavi alanlarında sitotoksik ilaç maruziyetine karşı göz duşu bulundurulmalıdır.                                                                                                                                                      2-Göz duşları solüsyonları kullanıldıktan sonra yenisi tekrar konulmalıdır.                                                      3- Göz duşu kullanım talimatları asılmalıdır.', 'İŞVEREN V.', 'SÜREKLİ KONTROL', 1, 0.5, 3, 1.5, 'E', 'acik', 'Göz duşu solusyonları yenilenmiş ve miyad kontrolleri yapılmıştır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI', '1-Sitotoksik ilaç hazırlama işlerinde çeker ocak kullanılmaması', '1-Sitotksik ilaçlara maruz kalma, sonucu iş kazası, meslek hastalığı', '1-Sitotoksik ilaç hazırlama çalışanları', '1- Bazı ilaçlar kabinde hazırlanmaktadır.      2-Negatif basınçlı oda mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1--Sitotoksik ilaç hazırlama işleri, sadece çeker ocak altında yapılmalı, açık masalarda ilaç hazırlanmamalıdır.         \n2-Eksik çeker ocak temin edilmelidir.                                                                                                                                                                                                                                                                                                                                                         3-Çeker ocak yanlarında  tek kullanımlık emici, sıvı geçirmez pedler bulundurulmaldır.                                                                                                                                                                                             4- Dökülme kitleri (spill kit) ilaç hazırlık alanında bulundurulmalıdır.                                                                                                                      5- Nitril eldiven(EN 455), sıvı geçirmez uzun kollu önlük veya tek kullanımlık kaplamalı önlük(EN ISO 13688),koruyucu gözlük/ siperlik(EN 166), N95,bone(EN 14126) ve galoş(EN ISO 13688) kullanılmalıdır.', 'FİRMA \n\n  SİTOTOKSİTİK İLAÇ HAZIRLAMA ÇALIŞANLARI', '2 AY \n\n\nSÜREKLİ  KONTROL', 1, 1, 1, 1, 'E', 'acik', 'Kemoterapi ilaç hazırlama alanında  kamu çalışanı bulunmamaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI', '1-Sitotoksik ilaç hazırlama kabininde hava sirkülasyonunun engellenmesi', '1-Sitotoksik ilaç hazırlarken aerosol/solunum maruziyeti', '1-Sitotoksik ilaç hazırlama çalışanları', '1-Negatif basınç mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Kirli havayı zeminden atan aspirasyon sisteminin önü raf malzeme vb. ekipmanlar ile kapatılmamalı, emiş sistemi her zaman aktif olmalıdır.\n2-Sitotoksik ilaç  buharının çalışma ortamına yayılması önlenmeli,  buhar solunum bölgesine ulaşmadan zeminden atılmalıdır.\n3-İlaç hazırlama işleri sadece çeker ocak altında yapılmalıdır.', 'FİRMA', 'SÜREKLİ KONTROL', 1, 1, 1, 1, 'E', 'acik', 'Kemoterapi ilaç hazırlama alanında  kamu çalışanı bulunmamaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI', '1-Sitotoksik ilaç hazırlama kabininde acil kapı açma butonunun olmaması', '1- Acil durumlarda tahliyenin sağlanamaması', '1-Sitotoksik ilaç hazırlama çalışanları', '1- Mevcutta ilaç hazırlama ünitesi kapıları içe doğru açılmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1-Sitotoksik ilaç hazırlama kabininde  kapı kolunun arızalanmasına karşı, içeriden açılabillir ilave acil kapı açma butonu takılmalıdır.                                                                                                                                                                                                   2- Acil kapı açma butonu ve alarm butonu erişilebilir yükseklikte olmalı ve önüne malzeme konulmamalıdır.                                                                                                                                           3- Acil kapı açma butonu ve alarm sistemi karanlıkta görülebilir şekilde işaretlenmiş olmalıdır.', 'FİRMA', '30.12.2026 SÜREKLİ KONTROL', 1, 1, 1, 1, 'E', 'acik', 'Kemoterapi ilaç hazırlama alanında  kamu çalışanı bulunmamaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI', '1-Eczane içerisinde sitotoksik ilaçların depolanması', '1-Sitotksik ilaçlara maruz kalma sonucu                                                                           İş kazası, meslek hastalığı meydana gelmesi', '1-Sitotoksik ilaç hazırlama çalışanları', '1-Sitotoksik ilaçlar ayrı bir alanda depolanmaktadır.\n2-Yetkili kişiler tarafından kontrollü dağıtımı mevcuttur.                          .', 1, 0, 3, 6, 7, 126, 'C', '1-Sitotoksik ilaçların  depolama alanı kilitli ve yetkisiz girişlere kapalı olmalıdır.  2- Depolama alanında yeterli havalandırma bulunmalıdır.\n3- Raflarda ilaçlar düşme, devrilme, ezilme riski olmayacak şekilde yerleştirilmeli, raflar en az iki noktadan duvara sabitlenmiş olmalıdır.                                                                                         \n4-Olası dökülme veya sızıntılara karşı absorban pedler, koruyucu eldiven, maskeler kolay erişilebilir olmalıdır.                                                                                                           5-Depoya giriş yapan personel koruyucu  eldiven(EN 455), sıvı geçirmez önlük(EN ISO 13688), maske(EN 14683), koruyucu gözlük/ siperlik(EN 166) kullanmalıdır.                                                                                                                                                                                                                                                         6-Personel, sitotoksik ilaçların depolanması sırasında kimyasal riskler ve acil durum prosedürleri konusunda düzenli olarak eğitilmelidir. Yılda en az bir kez tatbikat yapılmalı, acil durum senaryoları test edilmelidir.', 'FİRMA \n\n  SİTOTOKSİTİK İLAÇ HAZIRLAMA ÇALIŞANLARI', 'SÜREKLİ KONTROL', 1, 1, 1, 1, 'E', 'acik', 'Kemoterapi ilaç hazırlama alanında  kamu çalışanı bulunmamaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI', '1-Sitotoksik ilaç hazırlama kabininde  havalandırma sisteminin periyodik kontrollerinin tekrarlanmaması', '1-Kimyasal madde buharlarının solunması sonucunda meslek hastalıklarının oluşması', '1-Sitotoksik ilaç hazırlama çalışanları', '1-Havalandırma sisteminin periyodik kontrolü mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1- Havalandırma sisteminin periyodik kontrolleri havalandırma tesisat projesinde yer alan kriterlere göre en geç yılda bir tekrarlanmalıdır. \n2- Partiküllere karşı kullanılan hepa filtreler en geç yılda bir kez değiştirilmelidir.', 'FİRMA', 'YILDA 1', 1, 1, 1, 1, 'E', 'acik', 'Kemoterapi ilaç hazırlama alanında  kamu çalışanı bulunmamaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI', '1-Dökülme sonrası alanın yanlış dekontaminasyonu', '1- Hatalı temizlik nedeniyle aerosollerin yeniden ortama yayılması', '1-Sitotoksik ilaç hazırlama çalışanları', '1-Alanda dökülme kiti mevcuttur.                2-KKD\'ler mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1 -Hazırlık alanında standart dökülme kiti (spill kit) bulundurulmalıdır.                                                                                                                                                                         2-Yüzeylerin sitotoksik ilaçlara uygun dekontaminanlarla (örn. sodyum hipoklorit, ardından nötral temizleyici) temizlenmeli, temizleme işlemi temiz alandan kirli alana doğu yapılmalı, dökülme sonrası alan geçici olarak kapatılmalıdır.\n3- Dökülme temizliği sırasında eldiven (EN 455), su geçirmez önlük (EN ISO 13688), N95/FFP3 maske (EN149:2001+A1:2009), gözlük/siperlik (EN 166 )giyilmelidir.                                                                                                                                                                       3- Dekontaminasyon sonrası KKD’ler çıkarılıp sitotoksik atık kutusuna atılmalıdır.', 'SİTOTOKSİTİK İLAÇ HAZIRLAMA ÇALIŞANLARI', 'DÖKÜLME SIRASINDA SÜREKLİ KONTROL', 1, 1, 1, 1, 'E', 'acik', 'Kemoterapi ilaç hazırlama alanında  kamu çalışanı bulunmamaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI', '1-Sitotoksik ilaçların eczaneden  ilaç hazırlama ünitesine taşınması', '1-Sitotoksik ilaçlara maruziyet sonucu iş kazaları meydana gelmesi', '1- Sitotoksik ilaç hazırlama çalışanları \n2-Hasta ve hasta yakınları', '1- Taşıma personeli bulunmaktadır.                       2-Dökülme kiti bulunmaktadır.', 1, 0, 3, 6, 3, 54, 'D', '1- Sitotoksik ilaçlar sızdırmaz kaplarda taşınmalı ve etiketlenmelidir.\n2- Taşıma araçlarında dökülme ve saçılmalara karşı müdahale kitleri bulunmalıdır. \n3- Müdahale kiti bulaş olma ihtimaline karşı taşıma kabini dışında tutulmalıdır.                        4- Taşıma güzergâhı önceden belirlenmeli, insan ve hasta trafiğinin yoğun olduğu bölgelerden taşınmamalıdır.', 'FİRMA\nTAŞIMA ÇALIŞANI', 'SİTOTOKSİTİK İLAÇ TAŞIMA SIRASINDA SÜREKLİ KONTROL', 1, 1, 1, 1, 'E', 'acik', 'Kemoterapi ilaç hazırlama alanında  kamu çalışanı bulunmamaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 2: KEMOTERAPİ İLAÇ HAZIRLAMA VE DEPOLAMA ALANI', '1-İlaç hazırlama alanında göz duşu bulunmaması', '1-Sitotoksik ilaçlaraın göze kaçması sonucu iş kazaları meydana gelmesi', '1-Sitotoksik ilaç hazırlama çalışanları', '1-İlaç hazırlama alanı dışında göz duşu bulunmaktadır.', 1, 0, 3, 6, 3, 54, 'D', '1- İlaç hazırlama alanında dökülme saçılmalara karşı göz duşu bulunmalıdır. Göz duşları tek kullanımlık olmalı, kullanıldıktan sonra yenisi tekrar konulmalıdır.                    \n2- Gözduşu kullanma talimatı asılmalıdır.', 'FİRMA', 'SÜREKLİ KONTROL', 1, 1, 1, 1, 'E', 'acik', 'Kemoterapi ilaç hazırlama alanında  kamu çalışanı bulunmamaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: İDARİ BİRİMLER', '1-Çalışan hasta ve hasta yakınları iletişim problemleri, fiziksel sözlü şiddet', '1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma,', '1- Hasta hakları birimi çalışanları                                    2-İdari birim çalışanlar', '1- Panik butonları mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Hasta ve hasta yakınları tarafından çalışanların şiddete uğrayabileceği tüm alanlara sabit panik butonları ya da yaka butonları temin edilmelidir.                                                                                         2- Özellikle şiddet riskinin yoğun olduğu alanlarda ( hasta hakları vb.) alanlarda  masalarının altında bir adet, yakalarında bir adet olamak üzere iki adet panik butonu temin edilmelidir.                                                                                                                                                                                                                                                                                3- Şiddet riskinin yoğun olduğu alanlarda sabit güvenlik personeli  bulundurulmalıdır.                                                                                                                                   4- Çalışanlara iletişim, stres yönetimi ve öfke kontrolü ile mesleki bilgi ve becerilerini arttırıcı eğitimler verilmelidir.', 'İŞVEREN V.                                         İŞ GÜVENLİĞİ UZMANI', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Buat bulunan zemin üzerinde buatların kapaklarının açık olması                                       2- Buat kapaklarının olmaması', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, elektrik yanıkları', '1-İdari birim çalışanları', '1- Topraklama mevcuttur.                                                             2- Kaçak akım rölesi kullanılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1- Tüm buatlar kapaklı ve kapakları kapalı olmalıdır.                                                                                                           2- Buatlara takılan prizler kapakların tam kapatılabilmesi için yatay özellikte olmalı, dikey fişler kullanılmamalıdır.                                                                                                                                       3- Kablolar buat kablo kanallarından geçirilmelidir.                                                                                                       4- Islak elle veya çıplak ayakla elektrikli aletlere dokunulmamalıdır.                                                                                       5- Buat üzerinde bulunan masalarda sıvı gıdalar tüketilmemelidir.', 'İŞVEREN V.                           İDARİ BİRİM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Ofislerde kullanılan elektrikli cihazların kablo, priz veya fişlerinin hasarlı olması', '1- Elektrik çapması.               2- yangın kaynaklı yanıklar ve duman zehirlenmesi', '1-İdari birim çalışanları', '1- Kaçak akım röleleri mevcuttur.                                         2- Topraklama ölçümleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Elektrik kablolarında yırtık, izolasyon bozlukluğu vb. olmamalı, olan kablolar kullanılmamalı değiştirilmelidir.                                                                                                                                      2- Hastane de kullanılan tüm elektrik, uzatma (3\'lü) vb. kablolar halojen free (geç yanan, zehirli gaz çıkarmayan) özellikte olmalıdır.                                                                                                                                                           3- Halojen free olmayan uzatma kablolalarının kulllanımı yasaklanmalı, toplatılmalıdır.                                                                                                                                             4- Islak elle cihazlara dokunulmamalıdır.', 'İŞVEREN V.                           İDARİ BİRİM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Ergonomik olmayan ofis mobilyaları ve çalışma şekli', '1- Postür bozuklukları sonucunda kas-iskelet sistemi hastalıkları,  verimlilik kaybı,', '1-İdari birim çalışanları', '1- Ergonomik risk faktörleri hakkında eğitim verilmiştir.', 1, 0, 6, 3, 7, 126, 'C', '1- Sandalyeler ergonomik tasarıma sahip olmalı, ayaklar düz olarak yere temas etmeli, diz 90 derece açılı olmalı,  sandalyede bel desteği olmalı,  sırt dik, omuzlar rahat, dirsekler 90 derece açılı olmalıdır.                                                                                                                                                                   3- Eğer ayaklar yere temas etmiyorsa, ayaklara ek bir destek yerleştirilmelidir.                                                                                                                                       4- Ekranın üst kenarı göz hizasında veya az aşağısında olmalıdır.', 'İŞVEREN V.                          (EKSİK MALZEMELER) İDARİ BİRİM ÇALIŞANLARI', '3 AY                         HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Sürekli klavye ve mause kullanımı', '1- El ve bilek rahatsızlıkları.                 2- Meslek hastalığı', '1-İdari birim çalışanları', '1- Ergonomik risk faktörleri hakkında eğitim verilmiştir.', 1, 0, 6, 3, 7, 126, 'C', '1- Ergonomik yapıda klavye ve mouse destek pedi temin edilmelidir.                                                                                              2- Kollar yazı yazarken yere paralel tutulmalı ve bilekler bükülmemelidir.                                                                                      3- Tuş karakterleri okunaklı ve yeteri büyüklükte olmalı,uygun olmayanlar değiştirilmelidir.', 'İŞVEREN V.                          (EKSİK MALZEMELER) İDARİ BİRİM ÇALIŞANLARI', '3 AY                         HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Statik duruş, \n2- Uygunsuz duruş ve uzun süre oturarak çalışma', '1- Kas, iskelet sistemi, eklem, el ve bilek rahatsızlıkları.                        2- Dolaşım sistemi rahatsızlıkları.', '1-İdari birim çalışanları', '1- Ergonomik risk faktörleri hakkında eğitim verilmiştir.', 1, 0, 6, 3, 7, 126, 'C', '1- Ayarlanabilir sandalye ve bel desteği sağlanmalıdır.                                                                                             2- Çalışanlar 45 dakikalık periyotlarla yerlerinden kalkarak hareket etmelidir.                                                                                                                                                        3- Masa yüksekliği kişiye göre ayarlanmalıdır.                                                                                              4- Molalarda ofis egzersizleri ve açma/ germe hareketleri yapılmalıdır.', 'İŞVEREN V.                          (EKSİK MALZEMELER) İDARİ BİRİM ÇALIŞANLARI', '3 AY                         HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: İDARİ BİRİMLER', '1-Kayma, takılma ya da düşmeye sebep olabilecek kablolar, düzensiz konulmuş eşya ve ekipmanlar', '1-Kayma, takılma, düşme sonucunda vücut bölümlerinin yaralanması', '1-İdari birim çalışanları', '1-Ofislerin bulunduğu zemin pürüzsüz malzemeden yapılmıştır.', 1, 0, 3, 6, 7, 126, 'C', '1- Zeminde bulunan kablolar çalışanların takılıp düşmeyeceği şekilde toplanmalıdır.                                                                                                                                                       2- Masa, mobilya vb.  ekipmanların yerleşimi geçişe uygun, takılma ve kaymaya neden olmayacak şekilde yerleştirilmelidir.                                                                                                       3- Acil durumlar haricinde koşarak, ani hızlı hareketlerden kaçınılmalıdır.                                                                       4-Çalışanlar kaymaz tabanlı ayakkabı giymeli, topuklu ayakkabı giyilmemelidir.', 'FİRMA                           İDARİ BİRİM ÇALIŞANLARI', '3 AY                    HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Ofislerde uygun olmayan uzatma kabloları kullanılması                            2- Üçlü prize üçlü priz bağlanması.', '1- Elektrik yangını çıkması sonucu, yaralanma, ölüm', '1-İdari birim çalışanları', '1- Kaçak akım röleleri mevcuttur.                                            2- Topraklama yapılmıştır.                                                                               3- Yangın söndürme sistemleri mevcuttur.', 1, 0, 3, 1, 40, 120, 'C', '1- 3 lü uzatma kablolarına, 3 lü uzatma kablosu takılarak kullanılmamalıdır.                                                                                                                                      2- Yüsek akım çeken cihazların beslemesi ayrı fişlerden yapılmalı, uzatma kabloları kullanılmamalıdır.                                                                                                                                                                                                                                                     3- Çalışanların dışarıdan uzatma kablosu getirmesi yasaklanmalıdır.                                                                                                                                   4- Konu ile ilgili kontrol denetim sağlanmalı ,uygun olmayan cihaz ve kablolar toplatılmalıdır.', 'İŞVEREN V.                           İDARİ BİRİM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: İDARİ BİRİMLER', '1- İş stresi', '1- Sinirlilik, stres, uyum problemlerinin oluşması, \n2-Güvensizlik, iş verim kaybı, iletişim sorunları', '1-İdari birim çalışanları', '1- Psikososyal tehlike ve risk faktörleri hakkında eğitim verilmiştir.                                                                            2- Çalışan hakları birimi mevcuttur ve gerektiğinde destek sağlanmaktadır.', 1, 0, 6, 6, 3, 108, 'C', '1- Çalışanların görev, yetki ve sorumlulukları tanımlanmalı ve bu konu hakkında bilgilendirilmelidir.                                                                                                                                                          2- Dinlenme molalarında çalışanlara iş yaptırılmamalıdır.                                                                                           3- Çalışanlara gerçekçi olmayan teslim tarihleri verilmemeli zaman baskısı yaratılmamalıdır.                                                                                                                                                                           4- Monoton ve tekdüze işler sürekli sabit kişilere yaptırılmamalı, işler çalışanlar arasında eşit olarak paylaştırılmalıdır.                                                                                                                                5- Çalışanlara stres ,zaman yönetimi, etkili iletişim, öfke kontrolü vb. konularda eğitim verilmelidir.', 'İŞVEREN V.                         İDARİ BİRİM SORUMLULARI    İŞ GÜVENLİĞİ UZMANI', 'HERGÜN            3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Tanımlı olmayan, mutfak alanı olarak ayrılmamış alanlarda çay ocağı, kahve makinesi, kettle vb elektrikli alet kullanımı', '1-Yangın sonucu yaralanma                                                  2-Elektrik çarpması', '1-İdari birim çalışanları', '1- Kaçak akım röleleri mevcuttur.                                       2- Topraklama yapılmıştır.', 1, 0, 3, 2, 15, 90, 'C', '1- Mutfak olarak tanımlanmış alanlarda sadece çay ve kahve makinesi kullanılmalı, bunların dışındaki aletlerin kullanımı yasaklanmalıdır.                                                                                                          2- Sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.                                                                                                                         3- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.                                                                                                                                           4- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.                                                                                  5- Elektrikli cihazlara ıslak elle temas edilmemelidir.', 'İŞVEREN V.                           İDARİ BİRİM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Acil çıkış kapılarının önlerinin masa, mobilya vb. ekipmanlar ile kapatılmış olması', '1-Acil durumlarda hızlı tahliyenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması', '1-İdari birim çalışanları', '1- Yangın yönlendirme levhaları mevcuttur.                                              2- Tahliye planı asılıdır.', 1, 0, 1, 6, 15, 90, 'C', '1-Acil çıkış kapıları ve acil çıkış yolları açıkça görülebilir olmalı ve acil çıkış kapılarnın ve yollarının önüne ve üzerine malzeme vb. konulmamalıdır.                                                                                                                                                                        2- Acil çıkış yönlendirmelerinin önleri kapatılmamalı, kaçış yolu üzerinde bütün erişim noktalarından görülebilir olmalı, yönlendirmeler 200-240 cm yüksekliğe asılı olmalıdır.                                                                                                                                                                 3- Acil çıkış yollarında en az 150 cm genişliğinde mesafe olması sağlanmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Islak ve kaygan zeminlerin bulunması', '1- Kayma ve düşme sonucu burkulma, kırık, incinme', '1-İdari birim çalışanları', '1- Temizlik sonrası ıslak zemin uyarı levhaları mevcuttur.', 1, 0, 6, 2, 7, 84, 'C', '1- Temizlik sonrası “Islak Zemin” uyarı tabelası konulmalıdır.                                                                   2-Temizlik sonrası ıslak zemin kurulanmalıdır.                                       \n3- Dökülme sonrası zemin hemen temizletilmelidir.                                                                                     4- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.', 'TEMİZLİK ÇAŞIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Elle taşıma işlerinin uygun yapılmaması', '1- Kas, iskelet sistemi, eklem, el ve bilek rahatsızlıkları.                        2- Dolaşım sistemi rahatsızlıkları.', '1-İdari birim çalışanları', '1- Ergonomik risk faktörleri ve elle taşıma işleri hakkında eğitim verilmiştir.                                         2- Ağır işler firma  tarafından yapılmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1- Özellikle çalışanların sırt ve bel incinme risklerini önlemek veya azaltmak için kaldırılacak maksimum yük erkelerde 25 kg, kadınlarda 15 kg\'ı geçmemelidir.                                                                                                                                       2- Yükler belden eğilerek kalıdırılmamalı, dizlerden yere çökülmeli, sırt düz tutulmalı bacak kasları kullanmalı, yük vücuda yakın tutulmalıdır.                                                               3-Dengesiz, devrilme riski olan yükler taşıma aracıyla ya da en az iki kişiyle taşınmalı, yükler görüş alanını kapatmayacak şekilde taşınmalıdır.', 'İDARİ BİRİM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Su sebillerinin bakım ve temizliğinin yapılmaması.                                           2- Su sebillerinin su sızdırması', '1-Enfeksiyon, bulaşıcı hastalıklara yakalanma', '1-İdari birim çalışanları', '1- Enfeksiyon riskleri hakkında eğitim verilmiştir.', 1, 0, 3, 3, 7, 63, 'D', '1- Su sebillerinin bakımları  düzenli aralıklarla yaptırılmalıdır.                                                                                   2- Su sebillerinin temizliği düzenli aralıklarla yaptırılmalıdır.                                                                                                                                                                          3- Su sızıntılarından kaynaklı riskleri önlemek için su sebillerinin altlarına taşma havuzu konulmalıdır.                                                                                                                                                                                                                                      4- Su sebillerinin bulunduğu zemin davamlı kuru tutulmalıdır ve kaygan zemin levhası konulmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Ofis mobilyalarının ve dolapların sabitlenmemesi.', '1- Dolabın çarpması sonucu yaralanma, ezilme, kafa travması.                                   2- Malzemenin düşmesi sonucu yaralanma', '1-İdari birim çalışanları', '1- Çoğu dolap ve raflar duvara sabitlenmiştir.', 1, 0, 3, 3, 7, 63, 'D', '1- Dolap ve raflar en az iki noktadan duvara sabitlenmelidir.                                                                       2- Dolapların üzerine devrilebilecek dosya vb. malzemeler istiflenmemelidir.                                                                                                                                         3- Ağır malzemeler alt raflara yerleştirilmelidir.                                                                                                                                                           4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.', 'İDARİ BİRİM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Termal konfor takibinin yapılmaması', '1- Dikkat kaybı, iş kazası ve meslek hastalıklarında artışlar', '1-İdari birim çalışanları', '1- Merkezi havalandırma sistemi mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1-Çalışma ortamı %35-%75 nem oranında ve 18-24 C derece arasında olması sağlanmalıdır.                                                                                                                                                                                                                   2- Ofislerde çalışan başına 10m3 temiz hava sağlanmalıdır.\n3-Hava akım hızının 0,5 m/sn ortalamada olması sağlanmalıdır.\n4-Çalışma ortamının saatte en az 6-10 kez havalandırılması sağlanmalıdır.', 'İŞVEREN V.', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Aydınlatma yetersizliği, bozulması, titremesi', '1- Görme bozukluklarının oluşması ve ilerlemesi, iş kazalarında artış', '1-İdari birim çalışanları', '1- Bozuk ya da arızalı aydınlatmalar değiştirilmektedir.', 1, 0, 3, 6, 3, 54, 'D', '1- Aydınlatma ölçümü yapılmalı, ofislerde aydınlatma lüks seviyeleri (300–500 lx) şiddeteinde olmalıdır.                                                                                                                                                                              2-Aydınlatma sistemleri sağlam yapıda olmalı, bozulan, yanmayan titreyen aydınlatmalar değiştirilmelidir.\n3-Periyodik göz muayeneleri yılda bir kez yapılmalıdır.', 'İŞVEREN V.                                  İŞYERİ HEKİMİ', '3 AY                              YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Ekranlı araçlarla çalışmalarda sağlık ve güvenlik önlemlerinin alınmaması', '1- Göz yorgunluğu,göz kuruluğu, bulanık görme.                                                                    2- Stres, dikkat dağınıklığı,', '1-İdari birim çalışanları', '1-Yeni nesil monitörler mevcuttur\n2-Ekran titremeyen çözünürlüktedir.', 1, 0, 3, 2, 7, 42, 'D', '1-Ekran parlaklığı ve çözünürlüğü kişiye göre ayarlanmalı, Ekranın çalışana uzaklığı en az 60 cm olmalı ve çalışanın göz hizasında olmalıdır.\n2-Ekran göze uygun ayarlanmalı, Ekran görüntüsü sabit olmalıdır.\n3-Monitör çalışanı eğilmeye zorlamayacak şekilde arkaya eğimli, 15-50 derece arasında, dik oturarak çalışacak şekilde ayarlanmış olmalıdır.\n4- Çalışanların periyodik göz muayenelerinin yapılmalıdır.\n5- 45 dakikada bir gözler dinlendirilmelidir.', 'İŞYERİ HEKİMİ İDARİ BİRİM ÇALIŞANLARI', 'YILDA 1 HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Ofislerde cam malzemelerin bulunması.                                 2- Kırık/çatlak pencere ve dolap camlarının bulunması', '1- El, kol ve yüz bölgesinde kesilme yaralanma', '1-İdari birim çalışanları', '1- Çalışanlar talep ettiklerinde gerekli bakımlar yapılmaktadır.', 1, 0, 3, 2, 7, 42, 'D', '1- Kırık ve hasarlı camlar değiştirilmelidir.                                                                                                   2- Camlı dolap kapakları tüm sabitleme aparatları ( menteşe , fitil, ray, çerçece vb ) kontrol edilmelidir.                                                                                                                                            3- Dolap kapaklarına darbe emici bant veya güvenlik filmi uygulanmalıdır.                                                                                          4- Temperli veya lamine güvenlik camı kullanılmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Çalışanlara, diğer çalışanlar veya yöneticileri tarafından mobing uygulanması', '1-Sinirlilik, stres, depresyon, tükenmişlik sendromu, iş kazalarında artış', '1-İdari birim çalışanları', '1- Çalışan hakları birimi mevcuttur.                                        2- Psikososyal tehlike ve risk faktörleri hakkında eğitim verilmiştir.', 1, 0, 6, 2, 3, 36, 'D', '1-Çalışanlara gerektiğinde psikolojik destek ve danışmanlık sağlanmalıdır.                                                                                                                                         2- Mobing bildirimi alındığında tarafsız inceleme süreci başlatılmalı, taraflar ayrı ayrı dinlenmeli, ve somut veriler ile kayıt tutulmalıdır.                                                                                                                            3- Tükenmişlik yaşayan çalışanlar düşük yoğunluklu birimlere kaydırılmalıdır.                                                                                                                                                             4- Şikayet konusu yönetici ise, yönetici davranış düzeltme sürecine (eğitim, gözlem vb.) alınmalıdır.                                                                                                                                                               5- Sürekli sorun çıkaran çalışanlar için eğitim, görev değişikliği ya da disiplin süreçleri başlatılmalıdır.', 'İŞVEREN V.  ÇALIŞAN HAKLARI BİRİMİ', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Ofis temizliği ve havalandırma mazgallarının temizliğinin yeterince yapılmaması', '1- Enfeksiyona bağlı bulaş ve meslek hastalığı', '1-İdari birim çalışanları', '1- Temizlik, şirket çalışanları tarafından yapılmaktaır.', 1, 0, 3, 3, 3, 27, 'D', '1- Ofisler günlük olarak temizlenmeli. havalanrdırma mazgallarında ayda bir toz temizliği yapılmalıdır.                                                                                                                                                                                               2- Temizlik çizelgeleri/formları bulundurulup düznli kontrolleri yapılmalıdır.', 'TEMİZLİK ÇALIŞANLARI', 'AYDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Ofis çöplerine yanıcı malzemeler atılması', '1- Yangın çıkması', '1-İdari birim çalışanları', '1- Yangın algılama ihbar söndürme sistemleri mevcuttur.', 1, 0, 3, 3, 3, 27, 'D', '1- Çöp kutuları ateş, alev kaynaklarından uzak tutulmalıdır.\n2- Ofis alanlarında çöpler günlük toplanmalı ve çöp poşetleri günlük değiştirilmelidir.  \n3- Yangına sebep olabilecek maddeler ya da birbirleri ile etkileşim sonucu yangın çıkarabilecek maddeler bir arada çöpe atılmamalıdır.                                                                      2- Çöp kovaları ayda bir dezenfekte edilmelidir.', 'TEMİZLİK ÇALIŞANLARI     İDARİ BİRİM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 1: İDARİ BİRİMLER', '1- Fotokopi makinesi, kağıt öğütücü, yazıcı gibi cihazların hareketli ve sıcak parçalarına temas', '1- El veya parmak yaralanmaları/ yanıkları', '1-İdari birim çalışanları', '1- Makine güvenlik kapakları genellikle kapalı durumdadır.            2- Arıza durumunda cihaz bakımları yapılmaktadır.', 1, 0, 3, 3, 3, 27, 'D', '1- Cihazlar çalışırken kapağı açılmamalıdır.\n2- Cihazlar çalışırken hareketli ve sıcak kısımlarına el ve kollar yaklaştırılmamalıdır.                                                                                                                                      3- Güvenlik sensörleri devre dışı bırakılmamalıdır.                                                                                                                                                              4- Güvenlik tertibatı olmayan ya da bozuk olan cihazlar kullanılmamalıdır.', 'İDARİ BİRİM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: KLİNİKLER', '1-Elektrikli mutfak aletleri (çay, kahve, microdalga fırın, airfryer vb.) kullanılması', '1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm', '1-Klinik Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Hastane de mutfak olarak belirlenmiş alanlar dışında hiçbir yerde elektrikli mutfak aletleri kullanılmamalıdır.                                          \n2- Mutfak olarak tanımlanmış alanlarda sadece çay ve kahve makinesi kullanılmalı, bunların dışındaki aletlerin kullanımı yasaklanmalıdır.         \n3- Sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.    \n4- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.\n5- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.', 'İŞVEREN V.   KLİNİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: KLİNİKLER', '1- Oksijen tüplerinin ve diğer basınçlı tüplerin paslı ve korozyonlu olması', '1- Tüplerinin yapısal bütünlüğünün bozulması sonucu gaz kaçağı, patlama meydana gelmesi', '1-Klinik Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-O2 Tüpleri  alanda köşede zincirler ile sabitlenmesi gereken alanlar belirlenmiştir.', 1, 0, 3, 3, 15, 135, 'C', '1- Paslı ve korozyonlu tüpler kullanım dışı bırakılmalıdır.               \n 2- Bu tüplerin tedarikçi firma tarafından hidrostatik test ve ultrasonik kalnlık ölçümleri yapılmalıdır.                                                                          \n3- Gaz sızıntısı durumunda hiçbir onarım yapmadan tüp açık bir alana çıkarılarak tedarikçi firmaya haber verilmelidir.                    \n4- Basınçlı tüpler elektrik ısı kıvılcım kaynaklarından en az 3 metre uzakta bulundurulmalı, en az iki noktadan dik konumda sabitlenmelidir.', 'İŞVEREN V.                                       KLİNİK ÇALIŞANLARI', '3 AY    \n\n HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: KLİNİKLER', '1-Tedavi arabalarının koridorda bulundurulması', '1-Hasta ya da hasta yakınlarının kesici delici aletlere kolay erişmesi sonucu fiziksel şiddet', '1-Klinik çalışanları', '1- Panik butonları mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Tedavi arabaları mümkün olduğunce ortak alanlardan uzakta park edilmelidir.                              \n2-Üzerinde kesinlikle makas, bıçak vb. kesici aletler bulundurulmamalıdır.                                                         3-Ayrıca ilaç rafları kilitli tutulmalı, tehlikeli ya da kırmızı reçeteli ilaçlar kesinlikle bulundurulmamalıdır. \n4-Tedavi arabası içerisindeki tıbbi atık kutusunun kapağının sürekli kapalı tutulmalı ve dolu olmamalıdır.', 'BİRİM SORUMLULARI\nKLİNİK ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: KLİNİKLER', '1- Ultraviole ışınlarına maruziyet', '1- Yanık,\n2- Cilt kanseri, \n3- Gözde katarakt', '1-Klinik çalışanları', '1-UV lambalarında kapak mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- UV lambaları sayaçlı olmalıdır. Sayaç ömrü tamamladığında değişimi yapılmalıdır.\n2-  UV lambalarının kapakları her zaman takılı olmalıdır. \n3-  UV Lambaları çalışanlar bölümdeyken çalıştırılmamalı, mesai bitiminden sonra çalıştırılmalıdır.                                                                  \n4-UV lambasını kapatmak için odaya girildiğinde kişisel koruyucu ekipmanları kullanılmalıdır.                                                                                                                                        5- UV lambaları Ultraviyole lamba kullanımı hakkında eğitim verilmelidir.', 'FİRMA                             KLİNİK  ÇALIŞANLARI                  İŞ GÜVENLİĞİ UZAMNI', 'SAYAÇ ÖMRÜ BİTTİĞİNDE DEĞİŞİM                      HERGÜN                                  3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: KLİNİKLER', '1-Hasta yıkama odası içerisinde duş telefonları ve yataklarının prize yakın olması', '1-Elektrik çarpması', '1-Yanık K. Çalışanları', '1- Prizlerde koruma kapakları mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Hasta yıkama odasında duş telefonları yakınında bulunan bütün prizler eğer imkan dahilindeyse iptal edilmelidir.                                                                          \n 2-Aktif olarak kullanılıyorsa prizler değiştirilerek yerlerine su geçirmez priz (etanj) kullanılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: KLİNİKLER', '1- Hasta odası camlarının yetkisiz kişilerce açılması', '1- İntihara meyil                                                         2-İklim bozuklukları', '1-Klinik çalışanları', NULL, 1, 0, 3, 3, 15, 135, 'C', '1- Hastane de tüm camlar kontrol edilmeli, tam açılabilen camlar en fazla açıklık 15 cm açılacak şekilde ayarlanmalı ve sabitlenmelidir.                                                                                                  2- Pencere kilitleri sadece yetkili bölüm sorumlularında bulunmalı, sadece acil ihtiyaç halinde açılmalıdır. \n3- Hastalarda ya da hasta yakınlarında lokma anahtar tespit edildiğinde derhal birim sorumluları ya da çalışanlar tarafından el konulmalıdır.', 'FİRMA  \nKLİNİK ÇALIŞANLARI', '3 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: KLİNİKLER', '1-Bulaşı Bulunan hastaların izolasyonu', '1- Meslek hastalıkları                                                   2- İş Kazaları', '1-Klinik çalışanları', '1-Tanımlayıcı figürler aktif olarak kullanılmalıdır.', 1, 0, 3, 6, 7, 126, 'C', '1-Klinikte bulaşı bulunan ve bilinen hastalarında odaları Sağlık Bakanlığı\'nın belirlemiş olduğu tanımlayıcı figürler ile belirtilmelidir.    \n2-Sarı Yaprak (Solunum İzolasyonu)- Mavi Çiçek (Damlacık İzolasyonu)-Kırmızı Yıldız (Temas İzolasyonu) Şeklindedir.                                                 \n3-Hastane içerisindeki tüm personele EKK eğitim vermelidir.                                                                     4- Personel Figürlerin bulunduğu odaya girerken KKD\'lerini eksiksiz kullanmalı, koruyucu önlemleri olmadan odaya girmemelidir.', 'EKK \nKLİNİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: KLİNİKLER', '1-Steril olmayan, kontamine olmuş aletlerin açıkta bırakılması', '1-Steril olmayan aletlere temas sonucu iş kazaları enfeksiyon, bulaşıcı hastalık', '1-Klinik Çalışanları', '1-Enfeksiyon Kontrol Komitesi işe başlangıç ve belirli periyotlar ile çalışana eğitim vermektedir.', 1, 0, 3, 6, 7, 126, 'C', '1-Kullanılan, kontamine olmuş aletler bekletilmeden hemen kapaklı ve renk kodlu atık kutularına atılmalıdır.                                                                                                                           2- Sterilazyona gidecek aletlere TS EN 388 standardında kesilme ve delinmeye dayanıklı eldiven olmadan temas edilmemeli, çelik, kapaklı kutulara konulmalıdır.                                                                                                                                                        3- Tek kullanımlık olmayan aletler her kullanımdan sonra dezenfekte edilmelidir.                                                                                                     \n4- Kontamine olmuş aletler, çarşaf, yatak, yorgan vb. yere saplanmamalı, yere atılmamalıdır.                                                                                                                                                          5- Temas edilmesi durumunda, bölge bol su ve sabunla yıkanmalıdır.', 'KLİNİK ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: KLİNİKLER', '1-Hastalardan inhalasyon yoluyla hastalık bulaşması', '1-Enfeksiyon, bulaşıcı hastalıklara yakalanma', '1-Klinik Çalışanları', '1-Havalandırma sisteminin periyodik kontrol raporu mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Bulaşıcı hastalık şüphesi olan hastalar, sonuçları çıkana kadar tek kişilik izolasyon odalarında tutulmalıdır.                                                                                         \n2- Şüpheli hastaların bulunduğu alanın teması bittikten sonra hemen dezenfekte edilmelidir.                                                                                                                                                                                           3- Bulaşıcı hastalıkların yayılma ihtimali yüksek olan bölümlerde  hepa filtreler kullanılmalıdır.                                                                                                                                              4-Tanı konulmuş hastalar negatif basınçlı odalara alınarak izole edilmelidir.                                                                                                                        5-Çalışanlar N95 ya da TS EN 149 standrtdında FFP2 filtreli maske, yüz siperi, TS EN 455  standardında eldiven kullanmalıdır.', 'BİRİM SORUMLUSU KLİNİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: KLİNİKLER', '1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması', '1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması', '1-Klinik Çalışanları', '1-Alanlara özel olarak KKD\'ler alanda mevcuttur.                                                                                  2- Tüm çalışanlar KKD Zimmet formunu imzalamıştır.', 1, 0, 3, 6, 7, 126, 'C', '1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan kkd\'ler temin edilmelidir.\n2- Çalışanların maskeleri N95 ya da TS EN149 A1 standardında,göz koruyucuları TS EN 166 standardına uygun ve tam kapalı tip, iş eldivenleri TS EN 455 standardına, kesilmelere dayanıklı TS EN 388 standardına, çalışanların önlükleri sıvı geçirmez önlük/ cerrahi önlük TS EN ISO 13688 ve TS EN 13795 standartlarında iş ayakkabıları kaymaz tabanlı olmalıdır.                                                                                                                                                                                                 3- Bütün kişisel koruyucular çalışanlara zimmetlenmelidir.                                                                       4- Kişisel koruyucu donanımlar çalışanlar tarafından eksiksiz kullanılmalıdır.', 'İŞVEREN V. (EKSİK KKD TEMİNİ)\n\nKLİNİK ÇALIŞANLARI', '3 AY  \n\n                                HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: KLİNİKLER', '1-Çalışma alanında (klinik çalışma deskleri) mutfak alanları dışında yiyecek-içecek tüketilmesi', '1-Enfeksiyon kaynaklı bulaş', '1-Klinik Çalışanları', '1-Klinik içerisinde personellere dinlenme alanları belirlenmiştir.', 1, 0, 3, 6, 7, 126, 'C', '1-Çalışanlar müdahale odası, hasta odası gibi enfeksiyon kaynağı bulundurulabilecek alanlarda yiyecek-içecek tüketmemelidir.                                               \n2-Yemek ve çay saatlerinden önce el, yüz ve vücut temizliği sağlanmalıdır.                                                                                                                                                                                                                                                                                                                                                                                                      3-Çalışanlara, yiyecek–içecek tüketiminin hastane enfeksiyonlarına, kimyasal/biyolojik madde bulaşına ve çalışan sağlığına yönelik risklerine karşı eğitim verilmelidir.', 'İŞ GÜVENLİĞİ UZMANI     KLİNİK ÇALIŞANLARI', '3 AY \n\n                              HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: KLİNİKLER', '1-Tehlikeli kimyasalların yanlış depolanması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması                                 2- Yangın meydana gelmesi', '1-Klinik Çalışanları', '1- Kimyasallar depo alanında depolanmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Kimyasal maddeler depolama matirsine göre depolanmalıdır.                                                        2- Yanıcı kimyasallar elektrik kaynaklarından uzak depolanmalıdır.                                                                               3- Kimyasal maddelerin ağzı açık olmamalı, dik olarak istiflenmelidir.                                              4- Ağzı açılmış kimyasal madde kaplarının altına taşma kapları konulmalıdır.', 'KLİNİK ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: KLİNİKLER', '1- Kimyasal madde deposunda göz duşu ve döküntü kiti bulunmaması                                               2- Çalışanların kimyasallar hakkında bilgi sahibi olmaması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1-Klinik Çalışanları', '1- Kimyasallar depo alanında depolanmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.                                              3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               4-Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.                              5- Çalışanlara MSDS ve kimyasalların güvenli kullanımı konusunda eğitimler verilmelidir.', 'İŞVEREN V.                                       İŞ GÜVENLİĞİ UZMANI', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: KLİNİKLER', '1-Basınçlı tüplerin hatalı kullanılması', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1-Klinik Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Oksijen tüpü sabitleme aparatları bulunmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Oksijen tüplerine yağlı, kremli eller ile temas edilmemeli, vanaları yağlanmamalıdır.                                                                                                                                   2- Tüpler ısı kaynaklarından ve güneşin etkisinden uzak tutulmalıdır.                                                                                                                                    3- Manometreler sağlam olmalı, kırık olanlar değiştirilmelidir.                                       \n4- Basınçlı tüpler zeminde sabitlenmeden bırakılmamalı, sabitleme aparatlarına takılmalı ve 2 noktadan zincir ya da halatla bağlanmalıdır.', 'KLİNİK ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: KLİNİKLER', '1-Buat kapaklarının açık olması, kapakların kırık olması', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, elektrik yanıkları, ölüm,', '1-Klinik çalışanları', '1-30 MA kaçak akım rölerleri mevcuttur.\n2- Topraklama ölçümleri mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Buat kapakları kapalı tutulmalıdır.                                                                         \n2-Kırık buat kapakları değiştirilmeli, vidalar ile tutturulmamalıdır.  \n3- Buatlara fişler yatay takılmalı, dikey fişler kullanılmamalı, buatların açık kalması önlenmelidir.       \n4- Buatların üzerinde ki masalarda bir şey yenilip içilmemelidir.', 'FİRMA  \nKLİNİK ÇALIŞANLARI', '3 AY \n                          HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: KLİNİKLER', '1-Hasta odalarında refakatçilerin çaycı, kahve makinesi vb. elektrikli ev aletlerini kullanması', '1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm', '1-Klinik Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Hasta/Hasta yakını ve ziyaretçiler kliniğe gelirken güvenlik kontrolünden geçmeli, güvenlik personelleri kliniklere elektrikli ev aletlerinin çıkarılması engellenmelidir.                                                                                                                                                  2-Klinikler içerisinde hasta odalarında tespit edildiği takdirde personel tarafından uyarılmalıdır.', 'KLİNİK ÇALIŞANLARI    GÜVENLİK PERSONELİ', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: KLİNİKLER', '1-Islak/Kaygan zemin oluşması', '1-Düşme, denge kaybı sonucunda vücut bölümlerinin yaralanması', '1-Klinik çalışanları', '1-Kliniklerde sabit temizlik çalışanları mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.    \n2- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\n3- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.', 'TEMİZLİK ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: KLİNİKLER', '1- Elektrik kabloların da aşırı yükleme olması \n2- Elektrik kablolarına su ve buhar temas etmesi', '1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm', '1-Klinik Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Hastane de kullanılan tüm elektrik, uzatma (3\'lü) vb. kablolar halojen free (geç yanan, zehirli gaz çıkarmayan) özellikte olmalıdır.                      \n2- 3 lü uzatma kablolarına, 3 lü uzatma kablosu kullanarak kullanılmamalıdır.                                                                                                     3- Yüsek akım çeken cihazlar (kettle çay makinesi vb.) beslemesi ayrı fişlerden yapılmalı, uzatma kabloları kullanılmamalıdır.                                                                                                             4- Elektrik kablolarının su ve buhar ile teması önlenmelidir.\n5- Çalışanların dışarıdan uzatma kablosu getirmesi yasaklanmalıdır.', 'İŞVEREN V.\nKLİNİK ÇALIŞANLARI', '3 AY \n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: KLİNİKLER', '1-Banyodan su taşkınlarının yaşanması', '1-Su baskınları                                                     2-Sıvıya bağlı Elektrik çarpma ve kaçakları                                                                              3- Kayma, Düşme', '1-Klinik çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-Hasta odalarında banyo giderlerinin düzenli bakım ve onarımları yapılarak tıkanma problemleri engellenmelidir.                                                               \n2- Duşakabin içerisinde eğim tekrar düzenlenmeli, gider doğru yokuş yapılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: KLİNİKLER', '1- Uygunsuz Formaldehit Kullanımı', '1- Meslek hastalıkları                                                   2- İş Kazaları', '1-K.D Septik                        2-Hemotoloji K.', '1-Formaldehit ile çalışan personele İSGB tarafından Formaldehitile güvenli Çalışma eğitimi verilmiştir.', 1, 0, 3, 6, 7, 126, 'C', '1- 21.10.2025 tarihinde hazırlanan Yöntem Beyan\'ına göre firma tarafından formaldehit, patoloji laboratuvarında porsiyonlanarak gönderilmelidir\n2- Formaldehit büyük kaplardan, küçük kaplara aktarılırken taşma kapları kullanılmalı, zemine dökülmesi önlenmelidir.\n3- Formaldehit dökülmesine karşı döküntü kitleri temin edilmelidir.\n4- Çalışanlar formaldehit ile çalışma esnasında EN 149 standardında ffp3 maske, eldiven ve koruyucu gözlük kullanmalıdır.', 'İŞVEREN V.\nKLİNİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: KLİNİKLER', '1- Kan ve vücut sıvılarının göz ve cilde temas etmesi', '1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma', '1-Klinik Çalışanları', '1-KKD\'ler mevcuttur.                                         2- Çalışanlara KKD önemi ve kullanımı konusunda eğitim verilmektedir.', 1, 0, 6, 6, 3, 108, 'C', '1-Çalışanlar TS EN 455  standardında eldiven, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında maske vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.', 'İŞYERİ HEKİMİ \n\n KLİNİK ÇALIŞANLARI', 'MARUZİYET OLMASI DURUMUNDA    HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 1: KLİNİKLER', '1- Kesici delici aletlerin emniyetsiz kullanılması', '1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma', '1-Klinik Çalışanları', '1- Kesici delici alet kutuları mevcttur.                2-Çalışanlara kesici delici aletlerin güvenli kullanımı konusunda eğitim verilmektedir.', 1, 0, 6, 6, 3, 108, 'C', '1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                                 3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                                                                                                5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.', 'KLİNİK ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 1: KLİNİKLER', '1-Atık varillerin kapaklarının açık bırakılması', '1-Toksik maddelere maruziyet sonucu iş kazaları olması', '1-Klinik Çalışanları', '1-Renk kodlarına göre atık varilleri mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1- Atık varillerinin kapağı sürekli olarak kapalı halde tutulmalıdır,                                                                  2- Atıklar karıştırılmamalı, her atık türü için (Tıbbi, Tehlikeli, Evsel)belirlenmiş renk kodlu atık kutularına atılmalıdır.                                                                                                                                                    3- Kesici delici aletler sadece kesici delici alet kutusuna atılmalıdır.                                                     4- Atık varilleri en fazla 3/4 oranında dolduğunda değiştirilmelidir.', 'KLİNİK ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 1: KLİNİKLER', '1-Defibilatörün emniyetsiz kullanımı', '1-Defibrilatör kullanımı sırasında elektrik çarpması, elektrik yanıkları oluşması', '1- Defbilatör kullanan çalışanlar                                                     2- Diğer ilgili çalışanlar', '1-Makinelerin periyodik kontrolleri yapılmaktadır.', 1, 0, 3, 2, 15, 90, 'C', '1-Defibrilasyon esnasında hastaya elektrotlara ve diğer iletken nesnelere dokunulmamalıdır.\n2-Hastaya ıslak  ve iletken ortamlarda defibrilasyon uygulanmamalı, hastanın göğsünde ıslaklık, jel, ter olmamalı, hastanın göğüsü kurulanmalıdır.\n3-Defibrilatör cihazı oksijen tüpü, alkol vb. yanıcı sıvı ve gazların bulunduğu ortamlarda kullanılmamalıdır.                                                                               \n4- Hastanın ve defibilatörü kullanan çalışanın üzerinde metal eşyalar bulunmamalıdır.                                                                                           \n5- Ortamda bulunan diğer çalışanlar en az 1 metre uzakta bulunmalıdır.', 'DEFİLBİLATÖR KULLANAN ÇALIŞANLAR', 'DEFİBİLATÖR KULLANIM SIRASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM 1: KLİNİKLER', '1-O2 tüplerinin kliniklerde  fazla sayıda  bulundurulması', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1-Klinik Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Acil durum arabaları dışında bulundurulan her O2 tüpü zincirler ile belirlenen yerlerde sabitlenerek bulundurulmaktadır', 1, 0, 3, 3, 7, 63, 'D', '1-Klinik alanlarında O2 tüplerinin fazla istiflenmemesine her alanda klinik özelliğine göre 1 ya da 2 adet bulundurulmalıdır.      \n2- Merkezi Oksijen sistemi kullanılmalı,  taşınablilir O2 tüpleri fazla sayıda bulundurulmamalıdır. \n3- Oksijen tüpü kullanım talimatı kullanılan alanlara asılmalıdır.', 'BİRİM SORUMLULARI\nKLİNİK ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM 1: KLİNİKLER', '1-Çalışan hasta ve hasta yakınları iletişim problemleri, fiziksel sözlü şiddet,', '1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma,', '1-Klinik çalışanları', '1-Panik butonları mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Hasta ve hasta yakınları tarafından çalışanların şiddete uğrayabileceği tüm alanlara sabit panik butonları ilave olarak yaka butonları temin edilmelidir.                                                                                                                                                                                                         2- Şiddet riskinin yoğun olduğu alanlarda butonlara ilave olarak sabit güvenlik personeli  bulundurulmalıdır.                                         \n3- Çalışanlara iletişim, stres yönetimi ve öfke kontrolü ile mesleki bilgi ve becerilerini arttırıcı eğitimler verilmelidir.', 'İŞVEREN V.\nİŞ GÜVENLİĞİ UZMANI', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 27, 'BÖLÜM 1: KLİNİKLER', '1-Sabitlenmemiş dolap ve raflar', '1-Devrilme, düşme ya da çarpma sonucunda vücut bölümlerinin sıkışması, yaralanması', '1-Klinik çalışanları', '1-Birçok dolap ve raf sabitlenmiştir.', 1, 0, 3, 3, 7, 63, 'D', '1-Sabitlenmemiş doalp ve raflar en az iki noktadan sabitlenmelidir.\n2-Düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.\n3-Ağır malzeme ve ekipmanlar yüksek istiflenmemeli, dolap üzerine malzeme konulamamlıdır.                                    \n4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.', 'İŞVEREN V.\nKLİNİK ÇALIŞANLARI', '3 AY \n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 28, 'BÖLÜM 1: KLİNİKLER', '1-Hasta taşıma veya pozisyon verme sırasında ergonomik olmayan davranışlar', '1-Kas-İskelet sistemi rahatsızlıkları, meslek hastalığı veya işle ilgili hastalıklar                                                             2- iş kazaları', '1-Klinik çalışanları', '1-Çalışanlara Ergonomik çalışma eğitimi verilmektedir.', 1, 0, 3, 3, 7, 63, 'D', '1- Hasta taşıma için kaydırma örtüsü, hasta kaldırma lifti, tekerlekli sandalye, sedye gibi ekipmanlar kullanılmalıdır.                                             \n2- Yatak kenarlıkları kaldırılmalı, frenlerin kilitlenmelidir. Kateter, dren ve monitör bağlantılarının sabitlenmelidir.                                                                                                     3- Hastalara pozisyon verme ve taşıma esnasında en az 2 kişi tarafından yapılmalı, zemin kuru olmalıdır.', 'KLİNİK ÇALIŞANLARI    TAŞIMA ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 29, 'BÖLÜM 1: KLİNİKLER', '1-Hasta taşıma ekipmanının ağırlık testi', '1- Hastanın personel üzerine düşmesi                                 2-Ergonomik yaralanmalar', '1-Yanık Kliniği', NULL, 1, 0, 3, 3, 7, 63, 'D', '1-Banyo içerisinde yardıma muhtaç hastaları küvete yerleştirmek amacıyla kullanılan hasta taşıma ekipmanının kalıdırma sistemlerinin kontrol ve bakımları yapılmalıdır.', 'BİYOMEDİKAL HİZMETLER', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 30, 'BÖLÜM 1: KLİNİKLER', '1-Hasta yıkama odasının giderlerinin uygun olmaması', '1-Su taşmaları, baskınlar                                     2-Kaygan Zemin sonucu düşme, iş kazaları', '1-Yanık K. Banyo personeli', '1-Hasta odasında drenaj kanalı mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1-Hasta yıkama odasında bulunan drenaj kanalına doğru eğim bulundurulmalıdır.                                                           \n2-Su gideri uygun genişlikte olmalı, arıza, tıkanma durumlarında derhal bildirilmeli ve onarımları yaptırılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 31, 'BÖLÜM 1: KLİNİKLER', '1-Portable röntgen cihazlarının kullanılması', '1-Radyasyon maruziyeti sonucu meslek hastalıkları', '1-Klinik çalışanları', '1-Kurşun önlükler mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Taşınabilir röntgen cihazı ile yapılan çekimler de kurşun paravan kullanılmalıdır.                                                                                                                                                               2- Çekim yapılan alanda hasta ve çekim yapan çalışan dışında kimse olmamalı, zorunlu hallerde bulunulması gerekirse(TS EN 61331 standardında kurşun önlük troid koruyucu vb.kişisel koruyucu ekipmanlar kullanılmalıdır.                                                                                                       3- Çekim yapılan odaların kapıları kapatılmalıdır.                                                                                           4- Açık alanlarda yapılan çekimlerde çalışanlar en az 2 metre uzakta durmalıdır.', 'RADYOLOJİ ÇALIŞANLARI       KLİNİK ÇALIŞANLARI', 'ÇEKİM ESANASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 32, 'BÖLÜM 1: KLİNİKLER', '1-Hasta odalarında sigara içilmesi', '1- Yangın çıkması                                                                             2-Sigara dumanına maruziyet', '1-Hasta,                                   2-Hasta yakını,                        3-Çalışanlar', '1-Duman dedektörleri mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Hastalar Kliniğe yatarken Sigara içmeyeceği konusunda yazılı taahhüt alınmalıdır.                                                                 \n2- Birim sorumlusu ve çalışanlar sürekli alan gözetimi yaparak tespit edildiğinde hasta uyarılmalı, gerekirse idareye bildirilmelidir.                                \n3- Duman dedektörleri her zaman aktif olmalıdır.\n4- Hasta odalarında sigara içildiği tespit edilmesi halinde hasta ya da hasta yakınlarına yaptırım uygulanmalıdır.', 'İŞVEREN V.   KLİNİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 33, 'BÖLÜM 1: KLİNİKLER', '1- Klinik alanında hastalara kemoterapi uygulanması', '1- Sitotoksik İlaçlara bağlı İş Kazaları, Hastalıklar', '1-Klinik çalışanları', NULL, 1, 0, 3, 3, 7, 63, 'D', '1- Zorunlu olmayan durumlar dışında kliniklerde kemoterapi uygulaması yapılmamalıdır.                                             \n2-Kemoterapi uygulaması, sadece yetkili ve eğitimli çalışanlar tarafından yapılmaldır.                                                                                                                             \n3- Sitotoksik ilaçların dökülmesi ihtimaline karşı, kliniklere kemoterapi ilaç seti ile birlikte döküntü kiti de getirimelidir.', 'KEMOTERAPİ UYGULAYAN ÇALIŞANLAR   KLİNİK ÇALIŞANLARI', 'KEMOTERAPİ UYGULANMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 34, 'BÖLÜM 1: KLİNİKLER', '1-Tutuklu Servisine Bağlı Tehlikeler', '1- ARBEDE VE İSYANLAR                                               2- SABOTAJ                                                                      3- DARP SONUCU İŞ KAZALARI', '1-Klinik çalışanları', '1-Yaka butonları bulunmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1-Alanlar mümkün olduğunca 7/24 kamera sistemi ile izlenmelidir.                                                                2-Yeterli infaz koruma memuru bulundurulmalıdır.                                                                                                   \n3-Alanlarda bulunan panik butonları (1111) beyaz kod sürekli aktif olarak çalışıyor durumda bulundurulmalıdır, arıza durumunda talep açılmalı, derhal onarımı yapılmalıdır.                                             \n4-Çalışanların her birinde acil durum butonu bulunmalıdır.                                                                 5- Hükümlüler poliklinik alanlarına çıkarılırken sirkülasyonun az olduğu alanlardan geçişi sağlanarak, görevli sayısı tutuklu sayısınca bulundurulmalıdır.', 'ADALET BAKANLIĞI İNFAZ KORUMA MEMURLARI VE SORUMLULARI (KONTROL VE KORUMA)', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 35, 'BÖLÜM 1: KLİNİKLER', '1-Oksijen ve basınçlı tüplerin uygunsuz taşınması', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1-Klinik Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Hasta taşıma esnasında sO2 tüplerini sabitlemek için aparatlar mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1- Hasta yatakları, taşıma araçları vb. basınçlı tüp taşınan ekipmanlarda tüpleri sabitlemek için aparatlar bulunmalı, tüpler en az iki noktadan sabitlenerek taşınmalıdır.                                                                                                \n2- Tüplerin taşınması esnasında vanaları kapalı olmalı, dik taşınmalı, kapağı kapalı olmalıdır.                                                                               \n3- Taşıma esnasında tüplerin başka cisimlere çarpması engellenmelidir.', 'KLİNİK ÇALIŞANLARI    TAŞIMA ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 36, 'BÖLÜM 1: KLİNİKLER', '1-Parafin Kullanımı (yanık K.)', '1-Dökülme, saçılma sonrası kaygan zemine bağlı kayma, düşme                                                                                  2-yangının büyümesi', '1-Yanık K. Banyo', '1-Yangın algılama ihbar ve söndürme sistemleri mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1-Parafin maddesi depolama sıcaklığına dikkat edilerek ergimesi önlenmelidir.                                      \n2-Yere dökülme durumunda derhal alan temizlenmelidir.                                                               3-Depolama alanında yanııcı maddeler ile bir arada depolanmamalıdır.                                                          4-Parafinler her türlü ısı kaynağından ve ısı kaynaklarından uzak tutulmalıdır.                                      \n5- Parafinin bulunduğu metal kabın statik topraklaması yapılmalıdır.', 'BİRİM SORUMLULARI\nKLİNİK ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 37, 'BÖLÜM 1: KLİNİKLER', '1-Dinlenme alanlarında koltuklar ve sandalyelerde tahta kurularının olması', '1-Zehirsiz böcek ısırığı,                                        2-Allerjik reaksiyon', '1-Klinik çalışanları', '1- İlaçlama yapılmaktadır.', 1, 0, 3, 3, 3, 27, 'D', '1- Kliniklerde kullanılan sandalyelerde tahta kurusu olması halinde sandalyeler yenileri ile değiştirilmelidir.\n2- Değiştirelemeyen sandalyeler yüksek sıcaklıkta buharla dezenfekte edilmelidir. \n3-İlaçlama malzemesi olarak kimyasallar kullanılmamalıdır.', 'HAŞERE KOMİSYONU', 'TAHTA KURUSU OLMASI DURUMUNDA', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Medikal oksijen (O2 ) kullanımına bağlı maruziyetler', 'H270- Yangına yol açabilir veya yangını oksitleyici.\nH280 – Basınç altında gaz içerir; ısındığında patlayabilir.', '1- Medikal oksijen kullanan, alanda bulunan, depolayan ve taşıyan  tüm çalışanlar, hasta ve hasta yakınları', '1- Kimyasal Maddelerle ve basınçlı kaplarla çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 6, 15, 270, 'B', 'İlk Yardım Önlemleri:  Solunması: Uzun müddet yüksek konsantrasyonlarda maruz kalınmaması şartıyla atmosfer basıncında, yüksek safiyetteki oksijen toksik değildir. Deri ile Temas: Bu üründen kaynaklanan yan etkiler beklenmemektedir.Göz ile Temas: Bu üründen kaynaklanan yan etkiler beklenmemektedir.Ağız Yolu ile Temas: Normal koşullarda yutma olası değildir.\nSindirim sistemi İle Temas: Olası bir maruziyet yolu olarak kabul edilmez.                                                                                 Yangınla mücadele: Oksijen, oksitleyici bir gaz olduğundan yangın ortamı, yüksek oksijen yoğunluğuna maruz kalmamalıdır. Yangına maruz kalan tüpler, yangın esnasında ve sonrasında emniyetli bir mesafeden su ile soğutulmalıdır. Gaz sıkışmasını önlemek amacı ile tüpün ventil kısmına su tutulmamalıdır. Oksijenin direkt yanması söz konusu değildir, daha çok tutuşan, yanan malzemeye göre södürücü seçilmelidir. Karbondioksit, kuru kimyevi maddeler veya buharlaşan sıvı, yangın söndürücü olarak genel kullanılanlardandır.                                                                                                       Kişisel koruyucu ekipman kullanımı : Havadaki Oksijen seviyesinin % 23,5 üstüne çıkmasını engelleyecek şekilde havalandırma yapılmalıdır. Uzun müddet yüksek konsantrasyonlara maruz kalınmaması şartıyla atmosfer basıncında, yüksek safiyetteki oksijen toksik değildir. Solunum Sisteminin Korunması: Uzun süre yüksek konsantrasyondaki oksijen istenilerek solunmamalıdır\nEllerin Korunması: EN 388 standartlarında sağlam iş eldiveni kullanılmalıdır\nGözlerin Korunması: EN 166 standartlarına uygun yan siperli koruyucu gözlük kullanılmalıdır. Cildin Korunması: Oksijene doymuş elbiseler havalandırılmalıdır. Bütün ekipman, takımlar ve elbiseler yağdan arındırılmış olmalıdır', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Medikal sıvı oksijen kullanımına bağlı maruziyetler', 'H220 – Aşırı alevlenir gaz\nH350 – Kansere yol açabilir.\nH340 – Genetik hasara yol açabilir\nH331 – Solunması halinde toksiktir\nH319 – Ciddi göz tahrişine yol açar\nH335 – Solunum yolu tahrişine yol açar\nH315 – Cilt tahrişine yol açar\nH280 – Basınçlı gaz içerir; ısıtıldığında patlayabilir', '1- Medikal sıvı oksijen kullanan, alanda bulunan, depolayan ve taşıyan  tüm çalışanlar, hasta ve hasta yakınları', '1- Kimyasal Maddelerle ve basınçlı kaplarla çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 6, 15, 270, 'B', 'İlk yardım önlemleri: Dikkat ! Aşırı maruz kalınan tüm vakalarda derhal tıbbi müdahale zorunludur. Kazazede bir an önce doktora ya da sağlık kuruluşuna götürülmelidir.\nTeneffüs Edilmesi: Bilinci yerinde olan kazazedeye yardım edilerek gazla kirlenmemiş bir alana götürülmeli, uzanmaları sağlanmalı, sıcak tutulmalı ve bilinci yerinde olan kazazedeye yeterli miktarda ılık su verilerek midelerindeki etilen oksit yıkanmalıdır. Deri ile Temas: Buharlaşan sıvının deriye teması soğuk yanığı veya dokunun donmasına sebep olabilir. Etkilenen bölgeler ılık su ile en az 15 dakika yıkanmalıdır. Sıcak su kullanılmamalıdır. Yanık bölge ovulmamalı ve masaj yapılmamalıdır. Göz ile Temas: Gaz ile temas eden kişiler kontakt lens kullanmamalıdır. Göz bölgesi en az 15 dakika boyunca ılık su ile yıkanmalıdır. Sindirim sistemi İle Temas: Olası bir maruziyet yolu olarak kabul edilmez.Akut: Kuru boğaz ağrısı, burun mukoza membranlarında tahriş, merkezi sinir sistemi depresyonu, mide bulantısı, kusma, başağrısı, baş dönmesi, bilinç bozukluğu, cilt şişmesi, kızarık deri, ciltte su toplama (kabarcıklar). Su ile temas ettikten sonra: kostik yanıklar / cilt aşınması. Yüksek konsantarasyona maruz kalındığında: kalp atışlarında düzensizlik, solunum güçlükleri.  Yangınla mücadele: Karbon dioksit, kuru kimyasal (BC tozu), su, alkole dayanıklı köpük bilinen uygun yangın söndürme yöntemleridir. Kişisel koruyucu ekipman kullanımı: Solunum Sisteminin Korunması:  EN 137 standardına uygun tam yüz maskeli solunum koruma cihazı veya bağımsız solunum cihazı acil durumda kullanılmak üzere hazır olmalıdır. Bu donanımı “artı basınç kullanım” konumunda çalıştırın. Günlük çalışmada hava beslemeli solunum cihazı kullanılmalıdır. Ellerin Korunması: Etilen oksit plastiklerin çoğunu yumuşatır ve lastik-esaslı malzemelerin yüzeyinde kabarıklar oluşturur. Etilen oksite dayanıklı, bütil kauçuktan imal edilmiş EN 511 standardına uygun iş eldivenleri kullanılmalıdır. Gözlerin Korunması: EN 166 standartlarına uygun yan siperli koruyucu gözlük kullanılmalıdır. Cildin Korunması: EN 342, EN ISO 13688 standardına uygun etilen oksite dayanıklı iş elbiseleri ve çelik burunlu ayakkabı giyilmelidir.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Formaldehit kullanımına bağlı maruziyet', 'H226 Alevlenir sıvı ve buhar. H301 Yutulduğunda, ciltle temas ettiğinde veya solunduğunda toksiktir. \nH314 - Ciddi cilt yanıklarına ve göz hasarına yol açar.\nH317 - Alerjik cilt reaksiyonlarına yol açar.\nH350 -  Kansere yol açabilir.', '1- Formaldehit kullanan ve alanda bulunan tüm personeller', '1- Kimyasal Maddelerle çalışmalarda sağlık ve güvenlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 6, 2, 15, 180, 'C', 'İlk yardım önlemleri:   Gözlerle Temas: Lens takılı ise çıkarın. Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkayın. Problemin devam etmesi halinde bir doktora danışın. Ciltle Temas: Kirlenmiş giysileri çıkarın. Hemen bol su ile yıkayınız. Tahriş devam ediyorsa, bir doktora danışınız. Kirlenmiş giysilerinizi tekrar kullanmadan önce yıkayın. Solunum: Kişiyi açık havaya çıkarınız. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım / öneri alınız. Yutma: Tıbbi tavsiye / yardım alın. Sadece doktor tavsiyesi üzerine kusturmaya çalışınız. Bir doktor tarafından izin verilmedikçe, bilinçsiz bir kişiye asla ağızdan bir şey vermeyin.                                                                                                                                                                                             Yangınla mücadele:   Yangın söndürücü maddeler şunlardır: karbondioksit, köpük, kimyasal toz.  Yanma sonucu zehirli gazlar açığa çıkabilir.                                                                                                                                                                      Kişisel koruyucu ekipman kullanımı:   Elleri Koruma: kategori III iş eldivenleri ile koruyun (ref. EN 374 standardı). Cildi Koruma: koruyucu kıyafetler giyilmelidir. Gözleri Koruma: Hava geçirmez koruyucu gözlük takılması tavsiye edilir (ref. EN 166 standardı). Solunumu Koruma: Yetersiz havalandırma veya toz solunma riski olduğu hallerde uygun parçacık filtreli solunum cihazı (tip P2) kullanın. kendi kendine yeterli açık devreli basınçlı hava solunum cihazı (ref. EN 137 standardı) veya dış hava alımlı solunum cihazı (ref. EN 138 standardı) kullanın. EN 14387 Sıtandardına uygun olmalıdır.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Sitotoksik ilaç kullanımına bağlı maruziyet', 'H350- Kanser yapabilir.\nH340- Genetik hasara yol açabilir.\nH302- Yutulduğunda zararlıdır.\nH319- Göz tahrişi yapar.\nH373- Uzun süreli maruziyette organlara zarar verebilir.', '1- Sitotoksik ilaçları hazırlayan, hastaya kullanan, taşıyan ve alanda bulunan tüm çalışanlar.', '1- Kanserojen veya mutejen maddelerle çalışmalarda sağlık ve güvenlik önlemleri hakkında eğitim verilmiştir.', 1, 0, 6, 2, 15, 180, 'C', 'İlk Yardım Önlemleri : Göz ile temas: Göz kapakları açık tutularak en az 15 dakika bol su ile yıkanmalı. Derhal tıbbi yardım istenmeli. Cilt teması:  Kirlenmiş giysiler çıkarılmalı. Temas eden bölge bol su ve sabun ile yıkanmalı. Tıbbi yardım gerekebilir.\nYutma: Bilinci kapalı kişiye asla ağızdan bir şey verilmemeli. Ağız suyla çalkalanmalı. Kusturmaya zorlamayın (tıbbi personel yönlendirmedikçe). Derhal tıbbi yardım çağırılmalı. Soluma:  Kişi temiz havaya çıkarılmalı ve dinlenmesi sağlanmalı. Derhal tıbbi yardım istenmeli. \nYangınla mücadele: Uygun söndürücüler: Karbondioksit (CO₂), kuru kimyasal toz, su spreyi.  Yanma ürünleri: CO₂, CO, azot oksitleri (NOx), fosfor oksitleri.  Özel tehlikeler: İnce partiküller (toz, aerosol) yangın ve/veya patlamaya katkıda bulunabilir. \nKişisel Koruyucu Ekipman Kullanımı: İş hijyeni mühendislik kontrolleri öncelikli: Kapalı sistemler, lokal egzoz havalandırma, HEPA filtreleme. Eldiven: Eldivenler (Kemoterapi / Sitotoksik İlaç Dayanımlı)Standartlar: EN ISO 374-1:2016 / Type B veya C Göz koruma: Kimyasal sıçramaya karşı koruyucu gözlük/face shieldEN 166:2001 Giysi: Tek kullanımlık, kimyasal geçirmez önlük/tulum.EN 14126:2003  Solunum: Toz/mist aerosol üretildiğinde uygun partikül filtreli solunum cihazı (uygun koruma faktörlü) kullanılmalı.EN 149:2001 + A1:2009 → Partikül filtreli yarım maskeler (FFP1, FFP2, FFP3)', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Medikal azot prtoksit kullanımına bağlı maruziyetler', 'H270 – Yangına yol açabilir veya yangını siddetlendirilebilir; oksitleyici.\nH280 – Basınç altında gaz içerir; ısındığında patlayabilir', '1- Medikal azot protoksit kullanan, alanda bulunan,  depolayan ve taşıyan  tüm  çalışanlar, hasta ve hasta yakınları', '1- Kimyasal Maddelerle ve basınçlı kaplarla çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 3, 15, 135, 'C', 'lk Yardım Önlemlerinin: Teneffüs Edilmesi: Yüksek konsantrasyonlarda uzun süre solunduğu takdirde baş dönmesi, mide bulantısı ve baygınlık belirtisi ile birlikte ölüme neden olabilir. Çalışanın riskini en aza indirerek kazazede derhal temiz bir sahaya götürülmelidir. Deri ile Temas: Deri yolu ile temas veya soğuk yanığı durumunda; etkilenen bölgeler ılık su ile en az 15 dakika yıkanmalıdır. Sıcak su kullanılmamalıdır. Yanık bölge ovulmamalı ve masaj yapılmamalıdır. Göz ile Temas: Göz bölgesi en az 15 dakika boyunca ılık su ile yıkanmalıdır. Ağız Yolu ile Temas: Normal koşullarda yutma olası değildir. Sindirim sistemi İle Temas: %75 ‘den daha yüksek konsantrasyonlarda sürekli inhalasyon bulantı, baş dönmesi, solunum güçlüğü ve konvülziyon neden olabilir. Yangın ile mücadele: Karbondioksit, kuru kimyevi maddeler veya buharlaşan sıvı, yangın söndürücüler kullanılmalıdır. Yangına maruz kalan tüpler, yangın esnasında ve sonrasında emniyetli bir mesafeden su ile soğutulmalıdır. Yangın durumunda sıcaklık artışı ile birlikte basıncın artması tüpün şiddetle yırtılmasına neden olabilir.. Gaz sıkışmasını önlemek amacı ile tüpün ventil kısmına su tutulmamalıdır. Kişisel koruyucu ekipman kullanımı: Solunum Sisteminin Korunması: Havadaki konsantrasyonu, maruz kalma sınırlarından fazla ise tüplü solunum cihazlarıkullanılmalıdır.  EN 137 standardına uygun olmalıdır .Ellerin Korunması:  EN 511 standardına ugun kriyojenik sıvılara dayanıklı eldiven kullanılmalıdır. Herhangi bir kriyojenik sıvı dökülmesi veya sıçraması olduğunda , kolayca elden çıkarılması için eldivenler gevşek olmalı ve eldivenle dahi olsa soğuk teçhizatın yalnızca kısa bir süre için tutulabileceği unutulmamalıdır. Gözlerin Korunması: Direkt maruz kalma riski olan personel, çalışırken yüz siperliği veya göz maskesi ile korunmalıdır. EN 166 standartlarına uygun  koruyucu gözlük kullanılmalıdır.\nCildin Korunması: TS EN ISO 13688 standarına uygun iş elbiseleri giyilmelidir.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Hidrojen peroksit            ( oksijenli su ) kullanımına bağlı maruziyet', 'H271-Yangına veya patlamaya yol açabilir; güçlü oksitleyici.                    H302-Yutulması halinde zararlıdır.                                     H314- Ciddi cilt yanıklarına ve göz hasarına yol açar.                                                H318-Ciddi göz hasarına yol açar.                                  H335 - Solunum yolu tahrişine yol açabilir.', '1- Hidrojen peroksit kullanan ve alanda bulunan tüm çalışanlar.', '1- Kimyasal Maddelerle çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 6, 6, 3, 108, 'C', 'İlk yardım önlemeleri: Solunum: Kişiyi temiz havaya çıkartın ve rahat nefes almasını sağlayın. Kendinizi iyi hissetmezseniz, zehir merkezini veya doktoru/hekimi arayın.\nCilt İle Temas:  Cildi bol su ile yıkayın. Kirlenmiş giysilerinizi çıkarın. Ciltte tahriş söz konusu ise tıbbi yardım/müdahale alın. Kirlenmiş tüm giysilerinizi hemen kaldırın/çıkarın. Ciltte tahriş veya kaşıntı söz konusu ise: Tıbbi yardım/müdahale alın. Derhal bir doktor çağırın.\nGöz İle Temas:  Su ile birkaç dakika dikkatlice durulayın. Kontakt lens, varsa ve çıkarması kolaysa, çıkarın. Sürekli çalkalayın. Derhal bir doktor çağırın.\nYutma:  Ağızı çalkalayın. Kendinizi iyi hissetmezseniz, zehir merkezini veya doktoru/hekimi arayın. Kusmaya zorlamayın. Derhal bir doktor çağırın.  Yangınla mücadele: Yangın söndürücü maddeler şunlardır: Su spreyi. Kuru toz. Köpük. Karbondioksit. kuru kimyasal toz, alkole dayanıklı köpük, karbondioksit. Yangını güçlendirebilir; oksitleyici. Yüksek sıcaklıklarda tehlikeli gazlar açığa çıkarabilir.                                                                                                                             Kişisel koruyucu ekipman kullanımı: Ellerin koruması:Koruyucu eldivenler. EN 374 . Gözlerin koruması: Koruyucu gözlükler. Emniyet gözlükleri. EN 166. Aşırı toz olabilecek yerlerde koruyucu gözlük giyin. Deri ve vücudun korunması: Uygun koruyucu kıyafet kullanın. Toz üretimi durumunda: toz geçirmez kıyafet. \nSolunum yollarının koruması: Yetersiz havalandırma veya toz solunma riski olduğu EN 14387 standardına uygun filtre kullanılmalıdır. ( B Tipi ).', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Medikal karbondioksit (CO2) kullanımına bağlı maruziyet', 'H280- Basınçlı gaz içerir; ısıtıldığında patlayabilir', '1- Medikal karbondioksit kullanan, alanda bulunan, depolayan ve taşıyan  tüm çalışanlar, hasta ve hasta yakınları', '1- Kimyasal Maddelerle ve basınçlı kaplarla çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 2, 15, 90, 'C', 'İlk Yardım Önlemleri: Solunması: Yüksek konsantrasyonlar boğulmaya neden olabilir. Bulgular; hareket ve bilinç kaybını içerebilir. Kazazede boğulduğunun farkında olmayabilir. Çalışanın riskini en aza indirerek kazazedeye kendi üzerinde taşınabilen bir solunum cihazı takarak derhal temiz bir sahaya götürülmelidir. Eğer solunum zayıflığı varsa veya durmuşsa, derhal suni teneffüs uygulanmalıdır. Deri ile Temas: Buharlaşan sıvının deriye teması soğuk yanığı veya dokunun donmasına sebep olabilir. Etkilenen bölgeler ılık su ile en az 15 dakika yıkanmalıdır. Sıcak su kullanılmamalıdır. Yanık bölge ovulmamalı ve masaj yapılmamalıdır. Göz ile Temas: Göz ile temasında, göz kapakları mümkün olduğunca açılarak sıvı haldeki ürünün buharlaşması hızlandırılmalıdır. Göz bölgesi en az 15 dakika boyunca ılık su ile yıkanmalıdır. Eğer lens takıyorsanız çıkardıktan sonra bol su ile yıkamaya devam edin. Ağız Yolu ile Temas: Normal koşullarda yutma olası değildir. Sindirim sistemi İle Temas: Olası bir maruziyet yolu olarak kabul edilmez. Akut: Solunum yavaşlaması veya durması. Buharlaşan gaz deri ile temas nedeniyle soğuk yanması neden olabilir. Yangınla mücadele: Karbondioksit yanıcı değildir. Tutuşan malzemeye uygun söndürme aracı kullanılır. Yangın durumunda sıcaklık artışı ile birlikte basıncın artması tüpün şiddetle yırtılmasına neden olabilir. Yangına maruz kalan tüpler, yangın esnasında ve sonrasında emniyetli bir mesafeden su ile soğutulmalıdır. Gaz sıkışmasını önlemek amacı ile tüpün ventil kısmına su tutulmamalıdır. Aksi takdirde gaz toplanabilir ve patlamaya yol açabilir. Kişisel koruyucu ekipman kullanımı : Karbondioksit zehirli değildir, fakat yüksek konsantrasyonda boğucu gaz olarak davranır. İstenilerek solunulmamalıdır. Havadaki Oksijen seviyesinin % 19,5 altına düşmesi engelleyecek şekilde havalandırma yapılmalıdır. Solunum Sisteminin Korunması:  EN 137 standartlı solunum cihazları kullanılmalıdır Ellerin Korunması: EN 388 standartlarında sağlam iş eldiveni kullanılmalıdır Gözlerin Korunması: EN 166 standartlarına uygun yan siperli koruyucu gözlük kullanılmalıdır. Cildin Korunması: Uygun iş elbiseleri ve çelik burunlu ayakkabı giyilmelidir.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Medikal azot ( N2 ) kullanımına bağlı maruziyet', 'H280-  Basınçlı gaz içerir; ısıtıldığında patlayabilir.', '1- Medikal azot kullanan, alanda bulunan, depolayan ve taşıyan  tüm çalışanlar, hasta ve hasta yakınları', '1- Kimyasal Maddelerle ve basınçlı kaplarla çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 2, 15, 90, 'C', 'İlk Yardım Önlemlerinin: Teneffüs Edilmesi: Yüksek konsantrasyonlar boğulmaya neden olabilir. Bulgular; hareket ve bilinç kaybını içerebilir. Kazazede boğulduğunun farkında olmayabilir. Çalışanın riskini en aza indirerek kazazedeye kendi üzerinde taşınabilen bir solunum cihazı takarak derhal temiz bir sahaya götürülmelidir. Eğer solunum zayıflığı varsa veya durmuşsa, derhal suni teneffüs uygulanmalıdır.\nDeri ile Temas: Bu üründen kaynaklanan yan etkiler beklenmemektedir. Göz ile Temas: Bu üründen kaynaklanan yan etkiler beklenmemektedir. Ağız Yolu ile Temas: Normal koşullarda yutma olası değildir. Sindirim sistemi İle Temas: Olası bir maruziyet yolu olarak kabul edilmez. Yangın ile mücadele: Azot yanıcı değildir. Tutuşan malzemeye uygun söndürme aracı kullanılır. Gaz fazdaki azot yüksek basınca dayanıklı çelik tüpler içinde sıkıştırılmış olarak muhafaza edilir. Yangın durumunda sıcaklık artışı ile birlikte basıncın artması tüpün şiddetle yırtılmasına neden olabilir. Yangına maruz kalan tüpler, yangın esnasında ve sonrasında emniyetli bir mesafeden su ile soğutulmalıdır. Gaz sıkışmasını önlemek amacı ile tüpün ventil kısmına su tutulmamalıdır. Kişisel koruyucu ekipman kullanımı: Havadaki Oksijen seviyesinin % 19,5 altına düşmesi engelleyecek şekilde havalandırma yapılmalıdır. Azot zehirli değildir, fakat yüksek konsantrasyonda basit bir boğucu gaz olarak davranır. İstenilerek solunulmamalıdır.Kaçaklar düzenli olarak kontrol edilmelidir.\nSolunum Sisteminin Korunması: Havadaki konsantrasyonu, solunum için gerekli oksijen konsantrasyonundan fazla ise tüplü solunum cihazları kullanılmalıdır.  EN 137 standardına uygun olmalıdır.\nEllerin Korunması: EN 388 standartlarında sağlam iş eldiveni kullanılmalıdır\nGözlerin Korunması: EN 166 standartlarına uygun yan siperli koruyucu gözlük kullanılmalıdır.\nCildin Korunması: Uygun iş elbiseleri giyilmelidir.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Etilen oksit kullanımına bağlı maruziyetler', 'H220 – Aşırı alevlenir gaz\nH350 – Kansere yol açabilir.\nH340 – Genetik hasara yol açabilir\nH331 – Solunması halinde toksiktir\nH319 – Ciddi göz tahrişine yol açar\nH335 – Solunum yolu tahrişine yol açar\nH315 – Cilt tahrişine yol açar\nH280 – Basınçlı gaz içerir; ısıtıldığında patlayabilir', '1- Etilen oksit kullanan, alanda bulunan, taşıyan ve depolayan tüm çalışanlar, hasta ve hasta yakınları.', '1- Kimyasal Maddelerle ve basınçlı kaplarla çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 2, 15, 90, 'C', 'İlk Yardım Önlemleri:  Teneffüs Edilmesi: Bilinci yerinde olan kazazedeye yardım edilerek gazla kirlenmemiş bir alana götürülmeli, uzanmaları sağlanmalı, sıcak tutulmalı ve bilinci yerinde olan kazazedeye yeterli miktarda ılık su verilerek midelerindeki etilen oksit yıkanmalıdır. Deri ile Temas: Buharlaşan sıvının deriye teması soğuk yanığı veya dokunun donmasına sebep olabilir. Etkilenen bölgeler ılık su ile en az 15 dakika yıkanmalıdır. Sıcak su kullanılmamalıdır. Yanık bölge ovulmamalı ve masaj yapılmamalıdır. Göz ile Temas: Gaz ile temas eden kişiler kontakt lens kullanmamalıdır. Göz ile temasında, göz kapakları mümkün olduğunca açılarak sıvı haldeki ürünün buharlaşması hızlandırılmalıdır. Göz bölgesi en az 15 dakika boyunca ılık su ile yıkanmalıdır.Ağız Yolu ile Temas: Normal koşullarda yutma olası değildir. Sindirim sistemi İle Temas: Kuru boğaz ağrısı, burun mukoza membranlarında tahriş, merkezi sinir sistemi depresyonu, mide bulantısı, kusma, başağrısı, baş dönmesi, bilinç bozukluğu, cilt şişmesi, kızarık deri, ciltte su toplama (kabarcıklar). Su ile temas ettikten sonra: kostik yanıklar / cilt aşınması. Yüksek konsantarasyona maruz kalındığında: kalp atışlarında düzensizlik, solunum güçlükleri.  Yangın İle Mücadele:  Yangın Söndürücüler,Karbon dioksit, kuru kimyasal (BC tozu), su, alkole dayanıklı köpük bilinen uygun yangın söndürme yöntemleridir. Valf çıkışında tutuşma var ise ve henüz tutuşma tüpe ulaşmamış ise solunumu cihazı ve yangına dayanıklı koruyucu elbise donanımlı eğitimli personel tarafından valf kapatılarak alevin tüpe geri dönüşü engellenebilir. Etilen oksit sızıntısı en az 100 hacim su / 1 hacim etilen oksit oranında su ile seyreltilerek parlama ihtimali ortadan kaldırılabilir. Kişisel Koruyucu Ekipman Kullanımı:  Solunum Sisteminin Korunması: A düzeyinde tam yüz maskeli solunum koruma cihazı veya bağımsız solunum cihazı acil durumda kullanılmak üzere hazır olmalıdır. Ellerin Korunması: Etilen oksit plastiklerin çoğunu yumuşatır ve lastik-esaslı malzemelerin yüzeyinde kabarıklar oluşturur. Etilen oksite dayanıklı, bütil kauçuktan imal edilmiş iş eldivenleri kullanılmalıdır. Gözlerin Korunması: EN 166 standartlarına uygun yan siperli koruyucu gözlük kullanılmalıdır. Cildin Korunması: Etilen oksite dayanıklı iş elbiseleri ve çelik burunlu ayakkabı giyilmelidir.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Solunum Fonksiyon Test Cihazı Düfüzyon Gazına bağlı maruziyet  ( SFT )', 'H280 – Basınçlı gaz içerir; ısıtıldığında patlayabilir.', '1- Solunum Fonksiyon Test Cihazı  ( SFT ) kullanan, alanda bulunan  çalışanlar, hasata ve hasta yakınları', '1- Kimyasal Maddelerle ve basınçlı kaplarla çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 2, 15, 90, 'C', 'İLK YARDIM ÖNLEMLERİ: Teneffüs Edilmesi: Çalışanın riskini en aza indirerek kazazedeye kendi üzerinde taşınabilen bir solunum cihazı takarak derhal temiz bir sahaya götürülmelidir. Eğer solunum zayıflığı varsa veya durmuşsa, derhal suni teneffüs\nuygulanmalıdır. Deri ile Temas: Bu üründen kaynaklanan yan etkiler beklenmemektedir.\nGöz ile Temas: Bu üründen kaynaklanan yan etkiler beklenmemektedir.\nAğız Yolu ile Temas: Normal koşullarda yutma olası değildir. Ürün oda sıcaklığında gaz halinde bulunur. Sindirim sistemi İle Temas: Olası bir maruziyet yolu olarak kabul edilmez.   Yangınla mücadele: Karışım yanıcı değildir. Tutuşan malzemeye uygun söndürme aracı kullanılır. Gaz fazdaki karışım yüksek basınca dayanıklı çelik tüpler içinde sıkıştırılmış olarak muhafaza edilir. Yangın durumunda sıcaklık artışı ile birlikte basıncın artması tüpün şiddetle yırtılmasına neden olabilir. Yangına maruz kalan tüpler, yangın esnasında ve sonrasında emniyetli bir mesafeden su ile soğutulmalıdır. Gaz sıkışmasını önlemek amacı ile tüpün ventil kısmına su tutulmamalıdır.                 Kişisel Koruyucu Ekipman Kullanımı: Havadaki Oksijen seviyesinin % 19,5 altına düşmesi engelleyecek şekilde havalandırma yapılmalıdır. Solunum Sisteminin Korunması: Havadaki konsantrasyonu, solunum için gerekli oksijen konsantrasyonundan fazla ise tüplü solunum cihazları kullanılmalıdır. Ellerin Korunması : EN 388 standartlarında sağlam iş eldiveni kullanılmalıdır Gözlerin Korunması : EN 166 standartlarına uygun yan siperli koruyucu gözlük kullanılmalıdır. Cildin Korunması : Uygun iş elbiseleri ve çelik burunlu ayakkabı giyilmelidir.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Ksilen kullanımına bağlı maruziyetler', 'H226 - Alevlenir sıvı ve buhar.\nH312+H332 - Ciltle temas ettiğinde veya solunduğunda zararlıdır.\nH315 - Cilt tahrişine yol açar.', '1- Patoloji laboratuvarında çalışan ve alanda bulunan tüm  çalışanlar', '1- Kimyasal Maddelerle çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 2, 15, 90, 'C', 'İlk yardım önlemleri:  Gözlerle Temas: Lens takılı ise çıkarın. Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkayın. Problemin devam etmesi halinde bir doktora danışın. Ciltle Temas: Kirlenmiş giysileri çıkarın. Hemen bol su ile yıkayınız. Solunum: Kişiyi açık havaya çıkarınız. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım / öneri alınız. Yutma: Tıbbi tavsiye / yardım alın. Sadece doktor tavsiyesi üzerine kusturmaya çalışınız. Bir doktor tarafından izin verilmedikçe, bilinçsiz bir kişiye asla ağızdan bir şey vermeyin.                                                                                                             Yangınla mücadele:  Yangın söndürücü maddeler şunlardır: karbondioksit, köpük, kimyasal toz. Yanmamış ürün kaçakları ve dökülmeleri halinde, alevlenir buharları dağıtmak vekaçakları durdurmaya çalışan kişileri korumak için su spreyi kullanılabilir.                                                                                                                                                           Kişisel koruyucu ekipman kullanımı:  Elleri Koruma: kategori III iş eldivenleri ile koruyun (ref. EN 374 standardı). Cildi Koruma: Kategori II profesyonel kullanım amaçlı uzun kollu tulumlar ve güvenlik ayakkabıları giyiniz (ref. EN ISO 20344 standardı). Gözleri Koruma: Hava geçirmez koruyucu gözlük takılması tavsiye edilir (ref. EN 166 standardı). Solunumu Koruma: Yetersiz havalandırma veya toz solunma riski olduğu hallerde uygun parçacık filtreli solunum cihazı (tip P2) kullanın.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Medikal sıvı azot( N2 ) kullanımına bağlı maruziyet', 'H281 - Soğutulmuş gaz içerir; soğuktan yanma veya yaralanmalara yol açabilir.', '1- Medikal sıvı azot kullanan, alanda bulunan, depolayan ve taşıyan  tüm  çalışanlar, hasta ve hasta yakınları', '1- Kimyasal Maddelerle ve basınçlı kaplarla çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 2, 15, 90, 'C', 'İlk Yardım Önlemlerinin: Teneffüs Edilmesi: Çalışanın riskini en aza indirerek kazazede derhal temiz bir sahaya götürülmelidir. Kazazede sıcak ve rahat tutulmalıdır. Daha sonraki tedavi semptomatik ve destek tedavi olmalıdır. Deri ile Temas: Deri yolu ile temas veya soğuk yanığı durumunda; sıvı bulaşmış elbise çıkarılmalı ve etkilenen bölgeler ılık su ile en az 15 dakika yıkanmalıdır. Sıcak su kullanılmamalıdır. Yanık bölge ovulmamalı ve masaj yapılmamalıdır. Göz ile Temas: Göz bölgesi en az 15 dakika boyunca ılık su ile yıkanmalıdır. Ağız Yolu ile Temas: Normal koşullarda yutma olası değildir. Sindirim sistemi İle Temas: Solunum yavaşlaması veya durması. Sıvının deriye teması soğuk yanığı veya donmaya sebep olabilir. Yangınla Mücadele: Azot yanıcı değildir. Tutuşan malzemeye uygun söndürme aracı kullanılır. Sıvı azot düşük basınçta ( 15 Bar ) özel stok tanklarında muhafaza edilir. Yangın durumunda sıcaklık artışı ile birlikte basıncın artması stok tankının patlamasına neden olabilir. Stok tankında gaz kaçağı olan bölgelere gaz sıkışmasını önlemek amacı ile su tutulmamalıdır.  Kişisel koruyucu ekipman kullanımı : Solunum Sisteminin Korunması:  Havadaki konsantrasyonu, solunum için gerekli oksijen konsantrasyonundan fazla ise tüplü solunum cihazları kullanılmalıdır. EN 137 standardına uygun olmalıdır. Ellerin Korunması:  EN 511(3, 4, 1) - EN 388,- EN 420 standardı kriyojenik sıvılara dayanıklı eldiven kullanılmalıdır. Herhangi bir kriyojenik sıvı dökülmesi veya sıçraması olduğunda , kolayca elden çıkarılması için eldivenler gevşek olmalı ve eldivenle dahi olsa soğuk teçhizatın yalnızca kısa bir süre için tutulabileceği unutulmamalıdır. Gözlerin Korunması: EN 166 standardına uygun kriyojenik sıvılar ile çalışırken gözler, yüz siperliği veya göz maskesi ile korunmalıdır. Cildin Korunması: Kriyojenik sıvı sıçramalarından zarar görmemek için; cepsiz ve çıkıntısız tulum önlük veya benzer tip elbiseler giyilmeli, pantolonların paçaları botun veya ayakkabının dışına sarkıtılmalıdır. Islak elbiseler ile çalışılmamalıdır.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Etil alkol kullanımına bağlı maruziyet', 'H225 -  Kolay alevlenir sıvı ve buhar.\nH319 - Ciddi göz tahrişine yol açar.', '1- Etil alkol kullanan ve alanda bulunan tüm personeller', '1- Kimyasal Maddelerle çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 2, 15, 90, 'C', 'İlk yardım önlemleri:  Gözlerle Temas: Lens takılı ise çıkarın. Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkayın. Problemin devam etmesi halinde bir doktora danışın. Ciltle Temas: Kirlenmiş giysileri çıkarın. Hemen bol su ile yıkayınız. Tahriş devam ediyorsa, bir doktora danışınız. Kirlenmiş giysilerinizi tekrar kullanmadan önce yıkayın. Solunum: Kişiyi açık havaya çıkarınız. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım / öneri alınız. Yutma: Tıbbi tavsiye / yardım alın. Sadece doktor tavsiyesi üzerine kusturmaya çalışınız. Bir doktor tarafından izin verilmedikçe, bilinçsiz bir kişiye asla ağızdan bir şey vermeyin.                                                                                                             Yangınla mücadele: Yangın söndürücü maddeler şunlardır: karbondioksit, köpük, kimyasal toz. Yanmamış ürün kaçakları ve dökülmeleri halinde, alevlenir buharları dağıtmak vekaçakları durdurmaya çalışan kişileri korumak için su spreyi kullanılabilir.                                                                                                     Kişisel koruyucu ekipman kullanımı: Elleri Koruma: kategori III iş eldivenleri ile koruyun (ref. EN 374 standardı). Cildi Koruma: Kategori III profesyonel kullanım amaçlı uzun kollu tulumlar ve güvenlik ayakkabıları giyiniz (ref. EN ISO 20344 standardı). Gözleri Koruma: Hava geçirmez koruyucu gözlük takılması tavsiye edilir (ref. EN 166 standardı). Solunumu Koruma: kullanım limiti üretici tarafından belirlenecek olan AX tip filtreli bir maskenin takılması tavsiye edilir (ref. EN 14387 standardı). Farklı gaz veya buharların ve/veya partiküllü gaz veya buharların (aerosol, duman, sis, vb.) bulunması halinde kombine tip filtreler öngörmek gerekir.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Asetik asit kullanımına bağlı maruziyet', 'H226 - Alevlenir sıvı ve buhar.\nH314 - Ciddi cilt yanıklarına ve göz hasarına yol açar.', '1- Asetik asit kullanan ve alanda bulunan tüm  çalışanlar', '1- Kimyasal Maddelerle çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 2, 15, 90, 'C', 'İlk yardım önlemleri:  Solunum: Hastayı sakin bir yerde yatırın ve hipotermiye karşı koruyunuz. Solunum güçlüğü durumunda hastaya oksijen veriniz.  Bir doktor tarafından hızlıca tedavi olunuz. Deri İle Temas:  Kendinizi koruyarak, kirlenen giysileri çıkarınız. Cildin etkilenen bölgelerini akan suyun altında 10 dakika yıkayınız. Acilen doktor çağırınız. Göz İle Temas:  Etkilenen gözü, çevresini ve göz kapaklarını akan suyun altında 10 dakika yıkayın, hasar görmeyen gözü koruyunuz. Daha sonra, bir göz doktoruna mümkün olan en hızlı ulaşımı sağlayınız. Yutma: %10’dan büyük konsantrasyonlarda asit yutulduysa; Hastanın bilinci yerinde ise bol miktarda içecek (su) veriniz. Hastayı sakin bir yerde yatırın ve hipotermiye karşı koruyunuz. Hastayı kusturmayınız. Acil doktor çağırınız. Yangın ile mücadele: Yangın Söndürücüler: Su (sprey - sıçrama değil), kuru kimyasal toz, alkole dayanıklı köpük, karbon dioksit (CO2).Ürün yanıcıdır. Yanma sonucu; karbon oksitler açığa çıkar.                                                                                     Kişisel koruyucu ekipman kullanımı:  Göz/Yüz Korunması: NIOSH (US) veya EN 166(AB) standardına uygun kimyasal koruyucu gözlük kullanınız. Elleri Koruma: kategori III iş eldivenleri ile koruyun (TS EN 374 standardı). Cildi Koruma: Kategori III profesyonel kullanım amaçlı uzun kollu tulumlar ve güvenlik ayakkabıları. Solunumun korunması: (AB) tam yüz maskesi ya da yedek kullanım için mühendislik kontrollerine uygun ABEK (EN 14387) tipi solunum kartuşu kullanılabilir.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Sıvı vazelin kullanımına bağlı maruziyet', 'H304 - Solunum yoluna nüfuzu ve yutulması halinde öldürücüdür', '1- Sıvı vazelin kullanan ve alanda bulunan tüm  çalışanlar', '1- Kimyasal Maddelerle çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 3, 7, 63, 'D', 'İlk yardım önlemleri:   Solunum: Kişiyi açık havaya çıkarınız. Solunum zorluğu çekilmesi halinde, derhal tıbb iyardım alınız. Cilt Teması: Cildin duyarlı ve hassas bölgelerine (gözler, ağız, kulaklar, burun iç kısımlarında) kullanmaktan kaçınınız. Tahriş oluşursa doktora başvurunuz. Göz Teması: Maruz kalan gözü, göz kapakları açık olacak şekilde en az 15 dakika süreyle bol su ile yıkayın. Varsa ve kolayca çıkabiliyorsa kontak lensleri çıkarın ve yıkamayı sürdürün. Doktora başvurunuz. Yangın ile mücadele: Yangın Söndürücüler:  Kuru kimyasal toz, köpük, karbon dioksit (CO2).  Yangını sıçratıp yayabileceğinden söndürmek için basınçlı su kullanmayın. Zehirli dumanlar açığa çıkabilir.  Kişisel koruyucu ekipman kullanımı: Elleri Koruma: kategori III iş eldivenleri ile koruyun (ref. EN 374 standardı). Cildi Koruma: Kategori II profesyonel kullanım amaçlı uzun kollu tulumlar ve güvenlik ayakkabıları giyiniz . Gözleri Koruma: Hava geçirmez koruyucu gözlük takılması tavsiye edilir (ref. EN 166 standardı). Solunumu Koruma: Yetersiz havalandırma veya toz solunma riski olduğu hallerde uygun parçacık filtreli solunum cihazı (tip P2) kullanın. kendi kendine yeterli açık devreli basınçlı hava solunum cihazı (ref. EN 137 standardı) veya dış hava alımlı solunum cihazı (ref. EN 138 standardı) kullanın. sınıfı (1, 2 veya 3) kullanım limiti konsantrasyonuna göre seçilecek olan A tip filtreli bir maskenin takılması tavsiye edilir. (ref. EN 14387)', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Tıbbi alet ve endoskop dezenfeksiyonu için Ortofitalaldehit (OPA) kullanımına bağlı maruziyetler', 'H301 -Yutulması halinde toksiktir.                                       H314 -Ciddi cilt yanıklarına ve göz hasarına yol açar.\nH317 -Alerjik cilt reaksiyonlarına yol açar. H335 - Solunum yolu tahrişine yol açabilir.', '1-Ortofitalaldehit kullanan ve alanda bulunan tüm  çalışanlar.', '1- Kimyasal Maddelerle çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 6, 3, 3, 54, 'D', 'İlk yardım önlemeleri: Solunum : Kişiyi temiz havaya çıkartın ve rahat nefes almasını sağlayın. Cilt ile Temas: Bol su ile yıkayınız. Göz ile Temas : Bol su ile yıkanmalıdır. Yutma: Kendinizi iyi hissetemzseniz, zehir merkezini ve ya doktorunuzu arayınız.                                                                                        Yangınla mücadele: Yangın söndürücü maddeler şunlardır: Su, karbondoksit, köpük, kuru kimyevi toz. Yangın halinde zehirli dumanlar açığa çıkabilir.   Kişisel koruyucu ekipman kullanımı:  Elleri Koruma: kategori III iş eldivenleri ile koruyun (ref. EN 374 standardı). Cildi Koruma: koruyucu kıyafetler giyilmelidir. Gözleri Koruma: Hava geçirmez koruyucu gözlük takılması tavsiye edilir (ref. EN 166 standardı). Solunumu Koruma: Yetersiz havalandırma veya toz solunma riski olduğu hallerde uygun parçacık filtreli solunum cihazı (tip P2) kullanın. kendi kendine yeterli açık devreli basınçlı hava solunum cihazı (ref. EN 137 standardı) veya dış hava alımlı solunum cihazı (ref. EN 138 standardı) kullanın.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Alkol Bazlı Antiseptik         ( Etanol-izopropanol ) kullanımına bağlı maruziyet', 'H225-  Kolay alevlenir sıvı ve buhar.                                                  H319-  Ciddi göz tahrişine yol açar.', '1- Alkol bazlı antiseptik kullanan ve alanda bulunan tüm  çalışanlar', '1- Kimyasal Maddelerle çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 2, 7, 42, 'D', 'İlk Yardım Önlemleri: Genel Uyarılar: Kullanıcı kendini koruyucu tedbirler alarak ürünü kullanmalıdır. Acil bir durum, şüpheye kapılmanız veya semptomların devam etmesi halinde daima bir doktora başvurun. Solunum: Maruz kaldığı yerden kişiyi uzaklaştırın ve temiz hava aldırın. Rahatsızlık halinde doktora başvurunuz. Cilt ile Temas: Önlem gerektirmez. Göz ile Temas: Gözle temasından kaçınınız. Gözle temas durumunda hemen bol su ile yıkayınız. Gerektiği durumda, kontak lensleri çıkarın. Etiketi ile birlikte hemen doktora başvurunuz. Yutma: Yutulması halinde kişi kusturmayınız, etiketi ile birlikte hemen doktora başvurunuz.                                                                              Yangınla mücadele: Yangın söndürücü maddeler şunlardır; Su, karbondoksit, köpük, toz. Yanan materyalin üzerine tazyikli su yada su jeti uygulanmamalıdır. Yangın çoğunlukla kara, kalın bir duman oluşmasına neden olur. Ayrışım ürünlerine maruz kalınması sağlık açısından tehlikeli olabilir. Dumanı solumayın. Kişisel koruyucu ekipman kullanımı: Kişisel koruyucu donanımı (KKD) önerilen ulusal standartlara uymalıdır. Sıçrama için gözlük, laboratuvar önlüğü, solunum cihazı kullanın. Göz/yüz koruma: EN 166 standartlı tam korumalı gözlük kullanınız. Göz ile her türlü temasından kaçınınız. Kullanılan alanlarda göz banyosu olmalıdır. Cildin ve vücudun korunması : Uygulanmamaktadır. Ellerin korunması: Uygulanmamaktadır. Solunum sisteminin korunması: Normal koşullar içinde uygulanmamaktadır.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Klorheksidin Glukonat /Propan-2-ol içerikli Antiseptik Sıvı Sabun kullanımına bağlı maruziyetler', 'H226- Alevlenir sıvı ve buhar.                     H318 Ciddi göz hasarına yol açar.\nH400- Sucul ortamda çok toksiktir.\nH411- Sucul ortamda uzun süre kalıcı, toksik etki.', '1- Klorheksidin Glukonat /Propan-2-ol içerikli Antiseptik Sıvı Sabun kullanan ve alanda bulunan tüm  çalışanlar', '1- Kimyasal Maddelerle çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 2, 7, 42, 'D', 'İlk yardım önlemleri:   Gözlerle Temas: Lens takılı ise çıkarın. Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkayın. Problemin devam etmesi halinde bir doktora danışın.\nCiltle Temas: Kirlenmiş giysileri çıkarın. Hemen bol su ile yıkayınız. Tahriş devam ediyorsa, bir doktora danışınız. Kirlenmiş giysilerinizi tekrar kullanmadan önce yıkayın. Solunum: Kişiyi açık havaya çıkarınız. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım / öneri alınız. Yutma: Tıbbi tavsiye / yardım alın. Sadece doktor tavsiyesi üzerine kusturmaya çalışınız. Bir doktor tarafından izin verilmedikçe, bilinçsiz bir kişiye asla ağızdan bir şey vermeyin.                              Yangınla mücadele: Yangın söndürücü maddeler şunlardır: karbondioksit, köpük, kimyasal toz.  Yanma sonucu zehirli gazlar açığa çıkabilir. Yüksek güçlü su püskürtme jeti kullanmayınız. Kişisel koruyucu ekipman kullanımı: Elleri Koruma: kategori III iş eldivenleri ile koruyun (ref. EN ISO  374 standardı). Cildi Koruma: koruyucu kıyafetler giyilmelidir. Gözleri Koruma: Hava geçirmez koruyucu gözlük takılması tavsiye edilir (ref. EN 166 standardı). Solunumu Koruma: Yetersiz havalandırma veya toz solunma riski olduğu hallerde uygun parçacık filtreli solunum cihazı EN 140 ( tam üz maskesi), EN 136 ( yarım yüz maskesi )  standartlı cihaz  kullanın.', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Polivinilprolidin iyot      ( cilt antiseptiği ) kullanımına bağlı maruziyet', 'H315 – Cilt tahrişine yol açar\nH318 –  Ciddi göz hasarına yol açar H412 –  Sucul ortamda uzun süre kalıcı, zararlı etki', 'Polivinilprolidin iyot içerikli cilt antiseptiği kullanan tüm  çalışanlar', '1- Kimyasal Maddelerle çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 3, 3, 27, 'D', 'İlk yardım önlemleri:  Gözlerle Temas: Lens takılı ise çıkarın. Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkayın. Problemin devam etmesi halinde bir doktora danışın. Ciltle Temas: Kirlenmiş giysileri çıkarın. Hemen bol su ile yıkayınız. Tahriş devam ediyorsa, bir doktora danışınız. Kirlenmiş giysilerinizi tekrar kullanmadan önce yıkayın. Solunum: Kişiyi açık havaya çıkarınız. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım / öneri alınız. Yutma: Tıbbi tavsiye / yardım alın. Sadece doktor tavsiyesi üzerine kusturmaya çalışınız. Bir doktor tarafından izin verilmedikçe, bilinçsiz bir kişiye asla ağızdan bir şey vermeyin. Yangınla mücadele: Yangın söndürücü maddeler şunlardır: su spreyi, karbondioksit, köpük, kimyasal toz.  Yanma sonucu zehirli gazlar açığa çıkabilir. Yüksek güçlü su püskürtme jeti kullanmayınız .  Kişisel Koruyucu Ekipman Kullanımı:   Elleri Koruma: kategori III iş eldivenleri ile koruyun (ref. EN 374 standardı). Cildi Koruma: koruyucu kıyafetler giyilmelidir(EN ISO13688). Gözleri Koruma: Hava geçirmez koruyucu gözlük takılması tavsiye edilir (ref. EN 166 standardı). Solunumu Koruma: Yetersiz havalandırma veya toz solunma riski olduğu hallerde uygun parçacık filtreli solunum cihazı masakesi kullanın( EN 14387).', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Tıbbı aletler ve endoskoplar için Enzimatik temizleyici kullanımına bağlı maruziyet', 'H318 –  Ciddi göz hasarına yol açar.', '1- Enzimatik temizleyici kullanan tüm  çalışanlar', '1- Kimyasal Maddelerle çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 3, 3, 27, 'D', 'İlk yardım önlemleri:   Gözlerle Temas: Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkayın.  Problemin devam etmesi halinde bir doktora danışın. Ciltle Temas: Kirlenmiş giysileri çıkarın. Hemen bol su ile yıkayınız. Tahriş devam ediyorsa, bir doktora danışınız. Solunum: Kişiyi açık havaya çıkarınız. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım / öneri alınız. Yutma: Tıbbi tavsiye / yardım alın. Sadece doktor tavsiyesi üzerine kusturmaya çalışınız. Bir doktor tarafından izin verilmedikçe, bilinçsiz bir kişiye asla ağızdan bir şey vermeyin.                                    Yangınla mücadele:  Yangın söndürücü maddeler şunlardır: su spreyi, karbondioksit, köpük, kimyasal toz. Yüksek güçlü su püskürtme jeti kullanmayınız. Yanma sırasında zehirli gazlar açığa çıkabilir. Kişisel Koruyucu Ekipman Kullanımı:   Elleri Koruma: Uygun iş eldivenleri ile koruyun (ref. EN 374 standardı). Cildi Koruma: koruyucu kıyafetler giyilmelidir(EN ISO13688). Gözleri Koruma: Hava geçirmez koruyucu gözlük takılması tavsiye edilir (ref. EN 166 standardı). Solunumu Koruma: Yetersiz havalandırma veya toz solunma riski olduğu hallerde uygun  filtreli solunum cihazı masakesi kullanın ( EN 14387).', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: KİMYASAL MADDELER', '1- Bütan, Propan, İzobütan, D-pentanol içerikli cilt temizleyici kullanımına bağlı maruziyet.', 'H223- Alevlenir aerosol.                              H280- Basınçlı gaz içerir; ısıtıldığında patlayabilir.                                              H412-Sucul ortamda uzun süre kalıcı, zararlı etki.', '1- Bütan, Propan, İzobütan, D-pentanol, Klorheksidin diglukonat içerikli cilt temizleyici kullanan tüm  çalışanlar', '1- Kimyasal Maddelerle çalışmalarda sağlık ve güvanlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 3, 3, 27, 'D', 'İlk yardım önlemleri:   Solunum: Kişiyi açık havaya çıkarınız. Solunum zorluğu çekilmesi halinde, derhal tıbbi yardım ve öneri alınız. Ciltle Temas: Cildi  hemen bol su ile yıkayınız. Tahriş devam ediyorsa, bir doktora danışınız.  Gözlerle Temas: Göz kapaklarını iyice açarak, derhal ve bol su ile en az 15 dakika yıkayın.  Problemin devam etmesi halinde bir doktora danışın. Yutma: Tıbbi tavsiye / yardım alın. Sadece doktor tavsiyesi üzerine kusturmaya çalışınız. Bir doktor tarafından izin verilmedikçe, bilinçsiz bir kişiye asla ağızdan bir şey vermeyin.                                                                                          Yangınla mücadele:  Yangın söndürücü maddeler şunlardır; su spreyi, karbondioksit, köpük, kimyasal toz. Yüksek güçlü su püskürtme jeti kullanmayınız. Yanma sırasında zehirli gazlar açığa çıkabilir. Kişisel Koruyucu Ekipman Kullanımı:   Elleri Koruma: Uygun iş eldivenleri ile koruyun (ref. EN 374 standardı). Cildi Koruma: koruyucu kıyafetler giyilmelidir(EN ISO13688). Gözleri Koruma: Hava geçirmez koruyucu gözlük takılması tavsiye edilir (ref. EN 166 standardı). Solunumu Koruma: Yetersiz havalandırma veya toz solunma riski olduğu hallerde uygun  filtreli solunum cihazı masakesi kullanın ( EN 14387).', 'ÇALIŞANLAR', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: POLİKLİNİKLER', '1-Göğüs Hast. Polikliniğinde SFT 3 odasında difüzyon test tüpünün cihaza sabitlenmemiş olması', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1-Poliklinik çalışanları      \n2-Hasta ve hasta yakınları', NULL, 1, 0, 3, 6, 15, 270, 'B', '1- Difüzyon testi için kullanılan basınçlı tüp, zemine sabitlenmeden bırakılmamalıdır.\n2- Tüp boyutu cihazda ki sabitleme aparatına uyacak boyutta olmalı ya da mevcut tüp boyutuna uygun sabitleme aparatları takılmalıdır.\n3- Cihaz üzerinde bulunan sabitleme alanına en az 2 noktadan sabitlenmeldir.', 'FİRMA', '3  AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: POLİKLİNİKLER', '1-Kadın Doğum Pol. Müdahale odasında Cryo Gaz Tüpü (basınçlı kap, saf CO2 )  tüpün kabin dışında kullanılması.', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1-Poliklinik çalışanları      \n2-Hasta ve hasta yakınları', NULL, 1, 0, 3, 6, 15, 270, 'B', '1-Cryo tüpü kabin içinde bulundurlmalıdır.                                                                                                                                                                   2- Kabin içerisinde hortumların sıkışması önlenmelidir.\n3- Kabin tekerlek frenleri sağlam olmalı, kabin devrilmeyecek şekilde konumlandırılmalıdır.\n4- Kabin üzerine uyarı işaretleri yerleştirilmelidir.\n3- TS EN 511 standardına uygun eldiven kullanılmalıdır.', 'FİRMA\nPOLİKLİNİK ÇALIŞANLARI', '3  AY\n\nHER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: POLİKLİNİKLER', '1-Beraberinde Oksijen tüpü bulunması gereken hasta nakli esnasında oksijen tüplerinin tehlike içerecek şekilde  taşınması.', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1-Poliklinik çalışanları      \n2-Hasta ve hasta yakınları', '1-Hasta nakilleri için hastanede tüp taşıma aparatları bulunmaktadır.', 1, 0, 3, 6, 15, 270, 'B', '1- Hasta yatakları, taşıma araçları vb. basınçlı tüp taşınan ekipmanlarda tüpleri sabitlemek için aparatlar bulunmalı, tüpler en az iki noktadan sabitlenerek taşınmalıdır.                                                                                                \n2- Tüplerin taşınması esnasında vanaları kapalı olmalı, dik taşınmalı, kapağı kapalı olmalıdır.                                                                               \n3- Taşıma esnasında tüplerin başka cisimlere çarpması engellenmelidir.', 'POLİKLİNİK ÇALIŞANLARI    TAŞIMA ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: POLİKLİNİKLER', '1-Polikliniklerde hasta yoğunluğu sebebi ile havalandırma sisteminin yetersiz olması', '1. Ortam kaynaklı bulaş enfeksiyon', '1-Poliklinik çalışanları', '1-Havalandırma sistemi mevcuttur.                  2. Periyodik kontrolleri mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Poliklinik hasta bekleme alanları ve koridorlarda , hasta yoğunluğunun fazla olduğu yerlerde taze hava çevirim sayısı arttırılmalıdır.  \n2- Havalandırma sistemi çevrim sayısı saatte 16-20 arasında olmalıdır.\n3- Havalandırma sisteminin periyodik kontrolü en geç yılda bir kez tekrarlanmalıdır.', 'FİRMA', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: POLİKLİNİKLER', '1-Buat bulunan zemin üzerinde buatlarının kapaklarının açık olması,  kapaklarının olmaması', '1- Elektrik çapması             \n2- Yangın ve duman zehirlenmesi', '1-Poliklinik çalışanları', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Buat kapakları kapalı tutulmalıdır.                                                                         \n2-Kırık buat kapakları değiştirilmeli, vidalar ile tutturulmamalıdır.                                                                                                  3- Buatlara L tipi fişler kullanılmalı,  buatların açık kalması önlenmelidir.                                                                                                                             4- Buatların üzerinde ki masalarda bir şey yenilip içilmemelidir.', 'FİRMA  \nPOLİKLİNİK ÇALIŞANLARI', '3 AY \n                          HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: POLİKLİNİKLER', '1-Alçı odasında bulunan tozun solunması', '1-Tozun solunması sonucu meslek hastalıkları meydana gelmesi', '1-Alçı yapan çalışanlar', '1-Redüksiyon dışındaki alçılamalar için sentetik alçı kullanılmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1-Toz alçı işlemlerinde oluşan tozun çalışma ortamına yayılmasını önlemek için toz emici kullanılmalıdır.                                                                                                                                                          2-Alçı kesme işleminden sonra oluşan toz hemen temizlenmeli, ortamda birikmesi önlenmelidir.                                                                                                                                                                                                                                                                                                                                                         4-Çalışanlar tozdan korunmak için FFP2-FFP3 tipi maske kullanılmalıdır. Yüz koruyucu siperlik,  eldive  kullanılmalıdır.', 'ORTOPEDİ POLİKLİNİK ÇALIŞANLARI', 'ALÇILAMA İŞLERİNDE SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: POLİKLİNİKLER', '1-Formaldehit kullanımı  maruziyeti (Kadın Doğum Pol., Jinekolojik Onkoloji,Genel Cerrahi pansuman ve müdahale odası, KBB müdahale odası, Üroloji müdahale odası)', '1-Alerji reaksiyonlar \n2-Cilt ve göz tahrişi     \n3-Solunum yolu tahrişi', '1-Poliklinik çalışanları', '1. Kimyasal Maddelerle çalışmalarda sağlık ve güvenlik önlemeleri hakkında eğitim verilmiştir.', 1, 0, 3, 3, 15, 135, 'C', '1- Formaldehit büyük kaplardan, küçük kaplara aktarılırken taşma kapları kullanılmalı, zemine dökülmesi önlenmelidir.\n2- Formaldehit dökülmesine karşı döküntü kitleri temin edilmelidir.\n3- Çalışanlar formaldehit ile çalışma esnasında EN 149 standardında ffp3 maske, eldiven ve koruyucu gözlük kullanmalıdır.', 'İŞVEREN V.\nPOLİKLİNİK ÇALIŞANLARI', '3 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: POLİKLİNİKLER', '1- Kesici delici aletlerin emniyetsiz kullanılması', '1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma', '1-Poliklinik çalışanları', '1-Kesici delici atık kutuları bulunmaktadır.', 1, 0, 6, 3, 7, 126, 'C', '1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                                 3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                                                                                                5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.', 'POLİKLİNİK ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: POLİKLİNİKLER', '1-Kan alma koltuklarının hasarlı veya kırık olması,', '1.Kesici delici alet yaralanması                2.Enfekte hastadan bulaş', '1-Poliklinik çalışanları', '1-Tamir talebi oluşturulduğunda, koltuk tamir bakımı yapılmaktadır.', 1, 0, 6, 3, 7, 126, 'C', '1- Hasarlı ya da kırık kan alma kotukları değiştirilmeli ya da onarılmalıdır.\n2-  Özellikle koltuk kolları sağlam olmalı, kan alma işlemi sırasında sabit olması sağlanmalıdır.\n3-  Koltuk yüksekliği çalışanı rahatsız edici göz ve baş hareketleri ihtiyacını en aza indirecek şekilde olmalıdır.                    \n3- Sandalyeler ergonomik tasarıma sahip olmalı, gerekli hallerde ayak desteği kullanılmalıdır.', 'TEKNİK HİZMETLER MÜDÜRLÜĞÜ', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: POLİKLİNİKLER', '1-Enfeksiyon Polikliniğinde bulunan  kan alma ünitesinin alanının dar olması', '1. Hasta kaynaklı bulaş                                                        2. Kesici delici alet yaralanması', '1-Poliklinik çalışanları', '1-Havalandırma sistemi mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Kan alma odalarına hastalar tek tek alınmalı, kan alma işlemi tamamlanmadan yeni hasta odaya alınmamalıdır.                                                                                                                                                    2- Kan alma odasında, çalışanın kan alırken rahat hareket edebileceği alan sağlanmalıdır.                                                                                                                                                                                          3-Kişi başına düşen hava miktarı 10 metreküpten az olmamalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: POLİKLİNİKLER', '1-Elektrikli mutfak aletleri (çay, kahve, microdalga fırın, airfryer vb.) kullanılması', '1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm', '1-Poliklinik Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Hastane de mutfak olarak belirlenmiş alanlar dışında hiçbir yerde elektrikli mutfak aletleri kullanılmamalıdır.                                          \n2- Mutfak olarak tanımlanmış alanlarda sadece çay ve kahve makinesi kullanılmalı, bunların dışındaki aletlerin kullanımı yasaklanmalıdır.         \n3- Sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.    \n4- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.\n5- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.', 'İŞVEREN V.   KLİNİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: POLİKLİNİKLER', '1- Kimyasal madde deposunda göz duşu ve döküntü kiti bulunmaması                                               2- Çalışanların kimyasallar hakkında bilgi sahibi olmaması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1-Klinik Çalışanları', '1- Kimyasallar depo alanında depolanmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.                                              3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               4-Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.                              5- Çalışanlara MSDS ve kimyasalların güvenli kullanımı konusunda eğitimler verilmelidir.', 'İŞVEREN V.                                       İŞ GÜVENLİĞİ UZMANI', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: POLİKLİNİKLER', '1-Tehlikeli kimyasalların yanlış depolanması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması                                 2- Yangın meydana gelmesi', '1-Klinik Çalışanları', '1- Kimyasallar depo alanında depolanmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Kimyasal maddeler depolama matirsine göre depolanmalıdır.                                                        2- Yanıcı kimyasallar elektrik kaynaklarından uzak depolanmalıdır.                                                                               3- Kimyasal maddelerin ağzı açık olmamalı, dik olarak istiflenmelidir.                                              4- Ağzı açılmış kimyasal madde kaplarının altına taşma kapları konulmalıdır.', 'KLİNİK ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: POLİKLİNİKLER', '1-Alanda kullanılan elektrikli cihazların kablo, priz veya fişlerinin hasarlı olması', '1-Elektrik çapması\n2-Yangın, duman zehirlenmesi', '1-Poliklinik çalışanları', '1- Kaçak akım röleleri mevcuttur.                                                                                        2- Yangın söndürme sistemleri mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1- 3 lü uzatma kablolarına, 3 lü uzatma kablosu kullanarak kullanılmamalıdır.                                                                                                     2- Yüsek akım çeken cihazlar (kettle çay makinesi vb.) beslemesi ayrı fişlerden yapılmalı, uzatma kabloları kullanılmamalıdır.                                                                                                             3- Çalışanların dışarıdan uzatma kablosu getirmesi yasaklanmalıdır.                                                                                                                                                                       4-Islak elle cihazlara dokunulmamalıdır.', 'POLİKLİNİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: POLİKLİNİKLER', '1- Monitörlerin, bilgisayarların, yazıcıların ve ofis mobilyalarının acil çıkış yollarını ve kapılarını kapatması', '1-Acil durumlarda hızlı tahliyenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması', '1-Poliklinik çalışanları  \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Yangın yönlendirme levhaları mevcutur.                                              2- Tahliye planı mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1-Acil çıkış kapıları ve acil çıkış yolları açıkça görülebilir olmalı ve acil çıkış kapılarnın ve yollarının önüne ve üzerine malzeme vb. konulmamalıdır.                                                                                                                                                                        2- Acil çıkış yönlendirmelerinin önleri kapatılmamalı, kaçış yolu üzerinde bütün erişim noktalarından görülebilir olmalı, yönlendirmeler 200-240 cm yüksekliğe asılı olmalıdır.                                                                                                                                                                 3- Acil çıkış yollarında en az 150 cm genişliğinde mesafe olması sağlanmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: POLİKLİNİKLER', '1- Kan ve vücut sıvılarının göz ve cilde temas etmesi', '1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma', '1-Poliklinik çalışanları', '1-KKD\'ler mevcttur..', 1, 0, 3, 3, 7, 63, 'D', '1-Çalışanlar TS EN 455  standardında eldiven, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında maske vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.', 'POLİKLİNİK ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: POLİKLİNİKLER', '1-Ortopedi Polikliniği Alçı odasında alçı kesme motoru kullanımı', '1-Kesici alet yaralanmaları.                2-Aşırı ısınmadan dolayı yanık', '1-Poliklinik çalışanları', '1. Alçı kesme motoru dönme hareketi ile değil titreşim hareketi ile kesme yapmaktadır.', 1, 0, 3, 3, 3, 27, 'D', '1. Alçı kesim motoru çalışırken operasyon bölgesine el ve kollar yaklaştırılmamalıdır. \n2- Alçı kesim motoru çalışırken elektrik kabloları operasyon bölgesinden uzakta tutulmalıdır.    \n3- Alçı kesim moturu kullanırken bol eldiven kullanılmamalıdır.\n4- Tam kapalı iş gözlüğü, maske mutlaka kullanılmalıdır.', 'ORTOPEDİ POLİKLİNİK ÇALIŞANLARI', 'ALÇI KESİM MOTORU KULLANIMI SIRASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: POLİKLİNİKLER', '1-Çalışma alanında yiyecek-içecek tüketilmesi', '1-Enfeksiyon, bulaş', '1-Poliklinik çalışanları', '1. Alanda dinlenme ve yiyecek içecek alanları bulunmaktadır.', 1, 0, 3, 3, 3, 27, 'D', '1-Çalışanlar polikliniklerde hastaların youğun olduğu enfeksiyon kaynağı bulundurulabilecek alanlarda yiyecek-içecek tüketmemelidir.                                               \n2-Yemek ve çay saatlerinden önce el, yüz ve vücut temizliği sağlanmalıdır.                                                                                                                                                                                                                                                                                                                                                                                                      3-Çalışanlara, yiyecek–içecek tüketiminin hastane enfeksiyonlarına, kimyasal/biyolojik madde bulaşına ve çalışan sağlığına yönelik risklerine karşı eğitim verilmelidir.', 'İŞ GÜVENLİĞİ UZMANI     POLİKLİNİK ÇALIŞANLARI', '3 AY \n\n                              HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: MORG', '1-Morga fazla sayıda cenzaze yakını girmesi', '1- Ex yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma', '1- Morg çalışanları', '1- Morgda görevli bir güvenlik görevlisi  bulunmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1- Morga tüm girişlerde sadece yetkili çalışanların girebildiği kartlı giriş sistemi bulunmalı, yetkisiz kişilerin morga girmesi önlenmelidir.\n2- Morga mümkün olan en az sayıda cenaze yakını alınmalıdır.\n3- Cenaze yakınları morg bölümüne sıra ile güvenlik personeli eşliğinde alınmalıdır.', 'FİRMA\n\nGÜVENLİK PERSONELİ', '2 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: MORG', '1-Cenaze yakınları tarafından sözel/fiziksel şiddete maruz kalınması', '1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma', '1- Morg çalışanları', '1- Güvenlik personeli mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Hasta ve hasta yakınları tarafından çalışanların şiddete uğrayabileceği morg bölümüne sabit panik butonlarının yanında yaka butonları temin edilmelidir.                                                                                                                                                                                                      2- Morg bölümünde biri alanda biri cenaze teslim sırasında oda da bulunmak üzere en az 2 adet güvenlik personeli bulundurulmalıdır.                                                                 \n3- Çalışanlara iletişim, stres yönetimi ve öfke kontrolü ile mesleki bilgi ve becerilerini arttırıcı eğitimler verilmelidir.', 'İŞVEREN V.  \n                                       İŞ GÜVENLİĞİ UZMANI', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: MORG', '1- Sürekli  cenazelerle temas halinde çalışma ve travmatik olaylara maruz kalınması', '1-Sinirlilik, stres, depresyon, tükenmişlik sendromu, iş kazalarında artış', '1- Morg çalışanları', '1-Çalışan hakları birimi mevcuttur.                                         2-Çalışan memnuniyet anketleri yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1- Çalışanlara gereğinde psikolojik destek ve danışmanlık sağlanmalıdır.                                                                                                                                                                                                                                                              2- Tükenmişlik yaşayan çalışanlar düşük yoğunluklu birimlere kaydırılmalıdır.                                                                                                                                3- Çalışanlara iletişim, stres yönetimi ve öfke kontrolü ile  mesleki bilgi ve becerilerini arttırıcı eğitim yapılmalıdır.', 'İŞVEREN V.  \n          \n İŞ GÜVENLİĞİ UZMANI', 'HERGÜN\n\n2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: MORG', '1-Ceset torbalarının yırtık, hasarlı olması', '1-Cenazelerin vücut sıvılarının akması, bulaşı sonucu iş kazaları                                                 2- meslek hastalıkları', '1- Morg çalışanları', '1- Cenazeler ceset torbası içerisinde gelmektedir.', 1, 0, 3, 3, 15, 135, 'C', '1- Temin edilen ceset torbaları sıvı geçirmez özellikte olmalı,  kanla bulaşan patojenlerin tam olarak tutulmasını sağlamalı, kan ve sıvı geçirmeyen maddeden yapılmış olmalıdır.  \n2- Cenazelerin taşınması sırasında torbaların yırtılmaması için özen gösterilmelidir.                                                                                                \n3- Ceset torbasından sıvı sızmasına ihtimalin morg personeli TSE EN 374 standardına uygun çizme, EN 14605 standardında koruyucu önlük, temin edilmeli ve kullanılmalıdır.', 'TAŞIMA ÇALIŞANLARI        MORG ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: MORG', '1-Cenaze teslimi esnasında kan ve vücut sıvılarının bulaşması', '1-Kan ile bulaşabilen hastalıklar                                         2- iş kazaları                                                3- meslek hastalıklarI', '1- Morg çalışanları', '1- Cenazeler ceset torbası içerisinde gelmektedir.', 1, 0, 3, 3, 15, 135, 'C', '1-Cenazeler açık yaraları tamamen kapatılarak, sıvı geçirmez ceset torbaları ile morga getirilmelidir.                                                                                                         \n2-Cenazenin morga getirilmesi, teslim alınan ve teslim edilen esnada ceset torbası açılırken, cenazeye temas edileceği zaman KKD\'ler kullanılmalıdır.                                                                                                                                                            3- Exlerin teslim, transfer esnasında bulaş kaynağına uygun olarak EN 149 standardında FFP2 filtreli maske, EN 13795 Standardında Cerrahi önlük, En 455 Standardında Cerrahi çift eldiven kullanılmalıdır.\n4-KKD\'ler çalışanlara zimmetlenmeli, çalışanlar tarafından eksiksiz kullanılmalıdır.', 'CENAZENİN GELDİĞİ \nBİRİM SORUMLULARI\nMORG ÇALIŞANLARI', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: MORG', '1- Temizlik arabalarının akülerinin morg alanında şarj edilmesi', '1-Patlama, yangın,                           2-Elektrik çarpması', '1- Morg çalışanları', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Morg içerisindeki temizlik odalarında akü şarj işlemi yapılmamalıdır.                                                                                                                                                                2- Aküler şarj için belirlenmiş alanlarda şarj edilmelidir.                                                              3-Akü şarj alanları iyi havalandırılmış olmalı, devrilmeyecek şekilde konumlandırmalıdır.  \n4-Aküler şarj edildikten sonra fişte takılı bırakılmamalıdır.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  5-Şarj noktasında CO₂ veya kuru kimyevi tozlu söndürücü bulundurulmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: MORG', '1- Cenaze teslim alanının dezenfekte edilmemesi', '1-Virüs, bakteri ve mikrop yayılması sonucu meslek hastalıkları', '1- Morg çalışanları', '1- Her gün dezenfeksiyon yapılmaktadır.', 1, 0, 6, 3, 7, 126, 'C', '1-Her cenaze tesliminden sonra alan yıkanmalı ve dezenfekte edilmelidir.\n2- Günlük temizliğe ilave olarak yerler, duvarlar, kapılar haftada bir kez dezenfektanlar ile temizlenmelidir.', 'TEMİZLİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: MORG', '1-Cenazeler morga teslim edilirken bulaşıcı hastalığı vb. konusunda hakkında bilgi verilmemesi', '1-Cenazelerden bulaş   \n2-iş kazaları                                               3-meslek hastalıkları olması', '1- Morg çalışanları', '1- Cenazenin bulaş bilgisi kimlik kartları üzerinde bulunmaktadır.', 1, 0, 6, 3, 7, 126, 'C', '1-Bulaşıcı hastalığı olan cenazelerin kimlik kartları ve taşındığı sedyelerin üzeri tanımlayıcı figürler ile belirtilmelidir.                                                                                                                                                                              2-Sarı yaprak (solunum izolasyonu) , Mavi çiçek (Damlacık izolasyonu) , Kırmızı yıldız (temas izolasyonu) şeklindedir.          \n3-Figürlerin bulunduğu cenazeler ile temas edileceği zaman KKD\'ler eksiksiz kullanılmalı, koruyucu önlemler alınmadan temas edilmemelidir. \n4- Her teslim sonrası uygun kimyasallar kullanılarak alan dezenfeksiyonu yapılmalıdır.                                                                                                                                     5- Bulaşıcı hastalıklar konusunda enfeksiyon kontrol komitesi tarafından çalışanların eğitimi yılda en az bir kez tekrarlanmalıdır.', 'ENFEKSİYON KONTROL KOMİTESİ\nTAŞIMA ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: MORG', '1-Cenazelerin morgda bekleme sürelerini aşması', '1-Virüs, bakteri ve mikropların üremesi sonucu meslek hastalıkları', '1- Morg çalışanları', '1- Cenazeler uygun sürelerde teslim edilmektedir.', 1, 0, 6, 2, 7, 84, 'C', '1- Kimliği olan ve yakınları bulunan cenazeler 24–72 saat içinde teslim edilmelidir. \n2- Kimsesiz ve kimliksiz cenazeler en geç iki hafta içerisinde ilgili kurumlara teslim edilmelidir.', 'MORG SORUMLULARI      MORG ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: MORG', '1-Aydınlatma yetersizliği', '1-Görüş azalması sonucu iş kazaları sebebiyeti', '1- Morg çalışanları', '1- Alanda yeterli sayıda aydınlatma armatürü bulunmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1-Özellikle gece çalışmalarında olmak üzere, suni ışık ihtiyacında çalışma alanı ve diğer eklentiler, yollar en az 300 lüks şiddetinde aydınlatılmalıdır.                                                                                                                      2-Aydınlatma sistemleri sağlam yapıda olmalı, bozulan, yanmayan titreyen aydınlatmalar değiştirilmelidir.\n3-Periyodik göz muayeneleri yılda bir kez yapılmalıdır.', 'İŞVEREN V.                                  İŞYERİ HEKİMİ', '3 AY                              YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: MORG', '1-Sivri, delici, kesici, paslı dolap masa ve ekipmanlar', '1-Yaralanma sonucu tetanos hastalığına yakalanma', '1- Morg çalışanları', '1- Çok fazla paslı yüzey bulunmamaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1-Paslı alet ve ekipmanlar yenileriyle değiştirilmeli, paslanmaz malzemeler kullanılmalıdır.\n2-Sivri, delici, kesici, paslı ekipmanlara eldivensiz temas edilmemelidir.\n3-Yeni başlayan ya da aşısı eksik olan çalışanlara tetanos aşısı yapılmalı, 5 yılda bir ya da yaralanma durumunda tekrar aşı yapılmalıdır.', 'İŞVEREN V.  \n          \nMORG ÇALIŞANLARI', '3 AY \n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: MORG', '1-Hasta yıkama odaları ve abdesthane içerisinde ıslak zemin oluşması', '1-Kayma, Düşme sonucu yaralanma                           2- iş kazası', '1- Morg çalışanları', '1- Hastane morgu içerisinde cenaza yıkama işi yapılmamaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.                                                                                                     \n2- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\n3- Zeminde bulunan giderler açık olmalıdır.\n4-  Çalışanlar kaymaz tabanlı ayakkabı giymelidir.', 'TEMİZLİK ÇALIŞANLARI MORG ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: MORG', '1-İklimlendirme sisteminin bozulması sonucu ortam ısısının yükselmesi', '1-Virüs, bakteri ve mikrop yayılması sonucu meslek hastalıkları', '1- Morg çalışanları', '1- Havalandırma sisteminin periyodik kontrolü mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1-Morg bölümünde odalar içerisinde ısı ölçer bulundurulmalıdır.\n2- Havalandırmalar sürekli aktif olmalıdır.    \n3- Ortam ve oda sıcaklığı 16-20 °C olmalıdır.                                                                                       \n4-Havalandırma sisteminin periyodik kontrolleri ve  filtrelerin değişimi en geç yılda bir tekrarlanmalıdır.', 'FİRMA', 'ISI ÖLÇER\n(3 AY)\nPERİYODİK KONTROL \nYILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: MORG', '1-Cenazelerin taşınması', '1-Kas-İskelet sistemi rahatsızlıkları', '1- Morg çalışanları', '1- Cenazeler, cenaze taşıma sedyesi ile gelmektedir.', 1, 0, 3, 6, 3, 54, 'D', '1-Cenaze taşıma işlemi sırasında exi sedyeye alma işlemi en az 2 çalışan ile veya kaldırma araçları ile gerçekleştirilmelidir.                                                                    \n 2- Sedyelerin kilit mekanizmaları bulunmalı, kilit mekanizmaları sağlam ve çalışır olmalıdır.', 'TAŞIMA ÇALIŞANLARI        MORG ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: MORG', '1-Cenazelerin saklandığı dolapların soğutma sisteminin bozulması', '1-Virüs, bakteri ve mikropların üremesi sonucu meslek hastalıkları', '1- Morg çalışanları', '1- Cenaze soğuk hava dolabı aktif olarak çalışmaktadır.', 1, 0, 3, 1, 7, 21, 'D', '1- Dolap sıcaklıkları 2-6 °C  olmalıdır.                                                                               \n2- Soğutma sistemleri için aylık bakım, yılda bir periyodik bakımı yapılmalıdır.                                                                                                                           3- Dolapların ısı göstergeleri sağlam ve çalışır durumda olmalıdır.                                                                                                            4- Her dolap için dijital datalogger ve merkezi alarm sisemi bulundurulmalıdır. \n5- Morgun günlük olarak ısı izlem çizelgesi tutulmalıdır. 6 °C  üzerine çıkması durumunda sesli ikaz sistemi bulunmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: PARK BAHÇE', '1-Otomatik sulama sistemi çalışırken çim aydınlatma armatürlerine su temas etmesi', '1-Eletkriğin su ile teması sonucu çarpılma', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1-Çim aydınlatma armatürleri güneş enerjili lamba vb. elektrik kullanmayan sistemler ile değiştirilmelidir.\n2- Sulama başlıklarının açıları düzeltilmeli,  çim aydınlatma armatürlerine ve kablolarına su  temas etmeyecek şekilde konumlandırılmalıdır.                                                                                                                                                   3- Elektriğin su ile teması önlenmeli, elektrik kabloları çift izolasyonlu olmalıdır.\n4- Çimlerin etrafı tel çit vb. malzemeler ile çevrelenmeli, insan geçişi önlenmelidir.\n5- Elektrik ile ilgili uyarı levhaları asılmalıdır.', 'FİRMA', '2 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: PARK BAHÇE', '1-Hastane yerleşkesine giriş ve çıkışların tek yoldan sağlanması', '1- Acil durumlarda itafiye afad vb. kurumların geç ulaşması sonucu durumun şiddetinin artması', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', NULL, 1, 0, 3, 6, 15, 270, 'B', '1-Hastane yerleşkesine ulaşımda yoğunluğun azaltılması için alternatif giriş çıkış yolu oluşturulmalıdır.    \n2- Yollar üzerine araç park edilmesini önleyecek bariyerler ve uyarı levhaları konulmalıdır.\n3- Ulaşım yolları genişletilmelidir.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: PARK BAHÇE', '1-Çalışanların yaya ve yürüyüş yollarını kullanmaması\n2- Araçların hızlı kullanılması', '1- İş kazası yaşanması sonucunda yaralanma, ölüm', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1-Yaya geçitleri belirlenmiştir.                2-Geçitlerde uyarı levhaları mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1-Hastanede tüm yaya yollarına araçların yavaşlaması için hız kesici setler konulmalıdır.\n2-Yaya yollarında silinen boyalar yenilenmeli, yollar belirgin olmalıdır.\n3-Araç yollarında uyarı levhaları konulmalıdır: ″Yayalar yaya yolunu kullanmalıdır″ \n4- Araç trafiği olan alanlara bariyer konarak yayaların girişi sınırlandırılmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: PARK BAHÇE', '1-Dilatasyon boşluklarının üzerinden araç geçmesi', '1- Kapakların kırılması sonucu yaralanma', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1-Bir çok alanda set mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Dilatasyon boşluk kapaklarının üzerinden araç, ambulans vb. geçemyecek şekilde setler konulmalıdır.\n2- Dilatasyon kapaklarının üzerine saksı vb. bir şey bırakılmamalıdır.     \n3- Dilatasyon kapaklarının bağlantı yerlerinde ki kaynaklar sağlam olmalı, kırılan kaynaklar onarılmalıdır.\n4- Bel veren, eğilen, deforme olmuş kapaklar değiştirilmelidir.', 'FİRMA', '3 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: PARK BAHÇE', '1-Yangın ve su hidrantlarının önü kapatılması( araç, malzeme , çöp, peyzaj ekipmanı, peyzaj alanında kullanılan bitkiler vb.)', '1- Yangın anında hidrantlara erişimin engellenmesi, söndürme gecikmesi', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1-Alanlar düzenli aralıklarla kontrol edilmektedir.', 1, 0, 3, 3, 15, 135, 'C', '1-Yangın hidrantlarının etrafı en az 1 metre çapında boş bırakılmalıdır                                                                                                          2-Bitkisel peyzaj uygulamaları yapılırken hidrantların görüş alanı engellenmemelidir.                                                                                                                        3-Yangın ve su hidrantlarının önü uyarı levhaları ile işaretlenmelidir.\n4-Hidrant çevresi sarı-siyah çizgilerle veya boyasıyla işaretlenmelidir.\n5-Bahçe ve ototpark düzeninde hidrant önüne araç parkını önleyecek barikat veya demir dubalar yerleştirilmelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: PARK BAHÇE', '1-Hız sınırı levhalarının yetersiz olması', '1-İş kazası yaşanması sonucu yaralanma', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1- Bir çok bölgede hız sınırı levhaları mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1-Bahçe ve otopark giriş-çıkış noktalarına ve kritik kavşak noktalarına eksik olan alanlara  hız sınır tabelaları yerleştirilmelidir.                                                                                                                         2-Hastane sınırları içinde hız sınırı kapalı alanlarda 20 km/s açık alanlarda 30 km/s geçmemelidir.\n3- Araç trafiğine yönelik tabelalar (hız sınırı, yönlendirme vb.) Ortalama 2,0 – 2,5 m yüksekliğe asılmalıdır.', 'FİRMA', '3 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: PARK BAHÇE', '1-Hastane ve çevresinde yılan vb. sürüngenler çıkması', '1-Isırılma, zehirlenme,alerji', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', NULL, 1, 0, 3, 2, 15, 90, 'C', '1-Hastane çevresinde dış alanda yabancı otlar temizlenmelidir.                                                                                2-Bina çevresinde bina boyunca devam eden boşluk kısımlarda sürüngen için bakanlıktan izinli yapışkan plaka kullanılmalıdır.                                                                                     3-Kapı altlarında yalıtım ve kapı altı fırçası takılması ve sinekliksiz pencerelere sineklik takılmalıdır.                                                                                                                                                                                                                4- Bahçe içerisinde ölü bölge yaratan bitkiler budanmalı ya da ortadan kaldırılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: PARK BAHÇE', '1- Kuru otların bulunduğu alanlarda sigara içilmesi, cam vb. çöplerin atılması', '1-Yangın çıkması', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1-Çöp ve kuru otların temizliği düzenli aralıklarla yapılmaktadır', 1, 0, 3, 2, 15, 90, 'C', '1-Kuru otlar düzenli aralıklar ile temizlenmelidir.\n2- Cam şişe, izmarit ve yanıcı atıklar  düzenli aralıklarla temizlenmelidir.\n3-Kuru ot bulunan alanlarda  ″Sigara içilmez- Yangın riski″ uyarı tabelalarının görünür noktalara konulmalıdır.                                               \n3- Sigara sadece izin verilen alanlarda içilmelidir.  \n4-Yangına dayanıklı ve kapaklı çöp kutuları sağlanmalıdır.', 'FİRMA', 'PERİYODİK OLARAK SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: PARK BAHÇE', '1-Klima santrali alanda elektrik kablolarının suyla temas etmesi', '1-Elektrik çarpması sonucu yaralanma', '1-Çalışanlar                                                                                2- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 2, 7, 84, 'C', '1-Elektrik kabloları çift izolasyonlu (IP67/IP68 standartlarına uygun) olmalıdır.\n2-Elektriğin suyla teması önlenmelidir.\n3-Elektrik kablolarında izole bant ile bantlanmış ekler olmamalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: PARK BAHÇE', '1-Döner kavşakta bulunan  bitkilerin sürücü görüşünü engellemesi', '1-Bitki boylarının büyümesi  araçların görüşünü engellemesi sonucu iş kazaları yaşanması', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1-Bitkiler düzenli aralıklarla budanmaktadır', 1, 0, 3, 3, 7, 63, 'D', '1-Döner kavşakta bulunan bitkiler araçların görüşünü kapatmayacak şekilde budanmalı, boyları en fazla 60 cm olmalıdır.\n2- Görüş açısını kapatan bitkiler daha düşük boylu türlerle değiştirilmelidir\n3- Düzenli saha gözetimlerinde bitki boyları kontrol edilmeli ve uygunsuzluklar raporlanmalıdır.', 'FİRMA\n\nİŞ GÜVENLİĞİ UZMANI', '3 AY\n\nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: PARK BAHÇE', '1- Helipot sahasına yetkisiz kişilerin erişmesi', '1- İş kazalarının yaşanması, vücut bölümlerinin yaralanması', '1- Heliport sahasında çalışanlar\n2- Diğer ilgili kişiler', '1-Saha girişinde bariyer bulunmaktadır.', 1, 0, 3, 1, 15, 45, 'D', '1-Heliport sahasına yetkisiz kişilerin girişini önleycek şekilde bariyer sistemi genişletilmeli, açıklıklar kapatılmalıdır.\n2- Gece çalışmalarında aydınlatma sistemi her zaman çalışır durumda olmalıdır.\n3- Çalışanlar, helikopter yanaşırken an az 50 metre mesafede bulunmalıdır. \n4- Sadece özel eğitim almış çalışanlar heliport sahasında bulunmalı ve kişisel koruyucu ekipmanları reflektörlü olmalıdır.', 'FİRMA\nHELİPORT SAHASINDA ÇALIŞANLAR', '3 AY\nÇALIŞMA ESNASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: PARK BAHÇE', '1- Heliport alanında bulunan rüzgar tulumun yıpranmış olması', '1- İş kazalarının yaşanması, vücut bölümlerinin yaralanması', '1- Heliport sahasında çalışanlar', NULL, 1, 0, 3, 1, 15, 45, 'D', '1- Her uçuş öncesi güvenlik veya teknik personel tarafından rüzgar tulumunun durumu kontrol edilmelidir. \n2- Rüzgar tulumu yıprandığı zaman değiştirilmelidir. Rüzgâr yüküne ve yağmura dayanıklı, reflektif kumaşlardan yapılmış ICAO onaylı rüzgar tulumu kullanılmalıdır. \n3- Hava koşullarına bağlı olarak en geç yılda bir kez yenilenmesi planlanmalıdır.', 'FİRMA\nHELİPORT SAHASINDA ÇALIŞANLAR', '3 AY\nÇALIŞMA ESNASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: PARK BAHÇE', '1-Heliport alanında bulunan elektrik regülatörü ve köpük cihazlarının periyodik kontrollerinin, bakımlarının yapılmaması', '1- İş kazalarının yaşanması, vücut bölümlerinin yaralanması', '1- Heliport sahasında çalışanlar', NULL, 1, 0, 3, 1, 15, 45, 'D', '1-Regülatör ve köpük cihazlarının TS, ISO, SHT ( Sivil Havacılık Talimatları) ve ilgili yönetmelik doğrultusunda periyodik kontrolleri yaptırılmalıdır. Tüm bakım faaliyetleri tarih, sorumlu kişi ve tespit edilen bulgularla birlikte kayıt altına alınmalıdır.\n2- Regülatörlerin çevresi suya, yağmura ve yakıt sızıntısına karşı korunaklı olmalıdır.\n3- Yangın söndürme ekipmanları bulundurulmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: PARK BAHÇE', '1-Peyzaj alanları için kullanılan su deposunun etrafınının çevrili olmaması', '1-iş kazası,Düşme ve Yaralanma Riski        2-Ekipman Hasarı                              3-Elektriksel Tehlike', '1-Çalışanlar                                                                                2- Diğer ilgili kişiler', NULL, 1, 0, 3, 2, 7, 42, 'D', '1-Sulama deposunun çevresi en az 1,5–2 metre yüksekliğinde tel çit veya bariyerle çevrilmelidir.\n2-Bakım personeli dışında kimsenin erişemeyeceği şekilde kilitli kapı kullanılmalıdır.\n3-Yetkisiz Girmek Yasaktır” ve “Dikkat! Sulama Suyu Deposu” uyarı tabelaları yerleştirilmelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: PARK BAHÇE', '1-Bahçede ki rögarların tıkanması, kırılması yerinden çıkması', '1-Takılma, düşme, kayma, su birikintisi  sonucu yaralanma', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', NULL, 1, 0, 3, 2, 7, 42, 'D', '1- Rögar kapakları  yılda en az 2 kez kontrol edilmeli,  kırık, gevşemiş, yerinden oynamış rögar kapakları değiştirilmelidir.\n2-Yaprak, toprak, çöp gibi malzemelerle tıkanan mazgallar temizlenmeli, tıkanması önlenmeldir.', 'FİRMA', 'YILDA 2', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: PARK BAHÇE', '1-Kış aylarında hastane yollarında buzlanma olması', '1-Kayma–düşme, araç kazası, yaralanma', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1- Otopark rampalarında ısıtmalı sistem mevcuttur.', 1, 0, 3, 1, 7, 21, 'D', '1-Kış aylarında yollarda buzlanma oluşumu, kar küreme ve tuzlama çalışmaları yapılarak önlenmelidir. \n2- Buzlanma olabilecek su birikintileri önlenmelidir.\n3- Otopark rampalarında bulunan ısıtma sistemi her zaman aktif olmalı, kontrol bakımları yapılmalıdır.\n4- Ambulans ve hastane hizmet araçlarında kış lastiği bulunmalıdır.\n5- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.', 'FİRMA\n ÇALIŞANLAR', 'BUZLANMA OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 2: OTOPARKLAR', '1-Kapalı otoparklara LPG\'li araç alınması', '1- LPG sızıntısı sonucu patlama, yangın, zehirlenme meydana gelmesi', '1-Çalışanlar                                         2-Hasta ve hasta yakınları                                        3-Diğer ilgili kişiler', '1-Otopark alanında yangın söndürücüler mevcuttur.', 1, 0, 6, 6, 15, 540, 'A', '1- Kapalı otoparlara LPG\'li araç girişi yasaklanmalıdır.                                                                          2- Otopark görevlileri tarafından kapalı otoparklara girişte araçlar kontrol edilmeli, LPG\'li araçlar kapalı otoparklara alınmamalıdır.\n3- Havalandırma sisteminin sürekli aktif olarak çalışması sağlanmalıdır.                                         \n4- Tüm kapalı otoparkların girişine LPG\'li araç girişi yasaktır tabelası olmalıdır.', 'İŞVEREN V. \nFİRMA', '1 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 2: OTOPARKLAR', '1-Kapalı otopark içinde sigara içilmesi', '1-Yangın ve patlama riski', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1-Otopark alanında yangın söndürücüler mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Otoparkın giriş ve iç alanlarına görünür yerlere  “sigara içilmez” uyarı levhaları yerleştirilmelidir. \n2-Sigara içen kişilere anında müdahale edilecek şekilde görevli bulundurulmalıdır.\n3-Yangın sistemleri aktif ve çalışır durumda olmalıdır.\n4-Kuralların ihlal edilip edilmediği güvenlik kameralarıyla izlenmelidir.', 'FİRMA \nOTOPARK GÜVENLİK PERSONELİ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 2: OTOPARKLAR', '1-Otopark kapasitesinin yetersiz olması nedeniyle araçların uygun olmayan alanlara park edilmesi', '1-Araçların çalışanlara çarpması sonucu yaralanma                                 2- Acil durumlarda tahliyenin zorlaşması', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1-Güvenlik kameraları mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1- Yol kenarlarına, yaya yollarına park alanı olarak belirlenmemiş alanlara araçların park etmesini önlemek için mantar, bariyer vb. konulmalıdır.\n2- Uygunsuz park eden araçlar için tutanak tutulmalı, gerektiğinde çekici ile çekilmelidir.  \n3- Uyarı levhaları artırılmalıdır.   \n4- Araçlar acil durumlarda tahliyenin rahat sağlanması için çıkış yönünde park etmeleri sağlanmalıdır.', 'ÇALIŞANLAR\nOTOPARK GÖREVLİLERİ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 2: OTOPARKLAR', '1-Kapalı otoparkta araçlardan yağ sıvı  vb. dökülmesi', '1-Kaygan zemin oluşması sonucunda düşme, yaralanma                     2-Yangın çıkması', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', NULL, 1, 0, 3, 2, 15, 90, 'C', '1- Otopark zeminleri en geç ayda bir kez yıkanmalıdır.\n2- Büyük döküntü olması durumunda hemen temizlenmeli, sıvı ve yağların zeminde birikmesi önlenmelidir.\n3-Kaygan zemin uyarı levhaları görünür yerlere yerleştirilmelidir.\n4-Yağ emici paspas veya absorbant granül malzeme kullanılmalıdır. Zemin düzenli yıkanmalı ve yağ birikimi önlenmelidir                                                                                                          5- Yangın söndürücüler kolay erişilebilir olmalıdır', 'FİRMA\n\nTEMİZLİK ÇALIŞANLARI', 'AYDA 1\n\nDÖKÜNTÜ OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 2: OTOPARKLAR', '1-Kapalı otoparklarda  egzoz gazları oluşması', '1-Egzoz gazı sonucu solunum yolu rahatsızlığı, karbon monoksit zehirlenmesi', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1- Havalandırma sistemi mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1-Jetfanlar her gün çalıştırılmalı, egzoz gazlarının kapalı otoparklarda birikmesi önlenmelidir. \n2- Kapalı otoparklarda gaz ölçümleri yaptırılmalıdır.\n2-Havalandırma  sistemininin, jet fanların periyodik kontrolleri en geç yılda bir kez tekrarlanmalıdır.\n3- Kapalı otoparklara karbon monoksit dedektörleri her zaman çalışır durumda olmalıdır.', 'FİRMA', '3 AY\n\nPERİYODİK KONTROL YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 2: OTOPARKLAR', '1-Abdesthane zeminlerinde ıslaklık nedeniyle kaygan yüzey oluşması', '1-Zeminde oluşan ıslaklık nedeniyle düşme, yaralanma, çarpma, burkulma', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', NULL, 1, 0, 6, 2, 7, 84, 'C', '1-Abdeshane de ıslak zemin olan yüzeylere kaymaz zemin kaplamaları (kaymaz PVC, epoksi veya pütürlü yüzeyler) konulmalıdır.\n2- Zemin düzenli aralıklarla temizlenmeli ve kurulanmalıdır.\n3-“Dikkat! Kaygan zemin” uyarı levhaları görünür noktalara yerleştirilmelidir.\n4-Zeminde su birikintisi oluşumunu engelleyecek eğim ve drenaj sistemleri sağlanmalıdır.', 'FİRMA\n\nTEMİZLİK ÇALIŞANLARI', '3 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 2: OTOPARKLAR', '1-Lojistik tünelde hız sınır tabelalarının olmaması    \n2-Arabaların\nhızlı kullanılması', '1-Araçların çalışanlara çarpması sonucu kaza, yaralanma', '1-Çalışanlar                                         2-Stajerler                                         3-Diğer ilgili kişiler', '1-Lojistik tünelde tümsek aynalar mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1-Kapalı otoparkhız sınırı 20 km/s açık otopark hız sınırı 30 km/s geçmemelidir. \n2- Görünür noktalara  hız sınırı tabelaları konulmalıdır.                                                                                                                                                                                                                                 3-Çalışanlar yaya yolu olarak belirtilen yolu kullanmalı, araç yolunu kullanmamalıdır.\n4- Tümsek aynaların görüş açısı yolları gösterecek şekilde ayarlanmalıdır.', 'FİRMA', '3 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 2: OTOPARKLAR', '1-Tümsek aynların sayısının yetersiz olması, ayna görüş açılarının uygun olmaması', '1-Çalışanların, araçları fark edememesi sonucu yaralanma', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1-Bazı noktalarda tümsek aynalar mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1-Tüm kör noktalar(otopark, rampalar, dar koridorlar ve bina köşeleri ) tespit edilerek ek tümsek aynalar yerleştirilmelidir. \n2- Aynalar yaklaşan araç ve yaya trafiğini tam gösterecek şekilde 1,6–1,8 m yükseklik aralığında monte edilmelidir. \n3- Gece veya kapalı alanlarda görüşü artırmak için ayna çevresinde yeterli aydınlatma sağlanmalıdır.', 'FİRMA', '3 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM 2: OTOPARKLAR', '1-Tavandan akmalar yaşanması, tavan kapaklarının açık bırakılması', '1-Tavandaki akma sonucu su sızdırma, kayma, düşme arızalar yaşanması', '1-Çalışanlar                                         2-Stajerler                                         3-Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 7, 63, 'D', '1- Tavan akıntısına neden olan tesisat, çatı veya klima hattı arızaları onarılmalıdır.                                          \n2- Elektrik kablolarının suyla temas riskine karşı izole edilmelidir.  \n3- Tavan akması görülen bölgeler uyarı şeridi veya bariyerlerle çevrelenmelidir. \n4- Kaygan zemin uyarı levhaları kullanılmalıdır. Sızan suyun birikmesini önlemek için alan  temizlenmelidir.', 'FİRMA', '3 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM 2: OTOPARKLAR', '1-Kapalı otopark çıkışlarını yayaların kullanması', '1-Yayaların kapalı otopark çıkışlarını kullanması sonucu yaralanma', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', NULL, 1, 0, 6, 2, 3, 36, 'D', '1- Çalışanlar kapalı otopark araç çıkış yollarını kullanmamalıdır.                                                                                            2- Yayalar sadece yaya yollarını ve otoparktan çıkmak için asansörleri kullanmalıdır.                                                                                                  \n3- Otopark görevlileri tarafından saha gözetimi yapılmalı, araç çıkışını kullanan kişiler uyarılmalıdır.', 'ÇALIŞANLAR\nOTOPARK GÖREVLİLERİ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 27, 'BÖLÜM 2: OTOPARKLAR', '1-Kapalı otoparklardaki yaya yollarının yönlendirmelerinin kapıları göstermemesi, yolların belirgin olmaması', '1-Araçların çalışanlara çarpması sonucu kaza, yaralanma', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1- Yaya yolları çoğunlukla belirlenmiştir.', 1, 0, 3, 3, 3, 27, 'D', '1- Yaya yolu çizgileri ve ok yönleri kapıları gösterecek şekilde yeniden çizilmelidir. \n2- Silinen yaya yolları tekrar boyanmalı, belirgin hale getirilmelidir.       \n3- Yaya yolları genişliği en az 120 cm genişliğinde olmalıdır.\n4- Araçların yaya yollarına park etmesi önlenmeli, sürekli kontrol denetim sağlanmalıdır.', 'FİRMA\n\nOTOPARK GÖREVLİLERİ', '3 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 28, 'BÖLÜM 2: OTOPARKLAR', '1- Kapalı otopark zemininde bulunan zemin farkı-çukur olması', '1-Takılma, düşme sonucu yaralanma', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 3, 27, 'D', '1-Zemindeki çukurlar doldurulmalı,  beton/asfalt vb. malzemeler ile kullanılmalıdır.                                                                                                                              2-Otopark zemini düzenli olarak kontrol edilerek deformasyonlar erken tespit edilmelidir .', 'FİRMA', '3 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 29, 'BÖLÜM 2: OTOPARKLAR', '1-Lojistik tünelde toz oluşması', '1- Solunum yolu hastalıkları meydana gelmesi', '1-Çalışanlar                                         2-Stajerler', NULL, 1, 0, 3, 3, 3, 27, 'D', '1- Havalandırma sistemi düzenli olarak çalıştırılmaldır.\n2- Biriken tozlar düzenli aralıklar ile temizlenmelidir.\n3- Zemin belli aralıklarla ıslatılmalıdır.', 'FİRMA\nTEMİZLİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 30, 'BÖLÜM 2: OTOPARKLAR', '1-Kapalı otoparklardaki otomatik kapı bariyerlerinin açılıp kapanma esnasında yayalar tarafından kullanılması', '1-Kapının çalışanlara çarpması sonucu yaralanma', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', NULL, 1, 0, 3, 1, 7, 21, 'D', '1-Çalışanlar otomatik kapı bariyerlerinin altından geçmemelidir.\n2- “Kapı altından geçmek tehlikeli ve yasaktır” gibi uyarı levhaları kapı üzerine yerleştirilmelidir\n3- Bariyerlerdeki algılama sistemlerinin kontrol ve bakımları düzenli olarak yapılmalıdır.', 'FİRMA\n\nÇALIŞANLAR', '3 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 31, 'BÖLÜM 2: OTOPARKLAR', '1-Lojistik tünelde yangın perdesinin yırtık olması\n2- Fotosel sisteminin olmaması', '1-Yangın durumunda dumanın diğer bölümlere sızması\n2- Ezilme, sıkışma', '1-Çalışanlar                                         2-Stajerler                                         3-Hasta ve hasta yakınları\n4- Diğer ilgili kişiler', '1- Yangın perdeleri yangın algılama ihbar sistemine bağlıdır.', 1, 0, 3, 1, 7, 21, 'D', '1- Yırtık olan yangın perdesi değiştirilmeli, yangın perdesi duman sızdırmaz özellikte olmalıdır.        \n2- Yangın perdesi altından çalışan geçerken çalışmasını durduracak şekilde fotosel tertibatı yaptırılmalıdır.                                                                                                                 3-Yangın perdelerinin, basınç sensörlerinin periyodik kontrolleri en geç yılda bir kez yapılmalıdır.', 'FİRMA', '3 AY\n\nPERİYODİK KONTROL YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 32, 'BÖLÜM 3: HASTANE ARAÇLARI', '1-Şoförlerde SRC ve  psikoteknik testlerin olmaması                                  2-Sağlık ve göz muayenesi raporlarının olmaması', '1-Trafik kazası sonucunda ölüm, sakatlık, uzuv kaybı, yaralanmaların meydana gelmesi', '1-Araç şoförleri\n2-Araçta bulunan çalışanlar', '1-Şoförler uygun ehliyete sahiptir.', 1, 0, 3, 1, 40, 120, 'C', '1-Şoförler psikoteknik ve src belgelerine sahip olmalı, eksik olanlar aldırılmalıdır.                                                                  \n2-Şoförlerin periyodik sağlık ve göz muayeneleri yılda bir kez yapılmalıdır.  \n3-Hastane araçları sadece görevlendirilmiş şoförler tarafından kullanılmalıdır.', 'İŞVEREN V.', '3 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 33, 'BÖLÜM 3: HASTANE ARAÇLARI', '1-Hastane araçlarının hızlı kullanılması\n2- Trafik kurallarına uyulmaması', '1-Trafik kazası sonucunda ölüm, sakatlık, uzuv kaybı, yaralanmaların meydana gelmesi', '1-Araç şoförleri\n2-Araçta bulunan çalışanlar', NULL, 1, 0, 3, 1, 40, 120, 'C', '1- Araçlar yasal hız limitlerinden %10 daha düşük hızda kullanılmalıdır.\n2- Araçlar sağ şeritte ve yavaş kullanılmalıdır.\n3- Trafik kurallarına uyulmalı, sinyalizasyon sistemi mutlaka kullanılmalı, takip mesafesi korunmalıdır.\n4- Seyir halinde emniyet kemerleri mutlaka takılı olmalıdır.\n5- Araçalar seyir halindeyken sigara içilmemelidir.', 'ARAÇ ŞOFÖRLERİ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 34, 'BÖLÜM 3: HASTANE ARAÇLARI', '1- Eskimiş, aşınmış  lastiklerin kullanılması\n2- Mevsime uygun lastik kullanılmaması', '1-Trafik kazası sonucunda ölüm, sakatlık, uzuv kaybı, yaralanmaların meydana gelmesi', '1-Araç şoförleri\n2-Araçta bulunan çalışanlar', '1-Kış lastikleri bulunmaktadır.???', 1, 0, 3, 1, 40, 120, 'C', '1- Mevsim şartlarına uygun yazlık-kışlık lastikler kullanılmalı, karlı havalarda zincir kullanılmalıdır.\n2- Aşınan, yıpranan, ezilen, balon yapan lastikler yenileri ile değiştirilmelidir.\n3- Lastik havaları mevsim şartlarına ve üretici tavsiyelerine uygun basınçta şişirilmelidir.\n4- Kaygan yollarda, sisli havalarda araçlar çok düşük hızlarda kullanılmalıdır.', 'İŞVEREN V.\nARAÇ ŞOFÖRLERİ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 35, 'BÖLÜM 3: HASTANE ARAÇLARI', '1- Araçların günlük kontrollerinin ve periyodik yapılmaması', '1- Arızların tespit edilememesi sonucu trafik kazası, ölüm', '1-Araç şoförleri\n2-Araçta bulunan çalışanlar', NULL, 1, 0, 3, 1, 40, 120, 'C', '1-Araçlar kullanmaya başlanmadan önce günlük kontrolleri yapılmalı ve belgelendirilmelidir. \n2- Her 3 ayda veya 10.000 km’de bir yetkili bir servise periyodik bakım yaptırılmalıdır.\n3- Yılda bir kez yaptırılacak fren bakımı kayıtları olmalıdır. \n4- Araç ruhsatında süresi geçmemiş fenni muayene ve egzoz emisyon test raporları mevcut olmalıdır.\n5- Tespit edilen eksiklikler giderilmeden araçlar kullanılmamalıdır.', 'İŞVEREN V.', 'İLGİLİ PERİYOTLAR İLE \nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: ÇAMAŞIRHANE', '1- Kurutma odası borularında sıvı sızıntısından dolayı kaygan zemin oluşması', '1-Kayma, düşme sonucu yaralanma', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 15, 135, 'C', '1- Sızıntının kaynağı tespit edilip boru onarımı veya arıza parça değişimi yapılmalıdır.    \n2- Sızıntı sonucu oluşan kayma veya tehlikeli alan temizlenmeli ve kurulanmalıdır.', 'FİRMA\nÇAMAŞIRHANE ÇALIŞANLARI', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: ÇAMAŞIRHANE', '1- Kompresör odasına yetkisiz giriş yapılması\n2- Kompresörün periyodik kontrollerinin yapılmaması', '1-Patlama sonucu yangın, uzuv kaybı,  meydana gelmesi,', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 15, 135, 'C', '1- Yetkisiz kişilerin girişi engellenmeli, kartlı giriş sistemi kullanılmalıdır.\n2- Kompresörün acil durumlarda uzaktan durdurulmasını sağlamak için odanın dışına acil durdurma düğmesi takılmalıdır.                                                                                                                                                                           3-Kompresör, tank, ve emniyet valflerinin periyodik kontrolleri yapılmalıdır (TS 1203 EN 286-1, TS EN 13445-5, TS EN 764-7)', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: ÇAMAŞIRHANE', '1- Çamaşır taşıma arabalarının aşırı yüklenmesi\n2- Aynalarının kırık olması', '1-Yüklerin görüşü kapatması  sonucu çalışana çarpma, yaralanma', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-Çamaşır taşıma işlerinde sadece lojistik tünel kullanılmalıdır.                                                                       2-Çamaşır taşıma arabaları fazla yüklenmemeli, çamaşırlar sabitlenerek taşınmalıdır.                              \n3-Geri gidişlerde sesli ve ışıklı sinyaller aktif olmalıdır.                                                                  4-Lojistik tünel kullanım hızı 20 km/s geçmemelidir.                                                                     5-Hasarlı aynalar değiştirilmelidir.', 'FİRMA\n\nARAÇ OPERATÖRLERİ', '3 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: ÇAMAŞIRHANE', '1-Yıkama makinelerin boru, bağlantı yerleri vb. noktalarından su sızıntıları olması', '1-Düşme, kayma sonucu yaralanma', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', NULL, 1, 0, 6, 3, 7, 126, 'C', '1- Makinelerin boruları ve bağlantı yerleri su sızdırmayacak şekilde olmalı, hasarlı olan borular değiştirilmelidir.\n2- Zemin, suyun birikmesini engelleyecek şekilde eğimli hale getirilmeli ve uygun drenaj sistemi sağlanmalıdır.                                                                                                                                                                                                    3- Su birikintileri anında temizlenmeli ve kurulanmalıdır.\n4- Makinelerin elektrik kabloları suyla temas etmiyecek şekilde çift izolasyonlu olmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: ÇAMAŞIRHANE', '1- Çamaşır makinesinden çıkan buharın elektrik tesisatı ve aydınlatmalara teması', '1--Elektrik çarpması sonucu yaralanma', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', '1-30 mA kaçak akım rolesi mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1- Elektrik kabloları ve bağlantı yerleri izole edilmelidir.\n2- Elektrik kabloları çift izolasyonlu olmalıdır.\n3- Kullanılan elektrik sistemleri etanj özellikte olmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: ÇAMAŞIRHANE', '1-Islak ve kaygan zemin', '1-Zeminde oluşan ıslaklık nedeniyle düşme, yaralanma', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', '1-Kaygan zemin oluşması halinde temizlik yapılmaktadır.', 1, 0, 6, 3, 7, 126, 'C', '1- Kaymaya sebep olacak kimyasal maddelerinin ve suyun zeminde birikmesi önlenmeli, hemen temizlenmelidir.\n2- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.    \n3- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.', 'ÇAMAŞIRHANE ve \nTEMİZLİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: ÇAMAŞIRHANE', '1-Elektrik panolarının, pano odalarının yangın dolaplarının önlerinin kapatılmış olması', '1-Acil durumlarda hızlı müdahalenin sağlanamaması sonucu durumun şiddetinin artması', '1- Çalışanlar                                2- Hastalar ve hasta yakınları        3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1- Malzeme, çamaşır vb. pano ve  yangın dolaplarının önlerini kapatmaması sağlanmalıdır.\n2-Panolara erişim için en az 80 cm genişlikte ulaşım yolları sağlanmalıdır.\n3-Pano üzerlerine uyarı etiket ve işaretleri asılmalıdır.', 'ÇAMAŞIRHANE ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: ÇAMAŞIRHANE', '1-Kirli alan çamaşır yıkama makinası ekipmanlarından köpük çıkması', '1- Kaygan zemin sonucu düşme yaralanma', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', NULL, 1, 0, 3, 2, 15, 90, 'C', '1-Deterjan dozajlarının düzenli kontrol edilmeli ve doğru miktarda kullanımı sağlanmalıdır. \n2-Dozaj pompası, filtre, köpük sensörü ve contalar sağlam yapıda olmalı, bozulanlar değiştirilmelidir.                                                        \n3-Fazla köpüğün zemine dökülmesi önlenmeli, köpük borusu büyük kapların içine konulmalı, zemine dökülen köpük hemen temizlenmelidir.', 'FİRMA\nÇAMAŞIRHANE ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: ÇAMAŞIRHANE', '1-Elektrik prizlerinin kırık olması', '1-Elektrik çarpması sonucu yaralanma', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', '1-30 mA kaçak akım rolesi mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Çalışma alanında hasarlı elektrik prizlerinin onanarımı ve değişimi sağlanmalıdır. \n2- Kırık prizler onarılana kadar kullanım dışı bırakılmalı, elektrik akımı kesilmelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: ÇAMAŞIRHANE', '1- Çamaşırhane dikim alanında elektrik kablolarının korumasız şekilde yerde bulunması ve uygunsuz uzatma kablosu kullanılması', '1-Elektrik çarpması, yangın çıkması, takılma/düşme, iş kazası', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 7, 63, 'D', '1- Kullanılan uzatma kabloları halejen free özellikte olmalıdır.\n2- Yerden geçen uzatma kabloları takılma düşmeye sebep olmayacak şekilde düzenlenmelidir.\n3- Elektrik kablolarında yırtık, izolasyon bozlukluğu vb. olmamalı, olan kablolar kullanılmamalı değiştirilmelidir.\n4- Elektrik kabloları makine ya da ekipmanların altına konulmamalı, kabloların ezilmesi önlenmelidir.', 'FİRMA\nÇAMAŞIRHANE ÇALIŞANLARI', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: ÇAMAŞIRHANE', '1-Ütüleme ve katlama makinasin döner aksamlarının yanlarının açık olması', '1- Dönen kısımlara kaptırma sonucu yaralanma', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', '1-Ön kısımda fotosel mevcuttur', 1, 0, 3, 3, 7, 63, 'D', '1-Ütü ve katlama makinesinin yan kısımda bulunan dönen aksamları koruyucu kapak veya muhafaza ile kapatılmalıdır.                                     \n2-Makine çalıştırılmadan önce tüm koruyucuların takılı ve sağlam olduğu kontrol edilmelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: ÇAMAŞIRHANE', '1-Makinelerin gövde topraklama ölçümlerinin yapılmamaış olması                                            2-Yıpranmış, ezilmiş kablolar', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, elektrik yanıkları', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 1, 3, 15, 45, 'D', '1-Makinelerin gövde topraklama ölçümleri yaptırılmalı, belgelendirilmelidir.\n2-Cihazlar durdurulmadan ve akım kesilmeden bakım, arıza onarım ve müdahaleler yapılmamalıdır.\n3-Yıpranmış, ezilmiş, soyulmuş ve izolasyonsuz kablolar değiştirilmelidir.                                                                                                                           4- Makikenelerin elektrik kabloları çift izolasyonlu olmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: ÇAMAŞIRHANE', '1-Kimyasal dozajlama cihazına kimyasalların takılması sonucu dökülmesi', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', '1- Taşma kapları mevcuttur.', 1, 0, 3, 2, 7, 42, 'D', '1- Kimyasal bidonları her zaman taşma kapları üzerinde bulundurulmalı,  zemine dökülmesi önlenmelidir.                                                                                                                              2- Bidonlar devrilmeyecek şekilde konulandırılmalı,  dozajlama horyumları sağlam olmalıdır.                                                                                                                                                                                                                                                                            3- Boşalan kimyasal madde kapları, bekletilmemeli, atığa gönderilmelidir.', 'ÇAMAŞIRHANE ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: ÇAMAŞIRHANE', '1- Çamaşır yıkama makinasının çalışırken kapağının açılması', '1- Sıcak su ve kimyasallara maruz kalma sonucu iş kazaları meydana gelmesi', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', NULL, 1, 0, 3, 2, 7, 42, 'D', '1-Çamaşır yıkama makinesinin kapak emniyet kilitleri her zaman aktif olmalı, makine çalışırken kapağın açılmaması sağlanmalıdır.\n2- Kapak açıldığında makine otomatik durmalıdır.\n3- Bozuk olan kapak emniyet kilitleri onarılana kadar makineler kullanılmamalıdır.', 'FİRMA\nÇAMAŞIRHANE ÇALIŞANLARI', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: ÇAMAŞIRHANE', '1-Tehlikeli kimyasalların yanlış depolanması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', '1- Kimyasal madde deposu mevcuttur.\n2- Göz duşu bulunmaktadır.', 1, 0, 1, 2, 15, 30, 'D', '1- Kimyasal maddeler depolama matirsine göre depolanmalıdır.                                                        2- Kimyasal maddelerin ağzı açık olmamalı, dik olarak istiflenmelidir.\n3- Kimyasal madde kaplarının altına taşma kapları konulmalıdır.\n4- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.', 'ÇAMAŞIRHANE ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: ÇAMAŞIRHANE', '1- Sıcak yüzey ve boruların izolasyonlarının bozulmuş olması', '1-Temas eden vücut bölümlerinde ısı yanıkları meydana gelmesi', '1- İlgili kamu çalışanları\n2- Diğer ilgili kişiler', NULL, 1, 0, 3, 1, 7, 21, 'D', '1- Sıcak yüzeyler izole edilmelidir.\n2- İzolasyonu bozulmuş olan alanlara yeniden izolasyon yapılmalıdır. \n3- Sıcak yüzeylere uyarı etiket ve işaretler konulmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: ACİL SERVİS', '1- Günlük hasta müracat sayısının fazla olması', '1-Fiziksel şiddet sonucu yaralanma', '1-Acil servis çalışanları', '1-Güvenlik görevlileri alanlarda dolaşım sağlamaktadır.', 1, 0, 6, 3, 15, 270, 'B', '1- Acil servise girişlerde hasta yanında tek refakatçiye izin verilmelidir.                                                                                                  2- Sonuç bekleyen ayaktan hastalar bekleme salonlarına yönlendirilmelidir.                                                                                                   3- Çalışanlar, triaj alanınla bulunan kapıyı hasta içeri girmeden önce açımalı ve tekrar kapatılmalıdır.                                                                                                                                                        4- Yeterli sayıda güvenlik personeli alanlarda bulunmalıdır.', 'GÜVENLİK PERSONELLERİ        \nACİL ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: ACİL SERVİS', '1-Çalışanların fazla mesai ile çalışması                                                          2- İş yükünün fazla olması', '1-Dikkatin azalması, yorgunluk, uykusuzluk, sonucunda iş kazalarının oluşması', '1- Acil servis çalışanları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Fazla mesai süreleri yasal sınırlarla En fazla 130 saat olmalıdır.                                                                                                                                             2- 24 saatlik nöbetten sonra çalışanlara en az 24 saat dinlenme süresi verilmelidir.                               \n3- Gün aşırı nöbet sayısı azaltılmalıdır.                                                                                                            4- Çalışanların düzenli sağlık kontrolleri yapılmalı ve yeterli dinlenme süreleri sağlanmalıdır.                                                                                                                                                                                                                                                                                                                                                    5- Yorgunluk ve stres yönetimi için psikososyal destek programları sağlanmalıdır.', 'İŞVEREN V.', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: ACİL SERVİS', '1- Sarı 1 müşahade alanında hemşire çalışma alanlarının açık olması', '1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma', '1- Sarı 1 müşahade alanı çalışanları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Sarı 1 müşehade hemşire çalışma alanı duvarlar arası açıklık  kapı paravan vb ile kapatılarak, çalışanların arasından hasta ve hasta yakınlarının geçmesi önlenmelidir. \n2- Hemşire çalışma alanına, \"çalışanlar hariç girmek yasaktır\" uyarı evhası konulmalıdır.  \n3- Erişkin acil sarı 1 müşehadede tıbbı sekreterler için çalışma kabini yapılmalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: ACİL SERVİS', '1- Yeşil enjeksiyon odasında fazla sayıda hasta olması', '1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma', '1- Yeşil enjeksiyon odası çalışanları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Yeşil enjeksiyon odası ikinci bir oda açılarak oda işlem sayısı düşürülmelidir.\n2- Yeşil enjeksiyon odası çalışanlarına yaka panik butonları verilmelidir.\n3- Hastalar odaya sıra ile alınmalıdır.', 'İŞVEREN V.                           ACİL ÇALIŞANLARI', '3 AY   \n                      HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: ACİL SERVİS', '1- Hasta ve yakınlarıyla tartışma', '1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma', '1- Acil servis çalışanları', '1- Birçok alanda sabit panik butonları mevcuttur.\n2-  Bazı kapılarda güvenlikler sabit beklemektedir.', 1, 0, 6, 6, 7, 252, 'B', '1- Erişkin acil kan alma odası, çocuk kan alma odası  vb. hasta ve hasta yakınları tarafından fiziksel şiddete maruz kalma riski yüksek olan bölüm çalışanlarına kişisel panik butonu temin edimelidir.                                                                                                        2- Kritik müşahede hemşire tedavi alanına saibit panik butonu takılmalıdır.                                                                                                                        3- Yeterli sayıda sabit güvenlik personeli bulundurulmalıdır.                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             4- Triaj alanında bulunan kapılar buton sistemi ile açılıp kapatılmalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: ACİL SERVİS', '1- Basınçlı oksijen tüplerinin sabitlenmemesi', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1-Acil Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Birçok alanda sabitleme aparatı mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Oksijen tüpünün kullanıldığı her odada sabitleyici aparat bulunmalıdır.\n2- Seyyar ventilatöre bağlı oksijen tüpü en az az iki noktadan sabitlenmelidir \n3- Tüp kullanılmadan önce ezik , çökme hava kaçırma açısından kontrol edilmelidir. Basınç göstergeleri ve vanaların her kullanımdan önce kontrol edilmelidir.                                                                                 \n4- Yatak ve sedye için, sabitleme aparatı, oksijen tüpü taşıma çantası ile çalışılmalıdır.', 'FİRMA           ACİL ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: ACİL SERVİS', '1- Entübe hastaların mr çekilmesi için poliklinik mr a çıkartılması', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1- Acil servis çalışanları\n2- Hasta ve hasta yakınları', NULL, 1, 0, 3, 3, 15, 135, 'C', '1- Acil servis içerisinde bulunan mr cihazına  uyumlu sabit ventilatör cihazı olmalıdır.                                                                                                                    2- Ventilatör cihazına oksijen tüpü çift bant ile sabitlenmelidir.      \n3- Tüplerin taşınması esnasında vanaları kapalı olmalı, dik taşınmalı, kapağı kapalı olmalıdır.', 'FİRMA             TAŞIMA ÇALIŞANLARI', '3 AY\nTAŞIMA ESNASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: ACİL SERVİS', '1-Defibilatörün emniyetsiz kullanımı', '1-Defibrilatör kullanımı sırasında elektrik çarpması, elektrik yanıkları oluşması', '1- Defbilatör kullanan çalışanlar                                                     2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 3, 15, 135, 'C', '1-Defibrilasyon esnasında hastaya elektrotlara ve diğer iletken nesnelere dokunulmamalıdır.\n2-Hastaya ıslak  ve iletken ortamlarda defibrilasyon uygulanmamalı, hastanın göğsünde ıslaklık, jel, ter olmamalı, hastanın göğüsü kurulanmalıdır.\n3-Defibrilatör cihazı oksijen tüpü, alkol vb. yanıcı sıvı ve gazların bulunduğu ortamlarda kullanılmamalıdır.                                                                               4- Hastanın ve defibilatörü kullanan çalışanın üzerinde metal eşyalar bulunmamalıdır.                                                                                           5- Ortamda bulunan diğer çalışanlar en az 1 metre uzakta bulunmalıdır.', 'DEFİLBİLATÖR KULLANAN ÇALIŞANLAR', 'DEFİBİLATÖR KULLANIM SIRASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: ACİL SERVİS', '1- Kesici delici alet yaralanması', '1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma', '1-Acil servis çalışanları', '1- Alanda sharp box kutusu bulunmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                              2- Kesici delici alet kutu kapakları vacoteynır çıkartmaya uyumlu olmalıdır.                                                                                                                                                                                                                                                                                                                                                          3- Alanda bulunan sharp boxlar 3/4 ü dolduktan sonra değiştirilmelidir.                                                                                           4- Hasta yataklarına iğne uçları saplanmamalı, iğne uçları pendant üzerine bırakılmamalıdır.    \n5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.', 'ACİL ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: ACİL SERVİS', '1- Kan ve vücut sıvılarının göz ve cilde temas etmesi', '1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma', '1-Acil servis çalışanları', '1- Çalışanlar eldiven ve maske kullanmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1-Çalışanlar TS EN 455  standardında eldiven, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında maske vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.', 'İŞYERİ HEKİMİ\n\nACİL ÇALIŞANLARI', 'MARUZİYET OLMASI DURUMUNDA\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: ACİL SERVİS', '1-Basınçlı tüplerin hatalı kullanılması', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1-Acil Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Oksijen tüpü sabitleme aparatları bulunmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Oksijen tüplerine yağlı, kremli eller ile temas edilmemeli, vanaları yağlanmamalıdır.                                                                                                                                   2- Tüpler ısı kaynaklarından ve güneşin etkisinden uzak tutulmalıdır.                                                                                                                                    3- Manometreler sağlam olmalı, kırık olanlar değiştirilmelidir.                                       \n4- Basınçlı tüpler zeminde sabitlenmeden bırakılmamalı, sabitleme aparatlarına takılmalı ve 2 noktadan zincir ya da halatla bağlanmalıdır.', 'ACİL ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: ACİL SERVİS', '1- Cpr odasına müdahale esnasında hasta yakınlarının girmesi', '1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma', '1- Cpr odalarında çalışanlar', NULL, 1, 0, 6, 3, 7, 126, 'C', '1- Cpr odasına müdahale esnasında hasta yakınlarının girmesi engellenmelidir. \n2- Hasta yakınlarının yanında güvenlik personeli bulunmalıdır.  \n3- Müdahale esnasında perde kapatılmalıdır.                                                                                                                                                                                                                                                                                                                 4- Kesici delici aletler ortalıkta bırakılmamalı, büyük makas işlemden sonra seyyar pendant çekmecesinde muhafaza edilmelidir.', 'ACİL ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: ACİL SERVİS', '1- CPR odasına bulaşıcı hastalığı olan entübe hastaların gelmesi', '1- Bulacı hastalık  2- Enfeksiyon', '1- Cpr odalarında çalışanlar\n2- Acil servis çalışanları', NULL, 1, 0, 6, 3, 7, 126, 'C', '1- CPR odasına zaman ayarlı, TS EN 62471 standartına uygun UV lambaları konulmalıdır.\n2- UV-C lambalarında alttan, üstten ve yandan ışık sızıntısı olmamalıdır.\n3- UV-C lambalarının yüzeyi yansıma yapmayacak şekilde olmalıdır.\n4- UV Lambaları çalışanlar bölümdeyken çalıştırılmamalıdır.\n5- UV lambasını kapatmak için odaya girildiğinde TS EN 170 standartında uv gözlük, uzun kollu koruyucu kıyafet, uv geçirmeyen eldiven vb. kişisel koruyucu ekipmanlar kullanılmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: ACİL SERVİS', '1- Uzun sürelerle ayakta çalışılması', '1- Kas iskelet sistemi hastalıkları \n2- Varis oluşması', '1- Acil servis çalışanları', '1- Çalışanlar için dinlenme odaları mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1- Çalışanlar 45 dakikalık periyotlarla oturarak dinlenmelidirler. \n2- Çalışanlar ortopedik tabanlı iş ayakkabısı giymeli, eksik malzemeler temin edilmelidir.\n3- Yeterli dinlenme molaları verilmeli, rotasyonlu çalışma yapılmalıdır.', 'İŞVEREN V. \nBİRİM SORUMUSU', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: ACİL SERVİS', '1- Vucut sıvılarının dökülmesi', '1-Düşme, denge kaybı sonucunda  yaralanma', '1- Acil servis çalışanları', NULL, 1, 0, 6, 6, 3, 108, 'C', '1- Vücut sıvıları zemine döküldüğünde bekletilmemeli, hemen temizlenmesi sağlanmalıdır.\n2- İdrar torbası askıları alanda hasta yatakları ve sedyelere asılmalıdır.                                                                                                                                      3- İdrar torbasının boşaltımı esnasında under ped ya da kap konularak dökülme saçılma engellenmelidir.                                                                                                                                                                                                                                                                                                                                     4- Kan ürünü temizliği için alkol kullanılmamalıdır.', 'TEMZİLİK ÇALIŞANLARI\nACİL ÇALIŞANLARI', 'DÖKÜNTÜ DURUMUNDA\nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: ACİL SERVİS', '1- Kan alma koltuklarının kollarının kırık olması', '1- Kesici delici alet yaralanması                   2- iş kazası', '1- Acil servis çalışanları', NULL, 1, 0, 6, 6, 3, 108, 'C', '1- Hasarlı ya da kırık kan alma kotukları değiştirilmeli ya da onarılmalıdır.\n2- Koltuk kolları sağlam olmalı, kan alma işlemi sırasında sabit olması sağlanmalıdır.\n3-  Koltuk yüksekliği çalışanı rahatsız edici göz ve baş hareketleri ihtiyacını en aza indirecek şekilde olmalıdır.                    \n3- Sandalyeler ergonomik tasarıma sahip olmalı, gerekli hallerde ayak desteği kullanılmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: ACİL SERVİS', '1- Pediatrik kan alma odasında havalandırma sistemi olmaması', '1- Solunum sistemi hastalıkları', '1- Çocuk kan alma odası çalışanları', NULL, 1, 0, 6, 6, 3, 108, 'C', '1- Pediatrik kan alma odasına havalandırma sistemi yapılmalıdır.                                                                                                                                         2- Odada bulunan banyo giderinden gelen koku gider kapatılarak bertaraf edilmelidir.                                                                                          \n3- Odada ısı nem ölçer bulunmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: ACİL SERVİS', '1- Çalışanların yüksek gürültüye maruz kalması', '1-Dikkatin azalması\n2- Yorgunluk, uyku bozuklukları,\n3- İş kazalarında artış', '1-Acil servis çalışanları', NULL, 1, 0, 3, 2, 15, 90, 'C', '1- Gürültü ölçümleri yapılarak gürültü düzeyi belirlenmelidir.                                                                                                2- Hasta refakatçi sayısı en aza indirilmelidir.                                                                                                 3- Ölçümlerin 85 Db üzerinde çıkan alanlarda TS EN 352  standardında kkd kulak koruyucularını temini ve kullanımı sağlanmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: ACİL SERVİS', '1- Bulaşıcı hastalığı olan ya da şüphesi olan hastalar', '1-Enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- Acil servis çalışanları', '1-Acil de negatif basınçlı odalar mevcuttur.???', 1, 0, 3, 3, 7, 63, 'D', '1-Bulaşıcı hastalık şüphesi olan hastalar, sonuçları çıkana kadar tek kişilik izolasyon odalarında tutulmalıdır.                                                                                           2- Şüpheli hastaların bulunduğu alanın teması bittikten sonra hemen dezenfekte edilmelidir.                                                                                                                          3- Tanı konulmuş hastalar negatif basınçlı odalara alınarak izole edilmelidir.                                                                                                                                                                                                                                                                  5-Çalışanlar N95 ya da TS EN 149 standrtdında FFP2 filtreli maske, yüz siperi, TS EN 455  standardında eldiven kullanmalıdır.', 'ACİL ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: ACİL SERVİS', '1- Psikiyatri hastalarının alanda tedavi edilmesi', '1- Psikiyatri hastası tarafından fiziksel şiddete uğrama', '1- Acil servis çalışanları', '1- Yumuşak oda mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Akli dengesi yerinde olmayan ya da saldırgan davranış gösteren hastalar yumuşak oda da tedavi edilmelidir.                                                                                               2- Yumuşak odadaki hastaya tedavi uygulama esnasında güvenlik eşlik etmeli ve çift hemşire ile odada çalışılmalıdır.                                                                                                                                                          3- Yumuşak odadaki kapı penceresi kırılmaz cam olmalıdır.                                                                  \n4- Yumuşak oda içinde yatağa sabitleyici aparat alanda bulunmalıdır.', 'İŞVEREN V.   \n                        ACİL ÇALIŞANLARI', '3 AY   \n                      HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: ACİL SERVİS', '1- Kan gazı ve mikroskop cihazları kullanılırken numunelerin dökülmesi', '1- Enfeksiyon         2- İş yükü', '1- Numune inceleyen çalışanlar', '1- KKD\'ler mevcuttur.', 1, 0, 6, 3, 3, 54, 'D', '1- Kan gazı ve mikroskop cihazlarının bulunduğu alan yüzey bakımından silinebilir ve dezenfekte edilebilir olmalıdır.                                                                                \n2- Numuneleri dökülmesi durumunda hemen dökülen yüzey dezenfekte edilmelidir.                                                                                                                                                           3- Maske, eldiven, yüz siperi vb. kkdler kullanılmadan cihazlarda çalışılmamalıdır.', 'NUMUNE İNCELEYEN ÇALIŞANLAR', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 1: ACİL SERVİS', '1- Çalışanların dinlenme alanının koltukluların deforme olması, ısı nem ölçerlerinin bulunmaması', '1-Enfeksiyon, kas, iskelet  ve sinir sistemi hastalıkları, solunum sistemi hastalıkları', '1-Acil servis çalışanları', '1- Havalandırma sistemi mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1- Dinlenme odalarında ki deforme olmuş koltuklar ya değiştirilmeli ya da onarılmalıdır.                                                                                                                                                                                       2- Dinlenme odalarında ısı nem ölçerler bulumalıdır.                                                                                                                                                                                                    3- 24 saat nöbet usulü çalışanların dinlenme alanları ulaşılabilir ve açık tutulmalıdır.                                                                                                                       4- Dinlenme odalarında kişi başına düşen hava miktarı en az 10 metreküp olacak şekilde iş organizasyonu yapılmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 1: ACİL SERVİS', '1- Ekranlı araçlarla çalışmalarda sağlık ve güvenlik önlemlerinin alınmaması', '1- Göz yorgunluğu,göz kuruluğu, bulanık görme.                                                                    2- Stres, dikkat dağınıklığı', '1-Tıbbi sekreterler', '1- Dinlenme molaları mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1- Ekran parlaklığı ve çözünürlüğü kişiye göre ayarlanmalı, Ekranın çalışana uzaklığı en az 60 cm olmalı ve çalışanın göz hizasında olmalıdır.                                                                                      \n2- Sandalyeler ergonomik tasarıma sahip olmalı, ayaklar düz olarak yere temas etmeli, diz 90 derece açılı olmalı,  sandalyede bel desteği olmalı,  sırt dik, omuzlar rahat, dirsekler 90 derece açılı olmalıdır.                                                                 \n3- Mouse destek pedi temin edilmelidir.', 'İŞVEREN V.                          (EKSİK MALZEMELER) ACİL ÇALIŞANLARI', '3 AY   \n\n                      HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 1: ACİL SERVİS', '1- Portable röntgen cihazının kullanımı sonucunda radyasyon ışınlarına  maruz kalma', '1-Radyasyon maruziyeti sonucu meslek hastalıkları', '1-Acil servis çalışanları', '1- Kurşun önlükler mevcuttur.', 1, 0, 1, 3, 15, 45, 'D', '1- Taşınabilir röntgen cihazı ile yapılan çekimler de kurşun paravan kullanılmalıdır.                                                                                                                                                               2- Çekim yapılan alanda hasta ve çekim yapan çalışan dışında kimse olmamalı, zorunlu hallerde bulunulması gerekirse(TS EN 61331 standardında kurşun önlük troid koruyucu vb.kişisel koruyucu ekipmanlar kullanılmalıdır.                                                                                                       3- Çekim yapılan odaların kapıları kapatılmalıdır.                                                                                           4- Açık alanlarda yapılan çekimlerde çalışanlar en az 2 metre uzakta durmalıdır.', 'RADYOLOJİ ÇALIŞANLARI       ACİL ÇALIŞANLARI', 'ÇEKİM ESANASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM 1: ACİL SERVİS', '1- Yotalanmamış esyaların bulunması', '1- İş kazası                   2- Devrilme            3- Ezilme', '1- Acil servis çalışanları', '1- Bazı dolaplar duvara sabitlenmiştir.', 1, 0, 3, 2, 7, 42, 'D', '1- Alanda , dinlenme odalarında , süper visör odalarında ve Acil servisler içindeki dolaplar, ranzalar, metal tel dolaplar en az iki noktadan duvara sabitlenmelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM 1: ACİL SERVİS', '1-İsmi bilinmeyen bilinci kapalı  hastaların acil müdehale için getirilmesi', '1- Enfeksiyon hastalıklarına yakalanma', '1- Kırmızı alan çalışanları', '1-KKD\'ler mevcuttur.', 1, 0, 3, 2, 7, 42, 'D', '1- Klinik geçmişine ulaşılamayan hastaları enfekte kabul edilmeli eldiven, maske, gözlük, önlük gibi kkdler kullanılmalıdır.                                                                                                                  2-  Hastane polisi ile kısa sürede iletişime geçilerek hasta bilgilerine ulaşım sağlanmalıdır.', 'ACİL ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 27, 'BÖLÜM 1: ACİL SERVİS', '1- Hastaların yoğun bakım ve ameliyathaneye transfer esnasında transfer çantası kullanılmaması', '1- Kesici delici aletlere temas sonucu yaralanma', '1- Hasta transferine eşilk eden hemşireler', NULL, 1, 0, 3, 3, 3, 27, 'D', '1- Hasta transferi yapılırken çalışanın üzerinde  ampül enjektör vb kesici delici alet bulunmamalıdır.                                                                                                        2- Hasta tranfer çantası kullanılmalıdır.                                                                                                                   3- Çantalar hasta yataklarına düşmeyecek devrilmeyecek şekilde konumlandırılmalıdır.', 'HASTA TRANFERİNE EŞİLK EDEN HEMŞİRELER', 'TRANSFER ESNASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 28, 'BÖLÜM 1: ACİL SERVİS', '1- Taşıma tahtalarının sabitlenmemesi', '1-Tahtalrın düşmesi sonucu yaralanma', '1- Acil servis çalışanları', NULL, 1, 0, 3, 3, 3, 27, 'D', '1- Alanda bulunan taşıma tahtaları duvara sabitlenmelidir.                  \n2- Tahtalar için sabit alan belirlenmelidir.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 29, 'BÖLÜM 1: ACİL SERVİS', '1- Su sebillerinin bakım ve temizliğinin yapılmaması.                                           2- Su sebillerinin su sızdırması', '1-Enfeksiyon, bulaşıcı hastalıklara yakalanma', '1-Sarı alan mutfak alanı kullanan çalışanlar', '1- Enfeksiyon riskleri hakkında eğitim verilmiştir.', 1, 0, 3, 3, 3, 27, 'D', '1- Su sebillerinin bakımları  düzenli aralıklarla yaptırılmalıdır.                                                                                   2- Su sebillerinin temizliği düzenli aralıklarla yaptırılmalıdır.                                                                                                                                                                          3- Su sızıntılarından kaynaklı riskleri önlemek için su sebillerinin altlarına taşma havuzu konulmalıdır.                                                                                                                                                                                                                                      4- Su sebillerinin bulunduğu zemin davamlı kuru tutulmalıdır.', 'BİRİM SORUMLUSU', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 30, 'BÖLÜM 1: ACİL SERVİS', '1- Refakatçilerin beklerken çalışan sandalyelerini alması', '1- Beyaz kod                  2- Enfeksiyon', '1- Acil servis çalışanları', NULL, 1, 0, 3, 3, 3, 27, 'D', '1- Alanda yeterli refakatçi sandalyesi bulunmalı, eksik sandalyeler temin edilmelidir.                             \n2- Refakatçi sandalyeleri enfeksiyon açısından silinebilir deri , plastik vb malzemeden olmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 31, 'BÖLÜM 1: AMBULANSLAR', '1- Eskimiş, aşınmış  lastiklerin kullanılması\n2- Mevsime uygun lastik kullanılmaması', '1-Trafik kazası sonucunda ölüm, sakatlık, uzuv kaybı, yaralanmaların meydana gelmesi', '1-Ambulans şoförleri\n2-Ambulans içinde bulunan çalışanlar\n3- Hastalar', '1- Ambulanslar hastane içinde ya da hasta nakil için kullanılmaktadır.', 1, 0, 6, 3, 15, 270, 'B', '1- Mevsim şartlarına uygun yazlık-kışlık lastikler kullanılmalı, karlı havalarda zincir kullanılmalıdır.\n2- Aşınan, yıpranan, ezilen, balon yapan lastikler yenileri ile değiştirilmelidir.\n3- Lastik havaları mevsim şartlarına ve üretici tavsiyelerine uygun basınçta şişirilmelidir.\n4- Kaygan yollarda, sisli havalarda araçlar çok düşük hızlarda kullanılmalıdır.', 'İŞVEREN V.\nAMBULANS ŞOFÖRLERİ', '1 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 32, 'BÖLÜM 1: AMBULANSLAR', '1-Eve hasta nakil sırasında trafik kurallarına uyulmaması', '1-Trafik kazası sonucunda ölüm, sakatlık, uzuv kaybı, yaralanmaların meydana gelmesi', '1-Ambulans şoförleri\n2-Ambulans içinde bulunan çalışanlar\n3- Hastalar', NULL, 1, 0, 3, 2, 40, 240, 'B', '1- Nakil ambulansları yasal hız limitlerinden %10 daha düşük hızda kullanılmalıdır.\n2- Nakil ambulansları sağ şeritte ve yavaş kullanılmalıdır.\n3- Trafik kurallarına uyulmalı, sinyalizasyon sistemi mutlaka kullanılmalı, takip mesafesi korunmalıdır.\n4- Seyir halinde şoför ve araç içinde bulunan çalışanların emniyet kemerleri mutlaka takılı olmalıdır.\n5- Araçalar seyir halindeyken sigara içilmemelidir.', 'AMBULANS ŞOFÖRLERİ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 33, 'BÖLÜM 1: AMBULANSLAR', '1- Ambulans bakım ve servis işlemlerinin düzenli yapılmaması', '1-Trafik kazası sonucunda ölüm, sakatlık, uzuv kaybı, yaralanmaların meydana gelmesi', '1-Ambulans şoförleri\n2-Ambulans içinde bulunan çalışanlar\n3- Hastalar', '1- Ambulansların periyodik kontrolleri yapılmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1- Ambulanslar kullanmaya başlanmadan önce günlük kontrolleri yapılmalıdır.\n2- Her 3 ayda veya 10.000 km’de bir yetkili bir servise periyodik bakım yaptırılmalıdır.\n3- Yılda bir kez yaptırılacak fren bakımı kayıtları olmalıdır. \n4- Araç ruhsatında süresi geçmemiş fenni muayene ve egzoz emisyon test raporları mevcut olmalıdır.\n5- Tespit edilen eksiklikler giderilmeden araçlar kullanılmamalıdır.', 'İŞVEREN V.\n\n\nAMBULANS ŞOFÖRLERİ', 'İLGİLİ PERİYOTLAR İLE\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 34, 'BÖLÜM 1: AMBULANSLAR', '1- Sedye ile hasta taşıma sırasında güvenlik önlemlerinin alınmaması', '1- Kas iskelet sistemi hastalıkları', '1-Ambulans şoförleri\n2-Ambulans içinde bulunan çalışanlar', '1- Sedyelerin tekerlek frenleri mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Sedye, tekerlekli sandalye vb. ekipmanların ayaklarında frenleri sağlam olmalıdır.\n2- Sedye ile taşıma işleri en az 2 çalışan tarafından yapılmalıdır.\n3- Hastalar sedye ile taşınırken emniyet kemeri ile bağlanmalıdır.', 'AMBULANS ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 35, 'BÖLÜM 1: AMBULANSLAR', '1- Yangın tüpü kontrollerinin yapılmamış olması', '1- Yangın durumunda müdahaele edilememesi', '1-Ambulans şoförleri\n2-Ambulans içinde bulunan çalışanlar\n3- Hastalar', '1-Ambulans içinde yangın söndürücü bulunmaktadır.', 1, 0, 3, 2, 15, 90, 'C', '1- Ambulansta bir adet hasta kabininde, bir adet sürücü kabininde 2\'şer litrelik kuru kimyevi tozlu yangın söndürücüler bulunmalıdır.                   \n2- Yangın tüplerinin kontrol ve bakımları yapılmalı, tüpler her zaman dolu olmalıdır.\n3- Tüpler ambulans içinde dik konumda sabitlenmelidir.', 'İŞVEREN V.\nAMBULANS ŞOFÖRLERİ', '1 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 36, 'BÖLÜM 1: AMBULANSLAR', '1- Ambulans içinde oksijen tüpü kullanılması', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1-Ambulans şoförleri\n2-Ambulans içinde bulunan çalışanlar\n3- Hastalar', '1- Tüp dolabı mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Ambulans içindeki taşınabilir oksijen tüpü defibrilatör gibi elektrikli cihazların yanında bulunmamalıdır.                                             \n2- Oksijen tüpleri devrilme açısından en az iki noktadan sabitlenmelidir.                                                                                                                                                                            3- Yağlı kremli vb ellerle dokunulmamalıdır.', 'AMBULANS ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 37, 'BÖLÜM 1: AMBULANSLAR', '1- Tıbbi ekipmanın ve ambulansın her vaka sonrası  dezenfekte edilmemesi', '1- Bulacı hastalık  2- Enfeksiyon', '1-Ambulans şoförleri\n2-Ambulans içinde bulunan çalışanlar', NULL, 1, 0, 3, 3, 3, 27, 'D', '1- Tıbbi ekipman ve ambulansın her vaka sonrası kontrol ve dezenfekte edilmesi sağlanmalıdır.               \n2- Vaka sonrası ambulanslar havalandırılmalıdır.', 'AMBULANS ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: DEPO ARŞİV', '1-Sığınakların depo olarak kullanılması', '1- Acil durumlarda sığınakların kullanılamaması sonucu yaralanma, ölüm', '1-Tüm çalışanlar\n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 1, 3, 100, 300, 'B', '1- Hastane de savaş, afet, kimyasal / biyolojik vb. acil durumlarda kullanılması gereken sığınakların depo olarak kullanılması tamamen sonlandırırlmalıdır.\n2- Sığınaklarda ki malzemeler boşaltılamı, acil durumlara hazır hale getirilmelidir.\n3- Depo ihtiyacı için ayrı alanlar oluşturulmalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: DEPO ARŞİV', '1- Raf önü tutucuların bulunmaması                                           2- Endüstriyel rafların sabitlenmemesi', '1- Malzeme düşmesi sonucu  yaralanma, ezilme, sıkışma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', '1-Bazı bölümlerde volanlı ray sistemi mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1- Tüm arşiv alanlarında volanlı raylı sistem kullanılımalıdır.\n2- Rafların önüne malzemelerin devrilmesini engelleyecek raf önü tutucular kullanılmalıdır.                                                                    \n3-  Endüstriyel raflar en az iki noktadan  sabitlenmeli, düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.', 'İŞVEREN V.', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: DEPO ARŞİV', '1- Depolarda yüksek istifleme yapılması', '1- Malzeme düşmesi sonucu  yaralanma, ezilme, sıkışma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 6, 3, 15, 270, 'B', '1- İstif yüksekliği en fazla 3 metre olmalıdır.\n2- Malzemeler düzenli istiflenmeli, devrilmeyecek şekilde sabitlenerek istif yapılmalıdır.\n3- Devrilme riski olan malzemeler 1,5 metreden yüksek istiflenmemelidir.\n4- Stok girişi yapılmayan malzemeler depoya alınmamalıdır.\n5- Ağır malzemeler en altta istiflenmelidir.', 'DEPO ECZANE ARŞİV ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: DEPO ARŞİV', '1- Endüstriyel rafların periyodik kontrollerinin yapılmaması', '1- Rafların devrilmesi sonucu yaralanma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 6, 15, 270, 'B', '1- Raflar  TS EN 15635 standartalarına uygun azami kontrol süresi geçmeden periyodik kontrolleri  yapılmalıdır.    \n2- Metal kısımların dayanıklılık ve metal yorgunluğu testleri yaptırılmalıdır. \n3- Bağlantı noktaları, çatlak, aşınma, taşıyıcı kısımlar 3 ayda bir kontrol edilmeli, eksiklikler giderilmelidir.', 'İŞVEREN V.', 'İLGİLİ PERİYOTLAR İLE \nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: DEPO ARŞİV', '1- Elektrikli transpaletin periyodik kontrolünün olmaması', '1- Yüklerin düşmesi, devrilmesi sonucu yaralanma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 6, 15, 270, 'B', '1-Alanda kullanılan elektrikli transpaletlerin periyodik kontroleri; TS EN 1757-2 standartlarına uygun olarak yılda 1 yapılmalıdır.                                                                                      2- En fazla kaldırma kapasitesinin en az 1, 25 katını, etkili ve güvenli bir şekilde kaldıracak ve askıda tutabilecek güçte olmalıdır ve bunların bu yüke dayanıklı ve yeterli yük frenleri bulunmalıdır.       \n3- Elektrikli transpaletin günlük, haftalık, aylık, üç aylık bakımları, imalatçının belirlediği şekilde ya da imalatçı tarafından yetkilendirilmiş servislerce yapılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: DEPO ARŞİV', '1- Ygap binasına minibüs ile arşiv dosyalarının taşınması', '1- Trafik kazası                sonucu  yaralanma', '1- Arşiv', NULL, 1, 0, 6, 3, 15, 270, 'B', '1- Risk değerlendirmesinin \"Hastane Araçları\" bölümünde bulunan düzeltici önleyici faaliyetler bu bölümde yer alan araçlar için de uygulanmalıdır.\n2- Minibüse sadece yolcu koltuk sayısı kadar çalışan alınmalı, arka kısımda çalışan taşınmamalı, ön kısımda bulunan 2 li oturma koltuğunda 3 çalışan alınmamalıdır.\n3- Minibüs sadece görevlendirilmiş ve uygun ehliyete sahip çalışanlar tarafından kullanılmalıdır.\n4-Minibüse binen herkes emniyet kemerlerini bağlamalıdır.', 'İŞVEREN V.\nDEPO ECZANE ARŞİV ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: DEPO ARŞİV', '1- Elekrikli transpalet ile insan taşınması', '1-Düşme sonucu yaralanma', '1-Depo çalışanları\n2-Diğer ilgili çalışanlar', NULL, 1, 0, 6, 3, 15, 270, 'B', '1- Elektrikli transpalet çatallarında insan taşınmamalıdır.                                                           \n2- Zorunlu hallerde elektrikli transpalet üzerinde yapılacak çalışmalar için sepet temin edilmelidir.                                                                                        3-İnsan taşımak için kullanılacak sepet sabitlenmeli ,sepet üzerinde yapılacak çalışmalarda emniyet kemeri kullanılmalıdır.', 'FİRMA', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: DEPO ARŞİV', '1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması', '1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması', '1- Depo, eczane, arşiv çalışanları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan kkd\'ler temin edilmelidir.\n2- Çalışanların maskeleri TS EN149 standardında uygun olmalıdır.                                                                                                                     3-Çalışanların göz koruyucuları TS EN 166 standardına uygun ve tam kapalı tip olmalıdır.                                                                                                                             4-Çalışanların iş eldivenleri TS EN 388 standartına uygun olmalıdır.                                                                                                                                5- Çalışanların iş ayakkabıları, koruyucu burun ve taban TS EN ISO 20345 standartına uygun olmalıdır.\n6- Çalışanların baretleri TS EN 397 standartına uygun olmalıdır\n7-Çalışanlar sahada kişisel koruyucu ekipmanlarını eksiksiz şekilde kullanmalıdırlar.', 'İŞVEREN V.  \n\nDEPO ECZANE ARŞİV ÇALIŞANLARI', '2 AY\n\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: DEPO ARŞİV', '1- Raflardan malzeme almak için eskoba merdiven ya da el merdiveni kullanılması', '1-Merdivenden düşme sonucu yaralanma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', '.', 1, 0, 6, 6, 7, 252, 'B', '1- Raflardan malzeme almak için eskoba ya da el merdivenleri kullanılmamalı, TS EN 131 standartlarına uygun merdivenler temin edilmelidir.                                                                                   \n2- Kullanılacak merdiven en az 1 metre yükseklikte korkuluklu, 47 cm de ara korkuluklu, platformlu, yere sabitlenebilen tekerlek frenleri olan yapıda olmalıdır.  \n3-Platformlu merdivenlerin giremeyeceği dar raf aralarında kullanılan el merdivenlerinin ayaklarına, merdivenin kaymasnı önlemek için destekler konulmalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: DEPO ARŞİV', '1- Raf arası mesafelerin yetersiz olması', '1- Çarpma, sıkışma, düşme sonucu yaralanma', '1-Arşiv çalışanları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Raflar arası boşluk en az yaya geçişi için 80 cm, merdiven geçmesi için en az 120 cm olacak şekilde iş organizasyonu yapılmalıdır.                                                  \n2- Depolama alanı değişikliği yapılmalıdır.\n3- Raf yerleşim planı hazrılanmalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: DEPO ARŞİV', '1- Koridor , tüneller, otopark, sığınak vb alanlara  malzeme istif edilmesi', '1-Acil durumlarda tahliyenin zorlaşması', '1-Tüm çalışanlar\n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Miadı geçen ürünlerin alandan bertaraf edilerek uzaklaştırılıp alanın açılması sağlanmalıdır.                                                                                       \n 2- Yeni depolama alanları belirlenerek koridor, tüneller, otopark, sığınak vb. alanlar depolama için kullanılmamalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: DEPO ARŞİV', '1- Depo alanlarının tozlu olması', '1- Solunum sistemi hastalıkları meydana gelmesi', '1-Depo çalışanları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Jet fanlar devreye girdiğinde çalışanlar depoda bulunmamalı,  fanlar kapandığında alandaki toz hemen temizlenmelidir.                                                                                       2- Haftada en az 2 defa ıslak zemin  temizliği yapılmalıdır.                                                                                     3- Toz maskesi kullanılarak maruziyet önlenmelidir.           \n4- Çalışanların hijyenlerini sağlayabilmeleri için el yıkama lavbosu bulunmalıdır.', 'İŞVEREN V.  \nDEPO ECZANE ARŞİV ÇALIŞANLARI', '2 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: DEPO ARŞİV', '1- Endüstriyel rafların ayak koruma bariyerlerinin bulunmaması', '1-Rafların devrilmesi sonucu yaralanma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 6, 2, 15, 180, 'C', '1- Elektrikli transpalet, transpalet vb. kaldırma ekipmanı kullanılan alanlarda rafların ayaklarına koruma bariyerleri takılmalıdır.\n2- Koruma bariyerli yüksek mukavemetli, darbelere dayanıklı çelik vb. darbe emici malzemeden yapılmış olmalıdır.\n3- Koruma bariyerleri yerlerinden çıkmayacak şekilde sabitlenmelidir.', 'İŞ VEREN', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: DEPO ARŞİV', '1- Endüstriyel rafların, raf panellerinin eksik olması \n2- Tahta paletlerin, raf paneli olarak kullanılması', '1-Malzemelerin devrilmesi sonucu yaralanma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 3, 15, 135, 'C', '1- Endüstriyel rafların eksik raf panelleri temin edilmelidir. \n2- Paneller sağlam, yerinden çıkmayacak şekilde monte edilmelidir.\n3- Tahta paletler raf paneli olarak kullanılmamalıdır.                                                    4- Deforme olmuş, bel vermiş raf panelleri değiştirilmelidir.\n5- Mevcut raf panelleri iptal edilmemelidir.', 'İŞVEREN V.  \n\nDEPO ECZANE ARŞİV ÇALIŞANLARI', '2 AY\n\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: DEPO ARŞİV', '1- Depo ve eczanelerde  zaman zaman tavandan su sızıntısı olması', '1- Elektrik çarpması                      2- Kayma düşme', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', '1- Su giderleri bulunmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1-Tıkalı olan su giderleri açılmalıdır.\n2- Tavan akıntısına neden olan tesisat, çatı veya klima hattı arızaları onarılmalıdır.                                          \n3- Elektrik kablolarının suyla temas riskine karşı izole edilmelidir.  \n4- Tavan akması görülen bölgeler uyarı şeridi veya bariyerlerle çevrelenmelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: DEPO ARŞİV', '1- Tavan aydınlatmalarına yakın istifleme yapılması', '1-Yangın çıkması', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', '1- Yangın söndürme sistemleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Aydınlatma armatürleri ile malzemeler arasında 50-100 cm boşluk bırakılmalıdır.                           \n2- Aydınlatma armatürleri ısı çıkarmyan led aydınlatma ya da etanj aydınlatmalar kullanılmalıdır.\n3- Yangın söndürücüler her zaman hazırda bulundurulmalıdır.', 'İŞVEREN V.  \n\nDEPO ECZANE ARŞİV ÇALIŞANLARI', '2 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: DEPO ARŞİV', '1- Rafların taşıma kapasitesinin bilinmemesi                                                         2- Raflara hatalı istifleme yapılması', '1- Rafların fazla yüklenmesi sonucu devrilmesi', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 6, 3, 7, 126, 'C', '1- Her rafa maksimum taşıma kapasitesi, görünür okunabilir şekilde asılmalıdır.\n2- Raflara taşıma kapasitesinin %10 altı ağırlıktaki malzemeler istiflenmelidir.\n3- Yükler raf yüzeylerine eşit dağıtılmalıdır.\n4- Malzemeler düzenli, devrilmeyecek şekilde istiflenmelidir.', 'İŞVEREN V.  \nDEPO ECZANE ARŞİV ÇALIŞANLARI', '3 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: DEPO ARŞİV', '1- Elektrikli transpalet ve manuel transpaletlere yüklerin düzensiz ve sabitlenmeden yüklenmesi, taşınması', '1- Yüklerin düşmesi, devrilmesi sonucu yaralanma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Yükler dengeli yüklenmelidir.\n2- Yüksek, ağır ve dengesiz düşebilecek yükler sabitlenerek taşınmalıdır.\n3- Taşıma alanında çalışanlar bulunmamalıdır.\n4- Transpaletlerde taşıma kapasitesi üzerinde yük taşınmamalıdır.\n5- Taşıma araçları sonrası kontrol edilmelidir.\n6- Yükler çalışanın görüşünü engellemeyecek şekilde taşınmalıdır.', 'DEPO ECZANE ARŞİV ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: DEPO ARŞİV', '1- Transpaletlerin periyodik kontrollerinin yapılmaması', '1- Yüklerin düşmesi, devrilmesi sonucu yaralanma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Manuel transpaletlerin periyodik kontrolleri  TS EN ISO 3691 serisi, FEM 4.004 standartlarında belirtilen kriterlere uygun olarak yapılmalıdır.                                                                                                                          2- Periyodik kontrolleri yapılmamış manuel  transpaletler kullanılmamalıdır.', 'İŞVEREN V.', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: DEPO ARŞİV', '1- Elektrikli transpalet kullanan çalışanların mesleki yetrlilik belgelerinin olmaması', '1- İş kazaların oluşması ve artması', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Elektrikli transpaletler sadece mesleki yeterlilik belgesine sahip çalışanlar tarafından kullanılmalıdır.                                                                                       2- Çalışanlar meslek eğitim merkezlerine gönderilerek yaptığı işe uygun mesleki yeterlilik belgesi alması sağlanmalıdır.\n3- Kamu çalışanları tarafından elektrikli transpalet kesinlikle kullanılmamalıdır.', 'FİRMA  \nDEPO ECZANE ARŞİV ÇALIŞANLARI', '3 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: DEPO ARŞİV', '1- Kaygan zemin oluşması                                                                  2- Bozuk zemin yüzeyi', '1-Düşme, denge kaybı sonucunda vücut bölümlerinin yaralanması', '1-Arşiv  çalışanları                        2- Kule serum depo çalışanları', NULL, 1, 0, 6, 3, 6, 108, 'C', '1-YGAP ta arşiv odası zemininde bulunan borular körlenmelidir.\n1- Bozulan zeminin tamir ve tadilatı yapılmalıdır.\n2- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.                                                                                                     \n3- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\n4- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 1: DEPO ARŞİV', '1- Kolilerin, dosyaların el ile taşınması', '1-Düşme, devrilme  sonucu yaralanma', '1-Tüm çalışanlar\n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Çalışanlara elle taşıma teknikleri hakkında eğitim verilmiştir.', 1, 0, 6, 6, 3, 108, 'C', '1- Erkekler 25 kg üzerinde kadınlar 15 kg üzerinde yük kaldırmamalıdır.                                                                                   2- Dengesiz devrilme riski olan yükler sabitlenerek taşınmalıdır.\n3- Yükler taşıma teknikleri kullanılarak taşınmalıdır.\n4- Yükler görüş alanını kapatmayacak şekilde taşınmalıdır.                                                                                                 5- Depo, eczane ve arşivde çalışan personellere yüksekte çalışma, depolarda uygun istifleme ve ergonomi ve elle taşıma eğitimi verilmelidir.', 'İŞ GÜVENLİĞİ UZMANI  \nDEPO ECZANE ARŞİV ÇALIŞANLARI', '3 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 1: DEPO ARŞİV', '1- Raflarda sivri köşelerin bulunması', '1- Yaralanma                  2- Çarpma', '1-Tüm çalışanlar\n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 10, 3, 90, 'C', '1-Tüm depo , eczane , arşiv alanlarında bulunan rafları köşelerindeki sivri uçlar için köşe koruyucular monte edilmelidir.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 1: DEPO ARŞİV', '1- Aydınlatma yetersizliği, bozulması, titremesi', '1- Görme bozukluklarının oluşması ve ilerlemesi, ş kazalarında artış', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 3, 7, 63, 'D', '1-Suni ışık ihtiyacında çalışma alanı ve diğer eklentiler, yollar en az 300 lüks şiddetinde aydınlatılmalıdır.                                                                                                                      2-Aydınlatma sistemleri sağlam yapıda olmalı, bozulan, yanmayan titreyen aydınlatmalar değiştirilmelidir.\n3-Periyodik göz muayeneleri yılda bir kez yapılmalıdır.', 'İŞVEREN V.                                  İŞYERİ HEKİMİ', '3 AY                              YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM 1: DEPO ARŞİV', '1- Termal konfor takibinin yapılmaması', '1- Dikkat kaybı, iş kazası ve meslek hastalıklarında artışlar', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', '1- Isı, nem ölçerler eczaneler ve arşivde mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Isı nem ölçerler eczane koridor alanlarında, depo alanları olarak tahsis edilmiş tüm yerlerde ve arşiv olarak tasarlanmış tüm yerlerde bulunmalı, ve mahale uygun ısı nem seviyesinde kalması sağlanmalıdır.                                                                   2- Çalışma ortamı %35-%75 nem oranında ve 18-24 C derece arasında olması sağlanmalıdır.                                                                                 \n3-Hava akım hızının 0,5 m/sn ortalamada olması sağlanmalıdır.\n4-Çalışma ortamının saatte en az 6-10 kez havalandırılması sağlanmalıdır..', 'İŞVEREN V.', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM 1: DEPO ARŞİV', '1-Elektrik panosunun su ile temas etmesi\n2- Pano önünde yalıtkan paspas olmaması', '1- Yangın                            2- Yanma                        3- Çarpılma', '1-Depo çalışanları', NULL, 1, 0, 3, 1, 15, 45, 'D', '1-Sığınak  depo olarak kullanılan alanda bulunan elektrik panosunun önüne yalıtkan paspas koyulmalıdır.                                                                                      \n 2- Üzerinde bulunan anahtar kilitlenerek yetkili personelde bulunması sağlanmalıdır.                                              \n3- Klimadan damlayan su nedenli elektrik ile teması önlenmelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 27, 'BÖLÜM 1: DEPO ARŞİV', '1- Yotasız dolapların bulunması', '1- Düşme                        2- Devrilme', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 1, 15, 45, 'D', '1-  Eczane ve tüm bölümleri , depo ve tüm bölümleri , arşiv ve tüm bölümlerindeki dolaplar, raflar vb. ekipmanlar en az iki noktadan yotalanmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 28, 'BÖLÜM 2: ECZANE', '1- Yanıcı kimyasal maddeler için ayrı bir depolama alanı bulunmaması', '1- Yagnın meydana gelmesi', '1-Tüm çalışanlar\n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Depo girişinde 50 kg\'lik yangın tüpü bulunmaktadır.', 1, 0, 6, 3, 15, 270, 'B', '1- Yanıcı maddeler için ayrıca bir depo oluşturulmalıdır.                                                                            2- Kimyasal maddeler yanıcı malzeme ve elektrik kaynaklarından uzakta depolanmalıdır.                                                                                                                     \n3- Depo girişine nötralizatör takılmalı, vücuttaki statik elektrik boşaltılmadan kimyasal madde deposuna girilmemelidir.\n4- Yanıcı kimyasal deposunda tüm metal raflar topraklanmalı, aydınlatma ve elektrik sistemleri exproof olmalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 29, 'BÖLÜM 2: ECZANE', '1- Kimyasal maddelerin yanlış depolanması\n2- Kimyasalların depo dışında depolanması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1- Depo, eczane çalışanları     \n2- Diğer ilgili çalışanlar', '1- Kimyasal madde deposu mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1- Kimyasal maddeler depolama matrisine göre depolanmalıdır.                                     2- Rafların altına tava ve emici malzemeler konulmalı, sızıntı, dökülme durumunda bu maddeler değiştirilmelidir.                                                                                                                3- Kimyasal depo zemini kolay temizlenebilir olmalıdır.                                                                                                                                                                                                                                                                                      4- Kimyasal maddelerin malzeme güvenlik bilgi formları depo girişine asılmalıdır.\n5- Kimyasal maddeler depolama alanlarında depolanmalı ve depolar kilitli tutulmalıdır.', 'İŞVEREN V.             DEPO ECZANE ARŞİV ÇALIŞANLARI', '2 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 30, 'BÖLÜM 2: ECZANE', '1- Kimyasal madde deposunda göz duşu ve döküntü kiti bulunmaması                                               2- Çalışanların kimyasallar hakkında bilgi sahibi olmaması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1- Depo, eczane çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 3, 15, 135, 'C', '1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         \n2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.  \n3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               \n4-Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.                              \n5- Çalışanlara MSDS ve kimyasalların güvenli kullanımı konusunda eğitimler verilmelidir.', 'İŞVEREN V.                                       İŞ GÜVENLİĞİ UZMANI', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 31, 'BÖLÜM 2: ECZANE', '1- Elektrikli ısıtıcı kullanılması', '1- Yangın çıkması', '1- Eczane,                          TPN ünitesi çalışanları', NULL, 1, 0, 3, 3, 15, 135, 'C', '1- Alanda elektrikli ısıtıcı kullanılmamalıdır.                             \n2-TPN ünitesinin termal konforu mevcut merkezi ısıtma ile sağlamalıdır.', 'FİRMA \nTPN ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 32, 'BÖLÜM 2: ECZANE', '1- Himss odasında bulunan sisnac makinasının operasyon bölgesinin açık olması', '1-El sıkışması sonucu yaralanma', '1-Eczane', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Sisnac makinesinin çalışanın elini sıkıştırmaması için press yapılan bölümüne switchli korucu kapak eklenmelidir.                                                                                       2- Cihaz bakım ve kalibrasyonları yapılmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 33, 'BÖLÜM 2: ECZANE', '1- Narkotik ilaç dolabının cam olması', '1- Narkotik ilaçların kullanımı sonucu bağımlılık sakatlık ya da ölüm', '1- YGAP eczane çalışanları', NULL, 1, 0, 3, 1, 40, 120, 'C', '1- Narkotik ilaçların bulunduğu dolaplar metal , kitlitlenebilir, çift anahtarlı olmalıdır.        \n2- Narkotik ilaç dolaplarının üzerinde anahtar bırakılmamalı, anahtarlar bölüm sorumlularına zimmetlenmelidir.                                                                                                                            3- Bölümlere gelen narkotik ilaçlar kayıt altına alınmalı, her vardiya değişiminde sayım yapılmalı, eksik çıkması durumunda yetkililere haber verilmelidir.', 'BİRİM SORUMLUSU', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 34, 'BÖLÜM 2: ECZANE', '1- Paslı yüzeylerin alanda mevcut olması', '1-Yaralanma sonucu tetanos hastalığına yakalanma', '1- Depo, eczane, arşiv, TPN çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 3, 7, 63, 'D', '1-Paslı alet ve ekipmanlar yenileriyle değiştirilmeli, paslanmaz malzemeler kullanılmalıdır.\n2-Sivri, delici, kesici, paslı makine ve ekipmanlara eldivensiz temas edilmemelidir.\n3-Yeni başlayan ya da aşısı eksik olan çalışanlara tetanos aşısı yapılmalı, 5 yılda bir ya da yaralanma durumunda tekrar aşı yapılmalıdır.', 'İŞVEREN V.           İŞYERİ HEKİMİ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 35, 'BÖLÜM 2: ECZANE', '1- Bekleme alanı olarak akü odalarının önlerinin kapatılması', '1-Acil durumda müdehale gecikmes               2- Yangın', '1-Eczane', NULL, 1, 0, 3, 6, 3, 54, 'D', '1-Bekleme alanı ; akü odası , çıkış kapıları vb. alanların önü kapatmayacak şekilde yeniden konumlandırılmalıdır.                                                                           2- Akü odası önü her zaman boş bırakılmalıdır.                          \n3- \"Malzeme istifi yapılmamalıdır \"şeklinde uyarı yazısı akü odası şaftlar ve bunun gibi teknik mahallere asılmalıdır.', 'ECZANE ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 36, 'BÖLÜM 2: ECZANE', '1- Yangın dolabı önüne istifleme yapılması ve elektrik panosunun önüne istifleme yapılması', '1-Yanma                 2-Yangın', '1- Depo, eczane çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 1, 15, 45, 'D', '1- Genel olarak eczane ve tüm bölümleri , depo ve tüm bölümleri , arşiv ve tüm bölümlerinde yangın dolapları önleri boş bulundurulmalıdır.                                                           2- Elektrik panoları önü boş kalacak şekilde iş organizasyonu yapılmalıdır.                                                                   3- Elektrik pano önleri boyanarak  istifleme yapılmayacağı vurgulanmalıdır.', 'DEPO ECZANE ARŞİV ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 37, 'BÖLÜM 2: ECZANE', '1- Eczane içinde bulunan himss odasında bulunan soğuk hava deposunda içerden acil durum butonu bulunmaması', '1-Mahsur kalma sonucu hipotermi geçirme', '1- Eczane çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 2, 7, 42, 'D', '1-Soğuk hava depolarında  kapı kolunun arızalanmasına karşı, içeriden açılabillir ilave acil kapı açma butonu takılmalıdır.                                                                                                                                                                                                   2- Acil kapı açma butonu ve alarm butonu erişilebilir yükseklikte olmalı ve önüne malzeme konulmamalıdır.                                                                                                                                           3- Acil kapı açma butonu ve alarm sistemi karanlıkta görülebilir şekilde işaretlenmiş olmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
