INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1- UV-C lambalarının koruyucusunun yetersiz olması \n2- UV-C lambasınıın sayaçsız olması', '1-Gözlerde katarakt, cilt yanıkları, mesleki kanserler oluşması', '1- Çalışanlar                                             2- Hastalar                                                3- Diğer ilgili kişiler', '1- UV-C lambasının alt kapağı mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1- UV-C lambaları zaman ayarlı, TS EN 62471 standartına uygun olmalıdır.  \n2- UV-C lambalarında alttan, üstten ve yandan ışık sızıntısı olmamalıdır.\n3- UV-C lambalarının yüzeyi yansıma yapmayacak şekilde olmalıdır.\n4-  UV-C lambalarının periyodik kontrolleri yapılmalı, sararan, çatlayan, filtre özelliği bozulan kapaklar değiştirilmelidir.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1- UV-C lambası çalışırken çalışanların odada bulunması\n2- Çalışanların uv lambası çalışırken çay kahve içmeleri', '1-Gözlerde katarakt, cilt yanıkları, mesleki kanserler oluşması', '1-Bronkoskopi çalışanları', '1- KKD\'ler mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1- UV Lambaları çalışanlar bölümdeyken çalıştırılmamalıdır.\n2- UV lambası çalışırken odanın kapısı kapalı tutulmalı, kapı açıldığında uv lambasının kapanmasını sağlayan interlock sistemi bulunmalıdır.\n4- UV lambasını kapatmak için odaya girildiğinde TS EN 170 standartında uv gözlük, uzun kollu koruyucu kıyafet, uv geçirmeyen eldiven vb. kişisel koruyucu ekipmanlar kullanılmalıdır.       \n5- Çalışanlar uv lambasının bulunduğu oda da kesinlikle çay kahve içmemelidir.', 'İŞVEREN V.  BRONKOSKOPİ  ÇALIŞANLARI', '2 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1- Mutfak alanıında çay kazanı ve uzatma kablosu kullanılması', '1-Elektrik çarpması sonucu yaralanma                      2-Yangın çıkması', '1- Tüm çalışanlar                                             2- Hasta ve hasta yakınları', '1-Kaçak akım koruma rolesi ve yangın rolesi mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Kullanılan tüm elektrik, uzatma (3\'lü) vb. kablolar halojen free (geç yanan, zehirli gaz çıkarmayan) özellikte olmalı, diğer uzatma kabloları kullanılmamalıdır.\n2- Çay kazanlarının kullanımı önlenmeli, sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.                                                                                                                         3- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.                                                                                                                4- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.', 'İŞVEREN V. ENDOSKOPİ BRONKOSKOPİ  ÇALIŞANLARI', '2 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1- Yıkama dezenfeksiyon cihaznın çalışırken kapağının açılması', '1. Kimyasal sıçraması ya da dönen kısımlara kapılma sonucu iş kazaları yaşanması', '1-Endoskopi bronkoskopi çalışanları', '1- Kişisel koruyucu ekipmanlar mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Yıkama dezenfeksiyon cihazı çalışırken kapağı açılmamalı, kapağa akım kesicili switch takılmalıdır.                                                   \n2- Cihaz durdurulmadan el ile müdahale edilmemelidir.            \n3- Operayon bölgesine el ve parmaklar yaklaştırılmamalıdır.\n4- Cihaz kapakları kapalı tutulmalıdır.', 'İŞVEREN V. ENDOSKOPİ BRONKOSKOPİ  ÇALIŞANLARI', '2 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1-Bulaşıcı hastalık riski olan hastalara bronkoskopi işlemi uygulanması', '1- TBC vb. bulaşıcı hastalıklara yakalanma', '1-Bronkoskopi çalışanları', '1- Kişisel koruyucu ekipmanlar mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Bronkoskopi işlem odaları negatif basınçlı olmalıdır.\n2- Bronkoskopi işlem odalarında kirli hava zeminden dışarı atılmalıdır.\n3- Odalarda hepa filtreler kullanılmalı, saatte en az 12 hava değişimi sağlanmalıdır.\n3- Çalışanlar N95 ya da TS EN 149 standrtdında FFP2 filtreli maske, yüz siperi, TS EN 455  standardında eldiven kullanmalıdır.', 'İŞVEREN V.  BRONKOSKOPİ  ÇALIŞANLARI', '2 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1- Dezenfeksiyon cihazı kullanılan bölümde döküntü kiti göz duşu bulunmaması', '1-Kimyasalların göze, cilde teması sonucu iş kazaları meyadana gelmesi', '1-Endoskopi bronkoskopi çalışanları', '1- Kişisel Koruyucu ekipmanlar mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         \n2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.  \n3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               \n4- Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.                              \n5- Çalışanlara MSDS ve kimyasalların güvenli kullanımı konusunda eğitimler verilmelidir.', 'İŞVEREN V.\nİŞ GÜVENLİĞİ UZMANI', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1- Endoskopi ve Bronkoskopi cihazlarının kullanımından kaynaklı kan ve vücut sıvılarının çalışanlara teması', '1- Enfeksiyona yakalanma', '1-Endoskopi bronkoskopi çalışanları', '1-Kişisel Koruyucu ekipmanlar mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Çalışanlar TS EN 455  standardında eldiven, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında maske vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.', 'İŞYERİ HEKİMİ  ENDOSKOPİ BRONKOSKOPİ  ÇALIŞANLARI', 'MARUZİYET OLMASI DURUMUNDA    HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1- Endoskopi cihazı hortum ve bağlantı yerlerinde sızıntı olması', '1- Elektrik çarpması sonucu yaralanma', '1-Endoskopi bronkoskopi çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Endoskopi cihazının hortum ve bağlantı yerleri sağlam olmalı, sızıntı olmamalıdır.\n2- Endoskopi cihazı her kullanımdan önce kontrol edilmelidir.\n3- Elektrik kablolarında ek, deformasyon bulunmamalı, elektrik kabloları çift izolasyonlu olmalıdır.\n4- Makine yıkama işlemi tamamlandığında fişte bırakılmamalıdır.', 'BİRİM SORUMLUSU ENDOSKOPİ BRONKOSKOPİ  ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1-Hastalardan inhalasyon yoluyla bulaş', '1-Enfeksiyon, bulaşıcı hastalıklara yakalanma', '1-Endoskopi bronkoskopi çalışanları', '1-Ortam havalandırması mevcuttur.                    2. Kişisel koruyucu ekipmanlar mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Bulaşıcı hastalık şüphesi olan hastalar, sonuçları çıkana kadar tek kişilik izolasyon odalarında tutulmalıdır.                                                                                           2- Şüpheli hastaların bulunduğu alanın teması bittikten sonra hemen dezenfekte edilmelidir.                                                                                                                          3- Bulaşıcı hastalıkların yayılma ihtimali yüksek olan bölümlerde hepa filtreler kullanılmalıdır.                                                                                                                                              4-Tanı konulmuş hastalar negatif basınçlı odalara alınarak izole edilmelidir.                                                                                                                        5-Çalışanlar N95 ya da TS EN 149 standrtdında FFP2 filtreli maske, yüz siperi, TS EN 455  standardında eldiven kullanmalıdır.', 'BİRİM SORUMLUSU ENDOSKOPİ BRONKOSKOPİ  ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1- Kesici delici aletlerin emniyetsiz kullanılması', '1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma', '1-Endoskopi bronkoskopi çalışanları', '1-Kesici aletller düzenli muhafaza edilmektedir.', 1, 0, 3, 6, 7, 126, 'C', '1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                                 3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                                                                                                5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.', 'ENDOSKOPİ BRONKOSKOPİ  ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1- Formaldehitin uygunsuz kullanılması', '1- Kimyasal maddelere maruziyet sonucu iş kazaları meydana gelmesi, meslek hastalıkları', '1-Endoskopi bronkoskopi çalışanları', '1. Kişisel koruyucu ekipmanlar mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1- 21.10.2025 tarihinde hazırlanan Yöntem Beyan\'ına göre firma tarafından formaldehit, patoloji laboratuvarında porsiyonlanarak gönderilmelidir\n2- Formaldehit büyük kaplardan, küçük kaplara aktarılırken taşma kapları kullanılmalı, zemine dökülmesi önlenmelidir.\n3- Formaldehit dökülmesine karşı döküntü kitleri temin edilmelidir.\n4- Çalışanlar formaldehit ile çalışma esnasında EN 149 standardında ffp3 maske, eldiven ve koruyucu gözlük kullanmalıdır.', 'İŞVEREN V. ENDOSKOPİ BRONKOSKOPİ  ÇALIŞANLARI', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1- Endoskopi 1 odasının fotoselli kapısı açıldığında yangın dolabının açılmasını  engellemesi', '1- Yangına müdehale edilememesi sonucu durumun şiddetinin artması', '1-Endoskopi bronkoskopi çalışanları\n2- Hasta ve hasta yakınları', '1- Yangın algılama ve ihbar sistemi mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1- Fotoselli kapının açılış yönü yangın dolabını kapatmayacak şekilde ayarlanmalıdır. \n2- Yangın dolaplarının önü her zaman boş bırakılmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1- Endoskopi kule sisteminin gövde topraklama ölçümünün yapılmaması   \n2- Kulenin devrilmesi', '1- Elektrik çarpması.                 2- Devrilme sonucu yaralanma', '1-Endoskopi bronkoskopi çalışanları', '1-Topraklama sistemi mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1- Endoskopi kulesinin gövde topraklama ölçümleri yapılmalıdır.\n2- Cihaz kabloları çift izolasyonlu olmalıdır.\n3- Kule tekerlek frenleri sağlam olmalı, sabit konumdayken kilitli tutulmalıdır.                                                                                                      \n4- Ağır cihazlar alt raflara, hafif cihazlar üst raflara konulmalıdır.', 'İŞVEREN V. ENDOSKOPİ BRONKOSKOPİ  ÇALIŞANLARI', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1-Cihazlardan zemine sıvı dökülmesi', '1- Kayma, düşme sonucu yaralanma', '1- Çalışanlar                                             2- Hastalar                                                3- Diğer ilgili kişiler', '1-Kaygan zemin işaretleme levhaları mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1- Zemine dökülen sıvılar bekletilmemeli, hemen temizlenmesi sağlanmaldır.\n2- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.                                                                                                     3- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\n4-  Çalışanlar kaymaz tabanlı ayakkabı giymelidir.', 'TEMİZLİK ÇALIŞANLARI ENDOSKOPİ BRONKOSKOPİ  ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1-Pano odasındaki sprink kapakları sökülmemesi                                  2-Endoskopi  3 odasındaki tavanda bulunan yangın sprink sisteminin bantla kapatılmış olması', '1- Yangının söndürülememesi sonucunda şiddetin artması', '1- Çalışanlar                                             2- Hastalar                                                3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1- Pano odasındaki yangın sprink sistemini kapatan kapak sökülmeli cihaz aktif hale getirilmelidir.                                                                                                                       2- Endoskopi 3 odasındaki yaıngın sprink sisteminin üzerindeki bant kaldırılmalı ve aktif çalışması sağlanmalıdır.\n3- Yangın algılama ihbar sistemlerinin her zaman çalışır durumda olması sağlnamalıdır.', 'BİRİM SORUMLUSU ENDOSKOPİ BRONKOSKOPİ  ÇALIŞANLARI', '1 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1-Dolap ve rafların düzenlenmemesi ve sabitlenmemesi', '1- Malzemelerin devrilmesi sonucu yaralanma', '1-Endoskopi bronkoskopi çalışanları', '1-Dolapların bir  çoğu sabitlenmiştir.', 1, 0, 3, 3, 7, 63, 'D', '1-Sabitlenmemiş doalp ve raflar en az iki noktadan sabitlenmelidir.\n2-Düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.\n3-Ağır malzeme ve ekipmanlar yüksek istiflenmemelidir.                                            4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.', 'İŞVEREN V. ENDOSKOPİ BRONKOSKOPİ  ÇALIŞANLARI', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1- Yıkama dezenfeksiyon cihazına kimyasalların aktarımı sırasında dökülmesi', '1- Kimyasalların göze, cilde teması sonucu iş kazaları meyadana gelmesi', '1-Endoskopi bronkoskopi çalışanları', '1- Kişisel koruyucu ekipmanlar mevcuttur.', 1, 0, 6, 3, 3, 54, 'D', '1- Yıkama dezenfeksiyon cihazına el ile kimyasal aktarımı yapılmamalı, otomatik dozajlama sistemi kurulmalıdır.\n2- Kimyasal aktarımı yapılırken sıçrama ve döküntü olmamasına özen gösterilmelidir.\n3- Aktarım yapılırken kimyasal dayanımlı eldiven, Su geçirmez önlük+ kolluk, FFP2/N95 maske, Gözlük ve yüz siperliği((ref. EN 166 standardı)   ve kaymaz tabanlı ayakkabı kullanılmalıdır.', 'ENDOSKOPİ BRONKOSKOPİ  ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: ENDOSKOPİ - BRONKOSKOPİ', '1- Basınçlı hava tabancasının hortumun da hasar olması\n2- Hava tabancasının vücuda tutulması', '1- Basınçlı havaya temas sonucu yaralanma', '1-Endoskopi bronkoskopi çalışanları', NULL, 1, 0, 3, 2, 7, 42, 'D', '1- Basınçlı hava tabacasının hortumu ve bağlantı yerleri sağlam olmalı kaçak olmamalıdır.\n2- Basınçlı hava tabancası ekipmanların temizliği dışında kullanılmamalıdır.\n3- Hava tabancaları vücuda tutulmamalıdır.', 'ENDOSKOPİ BRONKOSKOPİ  ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Davlumbaz ve bacalarda yağ birikmesi', '1- Yağ birikimi nedeniyle yangın meydana gelmesi', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Bir çok işletmede davlumbaz ve bacalarda otomatik söndürme sistemi bulunmaktadır.', 1, 0, 6, 3, 15, 270, 'B', '1- Ticari işletmelerde yemek pişen mutfaklarda davlumbazlarda otomatik yangın söndürme sistemleri kurulmalıdır.\n2- Davlumbazlarda yağ ve kir birikimi olmayacak şekilde  davlumbazlar  günlük temizlenerek yağ ve benzeri yanmaya sebep olabilecek maddelerin birikmesi önlenmelidir.  \n3-  Pişirme alanlarında yangın battaniyesi ve K sınıfı yangın söndürücü bulundurulmalıdır.\n4- Ayda en az bir kez davlumbazlar ve bacaları detaylı temizlenmelidir.', 'TİCARİ İŞLETMELER', '2 AY\n\nBACA TEMİZLİĞİ \nAYDA 1', 6, 3, 15, 270, 'B', 'acik', 'Ticari işletmelerde Davlumbazlarda otomatik yangın söndürme sistemleri kurulmştur.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Eletkrik tesisatının, topraklamaların, kaçak akım rölelerinin periyodik kontrollerinin yapılmaması', '1- Elektrik çarpması sonucu ya da elektrik yangını sonucu yaralanma', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 6, 3, 15, 270, 'B', '1- Elektrik tesisatının, topraklamaların, kaçak akım rölelerinin, yangın rölelerinin periyodik kontrolleri TS EN 60079 serisi, TS HD 60364-4 serisi, TS HD 60364-5 Serisi, TS HD 60364-6 standartlarına uygun olarak en geç yılda bir kez yapılmalıdır.\n2- Tüm bakım ve kontroller kayıt altına alınmalıdır.', 'TİCARİ İŞLETMELER', '2 AY', 6, 3, 15, 270, 'B', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: TİCARİ ALANLAR', '1-Yangın söndürme ekipmanlarının periyodik kontrollerinin yapılmaması', '1- Yangın durumunda müdahale edilememesi sonucu şiddetin artması', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Yangın söndürme tüpleri mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1- İtfaiye raporu alınmalıdır. \n2- Ticari işletmelerde yangın söndürme ekipmanlarının aylık kontrolleri yapılmalıdır.\n3- En geç yılda bir kez TS EN 11602 standartına göre periyodik kontrolleri yapılmalıdır.\n4- Yanıgın dolaplarının periyodik kontrolü yangın dolaplarının ve hortum makara sistemlerinin TS EN 671-3 standartına göre en geç yılda bir kez yapılmalıdır.\n5- 4 yılda bir hidrostatik basınç testi yapılmalı, içindeki malzeme değiştirilmelidir.\n6- Yangın teçhizatlarının her an göreve hazır bulunması sağlanmalıdır.', 'TİCARİ İŞLETMELER', '2 AY', 6, 3, 15, 270, 'B', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: TİCARİ ALANLAR', '1-Ticari işletmelerin iş güvenliği önlemlerini almamaları', '1-İş kazaları yaşanması sonucunda yaralanma', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 6, 3, 15, 270, 'B', '1- Ticari işletmelerin bu risk değerlendirmesinde yazan bütün tedbirleri  almaları sağlanmalıdır.\n2- Ticari işletmeler tüm iş ekipmanlarının periyodik kontrollerini yaptırılmalı ve belgelendirmelidir.\n3- Ticari işletmeler, çalışanlarına tehlike sınıfına uygun sürelerde iş güvenliği eğitimi aldırmalı, periyodik sağlık muayenelerini yaptırmalı, sigortasız işçi çalıştırmamalıdır.\n4- Ticari işletmelerin hastanede ki iş güvenliği kurallarına uymaları sağlanmalıdır.\n5- Ticari işletmelerin gerekli tedbirleri alıp almadıkları sürekli olarak kontrol edilmeli, denetimler yapılmalıdır.', 'FİRMA\nİŞVEREN V.', 'RİSK DEĞERLENDİRME RAPORUNDA BELİRLENEN TERMİN SÜRELERİNDE', 6, 3, 15, 270, 'B', 'acik', 'Firma bünyesinde İGU görevlendirmesi yapılmıştır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Elektrikli mutfak ekipmanlarının kablolarının hasarlı ekli olması', '1- Elektrik çarpması sonucu yaralanma\n2- Yangın çıkması', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1-Elektrik kablolarında yırtık, izolasyon bozlukluğu vb. olmamalı, olan kablolar kullanılmamalı değiştirilmelidir.                          \n2- Elektrik kabloları ağır malzeme ya da ekipmanların altına konulmamalı, kabloların ezilmesi önlenmelidir.                                           \n3- Kablolarda olan izolasyon açıklıkları izole bant ile kapatılmamalı, ekli kablolar değiştirilmelidir.  \n4- Kaçak akım röleleleri her zaman çalışır durumda olmalıdır.', 'TİCARİ İŞLETMELER', '2 AY', 6, 3, 15, 270, 'B', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Acil çıkış yollarının, kapılarınınve yönledirmelerinin  malzemeler ile kapatılması\n2- Yönlendirme işaretlerinin yetersiz olması', '1-Acil durumlarda hızlı tahliyenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması', '1- Çalışanlar                                2- Hastalar ve hasta yakınları        3- Diğer ilgili kişiler', NULL, 1, 0, 6, 3, 15, 270, 'B', '1-Acil çıkış kapıları ve acil çıkış yolları açıkça görülebilir olmalı ve acil çıkış kapılarnın ve yollarının önüne ve üzerine malzeme vb. konulmamalıdır.                                                                                        2- Acil çıkış yönlendirmelerinin önleri kapatılmamalı, kaçış yolu üzerinde bütün erişim noktalarından görülebilir olmalı, yönlendirmeler 200-240 cm yüksekliğe asılı olmalıdır.                                                                          \n3- Acil çıkış yollarında en az 150 cm genişliğinde mesafe olması sağlanmalıdır.', 'TİCARİ İŞLETMELER', '2 AY', 6, 3, 15, 270, 'B', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Halojen free olmayan uzatma kabloları kullanılması', '1- Elektrik çarpması\n2- Yangın meydana gelmesi', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Ana tesisat kabloları halojen free kablolar ile değiştirilmiştir.', 1, 0, 6, 3, 15, 270, 'B', '1- Ticari işletmelerde kullanılan tüm elektrik, uzatma (3\'lü) vb. kablolar halojen free (geç yanan, zehirli gaz çıkarmayan) özellikte olmalıdır.                                                                                                                                                           2- Halojen free olmayan uzatma kablolaları kesinlikle kullanılmamalıdır.', 'TİCARİ İŞLETMELER', '3 AY', 6, 3, 15, 270, 'B', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: TİCARİ ALANLAR', '1-Ocaklarda açık alev kullanılması', '1- Yangın çıkması', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 6, 15, 270, 'B', '1- Ocak etrafında herhangi yanıcı bir madde bulundurulmamalıdır.                                                                             2- Günlük temizlik yapılarak yağ ve benzeri yanmaya sebep olabilecek maddelerin birikmesi önlenmelidir.                                                                                                                                              3- Açık aleve fazla yaklaşılmadan çalışılmalı, elbise tutuşma ihtimali göz önünde bulundurulmalıdır.                                                                                                                                           4- Gaz detektörlerin bakım ve kontrolleri yapılmalıdır.', 'TİCARİ İŞLETMELER', 'HERGÜN', 3, 6, 15, 270, 'B', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Elektrik kabloların da aşırı yükleme olması', '1- Elektrik yangını çıkması sonucu, yaralanma', '1- Çalışanlar                                2- Hastalar ve hasta yakınları        3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1- 3 lü uzatma kablolarına, 3 lü uzatma kablosu kullanarak kullanılmamalıdır.                                                                                                     2- Yüsek akım çeken cihazların (fırın, ızgara fritöz  vb.) beslemesi ayrı fişlerden yapılmalı, uzatma kabloları kullanılmamalıdır.    \n3- Kullanılmayan cihazlar fişten çıkarılmalıdır.', 'TİCARİ İŞLETMELER', '3 AY', 6, 3, 15, 270, 'B', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Otomatların sabitlenmemiş olması', '1- Otomatların devrilmesi sonucu ezilme, yaralanma', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Otomatlar, duvar kenarına yanaştırılmalı ve en az iki noktadan duvara ya da zemine  sabitlenmelidir.\n2- Kullanıcıların otomatlara asılmasını ya da çekmesi önlenmeli, uyarı levhaları asılmalıdır.\n3- Otomatlar düz ve sağlam zeminlere yerleştirilmelidir.', 'TİCARİ İŞLETMELER', '3 AY', 6, 6, 7, 252, 'B', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Doğalgaz vanalarında ya da borularında gaz kaçağı olması', '1- Parlama, patlama yangın meydana gelmesi', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Gaz dedektörleri mevcuttur.', 1, 0, 3, 2, 40, 240, 'B', '1- Gaz kaçak alarm sistemi, elektromanyetik gaz vanasına bağlı olmalı, kaçak durumunda gazı otomatik olarak kesmelidir.\n2- Fırın vb. ekipmanlarda esnek gaz hortumları kullanılmamalı, besleme çelik boru ile yapılmalıdır.\n3- Her gazlı cihazın kendine özel gaz vanası olmalıdır.\n4- Manuel kapatma vanaları kolay erişilebilir olmalı ve işaretlenmelidir.\n5- Gaz vanalarının önleri her zaman açık bulundurulmalı, malzeme vb. konulmamalıdır.\n6- Her mesai sonrası gaz vanaları kapatılmalıdır.', 'TİCARİ İŞLETMELER', 'HERGÜN', 3, 2, 40, 240, 'B', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Doğalgaz tesisatının, gaz dedektörlerinin vb. sistemlerin periyodik kontrollerinin yapılmaması', '1- Parlama, patlama yangın meydana gelmesi', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Gaz dedektörleri mevcuttur.', 1, 0, 3, 2, 40, 240, 'B', '1- Doğalgaz tesisatının en geç yılda bir kez periyodik kontrolü yaptırılmalıdır.\n3- Kaynaklı gaz borularına penatran testi ile sızdırmazlık kontrolleri yaptırılmalıdır.\n3- Gaz dedektörlerinin ve otomatik gaz kesicilerin periyodik kontrolleri yaptırılmalıdır.', 'TİCARİ İŞLETMELER', 'PERİYODİK KONTROL \nYILDA 1', 3, 2, 40, 240, 'B', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Yangın söndürme cihazları yerlerinin uygun olmaması, malzemelerle kapatılması ve erişimin zor olması', '1- Yangının büyümesi sonucu şiddetin artması', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- İşletmelerde taşınabilir yangın Ttüpleri Ve dolapları mevcuttur.', 1, 0, 3, 2, 40, 240, 'B', '1- Yangın söndürme tüplerinin önüne malzeme istifi yapılmamalı, boş bırakılmalıdır.\n2- Portatif yangın söndürücüler yerden 90 cm yüksekliğe asılmalıdır.\n3- Yangınla mücadele uyarı işaretleri kalıcı şekilde yerleştirilmelidir.\n4- Düzenli aralıklarla yangın tüplerinin kontrolü, bakımı ve dolumu yapılmalıdır.', 'TİCARİ İŞLETMELER', '3 AY', 3, 2, 40, 240, 'B', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: TİCARİ ALANLAR', '1-Gıda maddelerinin ve yemeklerin uygunsuz şartlarda muhafazası, bekletilmesi', '1- Gıda Zehirlenmesi', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Şahit numuneler saklanmaktadır.', 1, 0, 6, 2, 15, 180, 'C', '1-Bozulma riski yüksek olan gıda maddeleri (tavuk et vb.), soğuk hava depolarında muhafaza edilmeli, dış alanda fazla bekletilmemelidir.                                                                                                            \n2-Son kullanma tarihi geçmiş, ambalajı okunmayan, yırtılmış, bombeleşmiş, gözle kontrol edildiğinde hatası bulunan,   etiketsiz, imal ve son kullanma tarihi bulunmayan, etiketi üzerinde ithalat veya üretim izin tarih ve sayısı bulunmayan gıda maddeleri imha edilmeli, kullanılmamalıdır.                                                                                           \n3-Gıda maddeleri kontrol edilmeden kullanılmamalıdır.', 'TİCARİ İŞLETMELER', 'HERGÜN', 6, 2, 15, 180, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Kullanılmış kızartma yağlarının tekrar kullanılması', '1- Gıda zehirlenmesi', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 6, 2, 15, 180, 'C', '1-  Yağ kızartma sıcaklığı 170-180 dereceyi aşmamalıdır.\n2- Dijital termometre ile yağ sıcaklığı kontrol edilmelidir.\n3- Yağlarda renk koyulaşması, köpürme ve koku değişimi olduğunda yağ kesinlikle kullanılmamalı, değiştirilmelidir.\n4- Farklı ürün gruplarına, farklı yağlar kullanılmalıdır.\n5- Fritöz vb. kızartma yapılan ekipmanlar günlük olarak temizlenmeli, temizlikten sonra deterjan kalıntısı kalmamalıdır.', 'TİCARİ İŞLETMELER', 'HERGÜN', 6, 2, 15, 180, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Ticari işletmelerde kontrolsüz tütün vb. kullanılması', '1- Yangın çıkması', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Kapalı alanarda sigara içilmemektedir.', 1, 0, 6, 2, 15, 180, 'C', '1- Kapalı alanlarda kesinlikle sigara içilmesine izin verilmemelidir.\n2- Küllükler çöp kutularına boşaltılırken yanan izmarit olmamasına özen gösterilmeli, küllük içine su dökülmelidir.\n3- Metal ve kapaklı küllükler kullanılmalıdır.\n4- Dış alanlarda Söndürmatik vb. yanmaz dış mekan küllükleri kullanılmalıdır.\n5- Yangın söndürücüler her zaman hazır durumda bulundurulmalıdır.', 'TİCARİ İŞLETMELER', '3 AY', 6, 2, 15, 180, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Elektrik panolarının,  malzeme ya da istifle kapatılmış olması', '1- Acil durumlarda  müdahale sağlanamaması sonucunda  şiddetin artması', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Pano önleri kapanmayacak şekilde bir iş organizasyonu yapılmalıdır.\n2- Malzeme ya da istiflerin pano önlerini kapatmaması sağlanmalıdır.\n3- Panolara erişim için en az 80 cm genişlikte ulaşım yolları sağlanmalıdır.\n4- Pano üzerlerine uyarı etiket ve işaretleri asılmalıdır.', 'TİCARİ İŞLETMELER', '3 AY', 3, 3, 15, 135, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Elektrik panoların kilitsiz olması\n2- Uyarı levhası olmaması\n3- Pano önlerinde yalıtkan paspas olmaması', '1- Elektrik çarpması sonucu yaralanma', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Elektrik panoları sürekli kilitli bulundurulmalıdır.\n2- Pano etrafındaki elektrik kabloları kablo kanalı içerisine alınmalıdır.\n3- Pano altlarına eksik olanlara yalıtkan paspas yerleştirilmelidir.\n4- Panolara yetkisiz kişilerin erişimi engellenmelidir.', 'TİCARİ İŞLETMELER', '3 AY', 3, 3, 15, 135, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Ticari işletmelerde bulunan dolap, raf ve portatif rafların sabitlenmemesi', '1-Devrilme, düşme ya da çarpma sonucunda  yaralanma', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Bir çok raf sabitlenmiştir.', 1, 0, 3, 3, 15, 135, 'C', '1-Sabitlenmemiş dolap ve raflar en az iki noktadan duvar, tavan ya da tabandan sabitlenmelidir.\n2- Portatif rafların ayak frenleri bulunmalı ve kapalı tutlmalıdır.\n3-Ağır malzeme ve ekipmanlar yüksek istiflenmemelidir.        \n4- Portatif raflar çıkışları engellemeyecek şekilde konumlandırılmalıdır.', 'TİCARİ İŞLETMELER', '3 AY', 3, 3, 15, 135, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: TİCARİ ALANLAR', '1-Yemek yapılan ve dağıtılan alanların kirli olması, yağ birikimi olması', '1-Enfeksiyon hastalıklarına yakalanma', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 15, 135, 'C', '1-Paslanmaz tezhgahlar, benmariler ve kullanılan aletler günlük olarak temizlenmelidir.                                                                                                                                                     2-Zemin günlük olarak düzenli temizlenmeli , duvar yüzeyleri haftalık olarak düzenli  temizlenmeli  ve  asma tavan aylık olarak  düzenli temizlenmelidir.', 'TİCARİ İŞLETMELER', 'HERGÜN', 3, 3, 15, 135, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Kola, içecek, lpg vb. basınçlı tüplerin uygun depolanmaması', '1- Fiziksel patlama sonucu yaralanma', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 15, 135, 'C', '1- Basınçlı tüpler için depolama alanı yapılmalı, çıkış yol ve güzergahlarına tüpler bırakılmamalıdır.\n2- Dolu ve boş tüpler için ayrı depolar yapılmalıdır.\n3- Tüpler ısı kaynaklarından ve güneşin etkisinden uzak tutulmalıdı\n4- Basınçlı tüpler zeminde sabitlenmeden bırakılmamalı, sabitleme aparatlarına takılmalı ve 2 noktadan zincir ya da halatla bağlanmalıdır.', 'TİCARİ İŞLETMELER', '3 AY', 3, 3, 15, 135, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 1: TİCARİ ALANLAR', '1-Yemek pişiren dağıtan çalışanların   sağlık kontrollerinin yapılmamış olması', '1- Bulaşıcı hastalıklar ve salgın hastalıkların diğer çalışanlara bulaştırma', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-Yemek pişiren dağıtan çalışanların 6 ayda 1 portör muayeneleri yapılmalıdır.\n2- Hepatit taramaları ve akciğer grafileri yılda bir tekrarlanmalıdır.   \n3- Bölüme yeni başlayan çalışanlar sağlık taramaları yapılmadan işe başlatılmamalıdır.                                                                                                                                                                                                           4-Sonucu uygun olmayanlar çalışanlar yemek pişirme, dağıtma bölümünde çalıştırılmamalıdır.', 'TİCARİ İŞLETMELER', '6 AYDA 1', 3, 6, 7, 126, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Ticari işletmeler totem ve reklam pamolarının fırtına, şiddetli rüzgarda devrilmesi', '1- Totemlerin ya da reklam panolarının devrilmesi sonucu yaralanma', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 1, 3, 40, 120, 'C', '1-Totemlerin taşıyıcı sistemlerinin şiddetli rüzgar deprem vb. yüklerine karşı taşıma kapasitesinin yeterli olup olmadığı statik uygunluk kontrolü yetkili inşaat mühendislerine yaptırılmalıdır. \n2-Totemler düzenli aralıklarlar ile korozyon, pas oluşumu, ankraj noktalarında çatlak ve bağlantı gevşemesine karşı kontrol edilmeli, Totemlerin korozyon ve paslanmış kısımları boyanmalı, çatlak ve bağlantı gevşemesi olan yerler onarılmalıdır.                                                                                                                                                                                                                                                                                \n3-Şiddetli rüzgâr, fırtına anında açık alanlarda hizmet verilmemelidir.', 'TİCARİ İŞLETMELER', 'ŞİDDETLİ RÜZGAR FIRTINA ESANASINDA \nSÜREKLİ', 1, 3, 40, 120, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Dış ticari işletme alanları faraday kafesinin periyodik kontrollerinin yapılmaması', '1-Yıldırım düşmesi sonucunda yaralanma, yangın', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 2, 15, 90, 'C', '1-Paratoner tesisatının periyodik kontrolleri TS EN 62305 standardına göre yılda en az 1 kez tekrarlanmalı ve belgelendirilmeldir.                                                                                                     2-Faraday kafesi içinde, civatalarda ve Franklin çubuklarında paslı ve korozyonlu alan bulunmamalıdır.                                                                                                                                                       3- Paratoner topraklaması bina topraklaması ile eşpotansiyel olmalıdır.                                                                                                                  4-Topraklama tesisinin direnci en fazla 10 ohm olmalıdır.', 'TİCARİ İŞLETMELER', 'YILDA 1', 3, 2, 15, 90, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Atık yağların uygunsuz muhafaza edilmesi', '1- Yangın çıkması', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 2, 15, 90, 'C', '1- Atık yağlar gıda hazırlama alanından ayrı tutulmalıdır.\n2- Atık yağlar kapalı sızdırmaz varillerde muhafaza edilmelidir.\n3- Kaplar üzerinde “ATIK YAĞ” etiketi bulunmalıdır.\n4- Dökülme durumunda hemen temizlenmeldir.\n5- Atık yağlar kesinlikle tekarar kullanılmamalıdır.', 'TİCARİ İŞLETMELER', 'HERGÜN', 3, 2, 15, 90, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Elektrik kablolarının, priz vb. elektrik sistemlerinin su ya da sıcak maddeler ile temas etmesi', '1- Kısa devre ve elektrik arkı\nsonucu elektrik yangınları meydana gelmesi', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1- Elektrik kabloları çift izolasyonlu olmalı, kullanılan fiş priz aydınlatma sistemleri etanj özellikte olmalıdır.\n2- Elektrik kablolarının, priz vb. elektrik sistemlerinin su, nem, buhar ve sıcak malzemelere teması önlenmelidir.\n3- Cihazların elektrik kablolarında izole bant ile bantlanmış ekler olmamalıdır.                                                                                                                          4- Kaçak akım röleleri aktif olmalıdır.', 'TİCARİ İŞLETMELER', '3 AY', 3, 2, 15, 90, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 27, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Ticari Alanlarda Sözel ve Fiziksel Saldırı (Beyaz kod)', '1- Beyaz kod gibi Acil durumlara müdahalenin gecikmesi', '1- Çalışanlar', '1-  Hastanede Beyazkod (1111) sistemi bulunmaktadır.', 1, 0, 3, 2, 15, 90, 'C', '1-  Ticari alanlarda Acil Durumlar ile ilgili prosedür ve talimatlar hazırlanmalı\n2-  Ticari Alanlarında Meydana Gelebilecek sözel ve fiziksel şiddet durumlarında çağrı başlatılabilecek ve Güvenlik Müdahalelerinde Koordinasyon Sorunlarını ortadan kaldıracak sistem kurulmalıdır.\n3- Dış beyazkod ihbar sistemi iletişim numaraları görünür şekilde asılı olmalıdır.', 'İŞVEREN V.', '3 AY', 3, 2, 15, 90, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 28, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Otomatlarda uzatma kabloları kullanılması\n2- Elektrik kablolarının açıkta olması', 'Elektrik Çarpması\nYangın Riski', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1- Otomatlarda uzatma kabloları kullanılmamalı, elektrik beslemesi prizlerden yapılmalıdır.\n2- Otomat elektrik kabloları otomat altında kalmamalı, ezilmesi önlenmelidir.\n3- Otomat elektrik kablolarıında yırtık, ek, deformasyon vb. bulunmamalı, kablolar çift izolasyonlu olmalıdır.\n4- Otomat elektrik kabloları çalışan, hasta, çocuk vb. temas edemeyecek şekilde kapatılmalıdır.', 'TİCARİ İŞLETMELER', '3 AY', 3, 2, 15, 90, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 29, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Ticari işletmelerin evsel atık alanlarının uygun olmaması', '1- Enfeksiyon\n2- Haşere üremesi\n3- Kötü koku', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1-Evsel Atık Alanının da açık çöp konteynerleri mevcuttur.', 1, 0, 6, 2, 7, 84, 'C', '1-  Ortak atık alanında kapalı, havalandırmalı ve yanmaz malzemeden yapılmış  etiketli konteynerler kullanılmalıdır.\n2- Atıklar sadece atık kutularına atılmalı, zemine dökülmesi önlemelidir.\n3- Zemine dökülen atıklar bekletilmemeli, hemen temizlenmelidir.\n4-  Atık alanları ve konteynerleri (Evsel organik, geri dönüşüm, tehlikeli atık vb.) ayrılmalı, konteynır kapıları kapalı tutulmalıdır.\n5-  Atık alanı yakınında 50 kg\'lik kuru kimyevi tozlu yangın söndürücü bulunmalıdır.\n6-  Haşerelere karşı ilaçlama yapılmalıdır.', 'FİRMA', '3 AY', 6, 2, 7, 84, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 30, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Kaygan, ıslak ve bozuk zemin', '1-Düşme, denge kaybı sonucunda vücut bölümlerinin yaralanması', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1-  Alan genelinde ıslak ve bozuk zemin bulunmamaktadır. \n2-  Sulu temizlik yapılmamaktadır.', 1, 0, 6, 2, 7, 84, 'C', '1- Bozulan zeminin tamir ve tadilatı yapılmalıdır.\n2- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.                                                                                                     3- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\n4- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.', 'TİCARİ İŞLETMELER', 'HERGÜN', 6, 2, 7, 84, 'C', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 31, 'BÖLÜM 1: TİCARİ ALANLAR', '1-Yemek pişiren dağıtan çalışanların önlük, bone maske kullanmaması', '1-Enfeksiyon hastalıklarına yakalanma', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 7, 63, 'D', '1-Yemek pişiren dağıtan çalışanlar iş kıyafetini ve ayakkabı/terliğini sadece çalışma alanında kullanmalı, bu ekipmanlar ile çalışma alanı dışına çıkılmamalıdır.                                                                                                                                                  2- Yemek pişiren dağıtan çalışanlar önlük bone ve eldiven kullanmadan çalışmamalıdır.', 'TİCARİ İŞLETMELER', 'HERGÜN', 3, 3, 7, 63, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 32, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Ticari işletmelerde kullanılan otomatik kapıların fotosel tertibatının olmaması', '1-Kapının düşmesi sonucu vücut bölümlerinin ezilmesi, yaralanma', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 6, 3, 3, 54, 'D', '1- Otomatik kapı ve kepenklerde,  altından çalışan geçerken çalışmasını durduracak şekilde fotosel tertibatı yaptırılmalıdır. \n2- Kapı indirilip kaldırılırken 1 metreden yakın içeride ve dışarıda hiç kimse bulunmamalıdır.\n3-  Kapı ve kepenklerin üzerinde veya görülebilir bir alanda uyarı işaretleri bulunmalıdır.\n4-  Motor, fren, sensör ve kontrol panelleri periyodik olarak test edilmelidir.', 'TİCARİ İŞLETMELER', '3 AY', 6, 3, 3, 54, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 33, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Depolama alanlarında kimyasal ve gıda maddelerinin birlikte depolanması', '1- Yangın riski\n2- Gıda/kuru malzeme kontaminasyonu', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 6, 1, 7, 42, 'D', '1-  Gıdalar maddleri ile kimyasallar, yanıcı malzemeler (Ambalaj,karton vb atıklar) ayrı alanlarda depolanmalıdır.\n2-  Yanıcı kimyasallar ısı,  elektrik, kıvılcım kaynaklarından uzakta depolanmlaıdır. \n3-  Acil çıkış yolları açık tutulmalıdır.\n4-  Depolarda yangın söndürücüler hazırda bulundurulmalıdır.', 'TİCARİ İŞLETMELER', '3 AY', 6, 1, 7, 42, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 34, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Dağınık elektrik kablo ve hortumlar', '1- Takılma, düşme sonucu yaralanma', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1-  Kısmi kablo kanalları ve spiral uygulaması mevcuttur.', 1, 0, 3, 2, 7, 42, 'D', '1-  Elektrik kabloları için kablo kanalları, spiral koruyucu veya yerden geçen hatlara sabitlenmelidir.\n2-  Hortum ve malzemeleri düzenli raf / askı sistemine alınmalıdır.\n3-  Kaçış yolları üzerinde kablo, kanalı vb. bulunmamalıdır.', 'TİCARİ İŞLETMELER', '3 AY', 3, 2, 7, 42, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 35, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Çöp kovalarının açık olması', '1- Sinek, böcek, fare gibi zararlı canlıların çoğalması ve hastalık yayması', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 6, 2, 3, 36, 'D', '1- Çöp kovaları sürekli kapalı tutulmalıdır.\n2- Çöp poşetlerinin ağızları bağlanarak dış çöpe atılmalı, çöpler bekletilmemelidir.\n3- Çöp kovaları temizlik maddeleriyle düzenli olarak yıkanmalıdır.\n4- Düzenli aralıklarla zararlının türüne göre ilaçlama yapılmalıdır.\n5- Zararlı canlıların yemekhane ve mutfağa ulaşabilecekleri delik ve açıklık varsa  kapatılmalıdır.', 'TİCARİ İŞLETMELER', 'HERGÜN', 6, 2, 3, 36, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 36, 'BÖLÜM 1: TİCARİ ALANLAR', '1- Havalandırma menfez ve iklimlendirme sistemlerin de toz birikmesi', '1- Solunum yolu rahatsızlıkları, alerji ve astım riski', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 6, 2, 3, 36, 'D', '1-  Menfez ve Filtre temizlikleri belirlenmiş periyotlar ile yapılmalı,toz birikimi önlenmelidir.\n2-  Yemek, cafe ve oturma alanlarında temiz hava akışı sağlanmalıdır.\n3-  Yoğun pişirme sırasında ekstra havalandırma veya fan kullanımı ile koku ve duman kontrol edilmelidir.', 'TİCARİ İŞLETMELER', 'HERGÜN', 6, 2, 3, 36, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Koterizasyon (elektrokoter) işleminin yapılması', '1- İşlem kaynaklı dumandan dolayı meslek hastalıkları                   2- Cihaz kaynaklı elektrik çarpmaları', '1-Cildiye Pol. Hekimler ve Hemşireler', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Koterizasyonun yapıldığı alana duman aspiratörü temin edilmeli ve  işlem sırasında kullanılmalıdır.                                                                                                                            2- Elektrokoter cihazının topraklaması yapılmalıdır.                                                                    3- İşlem esnasında ıslak yüzey bulunmamalıdır.                                                                              4- İşlem sırasında maruz kalan çalışan için TS EN 149 Standardında FFP2 Maske bulundurulmalı ve çalışan tarafından kullanılmalıdır.', 'İŞVEREN V.\nCİLDİYE\n ÇALIŞANLARI', '2 AY \nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Elektrikli mutfak aletleri (çay, kahve, microdalga fırın, airfryer vb.) kullanılması', '1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm', '1-Klinik Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Hastane de mutfak olarak belirlenmiş alanlar dışında hiçbir yerde elektrikli mutfak aletleri kullanılmamalıdır.                                          \n2- Mutfak olarak tanımlanmış alanlarda sadece çay ve kahve makinesi kullanılmalı, bunların dışındaki aletlerin kullanımı yasaklanmalıdır.         \n3- Sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.    \n4- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.\n5- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.', 'İŞVEREN V.   \nFTR \nÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Z katı acil çıkış merdivenlerinin lambalarının arızalı olması', '1-Acil durumlarda tahliyenin zorlaşması', '1- FTR Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 15, 135, 'C', '1-Arızalı acil durum aydınlatmaları değiştirilmelidir.\n2- Acil çıkış  merdivenleri yeterli şiddetde aydınlatılmalı ve elektrik kesilmelerinde otomatik olarak devreye girecek aydınlatma sistemi bulunmalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Oksijen tüplerinin ve diğer basınçlı tüplerin paslı ve korozyonlu olması', '1- Tüplerinin yapısal bütünlüğünün bozulması sonucu gaz kaçağı, patlama meydana gelmesi', '1- FTR Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-O2 Tüpleri  alanda köşede zincirler ile sabitlenmesi gereken alanlar belirlenmiştir.', 1, 0, 3, 3, 15, 135, 'C', '1- Paslı ve korozyonlu tüpler kullanım dışı bırakılmalıdır.               \n 2- Bu tüplerin tedarikçi firma tarafından hidrostatik test ve ultrasonik kalnlık ölçümleri yapılmalıdır.                                                                          \n3- Gaz sızıntısı durumunda hiçbir onarım yapmadan tüp açık bir alana çıkarılarak tedarikçi firmaya haber verilmelidir.                    \n4- Basınçlı tüpler elektrik ısı kıvılcım kaynaklarından en az 3 metre uzakta bulundurulmalı, en az iki noktadan dik konumda sabitlenmelidir.', 'İŞVEREN V.                                       FTR ÇALIŞANLARI', '3 AY    \n\n HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Tedavi arabalarının koridorda bulundurulması', '1-Hasta ya da hasta yakınlarının kesici delici aletlere kolay erişmesi sonucu fiziksel şiddet', '1-FTR çalışanları', '1- Panik butonları mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Tedavi arabaları mümkün olduğunce ortak alanlardan uzakta park edilmelidir.                              \n2-Üzerinde kesinlikle makas, bıçak vb. kesici aletler bulundurulmamalıdır.                                                         3-Ayrıca ilaç rafları kilitli tutulmalı, tehlikeli ya da kırmızı reçeteli ilaçlar kesinlikle bulundurulmamalıdır. \n4-Tedavi arabası içerisindeki tıbbi atık kutusunun kapağının sürekli kapalı tutulmalı ve dolu olmamalıdır.', 'BİRİM SORUMLULARI\nFTR\n ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Hasta yıkama odası içerisinde duş telefonları ve yataklarının prize yakın olması', '1-Elektrik kaçakları,                                                 2-Elektrik çarpmaları                                               3- Elektrik yangınları', '1-FTR Klinikler Hasta Odaları                                      2-Sedyeli Banyo Odaları', '1- Prizlerde koruma kapakları mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Hasta yıkama odasında duş telefonları yakınında bulunan bütün prizler iptal edilmelidir.                                                                          \n 2-Aktif olarak kullanılıyorsa prizler değiştirilerek yerlerine su geçirmez priz (etanj) kullanılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Hasta odası camlarının yetkisiz kişilerce açılması', '1- İntihara meyil                                                         2-İklim bozuklukları', '1-FTR çalışanları', NULL, 1, 0, 3, 3, 15, 135, 'C', '1- Hastane de tüm camlar kontrol edilmeli, tam açılabilen camlar en fazla açıklık 15 cm açılacak şekilde ayarlanmalı ve sabitlenmelidir.                                                                                                  2- Pencere kilitleri sadece yetkili bölüm sorumlularında bulunmalı, sadece acil ihtiyaç halinde açılmalıdır. \n3- Hastalarda ya da hasta yakınlarında lokma anahtar tespit edildiğinde derhal birim sorumluları ya da çalışanlar tarafından el konulmalıdır.', 'FİRMA  \nKLİNİK ÇALIŞANLARI', '3 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-3. Kat Teras çıkış kapısın da kart sistemi bulunmaması', '1-Yetkisiz kişilerin ulaşımı sonucu intihar girişimleri,', '1- FTR Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 15, 135, 'C', '1- Terasa çıkış kapısı kartlı sistem olmalıdır.                                         \n2- Terasa yetkisiz kişilerin çıkması önlenmelidir.\n3- Çalışanlar terasa sigara içme vb. amaçlar ile çıkmamalıdır.', 'İŞVEREN V.\nFTR\n ÇALIŞANLARI', '3 AY \nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Mahal Kodu: 08000103102 içerisinde mekanik odanın kapı kilidinin bozuk olması', '1- Yetkisiz çalışanın mahale girmesi sonucu yaralanma, ölüm', '1- FTR çalışanları', NULL, 1, 0, 3, 3, 15, 135, 'C', '1-Teknik Birim personelleri alanda işleri bittiğinde kapıları tam kapatmalı, kilitli olduğundan emin olmadan alandan ayrılmamalıdır.                                                                   2- Kilidi veya Kapıları bozuk mekanik ve elektrik odalarının tespitinde derhal Teknik Birim personeline bildirilmeli, derhal onarılmalıdır.                                                      3- Kapı Kilidi bozuk olan mekanik/Elektrik odalarının önüne \'\'Dikkat Elektrik Var, Girmek Yasaktır\'\' şeklinde uyarı levhaları bulundurulmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Basınçlı tüplerin hatalı kullanılması', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1- FTR Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Oksijen tüpü sabitleme aparatları bulunmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Oksijen tüplerine yağlı, kremli eller ile temas edilmemeli, vanaları yağlanmamalıdır.                                                                                                                                   2- Tüpler ısı kaynaklarından ve güneşin etkisinden uzak tutulmalıdır.                                                                                                                                    3- Manometreler sağlam olmalı, kırık olanlar değiştirilmelidir.                                       \n4- Basınçlı tüpler zeminde sabitlenmeden bırakılmamalı, sabitleme aparatlarına takılmalı ve 2 noktadan zincir ya da halatla bağlanmalıdır.', 'FTR\n ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Banyodan su taşkınlarının yaşanması', '1-Su baskınları                                                     2-Sıvıya bağlı Elektrik çarpma ve kaçakları                                                                              3- Kayma, Düşme', '1-FTR çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-Hasta odalarında banyo giderlerinin düzenli bakım ve onarımları yapılarak tıkanma problemleri engellenmelidir.                                                               \n2- Duşakabin içerisinde eğim tekrar düzenlenmeli, gider doğru yokuş yapılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Bulaşı Bulunan hastaların izolasyonu', '1- Meslek hastalıkları                                                   2- İş Kazaları', '1-Klinik çalışanları', '1-Tanımlayıcı figürler aktif olarak kullanılmalıdır.', 1, 0, 3, 6, 7, 126, 'C', '1-Klinikte bulaşı bulunan ve bilinen hastalarında odaları Sağlık Bakanlığı\'nın belirlemiş olduğu tanımlayıcı figürler ile belirtilmelidir.    \n2-Sarı Yaprak (Solunum İzolasyonu)- Mavi Çiçek (Damlacık İzolasyonu)-Kırmızı Yıldız (Temas İzolasyonu) Şeklindedir.                                                 \n3-Hastane içerisindeki tüm personele EKK eğitim vermelidir.                                                                     4- Personel Figürlerin bulunduğu odaya girerken KKD\'lerini eksiksiz kullanmalı, koruyucu önlemleri olmadan odaya girmemelidir.', 'EKK \nFTR\n ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Uygunsuz Formaldehit Kullanımı', '1- Meslek hastalıkları                                                   2- İş Kazaları', '1-K.D Septik  çalışanları                       2-Hemotoloji K. Çalışanları', '1-Formaldehit ile çalışan personele İSGB tarafından Formaldehitile güvenli Çalışma eğitimi verilmiştir.', 1, 0, 3, 6, 7, 126, 'C', '1- 21.10.2025 tarihinde hazırlanan Yöntem Beyan\'ına göre firma tarafından formaldehit, patoloji laboratuvarında porsiyonlanarak gönderilmelidir\n2- Formaldehit büyük kaplardan, küçük kaplara aktarılırken taşma kapları kullanılmalı, zemine dökülmesi önlenmelidir.\n3- Formaldehit dökülmesine karşı döküntü kitleri temin edilmelidir.\n4- Çalışanlar formaldehit ile çalışma esnasında EN 149 standardında ffp3 maske, eldiven ve koruyucu gözlük kullanmalıdır.', 'İŞVEREN V.\nFTR\n ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Fizyoterapi için kullanılan sedyelerin kilit sistemlerinin bozuk olması', '1- İş kazaları            2-Deprem anında tahliyenin gecikmesi', '1-FTR Binası Klinikler ve Fizyoterapi Ünitesi Çalışanları', NULL, 1, 0, 6, 3, 7, 126, 'C', '1- Firma tarafından belirli aralıklar ile sedyelerin periyodik muayeneleri yaptırılmalıdır.                                                                                                                                                 2- Kilit sistemleri veya sedyede herhangi bir arıza meydana gelirse kullanım dışı bırakılmalı, onarımı yaptırılmadan kullanılmamalıdır.', 'FTR\n ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Tavan, Çatı akmaları ve çökmeleri', '1-Suyun elektrik ile teması sonucu çarpılma', '1- FTR çalışanları', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1- Çatıdan su akan yerler tespit edilmelidir.\n2- Su çeken tavan vb. yerler onarılmalıdır.\n3- Suyun elektrik sistemlerine temas etmesi önlenmeli, temas eden yerlerin onarım sağlanana kadar akım kesilmelidir.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Robotik Rehabilitasyon ünitesi hasta kaldırma/ taşıma işlemi', '1-Kas iskelet sistemi hastalıkları', '1-Fizyoterapist', '1-Çalışanlar Yılda 1 kez Ergonomi ile Güvenli çalışma eğitimi almaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Hastaları Robota kaldırma, indirme işlemleri en az 2 kişi ile yapılmalıdır.                              2-Çalışanlara Ergonomik çalışma eğitimi verilmeli ve düzenli olarak sağlık taramalarına katılmalıdır.', 'İŞ GÜVENLİĞİ UZMANI\nFİZYOTERAPİSTLER', '2 AY \nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Atık odalarının kapılarının kilitli tutulmaması', '1-Enfeskiyon kaynaklı meslek hastalıkları/İşle ilgili hastalıkları', '1- FTR çalışanları', NULL, 1, 0, 6, 3, 7, 126, 'C', '1- Atık bekleme odalarının kapıları açık bırakılmamalı her zaman kilitli olmalıdır. \n2- Atık bekleme odalarına kartlı giriş sistemi yapılmalı, yetkisiz kişilerin girişi önlenmelidir.\n3- Düşen, okunmayan uyarı levhaları değiştirilmelidir.                                                                                                    4- Sürekli saha gözetimi, kontrol ve denetim sağlanmalıdır.', 'FİRMA                          \n ATIK VE TEMİZLİK ÇALIŞANLARI', '2 AY                              HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Prizlerin yuvalarından çıkması', '1- Elektrik çarpması sonucu yaralanna', '1- FTR çalışanları', NULL, 1, 0, 6, 3, 7, 126, 'C', '1- Hasarlı prizler onarılmalı ya da yenileriyle değiştirilmelidir.  \n2- Hasralı prizlerin topraklama bağlantıları da kontrol edilmelidir.                                                                              3-Birim sorumluları ve Ççlışanlar alan kontrolü yaparak Arızalı veya yerinden çıkmış priz gördüklerinde 1616 üzerinden Prizlerin onarılmasını talep etmelidir.', 'FİRMA                         FTR \nÇALIŞANLARI', '2 AY                              HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Hasta kayıt personellerinin önünde seyyar kalorifer kullanılması', '1-Yangının çıkması   \n2- Elektrik çarpması', '1- FTR çalışanları', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Hastane de soğuk havalarda elektrik ısıtıcılar kullanılmamalı, ısınma amaçlı sadece iklimlendirme sistemi kullanılmalıdır.                                                                                                          2- Çalışanların otomatik açılan kapılardan soğuk havaya maruz kaldıkları alanlara hava perdeleri yapılmalıdır.                                                                                                                                3- İstisnai durumlarda idareden özel izin alınmalı, ısıtıcıların prizlerden beslenmesi sağlanmalı, yanıcı malzemelerden uzak tutulmalı,kullanım sonrası fiş prizden çekilmelidir.                                                                                                                     4- İzinsiz kullanılan tüm ısıtıcılar toplatılmalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Z Katı acil çıkış merdivenlerine ulaşımda tümsek bulunması', '1-Acil durumlarda tahliyenin zorlaşması', '1- FTR Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Acil çıkış yollarınn ya da merdivenlerinin önünde hiçbir engel bulunmamalı, her an kullanılabilmesi için engellerden arındırılmış hâlde bulundurulması gerekir.\n2- Merdivenler önünde tümsek bulunmamalı, kaldırılmalıdır.\n3- Çıkışlar ve erişim yolları açıkça görülebilir olmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Terzi odasında kumaş kesim moturunun emniyetsiz kullanılması', '1- El kol yaralanmaları', '1- Terzi Çalışanı', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Kesim motorunun koruyucusu iptal edilmemelidir.\n2- Koruyucu indirilmeden kesim yapılmamalıdır.\n3- Kesim motoru durdurulmadan üzerinde herhangi bir işlem yapılmamalıdır.\n4- Kesim yapılırken cihaz kablosu işlem alanından uzak tutulmalıdır.\n5- Bıçak değiştirme işlemi elektrik akımı kesildikten sonra yapılmalıdır.\n6- Kullanılmayan kesim motoru fişten çekilip kaldırılmalıdır.', 'TERZİ ÇALIŞANI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Terzi odasında ya da oda önünde yangın söndürücü bulunmaması', '1- Yangın çıkması                       2- Yangının büyümesi', '1- Terzi Çalışanı', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Oda içerisinde ya da yanında kuru  kimyevi tozlu yangın söndürme tüpü bulundurulmalıdır.                                                                                                                                     2- Terzi odası içerisinde elektrikli ev aletleri kullanılmamalıdır.                                              3-  Terzi odası içerisinde hiçbir şekilde açık alev kullanılmamalı, yanıcı madde kullanılmamalıdır.     \n4- Kumaşlar raflara düzenli istiflenmeli, atıl kumaşlar oda da bekletilmemelidir.', 'İŞVEREN V.\nTERZİ ÇALIŞANI', '1 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Ayniyat odalarında yüksek istifleme yapılması', '1- Malzeme düşmesi sonucu  yaralanma, ezilme, sıkışma', '1- Ayniyat Çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- İstif yüksekliği en fazla 3 metre olmalıdır.\n2- Malzemeler düzenli istiflenmeli, devrilmeyecek şekilde sabitlenerek istif yapılmalıdır.\n3- Devrilme riski olan malzemeler 1,5 metreden yüksek istiflenmemelidir.\n4- Stok girişi yapılmayan malzemeler depoya alınmamalıdır.\n5- Ağır malzemeler en altta istiflenmelidir.', 'AYNİYAT BİRİMİ ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Hastaların oksijen tüpü ile hastaneye gelmesi', '1-Parlama, patlama, yangın                           2- iş kazaları yaşanması', '1- FTR Çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-Hastalar alana geldiğinde sabitlenmemiş, yatay taşınan oksijen tüpleri hasta karşılama ve güvenlik personeli tarafından tespit edilerek, oksijen tüplerinin hastane içerisine girişini engellemelidir. Mümkün olmadığı durumda alanda Oksijen tüpü sabitleme aparatı bulundurularak sedye ve tekerlekli sandalye için sabitleme aparatı hastane içerisinde kullanılması için hastalara temin edilmelidir.', 'İŞVEREN V. \nGÜVENLİK GÖREVLİLERİ', '3 AY          HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Güvenlik filesinin periyodik kontrolllerinin yapılmaması', '1- Yüksekten düşme sonucu yaralanma', '1- FTR Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-Güvenlik filelerinin periyodik kontrolü TS EN 1263-1, TS EN 1263-2 standartlarına uygun olarak en geç yılda bir yapılmalıdır.\n2- Fileler de yırtık, kopukluk, aşınma olup olmadığı, kenar halatlarının bağlantı iplerinin sağlam olup olmadığı, ankraj noktalarında aşınma, pas korozyon olup olmadığı göz ile ayda bir kontrol edilmeli, belgelendirilmelidir.', 'İŞVEREN V.', 'İLGİLİ PERİYOTLAR\nİLE \nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Portable ve EKG cihazlarının koridor alanında sarj edilmesi', '1 -Elektrik çarpmaları                                               3- Elektrik yangınları', '1-FTR çalışanları', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1- Portable ve Ekg cihazlarının sarj edilmesi için ortak alanlarda uzak ayrı bir alanda şarj edilmelidir.\n2- Sarj işlemi sona erdiğinde kablolar fişe takılı bırakılmamalıdır.', 'FTR\n ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 27, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Elektroterapi Ünitesinde kullanılan makine kablolarının yıpranması', '1- Elektrik çarpmaları', 'Elektroterapi Çalışanları', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1- Yıpranmış, ezilmiş, soyulmuş ve izolasyonsuz kablolar değiştirilmelidir.                                                                                                                           2-  İzole bantlı ekli kablolar kullanılmamalıdır.\n3- Makikenelerin elektrik kabloları çift izolasyonlu olmalıdır.', 'BİYOMEDİKAL HİZMETLER', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 28, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Elektroterapi cihazlarını kabloların dağınıklığı', '1-Kabloların deforme olması sonucu elektrik çarpmaları               2-Takılma/Düşme', '1- Elektroterapi Çalışanları', NULL, 1, 0, 6, 6, 3, 108, 'C', '1- Ekipmanların kabloları kablo tutucu ve kablo askıları ile sabitlenmeli, toparlanmalıdır.                                                                                                                                            2-Kabloları yıpranma, ezilme, izolasyon kopması açısından kontrol edilmelidir.             \n3-Makine ve priz yerleşimi gözden geçirilerek kablo karmaşası en aza indirilmelidir.', 'BİYOMEDİKAL HİZMETLER\nELEKTROTERAPİ\n ÇALIŞANLARI', '3 AY                      HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 29, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Kan ve vücut sıvılarının göz ve cilde temas etmesi', '1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- FTR çalışanları', '1-KKD\'ler mevcuttur.                                         2- Çalışanlara KKD önemi ve kullanımı konusunda eğitim verilmektedir.', 1, 0, 6, 6, 3, 108, 'C', '1-Çalışanlar TS EN 455  standardında eldiven, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında maske vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.', 'İŞYERİ HEKİMİ \n FTR \nÇALIŞANLARI', 'MARUZİYET OLMASI DURUMUNDA    HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 30, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-O2 tüplerinin kliniklerde  fazla sayıda  bulundurulması', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1- FTR Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Acil durum arabaları dışında bulundurulan her O2 tüpü zincirler ile belirlenen yerlerde sabitlenerek bulundurulmaktadır', 1, 0, 3, 3, 7, 63, 'D', '1-Klinik alanlarında O2 tüplerinin fazla istiflenmemesine her alanda klinik özelliğine göre 1 ya da 2 adet bulundurulmalıdır.      \n2- Merkezi Oksijen sistemi kullanılmalı,  taşınablilir O2 tüpleri fazla sayıda bulundurulmamalıdır. \n3- Oksijen tüpü kullanım talimatı kullanılan alanlara asılmalıdır.', 'BİRİM SORUMLULARI\nFTR  ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 31, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Çalışan hasta ve hasta yakınları iletişim problemleri, fiziksel sözlü şiddet,', '1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma,', '1-FTR çalışanları', '1-Panik butonları mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Hasta ve hasta yakınları tarafından çalışanların şiddete uğrayabileceği tüm alanlara sabit panik butonları ilave olarak yaka butonları temin edilmelidir.                                                                                                                                                                                                         2- Şiddet riskinin yoğun olduğu alanlarda butonlara ilave olarak sabit güvenlik personeli  bulundurulmalıdır.                                         \n3- Çalışanlara iletişim, stres yönetimi ve öfke kontrolü ile mesleki bilgi ve becerilerini arttırıcı eğitimler verilmelidir.', 'İŞVEREN V.\nİŞ GÜVENLİĞİ UZMANI', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 32, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Hasta taşıma ekipmanının ağırlık testi', '1- Hastanın personel üzerine düşmesi                                 2-Ergonomik yaralanmalar', '1-FTR çalışanları', NULL, 1, 0, 3, 3, 7, 63, 'D', '1-Banyo içerisinde yardıma muhtaç hastaları küvete yerleştirmek amacıyla kullanılan hasta taşıma ekipmanının kalıdırma sistemlerinin kontrol ve bakımları yapılmalıdır.', 'BİYOMEDİKAL HİZMETLER', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 33, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Hasta yıkama odasının giderlerinin uygun olmaması', '1-Su taşmaları, baskınlar                                     2-Kaygan Zemin sonucu düşme, iş kazaları', '1-FTR çalışanları', '1-Hasta odasında drenaj kanalı mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1-Hasta yıkama odasında bulunan drenaj kanalına doğru eğim bulundurulmalıdır.                                                           \n2-Su gideri uygun genişlikte olmalı, arıza, tıkanma durumlarında derhal bildirilmeli ve onarımları yaptırılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 34, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Portable röntgen cihazlarının kullanılması', '1-Radyasyon maruziyeti sonucu meslek hastalıkları', '1-FTR çalışanları', '1-Kurşun önlükler mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Taşınabilir röntgen cihazı ile yapılan çekimler de kurşun paravan kullanılmalıdır.                                                                                                                                                               2- Çekim yapılan alanda hasta ve çekim yapan çalışan dışında kimse olmamalı, zorunlu hallerde bulunulması gerekirse(TS EN 61331 standardında kurşun önlük troid koruyucu vb.kişisel koruyucu ekipmanlar kullanılmalıdır.                                                                                                       3- Çekim yapılan odaların kapıları kapatılmalıdır.                                                                                           4- Açık alanlarda yapılan çekimlerde çalışanlar en az 2 metre uzakta durmalıdır.', 'RADYOLOJİ ÇALIŞANLARI      \n FTR\n ÇALIŞANLARI', 'ÇEKİM ESANASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 35, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Kat asansörleri önünde yetersiz aydınlatma', '1- Görme problemleri sonucu düşme, iş kazası', '1- FTR çalışanları', NULL, 1, 0, 3, 3, 7, 63, 'D', '1- Eksik veya arızalı aydınlatma armatürleri değiştirilmelidir.                                                   3- Elektrik tesisastı kontrol edilmeli tekrarlayan arızaların giderilmesi sağlanmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 36, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Sıvı azotun vücut ile temas etmesi', '1- Dokularda donma ve nekroz riski                             2- İş kazaları meydana gelmesi', '1- Derma pol. çalışanları', NULL, 1, 0, 3, 3, 7, 63, 'D', '1- Kullanım sırasında izolasyonlu EN 511 standardına uygun kriyojenik eldiven, kriyojenik önlük, kriyojenik ayak koruyucuve yüz siperliği kullanılmalıdır. Eksik KKD\'ler temin edilmelidir.                                                                             \n2- KKD\'ler, zimmet formu ile çalışana zimmetlenmeli ve çalışanlar tarafından da eksiksiz kullanılmalıdır.', 'İŞVEREN V. \n(KKD TEMİNİ)\nDERMA POL. ÇALIŞANLARI', '3 AY                                     HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 37, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Z Katı ergoterapi ünitesi yangın söndürme cihazlarının kullanım dışı olması', '1-Yangına ilk müdahale yapılamaması sonucu şiddetin artması', '1- FTR çalışanları', NULL, 1, 0, 3, 3, 7, 63, 'D', '1-Yangın Tüpleri aylık olarak kontrol edilmeldir.\n2- Boş olan tüpler doluma gönderilmelidir.                  .                                                                3-Doluma giden tüp yerine yenisi bırakılmalıdır.', 'FİRMA', '1 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 38, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Sabitlenmemiş dolap ve raflar', '1-Devrilme, düşme ya da çarpma sonucunda vücut bölümlerinin sıkışması, yaralanması', '1- FTR Çalışanları', '1-Birçok dolap ve raf sabitlenmiştir.', 1, 0, 3, 3, 7, 63, 'D', '1-Sabitlenmemiş doalp ve raflar en az iki noktadan sabitlenmelidir.\n2-Düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.\n3-Ağır malzeme ve ekipmanlar yüksek istiflenmemeli, dolap üzerine malzeme konulamamlıdır.                                    \n4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.', 'İŞVEREN V.\nFTR \nÇALIŞANLARI', '3 AY \n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 39, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Oksijen ve basınçlı tüplerin uygunsuz taşınması', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1- FTR Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Hasta taşıma esnasında sO2 tüplerini sabitlemek için aparatlar mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1- Hasta yatakları, taşıma araçları vb. basınçlı tüp taşınan ekipmanlarda tüpleri sabitlemek için aparatlar bulunmalı, tüpler en az iki noktadan sabitlenerek taşınmalıdır.                                                                                                \n2- Tüplerin taşınması esnasında vanaları kapalı olmalı, dik taşınmalı, kapağı kapalı olmalıdır.                                                                               \n3- Taşıma esnasında tüplerin başka cisimlere çarpması engellenmelidir.', 'FTR\n ÇALIŞANLARI    TAŞIMA ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 40, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1-Parafin Kullanımı', '1-Dökülme, saçılma sonrası kaygan zemine bağlı kayma, düşme                                                                                  2-Yangının büyümesi', '1-FTR çalışanları', '1-Yangın algılama ihbar ve söndürme sistemleri mevcuttur.', 1, 0, 3, 6, 3, 54, 'D', '1-Parafin maddesi depolama sıcaklığına dikkat edilerek ergimesi önlenmelidir.                                    \n2-Yere dökülme durumunda derhal alan temizlenmelidir.   \n3-Depolama alanında yanııcı maddeler ile bir arada depolanmamalıdır.                                                          4-Parafinler her türlü ısı kaynağından ve ısı kaynaklarından uzak tutulmalıdır.', 'BİRİM SORUMLULARI\nFTR\n ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 41, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Terzi odasında kullanılan dikiş makinesinin iğne koruyucusunun olmaması', '1- El kol yaralanmaları', '1- Terzi Çalışanı', NULL, 1, 0, 3, 6, 3, 54, 'D', '1- Makine çalışırken iğne kırılmalarına karşı, operasyon bölgesine, şeffaf koruyucu kapak takılmalıdır.\n2- El ve parmaklar operasyon bölgesine yaklaştırılmadan dikiş yapılmalıdır.\n3- İğne değiştirilmeden önce makine durdurulmalıdır.', 'İŞVEREN V.\nTERZİ ÇALIŞANI', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 42, 'BÖLÜM 1: FİZİK TEDAVİ REHABİLİTASYON', '1- Sıvı azotun solunması', '1- Baş dönmesi                                                   2-Bilinç kaybı', '1- Derma pol. çalışanları', NULL, 1, 0, 3, 1, 15, 45, 'D', '1- Sıvı azotun kullanıldığı alanlarda yeterli havalandırma sisteminin bulunmalı ve havalandırma sistemi her zaman aktif olmalıdır.                                    \n2- Boş tüpler alanda bekletilmemeli, boş tüp deposuna gönderilmelidir.                                                                                                                                                       3- Dökülme/buharlaşma gibi acil durumlarda alan acilen tahliye edilerek alan tamamen havalanmadan tekrar giriş yapılmamalıdır. \n4- Eldiven, yüz siperi, kriyojenik koruyucu eldiven ile eğitimli kişiler tarafından müdahale edilmelidir.', 'DERMA POL. ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: YGAP GENELİ', '1- Sigara içme odalarında ve rehabilitasyon alanlarında  kamera bulunmaması', '1- Çalışanlara şiddet sonucu yaralanma', '1- YGAP Çalışanları', NULL, 1, 0, 6, 3, 15, 270, 'B', '1- Hasta sigara içme odalarına  ve rehabilitasyon odalarına kamera sistemi kurulmalıdır.                                                                               \n2- Güvenlik personelleri tarafından odalar sürekli izlenmelidir.\n3- Çalışanlara yaka panik butonları verilmelidir.', 'İŞVEREN V.\nGÜVENLİK PERSONELLERİ', '2 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: YGAP GENELİ', '1- Rehabilitasyon alanında kullanılan kesici delici ağır malzemeler(spor ağırlık ekipmanları,tiner,mutfak gereçleri vb.) bulunması', '1- Çalışanlara şiddet sonucu yaralanma', '1- YGAP Çalışanları', '1- Güvenlik personeli mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1-Rehabilitasyona uygun olan hastalar sorumlu hekimlerce belirlenmelidir.                                                                        \n2-Hastalar rehabilitasyona çıktıklarında alanda bulunan güvenlik personeli sayısı arttırılmalıdır.                                                                    \n3-Rehabilitasyon odalarında kamera bulunmalıdır.                                                  4-Çalışanların yakalarında bulunan acil durum düğmeleri çalışır olmalıdır.', 'İŞVEREN V.\nSORUMLU HEKİMLER', '2 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: YGAP GENELİ', '1-Elektrikli mutfak aletleri (çay, kahve, microdalga fırın, airfryer vb.) kullanılması', '1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.', 1, 0, 1, 6, 40, 240, 'B', '1- Hastane de mutfak olarak belirlenmiş alanlar dışında hiçbir yerde elektrikli mutfak aletleri kullanılmamalıdır.                                          \n2- Mutfak olarak tanımlanmış alanlarda sadece çay ve kahve makinesi kullanılmalı, bunların dışındaki aletlerin kullanımı yasaklanmalıdır.         \n3- Sadece çift termostatlı çay kahve makineleri makineleri kullanılmalıdır.    \n4- Çay kahve makineleri direk fişe takılmalı, uzatma kablolarına takılmamalıdır.\n5- Çay kahve makineleri kullanıldıktan sonra fişten çıkarılmalıdır.', 'İŞVEREN V.   \nYGAP ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: YGAP GENELİ', '1- Oksijen tüplerinin ve diğer basınçlı tüplerin paslı ve korozyonlu olması', '1- Tüplerinin yapısal bütünlüğünün bozulması sonucu gaz kaçağı, patlama meydana gelmesi', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-O2 Tüpleri  alanda köşede zincirler ile sabitlenmesi gereken alanlar belirlenmiştir.', 1, 0, 3, 3, 15, 135, 'C', '1- Paslı ve korozyonlu tüpler kullanım dışı bırakılmalıdır.               \n 2- Bu tüplerin tedarikçi firma tarafından hidrostatik test ve ultrasonik kalnlık ölçümleri yapılmalıdır.                                                                          \n3- Gaz sızıntısı durumunda hiçbir onarım yapmadan tüp açık bir alana çıkarılarak tedarikçi firmaya haber verilmelidir.                    \n4- Basınçlı tüpler elektrik ısı kıvılcım kaynaklarından en az 3 metre uzakta bulundurulmalı, en az iki noktadan dik konumda sabitlenmelidir.', 'İŞVEREN V.                                       YGAP ÇALIŞANLARI', '3 AY    \n\n HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: YGAP GENELİ', '1- Panik butonlarının çalışmaması, yaka butonlarının pilinin bitmesi', '1- Beyaz kod durumunda güvenlik görevlilerine ulaşılamaması sonucu durumun kötüleşmesi', '1- YGAP Çalışanları', '1-Bir çok alanda  panik butonları mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Panik butonları her zaman çalışır durumda olmalıdır.                    \n2- Panik butonlarının haftalık fonksiyon testleri yapılmalı, yılda en az bir kez periyodik kontrol yapılmalıdır.                                                                   \n3- Panik butonlarında arıza olması halinde en fazla 2 saat içinde arıza giderilmeli, giderilemiyorsa, çalışanlara yaka butonları verilmelidir.                                                                                                                                 4- Yaka butonları kontrol edilmeli pilleri bitmeden değiştirilmelidir.', 'İŞVEREN V.\nYGAP ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: YGAP GENELİ', '1- Yardımlı banyoda duş yanında priz olması 2- Elektirikli ısıtıcı bulunması', '1-Elektirik çarpması sonucu yaralanma', '1- YGAP Çalışanları', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Yardımlı banyolarda suyun elektrik ile teması önlenmeli, duş yanındaki priz iptal edilmelidir.\n2- Yardımlı banyolarda elektrikli ısıtıcılar kullanılmamalı, iklimlendirme sistemi kurulmalıdır.\n3-Yardımlı banyolar da kullanılan fiş priz aydınlatma sistemleri etanj özellikte olmalıdır.                     \n4- Elektirikli ısıtıcı su ile temasının olmayacağı bir alana taşınmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: YGAP GENELİ', '1-Özel politika grupları uygulamalarının yetersiz olması', '1-İş kazası ve meslek hastalıklarının artması', '1-Özel politika grupları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Acil durumlarda özel politika gruplarına tahliye esnasında refakat edilmesi için refakatçiler belirlenmelidir.\n2-Engelliler sadece sağlık raporunda belirtilen ve engel durumuna uygun işlerde  çalıştırılmalıdır.  \n3-Özel politika gruplarına kendi istekleri dışında fazla mesai yaptırılmamalı, gece vardiyalarında çalıştırılmamalıdır.\n4-Bu gruplar uzun süre ayakta çalıştırılmamalı, ağır yük taşıtılmamalıdır.                                                                                                                                     5-Özel politika gruplarına özel olarak eğitim verilmelidir.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: YGAP GENELİ', '1- Çalışanlara yöneticileri ya da hasta hasta yakınları tarafından mobing uygulanması', '1-Sinirlilik, stres, depresyon, tükenmişlik sendromu, iş kazalarında artış', '1- YGAP Çalışanları', '1-Çalışan hakları birimi mevcuttur.                                         2-Çalışan memnuniyet anketleri yapılmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1-Çalışanlara gereğinde psikolojik destek ve danışmanlık sağlanmalıdır.                                                                                                                                         2- Mobing bildirimi alındığında tarafsız inceleme süreci başlatılmalı, taraflar ayrı ayrı dinlenmeli, ve somut veriler ile kayıt tutulmalıdır.                                                                                                                            3- Tükenmişlik yaşayan çalışanlar düşük yoğunluklu birimlere kaydırılmalıdır.                                                                                                                              4- Şikayet konusu yönetici ise, yönetici davranış düzeltme sürecine (eğitim, gözlem vb.) alınmalıdır.                                                                           \n5- Sürekli sorun çıkaran çalışanlar için eğitim, görev değişikliği ya da disiplin süreçleri başlatılmalıdır.', 'İŞVEREN V.\nÇALIŞAN \nHAKLARI \nBİRİMİ', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: YGAP GENELİ', '1- Ergonomik olmayan ofis mobilyaları ve çalışma şekli', '1- Postür bozuklukları sonucunda kas-iskelet sistemi hastalıkları,  verimlilik kaybı,', '1- YGAP Çalışanları', '1- Ergonomik risk faktörleri hakkında eğitim verilmiştir.', 1, 0, 6, 3, 7, 126, 'C', '1- Sandalyeler ergonomik tasarıma sahip olmalı, ayaklar düz olarak yere temas etmeli, diz 90 derece açılı olmalı,  sandalyede bel desteği olmalı,  sırt dik, omuzlar rahat, dirsekler 90 derece açılı olmalıdır.                                                                                                                                                                   3- Eğer ayaklar yere temas etmiyorsa, ayaklara ek bir destek yerleştirilmelidir.                                                                                                                                       4- Ekranın üst kenarı göz hizasında veya az aşağısında olmalıdır.', 'İŞVEREN V.                          (EKSİK MALZEMELER)  ÇALIŞANLARI', '3 AY                         HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: YGAP GENELİ', '1-Tehlikeli kimyasalların yanlış depolanması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması                                 2- Yangın meydana gelmesi', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Kimyasallar depo alanında depolanmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Kimyasal maddeler depolama matirsine göre depolanmalıdır.                                                        2- Yanıcı kimyasallar elektrik kaynaklarından uzak depolanmalıdır.                                                                               3- Kimyasal maddelerin ağzı açık olmamalı, dik olarak istiflenmelidir.                                              4- Ağzı açılmış kimyasal madde kaplarının altına taşma kapları konulmalıdır.', 'YGAP ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: YGAP GENELİ', '1- Kimyasal madde deposunda göz duşu ve döküntü kiti bulunmaması                                               2- Çalışanların kimyasallar hakkında bilgi sahibi olmaması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1- YGAP Çalışanları', '1- Kimyasallar depo alanında depolanmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         \n2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.                                              3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               4-Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.                              \n5- Çalışanlara MSDS ve kimyasalların güvenli kullanımı konusunda eğitimler verilmelidir.', 'İŞVEREN V.                                       İŞ GÜVENLİĞİ UZMANI', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: YGAP GENELİ', '1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması', '1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması', '1- YGAP Çalışanları', '1-Alanlara özel olarak KKD\'ler alanda mevcuttur.                                                                                  2- Tüm çalışanlar KKD Zimmet formunu imzalamıştır.', 1, 0, 3, 6, 7, 126, 'C', '1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan kkd\'ler temin edilmelidir.\n2- Çalışanların maskeleri N95 ya da TS EN149 A1 standardında,göz koruyucuları TS EN 166 standardına uygun ve tam kapalı tip, iş eldivenleri TS EN 455 standardına, kesilmelere dayanıklı TS EN 388 standardına, çalışanların önlükleri sıvı geçirmez önlük/ cerrahi önlük TS EN ISO 13688 ve TS EN 13795 standartlarında iş ayakkabıları kaymaz tabanlı olmalıdır.                                                                                                                                                                                                 3- Bütün kişisel koruyucular çalışanlara zimmetlenmelidir.                                                                       4- Kişisel koruyucu donanımlar çalışanlar tarafından eksiksiz kullanılmalıdır.', 'İŞVEREN V.\n (EKSİK \nKKD \nTEMİNİ)\n\nYGAP ÇALIŞANLARI', '3 AY  \n\n                                HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: YGAP GENELİ', '1-Steril olmayan, kontamine olmuş aletlerin açıkta bırakılması', '1-Steril olmayan aletlere temas sonucu iş kazaları enfeksiyon, bulaşıcı hastalık', '1- YGAP Çalışanları', '1-Enfeksiyon Kontrol Komitesi işe başlangıç ve belirli periyotlar ile çalışana eğitim vermektedir.', 1, 0, 3, 6, 7, 126, 'C', '1-Kullanılan, kontamine olmuş aletler bekletilmeden hemen kapaklı ve renk kodlu atık kutularına atılmalıdır.                                                                                                                           2- Sterilazyona gidecek aletlere TS EN 388 standardında kesilme ve delinmeye dayanıklı eldiven olmadan temas edilmemeli, çelik, kapaklı kutulara konulmalıdır.                                                                                                                                                        3- Tek kullanımlık olmayan aletler her kullanımdan sonra dezenfekte edilmelidir.                                                                                                     \n4- Kontamine olmuş aletler, çarşaf, yatak, yorgan vb. yere saplanmamalı, yere atılmamalıdır.                                                                                                                                                          5- Temas edilmesi durumunda, bölge bol su ve sabunla yıkanmalıdır.', 'YGAP ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: YGAP GENELİ', '1-Buat kapaklarının açık olması, kapakların kırık olması', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, elektrik yanıkları, ölüm,', '1- YGAP Çalışanları', '1-30 MA kaçak akım rölerleri mevcuttur.\n2- Topraklama ölçümleri mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Buat kapakları kapalı tutulmalıdır.                                                                         \n2-Kırık buat kapakları değiştirilmeli, vidalar ile tutturulmamalıdır.  \n3- Buatlara fişler yatay takılmalı, dikey fişler kullanılmamalı, buatların açık kalması önlenmelidir.       \n4- Buatların üzerinde ki masalarda bir şey yenilip içilmemelidir.', 'FİRMA  \nYGAP ÇALIŞANLARI', '3 AY \n                          HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: YGAP GENELİ', '1- Elektrik kabloların da aşırı yükleme olması \n2- Elektrik kablolarına su ve buhar temas etmesi', '1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Hastane de kullanılan tüm elektrik, uzatma (3\'lü) vb. kablolar halojen free (geç yanan, zehirli gaz çıkarmayan) özellikte olmalıdır.                      \n2- 3 lü uzatma kablolarına, 3 lü uzatma kablosu kullanarak kullanılmamalıdır.                                                                                                     3- Yüsek akım çeken cihazlar (kettle çay makinesi vb.) beslemesi ayrı fişlerden yapılmalı, uzatma kabloları kullanılmamalıdır.                                                                                                             4- Elektrik kablolarının su ve buhar ile teması önlenmelidir.\n5- Çalışanların dışarıdan uzatma kablosu getirmesi yasaklanmalıdır.', 'İŞVEREN V.\nYGAP ÇALIŞANLARI', '3 AY \n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: YGAP GENELİ', '1-Islak/Kaygan zemin oluşması', '1-Düşme, denge kaybı sonucunda vücut bölümlerinin yaralanması', '1- YGAP Çalışanları', '1-Kliniklerde sabit temizlik çalışanları mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1-Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.    \n2- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\n3- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.', 'TEMİZLİK ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: YGAP GENELİ', '1-Basınçlı tüplerin hatalı kullanılması', '1- Tüplerin düşmesi, devrilmesi sonucu patlama meydana gelmesi', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Oksijen tüpü sabitleme aparatları bulunmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Oksijen tüplerine yağlı, kremli eller ile temas edilmemeli, vanaları yağlanmamalıdır.                                                                                                                                   2- Tüpler ısı kaynaklarından ve güneşin etkisinden uzak tutulmalıdır.                                                                                                                                    3- Manometreler sağlam olmalı, kırık olanlar değiştirilmelidir.                                       \n4- Basınçlı tüpler zeminde sabitlenmeden bırakılmamalı, sabitleme aparatlarına takılmalı ve 2 noktadan zincir ya da halatla bağlanmalıdır.', 'YGAP ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: YGAP GENELİ', '1-İç bahçelerde açıkta kapaksız prizler bulunması', '1-Elektirik çarpması sonucu yaralanma', '1- YGAP Çalışanları\n2- Hastalar\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1- Su ile temas eden kullanılmayan prizler tamamen kalıdırılmalıdır.\n2- Dış alanda kullanılacak tüm elektrik sistemleri (aydınlatma priz vb.) etanj özellikte olmalıdır.                 \n3- İptal edilen prizlerde akım olmadığından emin olunmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: YGAP GENELİ', '1-Çalışan giyinme odalarında bench olmaması                           2-Giyinme dolapları ve çalışma alanlarında bulunan dolapların yotalanmamış olması', '1- Kişinin düşmesi, kişinin üzerine dolap düşmesi, acil durumlarda tahliyenin zorlaşması', '1- YGAP Çalışanları', '1- Soyunma dolapları mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1.Soyunma odalarında  yeterli sayıda oturma yeri ve ayakkabılık bulunmalıdır.                                                                     \n2-Soyunma odalarında bulunan tüm dolaplar, raflar duvara en az iki noktadan  sabitlenmelidir.                                                \n3-Sabitlenemeyen dolap ya da raflar ise acil kaçış yollarından uzak, kişilerin üzerlerine düşmeyecek biçimde konumlandırılmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: YGAP GENELİ', '1- EKT işlemi sırasında çalışanın hastaya teması', '1- Elektirik çarpması sonucu yaralanma', '1- YGAP Çalışanları', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1-EKT işlem hazırlığı sırasında hasta sedyedeki bantlarla stabil hale getirilmelidir.                                                          \n2- EKT esnasında hastaya elektrotlara ve diğer iletken nesnelere dokunulmamalıdır.\n2-Hastaya ıslak  ve iletken ortamlarda EKT uygulanmamalı, hastanın göğsünde ıslaklık, jel, ter olmamalı, hastanın göğüsü kurulanmalıdır.\n4- Hastanın ve EKT cihazını kullanan çalışanın üzerinde metal eşyalar bulunmamalıdır.                                                                                           \n5- Ortamda bulunan diğer çalışanlar en az 1 metre uzakta bulunmalıdır.', 'YGAP ÇALIŞANLARI', 'EKT UYGULAMA ESNASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: YGAP GENELİ', '1- Saldırgan davranışta bulunan hastalar', '1- Çalışanlara şiddet sonucu yaralanma', '1- YGAP Çalışanları', '1- Yumuşak oda mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Akli dengesi yerinde olmayan ya da saldırgan davranış gösteren hastalar yumuşak oda da tedavi edilmelidir.                                                                                               2- Yumuşak odadaki hastaya tedavi uygulama esnasında güvenlik eşlik etmeli ve çift hemşire ile odada çalışılmalıdır.                                                                                                                                                          3- Hastalar tedavi edilmeden yatağa sabitleyici aparatlar ile bağlanmalıdır.', 'YGAP ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 1: YGAP GENELİ', '1- Çalışanların temel iş güvenliği eğitimlerine katılmamaları', '1-İş kazası ve meslek hastalıklarının artması', '1- YGAP Çalışanları', '1- Eğitim planı ve eğitim tarihleri çalışanlar ile paylaşılmıştır.', 1, 0, 3, 1, 40, 120, 'C', '1-İşe yeni başlayan çalışanlara hastane tehlike sınıfına göre 16 saat temel iş sağlığı güvenliği eğitimi verilmelidir.\n2-Mevcut çalışanların eğitimleri yılda bir kez tekrarlanmalıdır.\n3-İş güvenliği eğitimi aldırılmayan kişilere iş başı verilmemelidir.\n4-İşe yeni başlayan çalışanlara bölüm sorumluları tarafından en az 2 saat iş başı eğitimi verilmelidir.', 'İŞVEREN V.', 'İLGİLİ PERİYOTLAR \nİLE \nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 1: YGAP GENELİ', '1- Kan ve vücut sıvılarının göz ve cilde temas etmesi', '1-Temas sonucu enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- YGAP Çalışanları', '1-KKD\'ler mevcuttur.                                         2- Çalışanlara KKD önemi ve kullanımı konusunda eğitim verilmektedir.', 1, 0, 6, 6, 3, 108, 'C', '1-Çalışanlar TS EN 455  standardında eldiven, TS EN 166 standardında tam kapalı gözlük ya da yüz siperi, uzun kollu koruyucu önlük  EN 14683 standardında maske vb. gibi kişisel koruyucu donanımlar kullanılmalıdır.                                                                                                                         2- Temas durumunda bölgenin bol su ve sabunla yıkanması sağlanmalıdır.                                                                                                                                    3- Kan ve vücut sıvıları sıçramasına maruz kalma sonrası çalışanın, bulaş kaynağının durumuna göre muayene ve tetkikleri yapılmalıdır.', 'İŞYERİ HEKİMİ \n\n YGAP\nÇALIŞANLARI', 'MARUZİYET OLMASI DURUMUNDA    HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 1: YGAP GENELİ', '1- Kesici delici aletlerin emniyetsiz kullanılması', '1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- YGAP Çalışanları', '1- Kesici delici alet kutuları mevcttur.                2-Çalışanlara kesici delici aletlerin güvenli kullanımı konusunda eğitim verilmektedir.', 1, 0, 6, 6, 3, 108, 'C', '1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                                 3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                                                                                                5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.', 'YGAP ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM 1: YGAP GENELİ', '1-Klima sularının tavandan akması                  2-Klima sularının elektirik ile teması', '1-Kayma düşme sonucu yaralanma            2-Elektirik çarpması', '1- YGAP Çalışanları\n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1-Akan yerler onarılmalı zemine su akması ve elektriğin su ile temas etmesi önlenmelidir.                                                                                                                      3-Islak kaygan zemin uyarı levhaları gerekli alanlarda mutlaka kullanılmalıdır.                                                                            \n4- Alanlar ıslak bırakılmamalı temizlik sonrası mutlaka kurulama yapılmalıdır.', 'FİRMA\nTEMİZLİK ÇALIŞANLARI', '3 AY\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM 1: YGAP GENELİ', '1- YGAP Genel Hastane arası gidiş gelişte hastane aracı kullanılmaması', 'İş kazası geçirme', 'YGAP Bölüm Çalışanları', NULL, 1, 0, 3, 2, 15, 90, 'C', '1- Genel hastaneye gidiş geliş esnasında sadece hastane aracı kullanılmalıdır.\n2- Geliş gidiş esnasında hastane araçları yetkilendirilmiş şoförleri tarafından kullanılmalı, çalışanlar hastane aracını kullanmamalıdır.\n3- Emniyet kemerleri takılı olmalıdır.\n4- Araç şoförü trafik kurallarına uymalıdır.', 'ARAÇ \nŞOFÖRLERİ\nYGAP ÇALIŞANLARI', 'GENEL HASTANEYE\n GELİŞ \nGİDŞLERDE SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 27, 'BÖLÜM 1: YGAP GENELİ', '1-Çalışan hasta ve hasta yakınları iletişim problemleri, fiziksel sözlü şiddet,', '1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma,', '1- YGAP Çalışanları', '1-Panik butonları mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Hasta ve hasta yakınları tarafından çalışanların şiddete uğrayabileceği tüm alanlara sabit panik butonları ilave olarak yaka butonları temin edilmelidir.                                                                                                                                                                                                         2- Şiddet riskinin yoğun olduğu alanlarda butonlara ilave olarak sabit güvenlik personeli  bulundurulmalıdır.                                         \n3- Çalışanlara iletişim, stres yönetimi ve öfke kontrolü ile mesleki bilgi ve becerilerini arttırıcı eğitimler verilmelidir.', 'İŞVEREN V.\nİŞ GÜVENLİĞİ UZMANI', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 28, 'BÖLÜM 1: YGAP GENELİ', '1-Hasta taşıma veya pozisyon verme sırasında ergonomik olmayan davranışlar', '1-Kas-İskelet sistemi rahatsızlıkları, meslek hastalığı veya işle ilgili hastalıklar                                                             2- iş kazaları', '1- YGAP Çalışanları', '1-Çalışanlara Ergonomik çalışma eğitimi verilmektedir.', 1, 0, 3, 3, 7, 63, 'D', '1- Hasta taşıma için kaydırma örtüsü, hasta kaldırma lifti, tekerlekli sandalye, sedye gibi ekipmanlar kullanılmalıdır.                                             \n2- Yatak kenarlıkları kaldırılmalı, frenlerin kilitlenmelidir. Kateter, dren ve monitör bağlantılarının sabitlenmelidir.                                                                                                     3- Hastalara pozisyon verme ve taşıma esnasında en az 2 kişi tarafından yapılmalı, zemin kuru olmalıdır.', 'YGAP ÇALIŞANLARI    TAŞIMA ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 29, 'BÖLÜM 1: YGAP GENELİ', '1-Sabitlenmemiş dolap ve raflar', '1-Devrilme, düşme ya da çarpma sonucunda vücut bölümlerinin sıkışması, yaralanması', '1- YGAP Çalışanları', '1-Birçok dolap ve raf sabitlenmiştir.', 1, 0, 3, 3, 7, 63, 'D', '1-Sabitlenmemiş doalp ve raflar en az iki noktadan sabitlenmelidir.\n2-Düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.\n3-Ağır malzeme ve ekipmanlar yüksek istiflenmemeli, dolap üzerine malzeme konulamamlıdır.                                    \n4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.', 'İŞVEREN V.\nYGAP ÇALIŞANLARI', '3 AY \n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 30, 'BÖLÜM 1: YGAP GENELİ', '1-Makinelerin gövde topraklama ölçümlerinin yapılmamaış olması.                                              2-Yıpranmış, ezilmiş kablolar', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, elektrik yanıkları, ölüm,', '1- YGAP Çalışanları', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1-Makinelerin gövde topraklama ölçümleri yaptırılmalı, belgelendirilmelidir.\n2-Cihazlar durdurulmadan ve akım kesilmeden bakım, arıza onarım ve müdahaleler yapılmamalıdır.\n3-Yıpranmış, ezilmiş, soyulmuş ve izolasyonsuz kablolar değiştirilmelidir.                                                                                                                           4- Makikenelerin elektrik kabloları çift izolasyonlu olmalıdır.', 'İŞVEREN V.\nYGAP ÇALIŞANLARI', '3 AY \n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 31, 'BÖLÜM 1: YGAP GENELİ', '1-Elektrik panolarının, pano odalarının yangın dolaplarının önlerinin kapatılmış olması', '1-Acil durumlarda hızlı müdahalenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Malzeme, makine, temizlik arabası vb. pano ve  yangın dolaplarının önlerini kapatmaması sağlanmalıdır.\n2-Panolara erişim için en az 80 cm genişlikte ulaşım yolları sağlanmalıdır.\n3-Pano üzerlerine uyarı etiket ve işaretleri asılmalıdır.', 'YGAP ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 32, 'BÖLÜM 1: YGAP GENELİ', '1- Elektrik kablolarında yırtık, izolasyon bozukluğu olması,                                                                                   2- Ekli kabloların kullanılması', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm', '1- YGAP Çalışanları', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Elektrik kablolarında yırtık, izolasyon bozlukluğu vb. olmamalı, olan kablolar kullanılmamalı değiştirilmelidir.                          \n2- Elektrik kabloları ağır malzeme ya da ekipmanların altına konulmamalı, kabloların ezilmesi önlenmelidir.                                       \n3- Kablolarda olan izolasyon açıklıkları izole bant ile kapatılmamalı, ekli kablolar değiştirilmelidir.', 'İŞVEREN V.\nYGAP ÇALIŞANLARI', '3 AY \n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 33, 'BÖLÜM 1: YGAP GENELİ', '1-Sivri, delici, kesici, paslı makine ve ekipmanlar', '1-Yaralanma sonucu tetanos hastalığına yakalanma', '1- YGAP Çalışanları', NULL, 1, 0, 3, 3, 7, 63, 'D', '1-Paslı alet ve ekipmanlar yenileriyle değiştirilmeli, paslanmaz malzemeler kullanılmalıdır.\n2-Sivri, delici, kesici, paslı makine ve ekipmanlara eldivensiz temas edilmemelidir.\n3-Yeni başlayan ya da aşısı eksik olan çalışanlara tetanos aşısı yapılmalı, 5 yılda bir ya da yaralanma durumunda tekrar aşı yapılmalıdır.', 'İŞVEREN V.\nİŞYERİ HEKİMİ', '3 AY\nİLGİLİ PERİYOTLAR İLE SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 34, 'BÖLÜM 2: YEMEKHANE MUTFAK', '1-Yemekhane elektirik panosu önünde yalıtkan paspas olmaması             2-Yemekhane elektirik panosunun kilitsiz olması', '1- Elektrik çarpması sonucu yaralanma', '1- YGAP Çalışanları', NULL, 1, 0, 3, 6, 15, 270, 'B', '1-Yemekhane içinde bulunan elektrik panosu kaldırılmalıdır.     \n2- Panoya 30 Ma kaçak akım rölesi takılmalıdır.                                                 \n3-Elektirik panoları önüne yalıtkan paspas konulmalıdır.                                          4-Elektirik panoları her zaman kilitli olmalı, yetkisiz kişilerin erişimi engellenmelidir.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 35, 'BÖLÜM 2: YEMEKHANE MUTFAK', '1- Mutfaktaki tüm elektirikli ekipmankarın(benmarin,buzdolabı,fırın vb.) topraklama ölçümlerinin tekrarlanmaması', '1- Elektirik çarpması sonucu yaralanma', '1- YGAP Çalışanları', '1- Topraklama ölçümleri mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1- Elektrik tesisatının, panoların, fiş priz sistemlerinin topraklama ölçümleri yıllık olarak yetkili elektrik mühendislerine yaptırılmalıdır.                                                                                                                                                         2- Benmariler dahil tüm elektrikli mutfak ve yemekhane cihazlarının ve taşıma araçlarının gövde topraklama ölçümleri yıllık olarak yaptırılmalı ve kayıt altına alınmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 36, 'BÖLÜM 2: YEMEKHANE MUTFAK', '1-Mutfak ve yemekhane personelinin aynı kıyafeti hastane genelinde kullanması', '1-Enfeksiyon hastalıklarına yakalanma', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Yemekhane ve mutfak  personeli önlük, maske ve bone kullanmaktadır.', 1, 0, 3, 10, 7, 210, 'B', '1-Yemekhane ve mutfak  personeli  iş kıyafetini ve ayakkabı/terliğini sadece çalışma alanında kullanmalı, bu ekipmanlar ile çalışma alanı dışına çıkılmamalıdır.                                                                                                                                                  2- Yemekhane ve mutfak  personeli önlük bone ve eldiven kullanmadan çalışmamalıdır.', 'YEMEK FİRMASI   ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 37, 'BÖLÜM 2: YEMEKHANE MUTFAK', '1-Yemek dağıtılan alanların kirli olması, yağ birikimi olması', '1-Enfeksiyon hastalıklarına yakalanma', '1- YGAP Çalışanları\n2- Hastalar\n3- Diğer ilgili kişiler', '1-Ortam temizliği günlük yapılmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1-Paslanmaz tezhgahlar, benmariler ve kullanılan aletler günlük olarak temizlenmelidir.                                                                                                                                                     2-Zemin günlük olarak düzenli temizlenmeli , duvar yüzeyleri haftalık olarak düzenli  temizlenmeli  ve  asma tavan aylık olarak  düzenli temizlenmelidir.', 'TEMİZLİK ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 38, 'BÖLÜM 2: YEMEKHANE MUTFAK', '1-Makina ve ekipmanların elektrik aksamına su veya diğer sıvıların temas etmesi', '1- Elektrik çarpması                       2-Ölüm', '1- YGAP Çalışanları\n2- Diğer ilgili kişiler', '1-Kaçak akım koruma  rölesi mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Mutfakta kullanılan tüm elektrikli aletlerin kabloları çift izalasyonlu olmalıdır.                                        \n2- Sabit kablolar kablo kanalı içerisine alınmalıdır.                                                                                                         3- Elektrik kabloları sağlam olmalı, ek ya da izole bant ile bantlanmış kısımlar bulunmamalıdır.                                                                                                                                                    4- Elektrikli ekipmanlar su ve kimyasal içerikli ürünlerden uzakta saklanmalı ve kuru elle kullanılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 39, 'BÖLÜM 2: YEMEKHANE MUTFAK', '1-Çöp kovalarının açık olması', '1-Enfeksiyon', '1- YGAP Çalışanları\n2- Diğer ilgili kişiler', '1-Çöp kovaları mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1-Çöp kovalarının kapağı her daim kapalı olmalı, sineklenme olmayacak şekilde düzenli boşaltılmalıdır.                                                                                                                                      2-Pedalı bozuk olan çöp kovaları onarılmalı veya değiştirilmelidir.                                           3-Atık odalarının kapıları kapalı tutulmalıdır. Kapıya ait hidrolik yay sistemleri sökülmemelidir.', 'YEMEK FİRMASI   ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 40, 'BÖLÜM 2: YEMEKHANE MUTFAK', '1-Mutfak çalışanlarının  sağlık kontrollerinin yapılmamış olması', '1- Bulaşıcı hastalıklar ve salgın hastalıkların diğer çalışanlara bulaştırma', '1- YGAP Çalışanları\n2- Hastalar\n3- Diğer ilgili kişiler', '1-Çalışanların işe giriş raporları ve periyodik kontrolleri yaptırılmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1-Mutfak ve yemekhane çalışanlarının 6 ayda 1 portör muayeneleri yapılmalıdır.\n2- Hepatit taramaları ve akciğer grafileri yılda bir tekrarlanmalıdır.   \n3- Bölüme yeni başlayan çalışanlar sağlık taramaları yapılmadan işe başlatılmamalıdır.                                                                                                                                                                                                           4-Sonucu uygun olmayanlar çalışanlar mutfak yemekhane bölümünde çalıştırılmamalıdır.', 'YEMEK FİRMASI               İŞYERİ HEKİMİ', '6 AYDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 41, 'BÖLÜM 2: YEMEKHANE MUTFAK', '1- Yemekhane zeminde engel bulunması', '1- Takılıp düşme sonucu yaralanma', '1- YGAP Çalışanları', NULL, 1, 0, 6, 3, 7, 126, 'C', '1-Zemindeki engeller körlenmelidir.                                                        \n2-Zeminde bulunan engeller etrafına bariyer çekilerek çalışanların takılıp düşmesi önlenmelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 42, 'BÖLÜM 2: YEMEKHANE MUTFAK', '1- Hasta yemek dağıtım penceresinde koruyucu bulunmaması', '1- Mekanizmanın düşmesi sonucu yaralanma', '1- YGAP Çalışanları\n2- Hastalar', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Mekanizmanın kendi kendine boşalma riskine karşı tutucu ya da fotosel takılmalıdır.                                                              \n2- Kaldırma indirme esnasında panelin altına el sokulmamalıdır.\n3- Kaldırma sisteminin periyodik kontrolleri en geç yılda bir yapılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 43, 'BÖLÜM 2: YEMEKHANE MUTFAK', '1-Kuru gıda depolarında haşere ilaçlamasının olmaması', '1-Sinek, böcek, fare gibi zararlı canlıların çoğalması ve hastalık yayması', '1- YGAP Çalışanları\n2- Hastalar\n3- Diğer ilgili kişiler', '1-Bir çok alanda ilaçlama kutuları mevcuttur.', 1, 0, 3, 1, 15, 45, 'D', '1-İlaçlama kutusu olmayan kuru gıda depolarına kutular konulmalıdır.                                                        \n2- 3 ayda 1 zararlının türüne göre ilaçlama yapılmalıdır.\n3- Zararlı canlıların yemekhane ve mutfağa ulaşabilecekleri delik ve açıklıklar kapatılmalıdır.', 'FİRMA', '3 AYDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 44, 'BÖLÜM 3: DEPO ECZANE', '1- Narkotik ilaç dolabının cam olması', '1- Narkotik ilaçların kullanımı sonucu bağımlılık sakatlık ya da ölüm', '1- YGAP eczane çalışanları', NULL, 1, 0, 6, 3, 15, 270, 'B', '1- Narkotik ilaçların bulunduğu dolaplar metal , kitlitlenebilir, çift anahtarlı olmalıdır.        \n2- Narkotik ilaç dolaplarının üzerinde anahtar bırakılmamalı, anahtarlar bölüm sorumlularına zimmetlenmelidir.                                                                                                                            3- Bölümlere gelen narkotik ilaçlar kayıt altına alınmalı, her vardiya değişiminde sayım yapılmalı, eksik çıkması durumunda yetkililere haber verilmelidir.', 'İŞVEREN V.\nBİRİM SORUMLUSU', '2 AY \nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 45, 'BÖLÜM 3: DEPO ECZANE', '1- Raf önü tutucuların bulunmaması                                           2- Endüstriyel rafların sabitlenmemesi', '1- Malzeme düşmesi sonucu  yaralanma, ezilme, sıkışma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', '1-Bazı bölümlerde volanlı ray sistemi mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1- Tüm arşiv alanlarında volanlı raylı sistem kullanılımalıdır.\n2- Rafların önüne malzemelerin devrilmesini engelleyecek raf önü tutucular kullanılmalıdır.                                                                    \n3-  Endüstriyel raflar en az iki noktadan  sabitlenmeli, düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 46, 'BÖLÜM 3: DEPO ECZANE', '1- Depolarda yüksek istifleme yapılması', '1- Malzeme düşmesi sonucu  yaralanma, ezilme, sıkışma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 6, 3, 15, 270, 'B', '1- İstif yüksekliği en fazla 3 metre olmalıdır.\n2- Malzemeler düzenli istiflenmeli, devrilmeyecek şekilde sabitlenerek istif yapılmalıdır.\n3- Devrilme riski olan malzemeler 1,5 metreden yüksek istiflenmemelidir.\n4- Stok girişi yapılmayan malzemeler depoya alınmamalıdır.\n5- Ağır malzemeler en altta istiflenmelidir.', 'DEPO ECZANE ARŞİV ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 47, 'BÖLÜM 3: DEPO ECZANE', '1- Endüstriyel rafların periyodik kontrollerinin yapılmaması', '1- Rafların devrilmesi sonucu yaralanma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 6, 15, 270, 'B', '1- Raflar  TS EN 15635 standartalarına uygun azami kontrol süresi geçmeden periyodik kontrolleri  yapılmalıdır.    \n2- Metal kısımların dayanıklılık ve metal yorgunluğu testleri yaptırılmalıdır. \n3- Bağlantı noktaları, çatlak, aşınma, taşıyıcı kısımlar 3 ayda bir kontrol edilmeli, eksiklikler giderilmelidir.', 'İŞVEREN V.', 'İLGİLİ PERİYOTLAR İLE \nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 48, 'BÖLÜM 3: DEPO ECZANE', '1- Raflardan malzeme almak için eskoba merdiven ya da el merdiveni kullanılması', '1-Merdivenden düşme sonucu yaralanma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', '.', 1, 0, 6, 6, 7, 252, 'B', '1- Raflardan malzeme almak için eskoba ya da el merdivenleri kullanılmamalı, TS EN 131 standartlarına uygun merdivenler temin edilmelidir.                                                                                   \n2- Kullanılacak merdiven en az 1 metre yükseklikte korkuluklu, 47 cm de ara korkuluklu, platformlu, yere sabitlenebilen tekerlek frenleri olan yapıda olmalıdır.  \n3-Platformlu merdivenlerin giremeyeceği dar raf aralarında kullanılan el merdivenlerinin ayaklarına, merdivenin kaymasnı önlemek için destekler konulmalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 49, 'BÖLÜM 3: DEPO ECZANE', '1- Raf arası mesafelerin yetersiz olması', '1- Çarpma, sıkışma, düşme sonucu yaralanma', '1-Arşiv çalışanları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Raflar arası boşluk en az yaya geçişi için 80 cm, merdiven geçmesi için en az 120 cm olacak şekilde iş organizasyonu yapılmalıdır.                                                  \n2- Depolama alanı değişikliği yapılmalıdır.\n3- Raf yerleşim planı hazrılanmalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 50, 'BÖLÜM 3: DEPO ECZANE', '1-KKD’lerin eksik olması,                           2- KKD\'lerin çalışanlar tarafından kullanılmaması', '1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması', '1- Depo, eczane, arşiv çalışanları', NULL, 1, 0, 6, 6, 7, 252, 'B', '1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan kkd\'ler temin edilmelidir.\n2- Çalışanların maskeleri TS EN149 standardında uygun olmalıdır.                                                                                                                     3-Çalışanların göz koruyucuları TS EN 166 standardına uygun ve tam kapalı tip olmalıdır.                                                                                                                             4-Çalışanların iş eldivenleri TS EN 388 standartına uygun olmalıdır.                                                                                                                                5- Çalışanların iş ayakkabıları, koruyucu burun ve taban TS EN ISO 20345 standartına uygun olmalıdır.\n6- Çalışanların baretleri TS EN 397 standartına uygun olmalıdır\n7-Çalışanlar sahada kişisel koruyucu ekipmanlarını eksiksiz şekilde kullanmalıdırlar.', 'İŞVEREN V.  \n\nDEPO ECZANE ARŞİV ÇALIŞANLARI', '2 AY\n\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 51, 'BÖLÜM 3: DEPO ECZANE', '1- Tavan aydınlatmalarına yakın istifleme yapılması', '1-Yangın çıkması', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', '1- Yangın söndürme sistemleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Aydınlatma armatürleri ile malzemeler arasında 50-100 cm boşluk bırakılmalıdır.                           \n2- Aydınlatma armatürleri ısı çıkarmyan led aydınlatma ya da etanj aydınlatmalar kullanılmalıdır.\n3- Yangın söndürücüler her zaman hazırda bulundurulmalıdır.', 'İŞVEREN V.  \n\nDEPO ECZANE ARŞİV ÇALIŞANLARI', '2 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 52, 'BÖLÜM 3: DEPO ECZANE', '1- Rafların taşıma kapasitesinin bilinmemesi                                                         2- Raflara hatalı istifleme yapılması', '1- Rafların fazla yüklenmesi sonucu devrilmesi', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 6, 3, 7, 126, 'C', '1- Her rafa maksimum taşıma kapasitesi, görünür okunabilir şekilde asılmalıdır.\n2- Raflara taşıma kapasitesinin %10 altı ağırlıktaki malzemeler istiflenmelidir.\n3- Yükler raf yüzeylerine eşit dağıtılmalıdır.\n4- Malzemeler düzenli, devrilmeyecek şekilde istiflenmelidir.', 'İŞVEREN V.  \nDEPO ECZANE ARŞİV ÇALIŞANLARI', '3 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 53, 'BÖLÜM 3: DEPO ECZANE', '1- Transpaletlerin periyodik kontrollerinin yapılmaması', '1- Yüklerin düşmesi, devrilmesi sonucu yaralanma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Manuel transpaletlerin periyodik kontrolleri  TS EN ISO 3691 serisi, FEM 4.004 standartlarında belirtilen kriterlere uygun olarak yapılmalıdır.                                                                                                                          2- Periyodik kontrolleri yapılmamış manuel  transpaletler kullanılmamalıdır.', 'İŞVEREN V.', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 54, 'BÖLÜM 3: DEPO ECZANE', '1- Kolilerin, dosyaların el ile taşınması', '1-Düşme, devrilme  sonucu yaralanma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', '1- Çalışanlara elle taşıma teknikleri hakkında eğitim verilmiştir.', 1, 0, 6, 6, 3, 108, 'C', '1- Erkekler 25 kg üzerinde kadınlar 15 kg üzerinde yük kaldırmamalıdır.                                                                                   \n2- Dengesiz devrilme riski olan yükler sabitlenerek taşınmalıdır.\n3- Yükler taşıma teknikleri kullanılarak taşınmalıdır.\n4- Yükler görüş alanını kapatmayacak şekilde taşınmalıdır.                                                                                                 5- Depo, eczane ve arşivde çalışan personellere yüksekte çalışma, depolarda uygun istifleme ve ergonomi ve elle taşıma eğitimi verilmelidir.', 'İŞ GÜVENLİĞİ UZMANI  \nDEPO ECZANE ARŞİV ÇALIŞANLARI', '3 AY\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 55, 'BÖLÜM 3: DEPO ECZANE', '1- Raflarda sivri köşelerin bulunması', '1- Yaralanma                  2- Çarpma', '1- Depo, eczane, arşiv çalışanları     \n2- Diğer ilgili çalışanlar', NULL, 1, 0, 3, 10, 3, 90, 'C', '1-Tüm depo , eczane , arşiv alanlarında bulunan rafları köşelerindeki sivri uçlar için köşe koruyucular monte edilmelidir.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 56, 'BÖLÜM 4: BAHÇE OTOPARK', '1-Otomatik sulama sistemi çalışırken çim aydınlatma armatürlerine su temas etmesi', '1-Eletkriğin su ile teması sonucu çarpılma', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1-Çim aydınlatma armatürleri güneş enerjili lamba vb. elektrik kullanmayan sistemler ile değiştirilmelidir.\n2- Sulama başlıklarının açıları düzeltilmeli,  çim aydınlatma armatürlerine ve kablolarına su  temas etmeyecek şekilde konumlandırılmalıdır.                                                                                                                                                   3- Elektriğin su ile teması önlenmeli, elektrik kabloları çift izolasyonlu olmalıdır.\n4- Çimlerin etrafı tel çit vb. malzemeler ile çevrelenmeli, insan geçişi önlenmelidir.\n5- Elektrik ile ilgili uyarı levhaları asılmalıdır.', 'FİRMA', '2 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 57, 'BÖLÜM 4: BAHÇE OTOPARK', '1-Hastane ve çevresinde yılan vb. sürüngenler çıkması', '1-Isırılma, zehirlenme,alerji', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 6, 2, 15, 180, 'C', '1-Hastane çevresinde dış alanda yabancı otlar temizlenmelidir.                                                                                2-Bina çevresinde bina boyunca devam eden boşluk kısımlarda sürüngen için bakanlıktan izinli yapışkan plaka kullanılmalıdır.                                                                                     3-Kapı altlarında yalıtım ve kapı altı fırçası takılması ve sinekliksiz pencerelere sineklik takılmalıdır.                                                                                                                                                                                                                4- Bahçe içerisinde ölü bölge yaratan bitkiler budanmalı ya da ortadan kaldırılmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 58, 'BÖLÜM 4: BAHÇE OTOPARK', '1-Otopark alanına araçların uygunsuz park edilmesi', '1-Araçların çalışanlara çarpması sonucu yaralanma                                 2- Acil durumlarda tahliyenin zorlaşması', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Güvenlik kameraları mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1- Yol kenarlarına, yaya yollarına park alanı olarak belirlenmemiş alanlara araçların park etmesini önlemek için mantar, bariyer vb. konulmalıdır.  \n2- Uyarı levhaları artırılmalıdır.   \n3- Araçlar acil durumlarda tahliyenin rahat sağlanması için çıkış yönünde park etmeleri sağlanmalıdır.', 'YGAP\nÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 59, 'BÖLÜM 4: BAHÇE OTOPARK', '1- Kuru otların bulunduğu alanlarda sigara içilmesi, cam vb. çöplerin atılması', '1-Yangın çıkması', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Çöp ve kuru otların temizliği düzenli aralıklarla yapılmaktadır', 1, 0, 3, 2, 15, 90, 'C', '1-Kuru otlar düzenli aralıklar ile temizlenmelidir.\n2- Cam şişe, izmarit ve yanıcı atıklar  düzenli aralıklarla temizlenmelidir.\n3-Kuru ot bulunan alanlarda  ″Sigara içilmez- Yangın riski″ uyarı tabelalarının görünür noktalara konulmalıdır.                                               \n3- Sigara sadece izin verilen alanlarda içilmelidir.  \n4-Yangına dayanıklı ve kapaklı çöp kutuları sağlanmalıdır.', 'FİRMA', 'PERİYODİK OLARAK SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 60, 'BÖLÜM 4: BAHÇE OTOPARK', '1-Hız sınırı levhalarının yetersiz olması', '1-İş kazası yaşanması sonucu yaralanma', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Bir çok bölgede hız sınırı levhaları mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1-Bahçe ve otopark giriş-çıkış noktalarına ve kritik kavşak noktalarına eksik olan alanlara  hız sınır tabelaları yerleştirilmelidir.                                                                                                                         2-Hastane sınırları içinde açık alanlarda 30 km/s geçmemelidir.\n3- Araç trafiğine yönelik tabelalar (hız sınırı, yönlendirme vb.) Ortalama 2,0 – 2,5 m yüksekliğe asılmalıdır.', 'FİRMA', '3 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 61, 'BÖLÜM 4: BAHÇE OTOPARK', '1-Peyzaj alanları için kullanılan su deposunun etrafınının çevrili olmaması', '1-Su deposuna yetkisiz erişim sonucu iş kazaları yaşanması', '1-Çalışanlar                                                                                3- diğer ilgili kişiler', NULL, 1, 0, 6, 2, 7, 84, 'C', '1-Sulama deposunun çevresi en az 1,5–2 metre yüksekliğinde tel çit veya bariyerle çevrilmelidir.\n2-Bakım personeli dışında kimsenin erişemeyeceği şekilde kilitli kapı kullanılmalıdır.\n3-Çevre güvenliği için uyarı tabelalarının yerleştirilmelidir. Yetkisiz Girmek Yasaktır” ve “Dikkat! Sulama Suyu Deposu” uyarı tabelaları yerleştirilmelidir.\n4-Gece veya düşük görüş koşullarında riskleri önlemek için yeterli aydınlatma sağlanmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 62, 'BÖLÜM 4: BAHÇE OTOPARK', '1-Su tankı dışında sivri ve paslı alanlar bulunması                              2-Su tankının patlamış olması', '1- Paslı alanlara temas sonucu yaralanma', '1- YGAP Çalışanları', NULL, 1, 0, 6, 2, 7, 84, 'C', '1-Tankın sivri köşelerine yakın olan merdiven köşelerden uzaklaştırılmalıdır.      \n2-Patlamış olan depo tamir edilmeli ya da değiştirilmelidir.\n3- Tank boyanmalı, pas korozyon oluşumu önlenmelidir.', 'FİRMA', '3 Ay', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 63, 'BÖLÜM 4: BAHÇE OTOPARK', '1-Bahçede ki rögarların tıkanması, kırılması yerinden çıkması', '1-Takılma, düşme, kayma, su birikintisi  sonucu yaralanma', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 2, 7, 42, 'D', '1- Rögar kapakları  yılda en az 2 kez kontrol edilmeli,  kırık, gevşemiş, yerinden oynamış rögar kapakları değiştirilmelidir.\n2-Yaprak, toprak, çöp gibi malzemelerle tıkanan mazgallar temizlenmeli, tıkanması önlenmeldir.', 'FİRMA', 'YILDA 2', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 64, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Patlamadan korunma dokümanının olmaması', '1- Parlama, patlama yangın meydana gelmesi', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 40, 360, 'B', '1- Patlamadan korunma dokümanı hazırlanmalıdır. \n2- Patlayıcı ortam oluşabilecek alanlar işaretlenmeli ve patlamadan korunma dokümanında belirlenen zone ‘lara göre kullanılması gereken exproof ekipmanlar temin edilmelidir.\n3- Patlayıcı ortam oluşabilecek alanlar “EX Patlayıcı Ortam, Ateşle Yaklaşma” vb. levhalar ile işaretlenmelidir.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 65, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Doğalgaz kazan dairesinde elektrik tesisatlarının exproof olmaması', '1-Doğalgaz kaçağı olması durumunda parlama patlama yangın meydana gelmesi', '1- YGAP Çalışanları \n2- Diğer ilgili kişiler', '1- Bazı aydınlatmalar exproof özelliktedir.\n2- Doğal havalandırma sağlanmaktadır.', 1, 0, 3, 3, 40, 360, 'B', '1- Flanş, vana pompa vb. doğalgaz boşalma kaynaklarının en az 1 metre yarı çapında bulunan Pano, fiş priz, aydınlatma, gaz dedektörleri, solenoid valf vb. tüm elektrik sistemleri kıvılcım çıkarmayan exproof özellikte olmalıdır.\n2- Elektrik kabloları çift izolasyonlu olmalıdır.\n3- Elektrik kabloları açıkta olmamalı, yanmaz kablo kanalları içerisine alınmalıdır.\n4- Exproof ekipmanların en geç yılda bir kez periyodik kontrolleri TS EN 60079 stanrdardına göre \"ATEX\" belgeli kişiler tarafından yapılmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 66, 'BÖLÜM 5: TEKNİK MAHALLER', '1-Doğalgaz ünite kapısının kilitsiz olması                              2-Yangın söndürücü olmaması                            3-Uyarı levhalarının olmaması', '1- Yangına müdahale edilememesi sonucu şiddetin artması', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 2, 40, 240, 'B', '1-Doğalgaz ünite kapısı kilitli olmalı, yetkisiz kişilerin tank sahasına girmesi önlenmelidir.           \n2- Ünite girişine nötralizatör konulmalı, vücuttaki statik elektrik boşaltılmadan ünite içine girilmemlidir.                                                \n3-Ünite çevresinde en az bir adet 50 kg\'lik  yangın söndürücü (tozlu veya köpüklü) bulundurulmalıdır.                                           \n4-Ünite çevresine sigara izmariti vb. girmesini önlemek için tabandan 15 cm topukluk yapılmalıdır.\n5- Ünite çevresine \"SİGARA İÇİLMEZ\", \"ATEŞLE YAKLAŞILMAZ\"  vb. uyarı levhaları yerleştirilmelidir.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 67, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Mazot tankının sızdırmazlık, katodik koruma ve topraklama ölçümlerinin yapılmaması', '1- Parlama, patlama yangın meydana gelmesi', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 2, 40, 240, 'B', '1- Katodik koruma kontrolleri en geç yılda bir yapılmalıdır.\n2- Mazot tankının yılda en geç bir kez sızdırmazlık testleri yapılmalıdır.\n2- Borular korozyona karşı korunmalıdır.\n2- Tank topraklama ölçümleri yılda bir yaptırılmalı, belgelendirilmelidir.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 68, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Yangın panel kablolarında yanıcı malzeme kullanılmış olması', '1- Yangın durumunda kablonun kopması ya da erimesi sonucu şiddetin artması', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Yangın algılama sisteminin periyodik kontrolü mevcuttur.', 1, 0, 6, 2, 15, 180, 'C', '1- Yangın panel elektrik kabloları FE180 özellikte olmalıdır.\n2- Yangın paneli elektrik kabloları 180 dakika yangına dayanıklı olmalıdır.\n3- Elektrik kabloları halojen free özellikte olmalıdır.\n4- Yangın paneli elektrik kabloları mekanik darbelere karşı korunmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 69, 'BÖLÜM 5: TEKNİK MAHALLER', '1-Elektirik pano   odalarının zemininde  açıklık olması           \n2-Haşere ilaçlama olmaması', '1- Haşerelerin elektrik kablolarını kemirmesi sonucu elektrik yangınları meydana gelmesi', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Bir çok oda da ilaçlama mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1-Elektrik pano odalarında fare vb. haşerlerin girebileceği açıklıklar kapatılmalıdır.                                                      \n2- İlaçlama kutusu olmayan pano odalarına kutular konulmalıdır.                                                        2- 3 ayda 1 zararlının türüne göre ilaçlama yapılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 70, 'BÖLÜM 5: TEKNİK MAHALLER', '1-Çalışanların asansörü uygunsuz kullanması', '1- Kabin kapısına sıkışma ya da kabin içinde iş kazası yaşanması sonucu yaralanma', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Asansörlerin kapı fotoselleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Çalışanlar asansör kapıları tam açılmadan asansörlere binmemeli ya da inmemelidir.                                                                    \n2- Kapanma aşamasında ki kapılara el ile müdahale edilmemeli, kapı fotoselleri aktif olmalıdır.                                                                                            \n3- Asansör kullanılırken sıkışma riski olan elbise çanta vb. malzemelere dikkat edilmeli, kapıdan en az yarım metre uzakta durulmalıdır.                                                                              \n4- Asansör içinde şakalaşma yapılmamalıdır.                                                                   5- Asansörlere inip binerken yavaş haraket edilmemelidir.', 'YGAP ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 71, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Asansörlerin arızalanması, bozulması', '1-Kabinin düşmesi ya da asansörün kat arasında kalması sonucu sıkışma yaralanma, ölüm', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Asansörlerin kontrol ve bakımları yapılmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1- Asansörlerin arızalanması ya da bozulması durumunda, hemen acil durum ziline basılmalı, acil durum zil sesi tüm katlardan duyulabilecek seviyede olmalıdır.                                                            \n2- Asansörün kat arasında kalması durumunda, arıza giderilmeden ve kabin kata güvenli tam yanaşmadan asansör içinden kimse indirilmemeli, kimse kendi çabasıyla çıkmaya çalışmamalıdır.                                                                    \n3- Bozulan asansörlere sadece yetkili kişiler tarafından müdahale edilmelidir.                                                                     4- Bozulan asansörün etrafı yetkililer tarafından çevrenmeli, insanların yaklaşması önlemelidir.                                                                            \n5- Acil durum zilleri her zaman çalışır durumda olmalıdır.', 'FİRMA', 'ARIZA DURUMUNDA\nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 72, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Elektrik pano odalarında sulu sprink sistemi kullanılması', '1- Elektrik çarpması sonucu yaralanma', '1-YGAP Çalışanları \n2- Diğer ilgili kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Elektrik yangınlarında sulu sistemler kullanılmamalıdır.\n2- Elektrik panolarına FM200, NOVEC 1230 vb. otomatik söndürme sistemleri kurulmalıdır.\n3- Pano içinde oluşabilecek kıvılcımlar otomatik olarak söndürülmelidir.\n4- Otomatik söndürme sistemi olmayan pano odalarında karbondioksitli yangın söndürücüler ya da kuru kimyevi tozlu yangın topları bulundurulmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 73, 'BÖLÜM 5: TEKNİK MAHALLER', '1-Mazot tankı kapısının kilitsiz olması                              2-Yangın söndürücü olmaması                            3-Uyarı levhalarının olmaması', '1- Yangına müdahale edilememesi sonucu şiddetin artması', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 1, 40, 120, 'C', '1-Tank kapısı kilitli olmalı, yetkisiz kişilerin tank sahasına girmesi önlenmelidir.                                                           \n2-Tank çevresinde en az bir adet 50 kg\'lik  yangın söndürücü (tozlu veya köpüklü) bulundurulmalıdır.                                           \n3-Tank çevresine sigara izmariti vb. girmesini önlemek için tabandan 15 cm topukluk yapılmalıdır.\n4- Tank çevresine \"SİGARA İÇİLMEZ\", \"ATEŞLE YAKLAŞILMAZ\"  vb. uyarı levhaları yerleştirilmelidir.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 74, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Çatılarda açıklıklar bulunması', '1- Yüksekten düşme sonucu yaralanma', '1- YGAP Çalışanları', '1- Çatıya çıkış kartlı sistem mevcuttur.', 1, 0, 3, 1, 40, 120, 'C', '1-Çatıda yüksekten düşmeye sebep olabilecek açıklıklara en az 1 metre yüksekliğinde 47 cm de bir ara bölmeli, 125 kg yüke dayanıklı korkuluk yapılmalıdır.\n2- Yetkisiz ve görevi olmayan kişiler çatıya çıkmamalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 75, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Doğalgaz kazanlarının periyodik kontrollerinin tekrarlanmaması', '1-Doğalgaz kaçağı olması durumunda parlama patlama yangın meydana gelmesi', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Doğalgaz kazanlarının periyodik kontrol raporları mevcuttur.', 1, 0, 1, 3, 40, 120, 'C', '1- Doğalgaz kazanlarının periyodik kontrolleri en geç yılda bir kez TS EN 303 TS 430, TS 497, TS EN 14394+A1, TS EN 12828+A1 standartlarına uygun olarak tekrarlanmalıdır.\n2- Kazanların hidrostatik basınç deneyleri, en yüksek çalışma basıncının 1,5 katı ile yapılmalıdır.\n3- Doğalgaz kazanının manometreleri her zaman çalışır durumda olmalı, en yüksek çalışma basıncı işaretlenmiş olmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 76, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Doğalgaz kaçakları oluşması', '1-Doğalgaz kaçağı olması durumunda parlama patlama yangın meydana gelmesi', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Doğal havalandırma sağlanmaktadır. \n2- Kazan dairesi girişinde acil durudurma düğmesi mevcuttur.', 1, 0, 3, 1, 40, 120, 'C', '1- Kazan dairesine doğalgaz kaçaklarına karşı havalandırma menfezleri her zaman açık olmalıdır.\n2- Gaz dedektörleri her zaman aktif ve çalışır durumda olmalıdır.\n3- Gaz ana vanasının yerini gösteren plaka bina girişinde kolayca görülebilecek bir yere asılmalıdır.\n4- Kazan dairesi girişine nötralizatör konulmalı, vücuttaki statik elektrik boşaltılmadan ünite içine girilmemlidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 77, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Asansörlere taşıma kapasitesinin üzerinde insan binmesi', '1- Taşıma kapasitesinin aşılması sonucu kabinin düşmesi, yaralanma ölüm', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Bir çok asansörde taşıma kapasiteleri mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1 -Asansör taşıma taşıma kapasitesini ve maksimum kişi sayısını gösteren tabela kapılarda ya da kabin içinde görünür ve okunabilir olmalıdır.\n2-Taşıma kapasitesinin en fazla % 10 altında insan taşınmalı, kapasitenin üzerinde insan taşınmamalıdır.                                                               \n3- Asansör taşıma kapasitesi aşıldığında asansör sesli uyarı vermeli, kabin kapıları kapanmamalı ve asansör çalışmamalıdır.                                                  \n4- Kabin içi havalandırmaları her zaman aktif olmalı, kontrol bakımları yapılmaldır.', 'FİRMA', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 78, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Asansörlerin güvenlik koşullarının yetersiz olması                                                           2- Kullanma talimatlarının aşınmış olması', '1- Kabin arasına sıkışma ya da kırık cam kesmesi sonucu yaralanma', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Asansörlerde akım kesici switchler mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1- Asansörlerin kapı kanatlarında ki akım kesici switchler her zaman aktif olmalıdır.                                                                    \n2- Asansör çalışırken veya diğer kattayken kapıların açılmamasını sağlayan sistem her zaman çalışır durumda olmalıdır.                                                                                                         3- Asansör içinde kırık çatlak ayna olmamalı, kırılan ya da çatlayan aynalar hemen değiştirilmeli, asasörlerde kullanılan aynalar kırılmaz özellikte olmalıdır.                                                                                                                                                          4- Asansör katta değilken asansör kapısı el ile açılmaya çalışılmamalı, Acil durumlarda açılması gerekiyorsa  acil durum kilit açma anahtarı kullanılarak açılmalıdır.                                                                          \n5- Her asansörde okunabilir büyüklükte kullanım talimatı bulunmalı, yıpranan ya da aşınan talimatlar değiştirilmelidir.', 'FİRMA', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 79, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Asansörlerin periyodik kontrollerinin tekrarlanmaması', '1-Asansör kabinin  düşmesi sonucu yaralanma, ölüm', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Asansörlerin AT uygunluk beyanları mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1- Hastanede bulunan tüm asansörlerin periyodik kontrolleri en geç yılda bir kez TS EN 81-80 standardına göre tekrarlanmalıdır.                                                              2- Hastanede kullanılan tüm asansörler yeşil etikete sahip olmalıdır.                                                                                                      3- Asansör periyodik kontrolleri akredite olan A1 muayene kuruluşları ve ekipnete kayıtlı yetkili makine mühendisleri tarafından yapılmalıdır.                                                                                                                                                                4- Periyodik kontrol raporlarında uygunsuzluk tespit edilirse, uygunsuzluklar giderilene kadar asansörler kullanılmamalıdır.                                                                    5- Aylık kontrol ve bakımlar düzenli olarak tekrarlanmalı, sonuçlar belgelenmelidir.', 'FİRMA', 'PERİYODİK KONTROL               YILDA 1                                           KONTROL VE BAKIMLAR                     AYDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 80, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Doğalgaz kazanı işleten çalışanın mesleki yeterlilik belgesinin olmaması', '1- Yanlış işletim sonucu patlama, yangın meydana gelmesi', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 6, 1, 15, 90, 'C', '1- Kazanı işleten çalışanların sıcak su kazan operatörü mesleki yeterlilik belgeleri bulunmalıdır.\n2- Kazanı yalnızca mesleki yeterliliğe sahip olan çalışanlar işletmelidir.\n3- Kazan kullanım talimatlarına, üreticinin tavsiyelerine uyulmalıdır.\n4- Kazan dairesine yetkisiz kişilerin ulaşımı engellenmelidir.', 'FİRMA', '1 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 81, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Elektrik tesisatının, topraklamaların, kaçak akım rölelerinin, yangın rölelerinin periyodik kontrollerinin tekrarlanmaması', '1- Elektrik çarpması sonucu yaralanma\n2- Elektrik yangınları  meydana gelmesi', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Periyodik kontroller mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1- Elektrik tesisatının, topraklamaların, kaçak akım rölelerinin, yangın rölelerinin periyodik kontrolleri TS EN 60079 serisi, TS HD 60364-4 serisi, TS HD 60364-5 Serisi, TS HD 60364-6 standartlarına uygun olarak en geç yılda bir kez tekrarlanmalıdır.\n2- Her elektrik panosu için ayrı test ve ölçüm yaptırılmalıdır.\n3- Tüm bakım ve kontroller kayıt altına alınmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 82, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Elektrik panolarının kilitsiz olması\n2- Pano altlarında yalıtkan paspas bulunmaması', '1- Elektrik çarpması sonucu yaralanma', '1-YGAP Çalışanları \n2- Diğer ilgili kişiler', '1-Pano odalarına giriş kartlı sistemdir.\n2- Kaçak akım röleleri mevcuttur.', 1, 0, 6, 1, 15, 90, 'C', '1- Elektrik panoları kilitli olmalıdır.\n2- Elektrik panolarının altlarına yalıtkan paspas konulmalıdır.\n3- Pano odalarına girişte kartlı sistem her zaman çalışır durumda olmalı, yetkisiz kişilerin pano odalarına girmesi önlenmelidir.\n4- Elektrik ile ilgili yapılan çalışmalarda TS EN 50321 standardında yalıtkan ayakkabı kullanılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 83, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Hidroforların zemine sabitlenmemesi\n2- Manometrelerin en yüksek çalışma basıncını göstermemesi', '1- Hidroforların patlaması sonucu yaralanma', '1-YGAP Çalışanları \n2- Diğer ilgili kişiler', '1- Hidroforların periyodik kontrol raporları mevcuttur.', 1, 0, 6, 1, 15, 90, 'C', '1- Hidroforlar zemine sabitlenmelidir.\n2- Hidroforların manometreleri sağlam olmalı en yüksek çalışma basınçları işaretli olmalıdır.\n3- Manometreler TS EN 837 standartına uygun olmalıdır.\n4- Manometrelerin kalibrasyonları yapılmalı, sapma bulunan, bozuk, kırık manometreler değiştirilmelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 84, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Seksiyonel kapıların periyodik kontrollerinin tekrarlanmaması', '1-Kapının düşmesi sonucu vücut bölümlerinin ezilmesi, yaralanma', '1- YGAP Çalışanları', '1- Fotosel tertbitatı mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- En geç yılda bir kez kaldırma sisteminin periyodik bakımları yetkili kişilerce TS EN 13241+A2, TS EN 12453, TS EN 12604+A1 standartlarına uygun olarak periyodik bakımları tekrarlanmalıdır.\n2- Arıza durumlarında hemen arıza giderilmeli, onarım yapılmadan kapı kullanılmamalıdır. \n3-Kapı indirilip kaldırılırken 1 metreden yakın içeride ve dışarıda hiç kimse bulunmamalıdır.', 'FİRMA\nYGAP ÇALIŞANLARI', 'YILDA 1\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 85, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Mazot tankı nefesliklerin tıkanması', '1- Parlama, patlama yangın meydana gelmesi', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 7, 63, 'D', '1-Tankın bulunduğu alandaki nefeslikler düzenli aralıklarla kontrol edilmeli ve bakımları yapılmalıdır,tıkanması önlenmelidir.\n2- Nefeslikler tank doldurulurken doldurma ağzında buhar veya sıvı geri tepmesini önleyecek yeterli kapasitede olmalıdır.', 'FİRMA', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 86, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Elektirik odası duvarlarında nem oluşması', '1- Elektrik çarpması sonucu yaralanma', '1- YGAP Çalışanları', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1-Sızıntı kaynağı (boru,vana,bağlantı,hidrofor gövdesi) tespit edilmelidir.                                                               \n2-Sızdıran bölge  izolasyon malzemeleriyle onarılmalıdır.            \n3-Duvar ve zeminde su geçirmez kaplama yapılmalıdır.                                                                                             4-Elektiriğin su ile teması önlenmelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 87, 'BÖLÜM 5: TEKNİK MAHALLER', '1-Sprinklerin periyodik kontrollerinin tekrarlanmaması', '1-Yangının söndürülememesi sonucunda şiddetin artması', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Bakımları periyodik olarak yapılmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1-Sprinkler sisteminin aylık(görsel, fonksiyonel) kontrolleri yapılmalıdır.                                                                                                                                                                                                                                     3-Yılda 1 (TS EN 12845 standartları) olarak yapılmalıdır.                                                                                   \n4-Sprinkler başlıkları, boru hatları ve vanalar kontrol edilmelidir.', 'FİRMA', 'İLGİLİ PERİYOTLAR\nİLE SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 88, 'BÖLÜM 5: TEKNİK MAHALLER', '1-Yangın tüpünün kontrollerinin tekrarlanmaması', '1-Yangının söndürülememesi sonucunda şiddetin artması', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Tüpler mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1-Tüplerin ayda bir kontrolü yapılmalıdır.                                                          \n2-En geç yılda bir kez TS ISO 11602-2 standardına uygun olarak periyodik kontrolleri tekrarlanmalıdır.                                                                             \n3- 4 yılda bir hidrostatik basınç testi  göre yapılmalı, içindeki malzeme değiştirilmelidir.                                                                                                                                                                                                      4-Bakıma alınan yangın söndürme cihazın yerine, kullanıma hazır yangın söndürme cihazı bırakılmalıdır.', 'FİRMA', 'İLGİLİ PERİYOTLAR\nİLE SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 89, 'BÖLÜM 5: TEKNİK MAHALLER', '1-Yangın dolabının kontrollerinin tekrarlanmaması', '1-Yangının söndürülememesi sonucunda şiddetin artması', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Yangın dolapları mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1-Dolap, hortum makarası, hortum ve vanalar aylık kontrolleri yapılmalıdır.                                                                                                        2-En geç yılda bir kez TS EN 671-3 standardına göre periyodik kontrolleri tekrarlanmalıdır.\n3- Arıza tespit edildiğinde hemen bakım veya onarım yapılmalı, techizatın her zaman hazır durumda olması sağlanmalıdır.', 'FİRMA', 'İLGİLİ PERİYOTLAR\nİLE SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 90, 'BÖLÜM 5: TEKNİK MAHALLER', '1-Yangın kontrol panelinin arızalanması', '1-Yangının zamanında fark edilememesi sonucu şiddetin artması', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Sistem kontrolleri yapılmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1- Otomatik çalıştırma sistemi (sensörler, kontrol panosu, röleler)  yılda 1 kez TS 54-14 e göre  periyodik kontrolleri yapılmalıdır.\n2- Günlük bakımları yapılmalı arıza veya gecikme tespit edilirse yetkili teknik çalışanlar tarafından onarım yapılmalıdır.\n3- Sistemdeki yazılım ve elektronik bileşenlerin güncel ve doğru çalıştığı günlük olarak kontrol edilmelidir.\n4-Arıza tespit edilmesi durumunda sistem durdurulmamalı, manuel devreye alma prosedürleri uygulanmalı ve arıza kaydı oluşturulmalıdır.', 'FİRMA', 'İLGİLİ PERİYOTLAR\nİLE SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 91, 'BÖLÜM 5: TEKNİK MAHALLER', '1-Gazlı söndürme sistemlerinde manometre, kontrol paneli  arızası', '1-Yangına müdahale edilememesi sonucu şiddetin artması', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1-Manometre veya basınç göstergesi mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Manometre ve basınç göstergeleri yılda bir kez TS EN 837 kontrol edilmeli, doğru ölçüm yapmadığı tespit edilen cihazlar yetkili teknik çalışan tarafından onarılmalı veya değiştirilmelidir.\n2- Kontrol paneli ve elektrik bağlantıları günlük gözle ve fonksiyon testleri ile kontrol edilmeli, arıza tespit edilirse yetkili teknik personel tarafından onarılmalıdır.\n3- Paneldeki yazılım ve programlamalar güncel ve doğru çalışır durumda olmalıdır; gerektiğinde yeniden yükleme veya güncelleme yapılmalıdır.', 'FİRMA', 'İLGİLİ PERİYOTLAR\nİLE SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 92, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Faraday kafesinin periyodik kontrollerinin yapılmaması', '1-Yıldırım düşmesi sonucunda yaralanma, yangın', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Paratoner tesisatının periyodik kontrolü mevcuttur.', 1, 0, 1, 3, 15, 45, 'D', '1-Paratoner tesisatının periyodik kontrolleri TS EN 62305 standardına göre yılda en az 1 kez tekrarlanmalı ve belgelendirilmeldir.                                                                                                     2-Faraday kafesi içinde, civatalarda ve Franklin çubuklarında paslı ve korozyonlu alan bulunmamalıdır.                                                                                                                                                       3- Paratoner topraklaması bina topraklaması ile eşpotansiyel olmalıdır.                                                                                                                  4-Topraklama tesisinin direnci en fazla 10 ohm olmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 93, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Hidroforların periyodik kontrollerinin tekrarlanmaması', '1- Hidroforların patlaması sonucu yaralanma', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Hidroforların periyodik kontrol raporları mevcuttur.', 1, 0, 3, 1, 15, 45, 'D', '1- Hidroforların periyodik kontrolleri TS 1203 EN 286-1, TS EN 13445-5, TS EN 764-7 standartlarında belirtilen kriterlere uygun olarak tekrarlanmalıdır.\n2- Hidroforların emniyet ventilleri, check valf vb. güvenlik sistemleri çalışır durumda olmalıdır.\n3- Hidroforların  hidrostatik basınç deneyleri, en yüksek çalışma basıncının 1,5 katı ile yapılmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 94, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Hastane içerisinde kartlı sistemin çalışmaması, arızalanması', '1- Hastaların kaçma teşebbüsünde bulunması sonucu yaralanma', '1- YGAP Çalışanları', NULL, 1, 0, 1, 6, 7, 42, 'D', '1- Kartlı kapıların manyetik sistemleri bozulduğun da hemen onarılmalıdır.                                    \n2- Arızalı kapılar onarılana kadar hastalar başka güvenlikli bir odaya alınmalıdır.\n3- Çalışanların yaka butonları bulunmalıdır.', 'FİRMA\nYGAP ÇALIŞANLARI', 'ARIZA DURUMUNDA\n\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 95, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Havalandırma sisteminin periyodik kontrollerinin tekrarlanmaması', '1-Zararlı partiküllerin solunması sonucunda meslek hastalıklarının oluşması', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', '1- Havalandırma sisteminin periyodik kontrolleri mevcuttur.', 1, 0, 1, 6, 7, 42, 'D', '1- Havalandırma sisteminin periyodik kontrolleri havalandırma tesisat projesinde yer alan kriterlere göre en geç yılda bir tekrarlanmalıdır. \n2- Hava değişim sayısı ölçümleri yaptırılmalıdır.\n3- Otomatik sıcaklık, nem izleme sistemleri bulunmalı, çalışır durumda olmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 96, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Mazot tankının aşırı doldurulması', '1- Parlama, patlama yangın meydana gelmesi', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 1, 1, 40, 40, 'D', '1-Tankın aşırı dolum alarm sistemi, seviye göstergesi periyodik olarak kontrol edilmelidir.\n2- Tank doldurulurken  sıvı seviyesi tank kapasitesinin %85 e ulaşınca  duyulabilir şiddette sesli alarm vermeli, sıvı seviyesi tank kapasitesinin  %90 a ulaşınca akışı kesen sistemler her zaman aktif olmalıdır.', 'FİRMA', 'TANK DOLUM ESNASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 97, 'BÖLÜM 5: TEKNİK MAHALLER', '1-Mazot tankına ikmal yapılırken güvenlik önlemlerinin alınmaması', '1- Parlama, patlama yangın meydana gelmesi', '1-YGAP Çalışanları \n2- Hasta ve hasta yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 1, 1, 40, 40, 'D', '1- Tanka dolum yapmadan önce aracın egzoz çıkışına alev tutucu takılmalı, tanka ikmal başlatılmadan önce de aracın tekerleklerine her iki yönde takoz konulmalı ve araç topraklanmalıdır. İkmal süresince topraklama işlemine devam edilmelidir.\n2- İkmale başlanmadan önce tankerin motoru durdurulmalı, tüm elektrik aksamı kapatılmalıdır.\n3- Dolum yapan çalışanlar anti statik kkd’ler kullanmalı, kullanılan tüm ekipmanlar ve çalışanlar statik elektriğe karşı topraklanmalıdır.\n4- Aşırı akış kesme sistemleri aktif olmalıdır.', 'FİRMA', 'MAZOT İKMALİ ESNASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 98, 'BÖLÜM 5: TEKNİK MAHALLER', '1- Kazan dairesi sıcak yüzeyler olması', '1-Sıcak yüzeylere temas sonucu yaralanma', '1-YGAP Çalışanları \n2- Diğer ilgili kişiler', '1- Sıcak yüzeyler izole edilmiştir.', 1, 0, 3, 1, 7, 21, 'D', '1- Sıcak yüzeylere uyarı etiket ve işaretler konulmalıdır.\n2- Kazan soğumadan sıcak yüzeylere temas edilmemelidir.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: ACİL DURUMLAR', '1- Sabotaj oluşması', '1- Sabotaj sonucu yaralanma, ölüm', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- Güvenlik personelleri mevcuttur.                                   2- Kamera sistemleri mevcuttur.                            3-Tehlikeli alanlara yetkisiz giriş yapılamamaktadır.', 1, 0, 6, 6, 40, 1440, 'A', '1- Hastanenin tüm girişlerine silah bıçak vb. tehlike oluşturabilecek şüpheli nesnelerin fark edilebilmesi için xray cihazı konulmalıdır. \n2- Hastaneye giren herkesin xray cihazından geçmesi sağlanmalıdır.(Hamile, kalp pili olan kişiler vb. özel durumu olanlar hariç)\n3- Xray cihazı konulamayan tüm girişlerde güvenlik personeli bulundurulmalı ve dedektör ile üst araması yapılmalıdır. \n4- Xray cihazından geçemeyen özellikli kişilere dedektör ile üst araması yapılmalıdır.\n5-Yapılan eğitim ve tatbikatlarla çalışanlar, sabotajlara karşı korunma konularında bilinçlendirilmelidir.', 'İŞVEREN V.', '1 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: ACİL DURUMLAR', '1- Parlama patlama meydana gelmesi', '1-Vücut bölümlerinin yaralanması, uzuv kayıpları, ölüm', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', NULL, 1, 0, 3, 3, 40, 360, 'B', '1-Patlamadan korunma dokümanı hazırlanmalıdır.\n2- Patlayıcı ortam oluşabilecek alanlar işaretlenmeli ve patlamadan korunma dokümanında belirlenen zone ‘lara göre kullanılması gereken exproof ekipmanlar temin edilmelidir.\n3- Doğlagaz kullanılan alanlarda tüm fanlar ve havalandırma motorları exproof özellikte olmalıdır. \n4-Exproof ekipmanların periyodik kontrolleri TS EN 60079 standartına göre ATEX belgeli kişiler tarafından en az yılda bir kez yapılmalı, belgelendirilmelidir.\n5-Patlayıcı ortam oluşabilecek alanlar “EX Patlayıcı Ortam, Ateşle Yaklaşma” vb. levhalar ile işaretlenmelidir.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: ACİL DURUMLAR', '1-Yangın durumunda acil durum asansörleri dışında diğer asansörlerin çalışması', '1- Yangına dumanına maruz kalma sonucu boğulma', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- Asansörler yangın algılama sistemine bağlıdır.', 1, 0, 1, 6, 40, 240, 'B', '1-Asansörlerin, yangın uyarısı aldıklarında kapılarını açmadan doğrultuları ne olursa olsun otomatik olarak acil çıkış katına dönmelidir. \n2-Asansörler acil çıkış katına geldiklerinde bir daha çalışmamalıdır. \n3-Asansör boşluğuna ve bina içine duman dolmasını önlemek için asansörlerin önlerine duman perdeleri takılmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: ACİL DURUMLAR', '1-Yangın esnasında acil durum asansörlerinde ve acil çıkış merdivenlerinde  duman birikmesi', '1- Yangına dumanına maruz kalma sonucu boğulma', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1-Acil durum asansör kuyuları basınçlandırılmıştır', 1, 0, 1, 6, 40, 240, 'B', '1- Yangın esnasında acil durum asansörler kuyularının ve acil çıkış merdivenlerinin basınçlandırmaları aktif olmalıdır. \n2- Basınçlandırma sistemi çalıştığı zaman, bütün kapılar kapalı iken asansör kuyusu ve acil çıkış merdivenlerinin hastane kullanım alanları arasındaki basınç farkı en az 50 pa, kapılar açık iken basınç farkı en az 15 pa olmalıdır. \n3- Basınçlandırma sistemlerinin periyodik kontrolleri en geç yılda bir kez TS EN 12101-6 standartına göre yapılmalıdır. \n4- Acil durum asansörleri işaretlenmelidir.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: ACİL DURUMLAR', '1- Yangın meydana gelmesi', '1-Vücut bölümlerinin yaralanması, uzuv kayıpları, ölüm', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- Yangın söndürme ve algılama ihbar sistemleri mevcuttur.', 1, 0, 1, 6, 40, 240, 'B', '1- İtfaiye raporu alınmalıdır.\n2-Yangın söndürme tüplerinin, sprinklerin, yangın hortumlarının, yangın alarmlarının, duman algılama dedektörlerinin, yangın panellerinin, yangın pompalarının vb. yangın söndürme ile ilgili tüm tesisatların periyodik kontrolleri, risk değerlendirmesinin yangın söndürme sistemleri bölümünde belirtilen standartlara ve sürelere göre periyodik kontrolleri tekrarlanmaldır.\n 3-Yangın teçhizatlarının her an göreve hazır bulunması sağlanmalıdır.\n4-Hastane de kapalı alanlarda sigara içilmesi yasaklanmalıdır.', 'İŞVEREN V.', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: ACİL DURUMLAR', '1-Acil çıkış kapılarında bulunan manyetik tutucuların yangın ya da deprem anında çalışmaması, iptal edilmesi', '1-Tahliyenin gecikmesi sonucu yaralanma, ölüm', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- Acil çıkış kapıları yangın algılama sistemine bağlı ve acil durumlarda otomatik olarak açılmaktadır.', 1, 0, 3, 2, 40, 240, 'B', '1- Acil çıkış kapılarında bulunan manyetik tutcuların en az ayda bir bakım ve kontrolleri yapılmalı, sismik sensörlerin ve yangın algılama ve ihbar sistemlerinin sürekli çalışır durumda olması sağlanmalıdır. \n2- Manyetik tutucular çalışanlar tarafından iptal edilmemeli, iptal edilen manyetik tutucular tekrar aktif hale getirilmelidir.\n3- Manyetik tutucu bulunan acil çıkış kapıları sürekli olarak açık bırakılmamalı, önlerine malzeme bırakılmamalıdır.', 'FİRMA\nÇALIŞANLAR', 'AYDA 1\nHERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: ACİL DURUMLAR', '1-Sığınakların depo alanı olarak kullanılması', '1- Acil durumlarda sığınakların kullanılamaması sonucu yaralanma', '1- Çalışanlar', '1- Hastane de sığınak alanları mevcuttur.', 1, 0, 6, 2, 15, 180, 'C', '1- Hastane de sığınak olarak belirlenmiş alanlar depolama alanı olarak kullanılmamalı, sığınaklarda ki malzemeler boşaltılmalı, sığınak olarak hazır hale getirilmelidir. \n2- Sığınaklar da mekanik havalandırma sistemleri ve filtrelerinin yılda bir periyodik kontrolleri tekrarlanmaldır.\n3- Sığınaklara kesintisiz güç sağlayan jeneratörlerin her zaman çalışır durumda olması sağlanmalı, yıllık periyodik kontrolleri tekrarlanmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: ACİL DURUMLAR', '1-Salgın hastalıklar', '1- Salgın hastalıkların yayılması sonucu, hastalıklara yakalanma', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1-Kişisel koruyucu ekipmanlar mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Salgın hastalıkların yayılabileceği alanlarda havalandırma sistemleri hepa filtreli olmalı ve hepa filtrelerin değişimleri en geç yılda bir yapılmalıdır.\n2- Salgın hastalığın yayılabileceği bölümlerde izolasyon önlemleri arttırılmalıdır.\n3-Gerekli durumlarda ziyaretçi kısıtlaması getirilmeli ya da tamamen yasaklanmalıdır.\n4- Riskli birimlerde profesyonel dezenfeksiyon işlemi uygulanmaldır. \n5-Semptom gösteren çalışanlar teste tabi tutulmalı, sonuçlar çıkana kadar işten uzaklaştırılmaldır. \n6- Çalışanlar N95, ffp2 vb. maskeler, yüz siperleri, tulum, eldiven kullanmalıdır.', 'İŞVEREN V.', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: ACİL DURUMLAR', '1- Kimyasal sızıntısı', '1- Kimyasal maddeye ya da buharına maruz kalma sonucu yaralanma', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', NULL, 1, 0, 3, 3, 15, 135, 'C', '1- Hastane de tehlikeli kimyasallar için depo yapılmalıdır.\n2-Kimyasal maddelerin dökülme riskine karşı taşma kapları temin edilmelidir.\n3-Kimyasal döküntü kitleri temin edilmeli, çalışma ortamına yayılması önlenmelidir. \n4- Yüksek miktarda döküntülerde havalandırma sistemi kapatılmalı, kimyasal madde buharının diğer bölümlere yayılması önlenmeli, gerekirse çalışanlar ortam tamamen kimyasaldan arındırılana kadar tahliye edilmelidir.\n5- Yetkili ve eğitimli kişiler tarafından koruycu tulum, maske, gözlük, eldiven ve çizme giyerek bulaş olan bölüm emici malzemeler ile temizlenmelidir.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: ACİL DURUMLAR', '1- Acil durum ekiplerinin belirlenmemiş olması', '1- Acil durumlarda müdahale yapılamaması sonucu yaralanma, ölüm', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', NULL, 1, 0, 3, 3, 15, 135, 'C', '1-Hastane de acil durum ekipleri oluşturulmalıdır.\n2- Çalışan sayısına göre 30 kişi de 1 kişi yangınla mücadele, arama kurtarma, koruma konularında görevlendirilmeli, 10 kişi de 1 kişi ilk yardımcı olarak görevlendirilmelidir. \n3- Afad, İtfaiye vb. kurumlardan acil durum ekiplerine özel eğitim aldırılmalıdır.\n4- Acil durum ekiplerinde görevlendirilen kişilerin işten ayrılması vb. durumlarda yerine yeni kişiler görevlendirilmeli ve özel eğitime tabi tutulmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: ACİL DURUMLAR', '1- Elektrik yangını meydana gelmesi', '1- Elektrik çarpması sonucu yaralanma', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Elektrik yangınlarında sulu sistemler kullanılmamalıdır.\n2- Elektrik panolarına FM200, NOVEC 1230 vb. otomatik söndürme sistemleri kurulmalıdır.\n3- Pano içinde oluşabilecek kıvılcımlar otomatik olarak söndürülmelidir.\n4- Otomatik söndürme sistemi olmayan pano odalarında karbondioksitli yangın söndürücüler ya da kuru kimyevi tozlu yangın topları bulundurulmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: ACİL DURUMLAR', '1-Şiddetli rüzgâr fırtına', '1-Fırtına, rüzgâr sırasında elektrik tellerinin kopması, totemlerin veya dış cephe kaplamalarının devrilmesi, yüksekten düşme', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1-Totemler betona sabitlenmiştir.', 1, 0, 3, 6, 7, 126, 'C', '1-Totemlerin taşıyıcı sistemlerinin şiddetli rüzgar deprem vb. yüklerine karşı taşıma kapasitesinin yeterli olup olmadığı statik uygunluk kontrolü yetkili inşaat mühendislerine yaptırılmalıdır. \n2-Totemler düzenli aralıklarlar ile korozyon, pas oluşumu, ankraj noktalarında çatlak ve bağlantı gevşemesine karşı kontrol edilmeli, Totemlerin korozyon ve paslanmış kısımları boyanmalı, çatlak ve bağlantı gevşemesi olan yerler onarılmalıdır.\n3- Bina dış cephe kaplamaları sağlam ve düşmeyecek yapıda olmalıdır.\n4-Şiddetli rüzgâr anında çalışanlar kapalı bölgelerde bulunmalı, ağaç, elektrik direği, bayrak direği  vb. devrilebilecek  alanlardan uzakta durulmalıdır.\n5-Şiddetli rüzgârlı havalarda yüksekte çalışma yapılmamalıdır.', 'FİRMA', '3 AY\nŞİDDETLİ RÜZGAR FIRTINA ESANASINDA \nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: ACİL DURUMLAR', '1- Acil durum tatbikatlarının yapılmaması ya da eksik yapılması', '1- Acil durumlarda müdahale yapılamaması sonucu yaralanma', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-Yıllık tatbikat planı hazırlanmalıdır.\n2- Acil durum eylem planının uygulama adımlarının düzenli takip edilebilmesi ve uygulanabilirliğinden emin olunması için yangın, deprem, kimyasal döküntü, radyoaktif sızıntı vb. konularda yıllık olarak belirli aralıklar ile haberli ve habersiz tatbikatlar yapılmalıdır.\n3- Tatbikatlara tüm çalışanların katılımı sağlanmalıdır.', 'İŞVEREN V.', 'İLGİLİ PERİYOTLAR\n İLE \nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: ACİL DURUMLAR', '1-Deprem meydana gelmesi', '1-Göçük altında kalma, ağır yaralanmalar, ölüm, yangın çıkması', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1- Ana bina da sismik izalotör bulunmaktaıdır.', 1, 0, 0.5, 6, 40, 120, 'C', '1-Hastane de tam donanımlı afet konteynırı bulundurulmalıdır.\n2-Hastane genelinde tüm dolap ve raflar sabitlenmeli, düzensiz istifleme yapılmamalıdır.\n3-Deprem sırasında enerjinin kesilmesi gereken makine ve ekipmanların listesi hazırlanmalı ve güncel tutulması sağlanmalıdır.\n4- Deprem sırasında yapılacaklar ve hareket tarzı ile ilgili tüm çalışanlara eğitim verilmeli ve yılda bir deprem tatbikatı yaptırılmalıdır.', 'İŞVEREN V.', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: ACİL DURUMLAR', '1-Yıldırım düşmesi', '1-Yıldırım düşmesi sonucunda ağır yaralanmalar ölüm, yangın', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1-Faraday kafesi mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1-Paratoner tesisatının periyodik kontrolleri TS EN 62305 standardına göre yılda en az 1 kez tekrarlanmalı ve belgelendirilmeldir.\n 2-Faraday kafesi içinde, civatalarda ve Franklin çubuklarında paslı ve korozyonlu alan bulunmamalıdır.\n3- Paratoner topraklaması bina topraklaması ile eşpotansiyel olmalıdır.\n4-Topraklama tesisinin direnci en fazla 10 ohm olmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: ACİL DURUMLAR', '1- Radyoaktif sızıntı', '1-Radyoaktif maddelere ya da buharına temas sonucu yaralanma, hastalık meydana gelmesi', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', NULL, 1, 0, 3, 3, 7, 63, 'D', '1-Radyoaktif sızıntı olması durumunda sızıntı olan bölüm boşaltılmalı, en az 10 metre çevre bariyeri kurulmalı, havalandırma sistemi kapatılmalıdır.\n2- Yetkili ve eğitimli kişiler tarafından koruycu tulum, maske, gözlük, eldiven ve çizme giyerek bulaş olan bölüm emici malzemeler ile temizlenmelidir.\n 3- Radyoaktif atıklar, radyoaktif atık yönetim prosedürüne göre kaldırılmalıdır.\n4- Dozimetre ile ortamdaki radyasyon ölçülmeli, sonuçlar normal seviyeye inene kadar ölçüme devam edilmelidir.\n5- Bulaş olan kişiler acil servise yönlendirilmeli, izole odalarda yetkili ve eğitimli kişiler tarafından kişisel koruyucu ekipman kullanarak, giysileri çıkarılmalı, bulaş olan kişiler ılık su ve sabun ile  yıkanmalı, sağlık durumları gözlenmelidir.', 'İŞVEREN V.', 'RADYOAKTİF SIZINTI OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: ACİL DURUMLAR', '1-Sel, su baskını meydana gelmesi', '1-Vücut bölümlerinin yaralanması', '1- Çalışanlar\n2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', NULL, 1, 0, 0.5, 6, 15, 45, 'D', '1-Açık alanda ve işyeri içinde bulunan tüm rögarlar üç ayda bir periyodik olarak temizlenmelidir. \n2-Çatıda yer alan su kanalları ve suyu aşağıya veren borular yılda en az iki defa temizlenmelidir. \n3-Sel ve su baskını esnasında su ile temas eden elektrik ekipman ve panoların enerjileri kesilmelidir.\n4-Sel ve su baskını esnasında dış alanda bulunan çalışanlar güvenilir ve yüksek bir konumda beklemelidirler.', 'FİRMA', 'İLGİLİ PERİYOTLAR\n İLE \nSÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: STERİLİZASYON', '1-Sterilizasyon  bölümünde yanıcı parlayıcı kimyasallar kullanılması', '1- Parlama yangın meydana gelmesi', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1- Yangın algılama, ihbar, söndürme sistemleri mevcuttur.', 1, 0, 6, 2, 15, 180, 'C', '1- Yanıcı parlayıcı kimyasallar ile yapılan cihaz dezenfeksiyon işleri, cihazların tüm elektrik bağlantıları kesildikten sonra yapılmalıdır.\n2- Dezenfeksiyon işlerinde anti statik malzemeler kullanılmalıdır.\n3- Yanıcı parlayıcı kimyasalların kullanıldığı alanlarda ısı, kıvılcım ve elektrik kaynağı bulundurulmamalıdır.\n4- Çalışanların kkdleri anti statik özellikte olmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: STERİLİZASYON', '1- Acil çıkış yollarının, kapılarının malzemeler ile kapatılması\n2-  Koridorlarda bulunan kaçış yönlendirme tabelalarının kırık y ada eksik olması', '1-Acil durumlarda hızlı tahliyenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', NULL, 1, 0, 6, 2, 15, 180, 'C', '1-Acil çıkış kapıları ve acil çıkış yolları açıkça görülebilir olmalı ve acil çıkış kapılarnın ve yollarının önüne ve üzerine malzeme vb. konulmamalıdır.  \n2- Acil çıkış yönlendirmelerinin önleri kapatılmamalı, kaçış yolu üzerinde bütün erişim noktalarından görülebilir olmalı, yönlendirmeler 200-240 cm yüksekliğe asılı olmalıdır.                                                                         \n3- Acil çıkış yollarında en az 150 cm genişliğinde mesafe olması sağlanmalıdır.', 'FİRMA', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: STERİLİZASYON', '1- Otoklav cihazlarının yasal sürede periyodik muayenesinin yaptırılmamış olması', '1-Otoklavın patlaması sonucu yaralanma', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1- Otoklavların periyodik kontrolleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Otoklavın periyodik kontrolü TS EN 285+A1 ve TS EN 13060+A1 standartlarına göre en geç yılda bir kez tekrarlanmalıdır.                                                                                                              2- Otoklavın hidrolik basınç deneyleri, en yüksek çalışma basıncının 1,5 katı ile yapılmalıdır.                                                                                                                                                    3- Otoklavın kapı switchleri her zaman aktif olmalı, otoklav çalışırken kapıları açılmamalıdır.                                                                                                                                            4- Otoklav dolum ve boşaltılmasında ısıya dayanıklı eldiven kullanılmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: STERİLİZASYON', '1-Atık varillerin kapaklarının açık bırakılması', '1-Toksik maddelere maruziyet sonucu iş kazaları olması', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1-Renk kodlarına göre atık varilleri mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1- Atık varillerinin kapağı sürekli olarak kapalı halde tutulmalıdır,                                                                  2- Atıklar karıştırılmamalı, her atık türü için (Tıbbi, Tehlikeli, Evsel)belirlenmiş renk kodlu atık kutularına atılmalıdır.                                                                                                                                                    3- Kesici delici aletler sadece kesici delici alet kutusuna atılmalıdır.                                                     4- Atık varilleri en fazla 3/4 oranında dolduğunda değiştirilmelidir.', 'STERİLİZASYON ÇALIŞANLARI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: STERİLİZASYON', '1- Manuel transpaletlere yüklerin düzensiz ve sabitlenmeden yüklenmesi, taşınması', '1- Yüklerin düşmesi, devrilmesi sonucu yaralanma', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1- Malzemeler transpalet ile taşınmaktadır.', 1, 0, 3, 2, 15, 90, 'C', '1- Yükler dengeli yüklenmelidir.\n2- Yüksek, ağır ve dengesiz düşebilecek yükler sabitlenerek taşınmalıdır.\n3- Taşıma alanında çalışanlar bulunmamalıdır.\n4- Transpaletlerde taşıma kapasitesi üzerinde yük taşınmamalıdır.\n5- Taşıma araçları sonrası kontrol edilmelidir.\n6- Yükler çalışanın görüşünü engellemeyecek şekilde taşınmalıdır.', 'FİRMA', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: STERİLİZASYON', '1-Yangın dolaplarının önlerinin kapatılmış olması', '1-Acil durumlarda hızlı müdahalenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', NULL, 1, 0, 3, 2, 15, 90, 'C', '1- Malzeme, makine, temizlik arabası vb. yangın dolaplarının önlerini kapatmaması sağlanmalıdır.\n2-Yangın dolaplarına erişim için en az 80 cm genişlikte ulaşım yolları sağlanmalıdır.\n3-Yangın dolaplarının üzerlerine uyarı etiket ve işaretleri asılmalıdır.', 'FİRMA', '1 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: STERİLİZASYON', '1- Acil çıkış kapılarının dışarıdan anahtarla kilitlenmiş olması', '1- Afet anında acil çıkış kapısından çıkış yapılamaması', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', NULL, 1, 0, 3, 2, 15, 90, 'C', '1- Acil çıkış kapılarının kilitli olmamalı, acil durumlarda tahliyeyi sağlamak amacıyla her zaman açık olmalıdır.\n2- Acil çıkış kapılarında afet durumlarında açılmasını sağlayan manyetik tutucular takılmalıdır.', 'FİRMA', '1 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: STERİLİZASYON', '1- Otoklav cihazının sıcak yüzeyleri ile temas', '1- Sıcak yüzeylere temas sonucu ısı yanıkları oluşması', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1-Birçok sıcak yüzeyler izole edilmiştir.', 1, 0, 3, 3, 7, 63, 'D', '1- Sterilizasyon bölümünde tüm sıcak yüzeyler izole edilmelidir.                                                                                                            2- Sıcak yüzeylere uyarı etiket ve işaretler konulmalıdır.\n3- Otoklav soğumadan sıcak yüzeylere temas edilmemelidir.\n4- Isıya dayanıklı eldiven kullanılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: STERİLİZASYON', '1- Kirli ve temiz alandaki tüm yüzeylerin, gingerların dezenfeksiyonun yapılmaması', '1- Enfeksiyon riski       2-Bulaş riski', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1- Kirli ve temiz alandaki tüm yüzeyler  incidin foam kimyasalı kullanılarak dezenfeksiyonu yapılmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1- Kirli ve temiz alandaki tüm yüzeyler gün başında ve sonunda incidin foam kimyasalı kullanılarak  ile dezenfeksiyonu yapılmalıdır.\n2- Girngerlar her vardiya değişiminde dezenfekte edilmelidir.\n3- Yanıcı dezenfektanlara karşı anti statik malzemeler kullanılmalıdır.', 'FİRMA', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: STERİLİZASYON', '1- Zeminin sürekli ıslak olması', '1- Kayma                                       2- düşme                                    3- yaralanma', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1- Özellikle kirli alanda zemin ıslak durumdadır.', 1, 0, 3, 3, 7, 63, 'D', '1- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.                                                                                                     2- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\n3- Çalışanlar kaymaz tabanlı ayakkabı giymelidir.', 'TEMİZLİK\nÇALIŞANLARI\nBÖLÜM \nÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: STERİLİZASYON', '1- Sterilizasyon bölümünde kullanılan makineleri kapı switchlerinin iptal edilmesi', '1- Hareketli kısımlara kapılma sonucu el kol parmak yaralanmaları', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1-Kapı switchleri mevcuttur.', 1, 0, 3, 1, 15, 45, 'D', '1- Çalışanların cihazların operasyon bölgelerine ellerini sokabilecekleri kapılarına switchli kapaklar takılmalıdır.    \n2- Sterilizasyon bölümünde kullanılan tüm elektrikli cihazların kapı akım kesici switchleri aktif olmalıdır.                                                                                                                                                                                                                                                          3- Cihazın içindeki numune kaplarının devrilmesi, sıkışması vb. durumlarda elektrik akımı kesilmeden müdahale edilmemelidir.', 'FİRMA', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: STERİLİZASYON', '1- Hidrofor tankının  periyodik kontrolünün tekrarlanmaması', '1- Fiziksel patlama sonucu yaralanma', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1- Hidroforun periyodik kontrolü mevcuttur.', 1, 0, 3, 1, 15, 45, 'D', '1- Hidroforların periyodik kontrolleri TS 1203 EN 286-1, TS EN 13445-5, TS EN 764-7 standartlarında belirtilen kriterlere uygun olarak tekrarlanmalıdır.\n2- Hidroforların emniyet ventilleri, check valf vb. güvenlik sistemleri çalışır durumda olmalıdır.\n3- Hidroforların  hidrostatik basınç deneyleri, en yüksek çalışma basıncının 1,5 katı ile yapılmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: STERİLİZASYON', '1-Tehlikeli kimyasalların yanlış depolanması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1- Kimyasallar için taşkanlar mevcuttur.                          2- Raflarn önlerinde file mevcuttur.                            3- Raflar yotalıdır.', 1, 0, 3, 1, 15, 45, 'D', '1- Kimyasal maddeler depolama matirsine göre depolanmalıdır.                                                        \n2- Yanıcı kimyasallar elektrik kaynaklarından uzak depolanmalıdır.                                                                               3- Kimyasal maddelerin ağzı açık olmamalı, dik olarak istiflenmelidir.\n4- Ağzı açılmış kimyasal madde kaplarının altına taşma kapları konulmalıdır.', 'FİRMA', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: STERİLİZASYON', '1- Hidrojen peroksit kasedinin kırık hasarlı olması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1- Hasarlı kasetler idae kısmına ayrılmakta ve tutanak tutulmaktadır', 1, 0, 3, 2, 7, 42, 'D', '1- Hidrojen peroksit kasetleri cihaza takılmadan önce kontrol edilmeli, hasarlı olanlar kullanılmamalıdır.\n2- Hidrojen peroksit kasetlerinin düşmesi ya da hasarlı olmasından dolayı sızıntı, döküntü durumlarında, hemen döküntü kiti kullanılmalı, hidrojen peroksit buharının çalışma ortamına yayılması önlenmelidir.', 'FİRMA', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: STERİLİZASYON', '1-Ginger kullanan çalışanların servisler,poliklinikler ve yoğun bakımlardan  kirli malzemelerin alımı sırasında kkd kullanmaması', '1- Enfeksiyon riski       2-Bulaş riski', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1- Çalışanlar  kirli malzemeleri  tutanak ile tıbbi atık poşeti içerisinde veya set konteynerları ile teslim alınmaktadır.', 1, 0, 3, 2, 7, 42, 'D', '1-İlgili alanlardan ginger kullanan personeller kirli malzemeleri  tutanak ile tıbbi atık poşeti içerisinde veya set konteynerları ile teslim alınmalıdır.                                                   2- Teslim alınması esnasında personeller tarafından  maske (TS EN 143 - TS EN 149 )  ile  kimyasal ve mikroorganizmaya dayanıklı nitril  eldiven (TS EN ISO 374-1- TS EN ISO 374-5  )kullanmalıdır. \n3- Kirli, bulaş olan kkd\'ler ile ortak alanlara temas edilmemelidir.', 'GINGER OPERATÖRLERİ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: STERİLİZASYON', '1- Çalışanların kimyasallar hakkında bilgi sahibi olmaması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1- Döküntü kitleri alanda mevcuttur.', 1, 0, 1, 1, 40, 40, 'D', '1- Kimyasalların dökülme riskine karşı döküntü kitleri bulundurulmalıdır.                                         \n2- Göze kaçma riskine karşı göz duşu solüsyonu bulundurulmalıdır.  \n3- Kimyasal maddelere gözlük, eldiven olmadan temas edilmemelidir.                                                               \n4-Kimyasal maddelerin malzeme güvenlik bilgi formları depoda asılı olmalıdır.', 'FİRMA', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: STERİLİZASYON', '1- Ginger kapasitesinin üzerinde malzeme yüklenmesi', '1- Malzemelerin devrilmesi sonucu yaralanma', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 3, 27, 'D', '1- Gingerlara kapasitesinin üzerinde malzeme yüklenmemelidir.\n2- Düşme devrilme riski olan malzemeler sabitlenerek taşınmalıdır.', 'GINGER OPERATÖRLERİ', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: STERİLİZASYON', '1- Makasların tezgah üzerine uygunsuz şekilde konulması', '1- Kesme                                2- batma                          3- yaralanma', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1- Makaslar masa kenarlarında düşmeye/çarpmaya müsait konumda bırakılmamaktadır.', 1, 0, 3, 3, 3, 27, 'D', '1- Paketleme işleminde kesme için kullanılan makaslar kullanıldıktan sonra masa üstü vb. alanlarda bırakılmamalı, çekmece vb. yerlere kaldırılmalıdır.\n2- Makaslar masa kenarlarında düşmeye/çarpmaya müsait konumda bırakılmamalıdır.', 'FİRMA', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: STERİLİZASYON', '1- Kesici delici aletlerin emniyetsiz kullanılması', '1- Kullanılmış aletlere temas sonucu el kol yaralanmaları, enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1- Atık kutularının kapakları açık bırakılmamaktadır.', 1, 0, 3, 3, 3, 27, 'D', '1- Kullanılmış iğne ve kesici aletler, kesici delici alet kutusuna atılmalıdır.                                                                                                                           2- Çalışanlar tedavi tepsisi kullanmalı, iğne kapağı kapatılmadan kesici delici alet kutusuna atılmalıdır.                                                                                                                                 3- Kesici delici alet kutuları en fazla 2/3 dolduğunda yenisi ile değiştirilmeli, kutuların kapakları açık bırakılmamalıdır.                                                                                                                   4-  Kesici delici alet kutuları devrilmeyecek şekilde konumlandırılmalıdır.                                                                                                                                5- Çalışanlar TS EN 455 standardında çift eldiven kullanmalıdır.', 'STERİLİZASYON ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: STERİLİZASYON', '1-Steril depolardaki  ve tekstil alanındaki rafların sabitlenmemiş olması', '1- İş kazası                           2- Yaralanma                          3- Devrilme', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1- Steril depolardaki  ve tekstil alanındaki raflar sabitlenmiştir.', 1, 0, 3, 1, 7, 21, 'D', '1-Sabitlenmemiş doalp ve raflar en az iki noktadan sabitlenmelidir.\n2-Düşme, devrilme riski olan bütün malzemeler düşmeyecek şekilde sabitlenmelidir.\n3-Ağır malzeme ve ekipmanlar yüksek istiflenmemelidir.   \n4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: STERİLİZASYON', '1- Kirli ve temiz  alanlarına girişlerde çalışanlar tarafından kişisel koruyucu donanım kullanılmaması', '1- Enfeksiyon riski       2-Bulaş riski', '1- Sterilizasyon  Komisyon Üyeleri                          2- Diğer ilgili kişiler', '1-Asepsi içerisinde girişlerinde kullanılmak üzere bone,galoş tek kullanımlık önlükler bulunmaktadır.', 1, 0, 1, 3, 7, 21, 'D', '1- Kirli ve temiz alanlara girişler asepsilerden yapılmalıdır. \n2- Asepsi içerisinde girişlerinde kullanılmak üzere bone,galoş tek kullanımlık önlükler sürekli hazır bulundurulmalıdır.', 'FİRMA', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM : Radyasyon Onkolojisi', '1-Uygunsuz alanlarda Çay kazanı, çaycı vb. elektrikli aletlerin kullanılması', '1- Elektrik kesintileri, yangın', '1-Tüm radyasyon onkolojisi çalışanları', NULL, 1, 0, 3, 6, 15, 270, 'B', '1-Mutfak tanımlı odalar dışında çaycı, çay kazanı vb. elektrikli ev aletlerin kullanımı engellenmelidir.                                                              2- Mutfak tanımlı alanları içerisinde kullanılan elektrikli ev aletleri kırmızı prizlere takılmamalı, iş bittiğinde fişler derhal çekilmeli, sürekli takılı bırakılmamalıdır.                                                                  3- Fişleri ya da kendisi arızalı olan ev aletleri varsa kullanımı iptal edilmelidir.', 'İŞVEREN V.', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM : Radyasyon Onkolojisi', '1- Yeterli sayıda kişisel koruyucu ekipman olmaması', '1- Radyasyona maruziyet sonucu meslek hastalıkları oluşması\n2-Enfekte hastadan bulaş', '1-Tüm radyasyon onkolojisi çalışanları', NULL, 1, 0, 3, 6, 15, 270, 'B', '1-Radyasyon onkolojisi bölümünde çalışanlara TS EN 61331-1 standartında kurşun yelek,kurşun tiroid koruyucu donanımlardan eksik olanlar verilmelidir.                                                              \n2-Denetimli alan olarak sınıflandırılan bölümlere girişlerde ve çalışma esnasında kişisel koruyucu donanımlar (kurşun yelek,kurşun tiroid koruyucu) kullanılmalıdır.', 'İŞVEREN V.', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM : Radyasyon Onkolojisi', '1-Kişisel koruyucu ekipmanın deforme olması', '1- Radyasyona maruziyet sonucu meslek hastalıkları oluşması\n2-Enfekte hastadan bulaş', '1-Tüm radyasyon onkolojisi çalışanları', NULL, 1, 0, 3, 6, 15, 270, 'B', '1-Dezenfeksiyon ve temizliğinde alkol içerikli temizleme maddesi kullanılmamalıdır.\n2- Koruyucular saklama koşullarına uygun olarak saklanmalı, katlama veya kırışma sebebi ile çatlama veya aşınma oluşturulmamalıdır.\n3-Tüm koruyucular yılda en az bir kez veya ihtiyaç görüldüğü hallerde (Deforme olmuş, bozulmuş, kırılmış, düşmüş) sorumluya bilgi verilip floroskopi ile kontrol edilerek ayrılmalı ve kullanılmamalıdır.    \n4-Özellikli (kurşun kaplı) kişisel koruyucu donanımların kırılma vb. fiziksel kontrolleri günlük olarak çalışanlar tarafından yapılmalıdır.', 'RADYASYON ONKOLOJİSİ\nBÖLÜM ÇALIŞANLARI', '2 AYDA BİR', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM : Radyasyon Onkolojisi', '1- LINAC çalışması sırasında saçılma radyasyonu nedeniyle çalışanın iyonizan radyasyona maruz kalması', '1-Radyasyona maruziyet sonucu kanserojen etkiler görülmesi,meslek hastalıkları oluşması', '1-Tüm radyasyon onkolojisi çalışanları', '1- Personelin dozimetre takması sağlanarak aldıkları doz takip ediliyor. \n2- Çalışanlar kurşun yelek,kurşun tiroid koruyucu,maske , gözlük ve eldiven kullanarak çalışmaları konusunda gerekli ekipman sağlanarak eğitim verilmektedir.', 1, 0, 3, 6, 15, 270, 'B', '1-LINAC odası kurşun zırhlama ve bunker shielding kontrolleri yılda bir defa yapılmalıdır.\n2-Kapı interlock sistemlerinin devre dışı bırakılması yasaklanmalıdır.\n3-Personel için kişisel dozimetre (gövde + göz merceği) kullanımı sağlanmalıdır.\n4-ALARA prensibine (zaman–mesafe–zırhlama) uygun olarak eğitimler her yıl tekrar edilmelidir.\n5-Dozimetre kullanımının sürekliliği sağlanmalıdır.', '*BURTOM\n*İŞVEREN V.\n*RADYASYON KOMİTESİ\n*RKS', 'MARUZİYET OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM : Radyasyon Onkolojisi', '1-Yüksek Doz Alan Hastaya Yaklaşma', '1-Radyoaktif madde maruziyeti sonucu Akut Radyasyon Sendromu (ARS) oluşması', '1-Radyasyon Onkoloğu\n2-İşyeri Hekimi\n3-Sağlık fizikçileri', NULL, 1, 0, 3, 6, 15, 270, 'B', '1-Yazılı Brakiterapi Acil Durum Prosedürü uygulanmalıdır.\n2-Cihazın çalışması esnasında içeri personel girmesi engellenmelidir.\n3-Brakiterapi işlemleri yalnızca eğitimli personel tarafından yapılmalıdır.', '*BURTOM\n*RADYASYON KOMİTESİ\n*RADYASYON ONKOLOJİSİ BİRİM SORUMLUSU', 'HASTA TEDAVİSİ SÜRECİNDE OLMASI DURUMUNDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM : Radyasyon Onkolojisi', '1-Brakiterapi terapi cihazının devrilmesi', '1-Personelin acil müdahalede yüksek doz radyoaktif madde alması\n2-Cihazin devrilmesi sonucu personelin fiziksel yaralanması', '1-Tüm radyasyon onkolojisi çalışanları', '1-Girişler Kontrollü anahtarlı giriş olarak düzenlenmiştir. \n2-Devrilme önleyici kilit / denge sistemi aktiftir\n3-Alan monitörü bulunmaktadır.\n4-Acil durum prosedürü bulunmaktadır.\n5-Dozimetre kullanımı mevcuttur.\n6-Personele gerekli eğitimler verilmiştir.', 1, 0, 3, 6, 15, 270, 'B', '1-Girişler Kontrollü anahtarlı, elektronik kartlı, şifre vb. giriş olarak düzenlenmelidir.\n2-Devrilme önleyici kilit / denge sistemi aktif olmalıdır.\n3-Alan monitörü bulunmalıdır.\n4-Acil durum prosedürü bulunmalıdır.\n5-Dozimetre kullanımının sürekliliği sağlanmalıdır.\n6-Personele gerekli eğitimler verilmilidir.', '*BURTOM\n*RADYASYON KOMİTESİ\n*RADYASYON ONKOLOJİSİ BİRİM SORUMLUSU', NULL, NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM : Radyasyon Onkolojisi', '1-Acil çıkış kapılarında tütün ürünleri kullanımı', '1-Yangın,Kaçış Güvenliği,', '1-Hastane Çalışanları', NULL, 1, 0, 3, 10, 7, 210, 'B', '1-Kamera sistemleri ve güvenlik personeli ile Acil çıkış kapılarının önünde tütün kullanımının önlenmesi için denetimler yapılarak idari yaptırımlara başvurulmalıdır.                                                                                                                                          \n2-Tütün ürünlerinin kullanımın yasak olduğu alanlarda kesinlikle yasaktır yazılı uyarı levhaları bulundurulmalıdır.                      \n3-Çalışanlara sigara ve tütün ürünlerinin içilmesi yasak olan alanlardaki riskleri (yangın riski, enfeksiyon riski, ekipman zararları) hakkında bilgilendirme yapılmalıdır.', 'İŞVEREN V.\nTÜTÜN KOMİSYONU', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM : Radyasyon Onkolojisi', '1- Kesici ve delici alet kullanımı', '1-Kesici delici alet yaralanması.                2-Enfekte hastadan bulaş', '1-Kan alma çalışanı', '1-Kesici delici atık kutuları bulunmaktadır.', 1, 0, 6, 3, 7, 126, 'C', '1-Kesici delici materyaller iş bitiminde hemen sharp box atık kutusuna atılmalıdır.                        \n2-Atıklar kaynağında ve ilk kullanıcı tarafından doğru şekilde ayrıştırılmalıdır.', 'KAN ALMA ÇALIŞANI', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM : Radyasyon Onkolojisi', '1-Kan alma koltuk kollarının sağlam olmaması, hasarlı veya kırık olması', '1.Kesici delici alet yaralanması.                2.Enfekte hastadan bulaş.\n3-Hastanın düşme riski sonucunda personelin müdahale ederken yaralanması', '1-Kan alma çalışanı', '1-Tamir talebi oluşturulduğunda, koltuk tamir bakımı yapılmaktadır.', 1, 0, 6, 3, 7, 126, 'C', '1-Hasarlı yada kırık kan alma koltukları kullanılmamalıdır.', 'BRS\nKAN ALMA ÇALIŞANI', NULL, NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM : Radyasyon Onkolojisi', '1-Çalışanların yıllık radyoaktif madde maruziyet değerinin aşılması', '1-Radyasyona maruziyet sonucu kanserojen etkiler görülmesi,meslek hastalıkları oluşması', '1-Tüm radyasyon onkolojisi çalışanları', '1- Personelin dozimetre takması sağlanarak aldıkları doz takib ediliyor. \n2- Çalışanlar kurşun yelek,kurşun tiroid koruyucu,maske , gözlük ve eldiven kullanarak çalışmaları konusunda gerekli ekipman sağlanarak eğitim verilmekte.', 1, 0, 3, 6, 7, 126, 'C', '1-Radyasyon güvenlik önlemleri alınmalıdır. \n2-Çekim odaları lisanslı olmalıdır.\n 3-Radyasyonun yayılması muhtemel olan odaların önüne çalışanları ve hastaları uyarmak için uyarı levhaları asılmalıdır. \n4-Eğitimler yapılmalı, çalışanların dozimetre takiplerinin düzenli yapılması sağlanmalıdır. \n 5-Kişisel koruyucu ekipmanlar (Kurşun giysiler, Kurşun Gömlek, Gonat Koruyucu, Gözlük, Troid Koruyucu, boyunluk) eksiksiz bulundurularak uygun sürelerde kontrolleri yapılmalıdır. Kullanılması gerekli durumlarda kullanımı sağlanmalıdır. \n6-Yıllık radyasyon ölçüm sonuçları düzenli olarak değerlendirilmelidir.', '*RADYASYON ONKOLOJİSİ BİRİM SORUMLUSU', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM : Radyasyon Onkolojisi', '1- Temizlik çalışanlarının yeterli eğitime sahip olmaması', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Tüm radyasyon onkolojisi çalışanları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-Radyasyon Güvenliği, Radyoaktif Atıklar ve Radyokaktif Alanda Güvenli Çalışma konuları hakkında eğitime sahip olmayan temizlik çalışanları Radyasyon onkolojisi  bölümünde çalıştırılmamalıdır.                                                                                                                                                                                                                                                      2-Eğitimleri en az yılda bir kez tekrarlanmalı ve belgelendirilmelidir.\n3-Temizlik personeli sabit olmalıdır.', '*RADYASYON ONKOLOJİSİ BİRİM SORUMLUSU\n*İSS', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM : Radyasyon Onkolojisi', '1- Çalışanların dinlenme alanı olmaması', '1-Dinlenememe sonucu mental ve fiziksel yorgunluk', '1-Tüm radyasyon onkolojisi çalışanları', NULL, 1, 0, 6, 6, 3, 108, 'C', '1- Çalışanlar için dinlenme odası temin edilmelidir.', 'İŞVEREN V.', NULL, NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM : Radyasyon Onkolojisi', '1-Brakiterapi sırasında kaynağın cihaz içine geri çekilememesi', '1-Radyoaktif madde maruziyeti sonucu Akut Radyasyon Sendromu (ARS) oluşması', '1-Sağlık fizikçileri\n2-Radyasyon Onkologları', '1-Kaynak uygulamalarında manuel temasın olmaması\n2-Brakiterapi işlemi yalnızca eğitimli personel tarafından yapılıyor', 1, 0, 1, 1, 100, 100, 'C', '1-HDR afterloader sistemlerinin kullanımı sağlanmalıdır.\n2-Kaynak uygulamalarında manuel temas olmamalıdır.\n3-Brakiterapi işlemleri yalnızca eğitimli personel tarafından yapılmalıdır.\n4-Kurşun kaplı acil kaynak muhafaza kabı bulundurulmalıdır.', '*BURTOM\n*RADYASYON KOMİTESİ\n*RADYASYON ONKOLOJİSİ BİRİM SORUMLUSU', 'HASTA TEDAVİSİ SÜRECİNDE', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM : Radyasyon Onkolojisi', '1-Denetimli alanlara yetkisiz giriş olması', '1-Radyasyona maruziyet sonucu kanserojen etkiler görülmesi,meslek hastalıkları oluşması', '1-Tüm radyasyon onkolojisi çalışanları\n2-Hasta ve hasta yakınları', '1- Denetimli alanların tanımları yapılmıştır.\n2-Girişler Kontrollü açma butonu ile giriş olarak düzenlenmiştir. \n3-Çekim esnasında Hamile veya şüphesi olanlar için uyarı işaretleri mevcuttur.\n4-Çekim esnasında kontrollü alanlarda sadece Hasta ve Teknisyen bulunması\n5-Hasta veya hasta yakınının alanda olması\n6-Radyasyon Uyarı lambaları aktif  ve kullanılıyor.\n7-Yetkisiz Çalışan Giremez Uyarısı mevcut', 1, 0, 3, 2, 15, 90, 'C', '1-Denetimli alanların tanımları net olarak ayrılmalıdır.\n2-Girişler Kontrollü elektronik kartlı, şifre vb. Giriş olarak düzenlenmelidir.\n3-Çekim esnasında Hamile veya şüphesi olanlar için uyarı işaretleri artırılmalıdır.\n4-Çekim esnasında kontrollü alanlarda Hasta ve Teknisyen dışında hiç kimse olmamalıdır.\n5-Radyasyon Uyarı lambaları aktif olmalı ve kullanılmalıdır.\n6-\"Yetkisiz Çalışan Giremez\" Uyarısı bulunmalıdır.\n7-DİKKAT \"İyonlaştırıcı Radyasyon \" işareti görünür şekilde bulunmalıdır.', '*RADYASYON KOMİTESİ\n*RADYASYON ONKOLOJİSİ BİRİM SORUMLUSU\n*BÖLÜM ÇALIŞANLARI', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM : Radyasyon Onkolojisi', '1- Ortam ölçüm cihazlarının kalibrasyonlarının tekrarlanmaması', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Nükleer tıp bölüm çalışanları', '1- Cihazların kalibrasyonu yapılmaktaıdır.', 1, 0, 1, 10, 7, 70, 'C', '1-Kalibrasyonlar Nükleer Düzenleme Kurulunun belirlediği akredite firmalar tarafından tekrarlanmalıdır.                                                                                                                                                                                                                       2-Alan monitörleri  ve Geiger-Müller cihazı en geç iki yılda bir kalibre edilerek sonuçlar kayıt altına alınmalıdır.', 'İŞVEREN V.                             RKS', '2 YILDA BİR', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM : Radyasyon Onkolojisi', '1- Dozimetre kullanım sürelerinin aşılması', '1-Radyasyona maruziyet sonucu meslek hastalıkları oluşması', '1-Tüm radyasyon onkolojisi çalışanları', '1- Dozimetreler iki ayda bir ölçüme gönderiliyor.', 1, 0, 1, 10, 7, 70, 'C', '1-Nükleer Düzenleme Kurulunun klavuzuna uygun olarak dozimetreler en geç iki ayda bir  ölçüme gönderilmelidir.\n2-Sonuçlar belgelendirilerek arşivlenmelidir.', 'İŞVEREN V.                                 RKS', '2 AYDA BİR', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM : Radyasyon Onkolojisi', '1-Özel politika gerektiren gruplar', '1- Hamile çalışanların düşük yapması veya bebekte nörolojik etkiler', '1- Hamile Çalışanlar', NULL, 1, 0, 3, 3, 7, 63, 'D', '1-Hamile çalışanlar radyasyonlu alanlarda çalıştırılmamalıdır.\n2-Çalışanı gebelik durumunda birim sorumlusunu bilgilendirmelidir.\n3-Birim sorumlusu gebe çalışanın radyasyonlu alanda çalışmaması için yer değişikliği yapmalıdır.', '*RADYASYON KOMİTESİ\n*RADYASYON ONKOLOJİSİ BİRİM SORUMLUSU\n*BÖLÜM ÇALIŞANLARI', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1-Elektrikli ev aletleri (Cezve, Tek gözlü ocak vb.) kullanımı', '1-Yangın riski, \n2- Elektrik çarpması riski, \n3- Yanık ve yaralanma riski,', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 7, 3, 15, 315, 'B', '1. Prizlerin ve kabloların aşırı yüklenmeye karşı sigortalı ve kaçak akım rölesi aktif çalışır olmalıdır.\n2. Cihazların düzenli bakım ve periyodik kontrollerinin yapılmalıdır.\n3. Kullanılmayan cihazların fişten çekilmelidir. \n4. Cihazların ıslak ellerle kullanılmamalıdır.\n5. Yangın söndürücü, duman dedektörü gibi acil durum ekipmanları hazır bulundurulmalıdır. \n6. Çalışanlara elektrikli cihaz güvenliği ve yangın eğitimi verilmelidir. \n7. Uygunsuz cihazların (eski, arızalı, standart dışı) kullanımının yasaklanmalıdır.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'SÜREKLİ KONTROL\n31.12.2026', 4, 3, 15, 180, 'C', 'acik', '1. Sigorta ve kaçak akım rölesi bulunmaktadır.\n2. Cihazların düzenli bakım ve periyodik kontrollerinin yapılmaktadır.\n3. Yangın söndürücü, duman dedektörü gibi acil durum ekipmanları hazır bulunmaktadır.  \n4. Çalışanlara elektrikli cihaz güvenliği ve yangın eğitimi verilmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Hasta Bekleme Alanları Ve Çekim Alanı Koridorlarının Yoğun Ve Havalandırmanın Yetersiz Olması', '1- Solunum yolu hastalıkları, temas yolu ile bulaş', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1. Görüntüleme çekim alanlarının koridorlarında Belirli zamanlarda bekleyen hasta ve hasta yakınları yoğunluğu bulunmaktadır. \n2. Bekleme ve kayıt alanlarında hasta çağrı sistemi mevcuttur. \n3. Hastalar Çekim alanı kapısı önünde teknisyenin çağrısı ile içeri alınmaktadır. \n4. Çalışanlar, hasta ve refakatçileri koridorda geçerken çarpışmalar meydana gelmektedir', 1, 0, 7, 6, 7, 294, 'B', '1. Yoğun koridorlarda Havalandırma sisteminin bakımları düzenli yapılmalı, aktif ve çalışır durumda bulundurulmalı ve sirkülasyonu artırılmalıdır.\n2. Hasta Çağrı sistemi daha etkin ve verimli hale getirilmelidir.\n3. Hasta giriş çıkış güzergahı oluşturulmalıdır\n4. Hasta Yönlendirme Çalışanı görevlendirilmelidir.\n5. Çalışma usulü ve Hasta çağırma sistemi ile ilgili hastalara bilgilendirme yapılmalıdır.', 'İŞVEREN V.\nFİRMA', 'SÜREKLİ KONTROL\n30.10.2026', 7, 6, 7, 294, 'B', 'acik', 'Hasta giriş çıkış güzergahı işaretlemeleri yapılmıştır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Görüntüleme Biriminde (Tomografi, Röntgen,anjiyo x ışını) Denetimli alanda çekim esnasında bulunma', '1-İyonize radyasyona maruziyet', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1. Denetimli ve Gözetimli alan ayrımı ve Denetimli alana kontrollü giriş ve çıkışların olması\n2. Işıklı uyarı sistemleri,\n3. Cihaz periyodik test ve kalibrasyonu,\n4. Radyasyon Güvenliği Talimatları \n5. Dozimetre ölçümleri mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1. Kapı kilit/interlock sistemleri aktif kullanılmalıdır\n2. X-ışını çekimi sırasında odada bulunulmamadır.\n3. Bakım-onarım sırasında güvenlik kilitleri devre dışı bırakılmamalıdır\n4. Denetimli alana geçişlerinde kontrolsüz dolaşım engellenmelidir.\n5. Radyoloji dışı personel için temel radyasyon farkındalık eğitimi verilmelidir\n6. Gebe çalışan ve hastalar alandan uzaklaştırılmalı.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'SÜREKLİ KONTROL\n31.12.2026', 3, 3, 15, 135, 'C', 'acik', 'İçeri giriş ve çıkışlar yüklenici firma(BURTOM) tarafından kontrollü sağlanmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1-İyonize Görüntüleme Alanlarında (Taş Kırma Ünitesi ve Algoloji) Yerden Havalandırma Sisteminin Olmayışı', '1- İyonize Radyasyonun hava ile etkileşiminden dolayı ortaya çıkan (ozon, ozondioksit ve Radon vb ) sağlığa zararlı gazlara maruziyet', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1-  Zemine Yakın emiş Sistemi bulunmamaktadır.', 1, 0, 6, 3, 15, 270, 'B', '1. İyonize Radyasyonun hava ile etkileşiminden dolayı ortaya çıkan (ozon, ozondioksit ve Radon vb ) sağlığa zararlı gazlara maruziyet  TSE EN 14644 Temiz Oda hava akışı ilkeleri standardı çerçevesinde Üstten Üfleme Alttan Emiş Sistemi Kurulmalıdır.\n2. Cihazın kullanımda olmadığı hallerde iç ortama taze hava sağlanmalıdır.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nİŞYERİ HEKİMİ\nFİRMA', 'SÜREKLİ KONTROL\n30.10.2026', 6, 3, 15, 270, 'B', 'acik', 'Algoloji birimi ESWL biriminin yanına taşınmıştır ve Emiş sistemi her iki birimde de bulunmamaktadır. Emiş sistemi kurulması planlanmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Mr Görüntüleme Alanlarına Metal Malzeme İle Girilmesi', '1- Metal nesnelerin fırlaması sebebiyle yaralanma\n2- kalp pili, implant ve stentlerin fonksiyon kaybı, yer değiştirmesi\n3- MR görüntü bozulması', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1.Kontrol önlemleri ve denetimleri işleten firma (burtom) tarafından MR teknikerleri kontrolünde yapılmaktadır.', 1, 0, 6, 3, 15, 270, 'B', '1. Hasta Sorgulaması ve doğrulaması yapılmalıdır. Anamnezi alınmalı, kalp pili, implant, cerrahi vida, protez vb riskler değerlendirilmelidir.\n2. Kontrollü alana giren tüm çalışanlar ve hastaların üzerindeki Metal eşyalar saat, takı, gözlük, saç tokası, nakit para, cep telefonu vb. çıkarılmalıdır.\n3. Acil durumlarda (Quench Butonu ) uygulanacak prosedür bulunmalı ve tüm çalışanlara eğitim verilmelidir.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'SÜREKLİ KONTROL\n31.12.2026', 3, 3, 15, 135, 'C', 'acik', 'İçeri giriş ve çıkışlar yüklenici firma(BURTOM) tarafından kontrollü sağlanmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Kişisel Koruyucuyu Ekipmanların (Kurşun Önlük, Troid Koruyucu Vb.) Yetersiz Ve Kullanımının Kontrolsüz Olması', '1-İyonize radyasyona maruziyet', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1. Görüntüleme alanlarında KKD bulunmakla birlikte eksiklikler ve alım talepleri mevcuttur.\n2. KKD ler genel kullanıma sunulmaktadır. Kişi bazlı zimmetli değildir.\n3. Genel kullanımda olan KKD lerde kirlenme ve enfeksiyon riski oluştuğu gözlemlenmiştir.', 1, 0, 6, 3, 15, 270, 'B', '1. Çalışan sayısı ve işlem yoğunluğuna uygun yeterli kurşun önlük, tiroit koruyucu, gözlük, gonad koruyucu temin edilmeli,\n2. Tüm KKD’lerin yıllık fiziksel kontrolü (kurşun çatlak testi, röntgen veya floroskopi ile) yapılmalı\n3. Kurşun ekipmanların uygun şekilde askılanacağı, zarar görmeyecek biçimde saklanacağı alanların oluşturulmalı', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'SÜREKLİ KONTROL\n30.10.2026', 6, 3, 15, 270, 'B', 'acik', 'Talep yapıldı,Sağlık Müdürlüğü İhtiyaç Tespit Komisyonu tarafından kabul edildi,bütçe bekleniyor.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Ups Priz Ve Sisteminin Amaç Dışı Kullanımı', '1- Yangın riski (aşırı akım, kablo ısınması)\n2- Kısa devre, elektrik çarpması\n3- Kritik sistemlerin (sunucu, görüntüleme cihazları, güvenlik sistemleri vb.) enerjisiz kalması\n4- Donanım arızası veya veri kaybı', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1. UPS prizleri diğer prizlerden farklı renktedir.', 1, 0, 6, 3, 15, 270, 'B', '1. Yetkisiz kullanımın önlenmesi için Tüm UPS prizlerini renk kodu ile ayırılmalı\n2. UPS kapasitesine uygun olmayan tüm cihazların kullanımının yasaklanmalı\n3. Kullanıcı bilgilendirme ve hatırlatma eğitimleri verilmeli', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'SÜREKLİ KONTROL\n30.09.2027', 3, 3, 7, 63, 'D', 'acik', 'Kullanılmaması ile ilgili gerekli uyarı ve eğitmler verildi. Belirli periyotlarla ilgili birim sorumluları tarafından kontroller planlanmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Kimyasal  atıkların uygun ayrıştırılmaması', '1- Kimyasal yanıklar,\n2- Alerjik reaksiyon,', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Kimyasal atık varilleri bulunmaktadır.', 1, 0, 3, 6, 15, 270, 'B', '1- Kimyasal madde kullanım talimatları, MSDS bilgi formu mutlaka bulunmalı ve talimat ve uyarıları dikkate alınarak çalışmalar yapılmalı. \n2- Yapılan işe uygun kişisel koruyucu donanımları kullanmak, bilgilendirme, eğitim, bölümde kullanılan kimyasallara göre güvenlik önlemleri alınması, uygun havalandırma, iklimlendirme, sağlık taramaları düzenli yapılmalıdır. \n3- Etiketsiz kimyasal malzemeler çalışma alanında olmamalıdır.\n4- Kimyasal atıklar tıbbi, evsel ve radyoaktif atıklardan ayrı toplanmalı. Geçici depolama alanları iyi havalandırılmış, kapalı, kilitli ve sadece yetkili Çalışanin erişimine açık olmalı.\n5- Kimyasal atıklar için yönetmeliğe uygun, sızdırmaz, dayanıklı kaplar kullanılmalı.\n6- Atık kapları üzerinde “Tehlikeli Kimyasal Atık” ibaresi ve içerik bilgisi bulunmalı.\n7- Yanıcı/uçucu kimyasallar ateşten ve ısı kaynaklarından uzak tutulmalı.\n8- Kurum içinde sızdırmaz, kapaklı, tekerlekli arabalar ile taşınmalı ve bertarafı sağlanmalıdır.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA\nATIK KOMİSYONU', 'SÜREKLİ KONTROL\n31.12.2026', 3, 3, 15, 135, 'C', 'acik', 'Atıkların ayrıştırılması ile ilgili gerekli uyarı ve eğitmler verildi. Belirli periyotlarla ilgili birim sorumluları tarafından kontroller planlanmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', 'Tibbi Biyolojik Atıkların (parasentez sıvıları ) birim içi saklama koşullarının uygun olmaması', '1. Enfeksiyon Riski', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1. Mevcutta parasentez sıvılarının kapağı açık birşekilde bidonlarda bekletilmektedir. \n2. Bidon üzerinde tanımlama bulunmamaktadır.\n3.Tibbi atık olarak gün içerisinde iki defa atılmaktadır.', 1, 0, 6, 2, 15, 180, 'C', '1. Tibbi atıkların yönetmeliğe uygun birşekilde kapaklı bidonlarda saklanmalı ve yönetmeliğe uygun birşekilde tibbi atık deposuna gönderilmelidir.\n2. tibbi atıklar bekletme alanlarında tanımlı ve etiketli olmalıdır.\n3. Çalışanlara atık ayrıştırma konusunda eğitimler tekrarlanmalıdır.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nATIK KOMİSYONU', 'SÜREKLİ KONTROL\n31.12.2026', NULL, NULL, NULL, NULL, NULL, 'acik', 'Atıkların ayrıştırılması ile ilgili gerekli uyarı ve eğitmler verildi. Belirli periyotlarla ilgili birim sorumluları tarafından kontroller planlanmaktadır. Diyaliz biriminden kapaklı bidon temin edilmesi ve etiketlenmesi hususunda çalışanlara bilgilendirmeler yapıldı.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Kesici Delici Alet Kullanımı', '1- Enfekte hastadan bulaş,', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1. Kesici delici Alet kullanım talimatı bulunmaktadır.\n2. Teşhis ve Tedavi alanlarında kesici atık kutuları bulunmaktadır.\n3. Çalışanlara Temel iş güvenliği ve Atık Yönetim Eğitimleri verilmektedir.\n4. Alana Özgü Kişisel Koruyucu Ekpmanlar tanımlı, kullanıma hazı bulunmaktadır. \n5. Çalışanlara KKD Zimmet Tutanağı imzalatılmaktadır.\n6. Sağlık taramaları yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1. Kesici delici alet yaralanmalarına karşı dikkatli ve iş kurallarına uygun çalışılmalıdır. Uygun Kişisel Koruyucular ve eldivenler kullanılmalıdır.\n2. Çalışanlar İnvaziv işlem esnasında ve sonrasında iğne kapağı katılmadan sharp box kutusuna atılmalıdır,\n3. Atık kaynağında ve mümkünse ilk kullanıcı tarafından bertaraf edilmelidir. İğne uçları farklı atık kutularına (geri dönüşüm evsel atık vb.) atılmamalıdır. Kutunun ağzı açık bırakılmamalı ve 2/3 oranında dolduğunda yenisi ile değiştirilmelidir.\n4. Çalışma alanı düzenli / düzensiz aralıklarla kontrol edilmelidir. Çalışanlara ilgili eğitimler verilmelidir.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'SÜREKLİ KONTROL\n30.10.2026', 6, 6, 7, 252, 'B', 'acik', 'Çalışanlara ilgili eğitimler verilmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Kapı altlarında açıklık sebebiyle Sekonder İyonize Radyasyon Maruziyeti', '1- Sekonder radyason maruziyeti', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Alan tanımlamaları ve  ruhsatlandırması yapılmıştır.', 1, 0, 3, 3, 15, 135, 'C', '1-  Kapı altlarında açıklıkları kapatılmalıdır\n2- Uygun havalandırma/iklimlendirme yapılmalıdır. \n3- Havalandırmaların bakımı yapılarak aktif ve verimli çalışması sağlanmalıdır.\n4- Kaynakla mesafe artırılmalıdır.\n5- Cihazların düzenli kontrolleri ve bakımlarının tekrarları yapılmalıdır.\n6- Tüm çalışanlara düzenli Radyasyon Güvenliği hatırlatma eğitimleri verilmelidir.\n7- Radyasyon çalışanlarının dozimetreleri olmalıdır.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'SÜREKLİ KONTROL\n30.09.2027', 3, 3, 7, 63, 'D', 'acik', 'NDK lisanslama koşulları uygun olduğu görülmüştür ve ileten firma (BURTOM) tarafından düzenli yıllık alan ölçümleri sonuçları görülmüştür.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Alanlarda Bulundurulan Veya Hasta Taşıma Ve Çekim Esnasında Kullanılan Basınçlı O2 Tüpleri', '1- Patlama ve yangın riski, \n2- Gaz kaçağı riski,', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1. Oksijen tüpü sabitleme aparatları bulunmamaktadır.\n2. Hasta taşıma esnasında tekerlekli sandalye ve sedyelerde tüp taşıma aparatı olmadan hastanın bacakları arasında veya yatak kenarına sıkıştırılarak kullanılmaktadır.\n3. MR birimine girişte MR cihazına uygun O2 tüpleri bulunmaktadır ve hastalar içeri firma Teknikeri tarafından kontollü bir şekilde alınmaktadır.', 1, 0, 3, 3, 15, 135, 'C', '1. Tüm alanlarda tüplerin dikey ve zincir/kelepçe ile sabitlenerek saklanmalıdır.\n2. Basınç göstergeleri ve vanaların her kullanımdan önce kontrol edilmelidir.\n3. Oksijen tüplerine yağlı el, yağlı eldiven, gres yağı ile temas edilmemelidir (patlama riski).\n4- Tüplerin sadece uygun regülatör ve basınç düşürücü ile kullanılmalıdır.\n5- Tüp boşaldığında “BOŞ” etiketiyle işaretlenip ayrı alanda saklanmalıdır.\n6- Taşıma sırasında tüp arabası/sehpaları kullanılması gereklidir. \n7-Çalışanın basınçlı gaz tüpleri eğitimi almalıdır. Acil durum prosedürleri (yangın, gaz kaçağı) için tatbikat yapılmalıdır. \n8-Düzenli olarak sızdırmazlık testleri ve bakım kontrolleri yapılması gereklidir.\n9-Hasta taşıma esnasında tüp taşıma aparatı bulunan tekerlekli sandalye ve sedyeler kullanılmalıdır.\n10-MR birimine girişte MR cihazına uygun O2 tüpleri yeteri kadar bulunmalı ve hastalar içeri firma Teknikeri tarafından kontollü bir şekilde alınmalıdır.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA\nHYRRT HİZMETLERİ KOMİSYONU', 'SÜREKLİ KONTROL\n30.10.2026', 6, 3, 15, 270, 'B', 'acik', 'Hasta taşıma esnasında tüp taşıma aparatı temin edilmiştir. Tekerlekli sandalye ve sedyeler Aparatlı kullanılmalıdır.\nTüm alanlarda tüplerin dikey ve zincir/kelepçe ile sabitlenerek saklanma sistemi kurulamamıştır', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Dağınık Kablo Ve Hortumlar', '1- Takılma / düşme sonucu yaralanma\n2- Elektrik kablolarının hasarıyla elektrik çarpması riski\n3- Malzeme devrilmesi / ekipman zarar görmesi\n4- Acil durumda kaçış yolunun kapanması', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1. Kısmi kablo kanalları ve spiral uygulaması mevcut\n2. Kısmen kablolar yuvarlak sarılarak sabitlenme yapılmış', 1, 0, 6, 3, 7, 126, 'C', '1- Elektrik kabloları için kablo kanalları, spiral koruyucu veya yerden geçen hatlara sabitlenmeli\n2- Hortum ve malzemeleri düzenli raf / askı sistemine alınmalı\n3- Çalışma alanlarında Kaçış yollarının sürekli açık olduğunun kontrolü sağlanmalı', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'SÜREKLİ KONTROL\n31.12.2026', 6, 3, 7, 126, 'C', 'acik', 'Firma yetkililerine gerekli uyarılar yapılmıştır ve firma yetkilileri tarafından düzenli aralıklarla kontroller planlanmıştır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Cihazların Kontrol, Bakım Ve Onarımlarının yapılmaması', '1- Elektrik çarpması\n2- Kısa devre ve yangın riski', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1. Hastane görüntüleme hizmetleri, Cihazların Bakım ve Onarımları Hizmet Alt Yüklenici Firma tarafından yürütülmektedir.\n2. Alan Lisanslama çalışmaları Nükleer Düzenleme Kurumu NDK tarafından yapılmakta\n3.Yıllık radyasyon ölçümleri firma tarafından yapılmaktadır.', 1, 0, 6, 3, 7, 126, 'C', '1- Ruhsatlandırma ve Bakım ve Kontrol Kayıtları düzenli denetlenmelidir. \n2- Elektrik ve Radyasyon Güvenliği değerlendirmeleri düzenli /düzensiz aralıklarla kontrol edilmelidir. \n3- Havalandırma ve soğutma sistemleri, Helyum Seviyeleri, Quench Hatları kontrolleri yapılmalıdır.\n4- Kamuya ait cihazların fiziksel elektriksel güç çıkış testleri periyodik kontrolleri yapılmalıdır.\n5- Cihazların yedek parça ve sarf malzemelerinin temizlik bakım ve kontrolleri planlanan zamanlarda yapılmalıdır.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA\nGÖRÜNTÜLEME MUAYENE KABUL KOMİSYONU', 'PERİYODİK KONTROLLE İZLENİR', 0.5, 3, 7, 10.5, 'E', 'acik', 'Bakım ve onarım kayıtları gözlemlenmiştir. Komisyon tarafından takip edilmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Dolap Ve Malzemelerin Sabitlenmemiş (Yora) Olması', '1- Devrilme, \n2- Deprem anında kaçış yolunu kapatma nedeniyle tahliye edilememe ya da gecikme', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Görüntüleme alanlarında ve Hekim odalarında bulunan bazı raflar ve dolapların kısmen yotalandığı tespit edilmiştir', 1, 0, 6, 3, 7, 126, 'C', '1- Çalışan ve birim sorumluları talep açarak alandaki tüm raf ve dolapların en az iki noktadan sabitlenmesini talep etmelidir.\n2- Ayrıca alana yeni getirilen ya da yeri değiştirilen tüm dolap ve rafların sabitlenmesi talep edilmelidir.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'PERİYODİK KONTROLLE İZLENİR', 1, 2, 7, 14, 'E', 'acik', 'Sabitlemeler yapılmıştır. Yeni değişiklik durumunda sabitlemenin gerekli uyarılar yapılmıştır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Radyasyon Alanlarına Yetkisiz Giriş', '1-İyonize Radyasyon riski\n2- Mahremiyet İhlali', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1. Kontrollü ve Gözetimli alanların tanımları yapılmıştır.\n2. Girişler Kontrollü açma butonu ile giriş olarak düzenlenmiştir. \n3. Çekim esnasında Hamile veya şüphesi olanlar için uyarı işaretleri mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1- Denetimli ve Gözetimli alanların tanımları net olarak ayrılmalıdır.\n2- Girişler Kontrollü elektronik kartlı, şifre vb. Giriş olarak düzenlenmelidir.\n3- Çekim esnasında Hamile veya şüphesi olanlar için uyarı işaretleri artırılmalıdır.\n4- Çekim esnasında kontrollü alanlarda Hasta ve Teknisyen dışında hiç kimse olmamalıdır.\n5- Radyasyon Uyarı lambaları aktif olmalı ve kullanılmalıdır.\n6- \"Yetkisiz Çalışan Giremez\" Uyarısı bulunmalıdır.\n7- DİKKAT \"İyonlaştırıcı Radyasyon \" işareti görünür şekilde bulunmalıdır.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'SÜREKLİ KONTROL\n30.09.2027', 1, 2, 15, 30, 'D', 'acik', 'İçeri giriş ve çıkışlar yüklenici firma(BURTOM) tarafından kontrollü sağlanmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Seyyar Görüntüleme Cihazlarının Akü Şarz İşlemlerinin Koridorlarda Yapılması', '1-Parlama ve patlama riski     \n 2- Gaz sızıntısı', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Seyyar Görüntüleme Cihazlarının Akü Şarz İşlemlerinin Koridorlarda Yapılmaktadır.', 1, 0, 3, 2, 15, 90, 'C', '1- Seyyar Görüntüleme Cihazlarının Akü Şarz İşlemleri için tanımlı ve korumalı alanlar belirlenmelidir.\n2- Şarz olduktan sonra fişte bırakılmamalıdır.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'SÜREKLİ KONTROL\n31.12.2026', 3, 2, 15, 90, 'C', 'acik', 'Alan tanımlaması henüz yapılmamıştır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Mr Cihazının Acil (Quench Butonu) Kapatılması Durumunda Ortaya Çıkabilecek Helyum Gazı', '1- Helyum gazının O2 yerini alması sebebiyle Boğulma riski', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları', '1- Manyetik alana sıkışma, yangın gaz kaçağı ve elektriksel acil durumlarda Sıvı Helyum gaz haline geçerek hızla dışarı atılır.\n2- Havalandırma sistemi sızdırması halinde odaya gaz dolarak boğulma riskine sebebiyet verebilir. \n3- Mevcutta yapılmış havaladırma mevcuttur.', 1, 0, 2, 1, 40, 80, 'C', '1- Eğitimli Çalışan dışında kimse dokunmamalıdır.\n2- Havalandırma sisteminin sızdırmazlığı ve çıkış güzergahı düzenli olarak kontrol edilmelidir.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'SÜREKLİ KONTROL\n30.09.2027', 1, 1, 40, 40, 'D', 'acik', 'Herhangi bir olay yaşanmamış ve firma tarafından düzenli aralıklarla eğitimler verilmiştir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Kan ve vücut sıvılarına maruziyet', '1- Enfeksiyon riski,', '1- Çalışanlar', '1-Çalışanlara konu ile ilgili eğitimler verilmiştir\n2- Alanlarda çalışanların kullanması için Eldiven, yüz siperlikleri vb. KKD bulunmaktadır \n3- Zimmet formu imzalatılmaktadır.', 1, 0, 3, 3, 7, 63, 'D', '1. Kan ve Vücut Sıvı maruziyetine karşı dikkatli ve iş kurallarına uygun çalışılmalıdır. Çalışanlar işlem esnasında dikkatli olmalı, \n2. İşlem sonrasında enfekte atıkların bertarafını sağlamalıdır. Atık kutularının ağzı açık bırakılmamalı ve dezenfeksiyonlar düzenli yapılmalıdır. Çalışma alanı düzenli / düzensiz aralıklarla kontrol edilmelidir.\n3. Kan ve vücut sıvılarının bulaş yolları, korunma yöntemleri ve acil durum prosedürleri hakkında düzenli eğitim verilmelidir.\n4- Uygun Kişisel Koruyucular ve eldivenler kullanılmalıdır.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'PERİYODİK KONTROLLE İZLENİR', 1, 2, 7, 14, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Seyyar Cihaz Ve Ekipmanların Fren Sistemlerinin Kullanılmaması', '1- Sıkışma, ezilme, çarpma kaynaklı yaralanma', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Sabitleme ve fren sistemi Kısmen kullanılmaktadır', 1, 0, 6, 3, 3, 54, 'D', '1. Seyyar ekipmanların çalışma sırasında kontrolsüz hareketlerini engelleyecek, devrilme risklerini azaltacak tedbirler alınmalıdır.\n2. Cihaz yerleştirildiğinde tüm teker frenleri kapatılmalıdır.\n3. Fren sisteminin çalıştığı gözle ve elle kontrol edilmelidir. Uygun olmayanlar yenilenmelidir.\n4. Cihazlar geçiş yollarına acil çıkış ve kaçış güzergahlarına bırakılmamalıdır.\n5. Cihaz park alanı tanımlanmalı ve duvara yaslanarak sabitlenmelidir.\n6. Kablo ve aksesuarları toplanmalı takılma riskleri kaldırılmalıdır.\n7. Tüm çalışanlara bilgilendirme eğitimleri verilmelidir.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI\nFİRMA', 'SÜREKLİ KONTROL\n30.09.2027', 6, 3, 3, 54, 'D', 'acik', 'Bilgilendirme eğitimleri verilmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Usg Probları Ve Diğer Kullanılan Malzemelerle Çapraz Enfeksiyon', '1- Enfeksiyon riski,', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları', '1. Cihaz ve Ekipmanların dezenfeksiyonları yapılmaktadır.\n2. Gerekli hallerde tek kullanımlık kılıf / kondom kullanılmaktadır.\n3. Çalışanların kullanması için KKD bulunmaktadır ve Zimmet formu imzalatılmaktadır.', 1, 0, 3, 2, 7, 42, 'D', '1. İşlem esnasında ve sonrasında klinik uygulama standartlarına uygun temizlik ve dezenfeksiyon yapılmalıdır.\n2. Gerektiği hallerde tek kullanımlık kılıf kullanılmalıdır.\n3. Tek kullanımlık jel olmaması halinde Çoklu Kullanılan Jel Bulaşı önleyecek şekilde kullanılır.\n4. Kişisel koruyucu donanımlar (eldiven vb.) kullanılmalıdır.\n5. USG Kullanan ve temizleyen tüm çalışanlara düzenli hatırlatma eğitimi verilmelidir. \n6. Düzenli / Düzensiz kontroller yapılmalıdır.', 'İŞVEREN V.\nBİRİM ÇALIŞANLARI', 'PERİYODİK KONTROLLE İZLENİR', 1, 2, 7, 14, 'E', 'acik', 'Bilgilendirme eğitimleri verilmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Otomatik Kapı Sistemlerinin Çarpması', '1-Sıkışma ve Ezilme Riski\n2- Tahliye ve Acil Durum Engeli', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Yatayda tek nokta sensör bulunmaktadır', 1, 0, 3, 2, 7, 42, 'D', '1. Otomatik kapı ve kepenklerde, Acil durdurma butonları, Otomatik açma/kapanma sistemleri bulunmalı,\n2. İnsan/engel algılayan çift sensör bulunmalı,\n3. Kapı ve kepenklerin üzerinde veya görülebilir bir alanda uyarı işaretleri bulunmalıdır\n4. Motor, fren, sensör ve kontrol panelleri periyodik olarak test edilmelidir.\n5. Arıza ve bakım kayıtları tutulmalıdır.\n6. Çalışanlar Sensörlerin işleyişi ve güvenlik riskleri hakkında bilinçlendirilmelidir.\n7. Kapı kapanırken el ile açmaya çalışılmamalıdır', 'İŞVEREN V.\nFİRMA', 'SÜREKLİ KONTROL\n30.09.2027', 3, 2, 7, 42, 'D', 'acik', 'Tek nokta sensör bulunmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Taş Kırma Ünitesi Tedavi Esnasında Ortaya Çıkan Tekrarlayan Sese Bağlı İşitme Kaybı', '1 İşitme Kaybı', '1- Çalışanlar', '1- Alan tanımlamaları ve  ruhsatlandırması yapılmıştır.', 1, 0, 3, 2, 7, 42, 'D', '1. Ünitede ortam ve kişi maruziyet gürültü ölçümü yapılmalıdır\n2. Cihazın bulunduğu odanın akustik panellerle ses yalıtımı yapılmalı \n3. Çalışanlara işitme koruyucu kullanılmalı\n4. Belirli aralıklarla odyometrik tarama yapılmalı\n5. Maruziyet sürelerinin sınırlandırılması için çalışma planlaması yapılmalı', 'İŞVEREN V.\nİŞYERİ HEKİMİ\nFİRMA', 'PERİYODİK KONTROLLE İZLENİR', 1, 2, 7, 14, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 1:GÖRÜNTÜLEME BİRİMLERİ', '1- Depolama Alanı Yetersizliği Ve Dağınıklığı', '1- Takılma / düşme sonucu yaralanma\n2- Malzeme devrilmesi / ekipman zarar görmesi\n3- Acil durumda kaçış yolunun kapanması', '1- Çalışanlar', NULL, 1, 0, 3, 2, 7, 42, 'D', '1. Depolama alanı kapasitesi yeniden değerlendirilerek yeterli alan oluşturulmalıdır.\n2. Sabitlenmiş Raf  Sistemleri Standartlara uygun şekilde yapılmalıdır.\n3. Malzemelerin yerleşim ve etiketlemeleri yapılmalıdır.\n4. Kimyasal ve tehlikeli madde ve malzemeler ayrı düzenlenmelidir.', 'İŞVEREN V. / \nBİRİM SORUMLUSU', 'PERİYODİK KONTROLLE İZLENİR', 1, 2, 7, 14, 'E', 'acik', 'Raf ve düzenleme yapılmıştır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: ASANSÖRLER', '*Aşırı yük önleme ikaz sisteminin çalışmaması', 'Yaralanma, ölüm', '1-  Tüm Çalışanlar                                             2- Hasta- Hasta Yakınları', 'Tüm asansörlerde aşırı yük sistemi mevcuttur', 1, 0, 3, 2, 40, 240, 'B', 'Aylık bakımlarda firma tarafından kontrol edilmeli, çalışmıyorsa aktif edilmeli  ve uygun kg ayarlanmalıdır.', 'Bakım Firması', 'Periyodik bakım    ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: ASANSÖRLER', '1-Çalışanların asansörü uygunsuz kullanması', '1- Kabin kapısına sıkışma ya da kabin içinde iş kazası yaşanması sonucu yaralanma', '1-  Tüm Çalışanlar                                             2- Hasta- Hasta Yakınları', '1- Asansörlerin kapı fotoselleri mevcuttur.', 1, 0, 3, 6, 15, 270, 'B', '1- Çalışanlar asansör kapıları tam açılmadan asansörlere binmemeli ya da inmemelidir.                                                                     2- Kapanma aşamasında ki kapılara el ile müdahale edilmemeli, kapı fotoselleri aktif olmalıdır.                                                                                            3- Asansör kullanılırken sıkışma riski olan elbise çanta vb. malzemelere dikkat edilmeli, kapıdan en az yarım metre uzakta durulmalıdır.                                                                              4- Asansör içinde şakalaşma yapılmamalıdır.                                                                   5- Asansörlere inip binerken yavaş haraket edilmemelidir.', 'ASANSÖR BAKIM FİRMASI ÇALIŞAN LAR', 'FOTOSEL KONTROL YILDA BİR                             HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: ASANSÖRLER', '1- Asansör kontrol bakım işlerinde güvenlik tedbirlerinin yeterince alınmaması', '1-Kabinin düşmesi  sonucu sıkışma ya da yüksekten düşme sonucu  yaralanma, ölüm', '1-Kontrol bakım yapan çalışanlar', '1- Asansör kontrol ve bakım işleri firma tarafından yapılmaktadır.', 1, 0, 3, 2, 40, 240, 'B', '1- Kuyu altında ya da üstünde yapılacak çalışmalarda sıkışmayı önlemek için kuyu dibi ve kuyu üstü tamponları yerleştirilmeden çalışma yapılmamalıdır.                                                                  2- Kabin altında çalışma yapılmadan önce hız regülatörleri, sınır güvenlik  kesicileri, mekanik fren ve tüm güvenlik tertibatı aktif olmalıdır.                                                                                3- Kuyu içinde yapılacak çalışmalarda elektrik panosu kilitlenmeli ve etiketlenmeli, çalışmalar bir gözlemci yardımıyla yapılmalıdır.                                                                                     4- Kuyu içinde yapılacak yüksekte çalışmalar için çalışanlara yapılan işe ve standartlara uygun bağlantı halatları, kancalar, karabinalar, makaralar, halkalar, sapanlar karşı ağırlık ve dengeleme ağırlığı bloklarını tutan tijler ve benzeri bağlantı tertibatları; gerekli hallerde iniş ve çıkış ekipmanları, enerji sönümleyici aparatlar, yatay ve dikey yaşam hatlarına bağlantıyı sağlayan halat tutucular, TS EN 361 standartında paraşüt tipi emniyet kemeri vb. ekipmanlar verilmeli kullanımı sağlanmalıdır.                                                                          5-Kuyu içinde yapılacak çalışmalarda kuyu kabin vb. yeterince aydınlatılmalı, kuyu, kabin ve ray topraklaması mutlaka yapılmalıdır.                                                                         6- Kuyu içerisinde yabancı cisim bulunmamalı ve kuyu dibi temiz tutulmalıdır.', 'ASANSÖR BAKIM FİRMASI', 'KONTROL BAKIM İŞLERİ ESNASINDA SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: ASANSÖRLER', '1-Yangın algılama sistemi ile uyumlu çalışmama                         2- deprem sensörü', 'Mahsur kalma, boğulma, yaralanma', '1-  Tüm Çalışanlar                                             2- Hasta- Hasta Yakınları', '1-Tüm asansörler yangın algılama sistemine dahildir.         -        2-Tüm Asansörlerde sismik sensör mevcuttur.', 1, 0, 3, 0.5, 100, 150, 'C', '1-Yıllık periyodik muayenede firma tarafından kontrol edilmelidir, bağlantılar kontrol edilerek aktif durumda tutulmalıdır.', 'ASANSÖR BAKIM FİRMASI', 'Periyodik bakım ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: ASANSÖRLER', '1- Asansörlerin engelli çalışanlara yeterince uygun olmaması', '1-İş kazaları yaşanması sonucunda yaralanma', '1- Engelli çalışanlar', '1-Birçok asansör engelli zemin işaretlemeleri mevcuttur.                                       2- Birçok asansörde kat numaraları körler alfabesine göre işaretlenmiştir.', 1, 0, 3, 6, 7, 126, 'C', '1- Asansör kullanım talimatı, kabin içinde kat numaraları ve özellikle acil durum zili  Braille (körler) alfabesine uygun olarak işaretlenmeli, silinen işaretler yenilenmelidir ve sesli anons sistemi aktif olmalıdır.                                                                                        2- Kabin içinde tutunma barları sağlam yapıda olmalı, kırık olmamalıdır.                                                   3- Kabin içi aydınlatmaları her zaman çalışır durumda olmalı, butonlar ve özel işaretlemeler görülebilecek şiddette olmalıdır.                                                                                 4- Kabin dışı kat bekleme alanlarındaki aydınlatmalar her zaman çalışır durumda olmalıdır', 'ASANSÖR FİRMASI', '1 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: ASANSÖRLER', '1- Asansörlerin yük taşıma amaçlı kullanılması                                                                  2- İnsan taşınan asasörlerde atık taşınması', '1- Enfeksiyon ve bulaşıcı hastalıklarına yakalanma                              2- Meslek hastalıkları oluşması', '1-  Tüm Çalışanlar                                             2- Hasta- Hasta Yakınları', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- İnsan taşınan asansörler de yük taşınmamalıdır.                                                                     2-  Acil durum asansörleri (itfayeci asansörleri) sadece acil durum  ve  acil müdahale amaçlı kullanılmalıdır. Teknik servis ve  Beyaz ,mavi, pembe,kırmızı ve diğer kod ekipleri haricindeki kullanımlar engellenmelidir. Yük ve insan taşıma amaçlı kullanılmamalıdır.                                                                     3- Hastanede insan ve yük taşınan asansörler belirlenmelidir.                                                                  4- Yük asansörlerine münkün olduğu kadar çalışan binmemelidir.                                                       5- Özellikle atık taşınan asansörler işaretlenmeli, atıklar sadece bu belirlenmiş asansörlerde taşınmalı ve bu asansörlerin atık taşıma dışında kullanılması önlenmelidir.', 'ASANSÖR BAKIM FİRMASI                 ATIK FİRMASI', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: ASANSÖRLER', '1-Kabin temizliği', 'Enfeksiyon', '1- Çalışanlar                                             2- Hastalar                                                3- Diğer ilgili kişiler', 'Talep açılması halinde temizlik ekibi müdahale etmektedir.', 1, 0, 6, 6, 3, 108, 'C', 'Günlük olarak kabinler temizlenmelidir.', 'TEMİZLİK FİRMASI', 'HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: ASANSÖRLER', '1- Asansörlerin arızalanması, bozulması', '1-Kabinin düşmesi ya da asansörün kat arasında kalması sonucu sıkışma yaralanma, ölüm', '1-  Tüm Çalışanlar                                             2- Hasta- Hasta Yakınları', '1- Asansörlerin kontrol ve bakımları yapılmaktadır.', 1, 0, 1, 1, 100, 100, 'C', '1- Asansörlerin arızalanması ya da bozulması durumunda, hemen acil durum ziline basılmalı, acil durum zil sesi tüm katlardan duyulabilecek seviyede olmalıdır.                                                            2- Asansörün kat arasında kalması durumunda, arıza giderilmeden ve kabin kata güvenli tam yanaşmadan asansör içinden kimse indirilmemeli, kimse kendi çabasıyla çıkmaya çalışmamalıdır.                                                                     3- Bozulan asansörlere sadece yetkili kişiler tarafından müdahale edilmelidir.                                                                     4- Bozulan asansörün etrafı yetkililer tarafından çevrenmeli, insanların yaklaşması önlemelidir.                                                                             5- Acil durum zilleri her zaman çalışır durumda olmalıdır.                                                             6-Asansör kabini ile kat arasında kot farkı olmamalıdır.                                                                            7- Asansör kabini ile kat arasındaki boşluk 35mm aşmamalıdır.                                                                    8- Kabin etek sacı olmalıdır.', 'ASANSÖR BAKIM FİRMASI', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: ASANSÖRLER', '1- Asansörlerin güvenlik koşullarının yetersiz olması                                                           2- Kullanma talimatlarının aşınmış olması', '1- Kabin arasına sıkışma ya da kırık cam kesmesi sonucu yaralanma', '1-  Tüm Çalışanlar                                             2- Hasta- Hasta Yakınları', '1- Asansörlerde akım kesici switchler mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1- Asansörlerin kapı kanatlarında ki akım kesici switchler her zaman aktif olmalıdır.                                                                    2- Asansör çalışırken veya diğer kattayken kapıların açılmamasını sağlayan sistem her zaman çalışır durumda olmalıdır.                                                                                                         3- Asansör içinde kırık çatlak ayna olmamalı, kırılan ya da çatlayan aynalar hemen değiştirilmeli, asasörlerde kullanılan aynalar kırılmaz özellikte olmalıdır.                                                                                                                                                          4- Asansör katta değilken asansör kapısı el ile açılmaya çalışılmamalı, Acil durumlarda açılması gerekiyorsa  acil durum kilit açma anahtarı kullanılarak açılmalıdır.                                                                           5- Her asansörde okunabilir büyüklükte kullanım talimatı bulunmalı, yıpranan ya da aşınan talimatlar değiştirilmelidir.                           6-Kapılar kapanırken  engelle karşılaştığında geri açılması sağlanmalıdır.                                        7- Acil durum kilit açma tertibatı aktif olmalıdır.', 'ASANSÖR BAKIM FİRMASI', '1 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: ASANSÖRLER', '1- Asansörlerde taşıma kapasitesinin belli olmaması                                                   2- Asansörlere taşıma kapasitesinin üzerinde insan binmesi', '1- Taşıma kapasitesinin aşılması sonucu kabinin düşmesi, yaralanma ölüm', '1- Çalışanlar                                             2- Hastalar                                                3- Diğer ilgili kişiler', '1-Bir çok asansörde taşıma kapasiteleri mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1 -Asansör taşıma taşıma kapasitesini ve maksimum kişi sayısını gösteren tabela kapılara, kabin içine asılmalıdır.\n2-Taşıma kapasitesinin en fazla % 10 altında insan taşınmalı, kapasitenin üzerinde insan taşınmamalıdır.                                                               3- Asansör taşıma kapasitesi aşıldığında asasör sesli uyarı vermeli, kabin kapıları kapanmamalı ve asansör çalışmamalıdır.                                                  4- Kabin içi havalandırmaları her zaman aktif olmalı, kontrol bakımları yapılmaldır.', 'ASANSÖR BAKIM FİRMASI', '1 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: ASANSÖRLER', '1- Asansörlerin periyodik kontrollerinin tekrarlanmaması', '1-Asansör kabinin  düşmesi sonucu yaralanma, ölüm', '1-  Tüm Çalışanlar                                             2- Hasta- Hasta Yakınları', '1- Asansörlerin 2025 yılı periyodik kontrol raporları mevucttur.                           2- Asansörlerin AT uygunluk beyanları mevcuttur.', 1, 0, 0.5, 6, 15, 45, 'D', '1- Hastanede bulunan tüm asansörlerin periyodik kontrolleri en geç yılda bir kez TS EN 81-80 standardına göre tekrarlanmalıdır.                                                              2-Hastanede kullanılan tüm asansörler yeşil etikete sahip olmalıdır.                                                                                                      3-  Asansör periyodik kontrolleri akredite olan A1 muayene kuruluşları ve ekipnete kayıtlı yetkili makine mühendisleri tarafından yapılmalıdır.                                                                                                                                                                4- Periyodik kontrol raporlarında uygunsuzluk tespit edilirse, uygunsuzluklar giderilene kadar asansörler kullanılmamalıdır.                                                                    5- Aylık kontrol ve bakımlar düzenli olarak tekrarlanmalı, sonuçlar belgelenmelidir.', 'ASANSÖR BAKIM FİRMASI', 'PERİYO DİK KONTROL               YILDA 1                                           KONTROL VE BAKIMLAR                     AYDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: ASANSÖRLER', '*Taciz (Cinsel-Fiziksel)', '1-Depresyon       2-Öfke                      3-Tükenmişlik sendromu,', '1-  Tüm Çalışanlar                                             2- Hasta- Hasta Yakınları', '1-Güvenlik görevlileri mevcuttur. Gerekli durumlarda 1111 den beyaz kod verilebilmektedir.', 1, 0, 3, 2, 7, 42, 'D', '*İşyerinde cinsel tacize karşı sıfır tolerans politikası oluşturulmalı ve çalışanlara duyurulmalıdır.\n*Cinsel taciz durumlarının bildirilmesi için gizli ve güvenilir başvuru mekanizmaları kurulmalıdır.\n*Taciz iddiaları titizlikle araştırılmalı, mağdur korunmalı ve gerekli disiplin süreçleri işletilmelidir.\n*İşyerinde saygılı ve güvenli bir çalışma ortamı oluşturulmalı, olumsuz davranışlara fırsat verilmemelidir.', 'GÜVENLİK FİRMASI', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: ASANSÖRLER', '*Teknik dosya, At uygunluk beyanı, Ce uygunluk beyanı, Kullanma kılavuzu, Bakım kayıt defteri, Bakım sözleşmesi', 'Güvensizlik', '1-  Tüm Çalışanlar                                             2- Hasta- Hasta Yakınları', 'Tüm Asansörlerin ilgili belgeleri', 1, 0, 1, 1, 15, 15, 'E', 'Yıllık periyodik muayenede firma tarafından kontrol edilmelidir eksik belge tamamlanmalıdır.', 'ASANSÖR MONTAJ FİRMASI   ASANSÖR BAKIM FİRMASI', 'Yıllık Periyodik kontrol, yılda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 2: PANO ODALARI', '1- Elektrik Çarpması', '1-Yaralanma,     2-Uzuv kaybı       3-ölüm', '1-Tüm Çalışanlar        2-Bakım Personeli', '1-Kaçak akım mevcuttur', 1, 0, 3, 2, 40, 240, 'B', '1-LOTO prosedürleri uygulanmalıdır.   2-OG Hücresi yıllık bakımlarda izalasyon testleri yapılmalıdır.                    3-Panoların beslendiği trafo veya sayaç çıkış devrelerinde Kaçak Akım/Toroid rolelerini bulunmalıdır.                               4- Herbir pano önünde izole paspas konulmalıdır.                                                          5-Pano odalarına  TS EN 50321 standartında yalıtkan ayakkabısız girilmemelidir.                                               6-Yetkisiz kişilerin girmesini engelleyici tedbir alınmalıdır.                                             7-Tüm pano odalarının kapısına elektrik çarpma tehlikesi işareti asılmalıdır.                                                  8-Elektrik tesisatının ve topraklamaların periyodik kontrolleri TS HD 60364-4, TS HD 60364-5 , TS HD 60364-6 standartalarına uygun olarak en geç yılda 1 tekrarlanmalıdır.                                  9- Periyodik bakımlarda pano etiketlemeleri kontrol edilmeli ve yanlışlıklar eksiklikler deforme olanlar düzeltilmelidir.                                              10- Panolara ait devre şemaları pano cebinde bulunmalıdır.', 'BAKIM FİRMASI', 'Sürekli', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 2: PANO ODALARI', '1-Yangın algılama dedektörü eksikliği', '1-Yangın', '1 Tüm Çalışanlar         2-Bakım Personeli', '1-Yangın algılama dedektörleri mevcuttur.', 1, 0, 3, 2, 40, 240, 'B', '1-Tavandaki tüm ceplerde yangın algılama dedöktörleri olmalıdır.           2-Asma tavan varsa asma tavan içinde  yangın algılama dedöktörleri olmalıdır                   3-Ortamda yerden yükseltme mevcut ise içinde  yangın algılama dedöktörleri olmalıdır ve zemine olduğu yer işaretlenmelidir.tüm dedektörlerin periyodik bakımları düzenli olarak yapılmalıdır.', 'BAKIM FİRMASI', '6 Ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 2: PANO ODALARI', 'Uygunsuz söndürme sistemi', 'Yangın', '1-Tüm Çalışanlar           2-Bakım Personeli', '1-Sulu Yangın söndürme sistemi mevcuttur.', 1, 0, 3, 2, 40, 240, 'B', '1-Elektrik panolarının olduğu alanlarda sulu söndürme uygun olmayıp, uygun söndürme sistemi kullanılmalıdır.                                          2-Gazlı söndürme sistemlerinin basınçları periyodik kontrollerde kontrol edilmelidir.Uygunsuz olanlar yenilenmelidir.', 'BAKIM FİRMASI', 'Sürekli', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
