INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: JENERATÖRLER, TRİJENERASYON, OTOMATİK KAYAR KAPILAR, IPS SİSTEM, KAR BUZ ERİTME SİSTEMİ', '1-Patlamadan korunma\ndokümanının olmaması', '1-Parlama, patlama\nyangın meydana\ngelmesi', '1-Çalışanlar', NULL, 1, 0, 3, 3, 40, 360, 'B', '1- Patlamadan korunma dokümanı hazırlanmalıdır.\n2- Patlayıcı ortam oluşabilecek alanlar işaretlenmeli ve patlamadan korunma\ndokümanında belirlenen zone ‘lara göre kullanılması gereken exproof\nekipmanlar temin edilmelidir.\n3- Patlayıcı ortam oluşabilecek alanlar “EX Patlayıcı Ortam, Ateşle\nYaklaşma” vb. levhalar ile işaretlenmelidir', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: JENERATÖRLER, TRİJENERASYON, OTOMATİK KAYAR KAPILAR, IPS SİSTEM, KAR BUZ ERİTME SİSTEMİ', '1-Jeneratörler, Trijen Sistem odalarında elektrik\ntesisatlarının exproof\nolmaması', '1-Yangın / Patlama', '1-Çalışanlar', NULL, 1, 0, 3, 3, 40, 360, 'B', '1- Flanş, vana pompa vb. doğalgaz boşalma kaynaklarının en az 1 metre\nyarı çapında bulunan Pano, fiş priz, aydınlatma, gaz dedektörleri, solenoid\nvalf vb. tüm elektrik sistemleri kıvılcım çıkarmayan exproof özellikte\nolmalıdır.\n2- Elektrik kabloları çift izolasyonlu olmalıdır.\n3- Elektrik kabloları açıkta olmamalı, yanmaz kablo kanalları içerisine\nalınmalıdır.\n4- Exproof ekipmanların en geç yılda bir kez periyodik kontrolleri TS EN\n60079 stanrdardına göre \"ATEX\" belgeli kişiler tarafından yapılmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: JENERATÖRLER, TRİJENERASYON, OTOMATİK KAYAR KAPILAR, IPS SİSTEM, KAR BUZ ERİTME SİSTEMİ', '1- Jeneratörler Mazot tanklarının\nsızdırmazlık, katodik\nkoruma ve topraklama\nölçümlerinin\nyapılmaması', '1- Parlama, patlama\nyangın meydana\ngelmesi', '1-Çalışanlar', NULL, 1, 0, 3, 2, 40, 240, 'B', '1- Katodik koruma kontrolleri en geç yılda bir yapılmalıdır.\n2- Mazot tankının yılda en geç bir kez sızdırmazlık testleri yapılmalıdır.\n3- Borular korozyona karşı korunmalıdır.\n4- Tank topraklama ölçümleri yılda bir yaptırılmalı, belgelendirilmelidir', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: JENERATÖRLER, TRİJENERASYON, OTOMATİK KAYAR KAPILAR, IPS SİSTEM, KAR BUZ ERİTME SİSTEMİ', '1-Jeneratörler, Trijenerasyon Sistemi ve yakıt tankları Yangın / Patlama Riski (Yakıt – Elektrik Teması)', '1-Ciddi yaralanma, can kaybı, ekipman kaybı', '1-Çalışanlar', '1-Jenaratör ve Trijen Sistemleri ana binadan uzak konumlanmıştır.                                                           2-Firma tarafından periyodik muayene ve kontrolleri yapılmaktadır.                                                                                                      3-Yakıt depolama tanklarında seviye sensörü, taşma önleme sistemi ve otomatik kapama valfleri mevcuttur.', 1, 0, 3, 2, 40, 240, 'B', '1-Yakıt sızıntılarına karşı jeneratör yakıt hatlarının, bağlantı noktalarının ve tanklarının periyodik kaçak testi yapılmalıdır. Yakıt ikmali sırasında jeneratör tamamen durdurulmuş olmalı; ikmal alanında statik elektrik önleme ekipmanı kullanılmalıdır.                                                                                                           2-Jeneratör bölgesi iyi havalandırılmalı, yakıt buharı birikmesini önlemek için mekanik havalandırma sistemi sürekli çalışır olmalıdır.Jeneratör kabin alanlarında ex-proof (Patlama güvenlikli) aydınlatma ve elektrik tesisatı kullanılmalıdır.Oda içerisinde otomatik yangın algılama ve söndürme sistemi (FM-200, Inert gaz vb.) bulunmalıdır. Topraklama tesisatı düzenli ölçülmeli; kaçak akım röleleri periyodik olarak test edilmelidir.                                                                                                          3-peryodik bakımların ekipnet kayıtlı personel tarafından yapılması ve ekipnete işlenmesi sağlanmalıdır.', 'FİRMA', '2 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: JENERATÖRLER, TRİJENERASYON, OTOMATİK KAYAR KAPILAR, IPS SİSTEM, KAR BUZ ERİTME SİSTEMİ', '1- Elektrik pano\nodalarında sulu sprinkler\nsistemi kullanılması', '1- Elektrik\nçarpması sonucu\nyaralanma', '1-Çalışanlar', '1- 30 MA kaçak akım\nröleleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Elektrik yangınlarında sulu sistemler kullanılmamalıdır.\n2- Elektrik panolarına FM200, NOVEC 1230 vb. otomatik söndürme\nsistemleri kurulmalıdır.\n3- Pano içinde oluşabilecek kıvılcımlar otomatik olarak söndürülmelidir.\n4- Otomatik söndürme sistemi olmayan pano odalarında karbondioksitli\nyangın söndürücüler ya da kuru kimyevi tozlu yangın topları\nbulundurulmalıdır', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: JENERATÖRLER, TRİJENERASYON, OTOMATİK KAYAR KAPILAR, IPS SİSTEM, KAR BUZ ERİTME SİSTEMİ', '1- Doğalgaz kaçakları\noluşması', '1-Parlama, patlama\nyangın meydana\ngelmesi', '1-Çalışanlar', '1- Doğal\nhavalandırma\nsağlanmaktadır.', 1, 0, 3, 1, 40, 120, 'C', '1- Doğalgaz kaçaklarına karşı havalandırma menfezleri her\nzaman açık olmalıdır.\n2- Gaz dedektörleri her zaman aktif ve çalışır durumda olmalıdır.\n3- Gaz ana vanasının yerini gösteren plaka bina girişinde kolayca\ngörülebilecek bir yere asılmalıdır.\n4-Trijen dairesi girişine nötralizatör konulmalı, vücuttaki statik elektrik\nboşaltılmadan ünite içine girilmemelidir', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: JENERATÖRLER, TRİJENERASYON, OTOMATİK KAYAR KAPILAR, IPS SİSTEM, KAR BUZ ERİTME SİSTEMİ', '1- Elektrik tesisatının,\ntopraklamaların, kaçak\nakım rölelerinin, yangın\nrölelerinin periyodik\nkontrollerinin\ntekrarlanmaması', '1- Elektrik\nçarpması sonucu\nyaralanma\n2- Elektrik\nyangınları meydana\ngelmesi', '1-Çalışanlar', '1-Periyodik\nkontroller mevcuttur.', 1, 0, 1, 6, 15, 90, 'C', '1- Elektrik tesisatının, topraklamaların, kaçak akım rölelerinin, yangın\nrölelerinin periyodik kontrolleri TS EN 60079 serisi, TS HD 60364-4 serisi,\nTS HD 60364-5 Serisi, TS HD 60364-6 standartlarına uygun olarak en geç\nyılda bir kez tekrarlanmalıdır.\n2- Her elektrik panosu için ayrı test ve ölçüm yaptırılmalıdır.\n3- Tüm bakım ve kontroller kayıt altına alınmalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: JENERATÖRLER, TRİJENERASYON, OTOMATİK KAYAR KAPILAR, IPS SİSTEM, KAR BUZ ERİTME SİSTEMİ', '1- Elektrik panolarının\nkilitsiz olması\n2- Pano altlarında\nyalıtkan paspas\nbulunmaması', '1- Elektrik\nçarpması sonucu\nyaralanma', '1-Çalışanlar', '1-Pano odalarına giriş\nkartlı sistemdir.\n2- Kaçak akım röleleri\nmevcuttur.', 1, 0, 6, 1, 15, 90, 'C', '1- Elektrik panoları kilitli olmalıdır.\n2- Elektrik panolarının altlarına yalıtkan paspas konulmalıdır.\n3- Pano odalarına girişte kartlı sistem her zaman çalışır durumda olmalı,\nyetkisiz kişilerin pano odalarına girmesi önlenmelidir.\n4- Elektrik ile ilgili yapılan çalışmalarda TS EN 50321 standardında\nyalıtkan ayakkabı kullanılmalıdır', 'FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: JENERATÖRLER, TRİJENERASYON, OTOMATİK KAYAR KAPILAR, IPS SİSTEM, KAR BUZ ERİTME SİSTEMİ', '1- Seksiyonel kapıların\nperiyodik kontrollerinin\ntekrarlanmaması', '1-Kapının düşmesi\nsonucu vücut\nbölümlerinin\nezilmesi, yaralanma', '1-Çalışanlar', NULL, 1, 0, 3, 3, 7, 63, 'D', '1- En geç yılda bir kez kaldırma sisteminin periyodik bakımları yetkili\nkişilerce TS EN 13241+A2, TS EN 12453, TS EN 12604+A1\nstandartlarına uygun olarak tekrarlanmalıdır.\n2- Arıza durumlarında hemen arıza giderilmeli, onarım yapılmadan kapı\nkullanılmamalıdır.\n3-Kapı indirilip kaldırılırken 1 metreden yakın içeride ve dışarıda hiç kimse\nbulunmamalıdır.', 'FİRMA\nÇALIŞANLAR', 'YILDA 1          HER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: JENERATÖRLER, TRİJENERASYON, OTOMATİK KAYAR KAPILAR, IPS SİSTEM, KAR BUZ ERİTME SİSTEMİ', '1-IPS Yetersiz topraklama veya potansiyel farkı                                                             2-IPS Yükte dengesizlik (faz-faz farkı)', '1-Cihaz kasalarında gerilim oluşması, elektrik çarpması                                                       2-Gerilim dengesizliği, izolasyon bozulması', '1-Çalışanlar                   2-Hastalar', '1-Yetkisiz personelin girişine kapalıdır.                                                          2- Uyarı levhaları mevcuttur.', 1, 0, 1, 1, 30, 30, 'D', '1-IPS trafolarında ve panolarda izolasyon kaçaklarına karşı periyodik megger testleri yapılmalıdır.IPS panolarının topraklama baraları, izolasyon trafosu, şasi bağlantıları  düzenli kontrol edilmelidir.                                                                                                                                                              2-IPS panosu çıkışlarındaki üç fazın yük dağılımı düzenli olarak ölçülmeli ve dengesizlik tespit edilirse fazlar yeniden dengeli şekilde dağıtılmalıdır.Tıbbi cihazların bağlı olduğu hatlarda faz dağılımı tek hat üzerinde aşırı yoğunlaştırılmamalı; cihazlar eşit olarak fazlara paylaştırılmalıdır.                                                                                                                3-Klinik alanlarda topraklamasız uzatma kablosu, çoklu priz veya taşınabilir güç dağıtıcılar kullanılmamalıdır.', 'FİRMA\nÇALIŞANLAR', 'SÜREKLİ\nHER GÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: JENERATÖRLER, TRİJENERASYON, OTOMATİK KAYAR KAPILAR, IPS SİSTEM, KAR BUZ ERİTME SİSTEMİ', '1-Hızlı açılıp kapanan air-lock kapılarda açılmama veya aynı anda açılması', '1-Kontrolsüz giriş-çıkış                                             2-Enfeksiyon ve bulaş riski', '1-Çalışanlar', '1-Kayar kapılarda uyarı etiketleri bulunmaktadır.                                                    2-Talep halinde arızalar firma tarafından giderilmektedir.', 1, 0, 3, 3, 5, 45, 'D', '1- Air-lock kapıların periyodik bakımları en geç yılda 1 kez yetkili\nkişilerce yapılmalıdır.\n2- Arıza durumlarında hemen arıza giderilmeli, onarım yapılmadan kapı\nkullanılmamalıdır.', 'FİRMA', 'YILDA 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: JENERATÖRLER, TRİJENERASYON, OTOMATİK KAYAR KAPILAR, IPS SİSTEM, KAR BUZ ERİTME SİSTEMİ', '1-Kar Buz Ertime Sistem arızası otopark giriş -çıkış yüzeyinde oluşan buzlanma (giriş/çıkış rampası)', '1-Kayma–düşme, araç kazası, yaralanma', '1-Çalışanlar                                         2Hasta ve hasta yakınları', '1-Şirket tarafından periyodik bakımları yapılmaktadır', 1, 0, 3, 1, 7, 21, 'D', '1-“Kaygan Zemin” uyarıları görünür şekilde yerleştirilmelidir                                                                                 2-Uygun buz çözücü kimyasal (tuz, kalsiyum klorür vb.) veya sıcak su-buhar yöntemi ile buz çözülmelidir                                                                                                                                                                                                         3-Temizlik ekibi kaymayı önleyen ekipman (kaymaz taban, eldiven vb.) kullanmalıdır                                                                                                                           4-Buzlanmaya sebep olan HVAC sistemi, soğutma hattı, kazan dairesi, sprinkler hattı sızıntısı, klima drenajı gibi teknik altyapılar teknik servise bildirilip kontrol edilmeli. Sistem tamamen kapatılıp güvenli hale getirilene kadar ilgili hat izolasyona alınmalıdır                                                                                                                                                                        5-Hastalar ve personel için güvenli geçiş yolları belirlenmeli. Asansör, koridor, acil giriş gibi kritik noktalar kontrol altında tutulmalıdır', 'FİRMA', 'SÜREKLİ', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
