INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: HAVALANDIRMA SİSTEMLERİ', '1-Kuvvetli ve zayıf akım kablo tavalarının  uygun olmaması', '1-Yaralanma 2-Ölüm', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Kablo tavaları ve kablo spiralleri mevcuttur.', 1, 0, 3, 2, 40, 240, 'B', '1-Kablo tavalarının açık olan kısımları kapatılmalıdır.                                                                    2-Çürümüş kablo spiralleri değiştirilmelidir(Mümkünse çürümeye karşı demir boru veya çelik spiral kullanılmalıdır.                                                                3-Açık kabloların kemirgen hayvanlara karşı korunması için  ilaç kutusu konulmalıdır.', 'Bakım Firması', 'Periyodik bakım 6 ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: HAVALANDIRMA SİSTEMLERİ', '1-Havalandırma kanalı baş çarpma mesafesinde olması', '1-Yaralanma', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Kanalların altındaki perçinlerin bir kısmında mantar takılmış', 1, 0, 3, 3, 15, 135, 'C', '1-Baş mesafesindeki tüm kanalların altındaki tüm perçinlere mantar takılmalı ya da kesilerek sıfırlanmalı.                                                          2-Kanalların alçak mesafede olduğu yerlerde uyarı işaretlemeleri (sarı bant) yapılmalıdır.', 'TBO', 'Sürekli', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: HAVALANDIRMA SİSTEMLERİ', '1-Aydınlatmanın yetersiz olması-Acil Aydınlatmanın olmaması', '1-Düşme    2-Çarpma 3-Güvensizlik hissi', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Aydınlatmalar mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1-3 aylık bakımda akü kontrolü yapılmalıdır.                                               2- Acil aydınlatma  ve Yönlendirme sisteminin çalışıp çalışmadığı elektrik enerjisi kesilerek kontrol edilerek çalışmayanlar aktif edilmelidir.                                                                                                      3-Yönlendirme sistemi üzerindeki yazılar ve yönleri kontrol edilmeli , deforme ve yönleri yanlış  olanlar değiştirilmelidir.                                                                   4-Eksik olan yerlere Acil Aydınlatma ve Yönlendirme tesis edilmelidir.                                                     5-Kullanım ömrü dolmuş olan aküler , bertaraf edilmek üzere Atık birimine teslim edilmelidir.                                                              6- Deforme olan yer yönlendirmeleri yenileri ile değiştirilmelidir.', 'Bakım Firması', 'Periyodik bakım 6 ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
