INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 2:TIBBİ GAZ SİSTEMLERİ', '1-Aydınlatmanın yetersiz olması-Acil Aydınlatmanın olmaması', '1-Düşme 2-çarpma 3-güvensizlik hissi', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Aydınlatmalar mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1-Bahçede bulunan oksijen tüpleri için acil aydınlatma sistemi yapılmalıdır.                                                       2-3 aylık bakımda akü kontrolü yapılmalıdır.                                                 3- Acil aydınlatma  ve Yönlendirme sisteminin çalışıp çalışmadığı elektrik enerjisi kesilerek kontrol edilerek çalışmayanlar aktif edilmelidir.                                                             4- Acil aydınlatma ve Yönlendirme otomatı ve kaçak akım rolesi termal kamera ile kontrol edilmelidir.                                                         5-Yönlendirme sistemi üzerindeki yazılar ve yönlerikontrol edilmeli , deforme ve yönleri yanlış  olanlar değiştirilmelidir.                                           6-Eksik olan yerlere Acil Aydınlatma ve Yönlendirme tesis edilmelidir.                                               7-Kullanım ömrü dolmuş olan aküler , bertaraf edilmek üzere Atık birimine teslim edilmelidir.', 'Bakım Firması', 'Periyodik bakım 4 ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
