INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 28, 'BÖLÜM 3:KAZAN DAİRESİ / BUHAR JENERATÖRÜ SİSTEMİ', '1-Elektrik Çarpması (Pano, Pompa, Brülör)', '1-Yaralanma 2-Ölüm', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Uyarı işaretleri mevcuttur', 1, 0, 3, 2, 15, 90, 'C', '1- LOTO (Kilitleme/Etiketleme) prosedürü uygulanmalıdır.\n2- Kaçak akım rölesi (K.A.R.)kontrolleri yapılmalıdır.\n3- Pano önlerinde yalıtkan paspa konulmalıdır.\n4- Müdahalelerin sadece yetkili personelce yapılmalıdır.                                                          5- Havalandırma üniteleri ve Klima santralleri  topraklanmalıdır.                                                           6- Yıllık olarak torpaklama ölçümleri yapılmalıdır.', 'Bakım Firması', 'Periyodik bakım 6 ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 29, 'BÖLÜM 3:KAZAN DAİRESİ / BUHAR JENERATÖRÜ SİSTEMİ', '1-Aydınlatmanın yetersiz olması-Acil Aydınlatmanın olmaması', '1-Düşme  2-çarpma 3-güvensizlik hissi', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Aydınlatmalar mevcuttur.', 1, 0, 3, 2, 15, 90, 'C', '1-3 aylık bakımda akü kontrolü yapılmalıdır.                                                   2-Acil aydınlatma  ve Yönlendirme sisteminin çalışıp çalışmadığı elektrik enerjisi kesilerek kontrol edilerek çalışmayanlar aktif edilmelidir.                                                                                                      3-Yönlendirme sistemi üzerindeki yazılar ve yönleri kontrol edilmeli , deforme ve yönleri yanlış  olanlar değiştirilmelidir.                                                                   4- Eksik olan yerlere Acil Aydınlatma ve Yönlendirme tesis edilmelidir.                                                     5-Kullanım ömrü dolmuş olan aküler , bertaraf edilmek üzere Atık birimine teslim edilmelidir.                                                              6- Deforme olan yer yönlendirmeleri yenileri ile değiştirilmelidir.', 'Bakım Firması', 'Periyodik bakım 6 ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 30, 'BÖLÜM 3:KAZAN DAİRESİ / BUHAR JENERATÖRÜ SİSTEMİ', '1-Yangın algılama dedektörlerinin eksik olması', '1-Yangın', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Yangın algılama dedektörleri mevcuttur.', 1, 0, 3, 0.5, 40, 60, 'D', '1-Tavandaki tüm ceplerde yangın algılama dedektörü olmalıdır.                                              2-Yangın senaryosu devreye girdiğinde havalandırma sistemine ait tüm damperler yangın senaryosu ile uyumlu çalışmalı  testlerde dampererlerin çalışıp çalışmadığı test edilmelidir.', 'Bakım Firması', 'Periyodik bakım 6 ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 31, 'BÖLÜM 3:KAZAN DAİRESİ / BUHAR JENERATÖRÜ SİSTEMİ', '1-Yetersiz filtrasyon', '1-Enfeksiyon', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Periyodik bakımlar yapılmaktadır.                                 2-Filtreler düzenli aralıklarla değişimi yapılmaktadır.', 1, 0, 3, 1, 15, 45, 'D', '1-6 aylık periyodik bakımlarda filtreler kontrol edilmeli. Kirlenmiş olan filtreler yıkanmalı ya da değiştirilmeli. Yıkama işlemi bir kezdwn fazla yapılmamalı. Bu işlemler kayıt altına alınmalıdır.', 'Bakım Firması', 'Periyodik bakım 6 ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 32, 'BÖLÜM 3:KAZAN DAİRESİ / BUHAR JENERATÖRÜ SİSTEMİ', '1-Sıcak Yüzeylere Temas (Yanık)', '1-Yanık', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Uyarı işaretleri mevcuttur', 1, 0, 3, 2, 7, 42, 'D', '1-Tüm sıcak yüzeylerin ve vana ceketlerinin tam izolasyonlu olması. İzolasyonu bozulan yerlerin ivedilikle tamiri yapılmalıdır.\n2-\"Sıcak Yüzey\" ikaz levhaları konulmalıdır.\n3-Isıya dayanıklı KKD temin edilmelidir.', 'Bakım Firması', 'Periyodik bakım 6 ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 33, 'BÖLÜM 3:KAZAN DAİRESİ / BUHAR JENERATÖRÜ SİSTEMİ', '1-Basınçlı / Sıcak Akışkan Püskürmesi (Buhar/Su)', '1-Yaralanma 2-Ölüm', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Emniyet venti mevcuttur.', 1, 0, 3, 2, 7, 42, 'D', '1- LOTO prosedürü (vana kilitleme, basıncı boşaltma) uygulanmalıdır\n2- Emniyet ventillerinin periyodik testi ve mühürlenmesi yapılmalıdır\n3-Yıllık akredite basınçlı kap (kazan, boyler) periyodik muayenesi yapılmalıdır.\n4-KKD (vizör, ısıya dayanıklı eldiven) kullanılmalıdır.', 'Bakım Firması', 'Periyodik bakım 6 ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 34, 'BÖLÜM 3:KAZAN DAİRESİ / BUHAR JENERATÖRÜ SİSTEMİ', '1-Yetkisiz kişilerin müdahalesi', '1-Yaralanma 2-Ölüm', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Havalandırma/ Isıtma-Soğutma sistemlerinin olduğu mahallere giriş kartlı sistemdir. 2-Kapılar açık bırakılmaktadır.', 1, 0, 1, 1, 40, 40, 'D', '1-Havalandırma/ Isıtma-Soğutma sistemlerinin olduğu mahallere yetkisiz girişler engellenmelidir.                                                                       2-Oda kapılarına yetkisiz kişilerin girmemesi ve tehlike durumunu göstermek için uyarı levhaları asılmalıdır.                                                                 3-Müdahale edecek personel , gözlük,eldiven, baret, yalıtımlı ayakkabı giymeden mahallere girmemelidir.', 'Bakım Firması', 'Sürekli', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 35, 'BÖLÜM 4: PNÖMATİK SİSTEMLER', '1- Kuvvetli ve zayıf akım kablo tavalarının  uygun olmaması', '1-Yaralanma 2-Ölüm', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Kablo tavaları ve kablo spiralleri mevcuttur.', 1, 0, 3, 2, 40, 240, 'B', '1-Kablo tavalarının açık olan kısımları kapatılmalıdır.                                                                      2-Açık kabloların kemirgen hayvanlara karşı korunması için  ilaç kutusu konulmalıdır.', 'Bakım Firması', 'Periyodik bakım 4 ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 36, 'BÖLÜM 4: PNÖMATİK SİSTEMLER', '1-Yetkisiz kişilerin müdahalesi', '1-Çarpılma 2-Yaralanma 3-Ölüm', '1- Çalışanlar                                             2-Teknik personel', '1-Pnömatik  odaları girişi kartlı sistemdir.', 1, 0, 3, 2, 40, 240, 'B', '1-Yetkisiz kişilerin pnömatik odasına yanında teknik personel olmadan girmeleri engellenmelidir.', 'Bakım Firması', 'Periyodik bakım 4 ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
