INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 38, 'BÖLÜM 4: PNÖMATİK SİSTEMLER', '1-Topraklamamnın olmaması', '1-Yaralanma 2-Çarpma 3-Yangın 4-Ölüm', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Sistem topraklaması vardır..', 1, 0, 3, 2, 15, 90, 'C', '1-Yıllık olarak torpaklama ölçümleri yapılmalıdır.', 'Bakım Firması', 'yılda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 39, 'BÖLÜM 4: PNÖMATİK SİSTEMLER', '1-Yangın algılama dedektörlerinin uygunsuz konumu', '1-Geç algılama', '1- Çalışanlar                                                                                             2-Diğer ilgili kişiler', '1-Mevcut dedektör oda ortasında olmayıp kenardadır.', 1, 0, 3, 2, 15, 90, 'C', '1-Dedektörlerin tarama mesafesi dikkate alınarak uygunsuz dedektör uygun yere taşınmalı veya tüm alanı kapsayacak şekilde  dedektör ilavesi yapılmalıdır.', 'Güvenlik görevlisi', 'Her gün', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 40, 'BÖLÜM 4: PNÖMATİK SİSTEMLER', '1-Hareketli aksamlara yaklaşılması', '1-El,kol kaptırma 2-yaralanma', '1- Çalışanlar                                             2-Teknik personel', '1-Belli bir mesafede engel mevcuttur.', 1, 0, 3, 1, 15, 45, 'D', '1- Zincir engellerin sürekliliği sağlanmalı uyarı yazıları ve işaretleri asılmalıdır.', 'Bakım Firması', 'Periyodik bakım 4 ayda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 41, 'BÖLÜM 5: İYOT TANKI', '1-Radyasyon', '1-Radyasyon maruziyeti', '1-Bakımcı                   2- Diğer ilgili kişiler', '1-Odaya girmeden önce iş izni alınmaktadır. İdare fizikçisi tarafından Geiger Müller cihazı ile ölçüm yapılıp yazılı uygunluk alındıktan sonra gerekli KKD\'ler( kurşun önlük, Gonad, eldiven) kullanılarak alana girilmektedir. Elektronik dozimetre ile çalışma\nsırasında radyasyon düzeyi sürekli ölçülüp kayıt altına\nalınmaktadır.', 1, 0, 1, 4, 4, 16, 'C', '1-Alanda geçirilen süreyi mümkün olduğunca kısa tutmak, radyasyon kaynağından uzak durmak ve gerekirse ek koruyucu kalkanlar kullanmak maruziyeti azaltabilir.', 'Bakım Firması', 'SÜREKLİ KONTROL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 42, 'BÖLÜM 5: İYOT TANKI', '1-İzleme sisteminde hata/Ölçümcihazı!', '1-Radyoaktivite ölçüm\ncihazlarının kalibrasyonunun bozulması veya hatalı ölçüm', '1-Bakımcı                   2- Diğer ilgili kişiler', '1-Geiger Müller cihazının kalibrasonu ve bakımı kamu tarafından yapılmaktadır. 2-RNS-TBO\'da elektronik dozimetre mevcuttur.\nÖlçüm yapılmadan önce iş izni alınmaktadır.', 1, 0, 1, 4, 4, 16, 'D', '1-Mevcut durum devam ettirilmeli.                                  2-Radyoaktivite ölçüm cihazlarının\nkalibrasyonunun bozulması veya hatalı ölçümlerin güvenilirliğini azaltarak radyasyon maruziyetinin doğru izlenememesine yol açabileceğinden,\ncihazların düzenli kalibrasyon ve bakımının yapılması sağlanmalıdır.                                        3-İdare tarafından kullanılan cihazların bakım kalibrasyonları talep edilmelidir.', 'Bakım Firması', 'SÜREKLİ KONTROL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 43, 'BÖLÜM 5: İYOT TANKI', '1-Bozunum tank odasına yetkisiz erişim', '1-Radyasyon maruziyeti', '1-Bakımcı                   2- Diğer ilgili kişiler', '1-Odaya kartlı giriş sistemiyle sadece yetkili personelin girişine izin verilmektedir. Aynı zamanda kapının kapalı kalması için kapı\nhidroliği mevcuttur.', 1, 0, 2, 4, 8, 64, 'D', '1-Mevcut uygulamaya devam edilmeli.                                 2-Odaya giriş yetkilendirmeleri sadece onaylı personellere yapılmalıdır.                                            3-Kartlı geçişin arızalanması erişime açık olması durumunda kapı açık olduğunda uyarı verecek sistem değerlendirilmelidir.', 'Bakım Firması', 'SÜREKLİ KONTROL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 44, 'BÖLÜM 5: İYOT TANKI', '1-Yüksekte çalışma', '1-Yüksekten düşme 2-yaralanma', '1-Bakımcı                   2- Diğer ilgili kişiler', '1-Alana girişlerde ve yüksekte çalışmada iş izinsiz çalışma yapılmamaktadır. Yüksekte çalışma için paraşüt tipi emniyet kemeri kullanılmaktadır. Tankların üzerindeki tijlere lanyard bağlanarak çalışma yapılmaktadır.', 1, 0, 2, 4, 8, 64, 'D', '1-Mevcut uygulamalara devam edilmeli.                           2-Uzun süreli olası çalışmalar için sabit yatay yaşam hattı yapılması değerlendirilmelidir.', 'Bakım Firması', 'SÜREKLİ KONTROL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 45, 'BÖLÜM 5: İYOT TANKI', '1-Radyasyon', '1-Radyasyon maruziyeti', '1-Bakımcı                   2- Diğer ilgili kişiler', '1-Bozunum tanklarında radyasyon maruziyetine karşı uygun kişisel koruyucu donanımlar kullanılmakta, ayrıca alana giriş yapılacağı zaman öncelikle İdare Sağlık fizikçileri tarafından\n\"Geiger\" ölçüm cihazı ile tankların bulunduğu mahal kapısının kontrol panosu tarafından dış alanın ölçümü yapılmaktadır ve elektronik dozimetre ile çalışma sırasında radyasyon düzeyi sürekli ölçülüp kayıt altına alınmaktadır. Planlı bakım öncesi\nidare radyonüklit tedavi birimine bildirim yapılarak hasta alımının durdurulması, radyoaktivitenin minimuma/ sıfıra indirilmesi sağlanarak tankların boşaltılması sağlanır. Tüm planlı bakım\nsüreci iş izni ve iş tehlike analizi ile yürütülmektedir.', 1, 0, 1, 4, 4, 16, 'E', '1-Mevcut duruma devam edilmelidir.                        2-Alan tehlike ve riskleri minimize\nedilmeden iş izni verilmemelidir.', 'Bakım Firması', 'SÜREKLİ KONTROL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 46, 'BÖLÜM 5: İYOT TANKI', '1-Biyolojik etkenlere maruziyet', '1-Hastalık, bulaş', '1-Bakımcı                   2- Diğer ilgili kişiler', '1-Bakım, temizlik, numune alma veya arıza müdahalesi sırasında tank içeriğiyle temas veya aerosol oluşumu meydana gelebilir.\nBu durum çalışanlar açısından biyolojik etkenlere maruziyet riski yaratır. Alana girişlerde kişisel koruyucu donanım( maske, tulum, gözlük eldiven) kullanılmakta. iş izin sistemiyle yürütülmektedir.', 1, 0, 1, 4, 4, 16, 'E', '1-Mevcut uygulamalara devam edilmeli.', 'Bakım Firması', 'SÜREKLİ KONTROL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 47, 'BÖLÜM 5: İYOT TANKI', '1-Çalışma ortamı tertip düzen uygunsuzlukları', '1-Kayma takılma düşme sonucu iş kazası', '1-Bakımcı                   2- Diğer ilgili kişiler', '1-İş izni ile yürütülmektedir, çalışma sonrası alan tertip düzen kayma takılma riski değerlendirilerek tehlike ve riskler bertaraf edilerek iş izni onayı verilmektedir. Alanda kaygan zemin\noluşturabilecek sıvı birikimine karşı çizme/iş ayakkabısı\nkullanılmaktadır.', 1, 0, 1, 4, 4, 16, 'E', '1-Mevcut durum devam ettirilmeli.', 'Bakım Firması', 'SÜREKLİ KONTROL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 48, 'BÖLÜM 5: İYOT TANKI', '1-Sesli ışıklı uyarı sistemi arızası', '1-Acil durum bildirilememesi', '1-Bakımcı                   2- Diğer ilgili kişiler', '1-Sesli ışıklı uyarı sistemi tatbikatlarla kontrol edilmektedir.', 1, 0, 1, 4, 4, 16, 'E', '1-Mevcut duruma devam edilmelidir.', 'Bakım Firması', 'SÜREKLİ KONTROL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 49, 'BÖLÜM 5: İYOT TANKI', '1-Pompa / vana arızası', '1-Sıvı transferi sırasında kontrol kaybı veya taşma.', '1-Bakımcı                   2- Diğer ilgili kişiler', '1-Oda içerisindeki pompalar BMS sistemi üzerinden takip edilmektedir. 2-Alanda taşma/sızıntı sensörü bulunmakta olup SCADA üzerinden bildirim gelmektedir. 3-Bozunum tanklarında\nradyasyon maruziyetine karşı uygun kişisel koruyucu donanımlar kullanılmakta, ayrıca alana giriş yapılacağı zaman öncelikle 4-İdare Sağlık fizikçileri tarafından \"Geiger\" ölçüm cihazı ile tankların bulunduğu mahal kapısının kontrol panosu tarafından alanın ölçümü yapılmaktadır ve elektronik dozimetre takılarak alana giriş yapılmaktadır. 5-Aynı zamanda ortam kamera ile\nizlenmektedir. 6-Alana giriş için iş izin prosedürü uygulanmaktadır.', 1, 0, 1, 4, 4, 16, 'E', '1-Mevcut duruma devam edilmelidir.', 'Bakım Firması', 'SÜREKLİ KONTROL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 50, 'BÖLÜM 5: İYOT TANKI', '1-Elektriksel arıza', '1-Pompa veya sensör sisteminde meydana\ngelebilecek ekipman arızası', '1-Bakımcı                   2- Diğer ilgili kişiler', '1-Pompa ve sensör sistemlerinin elektrik tesisatı periyodik olarak kontrol edilmekte ve bakımları planlı şekilde yapılmaktadır.\nElektrik panolarında sigorta ve kaçak akım koruma röleleri bulunmaktadır. Tank seviye sensörü olarak güvenlik kat sayısı yüksek olan radar tip sensör tesis edilmiştir. Yapılan işler iş izin\nsistemiyle takip edilmektedir.', 1, 0, 1, 4, 4, 16, 'E', '1-Mevcut duruma devam edilmelidir.                        2-Pompa veya sensör sisteminde meydana gelebilecek arıza, tank seviyelerinin doğru izlenememesi ve taşma veya sızıntı riskine yol açabileceğinden, düzenli bakım ve testlerin yapılması\nsağlanmalıdır.', 'Bakım Firması', 'SÜREKLİ KONTROL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 51, 'BÖLÜM 5: İYOT TANKI', '1-Bozunum tanklarında elektrik\nkesintisi', '1-Çevresel ve radyolojik risk', '1-Bakımcı                   2- Diğer ilgili kişiler', '1-Bozunum tank odası yedek \"Q7-YEDEK\" şalteri mevcuttur. Olası elektrik kesintisinde bu şalter açılarak enerji verilmektedir.\nYapılan işler iş izin prosedürü ile takip edilmektedir.', 1, 0, 1, 4, 4, 16, 'E', '1-Mevcut duruma devam edilmeli.', 'Bakım Firması', 'SÜREKLİ KONTROL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 52, 'BÖLÜM 5: İYOT TANKI', '1-Gaz zehirlenmesi', '1-Zararlı veya toksik gazlara\nmaruz kalma', '1-Bakımcı                   2- Diğer ilgili kişiler', '1-Bozunum tankına giriş öncesinde, ortamda olası gaz birikimine karşı taşınabilir gaz ölçüm cihazı ile ölçüm yapılmakta, cihaz kalibrasyonları düzenli olarak gerçekleştirilmektedir. Kapalı alanlara giriş prosedürü ve izin sistemi uygulanmakta.', 1, 0, 1, 4, 4, 16, 'E', '1-Mevcut duruma devam edilmeli.                           2-Bozunum tankına giriş öncesinde kapalı alan iş izni mutlaka onaylanmalı ve yetkisiz girişler engellenmelidir.3-Tankta olası gaz birikimi taşınabilir gaz ölçüm cihazı ile giriş öncesi ve işlem sırasında kontrol edilmeli, cihaz kalibrasyonları düzenli olarak doğrulanmalıdır.', 'Bakım Firması', 'SÜREKLİ KONTROL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 53, 'BÖLÜM 5: İYOT TANKI', '1-Görüntüleme sisteminde\narıza', '1-Taşkına geç müdahale', '1-Bakımcı                   2- Diğer ilgili kişiler', '1-Odanın günlük kontrollerinde görüntüleme sistemin çalışıp çalışmadığı kontrol edilmektedir.', 1, 0, 1, 3, 3, 9, 'E', '1-Düzenli bakım ve kontrolü yapılması sağlanmalıdır.', 'Bakım Firması', 'SÜREKLİ KONTROL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
