INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 55, 'BÖLÜM 6: GÜNEŞ KOLLEKTÖRÜ', '1-Topraklamamnın olmaması', '1-Yaralanma 2-Çarpma 3-Yangın 4-Ölüm', '1-Bakımcı', '1-Güneş panellerinde ve topraklama mevcut', 1, 0, 3, 1, 15, 45, 'D', '1-Güneş panallerinin sabitlendiği iskelet dahil topraklanmalıdır ve yıllık kontrollerde ölçüm yapılmalıdır.', 'Bakım Firması', 'Yılda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 56, 'BÖLÜM 6: GÜNEŞ KOLLEKTÖRÜ', '1-Mekanik bağlantıların zayıf olması', '1-Uçma 2-yaralanma 3-ölüm', '1- Çalışanlar                                             2- Hastalar                                                3- Diğer ilgili kişiler', '1-Bağlantıda hem civatalı hem de kaynak sistemi kullanılmış.', 1, 0, 3, 1, 15, 45, 'D', '1-periyodik bakımda cıvata kontrolü yapılmalı, gevşeyenler sıkılmalıdır. İlaveten kaynaklı kısımlar kontrol edilip, çatlayan -kırılan varsa  tamir edilmelidir.', 'Bakım Firması', 'Yılda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 57, 'BÖLÜM 6: GÜNEŞ KOLLEKTÖRÜ', '1-Engellerden geçişte merdiven olmaması', '1-Düşme 2-yaralanma', '1-Bakımcı', '1-Yatay borular geçişe engel teşkil etmektedir ve merdiven yoktur.', 1, 0, 3, 2, 7, 42, 'D', '1-Bakımcının bakım düzergahında bulunan yatay borulardan geçiş için geçiş merdiveni yapılmalıdır.', 'Bakım Firması', 'Sürekli', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 58, 'BÖLÜM 6: GÜNEŞ KOLLEKTÖRÜ', '1-Korozyon', '1-Tetanoz', '1-Bakımcı', '1-Sistemde korozyona uğrayan parçalar vardır.', 1, 0, 3, 1, 7, 21, 'D', '1-Korozyona uğramış ekipmanların boyanması gerekmektedir.', 'Bakım Firması', 'Yılda 1', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 59, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Yangın tüpünün kontrollerinin tekrarlanmaması                           2- Yerlerinin uygun olmaması', '1-Yangın anında çalışmama                   2-Yangının büyümesi sonucu yaralanma', '1-Çalışanlar         2-Hastalar                3-Hasta yakınları', '1-Tüpler mevcuttur.                         2-Periyodik kontrolleri mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1-Tüplerin ayda bir kontrolü yapılmalıdır.                                                          2-Yılda bir bakımı yapılmalıdır.                                                                               3-4 yılda bir söndürme maddesi yenilenmeli ve hidrostatik basınç testi TS ISO 11602-2 standardına göre yapılmalıdır.                                                                                                           4-Söndürme cihazları, kapı arkasında, yangın dolapları hariç kapalı dolaplarda ve derin duvar girintilerinde bulundurulmamalıdır.                                                                                              5-Bakıma alınan yangın söndürme cihazlarının yerine, alınan söndürücü cihazın özelliğinde ve aynı sayıda kullanıma hazır yangın söndürme cihazlarını geçici olarak bırakılmalıdır.', '1-2-3-FİRMA              4-ALAN ÇALIŞANLARI     5-TEKNİK BİRİM', '1-AY                            2-1 YIL                3-4 YIL                             4-5-HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 60, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Dolabın kapağı veya hortum makarasının arızalanması                              2-Hortum veya vananın patlaması', '1-Kullanım sırasında yaralanma                   2-Hortumun açılmaması                   3-Su fışkırması', '1-Çalışanlar         2-Hastalar                3-Hasta yakınları', '1-Dolap ve makaraları kontrol edilmektedir.                   2-Periyodik kontrolleri mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1-Dolap, hortum makarası, hortum ve vanalar aylık(görsel, fonksiyonel) kontrol edilmelidir.                                                                                                                                                                              2-6 aylık (detaylı ara kontrol) yapılmalıdır.                                                                           3-Dolapların hortum makara ve vanaların periyodik kontrolü enaz yılda 1 (TS EN 671-3 standartlarında) yapılmalı kontrol tarihleri etiketlenerek dolabın üzerine asılmalıdır.                                                                                                                                              4-Arıza tespit edildiğinde hemen bakım veya onarım yapılmalıdır.', 'Bakım Firması', '1-AY                            2-6AY                3-1 YIL                             4-HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 61, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Sprink sistemini besleyen borularda su sızıntısı / basınç kaybı', '1-Zemin kayganlığı   2-Elektrik ekipmanına zarar', '1-Çalışanlar         2-Hastalar                3-Hasta yakınları', '1-Bakım ve kontrolleri yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1-Sistem enaz yılda 1 olarak kontrol edilmeli ve bakımları yapılmalıdır.\n2-Tesisat ve ekipman kullanım talimatlarına göre işletilmelidir.                                                                                    3-Sızıntı veya basınç düşüklüğü tespit edildiğinde derhal müdahale edilmelidir.', 'Bakım Firması', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 62, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Sprinklerin periyodik bakım eksikliği', '1-Yangının büyümesi', '1-Çalışanlar         2-Hastalar                3-Hasta yakınları', '1-Bakımları periyodik olarak yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1-Sprinkler sisteminin periyodik bakımları aylık(görsel, fonksiyonel) olarak yapılmalıdır.                                                                                                                                      2-6 aylık (detaylı ara kontrol) yapılmalıdır.                                                                                                       3-Yılda 1 (TS EN 12845 standartları) olarak yapılmalıdır.                                                                                   \n4-Sprinkler başlıkları, boru hatları ve vanalar yetkili ve eğitimli çalışanlar tarafından kontrol edilmelidir.                                                    5-Bakım sırasında tespit edilen arızalar giderilmelidir.\n6-Bakım kayıtları düzenli şekilde tutulmalıdır.', 'Bakım Firması', '1-AY                            2-6AY                3-1 YIL                             4-5-6-7-HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 63, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Dizel yangın söndürme sistemleri yakıt sızıntısı / buhar kaçağı', '1-Yangın çıkması       2-Çevre kirliliği            3-Çalışan yaralanması', '1-Çalışanlar', '1-Dizel yangın söndürme sistemlerinin periyodik kontrolleri mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1-Periyodik kontrol periyotları, TS EN 12845, NFPA 25 ve BYKHY esaslarıyla tamamen uyumlu olmalıdır.\n2-Yakıt deposu, hortum ve bağlantı elemanları darbe, gevşeme veya çatlak açısından gözle denetlenmeli; gerekirse değiştirilmeli, metal depolar statik elektriğe karşı topraklanmalıdır.\n3-Yakıt kaçağı riskini azaltmak için hortum, kelepçe ve bağlantı elemanlarının periyodik bakım planına alınması ve çalışanın yakıt güvenliği konusunda eğitilmesi sağlanmalıdır.                                                                                  4-Sızıntı veya buhar kaçağı tespit edilmesi durumunda sistem durdurulmalı, kaynak belirlenmeli ve ilgili ekipman yetkili teknik çalışan tarafından onarılmalıdır.               \n5-Onarım sonrası sistem basınç ve sızdırmazlık testine tabi tutulmalı, sonuçlar kayıt altına alınmalıdır.', 'Bakım Firması', 'HERGÜN', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 64, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Dizel yangın söndürme sistemleri yakıt depolama alanının uygunsuzluğu', '1-Yangın ve patlama riski', '1-Çalışanlar', '1-Yakıt depoları sızdırmazlık testi ve kontrolü yapılmıştır.', 1, 0, 6, 6, 7, 252, 'B', '1-Akaryakıt depolarının metal bölümleri, ilgili yönetmeliklere göre statik elektriğe karşı topraklanmalıdır.\n2-Depo dolumunda %85 dolumda sesli %90 a geldiğinde akış kesen sistem olmalıdır.                                                                                                    3-Depo, boru ve vanalarda pas ve korozyon olmamalıdır.                                                       4-Depo alanında yanıcı maddeler, kıvılcım kaynağı oluşturabilecek ekipman ve gereksiz malzemeler bulundurulmamalıdır.\n5-Depolama alanı çevresinde “Açık Alev Yasaktır” uyarı levhaları yerleştirilmeli, düzenli temizlik ve kontrol yapılmalıdır.                                                                                       6-Yakıt bidonları veya varilleri Kimyasal Maddelerin Sınıflandırılması, Etiketlenmesi ve Ambalajlanması Hakkında Yönetmeliğe göre yapılmalı, kapaklı ve sızdırmaz kaplarda muhafaza edilmeli taşma kabı yerleştirilmelidir.', 'Bakım Firması', '1-3-4-5-6-HERGÜN        2-DOLUM ESNASINDA', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 65, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Yağmurlama sistemi hattı patlaması / Su kaçağı', '1-Tesisin su basması ve sistem devre dışı kalması.', '1-Çalışanlar', '1-Kontrolleri periyodik olarak yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1-Yağmurlama sistemi hatları ve bağlantı elemanları düzenli olarak gözle kontrol edilmeli, çatlak, sarkma veya gevşeme tespit edilirse derhal onarılmalıdır.\n2-Hattaki sızdırmazlık contaları ve kelepçeler periyodik bakım kapsamında kontrol edilmeli, gerektiğinde yenilenmelidir.\n3-Basınç hattı patlaması veya su kaçağı durumunda sistem durdurulmalı, hasarlı boru veya parça yetkili teknik çalışan tarafından değiştirilmelidir.\n4-Onarım sonrası hattın basınç testi yapılmalı ve sistemin güvenli çalıştığı kayıt altına alınmalıdır.', 'Bakım Firması', '1-2 HERGÜN   3-4-OLAY VE BAKIM SONRASI', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 66, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Otomatik Çalıştırma Sisteminin Arızalanması', '1-Yangına zamanında müdahale edilememesi.', '1-Çalışanlar', '1-Sistem kontrolleri yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1-Otomatik çalıştırma sistemi (sensörler, kontrol panosu, röleler)  yılda 1 test edilmelidir.                                                                                              2-Günlük bakımları yapılmalı arıza veya gecikme tespit edilirse yetkili teknik çalışanlar tarafından onarım yapılmalıdır.(TS 54-14 e göre kontrolleri yapılmalıdır)\n3-Sistemdeki yazılım ve elektronik bileşenlerin güncel ve doğru çalıştığı günlük olarak kontrol edilmelidir.\n4-Arıza tespit edilmesi durumunda sistem durdurulmamalı, manuel devreye alma prosedürleri uygulanmalı ve arıza kaydı oluşturulmalıdır.', 'Bakım Firması', '1-YILDA 1       2-3-GÜNLÜK   4-DURUM TESPİTİNDE', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 67, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Gazlı söndürme sistemlerinde gaz Kaçağı     (fm200, Novec 1230)               2-Sensör ve dedektör arızaları', '1-Boğulma riski, oksijen yetersizliği       2-Çevresel etki                  3-Basınç düşmesi nedeniyle sistemin çalışmaması.', '1-Çalışanlar', '1-Söndürme sistemleri mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1-Gaz tüpleri, boru hatları, bağlantılar ve valfler düzenli olarak sızıntı testine tabi tutulmalı, hasar veya gevşeme tespit edilirse derhal onarılmalı testler EN 54-2, EN 54-4 e göre yapılmalıdır.                                                                       \n2-Kaçak tespit edilen sistem durdurulmalı, gazın kaynağı ve sızıntı noktası yetkili teknik çalışanlar tarafından giderilmelidir.\n3-Onarım ve kaçak giderildikten sonra sistem basınç testi ve gaz dolumu ile test edilerek güvenli çalışma durumu doğrulanmalıdır.', 'Bakım Firması', 'OLAY VE DURUM TESPİTİNDE', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 68, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Gazlı söndürme sistemlerinde manometre veya basınç göstergesi arızası', '1-Gaz eksilmesi fark edilme                  2-Sistem devreye girmediğinde fark edilmez.', '1-Çalışanlar         2-Hastalar                3-Hasta yakınları', '1-Manometre veya basınç göstergesi mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1-Manometre ve basınç göstergeleri (EN 837) standartlarına göre kontrol edilmeli, doğru ölçüm yapmadığı tespit edilen cihazlar yetkili teknik çalışan tarafından onarılmalı veya değiştirilmelidir.\n2-Göstergelerin kalibrasyonu üretici talimatlarına göre periyodik olarak yılda 1 yapılmalıdır.                    \n3-Arıza tespit edilmesi durumunda sistem güvenli şekilde durdurulmalı veya manuel kontrol prosedürleri uygulanmalıdır.', 'Bakım Firması', '1-GÜNLÜK         2-YILDA 1           3-DURUM TESPİTİNDE', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 69, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Gazlı söndürme sistemlerinde elektriksel arıza / kontrol paneli sorunu', '1-Sistem geç veya yanlış devreye girer.', '1-Çalışanlar         2-Hastalar                3-Hasta yakınları', '1-Kontrolleri yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1-Kontrol paneli ve elektrik bağlantıları günlük gözle ve fonksiyon testleri ile kontrol edilmeli, arıza tespit edilirse yetkili teknik çalışan tarafından onarılmalıdır.\n2-Periyodik kontrolleri enaz yılda 1 olacak şekilde yapılmalıdır.                             3-Paneldeki yazılım ve programlamalar güncel ve doğru çalışır durumda olmalıdır; gerektiğinde yeniden yükleme veya güncelleme yapılmalıdır.\n4-Arıza durumunda sistem güvenli şekilde durdurulmalı veya manuel çalıştırma prosedürleri uygulanmalıdır.', 'Bakım Firması', '1-2-GÜNLÜK            3-ARIZA DURUMUNDA', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 70, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Duman perdesinin kapanmaması                         2-Bakımlarının yapılmaması                           3-Otomatik devreye girmemesi                                   4-Duman perdesinin yırtık olması', '1-Yangının ve dumanın diğer alanlara dağılması / sıçraması', '1-Çalışanlar         2-Hastalar                3-Hasta yakınları', '1-Duman perdeleri mevcut                       2-Sensör ve çalışma mekanizma kontrolleri yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1-Duman perdeleri (UL 1784) (EN 12101-5 ) e göre test edilmelidir.                                                                                                             2-Kontrol paneli iletişimi ( TS54-14 e göre) yapılmalıdır.                                                                                                              3-Duman perdesi aylık kontrolde çalışma ve sensör testleri yapılmalıdır.                                                                                                                                 4- 3 aylık kontrolde yangın algılama entegrasyon testleri yapılmalıdır.                                                                                                                                                          5-Yıllık kontrollerde de yangın senaryosuna göre tam testi yapılmalıdır.                                                                                                                6-Duman sızdırmaz özellikte olmalı ve yırtık olmamalıdır.', 'Bakım Firması', '2-AYLIK                3-3 AYLIK                4-YILLIK', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 71, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Jet fanlarının bakımlarının olmaması           2-Sensörlerlerle uyumlu çalışmaması', '1-Dumanın alanı kaplaması', '1-Çalışanlar         2-Hastalar                3-Hasta yakınları', '1-Jet fanlar mevcut                            2-Kontrolleri periyodik olarak yapılmaktadır.', 1, 0, 6, 6, 7, 252, 'B', '1- Aylık kontrolde çalışma ve sensör testleri yapılmalıdır.                                                                   2-3 aylık kontrolde yangın algılama entegrasyon testleri yapılmalıdır.                                                                                                                                                3-Yıllık kontrollerde de tüm jet fan senaryosunun tam testi yapılmalıdır.(TS 54-14 e göre )', 'Bakım Firması', '1 AY 3 AY 1YIL', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 72, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Dizel/Elektrikli yangın söndürme sistemlerinin motor aşırı ısınması', '1-Yangın', '1-Çalışanlar', '1-Sıcaklık kontrolleri yapılmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1-Motor soğutma sistemi (radyatör, fan, su pompası, termostat) düzenli olarak kontrol edilmeli, tıkanıklık, kaçak veya arıza durumunda gerekli bakım yapılmalıdır.\n2-Soğutma suyu ve yağ seviyeleri periyodik olarak izlenmeli, eksikse üretici tavsiyesine uygun şekilde tamamlanmalıdır.\n3-Aşırı ısınma tespit edildiğinde sistem durdurulmalı, kök neden (soğutma arızası, sensör hatası, aşırı yük vb.) belirlenerek gerekli onarım gerçekleştirilmelidir.\n4-Onarım sonrası motor çalışma testi yapılmalı, sıcaklık değerleri kayıt altına alınmalıdır.', 'Bakım Firması', '1-2 HERGÜN              3-4 OLAY DURUM SONRASI', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 73, 'BÖLÜM 7: YANGIN SÖNDÜRME SİSTEMLERİ', '1-Yakıt Dolumu Sırasında Dökülme', '1-Yangın riski                2-Çevre kirliliği            3-Kayma tehlikesi', '1-Çalışanlar', '1-Yetkili çalışan tarafından yapılmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1-Yakıt dolumu sırasında kullanılan hortum, pompa ve bağlantı elemanları sızdırmaz ve sağlam olmalıdır; dolum esnasında taşma riskine karşı ölçüm cihazları ve seviye göstergeleri kontrol edilmelidir.\n2-Tanklar statik elektriğe maruz kalmaması için topraklanmalıdır.                                                   3-Dolum alanında dökülmeyi önleyecek kapalı sistemler veya taşma tepsileri kullanılmalı, çalışanlar Kimyasal dayanımlı koruyucu eldiven (EN 374)\nKapalı tip koruyucu gözlük (EN 166)\nAntistatik özellikli iş elbisesi / tulum (EN 1149-5)\nAntistatik ve yakıt dayanımlı güvenlik ayakkabısı (EN ISO 20345 – S1/S2, FO) kişisel koruyucu ekipman giymelidir.\n4-Dökülme meydana gelirse dolum hemen durdurulmalı, yakıt temizliği ve sızıntının kaynağı yetkili çalışanlar tarafından giderilmelidir.', 'Bakım Firması', 'YAKIT DOLUMU ESNASINDA', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: TERAS ALANLARI', '1- Terastan malzeme düşmesi', '1- Düşen malzemelerin çalışanlara, hasta ve yakınlarına zarar vermesi\n2- Metal aksamın paslı olması sebebiyle kopması', '1- Tüm çalışanlar\n2- Hasta ve hasta yakınları', '1-Terasta bulunan malzemeler sabitlenmiştir.', 1, 0, 3, 3, 40, 360, 'B', '1- Klima dış ünitelerinin ve diğer cihazların sabitlenmelidir.\n2- Dağcıların güvenlik aparatları ve bağlantı halatları periyodik olarak kontrol edilmelidir. Gevşeyen bağlantı vida ve somunlar sıkılmalıdır.\n3- Dağcıların çalışma esnasında düşürebilecekleri malzeme için zemin güvenlik çemberine alınmalı ve geçişler engellenmelidir.\n4- Sabitlenmiş olan malzemeler (güneş paneli, havalandırma ünite ve kanalları vd.) belirli periyotlarla kontrol edilmelidir.\n5- Paslanma olan yüzeyler antipas uygulanmak suretiyle boyanmalıdır.\n6- Tabelaların metal aksamları belirli periyorlarda kontrol edilmelidir.\n7- İlgili mevzuat ve standartlara göre alanda iş ve işlem tesis edilmelidir.', '1- FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: TERAS ALANLARI', '1- Teraslara ulaşımın kontrolsüz olması', '1- İntihar girişimi\n2- Sabotaj girişimi', '1- Görevli olmayan çalışanlar\n2- Hasta ve hasta yakınları', '1- Ana binada teraslara ulaşım güvenlik personeli nezaretinde sağlanmaktadır', 1, 0, 3, 6, 15, 270, 'B', '1- İlgili mevzuat ve standartlara göre alanda iş ve işlem tesis edilerek; FTR binasında yetkisiz kişilerin teraslara erişimi engellenmeli ve uluşam kontrolü sağlanmalıdır.', '1- FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: TERAS ALANLARI', '1- Yangın kaçış kapılarının tahrip edilmiş ya da zor açılıyor oluşu\n2- Çatılara giriş ve çıkışın kontrolsüz olması', '1- Yangın anında çalışanların zarar görmesi\n2- Yüksekten atlama, düşme, yaralanma ve ölüm', '1- Teknik personeller\n2- Hasta ve hasta yakınları\n3- Bakım ve onarım yapacak diğer firma çalışanları', '1- Ana binada yangın söndürme tüpleri teras çıkış holünde bulunmaktadır.\n2- Asansörlerle teraslara ulaşım kısıtlıdır.\n3- Ana binada teraslara ulaşım güvenlik personeli nezaretinde sağlanmaktadır', 1, 0, 3, 2, 40, 240, 'C', '1- Yangın çıkışlarına ulaşılabilirlik ve güvenlik etiketlemelidir.\n2- Yetkisiz kişilerin teraslara erişiminin engellenmesi ve kontrolünün sağlanması.\n3- Bakım, onarım ve tadilat esnasında gereken güvenlik önlemleri alınmalıdır.\n4- Yanma riski yüksek olan malzemelerin (reflektörlü malzeme, cam vd)  takibi ve kontrolü yapılmalıdır.\n5- FTR binasında teras çıkış hollerinde yangın söndürme tüpleri olmalıdır. \n6- İlgili mevzuat ve standartlara göre alanda iş ve işlem tesis edilmelidir.', '1- FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: TERAS ALANLARI', '1-KKD’lerin eksik olması,                           \n2- KKD\'lerin çalışanlar tarafından kullanılmaması', '1-KKD’lerin kullanılmaması sonucunda iş kazaları, meslek hastalıkları oluması', '1- Teknik personeller', '1-Yeterli KKD mevcuttur.                     2-Çalışanlara KKD eğitimi verilmektedir.', 1, 0, 3, 2, 7, 42, 'D', '1- Alanda uygun KKD\'ler (baret, iş ayakkabısı vd.) ile çalışılmalıdır. KKD\'ler ilgili mevzuat ve standartlara uygun olmalıdır.', '1- FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: TERAS ALANLARI', '1-Parapet duvarının alçak olması.', '1- Düşme ve yaralanma riski', '1- Teknik personeller', '1- Parapetler mevcuttur.', 1, 0, 1, 1, 40, 40, 'D', '1- Gemici merdiveni ile çıkılan parapetlerin yüksekliği ilgili mevzuata uygun özellikte olmalıdır.', '1- FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: TERAS ALANLARI', '1-Faraday kafesine ait metal şeritlerin eğrilmiş ve zemine temas ediyor olması\n2- Franklin çubuklarına ait iletken tellerin sarkıyor oluşu', '1- Yıldırım düşmesi esnasında alanda çalışanlara elektrik çarpması.\n2- Kabloların hasar görmesi', '1- Teknik personeller\n2- Çalışanlar\n3- Hasta ve hasta yakınları', '1- Faraday kafesleri mevcuttur.\n2- Franklin çubukları mevcuttur.', 1, 0, 3, 3, 7, 63, 'D', '1- Faraday kafesleri ve Franklin çubuğu tesisatları, ilgili mevzuat ve standartlarına uygun olarak tesis edilmelidir.\n2- Periyodik kontrolleri resmi standartlara uygun olarak sağlanmalıdır.', '1- FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: TERAS ALANLARI', '1- Elektrik kablolarının geçtiği metal kanal ve spiral plastik boruların deforme ve kırık oluşu.', '1- Alanda çalışacak personele elektrik çarpması.\n2- Yağmur kaynaklı sıvı temasıyla kısa devre oluşması.', '1- Teknik personeller', '1- Kablolar için spiral borular ve tavalar mevcuttur.', 1, 0, 3, 1, 15, 45, 'D', '1- Elektrik tesisatının geçtiği metal kanal ve spiral boruların ilgili mevzuat ve standartlara uygun tesis edilmelidir.\n2- Metal kanal kapaklarının eksik olanları takılmalıdır ve topraklaması sağlanmalıdır.\n2- Spiral plastik boruların deforme olanları değiştirilmelidir.\n3- Plastik spiral kullanılan kablolarda demir boru ya da metal spiral kullanılması sorunun tekrar yaşanmaması adına daha sağlıklı bir çözüm olacaktır. \n4- Kemirgenlerin kaboları deforme etmemesi için teraslara ilaçlama  kutusu konulmalıdır.', '1- FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: TERAS ALANLARI', '1- Güvenlik işaretleme eksiklik olması', '1- Yüksekten düşme, çarpma, yaralanma ve yangın', '1- Teknik personeller', '1- Güvenlik işaretleri kısmen mevcuttur.', 1, 0, 3, 1, 15, 45, 'D', '1- Güvenlik işaretlemeleri, ilgili mevzuat ve standartlara uygun olmalıdır.\n1- Gemici merdivenlerinde \"yüksekten düşme tehlikesi\" işaretleri takılmalıdır.\n2- Gerekli KKD (baret, kemer, iş ayakkabısı vb.) olmadan gemici merdivenleri kullanılmamalıdır.', '1- FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: TERAS ALANLARI', '1- Teraslarda inşaat atıklarının bulunması.\n2-  Geçişlerde engellerin bulunması', '1- Takılma, çarpma, düşme, kesici ve delici alet yaralanması', '1- Teknik personeller', '1- Engellerde geçiş köprüsü bulunmaktadır.', 1, 0, 1, 3, 7, 21, 'E', '1- Düzenli temizlik yapılmalıdır.\n2- Geçiş köprüsü bulunmayan alanlara engellerden rahatça geçilebilecek köprü temin edilmelidir.', '1- FİRMA', '3 AY', NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Ocaklarda açık alev kullanılması', '1- Yangın çıkması', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', NULL, 1, 0, 3, 6, 15, 270, 'B', '1- Ocak çevresinde yanıcı/parlayıcı malzeme bulundurulmamalı; yağ birikintileri oluşmadan temizlenmelidir.\n2- Ocak yalnızca yetkili çalışanlar tarafından kullanılmalı, kullanım sonrası gaz/enerji kaynağı kapatılmalıdır.\n3- Alev alabilecek giysi, bez, kâğıt vb. malzemeler ocaktan güvenli mesafede tutulmalıdır.\n4- Gaz dedektörü ve varsa gaz kesme sistemi çalışır durumda tutulmalı; test, bakım ve kontrolleri kayıt altına alınmalıdır.\n5- Gaz kokusu/kaçak alarmında elektrik anahtarlarına dokunulmamalı, açık alev oluşturulmamalı; gaz kesilerek alan havalandırılmalı ve teknik birime haber verilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', '46660', 0.5, 3, 15, 22.5, 'D', 'acik', 'ASM içerisinde ev tipi ocak kullanıldığı, ocaklarda açık alev bulunduğu ve kullanım alanında gaz dedektörü bulunmadığı tespit edilmiştir.  \n\nMevcut risk devam etmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Elektrik kabloların da aşırı yükleme olması', '1- Elektrik yangını çıkması sonucu, yaralanma, boğulma, ölüm', '1- Çalışanlar                                \n2- Hastalar ve hasta yakınları', '1- 30 MA kaçak akım röleleri mevcuttur.                                   2-300 MA yangın röleleri projede mevcuttur.                    3- Aşı muhafaza dolabında UPS mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Priz çoklayıcıların birbirine seri bağlanması yasaklanmalı; yüksek güç çeken cihazlar uygun kesitte sabit tesisattan ve ayrı prizlerden beslenmelidir.\n2- Uzatma kabloları kalıcı tesisat yerine kullanılmamalı; hasarlı, ekli veya standart dışı kablolar derhal kullanım dışı bırakılmalıdır.\n3- Çalışanların izinsiz elektrikli cihaz ve uzatma kablosu getirmesi engellenmelidir.\n4- Elektrik panoları, prizler, kaçak akım koruma düzenleri ve topraklama tesisatı yetkili kişilerce kontrol edilmeli; uygunsuzluklar giderilmelidir.\n5- Mutfak dışında kettle, çay makinesi vb. ısıtıcı cihazların kullanımı engellenmeli; izin verilen cihazlar uygun ve yanmaz yüzeyde kullanılmalıdır.\n6- Aşırı yüklenmeyi önlemek amacıyla priz ve hatların bağlı yükleri teknik birim tarafından değerlendirilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 3, 7, 10.5, 'E', 'acik', 'Kurum tarafından akım korumalı prizler temin edilerek kullanılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Çalışan hasta ve hasta yakınları iletişim problemleri, fiziksel sözlü şiddet,', '1- Hasta ya da yakınları tarafından fiziksel ya da sözlü şiddete maruz kalma sonucu yaralanma,', '1-Çalışanlar', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- Şiddet riski bulunan durumlar için 112\'yi arayarak ve 113 Beyaz Kod Hattı aranarak Beyaz Kod prosedürü uygulanmalı; çalışanlar çağrı yöntemini ve olay sonrası bildirim sürecini bilmelidir.\n2- Şiddet riskinin yüksek olduğu alanlarda güvenlik desteği, çağrı butonu/iletişim imkânı ve gerektiğinde kontrollü erişim sağlanmalıdır.\n3- Çalışanlara iletişim, çatışma yönetimi, güvenli geri çekilme ve şiddet olayında izlenecek prosedür hakkında eğitim verilmelidir.\n4- Şiddet olayları ve ramak kala bildirimleri kayıt altına alınmalı, kök neden değerlendirmesi yapılarak ilave tedbirler planlanmalıdır.', 'İŞVEREN V.', 'SÜREKLİ KONTROL', 1, 2, 7, 14, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Ortam ölçümlerinin yapılmamış olması', '1- İş kazalarında, Meslek hastalıklarında artış', '1- Çalışanlar', NULL, 1, 0, 6, 6, 7, 252, 'B', '1- İş hijyeni ölçümleri, işyerindeki gerçek maruziyet kaynakları ve çalışanların maruziyet süreleri esas alınarak planlanmalıdır.\n2- Gürültü, aydınlatma, termal konfor ve gerekli görülen diğer etkenler için mevzuata uygun ölçüm/testler yetkili laboratuvar veya kişilerce yaptırılmalıdır.\n3- Kişisel maruziyet değerlendirmesi gereken etkenlerde çalışan maruziyet ölçümleri yapılmalıdır.\n4- Sonuçlar ilgili sınır/değerlendirme değerleri ile karşılaştırılmalı; uygunsuzluklarda öncelikle kaynağında ve toplu korunma tedbirleri uygulanmalıdır.\n5- Proses, ekipman veya ortam koşulları değiştiğinde ölçüm ihtiyacı yeniden değerlendirilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Yangın tüplerinin yetersiz olması                                     2- Kontrollerinin tekrarlanmaması                           2- Yerlerinin uygun olmaması', '1-Yangın anında çalışmama                   2-Yangının büyümesi sonucu yaralanma', '1-Çalışanlar         2-Hastalar               ve Hasta yakınları', '1-1 adet yangın tüpü mevcuttur.', 1, 0, 6, 6, 7, 252, 'B', '1- Taşınabilir yangın söndürme cihazlarının türü, sayısı ve yerleşimi alanın yangın sınıfı ve riskine göre belirlenmeli; erişilebilir ve görünür noktalarda bulundurulmalıdır.\n2- Elektrik ekipmanlarının bulunduğu alanlarda uygun söndürücü tip seçimi yapılmalı; gerekli görülen noktalarda CO₂ söndürücü bulundurulmalıdır.\n3- Cihazların yerinde ve erişilebilir olduğuna ilişkin düzenli kullanıcı kontrolleri yapılmalı; yetkili servis bakım/kontrolleri ilgili mevzuat ve standarda uygun yürütülmelidir.\n4- Basıncı düşmüş, mühürü bozulmuş, hasarlı veya bakım zamanı geçmiş cihazlar derhal değiştirilmelidir.\n5- Cihazların önü kapatılmamalı; konumları uygun işaretlerle gösterilmelidir.\n6- Bakıma gönderilen cihazların yerine risk devam ettiği sürece yeterli sayıda kullanıma hazır söndürücü bırakılmalıdır.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', 'Alanda 1 adet 6kg kuru kimyevi tozlu söndürücü mevcuttur.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Doğalgaz vanalarında ya da borularında gaz kaçağı olması', '1- Parlama, patlama yangın meydana gelmesi', '1- Çalışanlar \n2- Hasta ve Hasta Yakınları\n3- Diğer ilgili kişiler', '1- Gaz dedektörleri mevcuttur.', 1, 0, 3, 2, 40, 240, 'B', '1- Gaz algılama sistemi çalışır durumda tutulmalı; mümkünse selenoid/emniyet vanası ile entegre edilerek kaçak halinde gaz otomatik kesilmelidir.\n2- Gazlı cihaz bağlantıları üretici talimatı ve yetkili tesisat şartlarına uygun olmalı; uygunsuz/eski bağlantılar kullanılmamalıdır.\n3- Her cihazın kolay erişilebilir kapatma vanası bulunmalı; ana ve cihaz vanaları işaretlenmeli, önleri kapatılmamalıdır.\n4- Doğalgaz tesisatı, cihazlar, gaz dedektörleri ve gaz kesme elemanlarının bakım/kontrolleri yetkili kişilerce yapılarak kayıt altına alınmalıdır.\n5- Gaz kokusu veya alarm halinde ateş/kıvılcım oluşturulmamalı, elektrik anahtarlarına dokunulmamalı; gaz güvenli şekilde kesilmeli, alan havalandırılmalı ve yetkili birime haber verilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 1, 40, 20, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Acil çıkış yollarının, kapılarının malzemeler ile kapatılması', '1-Acil durumlarda hızlı tahliyenin sağlanamaması sonucunda durumun etkisinin ve şiddetinin artması', '1- Çalışanlar                                \n2- Hastalar ve hasta yakınları\n3- Diğer ilgli kişiler', '1- Acil çıkış yönlendirmeleri mevcuttur.', 1, 0, 3, 3, 15, 135, 'C', '1- Kaçış yolları ve acil çıkış kapıları her zaman açık, engelsiz ve kullanılabilir tutulmalıdır.\n2- Kaçış yolu üzerine malzeme, mobilya, saksı veya geçişi daraltacak herhangi bir unsur konulmamalıdır.\n3- Acil çıkış ve yönlendirme işaretleri görüşü engellenmeyecek biçimde konumlandırılmalı; acil aydınlatma sistemi çalışır durumda tutulmalıdır.\n4- Kaçış yolu genişliği ve kapı özellikleri binanın kullanım sınıfı, kullanıcı yükü ve onaylı yangın projesine göre kontrol edilmelidir; sabit bir genişlik değeri tüm alanlara genellenmemelidir.\n5- Günlük saha kontrollerinde kaçış yollarının açıklığı kontrol edilmelidir.', 'İŞVEREN V.\n\nÇALIŞANLAR', 'SÜREKLİ KONTROL', 0.5, 2, 15, 15, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- İSG dosyalarının (eğitim bilgilendirme formu, iş kazası tebellüğ formu, KKD zimmet formları vb.) birimler tarafından oluşturulmaması', '1-Çalışanlara yasal yükümlülüklerin bilgilendirilmemesi ve kayıt altına alınmaması', '1-Çalışanlar', NULL, 1, 0, 3, 3, 15, 135, 'C', '1- İş sağlığı ve güvenliği eğitim bilgilendirme formu, KKD zimmet formu, KKD kullanım talimatı birimdeki bütün çalışanlara tebliğ edilmelidir.                                                                                            2- İş kazası prosedürü, iş kazası ön bildirim formu, iş kazası bildirimi tebliğ tebellüğ formu  birimdeki bütün çalışanlara tebliğ edilmelidir.                                                                          3- Kimyasal deoplama matrisleri, kimyasal işaretleme  ve sdslerin alanda görünür bir yerde asılı olması ve dosyada bulunmalıdır. \n4- İSG dosyası içerisindeki tüm evraklar bütün çalışanlar tarafından tebliğ alındığına dair imzalanmalı ve İSG dosyaları hem çalışan hem de dosya içerisine daha sonradan dahil edilen evraklar açısından güncel tutulmalıdır.\n5- Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.\n\nBİRİM SORUMLUSU\n\nALAN ÇALIŞANLARI', 'SÜREKLİ KONTROL', 0.5, 1, 15, 7.5, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Elektrik kablolarında yırtık, izolasyon bozukluğu olması,                                                                                   2- Ekli kabloların kullanılması', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm', '1- Çalışanlar', '1- 30 MA kaçak akım röleleri mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1- Elektrik kablolarında yırtık, izolasyon bozlukluğu vb. olmamalı, olan kablolar kullanılmamalı değiştirilmelidir.                          \n2- Elektrik kabloları ağır malzeme ya da ekipmanların altına konulmamalı, kabloların ezilmesi önlenmelidir.                                            \n3- Kablolarda olan izolasyon açıklıkları izole bant ile kapatılmamalı, ekli kablolar değiştirilmelidir.\n4- Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 10, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Oksijen ya da basınçlı tüplerin uygunsuz kullanılması', '1-Fiziksel olarak patlaması sonucu vücut bölümlerinin yaralanması', '1- Çalışanlar                                2- Hastalar ve hasta yakınları\n3- Diğer ilgli kişiler', '1- Tekerlekli sabitleme aparatı mevcuttur.', 1, 0, 3, 6, 7, 126, 'C', '1- Basınçlı gaz tüpleri devrilmeye karşı uygun taşıyıcı üzerinde veya duvara/zemine sağlam şekilde sabitlenmelidir.\n2- Tüpler ısı kaynaklarından, doğrudan güneşten ve darbe riskinden korunmalıdır.\n3- Oksijen tüpü vana, regülatör ve bağlantılarına yağlı/greaslı el veya malzeme ile temas edilmemelidir.\n4- Regülatör, manometre, vana ve hortumlar kullanılan gazla uyumlu ve sağlam olmalı; hasarlı ekipman kullanılmamalıdır.\n5- Tüpler taşınırken koruyucu başlık kullanılmalı, vana/regülatörden tutularak taşınmamalıdır.\n6- Dolu ve boş tüpler işaretlenerek ayrılmalıdır.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 11, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Kan alma işlemi sırasında uygun tedavi arabası/raf bulunmaması nedeniyle numune tüplerinin lavabo kenarına bırakılması', '1-Biyolojik risk                     2-Dağınıklık                            3- Numune güvenliği ihlali', '1-Çalışanlar', NULL, 1, 0, 3, 6, 7, 126, 'C', '1- Kan alma işlemleri için temizlenebilir yüzeyli, düzenli ve yeterli çalışma alanı/tedavi arabası sağlanmalıdır.\n2- Numune tüpleri için sabit ve devrilmeye dayanıklı tüp rafı kullanılmalı; tüpler lavabo kenarı veya kontamine yüzeylere bırakılmamalıdır.\n3- Temiz alan ile lavabo/kirli alan fiziksel veya fonksiyonel olarak ayrılmalıdır.\n4- Kan/vücut sıvısı bulaşı halinde uygulanacak temizlik-dezenfeksiyon prosedürü belirlenmeli; uygun döküntü ekipmanı erişilebilir olmalıdır.\n5- Kesici-delici atık kutusu işlem noktasına yakın ve güvenli konumda bulundurulmalıdır.', 'İŞVEREN V.               \n\nBİRİM SORUMLULARI\n\nÇALIŞANLAR', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 12, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Çalışma alanında (klinik çalışma deskleri, muayene odaları,vb.) mutfak alanları dışında yiyecek-içecek tüketilmesi', '1-Enfeksiyon kaynaklı bulaş                                 2-Elektrik kablosuna sıvı teması sonucu elektrik çarpması', '1-Çalışanlar', '1-Klinik içerisinde personellere dinlenme alanları belirlenmiştir.', 1, 0, 3, 6, 7, 126, 'C', '1-Çalışanlar müdahale odası, hasta odası gibi enfeksiyon kaynağı ve elektrik kablosuna sıvı teması bulundurulabilecek alanlarda yiyecek-içecek tüketmemelidir.                                               \n2-Personel için ayrı ve uygun dinlenme/yemek alanı oluşturulmalıdır.                                                                                                                                                                                                                                                                                                                                                                                                      3-Çalışanlara, yiyecek–içecek tüketiminin hastane enfeksiyonlarına, kimyasal/biyolojik madde bulaşına ve çalışan sağlığına yönelik risklerine karşı eğitim verilmelidir.\n• Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.\n\nBİRİM SORUMLUSU\n\nALAN ÇALIŞANLARI', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 13, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Hastalardan inhalasyon yoluyla hastalık bulaşması', '1-Enfeksiyon, bulaşıcı hastalıklara yakalanma', '1- Çalışanlar', '1-KKD\'ler mevcuttur.                                         2- Çalışanlara KKD önemi ve kullanımı konusunda eğitim verilmektedir.', 1, 0, 3, 6, 7, 126, 'C', '1- Solunum yolu ile bulaş şüphesi bulunan hastalarda triyaj ve izolasyon önlemleri kurum enfeksiyon kontrol prosedürüne göre uygulanmalıdır.\n2- Oda/alan havalandırması risk değerlendirmesine göre yeterli olmalı; gerekli alanlarda uygun mekanik havalandırma ve filtrasyon sağlanmalıdır.\n3- Çalışanlar riskin niteliğine göre uygun solunum koruyucu kullanmalı; FFP2/N95 ve üzeri maskelerde doğru takma ve sızdırmazlık kontrolü eğitimi verilmelidir.\n4- El hijyeni, göz/yüz koruması ve eldiven kullanımı bulaş yoluna göre uygulanmalıdır.\n5- Temas sonrası yüzey temizlik ve dezenfeksiyonu enfeksiyon kontrol prosedürüne göre yapılmalıdır.', 'İŞVEREN V.\n\nBİRİM SORUMLULARI   \n\nÇALIŞANLAR', 'SÜREKLİ KONTROL', 1, 2, 7, 14, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 14, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Döküntü kiti bulunmaması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması', '1- Çalışanlar', '1-Alanda döküntü kiti bulunmamaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Kullanılan kimyasalların türü ve miktarına uygun döküntü kiti kolay erişilebilir yerde bulundurulmalıdır.\n2- Dökülme müdahale talimatı hazırlanmalı; çalışanlara döküntünün sınırlandırılması, toplanması, atıklaştırılması ve olay bildirimi konusunda eğitim verilmelidir.\n3- Müdahalede SDS\'de belirtilen uygun eldiven, göz/yüz koruyucu ve gerekiyorsa solunum koruyucu kullanılmalıdır.\n4- Güncel Güvenlik Bilgi Formları (SDS) erişilebilir olmalı; kimyasallar etiketli ve uyumlu şekilde depolanmalıdır.\n5- Büyük/tehlikeli dökülmelerde alan izole edilmeli ve eğitimsiz personelin müdahalesi engellenmelidir.', 'İŞVEREN V.\n\nBİRİM SORUMLULARI   \n\nÇALIŞANLAR', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 15, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Elektrik kablolarının, priz vb. elektrik sistemlerinin su ya da sıvı maddeler ile temas etmesi', '1-Elektrik çarpması sonucu kalp ritim bozuklukları, ölüm', '1- Çalışanlar', '1-30 MA kaçak akım rölesi mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1-Su ya da sıvı maddeler bulunduran cihazların bağlantı yerlerinde ve hortumlarında hiç bir sızıntı olmamalıdır.                                                                                2- Cihazların elektrik kablolarında izole bant ile bantlanmış ekler olmamalıdır.                                                                                                                          3- Elektrik kabloları çift izolasyonlu olmalıdır.                                                                                                                4- Su ya da sıvı sızdırabilecek cihazlar fiş priz vb. elektrik sistemlerinden uzakta tutulmalı, suyun elektrik ile temas etmesi önlenmelidir.                                                                                                               5- Cihazların bakım ve kalibrasyonları  yapılmalıdır.\n6-  Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 16, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Çalışma alanında (klinik çalışma deskleri, muayene odaları,vb.)  kabloların dağınıklığı', '1- Elektrik çarpmaları                                      2- Takılma/düşme kaynaklı iş kazaları', '1-Çalışanlar', NULL, 1, 0, 3, 6, 7, 126, 'C', '1-Cihaz kabloları için kablo kanalı, kablo düzenleyici, spiral hortum veya kablo köprüsü kullanılmalıdır.  \n2- Elektrik kabloları çift izolasyonlu olmalıdır.\n3- Kabloların zeminde serbest dolaşması engellenmeli; duvar veya tavan üzerinden düzenli geçiş sağlanmalıdır.                                                                              \n4-Cihazların enerji kabloları standartlara uygun uzunlukta olmalı; kırık, ezik veya yıpranmış kablolar kullanımdan kaldırılmalıdır.                                                                                                                   5-Günlük temizlik kontrollerinde kabloların düzeni gözlemlenmeli ve dağınıklık giderilmelidir.\n• Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.              \n\nBİRİM SORUMLULARI    \n\nÇALIŞANLAR', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 17, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Tehlikeli kimyasalların yanlış depolanması', '1-Kimyasal maddelere maruziyet sonucu iş kazaları yaşanması                                 2- Yangın meydana gelmesi', '1-Çalışanlar       2-Hasta ve hasta yakınları', '1- Kimyasallar Engelli WC alanında depolanmaktadır.', 1, 0, 3, 6, 7, 126, 'C', '1- Kimyasallar WC gibi amacı farklı alanlarda depolanmamalı; kilitlenebilir, havalandırılan ve kimyasal depolamaya uygun ayrı bir alan/dolap oluşturulmalıdır.\n2- Güncel kimyasal envanter ve SDS\'ler bulundurulmalı; maddeler uyumluluk/depolama matrisine göre ayrılmalıdır.\n3- Yanıcı, oksitleyici ve aşındırıcı gibi uyumsuz kimyasallar birbirinden ayrılmalı; ateşleme ve ısı kaynaklarından uzak tutulmalıdır.\n4- Kaplar orijinal etiketli, kapalı ve dik konumda tutulmalı; ikincil kaplarda da uygun etiketleme yapılmalıdır.\n5- Sıvı kimyasallarda uygun ikincil sızdırmazlık/taşma tepsisi kullanılmalıdır.\n6- Depolama alanına yetkisiz erişim engellenmeli; yiyecek-içecek bulundurulmamalıdır.', 'İŞVEREN V.  \n\nALAN ÇALIŞANLARI', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 18, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Acil çıkış kapısının uygun olmaması ve panik bar olmaması', '1-Yangın                  2-Tahliye esnasında kaçışı engellemesi', '1-Çalışanlar      2-Hasta ve hasta yakınları 3-Diğer ilgili kişiler', NULL, 1, 0, 3, 1, 40, 120, 'C', '1- Acil çıkış kapısının kaçış yönünde açılması, kolay ve anahtarsız açılabilmesi ile gerekli panik çıkış donanımı; kullanıcı yükü, kapının kullanım amacı ve onaylı yangın projesi esas alınarak kontrol edilmelidir.\n2- Panik bar gereken kapılarda uygun standarda sahip donanım kullanılmalı ve çalışır durumda tutulmalıdır.\n3- Kapı önleri ve kaçış yolu sürekli açık tutulmalı; kapı kilitli veya kullanım dışı bırakılmamalıdır.\n4- Acil çıkış yönlendirmesi ve acil aydınlatma çalışır durumda olmalı; periyodik fonksiyon testleri kayıt altına alınmalıdır.\n5- Yangın kapısı niteliğindeki kapılarda kendiliğinden kapanma ve sızdırmazlık özellikleri korunmalıdır.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', '46660', 0.5, 1, 40, 20, 'D', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 19, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Atık varillerin kapaklarının açık bırakılması', '1-Zehirlenme, toksik maddelere maruz kalma', '1- Çalışanlar', '1-Renk kodlarına göre atık varilleri mevcuttur.', 1, 0, 6, 6, 3, 108, 'C', '1- Atık varillerinin kapağı sürekli olarak kapalı halde tutulmalıdır. \n2- Atıklar karıştırılmamalı, her atık türü için (Tıbbi, Tehlikeli, Evsel)belirlenmiş renk kodlu atık kutularına atılmalıdır.                                                                                                                                                    3- Kesici delici aletler sadece kesici delici alet kutusuna atılmalıdır.                                                                                                                           4- Atık varilleri en fazla 3/4 oranında dolduğunda değiştirilmelidir.\n5- Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.              \n\nBİRİM SORUMLULARI    \n\nÇALIŞANLAR', 'SÜREKLİ KONTROL', 0.5, 2, 3, 3, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 20, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Hasta ve çalışanların ortak kullandığı WC alanında tıbbi atıkların depolanması', '1- enfekte alanlara yetkisiz erişim                2-Biyolojik etkenlerle temas              3-Çapraz kontaminasyon', '1- Çalışanlar', '1- Çalışanlar ve hastalar için ortak WC mevcuttur.         2- Tıbbi atıklar atık toplama firması tarafından 15 günde bir toplanmaktadır.', 1, 0, 6, 6, 3, 108, 'C', '1- Tıbbi atıklar hasta/çalışan WC\'sinde depolanmamalı; mevzuata uygun, yetkisiz erişime kapalı geçici depolama alanına alınmalıdır.\n2- Geçici depolama alanı temizlenebilir/dezenfekte edilebilir yüzeylere, uygun havalandırmaya ve atık sızıntılarına karşı kontrollere sahip olmalıdır.\n3- Tıbbi atıkların bekletme süresi ve gerekiyorsa soğutma koşulları ilgili tıbbi atık mevzuatına göre belirlenmelidir; sabit \'+4 °C\' şartı tüm durumlara genellenmemelidir.\n4- Atıklar kaynağında ayrıştırılmalı, kaplar kapalı tutulmalı ve taşıma/depolama işlemleri eğitimli personelce yapılmalıdır.\n5- Atık toplama sıklığı oluşan atık miktarı ve depolama kapasitesine göre planlanmalıdır.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 2, 3, 3, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 21, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Çalışanlara ait ayrı personel WC\'sinin bulunmaması', '1-Biyolojik etkenlerle temas              2-Çapraz kontaminasyon', '1-Çalışanlar', NULL, 1, 0, 6, 6, 3, 108, 'C', '1- Çalışanların kullanımına uygun tuvalet/lavabo imkânı, çalışan sayısı ve işyeri koşulları dikkate alınarak yeterli kapasitede sağlanmalıdır.\n2- Hasta/ziyaretçi kullanımının yoğun olduğu ortak WC\'lerde temizlik ve dezenfeksiyon sıklığı risk esaslı artırılmalıdır.\n3- El yıkama noktalarında su, sıvı sabun ve tek kullanımlık el kurutma imkânı sürekli bulundurulmalıdır.\n4- Temizlik planı ve kontrol çizelgesi oluşturularak uygulama kayıt altına alınmalıdır.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 2, 3, 3, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 22, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Sabitlenmemiş dolap ve raflar', '1-Devrilme, düşme ya da çarpma sonucunda vücut bölümlerinin sıkışması, yaralanması', '1- Çalışanlar                                \n2- Hastalar ve hasta yakınları\n3- Diğer ilgli kişiler', '1-ASM\'de bir çok alanda dolaplar sabitlenmemiştir.', 1, 0, 3, 2, 15, 90, 'C', '1-Sabitlenmemiş dolap ve raflar duvara veya zemine (L aparatı, dübel, çelik bağlantı elemanları ile) en az iki noktadan sabitlenmelidir.\n2-Dolapların üzerine düşme, devrilme riski olan malzemeler  istiflenmemelidir.\n3-Ağır malzeme ve ekipmanlar yüksek raflara istiflenmemelidir.   \n4- Tekerlekli dolap varsa fren mekanizması bulunmalı, fren mekanizması çalışır durumda olmalı ve dolaplar sabit iken frenleri kapalı olmalıdır.                                                                                          5- Raflara maksimum yük kapasitesi etiketi konulmalıdır.\n6- Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 1, 15, 7.5, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 23, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Tehlike yangın algılama ve ihbar sisteminin çalışmaması', '1-Yangın                  2-Ölüm', '1- Çalışanlar                                2- Stajerler\n3- Hastalar ve hasta yakınları\n4- Diğer ilgli kişiler', '1-Yangın algılama sistemi vardır.', 1, 0, 3, 2, 15, 90, 'C', '1- Yangın algılama ve alarm sistemi sürekli çalışır durumda tutulmalı; arıza/izolasyon durumları gecikmeden giderilmelidir.\n2- Dedektör, siren, flaşör ve ihbar butonlarının önü kapatılmamalı; cihazlar boyanmamalı veya kapatılmamalıdır.\n3- Sistem, üretici talimatı, onaylı proje ve ilgili standartlara göre yetkili teknik personelce test/bakım görmeli; kayıtları saklanmalıdır.\n4- Yangın panelinin enerji beslemesi ve kablolama yangın senaryosu/onaylı projeye uygun olmalı; belirli bir kablo sınıfı yalnız proje ve teknik gereklilik varsa uygulanmalıdır.\n5- Alarmın duyulabilirliği/görülebilirliği ve ilgili senaryolar testlerle doğrulanmalıdır.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 1, 15, 7.5, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 24, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Acil durum ekiplerinin (yangın, ilkyardım, kurtarma, koruma) belirlenmemiş olması', '1-Acil durum anında müdahalede güçlük olması', '1-Çalışanlar', NULL, 1, 0, 3, 2, 15, 90, 'C', '1- Acil durum destek elemanları işyerinin tehlike sınıfı ve çalışan sayısı dikkate alınarak mevzuata uygun sayıda belirlenmeli ve yazılı görevlendirilmelidir.\n2- Yangınla mücadele, arama-kurtarma-tahliye ve ilkyardım görevleri için gerekli eğitim/yeterlilikler sağlanmalıdır.\n3- Görev listeleri güncel tutulmalı; vardiya, izin ve personel değişikliklerinde yeterli sayıda görevli bulunması güvence altına alınmalıdır.\n4- Acil durum planı personele duyurulmalı ve tatbikatlar mevzuatta öngörülen periyotlarda yapılarak kayıt altına alınmalıdır.\n5- Ekiplerin kullanacağı acil durum ekipmanları erişilebilir ve çalışır durumda tutulmalıdır.', 'İŞVEREN V.               \n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 1, 15, 7.5, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 25, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Depolama alanının yetersiz olması', '1-Takılma-düşme, denge kaybı sonucunda vücut bölümlerinin yaralanması                     2-Ortam dağınıklığı                3-Enfeksiyon ve çapraz bulaş riski', '1-Çalışanlar      2-Hasta ve hasta yakınları 3-Diğer ilgili kişiler', NULL, 1, 0, 3, 3, 7, 63, 'D', '1- Yeterli büyüklükte ayrı bir depolama alanı oluşturulmalıdır.\n2- Alana uygun kapaklı depolama dolabı temin edilmelidir.                                                                               3- Tıbbi malzemeler için temiz/kirli ayrımı yapılmış raf sistemi kurulmalıdır. \n4- Sadece yetkili kişiler tarafından depolama dolaplarına erişim sağlanmalıdır.  \n5- Yerde malzeme bulundurulması engellenmelidir.\n6- Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.               \n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 26, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Çalışanların temel iş güvenliği eğitimlerine katılmamaları                                2- Çalışanların sağlık taramalarının sürelerinin dolması', '1-İş kazası ve meslek hastalıklarının artması', '1- Çalışanlar', '1- Eğitim planı ve eğitim tarihleri çalışanlar ile paylaşılmıştır.', 1, 0, 3, 3, 7, 63, 'D', '1- İşe başlamadan önce çalışanlara işe ve işyerine özgü İSG eğitimi verilmelidir.\n2- Temel İSG eğitimlerinin süresi ve yenilenme periyodu işyerinin tehlike sınıfına göre güncel mevzuat esas alınarak planlanmalıdır; tüm çalışanlar için otomatik olarak \'16 saat/yılda bir\' kabul edilmemelidir.\n3- Sağlık gözetimi ve periyodik muayene aralıkları işyeri hekiminin risk değerlendirmesi, çalışan özelliği ve mevzuat hükümlerine göre belirlenmelidir; tüm tetkikler için sabit \'yılda bir\' şartı uygulanmamalıdır.\n4- İşe giriş/periyodik sağlık muayenesi tamamlanmadan ve gerekli eğitimler verilmeden çalışan riskli işe başlatılmamalıdır.\n5- Birime özgü oryantasyon/işbaşı eğitimi verilerek kayıt altına alınmalı; eğitim etkinliği değerlendirilmelidir.', 'İŞVEREN V.', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 27, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Su sebillerinin bakım ve temizliğinin yapılmaması.                                           2- Su sebillerinin su sızdırması', '1-Enfeksiyon, bulaşıcı hastalıklara yakalanma', '1-Çalışanlar', '1- Enfeksiyon riskleri hakkında eğitim verilmiştir.', 1, 0, 3, 3, 7, 63, 'D', '1- Su sebillerinin bakımları  düzenli aralıklarla yaptırılmalıdır.                                                                                   2- Su sebillerinin temizliği düzenli aralıklarla yaptırılmalıdır.                                                                                                                                                                          3- Su sızıntılarından kaynaklı riskleri önlemek için su sebillerinin altlarına taşma havuzu konulmalıdır.                                                                                                                                                                                                                                      4- Su sebillerinin bulunduğu zemin davamlı kuru tutulmalıdır ve kaygan zemin levhası konulmalıdır.\n• Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 28, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Aydınlatma yetersizliği, bozulması, titremesi', '1- Görme bozukluklarının oluşması ve ilerlemesi, ş kazalarında artış', '1- Çalışanlar', '1- Suni aydınlatma sistemleri yeterli sayıdadır.', 1, 0, 3, 3, 7, 63, 'D', '1- Aydınlatma düzeyi yapılan işin niteliğine göre ölçülmeli ve ilgili standart/mevzuat değerlerine uygun hale getirilmelidir; tüm alanlar için tek bir \'300 lux\' değeri kullanılmamalıdır.\n2- Arızalı, titreyen veya yetersiz aydınlatma elemanları gecikmeden değiştirilmelidir.\n3- Parlama, yansıma ve gölgelenme azaltılmalı; muayene/işlem alanlarında göreve uygun lokal aydınlatma sağlanmalıdır.\n4- Acil kaçış yollarındaki acil aydınlatma sistemi çalışır durumda tutulmalı ve fonksiyon testleri kayıt altına alınmalıdır.\n5- Görme ile ilgili sağlık gözetimi işyeri hekiminin değerlendirmesine göre yürütülmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', '1- Teknik birim tarafından sorunlar çözümlenmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 29, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Elle taşıma işlerinin yük kaldırma prensiplerine uygun yapılmaması', '1-Kas iskelet sistemi hastalıkları oluşması,                                    2-Malzeme düşmesi, devrilmesi sonucu yaralanma', '1- Çalışanlar', '1- Çalışanlara elle taşıma işleri hakkında eğitim verilmektedir.', 1, 0, 3, 3, 7, 63, 'D', '1- Elle taşıma mümkün olduğunca mekanik yardımcılarla azaltılmalı; yükün ağırlığı, boyutu, kavrama imkânı, taşıma mesafesi, çalışma ortamı ve çalışanın bireysel özellikleri birlikte değerlendirilmelidir.\n2- Sabit \'erkek 25 kg/kadın 15 kg\' sınırı tek başına güvenli kabul kriteri olarak kullanılmamalı; uygun ekipman veya ekip çalışması risk değerlendirmesine göre belirlenmelidir.\n3- Çalışanlara doğru kaldırma, taşıma, itme-çekme ve yük bırakma teknikleri konusunda uygulamalı eğitim verilmelidir.\n4- Görüşü kapatan, dengesiz veya kavranması güç yükler tek kişiyle taşınmamalıdır.\n5- Kaldırma/indirme sırasında el ve ayakların sıkışma hattında kalması önlenmeli; uygun tutamak, taşıma arabası ve ara destekler kullanılmalıdır.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 30, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Ayna ve cam yüzeylerin olması', '1-Kırılma,çarpma sonucu iş kazalarının olması', '1- Çalışanlar', NULL, 1, 0, 3, 6, 3, 54, 'D', '1-Tüm cam ve aynalar temperli (ısıya dayanıklı) veya kırıldığında dağılmayan/kesici olmayan özellikte olmalıdır.                                                       2-Tüm kenarlara koruyucu fitil / çerçeve uygulanmalıdır.                                                         3-Duvara monte aynalar askı sistemleri ile duvara sabitlenmelidir.                                                         3- Şeffaf cam yüzeylere uyarı bantları yapıştırılmalıdır.                                                            4- Çatlak, çizik camlar varsa derhal kullanım dışı bırakılarak yenisi ile değiştirilmelidir.                                    5- Riskli alanlarda (bebek odası vb.) cam kullanımı en aza indirilmelidir.\n• Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 1, 3, 1.5, 'E', 'acik', '1- Alanda kırılmaz ayna paneller mevcuttur.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 31, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Göz duşu bulunmaması', '1-Göze sıvı sıçramasi sonucu irritasyon, göz hasarları', '1-Çalışanlar', '1-Alanda göz duşu bulunmamaktadır.', 1, 0, 3, 6, 3, 54, 'D', '1-Kan ve vücut sıvılarının göze sıçraması riskine karşın alanda göz duşu bulunmalıdır.                             2-Göz duşları tek kullanımlık olmalı, kullanıldıktan sonra yenisi tekrar konulmalıdır.                    \n3- Gözduşu kullanma talimatı asılmalıdır.\n4- Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.\n\nBİRİM SORUMLULARI   \n\nÇALIŞANLAR', 'SÜREKLİ KONTROL', 0.5, 2, 3, 3, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 32, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Kaygan zemin oluşması                                                                  2- Bozuk zemin yüzeyi', '1-Düşme, denge kaybı sonucunda vücut bölümlerinin yaralanması', '1- Çalışanlar                                \n2- Hastalar ve hasta yakınları\n3- Diğer ilgli kişiler', '1- Temizlik işlerinde kaygan zemin levhaları konulmaktadır.', 1, 0, 1, 6, 7, 42, 'D', '1- Bozulan zeminin tamir ve tadilatı yapılmalıdır.\n2- Temizlik işlemi sırasında zemin kurulanmalı temizlik esnasında uyarı tabelaları konulmalıdır.                                                                                                     3- Kaymaya sebep olacak maddelerinin zeminde birikmesi önlenmeli, hemen temizlenmelidir.\n4-  Çalışanlar kaymaz tabanlı ayakkabı giymelidir.\n5- Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.              \n\nTEMİZLİK HİZMETLERİ\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', '1- Temizlik çalışanları alana müdahale ederek gerekli uyarı levhalarını yerleştirmektedir.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 33, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Merkezi havalandırma sisteminin olmaması', '1-Zararlı partiküllerin solunması sonucunda meslek hastalıklarının oluşması', '1- Çalışanlar', NULL, 1, 0, 1, 6, 7, 42, 'D', '1-Uygun olan alanlarda lokal mekanik havalandırma sistemleri (klima, vb.) kurulmalıdır.                                                      2- Hava değişim sayısı ölçümleri yaptırılmalıdır.\n3- Otomatik sıcaklık, nem izleme sistemleri bulunmalı, çalışır durumda olmalıdır\n• Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 2, 7, 7, 'E', 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 34, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Elektrik topraklama kaçak akım ve izole sisteminin çalışmaması', '1-Elektrik çarpılması                  2-Ölüm', '1- Çalışanlar                                2- Hastalar ve hasta yakınları\n3- Diğer ilgli kişiler', '1- Kaçak akımlar ve topraklama mevcuttur.', 1, 0, 3, 2, 7, 42, 'D', '1-Kuvvetli akım pano önlerine izole paspas konulmalıdır.                                                                                               2-Topraklama kaçak akım yıllık testlerinin yapılarak raporlanmasının yapılmalıdır.\n• Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER', 'SÜREKLİ KONTROL', 0.5, 1, 7, 3.5, 'E', 'acik', '1- Periyodik bakımları düzenli olarak yapılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 35, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Tüm alanda bulunan acil durum iplerinin yere kadar uzanmaması', '1-Erişim güçlüğü                  2- Acil durumda müdahale çağrısının gecikmesi', '1-Çalışanlar       2-Hasta ve hasta yakınları', '1-Acil durum ipleri mevcuttur.', 1, 0, 1, 1, 40, 40, 'D', '1-Acil durum ipleri zemine 10–15 cm mesafeye kadar uzatılmalıdır.                                                         2-İplerin kopmasını önlemek için dayanıklı ve esnek malzeme kullanılmalı ve ip uçlarına kolay kavranabilir tutamak/topuz eklenmelidir.                                    3- Çağrı sisteminin periyodik olarak kontrol ve testleri yapılmalıdır.\n• Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', '46660', 0.5, 1, 40, 20, 'D', 'acik', '1- Teknik birim tarafından alan düzenlemesi yapılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 36, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Duvar Tipi Otoskop Oftalmaskop İstasyonu kablosunun uzun ve dağınık olması', '1-Takılma-düşme, denge kaybı sonucunda vücut bölümlerinin yaralanması                     2-Ekipman hasarı                3-Yangın yükü', '1- Çalışanlar                               \n2- Hastalar ve hasta yakınları\n3- Diğer ilgli kişiler', '1-Her muayene odasında otoskop oftalmaskop seti mevcuttur.', 1, 0, 3, 3, 3, 27, 'D', '1-Kablo dağınıklığı kablo kanalı veya spiral düzenleyicilerle toplatılmalıdır.                                    2-Fazal kablo sabitlenmeli, yerle temas kesilmelidir.                                                                      3- Yanma ve yangını kolaylaştırıcı malzemelerle arasına güvenli mesafe bırakılmalıdır.\n• Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 1, 3, 1.5, 'E', 'acik', '1- Cihazların bakım ve kalibrasyonları yapılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 37, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1- Fotokopi makinesi, kağıt öğütücü, yazıcı gibi cihazların hareketli ve sıcak parçalarına temas', '1- El veya parmak yaralanmaları/ yanıkları', '1-Çalışanlar', '1- Makine güvenlik kapakları genellikle kapalı durumdadır.            2- Arıza durumunda cihaz bakımları yapılmaktadır.', 1, 0, 3, 3, 3, 27, 'D', '1- Cihazlar çalışırken kapağı açılmamalıdır.\n2- Cihazlar çalışırken hareketli ve sıcak kısımlarına el ve kollar yaklaştırılmamalıdır.                                                                                                                                      3- Güvenlik sensörleri devre dışı bırakılmamalıdır.                                                                                                                                                              4- Güvenlik tertibatı olmayan ya da bozuk olan cihazlar kullanılmamalıdır.\n• Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 1, 3, 1.5, 'E', 'acik', '1- Cihazların bakım ve kalibrasyonları yapılmaktadır.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 38, 'BÖLÜM 1: DEMİRTAŞ A.S.M', '1-Bebek bakım odasında keskin ve sivri yüzeylerin bulunması', '1-Düşme- çarpma sonucu yaralanma                         2- Enfeksiyon', '1- Çalışanlar                                2- Hastalar ve hasta yakınları\n3- Diğer ilgli kişiler', NULL, 1, 0, 3, 1, 7, 21, 'D', '1-Bebek bakım alanında kullanılan ekipmanların yuvarlatılmış kenarlı seçilme                                           2-Tüm keskin/sivri köşelere köşe koruyucu (kauçuk/silikon) takılmalıdır.                                        3-Hasarlı/kırık mobilyalar onarılmalı veya değiştirilmelidir.                                                             4-Oda içerisinde amacı dışında malzeme bulundurulmamalıdır.\n• Uygulanan tedbirlerin sürekliliği birim sorumlusu tarafından saha kontrolleriyle izlenmeli; uygunsuzluklar kayıt altına alınarak giderilmelidir.', 'İŞVEREN V.              \n\nTEKNİK HİZMETLER\n\nBİRİM SORUMLULARI', 'SÜREKLİ KONTROL', 0.5, 1, 7, 3.5, 'E', 'acik', '1- Keskin/sivri köşelere köşe koruyucu mevcuttur.', NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_degerlendirmeleri` (`firma_id`, `igu_id`, `yontem`, `cikti_sablonu`, `sablon_verisi`, `belge_no`, `revizyon_no`, `rapor_tarihi`, `gecerlilik_tarihi`, `firma_unvan`, `firma_sgk_sicil_no`, `firma_nace`, `tehlike_sinifi`, `firma_adres`, `proje_adi`, `durum`, `created_at`, `updated_at`)
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 1, 'BÖLÜM 1: BİYOMEDİKAL', '1-Elektrikli cihazların onarım esnasında güvene alınmaması', '1-Elektrik çarpması                                           2- Kısa devre/Yangın', '1-Biyomedikal çalışanları       2-Stajyer', '1-Kaçak akım röleleri mevcuttur.', 1, 0, 6, 3, 15, 270, 'B', '1-Biyomedikal atölyesinde \"Kilitleme ve Etiketleme\" sistemi zorunlu hale getirilmelidir. Şalter kapatıldıktan sonra üzerine \"Bakım Var\" etiketi asılmalı ve fiziksel olarak kilitlenmelidir.                 \n2-Çalışma masalarında yalıtkan paspaslar kullanılmalı ve personelin dielektrik (yalıtkan) eldiven kullanmalıdır.                                      \n 3-Elektrik panosundaki kaçak akım rölelerinin (30mA) işlevselliği  test edilmelidir.', '1-Biyomedikal çalışanları      2-Teknik Birim', NULL, NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 2, 'BÖLÜM 1: BİYOMEDİKAL', '1-Çalışma tezgahının yetersiz ve dağınık olması', '1-Çarpma yaralanma         2-Ergonomi', '1-Biyomedikal çalışanları       2-Stajyer', NULL, 1, 0, 3, 3, 15, 135, 'C', '1-Tezgah alanı büyütülmelidir.                          \n 2-Tezgah üzerinde her zaman kullanılmayan malzeme ve araç gereçler kalabalığı berteraf edecek şekilde farklı bir alanda depolanmalıdır.                                                      3-El aletleri için ayrı çekmece, pano, askı sistemi veya düzenleyici kutular kullanılmalıdır.                                                         4-Tezgâh yüzeyi düzenli olarak temizlenmeli, toz, yağ, kimyasal kalıntı veya metal parça birikimi önlenmelidir.                               \n 5-Birim sorumlusu tarafından periyodik saha kontrolleri yapılmalı, uygunsuzluklar kayıt altına alınarak giderilmelidir.', '1-Biyomedikal çalışanları      2-Teknik Birim', NULL, NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 3, 'BÖLÜM 1: BİYOMEDİKAL', '1-Cihazların kullanım talimatlarının bulunmaması', '1-Elektrik çarpması                 2-Yaralanma                           3-Yanlış ölçüm, hatalı bakım-onarım veya yanlış test sonucu oluşması', '1-Biyomedikal çalışanları       2-Stajyer', NULL, 1, 0, 3, 3, 15, 135, 'C', '1-Kullanım amacı bilinmeyen, etiketi olmayan, arızalı veya güvenli kullanımı doğrulanamayan cihazlar çalışma alanından kaldırılmalıdır.                                                         2-Her cihazın üzerine veya yakınına kısa, anlaşılır ve görünür cihaz kullanım talimatı bulundurulmalıdır.                                                                      3-Elektrikli cihazlarda topraklama, kablo, fiş, priz ve kaçak akım rölesi kontrolleri yapılmalıdır.                                                     4-Çalışanlara, bilmedikleri veya eğitimini almadıkları cihazları kullanmamaları gerektiği açıkça bildirilmelidir.                                                  5-Çalışanlara cihazların güvenli kullanımı, acil durdurma, elektrik güvenliği ve arıza bildirim süreçleri hakkında eğitim verilmelidir.', '1-Biyomedikal çalışanları', NULL, NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 4, 'BÖLÜM 1: BİYOMEDİKAL', '1-Alanda KKD kullanılmaması', '1-Yaralanma               2-Elektrik çarpması', '1-Biyomedikal çalışanları       2-Stajyer', '1-Çalışma alanında kkd mevcuttur.', 1, 0, 6, 3, 7, 126, 'C', '1-KKD’ler CE belgeli ve ilgili standartlara uygun olmalı, eksik olan kkd\'ler temin edilmelidir.\n2- Çalışanların Toz maskesi / partikül filtreli maskeTS EN 149 standardında,göz koruyucuları TS 5560 EN 166 / EN 166 standardına uygun ve tam kapalı tip, dielektrik (yalıtkan) eldiven TS EN 60903, TS EN IEC 61340 serisi standartlarında Antistatik ESD (Elektrostatik Deşarj Önleyici Ayakkabı) ayakkabı olmalıdır.                                                                                                                                                                                                 3- Bütün kişisel koruyucular çalışanlara zimmetlenmelidir.                                                                       4- Kişisel koruyucu donanımlar çalışanlar tarafından eksiksiz kullanılmalıdır.', '1-Biyomedikal çalışanları', NULL, NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 5, 'BÖLÜM 1: BİYOMEDİKAL', '1-Uyarı levhalarının bulunmaması', '1-Elektrik çarpması             2-Yangın', '1-Biyomedikal çalışanları       2-Stajyer', '1-Çalışanların gerekli eğitimleri mevcuttur.', 1, 0, 3, 1, 40, 120, 'C', '1-Uyarı levhaları görünür, okunaklı, uygun büyüklükte ve çalışma ortamına dayanıklı malzemeden olmalıdır.', 'Teknik Birim', NULL, NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 6, 'BÖLÜM 1: BİYOMEDİKAL', '1- Biyomedikal atölyesinde  uzatma kabloları kullanılması', '1-Elektrik çarpması           2- Düşme                                 3- Kısa devre/Yangın', '1-Biyomedikal çalışanları       2-Stajyer', '1-Talep açıldığında elektrik kablolarının spiral içinde düzenleme işlemleri yapılmaktadır.', 1, 0, 3, 2, 15, 90, 'C', '1-Biyomedikal cihazların bulunduğu tezgâh ve çalışma noktaları, sabit prizlere yakın olacak şekilde yeniden düzenlenmelidir.                                   \n 2-Standart dışı, hasarlı, ek yapılmış, topraklamasız veya kapasitesi belirsiz uzatma kabloları kullanım dışı bırakılmalıdır.                                                      \n 3-Kullanılması zorunlu olan uzatma kabloları; topraklı, CE belgeli, sağlam, uygun kesitte ve kullanılacak cihaz yüküne uygun kapasitede olmalıdır.                                              \n 4-Kablo güzergâhları yürüyüş yollarından geçirilmemeli; gerekiyorsa kablo kanalı, kablo rampası veya masa altı kablo taşıyıcı sistem kullanılmalıdır.                                                      5-Çalışanlar hasarlı, ısınan, kıvılcım çıkaran veya gevşek bağlantılı uzatma kablolarını kullanmamalıdır.                                                      6-Islak elle fiş, priz veya uzatma kablosuna dokunulmamalıdır.', '1-Biyomedikal çalışanları      2-Teknik Birim', NULL, NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 7, 'BÖLÜM 1: BİYOMEDİKAL', '1-Rafların yotasız olması', '1-Çalışanın üzerine raf veya ürün devrilmesi', '1-Biyomedikal çalışanları       2-Stajyer', '1-Talep açıldığında yotalama işlemleri yapılmaktadır.', 1, 0, 3, 1, 15, 45, 'D', '1- Dolap ve raflar en az iki noktadan duvara sabitlenmelidir.                                                                       2- Dolapların üzerine devrilebilecek dosya vb. malzemeler istiflenmemelidir.                                                                                                                                         3- Ağır malzemeler alt raflara yerleştirilmelidir.                                                                                                                                                           4- Sabitlenemeyen dolap ve raflar kapılardan uzak, çalışanların üzerine düşmeyecek şekilde konumlandırılmalıdır.', '1-Biyomedikal çalışanları      2-Teknik Birim', NULL, NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 8, 'BÖLÜM 1: BİYOMEDİKAL', '1-Aydınlatmamın arızalı/yetersiz olması', '1-Görme bozukluğu         2-İş kazası geçirme            3-Yangın', '1-Biyomedikal çalışanları       2-Stajyer', '1-Aydınlatma ölçümleri 2 yılda bir yapılmaktadır.     2-Duman algılama ve Sprink sistemi mevcuttur.', 1, 0, 1, 6, 7, 42, 'D', '1- Aydınlatma ölçümü yapılmalı, ofislerde aydınlatma lüks seviyeleri (500 lx) şiddeteinde olmalıdır.                                                                                                                                                                              2-Aydınlatma sistemleri sağlam yapıda olmalı, bozulan, yanmayan titreyen aydınlatmalar değiştirilmelidir.', '1-Biyomedikal çalışanları      2-Teknik Birim', NULL, NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
INSERT INTO `risk_maddeleri` (`risk_degerlendirmesi_id`, `sira`, `bolum`, `tehlike`, `risk`, `etki_alani`, `mevcut_onlem`, `etkilenen_calisan`, `etkilenen_diger`, `olasilik`, `frekans`, `siddet`, `puan`, `duzey`, `oneri`, `sorumlu`, `termin`, `son_olasilik`, `son_frekans`, `son_siddet`, `son_puan`, `son_duzey`, `durum`, `aciklama`, `created_at`, `updated_at`) SELECT @rd, 9, 'BÖLÜM 1: BİYOMEDİKAL', '1-Dolapların yüksek olması                           2-Malzeme istifinin düzensiz yapılması', '1-Yüksekten düşme                2-Malzemenin çalışanın üstüne düşmesi', '1-Biyomedikal çalışanları       2-Stajyer', '1-Dolaplarda yotalama mevcuttur.', 1, 0, 3, 2, 7, 42, 'D', '1-Sık kullanılan malzemeler omuz ve bel hizasında, kolay ulaşılabilir raflara yerleştirilmelidir.                                                          2-Yüksek raflara erişim gerekiyorsa sandalye veya tabure yerine merdiven kullanılmalıdır.                                       3-Dolap kapakları sağlam, düzgün kapanabilir ve güvenli olmalıdır.                                           \n4-Dolap içeriği etiketlenmeli, malzemelerin yeri standart hale getirilmelidir.', '1-Biyomedikal çalışanları      2-Teknik Birim', NULL, NULL, NULL, NULL, NULL, NULL, 'acik', NULL, NOW(), NOW() FROM (SELECT 1) d WHERE @yeni = 1 AND @rd IS NOT NULL;
