-- Bursa Şehir Hastanesi risk formu — MEHMET ÖZDEMİR hesabına AYRI KOPYA (30.10.2026) — phpMyAdmin'de mehse veritabanında çalıştırın.
-- 1) şema (3 sütun, koşullu)  2) hastane firması  3) 33 değerlendirme + 1002 madde (olduğu gibi).
-- Tekrar çalıştırılabilir: var olan sütun / firma / değerlendirme atlanır; mevcut maddelere dokunulmaz.
-- SIRA: ÖNCE bu SQL, SONRA `node deploy/deploy.mjs` (şablon dosyaları + kod).

SET NAMES utf8mb4;

SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `risk_degerlendirmeleri` ADD COLUMN `cikti_sablonu` varchar(30) NULL AFTER `yontem`', 'SELECT 1') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'risk_degerlendirmeleri' AND COLUMN_NAME = 'cikti_sablonu');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `risk_degerlendirmeleri` ADD COLUMN `sablon_verisi` longtext NULL AFTER `cikti_sablonu`', 'SELECT 1') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'risk_degerlendirmeleri' AND COLUMN_NAME = 'sablon_verisi');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `risk_maddeleri` ADD COLUMN `etki_alani` text NULL AFTER `risk`', 'SELECT 1') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'risk_maddeleri' AND COLUMN_NAME = 'etki_alani');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `firmalar` ADD COLUMN `risk_cikti_sablonu` varchar(30) NULL AFTER `tehlike_sinifi`', 'SELECT 1') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'firmalar' AND COLUMN_NAME = 'risk_cikti_sablonu');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- Hastane firması: varsa bulunur ve hastane şablonu işaretlenir, yoksa oluşturulur.
SELECT u.`id`, 'Bursa şehir hastanesi', '13012450', '86.10.05', 'cok_tehlikeli', 'hastane', 'Serkan Pehlivan', 'Doğanköy, 16110 Nilüfer/Bursa', 'Bursa', 'Nilüfer', 4320, 1, NOW(), NOW()
FROM `users` u WHERE u.`email` = 'mozdemir2816@gmail.com' AND NOT EXISTS (SELECT 1 FROM `firmalar` WHERE `unvan` LIKE '%Bursa%hastane%' AND `deleted_at` IS NULL AND `user_id` = u.`id`);
UPDATE `firmalar` SET `risk_cikti_sablonu` = 'hastane' WHERE `unvan` LIKE '%Bursa%hastane%' AND `deleted_at` IS NULL AND `user_id` = (SELECT `id` FROM `users` WHERE `email` = 'mozdemir2816@gmail.com');
SET @firma = (SELECT `id` FROM `firmalar` WHERE `unvan` LIKE '%Bursa%hastane%' AND `deleted_at` IS NULL AND `user_id` = (SELECT `id` FROM `users` WHERE `email` = 'mozdemir2816@gmail.com') ORDER BY `id` LIMIT 1);

-- HASTANE GENELİ
SET @rd = (SELECT `id` FROM `risk_degerlendirmeleri` WHERE `firma_id` = @firma AND `cikti_sablonu` = 'hastane' AND `proje_adi` = 'HASTANE GENELİ' LIMIT 1);
SET @yeni = IF(@rd IS NULL, 1, 0);
SELECT f.`id`, f.`igu_id`, 'fine_kinney', 'hastane', '{\"dosya\":\"1-hastane-geneli.xlsx\",\"sayfa\":\"HASTANE GENEL\\u0130\"}', 'RD-2026-H01', '00', '2025-12-08', '2027-12-08', f.`unvan`, f.`sgk_sicil_no`, TRIM(CONCAT(IFNULL(f.`nace_kodu`, ''), ' ', IFNULL(f.`nace_aciklama`, ''))), f.`tehlike_sinifi`, f.`adres`, 'HASTANE GENELİ', 'taslak', NOW(), NOW()
FROM `firmalar` f WHERE f.`id` = @firma AND @yeni = 1;
SET @rd = (SELECT `id` FROM `risk_degerlendirmeleri` WHERE `firma_id` = @firma AND `cikti_sablonu` = 'hastane' AND `proje_adi` = 'HASTANE GENELİ' LIMIT 1);

